--
-- Name: current_profile_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.current_profile_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select id from core_user_profiles where auth_user_id = auth.uid() limit 1;
$$;


--
-- Name: is_internal_user(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.is_internal_user() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select exists (
    select 1
    from core_memberships m
    join core_organizations o on o.id = m.organization_id
    join core_user_profiles u on u.id = m.user_id
    where u.auth_user_id = auth.uid()
      and u.status = 'active'
      and m.status = 'active'
      and o.organization_type = 'angelcare_internal'
      and o.status in ('active','trial')
  );
$$;


--
-- Name: normalize_code(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.normalize_code(input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select lower(regexp_replace(coalesce(input,''), '[^a-zA-Z0-9]+', '_', 'g'));
$$;


--
-- Name: org_has_entitlement(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.org_has_entitlement(org_id uuid, entitlement_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select exists (
    select 1
    from ent_organization_entitlements e
    join ent_definitions d on d.id = e.entitlement_definition_id
    where e.organization_id = org_id
      and d.code = entitlement_code
      and e.status = 'active'
      and (e.valid_from is null or e.valid_from <= now())
      and (e.valid_until is null or e.valid_until >= now())
  );
$$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: user_can_access_org(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.user_can_access_org(org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select app.is_internal_user()
    or org_id in (select app.user_organization_ids());
$$;


--
-- Name: user_can_access_session(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.user_can_access_session(session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select app.is_internal_user()
  or exists (
    select 1 from trn_sessions s
    where s.id = session_id and s.organization_id in (select app.user_organization_ids())
  )
  or exists (
    select 1
    from trn_session_trainers st
    join trn_trainers t on t.id = st.trainer_id
    join core_user_profiles u on u.id = t.user_id
    where st.session_id = session_id
      and u.auth_user_id = auth.uid()
      and st.status = 'assigned'
  );
$$;


--
-- Name: user_has_permission(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.user_has_permission(permission_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select app.is_internal_user() and exists (
    select 1
    from core_user_profiles u
    join authz_user_role_assignments ura on ura.user_id = u.id and ura.status = 'active'
    join authz_roles r on r.id = ura.role_id and r.status = 'active'
    join authz_role_permissions rp on rp.role_id = r.id
    join authz_permissions p on p.id = rp.permission_id
    where u.auth_user_id = auth.uid()
      and p.code = permission_code
  )
  or exists (
    select 1
    from core_user_profiles u
    join authz_user_role_assignments ura on ura.user_id = u.id and ura.status = 'active'
    join authz_roles r on r.id = ura.role_id and r.status = 'active'
    join authz_role_permissions rp on rp.role_id = r.id
    join authz_permissions p on p.id = rp.permission_id
    where u.auth_user_id = auth.uid()
      and p.code = permission_code
  );
$$;


--
-- Name: user_organization_ids(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.user_organization_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select distinct m.organization_id
  from core_memberships m
  join core_user_profiles u on u.id = m.user_id
  where u.auth_user_id = auth.uid()
    and m.status = 'active'
    and u.status = 'active';
$$;


--
-- Name: user_site_ids(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.user_site_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app', 'auth'
    AS $$
  select distinct m.site_id
  from core_memberships m
  join core_user_profiles u on u.id = m.user_id
  where u.auth_user_id = auth.uid()
    and m.status = 'active'
    and m.site_id is not null
    and u.status = 'active';
$$;


