--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
begin
    if not exists (
        select 1
        from pg_event_trigger_ddl_commands() ev
        join pg_catalog.pg_extension e on ev.objid = e.oid
        where e.extname = 'pg_graphql'
    ) then
        return;
    end if;

    drop function if exists graphql_public.graphql;
    create or replace function graphql_public.graphql(
        "operationName" text default null,
        query text default null,
        variables jsonb default null,
        extensions jsonb default null
    )
        returns jsonb
        language sql
    as $$
        select graphql.resolve(
            query := query,
            variables := coalesce(variables, '{}'),
            "operationName" := "operationName",
            extensions := extensions
        );
    $$;

    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,
    -- which in turn triggers set_graphql_placeholder to reinstall the "not enabled" stub.
    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);

    grant usage on schema graphql to postgres, anon, authenticated, service_role;
    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;
    grant usage on schema graphql to postgres with grant option;
    grant usage on schema graphql_public to postgres with grant option;
end;
$_$;


--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: guard_published_plan_mutation(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.guard_published_plan_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
 if old.status='published' and (
   new.scenario_id is distinct from old.scenario_id or
   new.release_ids is distinct from old.release_ids or
   new.collection_ids is distinct from old.collection_ids or
   new.collection_version_ids is distinct from old.collection_version_ids or
   new.catalogue_snapshot is distinct from old.catalogue_snapshot or
   new.price_dh is distinct from old.price_dh or
   new.objectives is distinct from old.objectives
 ) then raise exception 'Published learning plans are immutable; create a new version.'; end if;
 return new;
end $$;


--
-- Name: guard_published_solution_mutation(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.guard_published_solution_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin

    if
        old.status = 'published'

        and (

            new.scenario_id
                is distinct from
            old.scenario_id

            or

            new.journey_scenario_id
                is distinct from
            old.journey_scenario_id

            or

            new.direct_collection_id
                is distinct from
            old.direct_collection_id

            or

            new.direct_collection_version_id
                is distinct from
            old.direct_collection_version_id

            or

            new.collection_ids
                is distinct from
            old.collection_ids

            or

            new.collection_version_ids
                is distinct from
            old.collection_version_ids

            or

            new.price_dh
                is distinct from
            old.price_dh

            or

            new.snapshot
                is distinct from
            old.snapshot
        )

    then

        raise exception
            'Published sellable composition is immutable; create a new version.';

    end if;


    if
        old.status = 'published'

        and not (

            coalesce(
                new.release_ids,
                '{}'::uuid[]
            )

            @>

            coalesce(
                old.release_ids,
                '{}'::uuid[]
            )

        )

    then

        raise exception
            'Published sellable release lineage may only append releases; it cannot remove historical release references.';

    end if;


    return new;

end
$$;


--
-- Name: guard_released_asset_mutation(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.guard_released_asset_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin

    if
        old.status in (
            'released',
            'commercially_active',
            'superseded',
            'retired',
            'archived'
        )

        and (

            new.command_id
                is distinct from
            old.command_id

            or

            new.source_package_id
                is distinct from
            old.source_package_id

            or

            new.deliverable_ids
                is distinct from
            old.deliverable_ids

            or

            new.collection_version
                is distinct from
            old.collection_version

            or

            new.source_type
                is distinct from
            old.source_type

            or

            new.source_id
                is distinct from
            old.source_id

            or

            new.source_snapshot
                is distinct from
            old.source_snapshot

            or

            new.collection_ids
                is distinct from
            old.collection_ids

            or

            new.collection_version_ids
                is distinct from
            old.collection_version_ids
        )

    then

        raise exception
            'Released product composition is immutable; create a new release version.';

    end if;


    return new;

end
$$;


--
-- Name: prevent_approved_intelligence_delete(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.prevent_approved_intelligence_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (tg_table_name = 'research_syntheses' and old.status = 'approved')
     or (tg_table_name = 'product_designs' and old.status in ('approved','ready_for_umz3')) then
    raise exception 'Approved research syntheses and Product Designs are immutable and cannot be deleted';
  end if;
  return old;
end;
$$;


--
-- Name: prevent_released_version_delete(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.prevent_released_version_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.status in ('approved','superseded') then
    raise exception 'Approved or superseded collection versions are immutable';
  end if;
  return old;
end;
$$;


--
-- Name: protect_closed_experience_record(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.protect_closed_experience_record() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
 if tg_table_name='cx_cases' and old.status in('closed','rejected') and (to_jsonb(old)-array['updated_at'])<>(to_jsonb(new)-array['updated_at']) then raise exception 'Closed CX case is immutable; reopen through a governed event.'; end if;
 if tg_table_name='refund_requests' and old.status in('completed','cancelled','rejected') and (to_jsonb(old)-array['updated_at'])<>(to_jsonb(new)-array['updated_at']) then raise exception 'Completed or rejected refund is immutable.'; end if;
 if tg_table_name='return_authorizations' and old.status='closed' and (to_jsonb(old)-array['updated_at'])<>(to_jsonb(new)-array['updated_at']) then raise exception 'Closed return authorization is immutable.'; end if;
 return new;
end $$;


--
-- Name: protect_issued_commercial_document(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.protect_issued_commercial_document() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare old_core jsonb; new_core jsonb;
begin
 if old.status not in ('issued','sent','accepted','partially_delivered','fully_delivered','partially_invoiced','fully_invoiced','partially_paid','paid','overdue','disputed','completed') then return new; end if;
 if tg_table_name='quotations' then
   old_core=to_jsonb(old)-array['status','customer_decision','customer_decision_at','updated_at']; new_core=to_jsonb(new)-array['status','customer_decision','customer_decision_at','updated_at'];
 elsif tg_table_name='delivery_notes' then
   old_core=to_jsonb(old)-array['status','delivered_at','invoicing_eligible','updated_at']; new_core=to_jsonb(new)-array['status','delivered_at','invoicing_eligible','updated_at'];
 elsif tg_table_name='invoices' then
   old_core=to_jsonb(old)-array['status','payment_status','paid_dh','outstanding_dh','dispute_reason','updated_at']; new_core=to_jsonb(new)-array['status','payment_status','paid_dh','outstanding_dh','dispute_reason','updated_at'];
 else
   old_core=to_jsonb(old)-array['status','updated_at']; new_core=to_jsonb(new)-array['status','updated_at'];
 end if;
 if old_core<>new_core then raise exception 'Issued commercial document is immutable; create a revision, replacement or credit note.'; end if;
 return new;
end $$;


--
-- Name: recount_quality_blockers(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.recount_quality_blockers() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ declare rid uuid; begin rid=coalesce(new.review_id,old.review_id); update flashcards_os.quality_reviews set blockers=(select count(*) from flashcards_os.quality_findings where review_id=rid and severity in('release_blocker','critical') and status not in('resolved','waived')), findings=(select coalesce(jsonb_agg(jsonb_build_object('id',id,'reviewId',review_id,'discipline',discipline,'severity',severity,'title',title,'detail',detail,'locator',locator,'expectedCorrection',expected_correction,'responsibleParty',responsible_party,'dueDate',due_date,'status',status,'resolution',resolution) order by created_at),'[]'::jsonb) from flashcards_os.quality_findings where review_id=rid) where id=rid; return coalesce(new,old); end $$;


--
-- Name: refresh_collection_structured_card_count(text); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.refresh_collection_structured_card_count(target_collection_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'flashcards_os', 'public'
    AS $$
declare result_count integer;
begin
  select count(*)::integer into result_count
  from flashcards_os.cards
  where collection_id = target_collection_id
    and tenant_key = 'angelcare-internal';

  update flashcards_os.collections
  set structured_card_count = result_count, updated_at = now()
  where id = target_collection_id
    and tenant_key = 'angelcare-internal';
  return result_count;
end;
$$;


