-- Name: touch_updated_at(); Type: FUNCTION; Schema: flashcards_os; Owner: -
--

CREATE FUNCTION flashcards_os.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ begin new.updated_at=now(); return new; end $$;


