                            )
                        )
                    );
                END IF;
            END;
        $$;


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


--
-- Name: ac360_activate_addon(uuid, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_activate_addon(p_org_id uuid, p_addon_key text, p_quantity numeric DEFAULT 1, p_billing_interval text DEFAULT 'monthly'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_sub public.ac360_subscriptions%rowtype;
  v_addon public.ac360_addons%rowtype;
  v_item public.ac360_subscription_items%rowtype;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  if p_addon_key is null then raise exception 'p_addon_key is required'; end if;

  select * into v_sub from public.ac360_subscriptions
  where org_id = p_org_id and status in ('trial','active','grace','past_due','restricted')
  order by case status when 'active' then 1 when 'trial' then 2 when 'grace' then 3 else 4 end, created_at desc
  limit 1;
  if v_sub.id is null then raise exception 'No active subscription found for organization %', p_org_id; end if;

  select * into v_addon from public.ac360_addons where addon_key = p_addon_key and status = 'active' limit 1;
  if v_addon.id is null then raise exception 'Unknown or inactive AC360 add-on: %', p_addon_key; end if;

  select * into v_item from public.ac360_subscription_items
  where org_id = p_org_id and subscription_id = v_sub.id and addon_key = p_addon_key and status in ('active','cancel_pending')
  order by created_at desc limit 1;

  if v_item.id is null then
    insert into public.ac360_subscription_items(subscription_id, org_id, item_type, item_key, label, addon_key, quantity, unit_price_mad, billing_interval, status, current_period_end, metadata_json)
    values (v_sub.id, p_org_id, 'addon', 'addon:' || p_addon_key, v_addon.label, p_addon_key, greatest(coalesce(p_quantity,1),1), v_addon.monthly_price_mad, p_billing_interval, 'active', v_sub.current_period_end, jsonb_build_object('activated_by','phase1b_runtime_bridge'))
    returning * into v_item;
  else
    update public.ac360_subscription_items
    set status = 'active', cancel_at_period_end = false, cancelled_at = null, quantity = greatest(coalesce(p_quantity, v_item.quantity),1), updated_at = now()
    where id = v_item.id returning * into v_item;
  end if;

  insert into public.ac360_recommendations(org_id, subscription_id, recommendation_key, status, priority, title, message, recommended_addon_key, trigger_json)
  values (p_org_id, v_sub.id, 'addon_activated_' || p_addon_key, 'accepted', 'medium', 'Add-on activated: ' || v_addon.label, 'Growth Menu module activated and governed by entitlements.', p_addon_key, jsonb_build_object('addon_key',p_addon_key))
  on conflict do nothing;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-29', 'addon.activated', 'addon.activate', 'subscription_item', v_item.id, 'success', 'notice', p_actor_app_user_id, null, jsonb_build_object('addon_key',p_addon_key,'price_mad',v_addon.monthly_price_mad));

  return jsonb_build_object('ok', true, 'item', to_jsonb(v_item), 'addon', to_jsonb(v_addon));
end;
$$;


--
-- Name: ac360_add_qa_result(uuid, uuid, text, text, text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_add_qa_result(p_run_id uuid, p_org_id uuid, p_check_key text, p_check_family text, p_severity text, p_status text, p_title text, p_detail text DEFAULT NULL::text, p_expected_value text DEFAULT NULL::text, p_actual_value text DEFAULT NULL::text, p_remediation text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.ac360_foundation_qa_results(run_id, org_id, check_key, check_family, severity, status, title, detail, expected_value, actual_value, remediation, evidence_json)
  values (
    p_run_id,
    p_org_id,
    p_check_key,
    coalesce(nullif(p_check_family,''),'foundation'),
    case when p_severity in ('info','low','medium','high','critical') then p_severity else 'medium' end,
    case when p_status in ('passed','warning','failed','skipped') then p_status else 'skipped' end,
    coalesce(nullif(p_title,''),p_check_key),
    p_detail,
    p_expected_value,
    p_actual_value,
    p_remediation,
    coalesce(p_evidence, '{}'::jsonb)
  )
  on conflict (run_id, check_key) do update set
    check_family = excluded.check_family,
    severity = excluded.severity,
    status = excluded.status,
    title = excluded.title,
    detail = excluded.detail,
    expected_value = excluded.expected_value,
    actual_value = excluded.actual_value,
    remediation = excluded.remediation,
    evidence_json = excluded.evidence_json;
end;
$$;


--
-- Name: ac360_admissions_default_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_admissions_default_code(p_prefix text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select upper(coalesce(nullif(p_prefix,''),'ADM')) || '-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,6);
$$;


--
-- Name: ac360_bootstrap_foundation_org(text, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_bootstrap_foundation_org(p_org_code text DEFAULT 'ANGELCARE360-INTERNAL'::text, p_display_name text DEFAULT 'AngelCare 360 Internal Command'::text, p_owner_app_user_id uuid DEFAULT NULL::uuid, p_owner_email text DEFAULT NULL::text, p_plan_key text DEFAULT 'command'::text, p_city text DEFAULT 'Temara'::text, p_status text DEFAULT 'active'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_org public.ac360_organizations%rowtype;
  v_campus public.ac360_campuses%rowtype;
  v_year public.ac360_academic_years%rowtype;
  v_plan record;
  v_sub public.ac360_subscriptions%rowtype;
  v_membership public.ac360_user_memberships%rowtype;
  v_role public.ac360_roles%rowtype;
  v_wallet public.ac360_credit_wallets%rowtype;
  v_allowance numeric := 0;
  v_period_end timestamptz := now() + interval '1 month';
  v_subscription_code text;
  v_normalized_org_code text;
begin
  v_normalized_org_code := upper(regexp_replace(coalesce(nullif(trim(p_org_code), ''), 'ANGELCARE360-INTERNAL'), '[^A-Za-z0-9_-]+', '-', 'g'));
  v_subscription_code := 'AC360-SUB-' || v_normalized_org_code;

  if coalesce(p_plan_key, '') not in ('start','pro','command') then
    raise exception 'Invalid AC360 plan key: %. Expected start, pro or command.', p_plan_key;
  end if;

  select p.id as plan_id, p.plan_key, p.commercial_name, p.public_monthly_price_mad, p.public_annual_price_mad,
         pv.id as plan_version_id, pv.version_code, pv.included_credits_json
    into v_plan
  from public.ac360_plans p
  join public.ac360_plan_versions pv on pv.plan_id = p.id and pv.status = 'active'
  where p.plan_key = p_plan_key
  order by pv.created_at desc
  limit 1;

  if v_plan.plan_id is null then
    raise exception 'AC360 plan/version seed missing for plan key: %', p_plan_key;
  end if;

  v_allowance := coalesce((v_plan.included_credits_json ->> 'automation_credit')::numeric, 0);

  insert into public.ac360_organizations(
    org_code, display_name, legal_name, org_type, lifecycle_status, status, country, city,
    billing_email, email, timezone, currency, preferred_language, owner_app_user_id, metadata_json, created_by
  ) values (
    v_normalized_org_code,
    coalesce(nullif(trim(p_display_name), ''), 'AngelCare 360 Internal Command'),
    coalesce(nullif(trim(p_display_name), ''), 'AngelCare 360 Internal Command'),
    'kindergarten_school',
    case when p_status = 'trial' then 'trial' else 'active' end,
    case when p_status in ('trial','active','grace','restricted','suspended','cancelled','archived') then p_status else 'active' end,
    'Morocco', coalesce(nullif(trim(p_city), ''), 'Temara'), p_owner_email, p_owner_email,
    'Africa/Casablanca', 'MAD', 'fr', p_owner_app_user_id,
    jsonb_build_object('source','ac360_phase1b_runtime_bridge','bootstrap','true'), p_owner_app_user_id
  )
  on conflict (org_code) do update set
    display_name = excluded.display_name,
    legal_name = coalesce(public.ac360_organizations.legal_name, excluded.legal_name),
    city = excluded.city,
    billing_email = coalesce(excluded.billing_email, public.ac360_organizations.billing_email),
    email = coalesce(excluded.email, public.ac360_organizations.email),
    owner_app_user_id = coalesce(excluded.owner_app_user_id, public.ac360_organizations.owner_app_user_id),
    status = case when public.ac360_organizations.status in ('archived','cancelled') then public.ac360_organizations.status else excluded.status end,
    lifecycle_status = case when public.ac360_organizations.lifecycle_status in ('archived','cancelled') then public.ac360_organizations.lifecycle_status else excluded.lifecycle_status end,
    metadata_json = public.ac360_organizations.metadata_json || excluded.metadata_json,
    updated_at = now()
  returning * into v_org;

  insert into public.ac360_campuses(org_id, campus_code, name, status, city, address, email, metadata_json)
  values (v_org.id, 'MAIN', 'Campus Principal', 'active', v_org.city, v_org.address, v_org.email, jsonb_build_object('bootstrap','phase1b'))
  on conflict (org_id, campus_code) do update set name = excluded.name, status = 'active', city = excluded.city, updated_at = now()
  returning * into v_campus;

  insert into public.ac360_legal_profiles(org_id, legal_name, trade_name, billing_address, billing_contact_email, currency, metadata_json)
  values (v_org.id, v_org.legal_name, v_org.display_name, v_org.address, v_org.billing_email, 'MAD', jsonb_build_object('bootstrap','phase1b'))
  on conflict (org_id) do update set
    legal_name = coalesce(public.ac360_legal_profiles.legal_name, excluded.legal_name),
    trade_name = coalesce(public.ac360_legal_profiles.trade_name, excluded.trade_name),
    billing_contact_email = coalesce(excluded.billing_contact_email, public.ac360_legal_profiles.billing_contact_email),
    updated_at = now();

  insert into public.ac360_academic_years(org_id, label, status, starts_on, ends_on, metadata_json)
  values (v_org.id, '2026-2027', 'active', date '2026-09-01', date '2027-08-31', jsonb_build_object('bootstrap','phase1b'))
  on conflict (org_id, label) do update set status = 'active', updated_at = now()
  returning * into v_year;

  update public.ac360_organizations set current_academic_year_id = v_year.id, updated_at = now() where id = v_org.id;

  if p_owner_app_user_id is not null or p_owner_email is not null then
    insert into public.ac360_user_memberships(
      org_id, campus_id, app_user_id, email, display_name, member_type, status, default_role_key, joined_at, metadata_json
    ) values (
      v_org.id, v_campus.id, p_owner_app_user_id, p_owner_email, coalesce(p_owner_email, 'AngelCare Owner'),
      'angelcare_internal', 'active', 'owner', now(), jsonb_build_object('bootstrap','phase1b')
    )
    on conflict (org_id, app_user_id) do update set
      campus_id = excluded.campus_id,
      email = coalesce(excluded.email, public.ac360_user_memberships.email),
      status = 'active',
      default_role_key = 'owner',
      joined_at = coalesce(public.ac360_user_memberships.joined_at, now()),
      updated_at = now()
    returning * into v_membership;
  end if;

  insert into public.ac360_roles(org_id, role_key, label, description, scope, is_template, is_system_locked, status, metadata_json)
  values (v_org.id, 'owner', 'Owner / Direction Générale', 'Full AC360 owner role created by runtime bridge.', 'organization', false, true, 'active', jsonb_build_object('bootstrap','phase1b'))
  on conflict (org_id, role_key) do update set label = excluded.label, is_system_locked = true, status = 'active', updated_at = now()
  returning * into v_role;

  insert into public.ac360_role_permissions(role_id, permission_key, effect)
  select v_role.id, p.permission_key, 'allow'
  from public.ac360_permissions p
  on conflict (role_id, permission_key) do update set effect = 'allow';

  if v_membership.id is not null then
    insert into public.ac360_user_role_assignments(membership_id, role_id, campus_id, assigned_by, status, metadata_json)
    values (v_membership.id, v_role.id, null, p_owner_app_user_id, 'active', jsonb_build_object('bootstrap','phase1b'))
    on conflict (membership_id, role_id, campus_id) do update set status = 'active', updated_at = now();
  end if;

  insert into public.ac360_subscriptions(
    org_id, plan_id, plan_version_id, subscription_code, status, billing_interval, currency,
    current_period_start, current_period_end, trial_ends_at, created_by, metadata_json
  ) values (
    v_org.id, v_plan.plan_id, v_plan.plan_version_id, v_subscription_code,
    case when p_status = 'trial' then 'trial' else 'active' end,
    'monthly', 'MAD', now(), v_period_end,
    case when p_status = 'trial' then now() + interval '30 days' else null end,
    p_owner_app_user_id,
    jsonb_build_object('source','phase1b_runtime_bridge','plan_key',p_plan_key)
  )
  on conflict (subscription_code) do update set
    plan_id = excluded.plan_id,
    plan_version_id = excluded.plan_version_id,
    status = case when public.ac360_subscriptions.status in ('cancelled','archived') then public.ac360_subscriptions.status else excluded.status end,
    current_period_end = coalesce(public.ac360_subscriptions.current_period_end, excluded.current_period_end),
    metadata_json = public.ac360_subscriptions.metadata_json || excluded.metadata_json,
    updated_at = now()
  returning * into v_sub;

  if not exists (select 1 from public.ac360_subscription_items where subscription_id = v_sub.id and item_type = 'base_plan' and status in ('active','cancel_pending')) then
    insert into public.ac360_subscription_items(subscription_id, org_id, item_type, item_key, label, quantity, unit_price_mad, billing_interval, status, current_period_end, metadata_json)
    values (v_sub.id, v_org.id, 'base_plan', 'plan:' || p_plan_key, v_plan.commercial_name, 1, v_plan.public_monthly_price_mad, 'monthly', 'active', v_sub.current_period_end, jsonb_build_object('plan_key',p_plan_key));
  end if;

  insert into public.ac360_credit_wallets(org_id, wallet_key, credit_type, status, balance, monthly_included_allowance, rollover_policy, metadata_json)
  values (v_org.id, 'main', 'angelcare_credits', 'active', v_allowance, v_allowance, 'no_rollover', jsonb_build_object('source','phase1b_runtime_bridge'))
  on conflict (org_id, wallet_key) do update set
    monthly_included_allowance = excluded.monthly_included_allowance,
    status = case when public.ac360_credit_wallets.status in ('archived','expired') then public.ac360_credit_wallets.status else 'active' end,
    updated_at = now()
  returning * into v_wallet;

  insert into public.ac360_credit_ledger(wallet_id, org_id, ledger_type, amount, balance_after, reason, idempotency_key, metadata_json)
  values (v_wallet.id, v_org.id, 'grant', v_allowance, v_wallet.balance, 'Initial included allowance from ' || p_plan_key || ' package', 'bootstrap:' || v_sub.id::text, jsonb_build_object('plan_key',p_plan_key))
  on conflict (wallet_id, idempotency_key) do nothing;

  perform public.ac360_record_audit(v_org.id, 'AC360-ENG-01', 'foundation.bootstrap.completed', 'org.bootstrap', 'organization', v_org.id, 'success', 'notice', p_owner_app_user_id, p_owner_email, jsonb_build_object('plan_key',p_plan_key,'subscription_id',v_sub.id,'wallet_id',v_wallet.id));

  return jsonb_build_object(
    'ok', true,
    'org', to_jsonb(v_org),
    'campus', to_jsonb(v_campus),
    'academicYear', to_jsonb(v_year),
    'subscription', to_jsonb(v_sub),
    'membership', case when v_membership.id is null then null else to_jsonb(v_membership) end,
    'wallet', to_jsonb(v_wallet),
    'planKey', p_plan_key
  );
end;
$$;


--
-- Name: ac360_bootstrap_school_ops_skeleton(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_bootstrap_school_ops_skeleton(p_org_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_org public.ac360_organizations%rowtype;
  v_campus public.ac360_campuses%rowtype;
  v_year public.ac360_academic_years%rowtype;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;

  select * into v_org from public.ac360_organizations where id = p_org_id limit 1;
  if v_org.id is null then raise exception 'AC360 organization not found'; end if;

  select * into v_campus from public.ac360_campuses where org_id = p_org_id and status = 'active' order by created_at asc limit 1;
  if v_campus.id is null then
    insert into public.ac360_campuses(org_id, campus_code, name, status, city, metadata_json)
    values (p_org_id, 'MAIN', coalesce(v_org.display_name,'AngelCare 360') || ' - Main Campus', 'active', v_org.city, '{"created_by":"phase_2a_bootstrap"}'::jsonb)
    returning * into v_campus;
  end if;

  select * into v_year from public.ac360_academic_years where org_id = p_org_id and status = 'active' order by created_at desc limit 1;
  if v_year.id is null then
    insert into public.ac360_academic_years(org_id, label, status, starts_on, ends_on, metadata_json)
    values (p_org_id, '2026-2027', 'active', date '2026-09-01', date '2027-07-31', '{"created_by":"phase_2a_bootstrap"}'::jsonb)
    on conflict (org_id, label) do update set status='active', updated_at=now()
    returning * into v_year;
  end if;

  update public.ac360_organizations
  set current_academic_year_id = coalesce(current_academic_year_id, v_year.id), lifecycle_status = case when lifecycle_status = 'prospect' then 'onboarding' else lifecycle_status end, updated_at = now()
  where id = p_org_id;

  insert into public.ac360_school_operation_events(org_id, campus_id, event_key, action_key, entity_type, entity_id, severity, message, actor_app_user_id, metadata_json)
  values (p_org_id, v_campus.id, 'phase2a.bootstrap.completed', 'school_ops.bootstrap', 'organization', p_org_id, 'info', 'Phase 2A core school operations backend skeleton bootstrapped.', p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb));

  perform public.ac360_measure_capacity(p_org_id, 'students', public.ac360_school_current_capacity(p_org_id,'students'), 'ac360_school_students', '{"source":"phase_2a_bootstrap"}'::jsonb);
  perform public.ac360_measure_capacity(p_org_id, 'staff_users', public.ac360_school_current_capacity(p_org_id,'staff_users'), 'ac360_school_staff_profiles', '{"source":"phase_2a_bootstrap"}'::jsonb);
  perform public.ac360_measure_capacity(p_org_id, 'classes', public.ac360_school_current_capacity(p_org_id,'classes'), 'ac360_school_classes', '{"source":"phase_2a_bootstrap"}'::jsonb);
  perform public.ac360_measure_capacity(p_org_id, 'storage_gb', public.ac360_school_current_capacity(p_org_id,'storage_gb'), 'ac360_school_documents', '{"source":"phase_2a_bootstrap"}'::jsonb);

  return jsonb_build_object('ok', true, 'orgId', p_org_id, 'campusId', v_campus.id, 'academicYearId', v_year.id, 'readiness', public.ac360_school_ops_readiness_dashboard(p_org_id));
end;
$$;


--
-- Name: ac360_cancel_addon(uuid, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_cancel_addon(p_org_id uuid, p_addon_key text, p_cancel_at_period_end boolean DEFAULT true, p_actor_app_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_item public.ac360_subscription_items%rowtype;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  if p_addon_key is null then raise exception 'p_addon_key is required'; end if;

  select * into v_item from public.ac360_subscription_items
  where org_id = p_org_id and addon_key = p_addon_key and status in ('active','cancel_pending')
  order by created_at desc limit 1;
  if v_item.id is null then raise exception 'No active add-on subscription item found for %', p_addon_key; end if;

  update public.ac360_subscription_items
  set status = case when p_cancel_at_period_end then 'cancel_pending' else 'cancelled' end,
      cancel_at_period_end = p_cancel_at_period_end,
      cancelled_at = case when p_cancel_at_period_end then null else now() end,
      updated_at = now(),
      metadata_json = metadata_json || jsonb_build_object('data_preservation','enabled','cancel_reason','client_controlled_menu_cancellation')
  where id = v_item.id
  returning * into v_item;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-30', 'addon.cancelled_or_pending', 'addon.cancel', 'subscription_item', v_item.id, 'success', 'warning', p_actor_app_user_id, null, jsonb_build_object('addon_key',p_addon_key,'cancel_at_period_end',p_cancel_at_period_end,'data_preserved',true));

  return jsonb_build_object('ok', true, 'item', to_jsonb(v_item), 'dataPreserved', true);
end;
$$;


--
-- Name: ac360_count_table(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_count_table(p_table_name text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_count bigint := 0;
begin
  if p_table_name is null or p_table_name !~ '^ac360_[a-z0-9_]+$' then
    return 0;
  end if;
  if to_regclass('public.' || p_table_name) is null then
    return 0;
  end if;
  execute format('select count(*) from public.%I', p_table_name) into v_count;
  return coalesce(v_count, 0);
end;
$_$;


--
-- Name: ac360_create_phase2u_pre_ui_handoff(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_create_phase2u_pre_ui_handoff(p_org_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.ac360_phase2u_resolve_org(p_org_id);
  v_lock_id uuid;
  v_manifest_id uuid;
  v_id uuid;
  v_key text := 'phase2u-pre-ui-instruction-handoff';
begin
  select id into v_lock_id from public.ac360_phase2u_final_backend_locks where org_id=v_org_id order by created_at desc limit 1;
  select id into v_manifest_id from public.ac360_phase2u_release_manifests where org_id=v_org_id order by created_at desc limit 1;

  insert into public.ac360_phase2u_pre_ui_handoffs(org_id,handoff_key,handoff_status,instruction_required,ui_build_allowed,visual_instruction_status,required_instruction_json,backend_summary_json,lock_id,manifest_id,message)
  values(
    v_org_id,
    v_key,
    'waiting_for_user_instructions',
    true,
    false,
    'not_received',
    jsonb_build_object(
      'requiredBeforeUiBuild',true,
      'items',array['global visual direction','navigation/sitemap priority','dashboard information architecture','white-theme rules','card/table/modal style','mobile/desktop expectations','role-based experiences','AngelCare brand/logo rules'],
      'explicitStopRule','Do not create AC360 front-end pages until user provides instructions.'
    ),
    jsonb_build_object('phase','phase_2u','backendLocked',true,'uiBuildAllowed',false,'coveredThrough','Phase 2U','guardDoctrine','strict AC360 wired actions'),
    v_lock_id,
    v_manifest_id,
    'AngelCare 360 backend runtime is locked through Phase 2U. UI/front-end build must wait for explicit user visual and UX instructions.'
  )
  on conflict(org_id,handoff_key) do update set
    handoff_status='waiting_for_user_instructions',
    instruction_required=true,
    ui_build_allowed=false,
    visual_instruction_status='not_received',
    required_instruction_json=excluded.required_instruction_json,
    backend_summary_json=excluded.backend_summary_json,
    lock_id=excluded.lock_id,
    manifest_id=excluded.manifest_id,
    message=excluded.message,
    updated_at=now()
  returning id into v_id;

  return (select to_jsonb(h) from public.ac360_phase2u_pre_ui_handoffs h where h.id=v_id);
end $$;


--
-- Name: ac360_create_phase2u_release_manifest(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_create_phase2u_release_manifest(p_org_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.ac360_phase2u_resolve_org(p_org_id);
  v_id uuid;
  v_key text := 'phase2u-release-manifest';
begin
  insert into public.ac360_phase2u_release_manifests(org_id,manifest_key,release_status,covered_phases,covered_systems,backend_only,ui_build_allowed,deployment_notes,manifest_json)
  values(
    v_org_id,
    v_key,
    'ready_for_instruction',
    array['phase_1','phase_1b','phase_1c','phase_1d','phase_1e','phase_1f','phase_2a','phase_2b','phase_2c','phase_2d','phase_2e','phase_2f','phase_2g','phase_2h','phase_2i','phase_2j','phase_2k','phase_2l','phase_2m','phase_2n','phase_2o','phase_2p','phase_2q','phase_2r','phase_2s','phase_2t','phase_2u'],
    array['tenant','rbac','billing','entitlements','usage','policy','school_ops','admissions','finance','communication','documents','workflows','hr','health_safety','transport','parenttrust','academy','automation','intake','branding_integrations','onboarding_success','internal_admin','qa_hardening'],
    true,
    false,
    'Backend runtime locked through Phase 2U. Front-end build requires explicit user UI/UX instructions.',
    jsonb_build_object('phase','phase_2u','backendOnly',true,'uiBuildAllowed',false,'requiresUserUiInstructions',true,'archiveNotDelete',true,'guardDoctrine','organization -> subscription -> entitlement -> policy -> capacity/usage/credits -> execute -> usage/audit') || p_metadata
  )
  on conflict(org_id,manifest_key) do update set
    release_status=excluded.release_status,
    covered_phases=excluded.covered_phases,
    covered_systems=excluded.covered_systems,
    backend_only=excluded.backend_only,
    ui_build_allowed=false,
    deployment_notes=excluded.deployment_notes,
    manifest_json=public.ac360_phase2u_release_manifests.manifest_json || excluded.manifest_json,
    updated_at=now()
  returning id into v_id;

  return (select to_jsonb(m) from public.ac360_phase2u_release_manifests m where m.id=v_id);
end $$;


--
-- Name: ac360_create_policy_event(uuid, uuid, text, text, text, text, text, text, text, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_create_policy_event(p_org_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_event_key text DEFAULT 'policy.event'::text, p_action_key text DEFAULT NULL::text, p_feature_key text DEFAULT NULL::text, p_meter_key text DEFAULT NULL::text, p_route_path text DEFAULT NULL::text, p_http_method text DEFAULT NULL::text, p_severity text DEFAULT 'warning'::text, p_status text DEFAULT 'open'::text, p_message text DEFAULT 'AC360 policy event recorded.'::text, p_guard_decision_id uuid DEFAULT NULL::uuid, p_override_request_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_id uuid;
  v_severity text := case when p_severity in ('info','warning','critical') then p_severity else 'warning' end;
  v_status text := case when p_status in ('open','acknowledged','resolved','archived') then p_status else 'open' end;
begin
  insert into public.ac360_policy_events(org_id, actor_app_user_id, event_key, action_key, feature_key, meter_key, route_path, http_method, severity, status, message, guard_decision_id, override_request_id, metadata_json)
  values (
    p_org_id,
    p_actor_app_user_id,
    coalesce(nullif(p_event_key,''),'policy.event'),
    case when exists (select 1 from public.ac360_action_registry ar where ar.action_key = nullif(p_action_key,'')) then nullif(p_action_key,'') else null end,
    case when exists (select 1 from public.ac360_feature_registry fr where fr.feature_key = nullif(p_feature_key,'')) then nullif(p_feature_key,'') else null end,
    case when exists (select 1 from public.ac360_usage_meters um where um.meter_key = nullif(p_meter_key,'')) then nullif(p_meter_key,'') else null end,
    nullif(p_route_path,''),
    nullif(p_http_method,''),
    v_severity,
    v_status,
    coalesce(nullif(p_message,''),'AC360 policy event recorded.'),
    p_guard_decision_id,
    p_override_request_id,
    coalesce(p_metadata,'{}'::jsonb)
  )
  returning id into v_id;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-10', 'policy.event.recorded', p_action_key, 'policy_event', v_id, case when v_severity='critical' then 'warning' else 'success' end, case when v_severity='critical' then 'critical' else v_severity end, p_actor_app_user_id, null, jsonb_build_object('event_key',p_event_key,'route_path',p_route_path,'http_method',p_http_method) || coalesce(p_metadata,'{}'::jsonb));

  return jsonb_build_object('ok',true,'event_id',v_id,'severity',v_severity,'status',v_status);
end;
$$;


--
-- Name: ac360_decide_deployment_gate(text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_decide_deployment_gate(p_gate_key text, p_decision text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status text;
  v_gate public.ac360_deployment_gates%rowtype;
begin
  if p_gate_key is null or not exists(select 1 from public.ac360_deployment_gates where gate_key = p_gate_key) then
    return jsonb_build_object('ok',false,'error','Unknown deployment gate.');
  end if;

  v_status := case lower(coalesce(p_decision,'')) when 'approve' then 'ready' when 'ready' then 'ready' when 'waive' then 'waived' when 'waived' then 'waived' when 'block' then 'blocked' else null end;
  if v_status is null then
    return jsonb_build_object('ok',false,'error','Decision must be approve, waive or block.');
  end if;

  update public.ac360_deployment_gates
  set status = v_status,
      blocking_reason = case when v_status='blocked' then coalesce(p_reason,'Manually blocked by AC360 governance.') else null end,
      approved_by_app_user_id = case when v_status in ('ready','waived') then p_actor_app_user_id else approved_by_app_user_id end,
      approved_at = case when v_status in ('ready','waived') then now() else approved_at end,
      metadata_json = metadata_json || coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('manualDecisionReason',p_reason),
      updated_at = now()
  where gate_key = p_gate_key
  returning * into v_gate;

  insert into public.ac360_deployment_gate_events(gate_key, event_key, status, message, actor_app_user_id, metadata_json)
  values (p_gate_key, 'deployment_gate.manual_decision', v_status, coalesce(p_reason,'Manual AC360 gate decision.'), p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb));

  perform public.ac360_record_audit(null, 'AC360-ENG-10', 'deployment_gate.decided', 'deployment_gate.decide', 'deployment_gate', null, v_status, 'warning', p_actor_app_user_id, null, jsonb_build_object('gateKey',p_gate_key,'decision',p_decision,'reason',p_reason));

  return jsonb_build_object('ok',true,'gate',to_jsonb(v_gate));
end;
$$;


--
-- Name: ac360_decide_phase2_pre_ui_gate(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_decide_phase2_pre_ui_gate(p_org_id uuid, p_decision text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status text;
  v_allow boolean := false;
begin
  v_status := case
    when p_decision in ('lock','locked') then 'locked'
    when p_decision in ('block','blocked') then 'blocked'
    when p_decision in ('ready','ready_for_instruction') then 'ready_for_instruction'
    when p_decision in ('approve_ui_design','approved_for_ui_design') then 'approved_for_ui_design'
    else 'locked'
  end;

  -- Safety doctrine: even approved_for_ui_design does not start building UI; it only records permission to request user instructions.
  v_allow := false;

  insert into public.ac360_phase2_pre_ui_gates(org_id,gate_key,gate_type,status,ui_build_allowed,readiness_score,critical_failures,warning_count,decision_reason,decision_by,decision_at,gate_json,metadata_json)
  values(p_org_id,'phase2-pre-ui-master-gate','phase2_pre_ui',v_status,v_allow,0,0,0,coalesce(p_reason,'Manual Phase 2 pre-UI gate decision.'),p_actor_app_user_id,now(),jsonb_build_object('manualDecision',p_decision,'uiBuildAllowed',v_allow,'mustAskUserForUiInstructions',true),coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,gate_key) do update set
    status=excluded.status,
    ui_build_allowed=excluded.ui_build_allowed,
    decision_reason=excluded.decision_reason,
    decision_by=excluded.decision_by,
    decision_at=excluded.decision_at,
    gate_json=public.ac360_phase2_pre_ui_gates.gate_json || excluded.gate_json,
    metadata_json=public.ac360_phase2_pre_ui_gates.metadata_json || excluded.metadata_json,
    updated_at=now();

  return jsonb_build_object('ok',true,'gate_key','phase2-pre-ui-master-gate','status',v_status,'uiBuildAllowed',v_allow,'mustAskUserForUiInstructions',true);
end $$;


--
-- Name: ac360_decide_policy_override(uuid, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_decide_policy_override(p_request_id uuid, p_decision text, p_decision_reason text, p_decided_by_app_user_id uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_row public.ac360_policy_override_requests%rowtype;
  v_status text;
begin
  if p_decision not in ('approved','denied','cancelled') then
    return jsonb_build_object('ok',false,'error','Decision must be approved, denied, or cancelled.');
  end if;
  select * into v_row from public.ac360_policy_override_requests where id = p_request_id limit 1;
  if v_row.id is null then
    return jsonb_build_object('ok',false,'error','Override request not found.');
  end if;
  v_status := p_decision;
  update public.ac360_policy_override_requests
     set status = v_status,
         decided_by_app_user_id = p_decided_by_app_user_id,
         decided_at = now(),
         decision_reason = p_decision_reason,
         expires_at = case when v_status='approved' then coalesce(p_expires_at, expires_at, now() + interval '2 hours') else expires_at end,
         updated_at = now()
   where id = p_request_id
   returning * into v_row;

  perform public.ac360_create_policy_event(v_row.org_id, p_decided_by_app_user_id, 'policy.override.' || v_status, v_row.action_key, v_row.feature_key, v_row.meter_key, v_row.route_path, null, case when v_status='approved' then 'warning' else 'info' end, 'open', 'Policy override ' || v_status || ': ' || coalesce(p_decision_reason,''), v_row.guard_decision_id, v_row.id, jsonb_build_object('decision',v_status));
  perform public.ac360_record_audit(v_row.org_id, 'AC360-ENG-27', 'policy.override.' || v_status, v_row.action_key, 'policy_override_request', v_row.id, 'success', case when v_status='approved' then 'warning' else 'notice' end, p_decided_by_app_user_id, null, jsonb_build_object('decision_reason',p_decision_reason,'expires_at',v_row.expires_at));

  return jsonb_build_object('ok',true,'override_request_id',v_row.id,'status',v_row.status,'expires_at',v_row.expires_at);
end;
$$;


--
-- Name: ac360_evaluate_deployment_gate(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_evaluate_deployment_gate(p_org_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_qa jsonb;
  v_ready integer;
  v_total integer;
  v_blocked integer;
  v_score numeric;
begin
  v_qa := public.ac360_run_foundation_qa(p_org_id, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('source','deployment_gate.evaluate'));

  select count(*) into v_total from public.ac360_deployment_gates where required = true;
  select count(*) into v_ready from public.ac360_deployment_gates where required = true and status in ('ready','waived');
  select count(*) into v_blocked from public.ac360_deployment_gates where required = true and status = 'blocked';
  v_score := coalesce((v_qa ->> 'readinessScore')::numeric, 0);

  insert into public.ac360_deployment_gate_events(gate_key, run_id, event_key, status, message, actor_app_user_id, metadata_json)
  values ('phase2.entry.authorization', nullif(v_qa ->> 'runId','')::uuid, 'deployment_gate.evaluated', case when v_blocked = 0 and v_score >= 90 then 'ready' else 'blocked' end,
          case when v_blocked = 0 and v_score >= 90 then 'Deployment gate evaluated as ready.' else 'Deployment gate evaluated as blocked.' end,
          p_actor_app_user_id,
          jsonb_build_object('readyGates',v_ready,'totalGates',v_total,'blockedGates',v_blocked,'qa',v_qa));

  return jsonb_build_object('ok', true, 'phase','phase_1f_foundation_qa_gate', 'qa', v_qa, 'readyGates', v_ready, 'totalGates', v_total, 'blockedGates', v_blocked, 'phase2Allowed', v_blocked = 0 and v_score >= 90);
end;
$$;


--
-- Name: ac360_evaluate_phase2_pre_ui_gate(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_evaluate_phase2_pre_ui_gate(p_org_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run jsonb;
  v_run_id uuid;
  v_score numeric;
  v_critical integer;
  v_warning integer;
  v_status text;
begin
  v_run := public.ac360_run_phase2_runtime_qa(p_org_id,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb) || '{"preUiGateEvaluation":true}'::jsonb);
  v_run_id := (v_run->>'run_id')::uuid;
  v_score := coalesce((v_run->>'readiness_score')::numeric,0);
  v_critical := coalesce((v_run->>'critical_failures')::integer,0);
  v_warning := coalesce((v_run->>'warning_count')::integer,0);
  v_status := case when v_critical > 0 then 'blocked' when v_score >= 98 then 'ready_for_instruction' else 'locked' end;

  insert into public.ac360_phase2_pre_ui_gates(org_id,gate_key,gate_type,status,ui_build_allowed,readiness_score,qa_run_id,critical_failures,warning_count,decision_reason,decision_by,decision_at,gate_json,metadata_json)
  values(p_org_id,'phase2-pre-ui-master-gate','phase2_pre_ui',v_status,false,v_score,v_run_id,v_critical,v_warning,
         case when v_status='ready_for_instruction' then 'Backend runtime is ready for user UI/UX instructions, but UI build remains locked until explicit instruction.' else 'Backend runtime is not ready for UI instructions yet.' end,
         p_actor_app_user_id,now(),jsonb_build_object('phase','phase_2s','uiBuildAllowed',false,'mustAskUserForUiInstructions',true,'run',v_run),coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,gate_key) do update set
    status=excluded.status,
    ui_build_allowed=false,
    readiness_score=excluded.readiness_score,
    qa_run_id=excluded.qa_run_id,
    critical_failures=excluded.critical_failures,
    warning_count=excluded.warning_count,
    decision_reason=excluded.decision_reason,
    decision_by=excluded.decision_by,
    decision_at=excluded.decision_at,
    gate_json=excluded.gate_json,
    metadata_json=public.ac360_phase2_pre_ui_gates.metadata_json || excluded.metadata_json,
    updated_at=now();

  return jsonb_build_object('ok',true,'gate_key','phase2-pre-ui-master-gate','status',v_status,'uiBuildAllowed',false,'readiness_score',v_score,'critical_failures',v_critical,'warning_count',v_warning,'mustAskUserForUiInstructions',v_status='ready_for_instruction');
end $$;


--
-- Name: ac360_evaluate_phase2t_deployment_readiness(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_evaluate_phase2t_deployment_readiness(p_org_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_key text := 'phase2t-readiness-' || coalesce(p_org_id::text,'global') || '-' || extract(epoch from clock_timestamp())::bigint || '-' || substr(gen_random_uuid()::text,1,8);
  v_latest_hardening public.ac360_phase2t_build_hardening_runs%rowtype;
  v_latest_sweep public.ac360_phase2t_api_contract_sweeps%rowtype;
  v_latest_pre_ui public.ac360_phase2_pre_ui_gates%rowtype;
  v_blockers int := 0;
  v_warnings int := 0;
  v_score numeric(5,2) := 0;
  v_status text := 'passed';
  v_readiness text := 'backend_ready_pre_ui_locked';
begin
  select * into v_latest_hardening from public.ac360_phase2t_build_hardening_runs where (p_org_id is null or org_id=p_org_id) order by created_at desc limit 1;
  select * into v_latest_sweep from public.ac360_phase2t_api_contract_sweeps where (p_org_id is null or org_id=p_org_id) order by created_at desc limit 1;
  select * into v_latest_pre_ui from public.ac360_phase2_pre_ui_gates where (p_org_id is null or org_id=p_org_id) order by created_at desc limit 1;

  if v_latest_hardening.id is null or v_latest_hardening.status not in ('passed','warning') then v_blockers := v_blockers + 1; end if;
  if v_latest_sweep.id is null or v_latest_sweep.status not in ('passed','warning') then v_blockers := v_blockers + 1; end if;
  if v_latest_pre_ui.id is null then v_warnings := v_warnings + 1; end if;
  if v_latest_pre_ui.ui_build_allowed is true then v_blockers := v_blockers + 1; end if;
  if v_latest_hardening.status='warning' then v_warnings := v_warnings + 1; end if;
  if v_latest_sweep.status='warning' then v_warnings := v_warnings + 1; end if;

  v_score := case when v_blockers > 0 then 60 when v_warnings > 0 then 90 else 100 end;
  v_status := case when v_blockers > 0 then 'failed' when v_warnings > 0 then 'warning' else 'passed' end;
  v_readiness := case when v_blockers > 0 then 'blocked' when v_warnings > 0 then 'backend_ready_pre_ui_locked' else 'ready_for_ui_instruction' end;

  insert into public.ac360_phase2t_deployment_readiness_runs(org_id,readiness_key,status,deployment_readiness,backend_ready,ui_build_allowed,readiness_score,blocker_count,warning_count,summary_json,metadata_json,evaluated_by)
  values(p_org_id,v_key,v_status,v_readiness,(v_blockers=0),false,v_score,v_blockers,v_warnings,
         jsonb_build_object('hardeningRunId',v_latest_hardening.id,'hardeningStatus',v_latest_hardening.status,'apiSweepId',v_latest_sweep.id,'apiSweepStatus',v_latest_sweep.status,'preUiGateId',v_latest_pre_ui.id,'preUiStatus',v_latest_pre_ui.status,'uiBuildAllowed',coalesce(v_latest_pre_ui.ui_build_allowed,false)),
         coalesce(p_metadata,'{}'::jsonb),p_actor_app_user_id)
  returning id into v_id;

  insert into public.ac360_phase2t_deployment_readiness_results(org_id,readiness_run_id,check_key,check_group,severity,status,message,evidence_json,remediation_hint)
  values
  (p_org_id,v_id,'hardening_run_status','build','critical',case when v_latest_hardening.id is not null and v_latest_hardening.status in ('passed','warning') then 'passed' else 'failed' end,'Latest Phase 2T build hardening run must exist and be non-failing.',jsonb_build_object('runId',v_latest_hardening.id,'status',v_latest_hardening.status),'Run /api/ac360/phase2-build-hardening/typescript/run and repair blockers.'),
  (p_org_id,v_id,'api_contract_sweep_status','api_contracts','critical',case when v_latest_sweep.id is not null and v_latest_sweep.status in ('passed','warning') then 'passed' else 'failed' end,'Latest Phase 2T API contract sweep must exist and be non-failing.',jsonb_build_object('sweepId',v_latest_sweep.id,'status',v_latest_sweep.status),'Run /api/ac360/phase2-build-hardening/api-contracts/sweep and repair blockers.'),
  (p_org_id,v_id,'pre_ui_lock_status','pre_ui_gate','critical',case when coalesce(v_latest_pre_ui.ui_build_allowed,false)=false then 'passed' else 'failed' end,'UI build must remain locked until explicit user UX instructions.',jsonb_build_object('preUiGateId',v_latest_pre_ui.id,'uiBuildAllowed',coalesce(v_latest_pre_ui.ui_build_allowed,false)),'Reset pre-UI gate and ask user for UI/UX instructions before UI work.'),
  (p_org_id,v_id,'backend_ready_status','deployment','high',case when v_blockers=0 then 'passed' else 'failed' end,'Backend runtime should be deployable before front-end build begins.',jsonb_build_object('blockers',v_blockers,'warnings',v_warnings,'readiness',v_readiness),'Repair blockers, rerun hardening and reevaluate readiness.');

  if v_blockers > 0 then
    insert into public.ac360_phase2t_alerts(org_id,alert_key,alert_type,severity,status,title,message,related_readiness_id,metadata_json)
    values(p_org_id,'phase2t-deployment-readiness-'||v_id,'deployment_readiness','critical','open','Phase 2T deployment readiness blocked','Backend deployment readiness has blockers.',v_id,jsonb_build_object('readinessKey',v_key))
    on conflict(org_id,alert_key) do nothing;
  end if;

  return jsonb_build_object('ok',true,'readinessRunId',v_id,'readinessKey',v_key,'status',v_status,'deploymentReadiness',v_readiness,'backendReady',(v_blockers=0),'uiBuildAllowed',false,'readinessScore',v_score,'blockers',v_blockers,'warnings',v_warnings);
end;
$$;


--
-- Name: ac360_evaluate_phase2u_final_backend_lock(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_evaluate_phase2u_final_backend_lock(p_org_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.ac360_phase2u_resolve_org(p_org_id);
  v_lock_id uuid;
  v_key text := 'phase2u-final-backend-lock-' || replace(gen_random_uuid()::text,'-','');
  v_total integer := 0;
  v_passed integer := 0;
  v_failed integer := 0;
  v_warning integer := 0;
  v_blockers integer := 0;
  v_score numeric(5,2) := 0;
  v_status text := 'locked';
  v_backend_status text := 'backend_locked_pre_ui';
  v_latest_sql record;
begin
  insert into public.ac360_phase2u_final_backend_locks(org_id,lock_key,lock_status,backend_status,ui_build_allowed,ui_instruction_required,metadata_json)
  values(v_org_id,v_key,'evaluating','not_ready',false,true,p_metadata)
  returning id into v_lock_id;

  select * into v_latest_sql from public.ac360_phase2u_sql_compatibility_sweeps where org_id=v_org_id order by created_at desc limit 1;
  if v_latest_sql.id is null then
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'sql_compatibility.latest_sweep','sql_compatibility','warning','high','No Phase 2U SQL compatibility sweep found before final lock.','Run /api/ac360/phase2-final-lock/sql-compatibility/sweep first.');
  elsif v_latest_sql.critical_failures > 0 or v_latest_sql.status = 'failed' then
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'sql_compatibility.latest_sweep','sql_compatibility','failed','critical','Latest Phase 2U SQL compatibility sweep has blockers.','Repair SQL/schema failures and rerun sweep.',to_jsonb(v_latest_sql));
  else
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'sql_compatibility.latest_sweep','sql_compatibility','passed','low','Latest SQL compatibility sweep passed or has no critical blockers.',null,to_jsonb(v_latest_sql));
  end if;

  if to_regclass('public.ac360_phase2s_pre_ui_gates') is not null then
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'phase2s.pre_ui_gate.exists','pre_ui_gate','passed','low','Phase 2S pre-UI gate table exists.');
  else
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'phase2s.pre_ui_gate.exists','pre_ui_gate','failed','critical','Phase 2S pre-UI gate table is missing.','Apply Phase 2S before final lock.');
  end if;

  if to_regclass('public.ac360_phase2t_deployment_readiness_runs') is not null then
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'phase2t.deployment_readiness.exists','deployment_readiness','passed','low','Phase 2T deployment readiness table exists.');
  else
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'phase2t.deployment_readiness.exists','deployment_readiness','failed','critical','Phase 2T deployment readiness table is missing.','Apply Phase 2T before final lock.');
  end if;

  if (select count(*) from public.ac360_action_registry where action_key like 'school.%' or action_key like 'internal.%' or action_key like 'phase2.%') >= 170 then
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'action_registry.phase2_coverage','guard_wiring','passed','low','Phase 2 action registry coverage is sufficient.',null,jsonb_build_object('actions',(select count(*) from public.ac360_action_registry where action_key like 'school.%' or action_key like 'internal.%' or action_key like 'phase2.%')));
  else
    perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'action_registry.phase2_coverage','guard_wiring','failed','critical','Phase 2 action registry coverage is below expected threshold.','Re-apply missing runtime migrations.',jsonb_build_object('actions',(select count(*) from public.ac360_action_registry where action_key like 'school.%' or action_key like 'internal.%' or action_key like 'phase2.%')));
  end if;

  perform public.ac360_phase2u_add_lock_result(v_org_id,v_lock_id,'ui_build.locked','pre_ui_handoff','passed','critical','UI build remains locked until user provides explicit visual/UX instructions.',null,jsonb_build_object('uiBuildAllowed',false,'instructionRequired',true));

  select count(*),
         count(*) filter (where status='passed'),
         count(*) filter (where status='warning'),
         count(*) filter (where status in ('failed','blocked')),
         count(*) filter (where status in ('failed','blocked') and severity='critical')
    into v_total, v_passed, v_warning, v_failed, v_blockers
  from public.ac360_phase2u_final_backend_lock_results
  where lock_id=v_lock_id;

  v_score := case when v_total = 0 then 0 else round((v_passed::numeric / v_total::numeric) * 100, 2) end;
  if v_blockers > 0 then
    v_status := 'blocked';
    v_backend_status := 'blocked';
  else
    v_status := 'ready_for_instruction';
    v_backend_status := 'ready_for_ui_instruction';
  end if;

  update public.ac360_phase2u_final_backend_locks
  set lock_status=v_status,
      backend_status=v_backend_status,
      backend_locked=(v_blockers=0),
      ui_build_allowed=false,
      ui_instruction_required=true,
      phase2_runtime_complete=(v_blockers=0),
      sql_compatible=coalesce(v_latest_sql.critical_failures,0)=0,
      api_contracts_ready=(v_blockers=0),
      guard_wiring_ready=(v_blockers=0),
      deployment_ready=(v_blockers=0),
      readiness_score=v_score,
      blocker_count=v_blockers,
      warning_count=v_warning,
      evaluated_at=now(),
      summary_json=jsonb_build_object('phase','phase_2u','total',v_total,'passed',v_passed,'failed',v_failed,'warnings',v_warning,'blockers',v_blockers,'score',v_score,'backendStatus',v_backend_status,'uiBuildAllowed',false,'requiresUserUiInstructions',true),
      updated_at=now()
  where id=v_lock_id;

  if v_blockers = 0 then
    perform public.ac360_create_phase2u_release_manifest(v_org_id, jsonb_build_object('source','final_backend_lock','lockId',v_lock_id));
  else
    insert into public.ac360_phase2u_alerts(org_id,alert_key,alert_type,severity,status,title,message,related_lock_id,metadata_json)
    values(v_org_id,'phase2u.final_lock.blocked.'||v_lock_id,'final_backend_lock','critical','open','Phase 2U final backend lock is blocked','Repair critical blockers before UI instruction handoff.',v_lock_id,jsonb_build_object('blockers',v_blockers))
    on conflict(org_id,alert_key) do nothing;
  end if;

  return (select to_jsonb(l) from public.ac360_phase2u_final_backend_locks l where l.id=v_lock_id);
end $$;


--
-- Name: ac360_foundation_readiness_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_foundation_readiness_dashboard(p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_latest_run public.ac360_foundation_qa_runs%rowtype;
  v_runs jsonb;
  v_results jsonb;
  v_gates jsonb;
  v_matrix jsonb;
  v_engine jsonb;
  v_events jsonb;
  v_rules jsonb;
begin
  select * into v_latest_run from public.ac360_foundation_qa_runs
  where (p_org_id is null or org_id = p_org_id or org_id is null)
  order by created_at desc
  limit 1;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc), '[]'::jsonb) into v_runs
  from (select * from public.ac360_foundation_qa_runs where (p_org_id is null or org_id = p_org_id or org_id is null) order by created_at desc limit 20) r;

  select coalesce(jsonb_agg(to_jsonb(r) order by case r.status when 'failed' then 1 when 'warning' then 2 when 'skipped' then 3 else 4 end, r.check_key), '[]'::jsonb) into v_results
  from public.ac360_foundation_qa_results r
  where v_latest_run.id is not null and r.run_id = v_latest_run.id;

  select coalesce(jsonb_agg(to_jsonb(g) order by g.required desc, g.gate_key), '[]'::jsonb) into v_gates from public.ac360_deployment_gates g;
  select coalesce(jsonb_agg(to_jsonb(m) order by m.sort_order), '[]'::jsonb) into v_matrix from public.ac360_foundation_gate_matrix m where m.status = 'active';
  select coalesce(jsonb_agg(to_jsonb(e) order by e.engine_code), '[]'::jsonb) into v_engine from public.ac360_engine_coverage_matrix e;
  select coalesce(jsonb_agg(to_jsonb(ev) order by ev.created_at desc), '[]'::jsonb) into v_events from (select * from public.ac360_deployment_gate_events order by created_at desc limit 80) ev;
  select coalesce(jsonb_agg(to_jsonb(ar) order by ar.sort_order), '[]'::jsonb) into v_rules from public.ac360_automation_rules ar where ar.rule_key like 'phase1f.%';

  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_1f_foundation_qa_gate',
    'latestRun', case when v_latest_run.id is null then null else to_jsonb(v_latest_run) end,
    'runs', v_runs,
    'results', v_results,
    'gates', v_gates,
    'matrix', v_matrix,
    'engineCoverage', v_engine,
    'events', v_events,
    'rules', v_rules,
    'phase2Allowed', coalesce((select bool_and(status in ('ready','waived')) from public.ac360_deployment_gates where required=true), false)
  );
end;
$$;


--
-- Name: ac360_generate_subscription_invoice(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_generate_subscription_invoice(p_org_id uuid, p_period_start date DEFAULT (date_trunc('month'::text, now()))::date, p_period_end date DEFAULT ((date_trunc('month'::text, now()) + '1 mon -1 days'::interval))::date, p_status text DEFAULT 'issued'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_org public.ac360_organizations%rowtype;
  v_sub public.ac360_subscriptions%rowtype;
  v_invoice public.ac360_invoices%rowtype;
  v_invoice_number text;
  v_total numeric := 0;
begin
  p_period_start := coalesce(p_period_start, date_trunc('month', now())::date);
  p_period_end := coalesce(p_period_end, (date_trunc('month', now()) + interval '1 month - 1 day')::date);

  select * into v_org from public.ac360_organizations where id = p_org_id;
  if v_org.id is null then raise exception 'Unknown AC360 org %', p_org_id; end if;

  select * into v_sub from public.ac360_subscriptions
  where org_id = p_org_id and status in ('trial','active','grace','past_due','restricted')
  order by case status when 'active' then 1 when 'trial' then 2 when 'grace' then 3 else 4 end, created_at desc limit 1;
  if v_sub.id is null then raise exception 'No active subscription found for organization %', p_org_id; end if;

  v_invoice_number := 'AC360-INV-' || to_char(p_period_start, 'YYYYMM') || '-' || upper(left(regexp_replace(v_org.org_code, '[^A-Za-z0-9]+', '', 'g'), 18));

  insert into public.ac360_invoices(org_id, subscription_id, invoice_number, status, currency, subtotal_mad, total_mad, issued_at, due_date, period_start, period_end, metadata_json)
  values (p_org_id, v_sub.id, v_invoice_number, case when p_status in ('draft','issued','sent') then p_status else 'issued' end, 'MAD', 0, 0, now(), current_date + 7, p_period_start, p_period_end, jsonb_build_object('generated_by','ac360_phase1b_runtime_bridge'))
  on conflict (invoice_number) do update set status = excluded.status, issued_at = excluded.issued_at, due_date = excluded.due_date, updated_at = now()
  returning * into v_invoice;

  delete from public.ac360_invoice_lines where invoice_id = v_invoice.id;

  insert into public.ac360_invoice_lines(invoice_id, org_id, line_type, item_key, label, description, quantity, unit_price_mad, amount_mad, period_start, period_end, metadata_json)
  select v_invoice.id, p_org_id,
         case when item_type = 'base_plan' then 'subscription' when item_type = 'serenite_bundle' then 'serenite' when item_type = 'addon' then 'addon' else item_type end,
         item_key, label, 'AC360 active subscription item', quantity, unit_price_mad, quantity * unit_price_mad, p_period_start, p_period_end, metadata_json
  from public.ac360_subscription_items
  where org_id = p_org_id and subscription_id = v_sub.id and status in ('active','cancel_pending') and billing_interval in ('monthly','annual','custom');

  insert into public.ac360_invoice_lines(invoice_id, org_id, line_type, item_key, label, description, quantity, unit_price_mad, amount_mad, period_start, period_end, metadata_json)
  select v_invoice.id, p_org_id, 'usage', meter_key, 'Usage: ' || meter_key, 'AC360 usage metering for the selected period', quantity,
         case when quantity = 0 then 0 else amount_mad / quantity end,
         amount_mad, p_period_start, p_period_end, jsonb_build_object('meter_key',meter_key,'credits_consumed',credits_consumed)
  from public.ac360_usage_summaries
  where org_id = p_org_id and period_start = p_period_start and period_end = p_period_end and amount_mad > 0;

  select coalesce(sum(amount_mad),0) into v_total from public.ac360_invoice_lines where invoice_id = v_invoice.id;

  update public.ac360_invoices
  set subtotal_mad = v_total, total_mad = v_total, updated_at = now()
  where id = v_invoice.id
  returning * into v_invoice;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-17', 'invoice.generated', 'invoice.generate', 'invoice', v_invoice.id, 'success', 'notice', null, null, jsonb_build_object('period_start',p_period_start,'period_end',p_period_end,'total_mad',v_total));

  return jsonb_build_object('ok', true, 'invoice', to_jsonb(v_invoice), 'totalMad', v_total);
end;
$$;


--
-- Name: ac360_grant_credits(uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_grant_credits(p_org_id uuid, p_amount numeric, p_reason text DEFAULT 'Manual AC360 credit grant'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_wallet public.ac360_credit_wallets%rowtype;
  v_key text := coalesce(p_idempotency_key, gen_random_uuid()::text);
  v_existing public.ac360_credit_ledger%rowtype;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  if coalesce(p_amount, 0) <= 0 then raise exception 'p_amount must be positive'; end if;

  insert into public.ac360_credit_wallets(org_id, wallet_key, credit_type, status, balance, monthly_included_allowance, rollover_policy)
  values (p_org_id, 'main', 'angelcare_credits', 'active', 0, 0, 'no_rollover')
  on conflict (org_id, wallet_key) do update set status = 'active', updated_at = now()
  returning * into v_wallet;

  select * into v_existing from public.ac360_credit_ledger where wallet_id = v_wallet.id and idempotency_key = v_key limit 1;
  if v_existing.id is not null then
    return jsonb_build_object('ok', true, 'idempotent', true, 'wallet', to_jsonb(v_wallet), 'ledger', to_jsonb(v_existing));
  end if;

  update public.ac360_credit_wallets
  set balance = balance + p_amount, status = 'active', updated_at = now()
  where id = v_wallet.id
  returning * into v_wallet;

  insert into public.ac360_credit_ledger(wallet_id, org_id, ledger_type, amount, balance_after, reason, idempotency_key, metadata_json)
  values (v_wallet.id, p_org_id, 'grant', p_amount, v_wallet.balance, p_reason, v_key, jsonb_build_object('actor_app_user_id',p_actor_app_user_id))
  returning * into v_existing;

  update public.ac360_restrictions
  set status = 'resolved', resolved_at = now(), updated_at = now()
  where org_id = p_org_id and status = 'active' and behavior = 'topup_required';

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-36', 'credits.granted', 'credits.grant', 'credit_wallet', v_wallet.id, 'success', 'notice', p_actor_app_user_id, null, jsonb_build_object('amount',p_amount,'reason',p_reason));

  return jsonb_build_object('ok', true, 'wallet', to_jsonb(v_wallet), 'ledger', to_jsonb(v_existing));
end;
$$;


--
-- Name: ac360_guard_action(uuid, text, numeric, uuid, text, jsonb, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_guard_action(p_org_id uuid, p_action_key text, p_quantity numeric DEFAULT 1, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_record_usage boolean DEFAULT false, p_current_capacity numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_existing public.ac360_guard_decisions%rowtype;
  v_action record;
  v_org public.ac360_organizations%rowtype;
  v_sub public.ac360_subscriptions%rowtype;
  v_restriction public.ac360_restrictions%rowtype;
  v_feature_key text;
  v_meter_key text;
  v_access_type text := 'write';
  v_capacity_key text;
  v_suggested_addon_key text;
  v_allowed boolean := true;
  v_decision text := 'allowed';
  v_reason text := 'Action allowed by AC360 guard.';
  v_source text := 'guard';
  v_stage text := 'ready';
  v_access_mode text;
  v_capacity_current numeric;
  v_capacity_limit numeric;
  v_limit_count integer := 0;
  v_required_credits numeric := 0;
  v_credit_cost numeric := 0;
  v_wallet public.ac360_credit_wallets%rowtype;
  v_usage_event_id uuid;
  v_has record;
  v_guard_id uuid;
  v_qty numeric := greatest(coalesce(p_quantity, 1), 0);
  v_result text;
  v_severity text;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  if p_action_key is null or length(trim(p_action_key)) = 0 then raise exception 'p_action_key is required'; end if;

  if p_idempotency_key is not null then
    select * into v_existing
    from public.ac360_guard_decisions
    where org_id = p_org_id and action_key = p_action_key and idempotency_key = p_idempotency_key
    limit 1;
    if v_existing.id is not null then
      return jsonb_build_object(
        'ok', true,
        'idempotent', true,
        'allowed', v_existing.allowed,
        'decision', v_existing.decision,
        'reason', v_existing.reason,
        'source', v_existing.source,
        'guardStage', v_existing.guard_stage,
        'guardDecisionId', v_existing.id,
        'usageEventId', v_existing.usage_event_id,
        'actionKey', p_action_key,
        'featureKey', v_existing.feature_key,
        'meterKey', v_existing.meter_key
      );
    end if;
  end if;

  select ar.*, fr.default_meter_key, fr.default_credit_cost as feature_default_credit_cost
    into v_action
  from public.ac360_action_registry ar
  join public.ac360_feature_registry fr on fr.feature_key = ar.feature_key
  where ar.action_key = p_action_key
  limit 1;

  if not found then
    v_allowed := false;
    v_decision := 'unknown_action';
    v_reason := 'Action is not registered in ac360_action_registry.';
    v_stage := 'action_registry';
  else
    v_feature_key := v_action.feature_key;
    v_meter_key := coalesce(v_action.meter_key, v_action.default_meter_key);
    v_access_type := coalesce(v_action.metadata_json->>'access_type', 'write');
    v_capacity_key := nullif(v_action.metadata_json->>'capacity_key', '');
    v_suggested_addon_key := nullif(v_action.metadata_json->>'suggested_addon_key', '');
    v_credit_cost := coalesce(nullif(v_action.credit_cost, 0), v_action.feature_default_credit_cost, 0);
  end if;

  if v_allowed then
    select * into v_org from public.ac360_organizations where id = p_org_id limit 1;
    if v_org.id is null then
      v_allowed := false;
      v_decision := 'organization_not_found';
      v_reason := 'No AC360 organization exists for this action.';
      v_stage := 'organization';
    elsif v_org.status in ('suspended','cancelled','archived') or v_org.lifecycle_status in ('suspended','cancelled','archived') then
      v_allowed := false;
      v_decision := 'organization_restricted';
      v_reason := 'Organization status does not allow production actions: ' || v_org.status || ' / ' || v_org.lifecycle_status;
      v_stage := 'organization_status';
    end if;
  end if;

  if v_allowed then
    select * into v_sub
    from public.ac360_subscriptions
    where org_id = p_org_id and status in ('trial','active','grace','past_due','restricted')
    order by case status when 'active' then 1 when 'trial' then 2 when 'grace' then 3 when 'past_due' then 4 else 5 end, created_at desc
    limit 1;

    if v_sub.id is null then
      v_allowed := false;
      v_decision := 'no_subscription';
      v_reason := 'No active, trial, grace, past_due or restricted subscription found.';
      v_stage := 'subscription';
    end if;
  end if;

  if v_allowed then
    select * into v_restriction
    from public.ac360_restrictions r
    where r.org_id = p_org_id
      and r.status = 'active'
      and (r.ends_at is null or r.ends_at > now())
      and (
        r.target_action_key is null or r.target_action_key = p_action_key
        or r.target_feature_key is null or r.target_feature_key = v_feature_key
        or (v_meter_key is not null and (r.target_meter_key is null or r.target_meter_key = v_meter_key))
      )
      and r.behavior in ('block','read_only','suspend_non_admin','admin_only','topup_required','upgrade_required')
    order by case r.behavior when 'block' then 1 when 'suspend_non_admin' then 2 when 'admin_only' then 3 when 'topup_required' then 4 when 'upgrade_required' then 5 when 'read_only' then 6 else 9 end, r.created_at desc
    limit 1;

    if v_restriction.id is not null then
      if v_restriction.behavior = 'read_only' and v_access_type = 'read' then
        v_stage := 'restriction_read_only_allowed';
      elsif v_restriction.behavior = 'admin_only' and lower(coalesce(p_metadata->>'is_admin','false')) in ('true','1','yes') then
        v_stage := 'restriction_admin_override';
      else
        v_allowed := false;
        v_decision := case v_restriction.behavior when 'topup_required' then 'topup_required' when 'upgrade_required' then 'upgrade_required' else 'blocked' end;
        v_reason := coalesce(v_restriction.reason, 'Action blocked by active AC360 restriction.');
        v_stage := 'restriction';
        v_access_mode := v_restriction.behavior;
      end if;
    end if;
  end if;

  if v_allowed then
    select * into v_has from public.ac360_has_feature(p_org_id, v_feature_key, p_action_key, v_qty) limit 1;
    v_access_mode := v_has.access_mode;
    if coalesce(v_has.allowed, false) = false then
      if v_has.decision = 'read_only' and v_access_type = 'read' then
        v_stage := 'entitlement_read_only_allowed';
      else
        v_allowed := false;
        v_decision := coalesce(v_has.decision, 'upgrade_required');
        v_reason := coalesce(v_has.reason, 'Feature/action is not included in the current package or active add-ons.');
        v_source := coalesce(v_has.source, 'entitlement');
        v_stage := 'entitlement';
      end if;
    end if;
  end if;

  if v_allowed and v_capacity_key is not null then
    if p_current_capacity is not null then
      v_capacity_current := greatest(p_current_capacity, 0);
    else
      select current_value into v_capacity_current
      from public.ac360_capacity_snapshots
      where org_id = p_org_id and capacity_key = v_capacity_key
      order by measured_at desc
      limit 1;
      v_capacity_current := greatest(coalesce(v_capacity_current, 0), 0);
    end if;

    select sum(limit_value), count(limit_value)
      into v_capacity_limit, v_limit_count
    from (
      select pe.limit_value
      from public.ac360_plan_entitlements pe
      where pe.plan_version_id = v_sub.plan_version_id
        and pe.limit_key = v_capacity_key
        and pe.access_mode in ('included','limited','metered')
        and pe.limit_value is not null
      union all
      select ae.limit_value
      from public.ac360_subscription_items si
      join public.ac360_addon_entitlements ae on ae.addon_key = si.addon_key
      where si.org_id = p_org_id
        and si.subscription_id = v_sub.id
        and si.status in ('active','cancel_pending')
        and ae.limit_key = v_capacity_key
        and ae.access_mode in ('included','limited','metered')
        and ae.limit_value is not null
    ) capacity_limits;

    if v_limit_count = 0 then v_capacity_limit := null; end if;

    if v_capacity_limit is not null and (v_capacity_current + v_qty) > v_capacity_limit then
      v_allowed := false;
      v_decision := 'upgrade_required';
      v_reason := 'Capacity limit reached for ' || v_capacity_key || ': current ' || v_capacity_current || ', requested +' || v_qty || ', limit ' || v_capacity_limit || '.';
      v_stage := 'capacity_limit';

      insert into public.ac360_restrictions(org_id, subscription_id, restriction_key, status, severity, restriction_type, target_feature_key, target_action_key, target_meter_key, behavior, reason, metadata_json)
      values (p_org_id, v_sub.id, 'capacity_reached_' || replace(v_capacity_key, ' ', '_'), 'active', 'warning', 'capacity', v_feature_key, p_action_key, null, 'upgrade_required', v_reason, jsonb_build_object('capacity_key',v_capacity_key,'current',v_capacity_current,'limit',v_capacity_limit,'suggested_addon_key',v_suggested_addon_key))
      on conflict (org_id, restriction_key, target_feature_key, target_action_key, status) do update set reason = excluded.reason, metadata_json = excluded.metadata_json, updated_at = now();

      if v_suggested_addon_key is not null then
        insert into public.ac360_recommendations(org_id, subscription_id, recommendation_key, status, priority, title, message, recommended_addon_key, trigger_json, metadata_json)
        select p_org_id, v_sub.id, 'upgrade_' || v_capacity_key || '_' || v_suggested_addon_key, 'open', 'high',
               'Capacity limit reached',
               'Activate ' || v_suggested_addon_key || ' or upgrade the package before continuing this action.',
               v_suggested_addon_key,
               jsonb_build_object('action_key',p_action_key,'capacity_key',v_capacity_key,'current',v_capacity_current,'limit',v_capacity_limit),
               jsonb_build_object('source','phase1c_guard_wiring')
        where not exists (
          select 1 from public.ac360_recommendations rr
          where rr.org_id = p_org_id and rr.recommendation_key = 'upgrade_' || v_capacity_key || '_' || v_suggested_addon_key and rr.status = 'open'
        );
      end if;
    end if;
  end if;

  if v_allowed and v_meter_key is not null then
    v_required_credits := greatest(v_credit_cost * v_qty, 0);
    if v_required_credits > 0 then
      insert into public.ac360_credit_wallets(org_id, wallet_key, credit_type, status, balance, monthly_included_allowance, rollover_policy)
      values (p_org_id, 'main', 'angelcare_credits', 'active', 0, 0, 'no_rollover')
      on conflict (org_id, wallet_key) do update set updated_at = now()
      returning * into v_wallet;

      if v_wallet.balance < v_required_credits then
        v_allowed := false;
        v_decision := 'topup_required';
        v_reason := 'Insufficient AngelCare Credits for ' || p_action_key || ': required ' || v_required_credits || ', available ' || v_wallet.balance || '.';
        v_stage := 'credits';
        v_access_mode := 'topup_required';

        insert into public.ac360_restrictions(org_id, subscription_id, restriction_key, status, severity, restriction_type, target_feature_key, target_action_key, target_meter_key, behavior, reason, metadata_json)
        values (p_org_id, v_sub.id, 'credits_required_' || coalesce(v_meter_key,'unknown'), 'active', 'critical', 'usage', v_feature_key, p_action_key, v_meter_key, 'topup_required', v_reason, jsonb_build_object('required_credits',v_required_credits,'wallet_balance',v_wallet.balance,'action_key',p_action_key))
        on conflict (org_id, restriction_key, target_feature_key, target_action_key, status) do update set reason = excluded.reason, metadata_json = excluded.metadata_json, updated_at = now();

        insert into public.ac360_recommendations(org_id, subscription_id, recommendation_key, status, priority, title, message, recommended_addon_key, recommended_bundle_key, trigger_json, metadata_json)
        select p_org_id, v_sub.id, 'topup_required_' || coalesce(v_meter_key,'credits'), 'open', 'critical',
               'AngelCare Credits top-up required',
               'Buy a credit pack or switch to Sérénité to avoid action interruptions.',
               'credits_5000', 'serenite_plus',
               jsonb_build_object('meter_key',v_meter_key,'required_credits',v_required_credits,'wallet_balance',v_wallet.balance),
               jsonb_build_object('source','phase1c_guard_wiring')
        where not exists (
          select 1 from public.ac360_recommendations rr
          where rr.org_id = p_org_id and rr.recommendation_key = 'topup_required_' || coalesce(v_meter_key,'credits') and rr.status = 'open'
        );
      end if;
    else
      select * into v_wallet from public.ac360_credit_wallets where org_id = p_org_id and wallet_key = 'main' limit 1;
    end if;
  end if;

  if v_allowed and p_record_usage and v_meter_key is not null then
    v_usage_event_id := public.ac360_record_usage(
      p_org_id,
      v_meter_key,
      v_qty,
      v_feature_key,
      p_action_key,
      p_actor_app_user_id,
      p_idempotency_key,
      coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('guarded',true,'phase','phase1c')
    );
    v_stage := 'usage_recorded';
  elsif v_allowed then
    v_stage := case when v_stage = 'ready' then 'allowed' else v_stage end;
  end if;

  v_result := case when v_allowed then 'success' else 'blocked' end;
  v_severity := case when v_allowed then 'info' when v_decision in ('topup_required','blocked','organization_restricted') then 'critical' else 'warning' end;

  insert into public.ac360_guard_decisions(
    org_id, subscription_id, action_key, feature_key, meter_key, actor_app_user_id, requested_quantity,
    allowed, decision, reason, source, guard_stage, access_mode, capacity_key, capacity_current,
    capacity_limit, credits_required, wallet_balance_before, usage_event_id, idempotency_key, metadata_json
  ) values (
    p_org_id, v_sub.id, p_action_key, v_feature_key, v_meter_key, p_actor_app_user_id, v_qty,
    v_allowed, v_decision, v_reason, v_source, v_stage, v_access_mode, v_capacity_key, v_capacity_current,
    v_capacity_limit, v_required_credits, v_wallet.balance, v_usage_event_id, p_idempotency_key,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('record_usage_requested',p_record_usage,'phase','phase1c_guard_wiring')
  ) returning id into v_guard_id;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-26', 'guard.action.' || v_decision, p_action_key, 'guard_decision', v_guard_id, v_result, v_severity, p_actor_app_user_id, null, jsonb_build_object('allowed',v_allowed,'stage',v_stage,'feature_key',v_feature_key,'meter_key',v_meter_key,'usage_event_id',v_usage_event_id));

  return jsonb_build_object(
    'ok', true,
    'allowed', v_allowed,
    'decision', v_decision,
    'reason', v_reason,
    'source', v_source,
    'guardStage', v_stage,
    'guardDecisionId', v_guard_id,
    'actionKey', p_action_key,
    'featureKey', v_feature_key,
    'meterKey', v_meter_key,
    'subscriptionId', v_sub.id,
    'usageEventId', v_usage_event_id,
    'accessMode', v_access_mode,
    'capacity', jsonb_build_object('capacityKey',v_capacity_key,'current',v_capacity_current,'limit',v_capacity_limit),
    'credits', jsonb_build_object('required',v_required_credits,'walletBalance',v_wallet.balance),
    'recordUsage', p_record_usage
  );
end;
$$;


--
-- Name: ac360_has_feature(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_has_feature(p_org_id uuid, p_feature_key text, p_action_key text DEFAULT NULL::text, p_quantity numeric DEFAULT 1) RETURNS TABLE(allowed boolean, decision text, reason text, source text, access_mode text, limit_key text, limit_value numeric, active_subscription_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_sub record;
  v_restriction record;
  v_ent record;
  v_addon record;
begin
  select s.*, pv.id as pv_id
    into v_sub
  from public.ac360_subscriptions s
  join public.ac360_plan_versions pv on pv.id = s.plan_version_id
  where s.org_id = p_org_id
    and s.status in ('trial','active','grace','past_due','restricted')
  order by case s.status when 'active' then 1 when 'trial' then 2 when 'grace' then 3 else 4 end, s.created_at desc
  limit 1;

  if v_sub.id is null then
    return query select false, 'no_subscription'::text, 'No active subscription found for this organization.'::text, 'subscription'::text, null::text, null::text, null::numeric, null::uuid;
    return;
  end if;

  select * into v_restriction
  from public.ac360_restrictions r
  where r.org_id = p_org_id
    and r.status = 'active'
    and (r.ends_at is null or r.ends_at > now())
    and (
      r.target_feature_key is null or r.target_feature_key = p_feature_key
      or (p_action_key is not null and r.target_action_key = p_action_key)
    )
    and r.behavior in ('block','read_only','suspend_non_admin','admin_only','topup_required','upgrade_required')
  order by case r.behavior when 'block' then 1 when 'suspend_non_admin' then 2 when 'admin_only' then 3 else 4 end, r.created_at desc
  limit 1;

  if v_restriction.id is not null and v_restriction.behavior = 'block' then
    return query select false, 'blocked'::text, coalesce(v_restriction.reason, 'Feature blocked by active account restriction.')::text, 'restriction'::text, v_restriction.behavior::text, null::text, null::numeric, v_sub.id::uuid;
    return;
  end if;

  select pe.* into v_ent
  from public.ac360_plan_entitlements pe
  where pe.plan_version_id = v_sub.plan_version_id
    and pe.feature_key = p_feature_key
  order by case pe.access_mode when 'included' then 1 when 'limited' then 2 when 'metered' then 3 when 'read_only' then 4 else 9 end
  limit 1;

  if v_ent.id is not null and v_ent.access_mode in ('included','limited','metered','read_only') then
    return query select (v_ent.access_mode <> 'read_only'),
      case when v_ent.access_mode = 'read_only' then 'read_only' else 'allowed' end::text,
      ('Allowed by plan entitlement: ' || v_ent.entitlement_key)::text,
      'plan'::text,
      v_ent.access_mode::text,
      v_ent.limit_key::text,
      v_ent.limit_value::numeric,
      v_sub.id::uuid;
    return;
  end if;

  select ae.* into v_addon
  from public.ac360_subscription_items si
  join public.ac360_addon_entitlements ae on ae.addon_key = si.addon_key
  where si.org_id = p_org_id
    and si.subscription_id = v_sub.id
    and si.status in ('active','cancel_pending')
    and ae.feature_key = p_feature_key
  order by si.created_at desc
  limit 1;

  if v_addon.id is not null and v_addon.access_mode in ('included','limited','metered','read_only') then
    return query select (v_addon.access_mode <> 'read_only'),
      case when v_addon.access_mode = 'read_only' then 'read_only' else 'allowed' end::text,
      ('Allowed by active add-on: ' || v_addon.addon_key)::text,
      'addon'::text,
      v_addon.access_mode::text,
      v_addon.limit_key::text,
      v_addon.limit_value::numeric,
      v_sub.id::uuid;
    return;
  end if;

  return query select false, 'upgrade_required'::text, 'Feature is not included in the current package or active add-ons.'::text, 'entitlement'::text, coalesce(v_ent.access_mode, 'blocked')::text, v_ent.limit_key::text, v_ent.limit_value::numeric, v_sub.id::uuid;
end;
$$;


--
-- Name: ac360_internal_admin_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_internal_admin_dashboard(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  select jsonb_build_object(
    'ok', true,
    'phase', 'phase_2r_internal_admin_nationwide_success',
    'asOfDate', coalesce(p_as_of_date, current_date),
    'portfolioAccounts', (select count(*) from public.ac360_internal_portfolio_accounts where org_id=p_org_id and lifecycle_stage <> 'archived'),
    'activeClients', (select count(*) from public.ac360_internal_portfolio_accounts where org_id=p_org_id and lifecycle_stage in ('active','expanding')),
    'atRiskClients', (select count(*) from public.ac360_internal_portfolio_accounts where org_id=p_org_id and (risk_level in ('high','critical') or health_status in ('risk','critical'))),
    'openSupportTickets', (select count(*) from public.ac360_internal_support_tickets where org_id=p_org_id and status not in ('resolved','closed','archived')),
    'criticalIncidents', (select count(*) from public.ac360_internal_deployment_incidents where org_id=p_org_id and severity='critical' and status not in ('resolved','closed','archived')),
    'activeCityMarkets', (select count(*) from public.ac360_internal_city_markets where org_id=p_org_id and market_status in ('pilot','active','scaling')),
    'activeExpansionCampaigns', (select count(*) from public.ac360_internal_expansion_campaigns where org_id=p_org_id and status='active'),
    'pendingInternalTasks', (select count(*) from public.ac360_internal_admin_tasks where org_id=p_org_id and status not in ('completed','cancelled','archived')),
    'openAlerts', (select count(*) from public.ac360_internal_admin_alerts where org_id=p_org_id and status='open'),
    'uiBuildAllowed', false
  ) into result;
  return result;
end $$;


--
-- Name: ac360_internal_admin_reconcile(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_internal_admin_reconcile(p_org_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare snap_id uuid; active_clients integer; risk_clients integer; open_tickets integer; critical_incidents integer; active_cities integer; active_campaigns integer; pending_tasks integer;
begin
  select count(*) into active_clients from public.ac360_internal_portfolio_accounts where org_id=p_org_id and lifecycle_stage in ('active','expanding');
  select count(*) into risk_clients from public.ac360_internal_portfolio_accounts where org_id=p_org_id and (risk_level in ('high','critical') or health_status in ('risk','critical'));
  select count(*) into open_tickets from public.ac360_internal_support_tickets where org_id=p_org_id and status not in ('resolved','closed','archived');
  select count(*) into critical_incidents from public.ac360_internal_deployment_incidents where org_id=p_org_id and severity='critical' and status not in ('resolved','closed','archived');
  select count(*) into active_cities from public.ac360_internal_city_markets where org_id=p_org_id and market_status in ('pilot','active','scaling');
  select count(*) into active_campaigns from public.ac360_internal_expansion_campaigns where org_id=p_org_id and status='active';
  select count(*) into pending_tasks from public.ac360_internal_admin_tasks where org_id=p_org_id and status not in ('completed','cancelled','archived');
  insert into public.ac360_internal_admin_snapshots(org_id,snapshot_date,active_clients,at_risk_clients,open_support_tickets,critical_incidents,active_city_markets,active_expansion_campaigns,pending_internal_tasks,metadata_json)
  values(p_org_id,current_date,active_clients,risk_clients,open_tickets,critical_incidents,active_cities,active_campaigns,pending_tasks,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,snapshot_date) do update set active_clients=excluded.active_clients,at_risk_clients=excluded.at_risk_clients,open_support_tickets=excluded.open_support_tickets,critical_incidents=excluded.critical_incidents,active_city_markets=excluded.active_city_markets,active_expansion_campaigns=excluded.active_expansion_campaigns,pending_internal_tasks=excluded.pending_internal_tasks,metadata_json=public.ac360_internal_admin_snapshots.metadata_json||excluded.metadata_json
  returning id into snap_id;
  if critical_incidents > 0 then
    insert into public.ac360_internal_admin_alerts(org_id,alert_key,severity,alert_type,title,message,metadata_json)
    values(p_org_id,'critical-deployment-incidents-'||current_date,'critical','deployment','Critical deployment incidents open','One or more critical deployment incidents are open.','{}'::jsonb)
    on conflict(org_id,alert_key) do update set status='open',updated_at=now();
  end if;
  if risk_clients > 0 then
    insert into public.ac360_internal_admin_alerts(org_id,alert_key,severity,alert_type,title,message,metadata_json)
    values(p_org_id,'at-risk-clients-'||current_date,'warning','client_success','At-risk clients detected','One or more portfolio accounts are at risk.','{}'::jsonb)
    on conflict(org_id,alert_key) do update set status='open',updated_at=now();
  end if;
  return jsonb_build_object('ok',true,'snapshotId',snap_id,'activeClients',active_clients,'atRiskClients',risk_clients,'openSupportTickets',open_tickets,'criticalIncidents',critical_incidents,'activeCityMarkets',active_cities,'activeExpansionCampaigns',active_campaigns,'pendingInternalTasks',pending_tasks);
end $$;


--
-- Name: ac360_internal_create_admin_task(uuid, uuid, text, text, text, text, timestamp with time zone, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
