--
-- Name: ac360_phase2u_final_lock_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_phase2u_final_lock_dashboard(p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.ac360_phase2u_resolve_org(p_org_id);
begin
  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2u',
    'backendOnly', true,
    'uiBuildAllowed', false,
    'requiresUserUiInstructions', true,
    'latestSqlSweep', (select to_jsonb(s) from public.ac360_phase2u_sql_compatibility_sweeps s where s.org_id=v_org_id order by created_at desc limit 1),
    'latestBackendLock', (select to_jsonb(l) from public.ac360_phase2u_final_backend_locks l where l.org_id=v_org_id order by created_at desc limit 1),
    'releaseManifest', (select to_jsonb(m) from public.ac360_phase2u_release_manifests m where m.org_id=v_org_id order by created_at desc limit 1),
    'preUiHandoff', (select to_jsonb(h) from public.ac360_phase2u_pre_ui_handoffs h where h.org_id=v_org_id order by created_at desc limit 1),
    'openAlerts', coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from public.ac360_phase2u_alerts a where a.org_id=v_org_id and a.status in ('open','acknowledged')), '[]'::jsonb),
    'requiredNextStep', 'Stop backend generation and collect user visual/UX instructions before any UI/front-end build.'
  );
end $$;


--
-- Name: ac360_phase2u_resolve_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_phase2u_resolve_org(p_org_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    p_org_id,
    (select id from public.ac360_organizations order by created_at asc limit 1)
  )

$$;


--
-- Name: ac360_reconcile_lifecycle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_reconcile_lifecycle(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_sub public.ac360_subscriptions%rowtype;
  v_wallet public.ac360_credit_wallets%rowtype;
  v_overdue_count integer := 0;
  v_open_recommendations integer := 0;
begin
  select * into v_sub from public.ac360_subscriptions
  where org_id = p_org_id and status in ('trial','active','grace','past_due','restricted')
  order by case status when 'active' then 1 when 'trial' then 2 when 'grace' then 3 else 4 end, created_at desc limit 1;

  select * into v_wallet from public.ac360_credit_wallets where org_id = p_org_id and wallet_key = 'main' limit 1;

  select count(*) into v_overdue_count
  from public.ac360_invoices
  where org_id = p_org_id and status in ('issued','sent','partial','overdue') and amount_due_mad > 0 and due_date < current_date;

  if v_overdue_count > 0 then
    insert into public.ac360_restrictions(org_id, subscription_id, restriction_key, status, severity, restriction_type, behavior, reason, metadata_json)
    values (p_org_id, v_sub.id, 'payment_overdue', 'active', 'critical', 'billing', 'admin_only', 'Invoice overdue. Account should be restricted to admin/billing actions until payment is resolved.', jsonb_build_object('overdue_count',v_overdue_count))
    on conflict (org_id, restriction_key, target_feature_key, target_action_key, status) do update set reason = excluded.reason, metadata_json = excluded.metadata_json, updated_at = now();
  end if;

  if v_wallet.id is not null and v_wallet.monthly_included_allowance > 0 and v_wallet.balance <= v_wallet.monthly_included_allowance * 0.30 then
    insert into public.ac360_recommendations(org_id, subscription_id, recommendation_key, status, priority, title, message, recommended_bundle_key, trigger_json)
    values (p_org_id, v_sub.id, 'credits_low_serenite_plus', 'open', case when v_wallet.balance <= 0 then 'critical' else 'high' end,
            'AngelCare Credits are low', 'Usage is approaching the package allowance. Recommend a top-up or Sérénité bundle for predictable monthly comfort.', 'serenite_plus', jsonb_build_object('balance',v_wallet.balance,'allowance',v_wallet.monthly_included_allowance))
    on conflict do nothing;
  end if;

  select count(*) into v_open_recommendations from public.ac360_recommendations where org_id = p_org_id and status = 'open';

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-41', 'lifecycle.reconciled', 'lifecycle.reconcile', 'organization', p_org_id, 'success', 'info', null, null, jsonb_build_object('overdue_count',v_overdue_count,'open_recommendations',v_open_recommendations,'wallet_balance',coalesce(v_wallet.balance,0)));

  return jsonb_build_object('ok', true, 'overdueCount', v_overdue_count, 'openRecommendations', v_open_recommendations, 'walletBalance', coalesce(v_wallet.balance,0));
end;
$$;


--
-- Name: ac360_reconcile_policy_safety(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_reconcile_policy_safety(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_blocked_count int := 0;
  v_missing_count int := 0;
  v_restriction_count int := 0;
  v_event_count int := 0;
begin
  update public.ac360_policy_override_requests
     set status='expired', updated_at=now()
   where org_id = p_org_id and status in ('requested','approved') and expires_at is not null and expires_at <= now();

  select count(*) into v_blocked_count
  from public.ac360_guard_decisions
  where org_id = p_org_id and allowed = false and created_at >= now() - interval '7 days';

  select count(*) into v_restriction_count
  from public.ac360_restrictions
  where org_id = p_org_id and status='active';

  select count(*) into v_missing_count
  from public.ac360_route_coverage_audits
  where coverage_status in ('missing','expected') and enforcement_mode = 'strict';

  if v_blocked_count >= 3 then
    perform public.ac360_create_policy_event(p_org_id, null, 'policy.blocked_volume.warning', null, null, null, null, null, 'warning', 'open', 'Multiple blocked AC360 actions detected in the last 7 days. Review billing restrictions, credits, entitlements and add-ons.', null, null, jsonb_build_object('blocked_count',v_blocked_count));
    v_event_count := v_event_count + 1;
  end if;

  if v_restriction_count > 0 then
    perform public.ac360_create_policy_event(p_org_id, null, 'policy.active_restrictions.notice', null, null, null, null, null, 'warning', 'open', 'Active AC360 restrictions exist and must be resolved or intentionally maintained.', null, null, jsonb_build_object('restriction_count',v_restriction_count));
    v_event_count := v_event_count + 1;
  end if;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-41', 'policy.safety.reconciled', 'policy.safety_reconcile', 'policy_safety', p_org_id, 'success', 'notice', null, null, jsonb_build_object('blocked_count',v_blocked_count,'restriction_count',v_restriction_count,'missing_coverage_count',v_missing_count,'event_count',v_event_count));

  return jsonb_build_object('ok',true,'blocked_count',v_blocked_count,'restriction_count',v_restriction_count,'missing_coverage_count',v_missing_count,'event_count',v_event_count);
end;
$$;


--
-- Name: ac360_record_audit(uuid, text, text, text, text, uuid, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_record_audit(p_org_id uuid, p_engine_code text, p_event_code text, p_action_key text DEFAULT NULL::text, p_resource_type text DEFAULT NULL::text, p_resource_id uuid DEFAULT NULL::uuid, p_result text DEFAULT 'success'::text, p_severity text DEFAULT 'info'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_actor_email text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid;
begin
  insert into public.ac360_audit_logs(org_id, actor_app_user_id, actor_email, engine_code, event_code, action_key, resource_type, resource_id, result, severity, metadata_json)
  values (p_org_id, p_actor_app_user_id, p_actor_email, p_engine_code, p_event_code, p_action_key, p_resource_type, p_resource_id, p_result, p_severity, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: ac360_record_phase2_hardening_event(uuid, text, text, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_record_phase2_hardening_event(p_org_id uuid, p_event_type text, p_title text, p_message text DEFAULT NULL::text, p_severity text DEFAULT 'medium'::text, p_module_key text DEFAULT NULL::text, p_action_key text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_key text := 'PH2S-HARDEN-' || to_char(now(),'YYYYMMDDHH24MISSMS');
begin
  insert into public.ac360_phase2_hardening_events(org_id,event_key,event_type,severity,status,title,message,module_key,action_key,evidence_json,created_by,metadata_json)
  values(p_org_id,v_key,coalesce(nullif(p_event_type,''),'hardening'),coalesce(nullif(p_severity,''),'medium'),'open',coalesce(nullif(p_title,''),'Phase 2 hardening event'),p_message,p_module_key,p_action_key,coalesce(p_metadata,'{}'::jsonb),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning id into v_id;
  return jsonb_build_object('ok',true,'event_id',v_id,'event_key',v_key);
end $$;


--
-- Name: ac360_record_phase2t_deployment_repair(uuid, text, text, text, text, text, text, boolean, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_record_phase2t_deployment_repair(p_org_id uuid DEFAULT NULL::uuid, p_repair_type text DEFAULT 'typescript'::text, p_title text DEFAULT 'Phase 2T repair'::text, p_description text DEFAULT NULL::text, p_affected_file text DEFAULT NULL::text, p_affected_route text DEFAULT NULL::text, p_affected_action_key text DEFAULT NULL::text, p_verified boolean DEFAULT false, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_key text := 'phase2t-repair-' || coalesce(p_org_id::text,'global') || '-' || regexp_replace(lower(coalesce(p_repair_type,'custom')), '[^a-z0-9]+', '-', 'g') || '-' || substr(md5(coalesce(p_title,'repair')||coalesce(p_affected_file,'')||coalesce(p_affected_route,'')),1,10);
begin
  insert into public.ac360_phase2t_deployment_repairs(org_id,repair_key,repair_type,status,severity,title,description,affected_file,affected_route,affected_action_key,verified,verified_at,created_by,metadata_json)
  values(p_org_id,v_key,coalesce(p_repair_type,'custom'),case when p_verified then 'verified' else 'recorded' end,'medium',coalesce(p_title,'Phase 2T repair'),p_description,p_affected_file,p_affected_route,p_affected_action_key,coalesce(p_verified,false),case when p_verified then now() else null end,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,repair_key) do update set
    repair_type=excluded.repair_type,
    status=excluded.status,
    title=excluded.title,
    description=excluded.description,
    affected_file=excluded.affected_file,
    affected_route=excluded.affected_route,
    affected_action_key=excluded.affected_action_key,
    verified=excluded.verified,
    verified_at=excluded.verified_at,
    metadata_json=public.ac360_phase2t_deployment_repairs.metadata_json||excluded.metadata_json,
    updated_at=now()
  returning id into v_id;

  return jsonb_build_object('ok',true,'repairId',v_id,'repairKey',v_key,'verified',coalesce(p_verified,false));
end;
$$;


--
-- Name: ac360_record_usage(uuid, text, numeric, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_record_usage(p_org_id uuid, p_meter_key text, p_quantity numeric DEFAULT 1, p_feature_key text DEFAULT NULL::text, p_action_key text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_meter record;
  v_sub uuid;
  v_event uuid;
  v_existing uuid;
  v_period_start date := date_trunc('month', now())::date;
  v_period_end date := (date_trunc('month', now()) + interval '1 month - 1 day')::date;
  v_credits numeric := 0;
  v_amount numeric := 0;
  v_qty numeric := greatest(coalesce(p_quantity, 1), 0);
  v_wallet public.ac360_credit_wallets%rowtype;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  if p_meter_key is null then raise exception 'p_meter_key is required'; end if;

  select * into v_meter from public.ac360_usage_meters where meter_key = p_meter_key and status = 'active';
  if v_meter.meter_key is null then
    raise exception 'Unknown or inactive AC360 meter: %', p_meter_key;
  end if;

  if p_idempotency_key is not null then
    select id into v_existing
    from public.ac360_usage_events
    where org_id = p_org_id and meter_key = p_meter_key and idempotency_key = p_idempotency_key
    limit 1;
    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  select id into v_sub
  from public.ac360_subscriptions
  where org_id = p_org_id and status in ('trial','active','grace','past_due','restricted')
  order by case status when 'active' then 1 when 'trial' then 2 when 'grace' then 3 else 4 end, created_at desc
  limit 1;

  v_credits := coalesce(v_meter.default_credit_cost, 0) * v_qty;
  v_amount := coalesce(v_meter.default_unit_price_mad, 0) * v_qty;

  if v_credits > 0 then
    insert into public.ac360_credit_wallets(org_id, wallet_key, credit_type, status, balance, monthly_included_allowance, rollover_policy)
    values (p_org_id, 'main', 'angelcare_credits', 'active', 0, 0, 'no_rollover')
    on conflict (org_id, wallet_key) do update set updated_at = now()
    returning * into v_wallet;

    if v_wallet.balance < v_credits then
      insert into public.ac360_restrictions(org_id, subscription_id, restriction_key, status, severity, restriction_type, target_feature_key, target_action_key, target_meter_key, behavior, reason, metadata_json)
      values (p_org_id, v_sub, 'credits_exhausted_' || p_meter_key, 'active', 'critical', 'usage', p_feature_key, p_action_key, p_meter_key, 'topup_required', 'Insufficient AngelCare Credits for ' || p_meter_key || '.', jsonb_build_object('required_credits',v_credits,'wallet_balance',v_wallet.balance))
      on conflict (org_id, restriction_key, target_feature_key, target_action_key, status) do update set reason = excluded.reason, metadata_json = excluded.metadata_json, updated_at = now();
      perform public.ac360_record_audit(p_org_id, 'AC360-ENG-37', 'usage.blocked.insufficient_credits', p_action_key, 'credit_wallet', v_wallet.id, 'blocked', 'critical', p_actor_app_user_id, null, jsonb_build_object('meter_key',p_meter_key,'required_credits',v_credits,'balance',v_wallet.balance));
      raise exception 'Insufficient AngelCare Credits: required %, available %', v_credits, v_wallet.balance;
    end if;
  end if;

  insert into public.ac360_usage_events(org_id, subscription_id, meter_key, feature_key, action_key, actor_app_user_id, quantity, credits_consumed, amount_mad, period_start, period_end, idempotency_key, metadata_json)
  values (p_org_id, v_sub, p_meter_key, p_feature_key, p_action_key, p_actor_app_user_id, v_qty, v_credits, v_amount, v_period_start, v_period_end, p_idempotency_key, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_event;

  insert into public.ac360_usage_summaries(org_id, subscription_id, meter_key, period_start, period_end, quantity, credits_consumed, amount_mad, updated_at)
  values (p_org_id, v_sub, p_meter_key, v_period_start, v_period_end, v_qty, v_credits, v_amount, now())
  on conflict (org_id, meter_key, period_start, period_end)
  do update set quantity = public.ac360_usage_summaries.quantity + excluded.quantity,
                credits_consumed = public.ac360_usage_summaries.credits_consumed + excluded.credits_consumed,
                amount_mad = public.ac360_usage_summaries.amount_mad + excluded.amount_mad,
                updated_at = now();

  if v_credits > 0 then
    update public.ac360_credit_wallets
    set balance = balance - v_credits,
        status = case when balance - v_credits <= 0 then 'exhausted' else 'active' end,
        updated_at = now()
    where id = v_wallet.id
    returning * into v_wallet;

    insert into public.ac360_credit_ledger(wallet_id, org_id, ledger_type, amount, balance_after, usage_event_id, reason, idempotency_key, metadata_json)
    values (v_wallet.id, p_org_id, 'consume', -v_credits, v_wallet.balance, v_event, 'Usage consumed by ' || p_meter_key, coalesce(p_idempotency_key, v_event::text), jsonb_build_object('meter_key',p_meter_key,'quantity',v_qty));
  end if;

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-33', 'usage.recorded', p_action_key, 'usage_event', v_event, 'success', 'info', p_actor_app_user_id, null, jsonb_build_object('meter_key', p_meter_key, 'quantity', v_qty, 'credits', v_credits, 'amount_mad', v_amount));
  return v_event;
end;
$$;


--
-- Name: ac360_refresh_phase2_coverage_matrix(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_refresh_phase2_coverage_matrix(p_org_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_modules integer;
  v_actions integer;
begin
  update public.ac360_phase2_module_coverage_matrix
  set coverage_status = 'covered', updated_at = now()
  where phase_code like 'phase_2%'
    and not exists (
      select 1 from unnest(required_tables) t where to_regclass('public.'||t) is null
    );

  update public.ac360_phase2_module_coverage_matrix
  set coverage_status = 'partial', updated_at = now()
  where phase_code like 'phase_2%'
    and exists (
      select 1 from unnest(required_tables) t where to_regclass('public.'||t) is null
    );

  select count(*) into v_modules from public.ac360_phase2_module_coverage_matrix where phase_code like 'phase_2%';
  select count(*) into v_actions from public.ac360_app_action_wiring where status='active' and enforcement_mode='strict';

  insert into public.ac360_phase2_hardening_events(org_id,event_key,event_type,severity,status,title,message,module_key,evidence_json,created_by,metadata_json)
  values(p_org_id,'PH2S-COVERAGE-REFRESH-'||to_char(now(),'YYYYMMDDHH24MISSMS'),'coverage','medium','resolved','Phase 2 coverage matrix refreshed','Coverage matrix refreshed from database state.','phase2_runtime_qa_pre_ui_gate',jsonb_build_object('modules',v_modules,'strict_wiring',v_actions),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,event_key) do nothing;

  return jsonb_build_object('ok',true,'modules',v_modules,'strict_wiring',v_actions,'uiBuildAllowed',false);
end $$;


--
-- Name: ac360_request_policy_override(uuid, text, text, uuid, text, text, text, numeric, text, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_request_policy_override(p_org_id uuid, p_action_key text, p_reason text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_feature_key text DEFAULT NULL::text, p_meter_key text DEFAULT NULL::text, p_route_path text DEFAULT NULL::text, p_quantity numeric DEFAULT 1, p_requested_behavior text DEFAULT 'single_action_override'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_guard_decision_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_id uuid;
  v_status text := 'requested';
  v_expires timestamptz := coalesce(p_expires_at, now() + interval '24 hours');
begin
  if p_org_id is null then
    return jsonb_build_object('ok',false,'error','org_id is required.');
  end if;
  if coalesce(nullif(p_reason,''),'') = '' then
    return jsonb_build_object('ok',false,'error','Override reason is required.');
  end if;

  insert into public.ac360_policy_override_requests(org_id, actor_app_user_id, action_key, feature_key, meter_key, route_path, quantity, requested_behavior, reason, status, expires_at, guard_decision_id, metadata_json)
  values (p_org_id, p_actor_app_user_id, nullif(p_action_key,''), nullif(p_feature_key,''), nullif(p_meter_key,''), nullif(p_route_path,''), coalesce(p_quantity,1), coalesce(nullif(p_requested_behavior,''),'single_action_override'), p_reason, v_status, v_expires, p_guard_decision_id, coalesce(p_metadata,'{}'::jsonb))
  returning id into v_id;

  perform public.ac360_create_policy_event(p_org_id, p_actor_app_user_id, 'policy.override.requested', p_action_key, p_feature_key, p_meter_key, p_route_path, null, 'warning', 'open', 'Policy override requested: ' || p_reason, p_guard_decision_id, v_id, coalesce(p_metadata,'{}'::jsonb));
  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-27', 'policy.override.requested', p_action_key, 'policy_override_request', v_id, 'success', 'warning', p_actor_app_user_id, null, jsonb_build_object('expires_at',v_expires,'route_path',p_route_path));

  return jsonb_build_object('ok',true,'override_request_id',v_id,'status',v_status,'expires_at',v_expires);
end;
$$;


--
-- Name: ac360_resolve_phase2_runtime_alert(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_resolve_phase2_runtime_alert(p_org_id uuid, p_alert_id uuid DEFAULT NULL::uuid, p_alert_key text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  update public.ac360_phase2_runtime_alerts
  set status='resolved', resolved_at=now(), resolved_by=p_actor_app_user_id, metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now()
  where org_id=p_org_id and status in ('open','acknowledged') and (id=p_alert_id or alert_key=p_alert_key);
  get diagnostics v_count = row_count;
  return jsonb_build_object('ok',true,'resolved_count',v_count);
end $$;


--
-- Name: ac360_resolve_phase2t_alert(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_resolve_phase2t_alert(p_org_id uuid DEFAULT NULL::uuid, p_alert_id uuid DEFAULT NULL::uuid, p_alert_key text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  update public.ac360_phase2t_alerts
  set status='resolved', resolved_at=now(), resolved_by=p_actor_app_user_id, metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb), updated_at=now()
  where (p_org_id is null or org_id=p_org_id)
    and (p_alert_id is not null and id=p_alert_id or p_alert_id is null and p_alert_key is not null and alert_key=p_alert_key)
  returning id into v_id;

  return jsonb_build_object('ok',v_id is not null,'alertId',v_id,'status',case when v_id is null then 'not_found' else 'resolved' end);
end;
$$;


--
-- Name: ac360_resolve_phase2u_alert(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_resolve_phase2u_alert(p_org_id uuid DEFAULT NULL::uuid, p_alert_id uuid DEFAULT NULL::uuid, p_alert_key text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_resolution_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.ac360_phase2u_resolve_org(p_org_id);
  v_id uuid;
begin
  update public.ac360_phase2u_alerts
  set status='resolved',resolved_at=now(),resolved_by=p_actor_id,metadata_json=metadata_json||jsonb_build_object('resolutionNote',p_resolution_note),updated_at=now()
  where org_id=v_org_id
    and (p_alert_id is null or id=p_alert_id)
    and (p_alert_key is null or alert_key=p_alert_key)
    and status <> 'resolved'
  returning id into v_id;

  return jsonb_build_object('ok', true, 'resolvedId', v_id, 'phase', 'phase_2u');
end $$;


--
-- Name: ac360_resolve_policy_safety(uuid, text, text, text, text, text, numeric, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_resolve_policy_safety(p_org_id uuid, p_action_key text, p_feature_key text DEFAULT NULL::text, p_meter_key text DEFAULT NULL::text, p_route_path text DEFAULT NULL::text, p_http_method text DEFAULT NULL::text, p_quantity numeric DEFAULT 1, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_action record;
  v_lock record;
  v_restriction record;
  v_override record;
  v_wiring record;
  v_reason text;
  v_source text := 'policy';
  v_event jsonb;
begin
  if p_org_id is null then
    return jsonb_build_object('ok',false,'allowed',false,'decision','organization_required','reason','AC360 policy safety requires an organization.','guard_stage','policy_context','failsafe','fail_closed');
  end if;
  if coalesce(nullif(p_action_key,''),'') = '' then
    return jsonb_build_object('ok',false,'allowed',false,'decision','action_required','reason','AC360 policy safety requires action_key.','guard_stage','policy_validation','failsafe','fail_closed');
  end if;

  select ar.*, fr.feature_key as resolved_feature_key
    into v_action
  from public.ac360_action_registry ar
  left join public.ac360_feature_registry fr on fr.feature_key = ar.feature_key
  where ar.action_key = p_action_key
  limit 1;

  if v_action.action_key is null then
    v_reason := 'Action is not registered. Phase 1E safety lock fails closed until action registry and route wiring are complete.';
    v_event := public.ac360_create_policy_event(p_org_id, p_actor_app_user_id, 'policy.unknown_action.blocked', p_action_key, p_feature_key, p_meter_key, p_route_path, p_http_method, 'critical', 'open', v_reason, null, null, coalesce(p_metadata,'{}'::jsonb));
    return jsonb_build_object('ok',false,'allowed',false,'decision','unknown_action','reason',v_reason,'guard_stage','policy_action_registry','failsafe','fail_closed','event',v_event);
  end if;

  if p_route_path is not null then
    select * into v_wiring
    from public.ac360_app_action_wiring
    where route_path = p_route_path
      and http_method = coalesce(p_http_method, http_method)
      and action_key = p_action_key
      and status = 'active'
    limit 1;

    if v_wiring.id is null then
      perform public.ac360_create_policy_event(p_org_id, p_actor_app_user_id, 'policy.route_wiring.warning', p_action_key, coalesce(p_feature_key, v_action.feature_key), coalesce(p_meter_key, v_action.meter_key), p_route_path, p_http_method, 'warning', 'open', 'Route/action wiring is missing or inactive for this execution path.', null, null, coalesce(p_metadata,'{}'::jsonb));
    end if;
  end if;

  select * into v_override
  from public.ac360_policy_override_requests
  where org_id = p_org_id
    and status = 'approved'
    and (expires_at is null or expires_at > now())
    and (action_key is null or action_key = p_action_key)
    and (feature_key is null or feature_key = coalesce(p_feature_key, v_action.feature_key))
  order by created_at desc
  limit 1;

  if v_override.id is not null then
    perform public.ac360_record_audit(p_org_id, 'AC360-ENG-27', 'policy.override.applied', p_action_key, 'policy_override_request', v_override.id, 'success', 'notice', p_actor_app_user_id, null, jsonb_build_object('route_path',p_route_path,'quantity',p_quantity));
    return jsonb_build_object('ok',true,'allowed',true,'decision','override_allowed','reason','Approved AC360 policy override is active for this action.','guard_stage','policy_override','overrideRequestId',v_override.id,'failsafe','override');
  end if;

  select * into v_restriction
  from public.ac360_restrictions r
  where r.org_id = p_org_id
    and r.status = 'active'
    and r.behavior in ('block','suspend','read_only')
    and (
      r.target_action_key = p_action_key
      or r.target_feature_key = coalesce(p_feature_key, v_action.feature_key)
      or r.target_meter_key = coalesce(p_meter_key, v_action.meter_key)
      or r.restriction_type in ('account','subscription','billing')
    )
  order by case r.severity when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end, r.created_at desc
  limit 1;

  if v_restriction.id is not null then
    v_reason := coalesce(v_restriction.reason, 'Active AC360 restriction blocks this action.');
    v_event := public.ac360_create_policy_event(p_org_id, p_actor_app_user_id, 'policy.restriction.blocked', p_action_key, coalesce(p_feature_key, v_action.feature_key), coalesce(p_meter_key, v_action.meter_key), p_route_path, p_http_method, 'critical', 'open', v_reason, null, null, jsonb_build_object('restriction_id',v_restriction.id,'restriction_key',v_restriction.restriction_key) || coalesce(p_metadata,'{}'::jsonb));
    return jsonb_build_object('ok',false,'allowed',false,'decision','billing_restricted','reason',v_reason,'guard_stage','policy_restriction','restrictionId',v_restriction.id,'failsafe','fail_closed','event',v_event);
  end if;

  select * into v_lock
  from public.ac360_policy_locks l
  where l.status = 'active'
    and (
      (l.target_action_key is not null and l.target_action_key = p_action_key)
      or (l.target_feature_key is not null and l.target_feature_key = coalesce(p_feature_key, v_action.feature_key))
      or (l.target_meter_key is not null and l.target_meter_key = coalesce(p_meter_key, v_action.meter_key))
    )
  order by case l.severity when 'critical' then 1 when 'warning' then 2 else 3 end, l.sort_order asc
  limit 1;

  if v_lock.id is not null and v_lock.behavior in ('block','suspend','read_only','require_override') then
    v_reason := coalesce(v_lock.title, 'AC360 policy lock requires review before execution.');
    v_event := public.ac360_create_policy_event(p_org_id, p_actor_app_user_id, 'policy.lock.blocked', p_action_key, coalesce(p_feature_key, v_action.feature_key), coalesce(p_meter_key, v_action.meter_key), p_route_path, p_http_method, case when v_lock.severity='critical' then 'critical' else 'warning' end, 'open', v_reason, null, null, jsonb_build_object('lock_key',v_lock.lock_key,'override_allowed',v_lock.override_allowed,'failsafe_mode',v_lock.failsafe_mode) || coalesce(p_metadata,'{}'::jsonb));
    return jsonb_build_object('ok',false,'allowed',false,'decision','policy_locked','reason',v_reason,'guard_stage','policy_lock','policyLockKey',v_lock.lock_key,'overrideAllowed',v_lock.override_allowed,'failsafe',v_lock.failsafe_mode,'event',v_event);
  end if;

  return jsonb_build_object('ok',true,'allowed',true,'decision','policy_clear','reason','Phase 1E policy safety check passed. Continue to subscription, entitlement, usage, credits and audit guard.','guard_stage','policy_clear','failsafe','checked');
end;
$$;


--
-- Name: ac360_run_foundation_qa(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_run_foundation_qa(p_org_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_run_key text := 'AC360-QA-' || to_char(now(),'YYYYMMDDHH24MISSMS') || '-' || substr(gen_random_uuid()::text,1,8);
  v_required_tables text[] := array[
    'ac360_organizations','ac360_campuses','ac360_legal_profiles','ac360_academic_years',
    'ac360_user_memberships','ac360_permissions','ac360_roles','ac360_role_permissions','ac360_user_role_assignments','ac360_audit_logs',
    'ac360_foundation_engines','ac360_feature_registry','ac360_action_registry','ac360_plans','ac360_plan_versions','ac360_plan_entitlements',
    'ac360_addons','ac360_addon_entitlements','ac360_serenite_bundles','ac360_professional_services_catalog',
    'ac360_subscriptions','ac360_subscription_items','ac360_quotes','ac360_contracts','ac360_invoices','ac360_invoice_lines','ac360_payments',
    'ac360_usage_meters','ac360_usage_events','ac360_usage_summaries','ac360_credit_wallets','ac360_credit_ledger','ac360_capacity_snapshots',
    'ac360_trials','ac360_grace_periods','ac360_restriction_rules','ac360_restrictions','ac360_recommendations','ac360_automation_rules',
    'ac360_guard_decisions','ac360_app_action_wiring','ac360_policy_locks','ac360_policy_override_requests','ac360_policy_events','ac360_route_coverage_audits','ac360_blocked_action_messages',
    'ac360_foundation_qa_runs','ac360_foundation_qa_results','ac360_foundation_gate_matrix','ac360_engine_coverage_matrix','ac360_deployment_gates','ac360_deployment_gate_events'
  ];
  v_missing text[];
  v_count bigint;
  v_total integer;
  v_passed integer;
  v_warning integer;
  v_failed integer;
  v_skipped integer;
  v_critical integer;
  v_score numeric;
  v_gate_status text;
  v_has_org boolean := false;
  v_has_sub boolean := false;
  v_has_wallet boolean := false;
  v_missing_coverage bigint := 0;
  v_ready_gates integer := 0;
  v_gate_total integer := 0;
begin
  insert into public.ac360_foundation_qa_runs(run_key, org_id, actor_app_user_id, metadata_json)
  values (v_run_key, p_org_id, p_actor_app_user_id, coalesce(p_metadata, '{}'::jsonb))
  returning id into v_run_id;

  select array_agg(tbl order by tbl) into v_missing
  from unnest(v_required_tables) as tbl
  where to_regclass('public.' || tbl) is null;

  perform public.ac360_add_qa_result(
    v_run_id, p_org_id, 'phase1.required_tables', 'database', 'critical',
    case when coalesce(array_length(v_missing,1),0) = 0 then 'passed' else 'failed' end,
    'Phase 1 required database tables exist',
    'Checks Phase 1A-1F tables required by billing, guard, policy and deployment gate.',
    array_length(v_required_tables,1)::text || ' tables',
    (array_length(v_required_tables,1) - coalesce(array_length(v_missing,1),0))::text || ' present',
    'Apply missing AC360 migrations in sequence before Phase 2.',
    jsonb_build_object('missingTables', coalesce(to_jsonb(v_missing),'[]'::jsonb))
  );

  v_count := public.ac360_count_table('ac360_foundation_engines');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.engine_count','engines','critical',case when v_count >= 52 then 'passed' when v_count >= 44 then 'warning' else 'failed' end,'52-engine doctrine registry','The full AngelCare 360 52-engine doctrine must remain seeded.','52 engines minimum',v_count::text,'Re-run Phase 1 foundation migration seeds.',jsonb_build_object('count',v_count));

  select count(*) into v_count from public.ac360_engine_coverage_matrix where gate_required = true and coverage_status in ('seeded','wired','guarded','policy_locked','qa_locked');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.engine_coverage','engines','critical',case when v_count >= 44 then 'passed' else 'failed' end,'Phase 1 engine coverage matrix locked','All 44 Phase 1 foundation engines must have coverage status before Phase 2.','44 Phase 1 engines covered',v_count::text,'Re-seed ac360_engine_coverage_matrix from foundation engines.',jsonb_build_object('covered',v_count));

  v_count := public.ac360_count_table('ac360_plans');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.plans','billing','critical',case when v_count >= 3 then 'passed' else 'failed' end,'Start / Pro / Command plan catalog','The three smart AC360 packages must exist before entitlement checks.','3 plans minimum',v_count::text,'Re-run pricing plan seeds.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_plan_versions');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.plan_versions','billing','high',case when v_count >= 3 then 'passed' else 'failed' end,'Active plan versions exist','Pricing must be versioned and not hard-coded.','3 active/current versions minimum',v_count::text,'Re-run Phase 1 pricing version seeds.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_feature_registry');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.feature_registry','entitlements','critical',case when v_count >= 10 then 'passed' else 'failed' end,'Feature registry exists','Every serious action must map to a feature/entitlement.','10+ features',v_count::text,'Seed AC360 feature registry.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_action_registry');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.action_registry','entitlements','critical',case when v_count >= 30 then 'passed' when v_count >= 15 then 'warning' else 'failed' end,'Action registry exists','Guardable actions must be registered before route wiring.','30+ actions recommended',v_count::text,'Re-run Phase 1C/1D/1F action registry seeds.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_usage_meters');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.usage_meters','usage','critical',case when v_count >= 7 then 'passed' else 'failed' end,'Usage meters seeded','Credits, messaging, AI, report and storage meters must exist.','7 meters minimum',v_count::text,'Re-run usage meter seeds.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_addons');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.addon_menu','addons','high',case when v_count >= 8 then 'passed' else 'warning' end,'Growth Menu add-ons seeded','Menu monetization must be visible before commercial deployment.','8 add-ons minimum',v_count::text,'Re-run add-on catalog seeds.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_app_action_wiring');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.action_wiring','wiring','critical',case when v_count >= 22 then 'passed' when v_count >= 18 then 'warning' else 'failed' end,'Real app action wiring exists','Serious routes must be wired to AC360 guard contracts.','22+ wired actions after Phase 1F',v_count::text,'Apply Phase 1D and Phase 1F wiring migrations.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_policy_locks');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.policy_locks','policy','critical',case when v_count >= 6 then 'passed' else 'failed' end,'Production policy locks seeded','Fail-closed, override and data-preservation policy locks must exist.','6+ policy locks',v_count::text,'Apply Phase 1E policy migration.',jsonb_build_object('count',v_count));

  v_count := public.ac360_count_table('ac360_blocked_action_messages');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.blocked_ux','policy','high',case when v_count >= 4 then 'passed' else 'warning' end,'Blocked-action UX messages seeded','Blocked actions must explain what happened and what to do next.','4+ blocked messages',v_count::text,'Apply Phase 1E blocked UX seeds.',jsonb_build_object('count',v_count));

  select count(*) into v_missing_coverage from public.ac360_route_coverage_audits where enforcement_mode = 'strict' and coverage_status in ('missing','expected');
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.route_coverage','coverage','critical',case when v_missing_coverage = 0 then 'passed' else 'failed' end,'Strict route coverage is complete','Strict production routes should not remain expected/missing before Phase 2.','0 missing strict routes',v_missing_coverage::text,'Run route coverage scan and wire missing routes.',jsonb_build_object('missingStrictRoutes',v_missing_coverage));

  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.rpc_bootstrap','rpc','critical',case when to_regprocedure('public.ac360_bootstrap_foundation_org(text,text,uuid,text,text,text,text)') is not null then 'passed' else 'failed' end,'Bootstrap RPC exists','Runtime tenant/subscription bootstrap must exist.','RPC present',case when to_regprocedure('public.ac360_bootstrap_foundation_org(text,text,uuid,text,text,text,text)') is not null then 'present' else 'missing' end,'Apply Phase 1B runtime bridge migration.',jsonb_build_object('rpc','ac360_bootstrap_foundation_org'));
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.rpc_guard','rpc','critical',case when to_regprocedure('public.ac360_guard_action(uuid,text,numeric,uuid,text,jsonb,boolean,numeric)') is not null then 'passed' else 'failed' end,'Guard RPC exists','Production actions must pass the guard RPC before execution.','RPC present',case when to_regprocedure('public.ac360_guard_action(uuid,text,numeric,uuid,text,jsonb,boolean,numeric)') is not null then 'present' else 'missing' end,'Apply Phase 1C guard migration.',jsonb_build_object('rpc','ac360_guard_action'));
  perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.rpc_policy','rpc','critical',case when to_regprocedure('public.ac360_resolve_policy_safety(uuid,text,text,text,text,text,numeric,uuid,jsonb)') is not null then 'passed' else 'failed' end,'Policy safety RPC exists','Policy safety must run before the normal guard chain.','RPC present',case when to_regprocedure('public.ac360_resolve_policy_safety(uuid,text,text,text,text,text,numeric,uuid,jsonb)') is not null then 'present' else 'missing' end,'Apply Phase 1E policy migration.',jsonb_build_object('rpc','ac360_resolve_policy_safety'));

  if p_org_id is not null then
    select exists(select 1 from public.ac360_organizations where id = p_org_id and status in ('trial','active','grace','restricted')) into v_has_org;
    select exists(select 1 from public.ac360_subscriptions where org_id = p_org_id and status in ('trial','active','grace','past_due','restricted')) into v_has_sub;
    select exists(select 1 from public.ac360_credit_wallets where org_id = p_org_id and wallet_key = 'main') into v_has_wallet;
    perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.runtime_org','runtime','high',case when v_has_org then 'passed' else 'failed' end,'Organization runtime context resolves','The active organization must be resolvable before deployment.','active/trial/grace/restricted org',case when v_has_org then 'present' else 'missing' end,'Bootstrap or repair AC360 organization.',jsonb_build_object('orgId',p_org_id));
    perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.runtime_subscription','runtime','critical',case when v_has_sub then 'passed' else 'failed' end,'Active subscription resolves','Every tenant must have one active billing subscription context.','subscription present',case when v_has_sub then 'present' else 'missing' end,'Bootstrap or repair AC360 subscription.',jsonb_build_object('orgId',p_org_id));
    perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.runtime_wallet','runtime','high',case when v_has_wallet then 'passed' else 'warning' end,'Main credit wallet exists','Usage and automation credits require a main wallet.','wallet present',case when v_has_wallet then 'present' else 'missing' end,'Grant or bootstrap the main AC360 wallet.',jsonb_build_object('orgId',p_org_id));
  else
    select exists(select 1 from public.ac360_organizations where status in ('trial','active','grace','restricted')) into v_has_org;
    select exists(select 1 from public.ac360_subscriptions where status in ('trial','active','grace','past_due','restricted')) into v_has_sub;
    select exists(select 1 from public.ac360_credit_wallets where wallet_key = 'main') into v_has_wallet;
    perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.runtime_org','runtime','high',case when v_has_org then 'passed' else 'failed' end,'Organization runtime context resolves','At least one AC360 organization must be bootstrapped before deployment.','one active/trial/grace/restricted org',case when v_has_org then 'present' else 'missing' end,'Bootstrap the live AC360 organization from /api/ac360/bootstrap.',jsonb_build_object('orgId',null,'globalCheck',true));
    perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.runtime_subscription','runtime','critical',case when v_has_sub then 'passed' else 'failed' end,'Active subscription resolves','At least one AC360 subscription context must exist before deployment.','one subscription present',case when v_has_sub then 'present' else 'missing' end,'Bootstrap or repair AC360 subscription.',jsonb_build_object('orgId',null,'globalCheck',true));
    perform public.ac360_add_qa_result(v_run_id,p_org_id,'phase1.runtime_wallet','runtime','high',case when v_has_wallet then 'passed' else 'warning' end,'Main credit wallet exists','At least one main credit wallet should exist before deployment.','one wallet present',case when v_has_wallet then 'present' else 'missing' end,'Grant or bootstrap the main AC360 wallet.',jsonb_build_object('orgId',null,'globalCheck',true));
  end if;

  select count(*) into v_total from public.ac360_foundation_qa_results where run_id = v_run_id;
  select count(*) into v_passed from public.ac360_foundation_qa_results where run_id = v_run_id and status = 'passed';
  select count(*) into v_warning from public.ac360_foundation_qa_results where run_id = v_run_id and status = 'warning';
  select count(*) into v_failed from public.ac360_foundation_qa_results where run_id = v_run_id and status = 'failed';
  select count(*) into v_skipped from public.ac360_foundation_qa_results where run_id = v_run_id and status = 'skipped';
  select count(*) into v_critical from public.ac360_foundation_qa_results where run_id = v_run_id and status = 'failed' and severity = 'critical';

  v_score := case when v_total = 0 then 0 else round(((v_passed::numeric + (v_warning::numeric * 0.5)) / greatest(v_total - v_skipped,1)::numeric) * 100, 2) end;
  v_gate_status := case when v_critical > 0 or v_score < 85 then 'blocked' when v_score >= 90 and v_failed = 0 then 'ready' else 'blocked' end;

  update public.ac360_foundation_qa_runs
  set status = 'completed', completed_at = now(), total_checks = v_total, passed_checks = v_passed, warning_checks = v_warning, failed_checks = v_failed, skipped_checks = v_skipped, critical_failures = v_critical, readiness_score = v_score, gate_status = v_gate_status, updated_at = now()
  where id = v_run_id;

  update public.ac360_deployment_gates
  set status = case when v_gate_status = 'ready' then 'ready' else 'blocked' end,
      readiness_score = v_score,
      last_run_id = v_run_id,
      blocking_reason = case when v_gate_status = 'ready' then null else 'Phase 1F QA has blocking failures or score below threshold.' end,
      updated_at = now()
  where gate_key in ('phase1.foundation.sql','phase1.foundation.seeds','phase1.billing.entitlements','phase1.guard.policy','phase1.route.coverage','phase1.usage.credits','phase1.audit.traceability','phase1.ui.command','phase2.entry.authorization');

  select count(*) into v_gate_total from public.ac360_deployment_gates where required = true;
  select count(*) into v_ready_gates from public.ac360_deployment_gates where required = true and status in ('ready','waived');

  insert into public.ac360_deployment_gate_events(gate_key, run_id, event_key, status, message, actor_app_user_id, metadata_json)
  values ('phase2.entry.authorization', v_run_id, 'phase1f.qa.completed', case when v_gate_status = 'ready' then 'ready' else 'blocked' end,
          case when v_gate_status = 'ready' then 'Phase 1F QA passed. Phase 2 school operations can start under the AC360 guard doctrine.' else 'Phase 1F QA blocked Phase 2 entry. Review failed checks before building school modules.' end,
          p_actor_app_user_id,
          jsonb_build_object('score',v_score,'criticalFailures',v_critical,'failedChecks',v_failed,'readyGates',v_ready_gates,'totalGates',v_gate_total));

  perform public.ac360_record_audit(p_org_id, 'AC360-ENG-10', 'phase1f.qa.completed', 'qa.foundation_run', 'qa_run', v_run_id, case when v_gate_status='ready' then 'success' else 'blocked' end, case when v_gate_status='ready' then 'info' else 'warning' end, p_actor_app_user_id, null, jsonb_build_object('score',v_score,'gateStatus',v_gate_status,'criticalFailures',v_critical));

  return jsonb_build_object(
    'ok', true,
    'runId', v_run_id,
    'runKey', v_run_key,
    'phase', 'phase_1f_foundation_qa_gate',
    'readinessScore', v_score,
    'gateStatus', v_gate_status,
    'totalChecks', v_total,
    'passedChecks', v_passed,
    'warningChecks', v_warning,
    'failedChecks', v_failed,
    'skippedChecks', v_skipped,
    'criticalFailures', v_critical,
    'phase2Allowed', v_gate_status = 'ready',
    'message', case when v_gate_status = 'ready' then 'Phase 1 foundation is deployment-gated and ready for Phase 2.' else 'Phase 1 foundation is blocked; fix QA failures before Phase 2.' end
  );
exception when others then
  update public.ac360_foundation_qa_runs set status='failed', completed_at=now(), gate_status='blocked', metadata_json = metadata_json || jsonb_build_object('error',sqlerrm), updated_at=now() where id = v_run_id;
  return jsonb_build_object('ok', false, 'runId', v_run_id, 'gateStatus','blocked','error', sqlerrm);
end;
$$;


--
-- Name: ac360_run_phase2_integrity(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_run_phase2_integrity(p_org_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run jsonb;
  v_run_id uuid;
  v_open_findings integer;
begin
  v_run := public.ac360_run_phase2_runtime_qa(p_org_id,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb) || '{"integrityRun":true}'::jsonb);
  v_run_id := (v_run->>'run_id')::uuid;
  select count(*) into v_open_findings from public.ac360_phase2_integrity_findings where org_id = p_org_id and status = 'open';
  return v_run || jsonb_build_object('integrity_findings_open',v_open_findings);
end $$;


--
-- Name: ac360_run_phase2_runtime_qa(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_run_phase2_runtime_qa(p_org_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_run_key text := 'PH2S-QA-' || to_char(now(),'YYYYMMDDHH24MISSMS');
  m record;
  t text;
  a text;
  v_exists boolean;
  v_total integer := 0;
  v_passed integer := 0;
  v_failed integer := 0;
  v_warning integer := 0;
  v_critical integer := 0;
  v_score numeric(5,2) := 0;
begin
  insert into public.ac360_phase2_runtime_qa_runs(org_id,run_key,run_type,status,metadata_json,created_by)
  values(p_org_id,v_run_key,'phase2_runtime_qa','running',coalesce(p_metadata,'{}'::jsonb) || '{"phase":"phase_2s","uiBuildAllowed":false}'::jsonb,p_actor_app_user_id)
  returning id into v_run_id;

  for m in select * from public.ac360_phase2_module_coverage_matrix where phase_code like 'phase_2%' order by phase_code, module_key loop
    v_total := v_total + 1;
    perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'module.'||m.module_key,'module_coverage','high','passed','Module registered in Phase 2 coverage matrix.',jsonb_build_object('module_key',m.module_key),jsonb_build_object('phase_code',m.phase_code,'ui_build_status',m.ui_build_status),null);
    v_passed := v_passed + 1;

    if m.ui_build_status <> 'locked' then
      v_total := v_total + 1;
      perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'ui_lock.'||m.module_key,'ui_lock','critical','failed','UI build lock is not strict for module '||m.module_key,jsonb_build_object('expected','locked'),jsonb_build_object('actual',m.ui_build_status),'Reset ui_build_status to locked before pre-UI gate.');
      v_failed := v_failed + 1; v_critical := v_critical + 1;
    else
      v_total := v_total + 1;
      perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'ui_lock.'||m.module_key,'ui_lock','critical','passed','UI build remains locked for module '||m.module_key,jsonb_build_object('expected','locked'),jsonb_build_object('actual',m.ui_build_status),null);
      v_passed := v_passed + 1;
    end if;

    foreach t in array coalesce(m.required_tables,'{}'::text[]) loop
      v_exists := to_regclass('public.' || t) is not null;
      v_total := v_total + 1;
      if v_exists then
        perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'table.'||t,'table_presence','critical','passed','Required table exists: '||t,jsonb_build_object('table',t),jsonb_build_object('exists',true),null);
        v_passed := v_passed + 1;
      else
        perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'table.'||t,'table_presence','critical','failed','Required table missing: '||t,jsonb_build_object('table',t),jsonb_build_object('exists',false),'Apply the missing phase migration or repair table naming compatibility.');
        v_failed := v_failed + 1; v_critical := v_critical + 1;
        insert into public.ac360_phase2_integrity_findings(org_id,run_id,rule_key,module_key,severity,status,message,evidence_json,remediation_hint)
        values(p_org_id,v_run_id,'phase2.required_tables.present',m.module_key,'critical','open','Missing required table '||t,jsonb_build_object('table',t,'module_key',m.module_key),'Apply/re-run the owning migration for '||m.phase_code||'.');
      end if;
    end loop;

    foreach a in array coalesce(m.required_actions,'{}'::text[]) loop
      v_total := v_total + 1;
      select exists(select 1 from public.ac360_action_registry where action_key = a) into v_exists;
      if v_exists then
        perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'action.'||a,'action_registry','critical','passed','Required action registered: '||a,jsonb_build_object('action_key',a),jsonb_build_object('exists',true),null);
        v_passed := v_passed + 1;
      else
        perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'action.'||a,'action_registry','critical','failed','Required action missing from action registry: '||a,jsonb_build_object('action_key',a),jsonb_build_object('exists',false),'Patch action registry seed for the owning phase.');
        v_failed := v_failed + 1; v_critical := v_critical + 1;
      end if;

      v_total := v_total + 1;
      select exists(select 1 from public.ac360_app_action_wiring where action_key = a and status = 'active' and enforcement_mode = 'strict') into v_exists;
      if v_exists then
        perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'wiring.'||a,'action_wiring','critical','passed','Required action has strict app wiring: '||a,jsonb_build_object('action_key',a),jsonb_build_object('strict_wiring',true),null);
        v_passed := v_passed + 1;
      else
        perform public.ac360_phase2_record_qa_result(v_run_id,p_org_id,'wiring.'||a,'action_wiring','critical','failed','Required action missing strict app wiring: '||a,jsonb_build_object('action_key',a),jsonb_build_object('strict_wiring',false),'Patch lib/ac360/action-wiring.ts and ac360_app_action_wiring seeds.');
        v_failed := v_failed + 1; v_critical := v_critical + 1;
      end if;
    end loop;
  end loop;

  v_score := case when v_total = 0 then 0 else round((v_passed::numeric / v_total::numeric) * 100, 2) end;

  update public.ac360_phase2_runtime_qa_runs
  set status = case when v_critical > 0 then 'failed' when v_warning > 0 then 'warning' else 'passed' end,
      readiness_score = v_score,
      critical_failures = v_critical,
      warning_count = v_warning,
      passed_count = v_passed,
      failed_count = v_failed,
      completed_at = now(),
      updated_at = now(),
      summary_json = jsonb_build_object('total_checks',v_total,'passed',v_passed,'failed',v_failed,'critical_failures',v_critical,'warnings',v_warning,'readiness_score',v_score,'uiBuildAllowed',false,'nextGate','phase2_pre_ui_gate')
  where id = v_run_id;

  if v_critical > 0 then
    insert into public.ac360_phase2_runtime_alerts(org_id,alert_key,alert_type,severity,status,module_key,title,message,related_run_id,metadata_json)
    values(p_org_id,'PH2S-QA-CRITICAL-'||v_run_id,'qa','critical','open','phase2_runtime_qa_pre_ui_gate','Phase 2 runtime QA has critical failures','Critical failures must be repaired before any UI build.',v_run_id,jsonb_build_object('critical_failures',v_critical,'readiness_score',v_score))
    on conflict(org_id,alert_key) do nothing;
  end if;

  return jsonb_build_object('ok',true,'run_id',v_run_id,'run_key',v_run_key,'status',case when v_critical > 0 then 'failed' when v_warning > 0 then 'warning' else 'passed' end,'readiness_score',v_score,'critical_failures',v_critical,'warning_count',v_warning,'passed_count',v_passed,'failed_count',v_failed,'uiBuildAllowed',false);
end $$;


--
-- Name: ac360_run_phase2t_api_contract_sweep(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_run_phase2t_api_contract_sweep(p_org_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sweep_id uuid;
  v_sweep_key text := 'phase2t-api-' || coalesce(p_org_id::text,'global') || '-' || extract(epoch from clock_timestamp())::bigint || '-' || substr(gen_random_uuid()::text,1,8);
  v_total int := 0;
  v_failed int := 0;
  v_warning int := 0;
  v_passed int := 0;
  v_strict int := 0;
  v_status text := 'passed';
begin
  insert into public.ac360_phase2t_api_contract_sweeps(org_id,sweep_key,status,metadata_json,created_by)
  values(p_org_id,v_sweep_key,'running',coalesce(p_metadata,'{}'::jsonb),p_actor_app_user_id)
  returning id into v_sweep_id;

  insert into public.ac360_phase2t_api_contract_results(org_id,sweep_id,wiring_key,route_path,http_method,action_key,feature_key,target_module,enforcement_mode,status,severity,message,evidence_json,remediation_hint)
  select p_org_id,
         v_sweep_id,
         w.wiring_key,
         w.route_path,
         w.http_method,
         w.action_key,
         w.feature_key,
         w.target_module,
         w.enforcement_mode,
         case
           when a.action_key is null then 'failed'
           when f.feature_key is null then 'failed'
           when w.enforcement_mode <> 'strict' then 'failed'
           when w.route_path not like '/api/%' then 'warning'
           else 'passed'
         end as status,
         case
           when a.action_key is null or f.feature_key is null or w.enforcement_mode <> 'strict' then 'critical'
           when w.route_path not like '/api/%' then 'medium'
           else 'low'
         end as severity,
         case
           when a.action_key is null then 'Missing action registry row for wiring key.'
           when f.feature_key is null then 'Missing feature registry row for action contract.'
           when w.enforcement_mode <> 'strict' then 'Route contract is not strict.'
           when w.route_path not like '/api/%' then 'Route path is not an API path.'
           else 'Route contract is covered and strict.'
         end as message,
         jsonb_build_object('routePath',w.route_path,'httpMethod',w.http_method,'actionExists',a.action_key is not null,'featureExists',f.feature_key is not null,'enforcementMode',w.enforcement_mode),
         'Repair static action wiring, registry seeds, or route path contract.'
  from public.ac360_app_action_wiring w
  left join public.ac360_action_registry a on a.action_key=w.action_key
  left join public.ac360_feature_registry f on f.feature_key=coalesce(w.feature_key,a.feature_key)
  where w.status='active' and (w.target_module like 'angelcare_360%' or w.target_module like 'email_os%' or w.target_module like 'capital%');

  select count(*),
         count(*) filter(where status in ('failed','blocked')),
         count(*) filter(where status='warning'),
         count(*) filter(where status='passed')
    into v_total,v_failed,v_warning,v_passed
    from public.ac360_phase2t_api_contract_results where sweep_id=v_sweep_id;
  select count(*) into v_strict from public.ac360_phase2t_api_contract_results where sweep_id=v_sweep_id and enforcement_mode='strict';

  v_status := case when v_failed > 0 then 'failed' when v_warning > 0 then 'warning' else 'passed' end;

  update public.ac360_phase2t_api_contract_sweeps
  set status=v_status,total_routes=v_total,covered_routes=v_passed,failed_routes=v_failed,warning_routes=v_warning,strict_routes=v_strict,completed_at=now(),
      summary_json=jsonb_build_object('totalRoutes',v_total,'coveredRoutes',v_passed,'failedRoutes',v_failed,'warningRoutes',v_warning,'strictRoutes',v_strict)
  where id=v_sweep_id;

  if v_failed > 0 then
    insert into public.ac360_phase2t_alerts(org_id,alert_key,alert_type,severity,status,title,message,related_sweep_id,metadata_json)
    values(p_org_id,'phase2t-api-contract-'||v_sweep_id,'api_contract','critical','open','Phase 2T API contract sweep failed','One or more guarded API route contracts failed.',v_sweep_id,jsonb_build_object('sweep_key',v_sweep_key))
    on conflict(org_id,alert_key) do nothing;
  end if;

  return jsonb_build_object('ok',true,'sweepId',v_sweep_id,'sweepKey',v_sweep_key,'status',v_status,'totalRoutes',v_total,'coveredRoutes',v_passed,'failedRoutes',v_failed,'warningRoutes',v_warning,'strictRoutes',v_strict);
end;
$$;


--
-- Name: ac360_run_phase2t_typescript_hardening(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_run_phase2t_typescript_hardening(p_org_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_run_key text := 'phase2t-ts-' || coalesce(p_org_id::text,'global') || '-' || extract(epoch from clock_timestamp())::bigint || '-' || substr(gen_random_uuid()::text,1,8);
  v_route_count int := 0;
  v_missing_actions int := 0;
  v_missing_features int := 0;
  v_non_strict int := 0;
  v_phase2_modules int := 0;
  v_pre_ui_violations int := 0;
  v_failed int := 0;
  v_warning int := 0;
  v_passed int := 0;
  v_score numeric(5,2) := 0;
  v_status text := 'passed';
begin
  insert into public.ac360_phase2t_build_hardening_runs(org_id,run_key,run_type,status,metadata_json,created_by)
  values(p_org_id,v_run_key,'typescript_build_hardening','running',coalesce(p_metadata,'{}'::jsonb),p_actor_app_user_id)
  returning id into v_run_id;

  select count(*) into v_route_count from public.ac360_app_action_wiring where status='active' and (target_module like 'angelcare_360%' or target_module like 'email_os%' or target_module like 'capital%');
  select count(*) into v_missing_actions
    from public.ac360_app_action_wiring w
    left join public.ac360_action_registry a on a.action_key=w.action_key
    where w.status='active' and a.action_key is null;
  select count(*) into v_missing_features
    from public.ac360_action_registry a
    left join public.ac360_feature_registry f on f.feature_key=a.feature_key
    where (a.action_key like 'school.%' or a.action_key like 'phase2.%' or a.action_key like 'internal.%')
      and f.feature_key is null;
  select count(*) into v_non_strict
    from public.ac360_app_action_wiring
    where status='active' and (target_module like 'angelcare_360%' or target_module like 'email_os%' or target_module like 'capital%') and enforcement_mode <> 'strict';
  select count(*) into v_phase2_modules from public.ac360_phase2_module_coverage_matrix where module_key like '%';
  select count(*) into v_pre_ui_violations from public.ac360_phase2_pre_ui_gates where coalesce(ui_build_allowed,false)=true;

  insert into public.ac360_phase2t_build_hardening_results(org_id,run_id,check_key,check_group,severity,status,message,expected_json,actual_json,remediation_hint)
  values
  (p_org_id,v_run_id,'route_contract_minimum','api_contracts','critical',case when v_route_count >= 150 then 'passed' else 'failed' end,'Active guarded route/action wiring count must remain broad enough for Phase 2 nationwide runtime.','{"minimum":150}'::jsonb,jsonb_build_object('actual',v_route_count),'Run missing phase patches or action wiring repair.'),
  (p_org_id,v_run_id,'missing_action_registry','api_contracts','critical',case when v_missing_actions = 0 then 'passed' else 'failed' end,'Every app action wiring row must resolve to an action registry row.','{"missing":0}'::jsonb,jsonb_build_object('actual',v_missing_actions),'Seed missing ac360_action_registry rows.'),
  (p_org_id,v_run_id,'missing_feature_registry','feature_contracts','critical',case when v_missing_features = 0 then 'passed' else 'failed' end,'Every Phase 2/internal action must resolve to a feature registry row.','{"missing":0}'::jsonb,jsonb_build_object('actual',v_missing_features),'Seed missing ac360_feature_registry rows.'),
  (p_org_id,v_run_id,'strict_enforcement','guard_policy','critical',case when v_non_strict = 0 then 'passed' else 'failed' end,'Production AC360 route wiring must stay strict.','{"non_strict":0}'::jsonb,jsonb_build_object('actual',v_non_strict),'Switch action wiring enforcement_mode to strict.'),
  (p_org_id,v_run_id,'phase2_module_coverage','coverage','high',case when v_phase2_modules >= 19 then 'passed' else 'warning' end,'Phase 2 coverage matrix should include Phase 2A through Phase 2S/2T coverage.','{"minimum":19}'::jsonb,jsonb_build_object('actual',v_phase2_modules),'Refresh Phase 2 coverage matrix.'),
  (p_org_id,v_run_id,'ui_build_lock','pre_ui_gate','critical',case when v_pre_ui_violations = 0 then 'passed' else 'failed' end,'UI build must remain locked until user gives UI/UX instructions.','{"ui_build_allowed":false}'::jsonb,jsonb_build_object('violations',v_pre_ui_violations),'Reset pre-UI gate and wait for user visual instructions.');

  select count(*) filter(where status in ('failed','blocked')),
         count(*) filter(where status='warning'),
         count(*) filter(where status='passed')
    into v_failed,v_warning,v_passed
    from public.ac360_phase2t_build_hardening_results where run_id=v_run_id;

  v_score := greatest(0, round(((v_passed::numeric / greatest(v_passed+v_failed+v_warning,1)) * 100)::numeric,2));
  v_status := case when v_failed > 0 then 'failed' when v_warning > 0 then 'warning' else 'passed' end;

  update public.ac360_phase2t_build_hardening_runs
  set status=v_status, readiness_score=v_score, critical_failures=v_failed, warning_count=v_warning, passed_count=v_passed, failed_count=v_failed,
      completed_at=now(), summary_json=jsonb_build_object('route_count',v_route_count,'missing_actions',v_missing_actions,'missing_features',v_missing_features,'non_strict',v_non_strict,'phase2_modules',v_phase2_modules,'ui_build_violations',v_pre_ui_violations)
  where id=v_run_id;

  if v_failed > 0 then
    insert into public.ac360_phase2t_alerts(org_id,alert_key,alert_type,severity,status,title,message,related_run_id,metadata_json)
    values(p_org_id,'phase2t-build-hardening-'||v_run_id,'build_hardening','critical','open','Phase 2T build hardening failed','One or more TypeScript/API contract hardening checks failed.',v_run_id,jsonb_build_object('run_key',v_run_key))
    on conflict(org_id,alert_key) do nothing;
  end if;

  return jsonb_build_object('ok',true,'runId',v_run_id,'runKey',v_run_key,'status',v_status,'readinessScore',v_score,'criticalFailures',v_failed,'warnings',v_warning,'passed',v_passed,'summary',(select summary_json from public.ac360_phase2t_build_hardening_runs where id=v_run_id));
end;
$$;


--
-- Name: ac360_run_phase2u_sql_compatibility_sweep(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_run_phase2u_sql_compatibility_sweep(p_org_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.ac360_phase2u_resolve_org(p_org_id);
  v_sweep_id uuid;
  v_key text := 'phase2u-sql-sweep-' || replace(gen_random_uuid()::text,'-','');
  v_total integer := 0;
  v_passed integer := 0;
  v_failed integer := 0;
  v_warning integer := 0;
  v_critical integer := 0;
  v_status text := 'passed';
  v_score numeric(5,2) := 0;
  t text;
  required_tables text[] := array[
    'ac360_organizations','ac360_app_action_wiring','ac360_action_registry','ac360_feature_registry','ac360_subscriptions','ac360_usage_events','ac360_guard_decisions','ac360_policy_locks',
    'ac360_school_students','ac360_school_guardians','ac360_school_staff','ac360_school_classes','ac360_school_attendance_events','ac360_school_finance_billing_cycles','ac360_school_communication_campaigns',
    'ac360_school_documents','ac360_school_workflow_instances','ac360_school_admission_leads','ac360_school_hr_shift_assignments','ac360_school_incident_reports','ac360_school_transport_routes',
    'ac360_school_parenttrust_complaints','ac360_school_academy_courses','ac360_school_automation_rules','ac360_school_intake_forms','ac360_school_brand_profiles','ac360_school_migration_projects',
    'ac360_internal_support_tickets','ac360_phase2s_pre_ui_gates','ac360_phase2t_deployment_readiness_runs'
  ];
begin
  insert into public.ac360_phase2u_sql_compatibility_sweeps(org_id,sweep_key,status,metadata_json)
  values(v_org_id,v_key,'running',p_metadata)
  returning id into v_sweep_id;

  foreach t in array required_tables loop
    if to_regclass('public.' || t) is null then
      perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'table.'||t,'required_tables',t,'table','failed','critical','Required AC360 runtime table is missing.','Apply missing Phase 1/2 migration before UI work.');
    else
      perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'table.'||t,'required_tables',t,'table','passed','low','Required AC360 runtime table exists.',null,jsonb_build_object('table',t));
    end if;
  end loop;

  -- Compatibility columns that repeatedly protected later phases from schema drift.
  if exists(select 1 from information_schema.columns where table_schema='public' and table_name='ac360_addons' and column_name='family') then
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'column.ac360_addons.family','schema_compatibility','ac360_addons.family','column','passed','low','ac360_addons.family exists.');
  else
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'column.ac360_addons.family','schema_compatibility','ac360_addons.family','column','failed','critical','ac360_addons.family is missing.','Use Phase 1 add-on schema or add a compatibility column.');
  end if;

  if exists(select 1 from information_schema.columns where table_schema='public' and table_name='ac360_app_action_wiring' and column_name='fallback_action_key') then
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'column.ac360_app_action_wiring.fallback_action_key','schema_compatibility','ac360_app_action_wiring.fallback_action_key','column','passed','low','fallback_action_key exists for Phase 1E+ compatibility.');
  else
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'column.ac360_app_action_wiring.fallback_action_key','schema_compatibility','ac360_app_action_wiring.fallback_action_key','column','failed','critical','fallback_action_key is missing.','Apply Phase 1E compatibility hotfix.');
  end if;

  if exists(select 1 from information_schema.columns where table_schema='public' and table_name='ac360_feature_registry' and column_name='billing_family') then
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'column.ac360_feature_registry.billing_family','schema_compatibility','ac360_feature_registry.billing_family','column','passed','low','feature registry billing_family exists.');
  else
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'column.ac360_feature_registry.billing_family','schema_compatibility','ac360_feature_registry.billing_family','column','failed','critical','feature registry billing_family is missing.','Apply Phase 1 feature registry migration.');
  end if;

  if (select count(*) from public.ac360_app_action_wiring where status='active') >= 120 then
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'seed.app_action_wiring.coverage','seed_coverage','ac360_app_action_wiring','seed','passed','low','Strict app-action wiring coverage is broad enough for backend runtime.',null,jsonb_build_object('active_wiring',(select count(*) from public.ac360_app_action_wiring where status='active')));
  else
    perform public.ac360_phase2u_add_sql_result(v_org_id,v_sweep_id,'seed.app_action_wiring.coverage','seed_coverage','ac360_app_action_wiring','seed','failed','critical','Not enough active app-action wiring rows for Phase 2 backend runtime.','Re-apply missing phase migrations.',jsonb_build_object('active_wiring',(select count(*) from public.ac360_app_action_wiring where status='active')));
  end if;

  select count(*),
         count(*) filter (where status='passed'),
         count(*) filter (where status='warning'),
         count(*) filter (where status in ('failed','blocked')),
         count(*) filter (where status in ('failed','blocked') and severity='critical')
    into v_total, v_passed, v_warning, v_failed, v_critical
  from public.ac360_phase2u_sql_compatibility_results
  where sweep_id=v_sweep_id;

  v_score := case when v_total = 0 then 0 else round((v_passed::numeric / v_total::numeric) * 100, 2) end;
  if v_critical > 0 then v_status := 'failed'; elsif v_warning > 0 then v_status := 'warning'; else v_status := 'passed'; end if;

  update public.ac360_phase2u_sql_compatibility_sweeps
  set status=v_status,total_checks=v_total,passed_checks=v_passed,failed_checks=v_failed,warning_checks=v_warning,critical_failures=v_critical,compatibility_score=v_score,completed_at=now(),
      summary_json=jsonb_build_object('phase','phase_2u','total',v_total,'passed',v_passed,'failed',v_failed,'warnings',v_warning,'critical',v_critical,'score',v_score,'uiBuildAllowed',false,'requiresUserUiInstructions',true)
  where id=v_sweep_id;

  if v_critical > 0 then
    insert into public.ac360_phase2u_alerts(org_id,alert_key,alert_type,severity,status,title,message,related_sweep_id,metadata_json)
    values(v_org_id,'phase2u.sql_compatibility.critical.'||v_sweep_id,'sql_compatibility','critical','open','Phase 2U SQL compatibility blockers detected','Critical SQL/schema compatibility failures must be repaired before UI instructions.',v_sweep_id,jsonb_build_object('criticalFailures',v_critical))
    on conflict(org_id,alert_key) do nothing;
  end if;

  return (select to_jsonb(s) from public.ac360_phase2u_sql_compatibility_sweeps s where s.id=v_sweep_id);
end $$;


--
-- Name: ac360_school_academy_create_assignment(uuid, uuid, uuid, uuid, text, boolean, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_academy_create_assignment(p_org_id uuid, p_staff_id uuid DEFAULT NULL::uuid, p_program_id uuid DEFAULT NULL::uuid, p_course_id uuid DEFAULT NULL::uuid, p_assignment_reason text DEFAULT 'manual'::text, p_mandatory boolean DEFAULT true, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_key text;
begin
  v_key := 'ASSIGN-'||to_char(now(),'YYYYMMDDHH24MISS')||'-'||substr(gen_random_uuid()::text,1,6);
  insert into public.ac360_school_academy_training_assignments(org_id,staff_id,program_id,course_id,assignment_key,assignment_reason,mandatory,due_at,created_by,metadata_json)
  values(p_org_id,p_staff_id,p_program_id,p_course_id,v_key,coalesce(p_assignment_reason,'manual'),coalesce(p_mandatory,true),p_due_at,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  return jsonb_build_object('ok',true,'assignmentId',v_id,'assignmentKey',v_key);
end $$;


--
-- Name: ac360_school_academy_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_academy_dashboard(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_programs integer;
  v_courses integer;
  v_sessions integer;
  v_enrollments integer;
  v_completed integer;
  v_certificates integer;
  v_overdue integer;
  v_alerts integer;
begin
  select count(*) into v_programs from public.ac360_school_academy_programs where org_id=p_org_id and status in ('draft','published','paused');
  select count(*) into v_courses from public.ac360_school_academy_courses where org_id=p_org_id and status in ('draft','published','paused');
  select count(*) into v_sessions from public.ac360_school_academy_sessions where org_id=p_org_id and status in ('scheduled','confirmed','in_progress');
  select count(*) into v_enrollments from public.ac360_school_academy_enrollments where org_id=p_org_id and status in ('enrolled','in_progress');
  select count(*) into v_completed from public.ac360_school_academy_enrollments where org_id=p_org_id and status='completed';
  select count(*) into v_certificates from public.ac360_school_academy_certificates where org_id=p_org_id and status='issued';
  select count(*) into v_overdue from public.ac360_school_academy_training_assignments where org_id=p_org_id and status in ('open','in_progress') and due_at is not null and due_at < now();
  select count(*) into v_alerts from public.ac360_school_academy_alerts where org_id=p_org_id and status in ('open','in_progress');

  return jsonb_build_object('ok',true,'asOfDate',coalesce(p_as_of_date,current_date),'programs',v_programs,'courses',v_courses,'activeSessions',v_sessions,'activeEnrollments',v_enrollments,'completedEnrollments',v_completed,'issuedCertificates',v_certificates,'overdueAssignments',v_overdue,'openAlerts',v_alerts,'uiBuildAllowed',false,'phase','phase_2m_academy_training');
end $$;


