CREATE FUNCTION public.ac360_school_academy_resolve_alert(p_org_id uuid, p_alert_id uuid, p_resolution_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
