CREATE FUNCTION public.ac360_school_academy_upsert_assessment(p_org_id uuid, p_assessment_id uuid DEFAULT NULL::uuid, p_course_id uuid DEFAULT NULL::uuid, p_assessment_key text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_assessment_type text DEFAULT 'quiz'::text, p_max_score numeric DEFAULT 100, p_pass_score numeric DEFAULT 60, p_questions_json jsonb DEFAULT '[]'::jsonb, p_status text DEFAULT 'draft'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
