--
-- Name: ac360_school_academy_upsert_course(uuid, uuid, uuid, text, text, text, text, numeric, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_academy_upsert_course(p_org_id uuid, p_course_id uuid DEFAULT NULL::uuid, p_program_id uuid DEFAULT NULL::uuid, p_course_key text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_course_type text DEFAULT 'training'::text, p_level text DEFAULT 'standard'::text, p_duration_hours numeric DEFAULT 0, p_content_json jsonb DEFAULT '{}'::jsonb, p_status text DEFAULT 'draft'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_key text;
begin
  v_key := coalesce(nullif(p_course_key,''),'academy-course-'||substr(gen_random_uuid()::text,1,8));
  insert into public.ac360_school_academy_courses(id,org_id,program_id,course_key,title,course_type,level,duration_hours,content_json,status,created_by,metadata_json)
  values(coalesce(p_course_id,gen_random_uuid()),p_org_id,p_program_id,v_key,coalesce(nullif(p_title,''),'Academy Course'),coalesce(p_course_type,'training'),coalesce(p_level,'standard'),coalesce(p_duration_hours,0),coalesce(p_content_json,'{}'::jsonb),coalesce(p_status,'draft'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,course_key) do update set program_id=excluded.program_id,title=excluded.title,course_type=excluded.course_type,level=excluded.level,duration_hours=excluded.duration_hours,content_json=excluded.content_json,status=excluded.status,metadata_json=public.ac360_school_academy_courses.metadata_json || excluded.metadata_json,updated_at=now()
  returning id into v_id;
  insert into public.ac360_school_academy_events(org_id,event_type,entity_type,entity_id,severity,message,actor_app_user_id,metadata_json) values(p_org_id,'course_upserted','academy_course',v_id,'info','Academy course upserted.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'courseId',v_id,'courseKey',v_key);
end $$;


--
-- Name: ac360_school_academy_upsert_program(uuid, uuid, text, text, text, text, numeric, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_academy_upsert_program(p_org_id uuid, p_program_id uuid DEFAULT NULL::uuid, p_program_key text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_program_type text DEFAULT 'staff_training'::text, p_target_audience text DEFAULT 'staff'::text, p_duration_hours numeric DEFAULT 0, p_curriculum_json jsonb DEFAULT '[]'::jsonb, p_status text DEFAULT 'draft'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_key text;
begin
  v_key := coalesce(nullif(p_program_key,''),'academy-program-'||substr(gen_random_uuid()::text,1,8));
  insert into public.ac360_school_academy_programs(id,org_id,program_key,label,program_type,target_audience,duration_hours,curriculum_json,status,created_by,metadata_json)
  values(coalesce(p_program_id,gen_random_uuid()),p_org_id,v_key,coalesce(nullif(p_label,''),'Academy Program'),coalesce(p_program_type,'staff_training'),coalesce(p_target_audience,'staff'),coalesce(p_duration_hours,0),coalesce(p_curriculum_json,'[]'::jsonb),coalesce(p_status,'draft'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,program_key) do update set label=excluded.label,program_type=excluded.program_type,target_audience=excluded.target_audience,duration_hours=excluded.duration_hours,curriculum_json=excluded.curriculum_json,status=excluded.status,metadata_json=public.ac360_school_academy_programs.metadata_json || excluded.metadata_json,updated_at=now()
  returning id into v_id;
  insert into public.ac360_school_academy_events(org_id,event_type,entity_type,entity_id,severity,message,actor_app_user_id,metadata_json) values(p_org_id,'program_upserted','academy_program',v_id,'info','Academy program upserted.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'programId',v_id,'programKey',v_key);
end $$;


--
-- Name: ac360_school_acknowledge_incident(uuid, uuid, uuid, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_acknowledge_incident(p_org_id uuid, p_incident_id uuid, p_guardian_id uuid DEFAULT NULL::uuid, p_acknowledged_by_name text DEFAULT NULL::text, p_channel text DEFAULT 'manual'::text, p_status text DEFAULT 'acknowledged'::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  if p_incident_id is null then return jsonb_build_object('ok',false,'error','incidentId is required.'); end if;
  insert into public.ac360_school_incident_acknowledgements(org_id,incident_id,guardian_id,acknowledged_by_name,channel,status,notes,metadata_json)
  values(p_org_id,p_incident_id,p_guardian_id,p_acknowledged_by_name,coalesce(p_channel,'manual'),coalesce(p_status,'acknowledged'),p_notes,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  update public.ac360_school_incident_reports set parent_notification_status='acknowledged', status=case when status='open' then 'parent_notified' else status end, updated_at=now() where id=p_incident_id and org_id=p_org_id;
  insert into public.ac360_school_incident_events(org_id,incident_id,event_key,event_type,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_incident_id,'incident.acknowledged','acknowledgement','info','Incident acknowledgement recorded.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'acknowledgementId',v_id);
end $$;


--
-- Name: ac360_school_add_task_comment(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_add_task_comment(p_org_id uuid, p_task_id uuid, p_body text, p_comment_type text DEFAULT 'note'::text, p_visibility text DEFAULT 'internal'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_comment public.ac360_school_task_comments%rowtype; v_campus uuid;
begin
  if p_org_id is null or p_task_id is null then raise exception 'p_org_id and p_task_id are required'; end if;
  select campus_id into v_campus from public.ac360_school_tasks where id=p_task_id and org_id=p_org_id;
  if v_campus is null and not exists(select 1 from public.ac360_school_tasks where id=p_task_id and org_id=p_org_id) then raise exception 'Task not found'; end if;
  insert into public.ac360_school_task_comments(org_id,task_id,comment_type,body,visibility,created_by,metadata_json) values(p_org_id,p_task_id,coalesce(p_comment_type,'note'),coalesce(p_body,''),coalesce(p_visibility,'internal'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_comment;
  insert into public.ac360_school_operation_events(org_id,campus_id,event_key,action_key,entity_type,entity_id,severity,message,actor_app_user_id,metadata_json) values(p_org_id,v_campus,'school_ops.task.comment_added','school.task.comment.add','task_comment',v_comment.id,'info','Task comment added.',p_actor_app_user_id,jsonb_build_object('phase','phase_2g','taskId',p_task_id));
  return jsonb_build_object('ok',true,'comment',to_jsonb(v_comment));
end; $$;


--
-- Name: ac360_school_admissions_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_admissions_dashboard(p_org_id uuid DEFAULT NULL::uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_org_id uuid := p_org_id; v_snapshot jsonb; v_stage_counts jsonb; v_alerts jsonb; v_recent jsonb;
begin
  if v_org_id is null then select id into v_org_id from public.ac360_organizations where status in ('active','trial','grace') order by created_at asc limit 1; end if;
  if v_org_id is null then return jsonb_build_object('ok',false,'reason','No AC360 organization found.'); end if;

  perform public.ac360_school_reconcile_admissions(v_org_id,p_campus_id,null,'{"source":"dashboard_auto_reconcile"}'::jsonb);

  select to_jsonb(s) into v_snapshot from public.ac360_school_admission_snapshots s where s.org_id=v_org_id and (p_campus_id is null or s.campus_id=p_campus_id) and s.snapshot_date=coalesce(p_as_of_date,current_date) order by created_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('lead_status',lead_status,'count',count)), '[]'::jsonb) into v_stage_counts from (select lead_status,count(*)::int from public.ac360_school_admission_leads where org_id=v_org_id and (p_campus_id is null or campus_id=p_campus_id) group by lead_status order by lead_status) q;
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'type',alert_type,'severity',severity,'title',title,'message',message,'created_at',created_at) order by created_at desc), '[]'::jsonb) into v_alerts from public.ac360_school_admission_alerts where org_id=v_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('open','in_review') limit 20;
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'lead_code',lead_code,'child_first_name',child_first_name,'lead_status',lead_status,'priority',priority,'created_at',created_at) order by created_at desc), '[]'::jsonb) into v_recent from (select * from public.ac360_school_admission_leads where org_id=v_org_id and (p_campus_id is null or campus_id=p_campus_id) order by created_at desc limit 20) l;

  return jsonb_build_object('ok',true,'org_id',v_org_id,'phase','phase_2h_admissions_crm','uiBuildAllowed',false,'snapshot',coalesce(v_snapshot,'{}'::jsonb),'stage_counts',v_stage_counts,'alerts',v_alerts,'recent_leads',v_recent);
end $$;


--
-- Name: ac360_school_advance_workflow_step(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_advance_workflow_step(p_org_id uuid, p_workflow_instance_id uuid, p_step_key text, p_status text DEFAULT 'completed'::text, p_message text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_step public.ac360_school_workflow_steps%rowtype; v_next text; v_inst public.ac360_school_workflow_instances%rowtype;
begin
  if p_org_id is null or p_workflow_instance_id is null or p_step_key is null then raise exception 'p_org_id, p_workflow_instance_id and p_step_key are required'; end if;
  update public.ac360_school_workflow_steps set status=p_status, started_at=coalesce(started_at,now()), completed_at=case when p_status in ('completed','skipped','cancelled') then now() else completed_at end, metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now() where org_id=p_org_id and workflow_instance_id=p_workflow_instance_id and step_key=p_step_key returning * into v_step;
  if v_step.id is null then raise exception 'Workflow step not found'; end if;
  select step_key into v_next from public.ac360_school_workflow_steps where workflow_instance_id=p_workflow_instance_id and position > v_step.position and status='pending' order by position asc limit 1;
  update public.ac360_school_workflow_instances set current_step_key=v_next, status=case when v_next is null and p_status in ('completed','skipped') then 'completed' else status end, completed_at=case when v_next is null and p_status in ('completed','skipped') then now() else completed_at end, updated_at=now() where id=p_workflow_instance_id and org_id=p_org_id returning * into v_inst;
  insert into public.ac360_school_workflow_events(org_id,workflow_instance_id,workflow_step_id,event_key,event_type,actor_app_user_id,message,metadata_json) values(p_org_id,p_workflow_instance_id,v_step.id,'workflow.step.'||p_status,'step_change',p_actor_app_user_id,p_message,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'workflowInstance',to_jsonb(v_inst),'step',to_jsonb(v_step));
end; $$;


--
-- Name: ac360_school_ai_automation_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_ai_automation_dashboard(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_snapshot jsonb;
begin
  perform public.ac360_school_ai_automation_reconcile(p_org_id, p_as_of_date, null, '{}'::jsonb);
  select to_jsonb(s) into v_snapshot
  from public.ac360_school_ai_automation_snapshots s
  where s.org_id = p_org_id and s.snapshot_date = coalesce(p_as_of_date, current_date);

  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2n_ai_automation_smart_alerts_scheduled_jobs',
    'uiBuildAllowed', false,
    'snapshot', coalesce(v_snapshot, '{}'::jsonb),
    'openSmartAlerts', (select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc), '[]'::jsonb) from public.ac360_school_smart_alerts a where a.org_id=p_org_id and a.status in ('open','in_progress') limit 50),
    'runtimeAlerts', (select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc), '[]'::jsonb) from public.ac360_school_ai_automation_alerts a where a.org_id=p_org_id and a.status in ('open','in_progress') limit 50)
  );
end $$;


--
-- Name: ac360_school_ai_automation_reconcile(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_ai_automation_reconcile(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_snapshot public.ac360_school_ai_automation_snapshots%rowtype; v_due integer; v_failed_ai integer; v_failed_auto integer;
begin
  select count(*) into v_due from public.ac360_school_scheduled_jobs where org_id=p_org_id and status='active' and next_run_at is not null and next_run_at <= now();
  select count(*) into v_failed_ai from public.ac360_school_ai_jobs where org_id=p_org_id and status='failed' and created_at::date >= coalesce(p_as_of_date,current_date) - 7;
  select count(*) into v_failed_auto from public.ac360_school_automation_runs where org_id=p_org_id and status='failed' and created_at::date >= coalesce(p_as_of_date,current_date) - 7;

  insert into public.ac360_school_ai_automation_snapshots(org_id,snapshot_date,active_prompt_templates,queued_ai_jobs,failed_ai_jobs,active_automation_rules,running_automation_runs,failed_automation_runs,active_scheduled_jobs,due_scheduled_jobs,open_smart_alerts,critical_smart_alerts,metadata_json)
  values(
    p_org_id,coalesce(p_as_of_date,current_date),
    (select count(*) from public.ac360_school_ai_prompt_templates where org_id=p_org_id and status='published'),
    (select count(*) from public.ac360_school_ai_jobs where org_id=p_org_id and status in ('queued','running')),
    v_failed_ai,
    (select count(*) from public.ac360_school_automation_rules where org_id=p_org_id and status='active'),
    (select count(*) from public.ac360_school_automation_runs where org_id=p_org_id and status in ('queued','running')),
    v_failed_auto,
    (select count(*) from public.ac360_school_scheduled_jobs where org_id=p_org_id and status='active'),
    v_due,
    (select count(*) from public.ac360_school_smart_alerts where org_id=p_org_id and status in ('open','in_progress')),
    (select count(*) from public.ac360_school_smart_alerts where org_id=p_org_id and status in ('open','in_progress') and severity='critical'),
    coalesce(p_metadata,'{}'::jsonb)
  ) on conflict(org_id,snapshot_date) do update set active_prompt_templates=excluded.active_prompt_templates,queued_ai_jobs=excluded.queued_ai_jobs,failed_ai_jobs=excluded.failed_ai_jobs,active_automation_rules=excluded.active_automation_rules,running_automation_runs=excluded.running_automation_runs,failed_automation_runs=excluded.failed_automation_runs,active_scheduled_jobs=excluded.active_scheduled_jobs,due_scheduled_jobs=excluded.due_scheduled_jobs,open_smart_alerts=excluded.open_smart_alerts,critical_smart_alerts=excluded.critical_smart_alerts,metadata_json=public.ac360_school_ai_automation_snapshots.metadata_json||excluded.metadata_json,created_at=now() returning * into v_snapshot;

  if v_due > 0 then
    insert into public.ac360_school_ai_automation_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'scheduled-jobs-due-'||coalesce(p_as_of_date,current_date),'scheduled_jobs_due','warning','Scheduled jobs due',v_due::text || ' scheduled job(s) are due.','{}'::jsonb)
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,updated_at=now();
  end if;
  if v_failed_ai > 0 or v_failed_auto > 0 then
    insert into public.ac360_school_ai_automation_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'ai-automation-failures-'||coalesce(p_as_of_date,current_date),'runtime_failures','critical','AI / automation failures detected','Recent AI or automation failures require review.',jsonb_build_object('failed_ai_jobs',v_failed_ai,'failed_automation_runs',v_failed_auto))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;

  return jsonb_build_object('ok',true,'snapshot',to_jsonb(v_snapshot));
end $$;


--
-- Name: ac360_school_allocate_payment(uuid, uuid, uuid, numeric, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_allocate_payment(p_org_id uuid, p_payment_id uuid, p_invoice_id uuid, p_amount_mad numeric DEFAULT NULL::numeric, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payment public.ac360_school_fee_payments;
  v_amount numeric;
  v_allocation public.ac360_school_payment_allocations;
begin
  select * into v_payment from public.ac360_school_fee_payments where id=p_payment_id and org_id=p_org_id;
  if not found then raise exception 'payment not found'; end if;

  v_amount := greatest(coalesce(p_amount_mad, v_payment.amount_mad), 0);

  insert into public.ac360_school_payment_allocations(org_id, payment_id, invoice_id, amount_mad, allocated_by, notes, metadata_json)
  values (p_org_id, p_payment_id, p_invoice_id, v_amount, p_actor_app_user_id, p_notes, coalesce(p_metadata,'{}'::jsonb))
  on conflict (org_id, payment_id, invoice_id) do update set
    amount_mad=excluded.amount_mad,
    allocation_status='allocated',
    allocated_by=excluded.allocated_by,
    notes=excluded.notes,
    metadata_json=public.ac360_school_payment_allocations.metadata_json || excluded.metadata_json,
    updated_at=now()
  returning * into v_allocation;

  update public.ac360_school_tuition_invoices
  set paid_mad = least(total_mad, coalesce((select sum(amount_mad) from public.ac360_school_payment_allocations where org_id=p_org_id and invoice_id=p_invoice_id and allocation_status='allocated'),0)),
      status = case
        when coalesce((select sum(amount_mad) from public.ac360_school_payment_allocations where org_id=p_org_id and invoice_id=p_invoice_id and allocation_status='allocated'),0) >= total_mad then 'paid'
        when coalesce((select sum(amount_mad) from public.ac360_school_payment_allocations where org_id=p_org_id and invoice_id=p_invoice_id and allocation_status='allocated'),0) > 0 then 'partially_paid'
        else status
      end,
      updated_at=now()
  where org_id=p_org_id and id=p_invoice_id;

  return jsonb_build_object('ok', true, 'allocation', to_jsonb(v_allocation));
end $$;


--
-- Name: ac360_school_archive_document(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_archive_document(p_org_id uuid, p_document_id uuid, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_doc public.ac360_school_documents%rowtype;
begin
  update public.ac360_school_documents
  set status='archived', archived_at=now(), metadata_json=metadata_json || jsonb_build_object('archiveReason',p_reason,'archiveMetadata',coalesce(p_metadata,'{}'::jsonb)), updated_at=now()
  where org_id=p_org_id and id=p_document_id
  returning * into v_doc;
  if v_doc.id is null then raise exception 'Document not found'; end if;

  insert into public.ac360_school_document_access_events(org_id,document_id,access_type,actor_app_user_id,result,metadata_json)
  values(p_org_id,p_document_id,'archive',p_actor_app_user_id,'success',jsonb_build_object('reason',p_reason,'phase','phase_2f'));

  return jsonb_build_object('ok',true,'document',to_jsonb(v_doc),'archiveNotDelete',true);
end;
$$;


--
-- Name: ac360_school_archive_student(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_archive_student(p_org_id uuid, p_student_id uuid, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  return public.ac360_school_transition_student(p_org_id, p_student_id, 'archived', 'archived', coalesce(p_reason,'Archived through Phase 2B safe archive.'), p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || '{"archiveStrategy":"archive_not_delete"}'::jsonb);
end;
$$;


--
-- Name: ac360_school_assign_staff_shift(uuid, uuid, uuid, uuid, uuid, date, timestamp with time zone, timestamp with time zone, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_assign_staff_shift(p_org_id uuid, p_staff_profile_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_cycle_id uuid DEFAULT NULL::uuid, p_shift_profile_id uuid DEFAULT NULL::uuid, p_assignment_date date DEFAULT CURRENT_DATE, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_assigned_role text DEFAULT NULL::text, p_class_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_code text := 'SHF-' || to_char(coalesce(p_assignment_date,current_date),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8);
begin
  if p_staff_profile_id is null then return jsonb_build_object('ok',false,'error','staffProfileId is required.'); end if;
  insert into public.ac360_school_staff_shift_assignments(org_id,campus_id,cycle_id,staff_profile_id,shift_profile_id,assignment_code,assignment_date,starts_at,ends_at,assigned_role,class_id,status,created_by,metadata_json)
  values(p_org_id,p_campus_id,p_cycle_id,p_staff_profile_id,p_shift_profile_id,v_code,coalesce(p_assignment_date,current_date),p_starts_at,p_ends_at,p_assigned_role,p_class_id,'scheduled',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning id into v_id;
  insert into public.ac360_school_hr_events(org_id,campus_id,staff_profile_id,event_key,event_type,related_entity_type,related_entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_campus_id,p_staff_profile_id,'hr.shift.assign','schedule','staff_shift_assignment',v_id,'info','Staff shift assigned.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'assignmentId',v_id);
end $$;


--
-- Name: ac360_school_assign_transport_student(uuid, uuid, uuid, uuid, text, numeric, date, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_assign_transport_student(p_org_id uuid, p_student_id uuid, p_route_id uuid, p_stop_id uuid DEFAULT NULL::uuid, p_service_direction text DEFAULT 'round_trip'::text, p_monthly_fee_mad numeric DEFAULT 0, p_starts_on date DEFAULT CURRENT_DATE, p_ends_on date DEFAULT NULL::date, p_status text DEFAULT 'active'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  insert into public.ac360_school_transport_student_assignments(org_id,student_id,route_id,stop_id,service_direction,monthly_fee_mad,starts_on,ends_on,status,created_by,metadata_json)
  values(p_org_id,p_student_id,p_route_id,p_stop_id,coalesce(p_service_direction,'round_trip'),coalesce(p_monthly_fee_mad,0),coalesce(p_starts_on,current_date),p_ends_on,coalesce(p_status,'active'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,student_id,route_id,service_direction) do update set stop_id=excluded.stop_id,monthly_fee_mad=excluded.monthly_fee_mad,starts_on=excluded.starts_on,ends_on=excluded.ends_on,status=excluded.status,metadata_json=public.ac360_school_transport_student_assignments.metadata_json || excluded.metadata_json,updated_at=now()
  returning id into v_id;
  return jsonb_build_object('ok',true,'assignmentId',v_id);
end $$;


--
-- Name: ac360_school_attendance_daily_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_attendance_daily_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_operation_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_daybooks jsonb;
  v_alerts jsonb;
  v_recent_events jsonb;
  v_totals jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(d) order by d.operation_date desc, d.created_at desc), '[]'::jsonb)
  into v_daybooks
  from public.ac360_school_attendance_daybooks d
  where d.org_id = p_org_id
    and d.campus_id is not distinct from p_campus_id
    and d.operation_date = coalesce(p_operation_date,current_date);

  select jsonb_build_object(
    'expectedStudents', coalesce(sum(expected_students),0),
    'presentStudents', coalesce(sum(present_students),0),
    'absentStudents', coalesce(sum(absent_students),0),
    'lateStudents', coalesce(sum(late_students),0),
    'earlyOutStudents', coalesce(sum(early_out_students),0),
    'authorizedAbsenceStudents', coalesce(sum(authorized_absence_students),0),
    'unknownStudents', coalesce(sum(unknown_students),0),
    'checkedInStaff', coalesce(sum(checked_in_staff),0),
    'openIssues', coalesce(sum(open_issues_count),0)
  ) into v_totals
  from public.ac360_school_attendance_daybooks d
  where d.org_id = p_org_id
    and d.campus_id is not distinct from p_campus_id
    and d.operation_date = coalesce(p_operation_date,current_date);

  select coalesce(jsonb_agg(to_jsonb(a) order by a.opened_at desc), '[]'::jsonb)
  into v_alerts
  from public.ac360_school_daily_ops_alerts a
  where a.org_id = p_org_id
    and a.campus_id is not distinct from p_campus_id
    and a.status in ('active','acknowledged')
  limit 50;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.event_at desc), '[]'::jsonb)
  into v_recent_events
  from (
    select * from public.ac360_school_attendance_events e
    where e.org_id = p_org_id
      and e.event_at >= coalesce(p_operation_date,current_date)::timestamptz
      and e.event_at < (coalesce(p_operation_date,current_date) + interval '1 day')::timestamptz
    order by e.event_at desc
    limit 80
  ) e;

  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2c_attendance_presence_daily_ops',
    'uiBuildAllowed', false,
    'orgId', p_org_id,
    'campusId', p_campus_id,
    'operationDate', coalesce(p_operation_date,current_date),
    'totals', coalesce(v_totals, '{}'::jsonb),
    'daybooks', v_daybooks,
    'alerts', v_alerts,
    'recentEvents', v_recent_events
  );
end;
$$;


--
-- Name: ac360_school_book_parenttrust_appointment(uuid, uuid, uuid, uuid, uuid, uuid, text, timestamp with time zone, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_book_parenttrust_appointment(p_org_id uuid, p_slot_id uuid DEFAULT NULL::uuid, p_campus_id uuid DEFAULT NULL::uuid, p_guardian_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_complaint_id uuid DEFAULT NULL::uuid, p_appointment_type text DEFAULT 'parent_meeting'::text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_purpose text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_code text; v_scheduled timestamptz;
begin
  v_code := 'PTA-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || upper(substr(gen_random_uuid()::text,1,4));
  select starts_at into v_scheduled from public.ac360_school_parenttrust_appointment_slots where id=p_slot_id and org_id=p_org_id;
  v_scheduled := coalesce(v_scheduled,p_scheduled_at,now()+interval '1 day');
  insert into public.ac360_school_parenttrust_appointments(org_id,campus_id,slot_id,guardian_id,student_id,complaint_id,appointment_code,appointment_type,scheduled_at,purpose,created_by,metadata_json)
  values(p_org_id,p_campus_id,p_slot_id,p_guardian_id,p_student_id,p_complaint_id,v_code,coalesce(p_appointment_type,'parent_meeting'),v_scheduled,p_purpose,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  return jsonb_build_object('ok',true,'appointmentId',v_id,'appointmentCode',v_code,'status','scheduled');
end $$;


--
-- Name: ac360_school_branding_integrations_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_branding_integrations_dashboard(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_snapshot public.ac360_school_branding_integration_snapshots%rowtype; v_alerts jsonb;
begin
  insert into public.ac360_school_branding_integration_snapshots(
    org_id,snapshot_date,published_brand_profiles,active_domains,pending_domains,active_connectors,connector_errors,active_api_keys,active_webhooks,failed_deliveries,metadata_json
  ) values(
    p_org_id,coalesce(p_as_of_date,current_date),
    (select count(*) from public.ac360_school_brand_profiles where org_id=p_org_id and status='published'),
    (select count(*) from public.ac360_school_custom_domains where org_id=p_org_id and status='active'),
    (select count(*) from public.ac360_school_custom_domains where org_id=p_org_id and status in ('requested','pending_dns','failed')),
    (select count(*) from public.ac360_school_integration_connectors where org_id=p_org_id and status='active'),
    (select count(*) from public.ac360_school_integration_connectors where org_id=p_org_id and status='error'),
    (select count(*) from public.ac360_school_api_keys where org_id=p_org_id and status='active'),
    (select count(*) from public.ac360_school_webhooks where org_id=p_org_id and status='active'),
    (select count(*) from public.ac360_school_webhook_deliveries where org_id=p_org_id and status='failed' and created_at::date=coalesce(p_as_of_date,current_date)),
    '{"phase":"phase_2p"}'::jsonb
  ) on conflict(org_id,snapshot_date) do update set
    published_brand_profiles=excluded.published_brand_profiles,
    active_domains=excluded.active_domains,
    pending_domains=excluded.pending_domains,
    active_connectors=excluded.active_connectors,
    connector_errors=excluded.connector_errors,
    active_api_keys=excluded.active_api_keys,
    active_webhooks=excluded.active_webhooks,
    failed_deliveries=excluded.failed_deliveries,
    metadata_json=public.ac360_school_branding_integration_snapshots.metadata_json || excluded.metadata_json
  returning * into v_snapshot;

  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc),'[]'::jsonb) into v_alerts
  from public.ac360_school_integration_alerts a
  where a.org_id=p_org_id and a.status in ('open','in_review')
  limit 50;

  return jsonb_build_object('ok',true,'snapshot',to_jsonb(v_snapshot),'alerts',coalesce(v_alerts,'[]'::jsonb));
end $$;


--
-- Name: ac360_school_close_attendance_session(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_close_attendance_session(p_org_id uuid, p_attendance_session_id uuid, p_close_status text DEFAULT 'closed'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session record;
  v_daybook_id uuid;
  v_counts jsonb;
begin
  select * into v_session from public.ac360_school_attendance_sessions where id = p_attendance_session_id and org_id = p_org_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'Attendance session not found.'); end if;
  if p_close_status not in ('closed','locked') then p_close_status := 'closed'; end if;

  update public.ac360_school_attendance_sessions
  set status = p_close_status, closed_by = p_actor_app_user_id, closed_at = now(), metadata_json = metadata_json || coalesce(p_metadata,'{}'::jsonb)
  where id = p_attendance_session_id;

  v_daybook_id := public.ac360_school_find_or_create_daybook(p_org_id, v_session.campus_id, v_session.class_id, v_session.academic_year_id, v_session.session_date, v_session.session_key, p_actor_app_user_id, p_metadata);
  v_counts := public.ac360_school_refresh_daybook_counts(v_daybook_id);

  update public.ac360_school_attendance_daybooks
  set status = case when p_close_status='locked' then 'locked' else 'closed' end,
      closed_by = p_actor_app_user_id,
      closed_at = now()
  where id = v_daybook_id;

  insert into public.ac360_school_attendance_events(org_id, daybook_id, attendance_session_id, event_type, attendance_type, actor_app_user_id, source, reason, metadata_json)
  values (p_org_id, v_daybook_id, p_attendance_session_id, 'session_closed', 'student', p_actor_app_user_id, 'system', 'Attendance session closed safely.', coalesce(p_metadata,'{}'::jsonb));

  return jsonb_build_object('ok', true, 'sessionId', p_attendance_session_id, 'daybookId', v_daybook_id, 'status', p_close_status, 'counts', v_counts);
end;
$$;


--
-- Name: ac360_school_close_class(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_close_class(p_org_id uuid, p_class_id uuid, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_class public.ac360_school_classes%rowtype;
  v_active_count integer := 0;
  v_event_id uuid;
begin
  select * into v_class from public.ac360_school_classes where org_id = p_org_id and id = p_class_id for update;
  if v_class.id is null then raise exception 'Class not found for this organization'; end if;
  select count(*) into v_active_count from public.ac360_school_class_enrollments where org_id = p_org_id and class_id = p_class_id and status = 'active';

  update public.ac360_school_classes
  set status = 'archived', archived_at = coalesce(archived_at, now()), metadata_json = metadata_json || jsonb_build_object('closedAt', now(), 'closeReason', p_reason, 'activeEnrollmentCountAtClose', v_active_count), updated_at = now()
  where org_id = p_org_id and id = p_class_id;

  v_event_id := public.ac360_school_record_lifecycle_event(p_org_id, v_class.campus_id, 'class', p_class_id, 'school.class.close', v_class.status, 'archived', null, null, p_reason, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('activeEnrollmentCount', v_active_count));
  perform public.ac360_measure_capacity(p_org_id, 'classes', public.ac360_school_current_capacity(p_org_id,'classes'), 'ac360_school_classes', '{"source":"phase_2b_class_close"}'::jsonb);

  return jsonb_build_object('ok', true, 'classId', p_class_id, 'eventId', v_event_id, 'activeEnrollmentCountAtClose', v_active_count, 'status', 'archived');
end;
$$;


--
-- Name: ac360_school_close_transport_route_run(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_close_transport_route_run(p_org_id uuid, p_route_run_id uuid, p_status text DEFAULT 'completed'::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  update public.ac360_school_transport_route_runs set status=coalesce(p_status,'completed'),ended_at=now(),notes=coalesce(p_notes,notes),metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb),updated_at=now()
  where id=p_route_run_id and org_id=p_org_id returning id into v_id;
  if v_id is null then return jsonb_build_object('ok',false,'error','Route run not found.'); end if;
  return jsonb_build_object('ok',true,'routeRunId',v_id,'status',coalesce(p_status,'completed'));
end $$;


--
-- Name: ac360_school_communication_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_communication_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2e_communication_messaging_notifications',
    'uiBuildAllowed', false,
    'asOfDate', coalesce(p_as_of_date,current_date),
    'templates', jsonb_build_object(
      'total', coalesce((select count(*) from public.ac360_school_message_templates where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id)),0),
      'published', coalesce((select count(*) from public.ac360_school_message_templates where org_id=p_org_id and status='published' and (p_campus_id is null or campus_id=p_campus_id)),0)
    ),
    'campaigns', jsonb_build_object(
      'total', coalesce((select count(*) from public.ac360_school_message_campaigns where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id)),0),
      'queued', coalesce((select count(*) from public.ac360_school_message_campaigns where org_id=p_org_id and status in ('queued','dispatching') and (p_campus_id is null or campus_id=p_campus_id)),0),
      'sent', coalesce((select count(*) from public.ac360_school_message_campaigns where org_id=p_org_id and status in ('sent','partially_sent') and (p_campus_id is null or campus_id=p_campus_id)),0)
    ),
    'delivery', jsonb_build_object(
      'queued', coalesce((select count(*) from public.ac360_school_message_recipients r join public.ac360_school_message_campaigns c on c.id=r.campaign_id where r.org_id=p_org_id and r.status='queued' and (p_campus_id is null or c.campus_id=p_campus_id)),0),
      'dispatched', coalesce((select count(*) from public.ac360_school_message_recipients r join public.ac360_school_message_campaigns c on c.id=r.campaign_id where r.org_id=p_org_id and r.status='dispatched' and (p_campus_id is null or c.campus_id=p_campus_id)),0),
      'delivered', coalesce((select count(*) from public.ac360_school_message_recipients r join public.ac360_school_message_campaigns c on c.id=r.campaign_id where r.org_id=p_org_id and r.status='delivered' and (p_campus_id is null or c.campus_id=p_campus_id)),0),
      'failed', coalesce((select count(*) from public.ac360_school_message_recipients r join public.ac360_school_message_campaigns c on c.id=r.campaign_id where r.org_id=p_org_id and r.status='failed' and (p_campus_id is null or c.campus_id=p_campus_id)),0),
      'read', coalesce((select count(*) from public.ac360_school_message_recipients r join public.ac360_school_message_campaigns c on c.id=r.campaign_id where r.org_id=p_org_id and r.status='read' and (p_campus_id is null or c.campus_id=p_campus_id)),0)
    ),
    'notifications', jsonb_build_object(
      'unread', coalesce((select count(*) from public.ac360_school_parent_notifications where org_id=p_org_id and status='unread' and (p_campus_id is null or campus_id=p_campus_id)),0),
      'urgent', coalesce((select count(*) from public.ac360_school_parent_notifications where org_id=p_org_id and priority='urgent' and status='unread' and (p_campus_id is null or campus_id=p_campus_id)),0)
    ),
    'threads', jsonb_build_object(
      'open', coalesce((select count(*) from public.ac360_school_communication_threads where org_id=p_org_id and status in ('open','pending') and (p_campus_id is null or campus_id=p_campus_id)),0),
      'urgent', coalesce((select count(*) from public.ac360_school_communication_threads where org_id=p_org_id and priority='urgent' and status in ('open','pending') and (p_campus_id is null or campus_id=p_campus_id)),0)
    ),
    'alerts', coalesce((select count(*) from public.ac360_school_communication_alerts where org_id=p_org_id and status='open' and (p_campus_id is null or campus_id=p_campus_id)),0),
    'latestCampaigns', coalesce((select jsonb_agg(to_jsonb(x)) from (select id,campaign_code,title,channel,status,recipient_count,queued_count,dispatched_count,delivered_count,failed_count,created_at from public.ac360_school_message_campaigns where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) order by created_at desc limit 10) x), '[]'::jsonb),
    'latestAlerts', coalesce((select jsonb_agg(to_jsonb(a)) from (select id,alert_key,alert_type,severity,title,status,created_at from public.ac360_school_communication_alerts where org_id=p_org_id and status='open' and (p_campus_id is null or campus_id=p_campus_id) order by created_at desc limit 10) a), '[]'::jsonb)
  );
end $$;


--
-- Name: ac360_school_complete_admission_followup(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_complete_admission_followup(p_org_id uuid, p_followup_id uuid, p_outcome text DEFAULT NULL::text, p_next_action text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_lead_id uuid; begin
  select lead_id into v_lead_id from public.ac360_school_admission_followups where id=p_followup_id and org_id=p_org_id;
  if v_lead_id is null then raise exception 'followup not found'; end if;
  update public.ac360_school_admission_followups set status='done', outcome=p_outcome, next_action=coalesce(p_next_action,next_action), completed_at=now(), updated_at=now() where id=p_followup_id and org_id=p_org_id;
  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,actor_app_user_id,message,metadata_json) values(p_org_id,v_lead_id,'followup.completed','followup',p_actor_app_user_id,coalesce(p_outcome,'Admission follow-up completed.'),coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'followup_id',p_followup_id,'lead_id',v_lead_id);
end $$;


--
-- Name: ac360_school_complete_admission_visit(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_complete_admission_visit(p_org_id uuid, p_visit_id uuid, p_status text DEFAULT 'completed'::text, p_outcome text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_lead_id uuid; begin
  select lead_id into v_lead_id from public.ac360_school_admission_visits where id=p_visit_id and org_id=p_org_id;
  if v_lead_id is null then raise exception 'visit not found'; end if;
  update public.ac360_school_admission_visits set status=coalesce(nullif(p_status,''),'completed'), outcome=p_outcome, notes=coalesce(p_notes,notes), completed_at=case when p_status in ('completed','no_show','cancelled') then now() else completed_at end, updated_at=now() where id=p_visit_id and org_id=p_org_id;
  if p_status='completed' then update public.ac360_school_admission_leads set lead_status='visited', updated_at=now() where id=v_lead_id and org_id=p_org_id and lead_status not in ('converted','lost'); end if;
  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,to_status,actor_app_user_id,message,metadata_json) values(p_org_id,v_lead_id,'visit.completed','visit',p_status,p_actor_app_user_id,coalesce(p_outcome,'Admission visit completed.'),coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'visit_id',p_visit_id,'lead_id',v_lead_id,'status',p_status);
end $$;


--
-- Name: ac360_school_complete_ai_job(uuid, uuid, text, jsonb, numeric, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_complete_ai_job(p_org_id uuid, p_ai_job_id uuid, p_status text DEFAULT 'completed'::text, p_output_json jsonb DEFAULT '{}'::jsonb, p_actual_credit_cost numeric DEFAULT NULL::numeric, p_failed_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_record public.ac360_school_ai_jobs%rowtype;
begin
  update public.ac360_school_ai_jobs set status=coalesce(p_status,'completed'),output_json=coalesce(p_output_json,output_json),actual_credit_cost=coalesce(p_actual_credit_cost,actual_credit_cost),failed_reason=p_failed_reason,completed_at=case when coalesce(p_status,'completed') in ('completed','failed','cancelled') then now() else completed_at end,metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=p_ai_job_id and org_id=p_org_id returning * into v_record;
  if v_record.id is null then return jsonb_build_object('ok',false,'error','AI job not found.'); end if;
  insert into public.ac360_school_ai_job_events(org_id,ai_job_id,event_type,severity,message,actor_app_user_id,metadata_json) values(p_org_id,v_record.id,'completed',case when v_record.status='failed' then 'critical' else 'info' end,coalesce(p_failed_reason,'AI job completed.'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  if v_record.status='failed' then
    insert into public.ac360_school_ai_automation_alerts(org_id,alert_key,alert_type,severity,title,message,related_entity_type,related_entity_id,metadata_json)
    values(p_org_id,'ai-job-failed-'||v_record.id,'ai_job_failed','critical','AI job failed',coalesce(p_failed_reason,'AI job failed.'),'ai_job',v_record.id,coalesce(p_metadata,'{}'::jsonb))
    on conflict(org_id,alert_key) do nothing;
  end if;
  return jsonb_build_object('ok',true,'aiJob',to_jsonb(v_record));
end $$;


--
-- Name: ac360_school_complete_setup_item(uuid, uuid, text, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_complete_setup_item(p_org_id uuid, p_checklist_id uuid, p_item_key text, p_label text DEFAULT NULL::text, p_status text DEFAULT 'completed'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_item public.ac360_school_setup_items%rowtype;
begin
  insert into public.ac360_school_setup_items(org_id,checklist_id,item_key,label,status,completed_at,completed_by,notes,metadata_json)
  values(p_org_id,p_checklist_id,p_item_key,coalesce(nullif(p_label,''),p_item_key),coalesce(nullif(p_status,''),'completed'),case when coalesce(nullif(p_status,''),'completed')='completed' then now() else null end,p_actor_app_user_id,p_notes,coalesce(p_metadata,'{}'::jsonb)||'{"phase":"phase_2q"}'::jsonb)
  on conflict(checklist_id,item_key) do update set label=excluded.label,status=excluded.status,completed_at=excluded.completed_at,completed_by=excluded.completed_by,notes=excluded.notes,metadata_json=public.ac360_school_setup_items.metadata_json||excluded.metadata_json,updated_at=now()
  returning * into v_item;
  return jsonb_build_object('ok',true,'setup_item',to_jsonb(v_item));
end $$;


--
-- Name: ac360_school_compute_success_health_score(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_compute_success_health_score(p_org_id uuid, p_score_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_account public.ac360_school_client_success_accounts%rowtype; v_score public.ac360_school_success_health_scores%rowtype; v_open_alerts int; v_open_findings int; v_progress numeric; v_health numeric; v_status text;
begin
  insert into public.ac360_school_client_success_accounts(org_id) values(p_org_id) on conflict(org_id) do update set updated_at=now() returning * into v_account;
  select count(*) into v_open_alerts from public.ac360_school_onboarding_success_alerts where org_id=p_org_id and status in ('open','acknowledged');
  select count(*) into v_open_findings from public.ac360_school_data_validation_findings where org_id=p_org_id and status in ('open','acknowledged') and severity in ('error','critical');
  select coalesce(max(progress_percent),0) into v_progress from public.ac360_school_onboarding_projects where org_id=p_org_id;
  v_health := greatest(0,least(100,coalesce(v_progress,0) + 20 - (v_open_alerts*8) - (v_open_findings*10)));
  v_status := case when v_health >= 75 then 'green' when v_health >= 45 then 'yellow' else 'red' end;
  insert into public.ac360_school_success_health_scores(org_id,success_account_id,score_date,health_score,health_status,adoption_score,payment_score,support_score,usage_score,risk_score,drivers_json,metadata_json)
  values(p_org_id,v_account.id,coalesce(p_score_date,current_date),v_health,v_status,coalesce(v_progress,0),70,case when v_open_alerts=0 then 80 else 45 end,coalesce(v_progress,0),100-v_health,jsonb_build_object('open_alerts',v_open_alerts,'open_critical_findings',v_open_findings,'onboarding_progress',v_progress),coalesce(p_metadata,'{}'::jsonb)||'{"phase":"phase_2q"}'::jsonb)
  on conflict(org_id,score_date) do update set health_score=excluded.health_score,health_status=excluded.health_status,adoption_score=excluded.adoption_score,payment_score=excluded.payment_score,support_score=excluded.support_score,usage_score=excluded.usage_score,risk_score=excluded.risk_score,drivers_json=excluded.drivers_json,metadata_json=public.ac360_school_success_health_scores.metadata_json||excluded.metadata_json,created_at=now()
  returning * into v_score;
  update public.ac360_school_client_success_accounts set health_score=v_score.health_score,health_status=v_score.health_status,renewal_risk_level=case when v_score.health_status='red' then 'high' when v_score.health_status='yellow' then 'medium' else 'low' end,updated_at=now() where id=v_account.id;
  return jsonb_build_object('ok',true,'health_score',to_jsonb(v_score));
end $$;


--
-- Name: ac360_school_convert_admission_to_student(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_convert_admission_to_student(p_org_id uuid, p_lead_id uuid, p_class_id uuid DEFAULT NULL::uuid, p_academic_year_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_lead public.ac360_school_admission_leads%rowtype;
  v_student_id uuid;
  v_student_code text;
  v_guardian record;
  v_student_guardian_id uuid;
begin
  select * into v_lead from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id;
  if v_lead.id is null then raise exception 'lead not found'; end if;
  if v_lead.converted_student_id is not null then return jsonb_build_object('ok',true,'student_id',v_lead.converted_student_id,'already_converted',true); end if;

  v_student_code := public.ac360_admissions_default_code('STU');
  insert into public.ac360_school_students(org_id,campus_id,academic_year_id,student_code,first_name,last_name,date_of_birth,enrollment_status,status,joined_on,source_channel,created_by,metadata_json)
  values(p_org_id,v_lead.campus_id,coalesce(p_academic_year_id,v_lead.academic_year_id),v_student_code,v_lead.child_first_name,v_lead.child_last_name,v_lead.date_of_birth,'enrolled','active',current_date,'admissions_crm',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('admission_lead_id',p_lead_id)) returning id into v_student_id;

  if p_class_id is not null then
    insert into public.ac360_school_class_enrollments(org_id,student_id,class_id,status,starts_on,metadata_json)
    values(p_org_id,v_student_id,p_class_id,'active',current_date,'{"source":"admissions_conversion"}'::jsonb)
    on conflict do nothing;
  end if;

  for v_guardian in select * from public.ac360_school_admission_lead_guardians where lead_id=p_lead_id and org_id=p_org_id loop
    if v_guardian.guardian_id is not null then
      insert into public.ac360_school_student_guardians(org_id,student_id,guardian_id,relation_label,is_primary,status,metadata_json)
      values(p_org_id,v_student_id,v_guardian.guardian_id,v_guardian.relationship,v_guardian.is_primary,'active','{"source":"admissions_conversion"}'::jsonb)
      on conflict do nothing;
    end if;
  end loop;

  update public.ac360_school_admission_leads set lead_status='converted', status='converted', converted_student_id=v_student_id, converted_at=now(), updated_at=now() where id=p_lead_id and org_id=p_org_id;
  update public.ac360_school_enrollment_applications set status='converted', student_id=v_student_id, updated_at=now() where lead_id=p_lead_id and org_id=p_org_id and status <> 'archived';

  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,to_status,actor_app_user_id,message,metadata_json) values(p_org_id,p_lead_id,'lead.converted_to_student','conversion','converted',p_actor_app_user_id,'Admission lead converted to active student.',coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'student_id',v_student_id,'student_code',v_student_code,'lead_id',p_lead_id);
end $$;


--
-- Name: ac360_school_create_admission_followup(uuid, uuid, timestamp with time zone, text, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_admission_followup(p_org_id uuid, p_lead_id uuid, p_due_at timestamp with time zone, p_followup_type text DEFAULT 'call'::text, p_assigned_staff_id uuid DEFAULT NULL::uuid, p_next_action text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid; v_code text; begin
  if p_due_at is null then raise exception 'due_at is required'; end if;
  if not exists(select 1 from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id) then raise exception 'lead not found'; end if;
  v_code := public.ac360_admissions_default_code('FU');
  insert into public.ac360_school_admission_followups(org_id,lead_id,followup_code,followup_type,due_at,status,assigned_staff_id,next_action,notes,created_by,metadata_json)
  values(p_org_id,p_lead_id,v_code,coalesce(nullif(p_followup_type,''),'call'),p_due_at,'open',p_assigned_staff_id,p_next_action,p_notes,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  update public.ac360_school_admission_leads set next_followup_at=p_due_at, updated_at=now() where id=p_lead_id and org_id=p_org_id;
  return jsonb_build_object('ok',true,'followup_id',v_id,'followup_code',v_code);
end $$;


--
-- Name: ac360_school_create_admission_import_batch(uuid, uuid, text, integer, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_admission_import_batch(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_source_label text DEFAULT NULL::text, p_total_rows integer DEFAULT 0, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid; v_code text; begin
  v_code := public.ac360_admissions_default_code('IMP');
  insert into public.ac360_school_admission_import_batches(org_id,campus_id,batch_code,source_label,total_rows,status,created_by,metadata_json)
  values(p_org_id,p_campus_id,v_code,p_source_label,coalesce(p_total_rows,0),'queued',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  return jsonb_build_object('ok',true,'batch_id',v_id,'batch_code',v_code);
end $$;


--
-- Name: ac360_school_create_admission_lead(uuid, uuid, text, text, date, date, text, text, text, text, text, text, text, numeric, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_admission_lead(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_child_first_name text DEFAULT NULL::text, p_child_last_name text DEFAULT NULL::text, p_date_of_birth date DEFAULT NULL::date, p_desired_start_date date DEFAULT NULL::date, p_desired_level text DEFAULT NULL::text, p_parent_name text DEFAULT NULL::text, p_parent_phone text DEFAULT NULL::text, p_parent_email text DEFAULT NULL::text, p_preferred_channel text DEFAULT 'whatsapp'::text, p_source_key text DEFAULT 'manual'::text, p_priority text DEFAULT 'medium'::text, p_score numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_pipeline_id uuid;
  v_stage_id uuid;
  v_source_id uuid;
  v_lead_id uuid;
  v_code text;
begin
  if p_org_id is null then raise exception 'org_id is required'; end if;
  if nullif(trim(coalesce(p_child_first_name,'')),'') is null then raise exception 'child_first_name is required'; end if;

  perform public.ac360_school_ensure_admissions_pipeline(p_org_id,p_campus_id,p_actor_app_user_id,'{}'::jsonb);
  select id into v_pipeline_id from public.ac360_school_admission_pipelines where org_id=p_org_id and pipeline_key='default' limit 1;
  select id into v_stage_id from public.ac360_school_admission_stages where pipeline_id=v_pipeline_id and stage_key='new' limit 1;
  select id into v_source_id from public.ac360_school_admissions_sources where org_id=p_org_id and source_key=coalesce(nullif(p_source_key,''),'manual') limit 1;
  v_code := public.ac360_admissions_default_code('LEAD');

  insert into public.ac360_school_admission_leads(
    org_id,campus_id,pipeline_id,stage_id,source_id,lead_code,child_first_name,child_last_name,date_of_birth,desired_start_date,desired_level,
    parent_name,parent_phone,parent_email,preferred_channel,lead_status,priority,score,notes,created_by,metadata_json
  ) values(
    p_org_id,p_campus_id,v_pipeline_id,v_stage_id,v_source_id,v_code,trim(p_child_first_name),nullif(trim(coalesce(p_child_last_name,'')),''),p_date_of_birth,p_desired_start_date,p_desired_level,
    p_parent_name,p_parent_phone,p_parent_email,coalesce(nullif(p_preferred_channel,''),'whatsapp'),'new',coalesce(nullif(p_priority,''),'medium'),coalesce(p_score,0),p_notes,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_lead_id;

  if nullif(trim(coalesce(p_parent_name,'')),'') is not null then
    insert into public.ac360_school_admission_lead_guardians(org_id,lead_id,guardian_name,relationship,phone,email,is_primary,consent_status,metadata_json)
    values(p_org_id,v_lead_id,p_parent_name,'parent',p_parent_phone,p_parent_email,true,'pending','{"created_from":"lead_create"}'::jsonb);
  end if;

  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,to_status,actor_app_user_id,message,metadata_json)
  values(p_org_id,v_lead_id,'lead.created','lead_created','new',p_actor_app_user_id,'Admission lead created.',coalesce(p_metadata,'{}'::jsonb));

  return jsonb_build_object('ok',true,'lead_id',v_lead_id,'lead_code',v_code,'status','new');
end;
$$;


--
-- Name: ac360_school_create_document_version(uuid, uuid, text, text, bigint, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_document_version(p_org_id uuid, p_document_id uuid, p_file_name text DEFAULT NULL::text, p_file_path text DEFAULT NULL::text, p_file_size_bytes bigint DEFAULT 0, p_mime_type text DEFAULT NULL::text, p_checksum text DEFAULT NULL::text, p_change_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_doc public.ac360_school_documents%rowtype;
  v_version public.ac360_school_document_versions%rowtype;
  v_next integer := 1;
begin
  if p_org_id is null or p_document_id is null then raise exception 'p_org_id and p_document_id are required'; end if;
  select * into v_doc from public.ac360_school_documents where id=p_document_id and org_id=p_org_id limit 1;
  if v_doc.id is null then raise exception 'Document not found'; end if;

  select coalesce(max(version_number),0)+1 into v_next from public.ac360_school_document_versions where document_id=p_document_id;
  update public.ac360_school_document_versions set status='superseded' where document_id=p_document_id and status='active';

  insert into public.ac360_school_document_versions(org_id,document_id,version_number,file_name,file_path,file_size_bytes,mime_type,checksum,change_note,status,created_by,metadata_json)
  values(p_org_id,p_document_id,v_next,p_file_name,p_file_path,greatest(coalesce(p_file_size_bytes,0),0),p_mime_type,p_checksum,p_change_note,'active',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning * into v_version;

  update public.ac360_school_documents
  set current_version_id=v_version.id,
      file_name=coalesce(p_file_name,file_name), file_path=coalesce(p_file_path,file_path), file_size_bytes=greatest(coalesce(p_file_size_bytes,file_size_bytes),0), mime_type=coalesce(p_mime_type,mime_type), updated_at=now()
  where id=p_document_id;

  return jsonb_build_object('ok',true,'version',to_jsonb(v_version));
end;
$$;


--
-- Name: ac360_school_create_enrollment_application(uuid, uuid, uuid, text, text[], text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_enrollment_application(p_org_id uuid, p_lead_id uuid, p_offer_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'submitted'::text, p_missing_documents text[] DEFAULT '{}'::text[], p_review_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid; v_code text; begin
  if not exists(select 1 from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id) then raise exception 'lead not found'; end if;
  v_code := public.ac360_admissions_default_code('APP');
  insert into public.ac360_school_enrollment_applications(org_id,lead_id,offer_id,application_code,status,submitted_at,missing_documents,review_note,created_by,metadata_json)
  values(p_org_id,p_lead_id,p_offer_id,v_code,coalesce(nullif(p_status,''),'submitted'),case when p_status in ('submitted','in_review','approved') then now() else null end,coalesce(p_missing_documents,'{}'::text[]),p_review_note,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  update public.ac360_school_admission_leads set lead_status='application', updated_at=now() where id=p_lead_id and org_id=p_org_id and lead_status not in ('converted','lost');
  return jsonb_build_object('ok',true,'application_id',v_id,'application_code',v_code);
end $$;


--
-- Name: ac360_school_create_intake_submission(uuid, uuid, uuid, text, text, text, text, text, text, jsonb, jsonb, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_intake_submission(p_org_id uuid, p_form_id uuid DEFAULT NULL::uuid, p_source_id uuid DEFAULT NULL::uuid, p_submission_key text DEFAULT NULL::text, p_submission_type text DEFAULT 'form'::text, p_parent_name text DEFAULT NULL::text, p_parent_phone text DEFAULT NULL::text, p_parent_email text DEFAULT NULL::text, p_child_name text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_normalized_json jsonb DEFAULT '{}'::jsonb, p_consent_json jsonb DEFAULT '{}'::jsonb, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_sub public.ac360_school_intake_submissions%rowtype; v_alert public.ac360_school_intake_alerts%rowtype;
begin
  insert into public.ac360_school_intake_submissions(org_id,form_id,source_id,submission_key,submission_type,parent_name,parent_phone,parent_email,child_name,payload_json,normalized_json,consent_json,ip_address,user_agent,metadata_json)
  values(p_org_id,p_form_id,p_source_id,coalesce(nullif(p_submission_key,''),'submission-'||substr(gen_random_uuid()::text,1,10)),coalesce(nullif(p_submission_type,''),'form'),p_parent_name,p_parent_phone,p_parent_email,p_child_name,coalesce(p_payload_json,'{}'::jsonb),coalesce(p_normalized_json,'{}'::jsonb),coalesce(p_consent_json,'{}'::jsonb),p_ip_address,p_user_agent,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,submission_key) do update set payload_json=excluded.payload_json,normalized_json=excluded.normalized_json,metadata_json=public.ac360_school_intake_submissions.metadata_json||excluded.metadata_json,updated_at=now() returning * into v_sub;
  insert into public.ac360_school_intake_events(org_id,submission_id,event_type,severity,message,payload_json) values(p_org_id,v_sub.id,'submission.received','info','External intake submission received.',coalesce(p_payload_json,'{}'::jsonb));
  return jsonb_build_object('ok',true,'submission',to_jsonb(v_sub));
end $$;


--
-- Name: ac360_school_create_leave_request(uuid, uuid, uuid, text, date, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_leave_request(p_org_id uuid, p_staff_profile_id uuid, p_policy_id uuid DEFAULT NULL::uuid, p_leave_type text DEFAULT 'annual'::text, p_starts_on date DEFAULT CURRENT_DATE, p_ends_on date DEFAULT CURRENT_DATE, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_code text := 'LV-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,6); v_days numeric;
begin
  if p_staff_profile_id is null then return jsonb_build_object('ok',false,'error','staffProfileId is required.'); end if;
  v_days := greatest((coalesce(p_ends_on,p_starts_on,current_date) - coalesce(p_starts_on,current_date) + 1),1);
  insert into public.ac360_school_leave_requests(org_id,staff_profile_id,policy_id,request_code,leave_type,starts_on,ends_on,total_days,status,reason,requested_by,metadata_json)
  values(p_org_id,p_staff_profile_id,p_policy_id,v_code,coalesce(p_leave_type,'annual'),coalesce(p_starts_on,current_date),coalesce(p_ends_on,coalesce(p_starts_on,current_date)),v_days,'pending',p_reason,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  insert into public.ac360_school_hr_events(org_id,staff_profile_id,event_key,event_type,related_entity_type,related_entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_staff_profile_id,'hr.leave_request.create','leave','leave_request',v_id,'medium','Leave request created.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'leaveRequestId',v_id,'totalDays',v_days);
end $$;


--
-- Name: ac360_school_create_message_campaign(uuid, uuid, text, text, text, text, text, text, text, text, jsonb, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_create_message_campaign(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_template_key text DEFAULT NULL::text, p_campaign_code text DEFAULT NULL::text, p_campaign_type text DEFAULT 'announcement'::text, p_channel text DEFAULT 'email'::text, p_audience_type text DEFAULT 'parents'::text, p_title text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_variables jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_campaign public.ac360_school_message_campaigns%rowtype;
  v_template public.ac360_school_message_templates%rowtype;
  v_render jsonb;
  v_code text := coalesce(nullif(trim(p_campaign_code),''), 'CMP-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,8));
  v_message public.ac360_school_messages%rowtype;
  v_subject text := p_subject;
  v_body text := p_body;
  v_title text := coalesce(nullif(trim(p_title),''), 'Campagne communication');
begin
  if p_template_key is not null then
    select * into v_template from public.ac360_school_message_templates where org_id=p_org_id and template_key=p_template_key and status in ('published','draft') order by updated_at desc limit 1;
    if found then
      v_render := public.ac360_school_render_message_template(p_org_id, p_template_key, p_variables);
      v_subject := coalesce(v_subject, v_render->>'subject');
      v_body := coalesce(v_body, v_render->>'body');
      p_channel := coalesce(nullif(p_channel,''), v_template.channel);
      p_audience_type := coalesce(nullif(p_audience_type,''), v_template.audience_type);
      p_campaign_type := coalesce(nullif(p_campaign_type,''), v_template.template_type);
    end if;
  end if;

  if nullif(trim(coalesce(v_body,'')),'') is null then
    raise exception 'campaign body is required';
  end if;

  insert into public.ac360_school_messages(org_id,campus_id,message_code,channel,audience_type,subject,body,status,recipient_count,scheduled_at,created_by,metadata_json)
  values (p_org_id,p_campus_id,'MSG-' || v_code,case when p_channel='omnichannel' then 'internal' else p_channel end,coalesce(p_audience_type,'parents'),v_subject,v_body,case when p_scheduled_at is null then 'draft' else 'scheduled' end,0,p_scheduled_at,p_actor_app_user_id,jsonb_build_object('source','phase_2e_campaign','campaign_code',v_code) || coalesce(p_metadata,'{}'::jsonb))
  on conflict (org_id, message_code) do update set
    subject=excluded.subject, body=excluded.body, status=excluded.status, scheduled_at=excluded.scheduled_at, metadata_json=public.ac360_school_messages.metadata_json || excluded.metadata_json, updated_at=now()
  returning * into v_message;

  insert into public.ac360_school_message_campaigns(org_id,campus_id,template_id,message_id,campaign_code,campaign_type,channel,audience_type,title,subject,body,status,scheduled_at,created_by,metadata_json)
  values (p_org_id,p_campus_id,case when v_template.id is null then null else v_template.id end,v_message.id,v_code,coalesce(p_campaign_type,'announcement'),coalesce(p_channel,'email'),coalesce(p_audience_type,'parents'),v_title,v_subject,v_body,case when p_scheduled_at is null then 'draft' else 'scheduled' end,p_scheduled_at,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('uiBuildAllowed',false,'phase','phase_2e'))
  on conflict (org_id, campaign_code) do update set
    campus_id=excluded.campus_id,
    template_id=excluded.template_id,
    message_id=excluded.message_id,
    campaign_type=excluded.campaign_type,
    channel=excluded.channel,
    audience_type=excluded.audience_type,
    title=excluded.title,
    subject=excluded.subject,
    body=excluded.body,
    scheduled_at=excluded.scheduled_at,
    metadata_json=public.ac360_school_message_campaigns.metadata_json || excluded.metadata_json,
    updated_at=now()
  returning * into v_campaign;

  return jsonb_build_object('ok', true, 'campaign', to_jsonb(v_campaign), 'message', to_jsonb(v_message));
end $$;


