CREATE FUNCTION public.ac360_school_create_parent_request(p_org_id uuid, p_submission_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_guardian_id uuid DEFAULT NULL::uuid, p_request_key text DEFAULT NULL::text, p_request_type text DEFAULT 'general'::text, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_priority text DEFAULT 'medium'::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_assigned_to uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
