--
-- Name: ac360_school_current_capacity(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_current_capacity(p_org_id uuid, p_capacity_key text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_value numeric := 0;
begin
  if p_org_id is null then return 0; end if;

  if p_capacity_key = 'students' then
    select count(*)::numeric into v_value
    from public.ac360_school_students
    where org_id = p_org_id
      and status = 'active'
      and enrollment_status in ('pre_enrolled','enrolled','active');
  elsif p_capacity_key = 'staff_users' then
    select count(*)::numeric into v_value
    from public.ac360_school_staff_profiles
    where org_id = p_org_id
      and status = 'active'
      and employment_status in ('active','probation');
  elsif p_capacity_key = 'classes' then
    select count(*)::numeric into v_value
    from public.ac360_school_classes
    where org_id = p_org_id and status in ('active','full');
  elsif p_capacity_key = 'storage_gb' then
    select coalesce(sum(file_size_bytes),0)::numeric / 1073741824.0 into v_value
    from public.ac360_school_documents
    where org_id = p_org_id and status in ('active','pending_review','approved');
  elsif p_capacity_key = 'reports_monthly' then
    select count(*)::numeric into v_value
    from public.ac360_school_report_jobs
    where org_id = p_org_id
      and created_at >= date_trunc('month', now())
      and status <> 'archived';
  else
    select 0::numeric into v_value;
  end if;

  return greatest(coalesce(v_value,0),0);
end;
$$;


--
-- Name: ac360_school_decide_admission_offer(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_decide_admission_offer(p_org_id uuid, p_offer_id uuid, p_decision text, p_decision_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_lead_id uuid; v_status text; begin
  select lead_id into v_lead_id from public.ac360_school_admission_offers where id=p_offer_id and org_id=p_org_id;
  if v_lead_id is null then raise exception 'offer not found'; end if;
  v_status := case when p_decision in ('accept','accepted','approve','approved') then 'accepted' when p_decision in ('decline','declined','reject','rejected') then 'declined' else p_decision end;
  if v_status not in ('accepted','declined','expired','cancelled') then raise exception 'invalid offer decision'; end if;
  update public.ac360_school_admission_offers set status=v_status, decision_note=p_decision_note, decided_at=now(), updated_at=now() where id=p_offer_id and org_id=p_org_id;
  if v_status='accepted' then update public.ac360_school_admission_leads set lead_status='application', updated_at=now() where id=v_lead_id and org_id=p_org_id and lead_status not in ('converted','lost'); end if;
  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,to_status,actor_app_user_id,message,metadata_json) values(p_org_id,v_lead_id,'offer.decided','offer',v_status,p_actor_app_user_id,coalesce(p_decision_note,'Admission offer decided.'),coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'offer_id',p_offer_id,'lead_id',v_lead_id,'status',v_status);
end $$;


--
-- Name: ac360_school_decide_approval(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_decide_approval(p_org_id uuid, p_approval_request_id uuid, p_decision text, p_decision_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_req public.ac360_school_approval_requests%rowtype; v_dec public.ac360_school_approval_decisions%rowtype;
begin
  if p_org_id is null or p_approval_request_id is null then raise exception 'p_org_id and p_approval_request_id are required'; end if;
  select * into v_req from public.ac360_school_approval_requests where id=p_approval_request_id and org_id=p_org_id for update;
  if v_req.id is null then raise exception 'Approval request not found'; end if;
  insert into public.ac360_school_approval_decisions(org_id,approval_request_id,decision,decision_note,decided_by,metadata_json) values(p_org_id,p_approval_request_id,p_decision,p_decision_note,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_dec;
  if p_decision in ('approved','rejected','cancelled') then update public.ac360_school_approval_requests set status=p_decision, decided_at=now(), updated_at=now() where id=p_approval_request_id returning * into v_req; end if;
  return jsonb_build_object('ok',true,'approvalRequest',to_jsonb(v_req),'decision',to_jsonb(v_dec));
end; $$;


--
-- Name: ac360_school_decide_attendance_correction(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_decide_attendance_correction(p_org_id uuid, p_correction_id uuid, p_decision_status text, p_decision_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_correction record;
  v_event_type text;
begin
  if p_decision_status not in ('approved','rejected','cancelled') then
    return jsonb_build_object('ok', false, 'error', 'Decision must be approved, rejected or cancelled.');
  end if;

  select * into v_correction from public.ac360_school_attendance_corrections where id = p_correction_id and org_id = p_org_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'Correction request not found.'); end if;

  update public.ac360_school_attendance_corrections
  set decision_status = p_decision_status,
      decision_reason = p_decision_reason,
      decided_by = p_actor_app_user_id,
      decided_at = now(),
      metadata_json = metadata_json || coalesce(p_metadata,'{}'::jsonb)
  where id = p_correction_id;

  if p_decision_status = 'approved' then
    update public.ac360_school_attendance_records
    set attendance_status = coalesce(v_correction.requested_status, attendance_status),
        check_in_at = coalesce(v_correction.requested_check_in_at, check_in_at),
        check_out_at = coalesce(v_correction.requested_check_out_at, check_out_at),
        correction_status = 'approved',
        reason = coalesce(p_decision_reason, reason),
        metadata_json = metadata_json || jsonb_build_object('lastApprovedCorrectionId', p_correction_id)
    where id = v_correction.attendance_record_id;
    v_event_type := 'correction_approved';
  elsif p_decision_status = 'rejected' then
    update public.ac360_school_attendance_records set correction_status='rejected' where id = v_correction.attendance_record_id;
    v_event_type := 'correction_rejected';
  else
    update public.ac360_school_attendance_records set correction_status='none' where id = v_correction.attendance_record_id;
    v_event_type := 'correction_rejected';
  end if;

  insert into public.ac360_school_attendance_events(org_id, daybook_id, attendance_session_id, attendance_record_id, student_id, staff_profile_id, attendance_type, event_type, attendance_status, actor_app_user_id, reason, correction_id, metadata_json)
  values (p_org_id, v_correction.daybook_id, v_correction.attendance_session_id, v_correction.attendance_record_id, v_correction.student_id, v_correction.staff_profile_id, case when v_correction.staff_profile_id is not null then 'staff' else 'student' end, v_event_type, v_correction.requested_status, p_actor_app_user_id, p_decision_reason, p_correction_id, coalesce(p_metadata,'{}'::jsonb));

  perform public.ac360_school_refresh_daybook_counts(v_correction.daybook_id);
  return jsonb_build_object('ok', true, 'correctionId', p_correction_id, 'decisionStatus', p_decision_status);
end;
$$;


--
-- Name: ac360_school_decide_document_review(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_decide_document_review(p_org_id uuid, p_review_id uuid, p_decision text, p_decision_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_review public.ac360_school_document_review_requests%rowtype; v_status text;
begin
  v_status := case when lower(coalesce(p_decision,'')) in ('approve','approved') then 'approved' when lower(coalesce(p_decision,'')) in ('reject','rejected') then 'rejected' else null end;
  if v_status is null then raise exception 'Decision must be approved or rejected'; end if;
  update public.ac360_school_document_review_requests
  set status=v_status, decided_by=p_actor_app_user_id, decided_at=now(), decision_note=p_decision_note, metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now()
  where org_id=p_org_id and id=p_review_id
  returning * into v_review;
  if v_review.id is null then raise exception 'Review not found'; end if;
  update public.ac360_school_documents set status=v_status, review_status=v_status, updated_at=now() where id=v_review.document_id;
  return jsonb_build_object('ok',true,'review',to_jsonb(v_review));
end;
$$;


--
-- Name: ac360_school_decide_finance_adjustment(uuid, uuid, text, numeric, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_decide_finance_adjustment(p_org_id uuid, p_invoice_id uuid, p_adjustment_type text DEFAULT 'discount'::text, p_requested_amount_mad numeric DEFAULT 0, p_status text DEFAULT 'approved'::text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_adjustment public.ac360_school_finance_adjustments;
  v_code text := 'ADJ-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text, 1, 6);
  v_amount numeric := greatest(coalesce(p_requested_amount_mad,0),0);
begin
  insert into public.ac360_school_finance_adjustments(org_id, invoice_id, adjustment_code, adjustment_type, requested_amount_mad, approved_amount_mad, status, request_reason, decision_reason, requested_by, decided_by, decided_at, metadata_json)
  values (p_org_id, p_invoice_id, v_code, coalesce(p_adjustment_type,'discount'), v_amount, case when p_status in ('approved','applied') then v_amount else null end, coalesce(p_status,'approved'), p_reason, p_reason, p_actor_app_user_id, p_actor_app_user_id, now(), coalesce(p_metadata,'{}'::jsonb))
  returning * into v_adjustment;

  if p_status in ('approved','applied') and v_amount > 0 then
    update public.ac360_school_tuition_invoices
    set discount_mad = discount_mad + v_amount,
        total_mad = greatest(total_mad - v_amount, 0),
        status = case when paid_mad >= greatest(total_mad - v_amount,0) then 'paid' else status end,
        updated_at=now()
    where org_id=p_org_id and id=p_invoice_id;
  end if;

  insert into public.ac360_school_collection_events(org_id, invoice_id, event_type, event_channel, amount_mad, event_note, actor_app_user_id, metadata_json)
  values (p_org_id, p_invoice_id, 'adjustment', 'system', v_amount, p_reason, p_actor_app_user_id, jsonb_build_object('adjustment_id', v_adjustment.id, 'status', v_adjustment.status));

  return jsonb_build_object('ok', true, 'adjustment', to_jsonb(v_adjustment));
end $$;


--
-- Name: ac360_school_decide_leave_request(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_decide_leave_request(p_org_id uuid, p_leave_request_id uuid, p_decision text, p_decision_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_row public.ac360_school_leave_requests%rowtype; v_status text := case when lower(coalesce(p_decision,'')) in ('approve','approved') then 'approved' when lower(coalesce(p_decision,'')) in ('reject','rejected') then 'rejected' else coalesce(p_decision,'pending') end;
begin
  update public.ac360_school_leave_requests set status=v_status, decided_by=p_actor_app_user_id, decided_at=now(), decision_note=p_decision_note, metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now() where id=p_leave_request_id and org_id=p_org_id returning * into v_row;
  if v_row.id is null then return jsonb_build_object('ok',false,'error','Leave request not found.'); end if;
  insert into public.ac360_school_hr_events(org_id,staff_profile_id,event_key,event_type,related_entity_type,related_entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,v_row.staff_profile_id,'hr.leave_request.decide','leave','leave_request',v_row.id,'medium','Leave request ' || v_status || '.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'leaveRequestId',v_row.id,'status',v_status);
end $$;


--
-- Name: ac360_school_dispatch_campaign_batch(uuid, uuid, integer, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_dispatch_campaign_batch(p_org_id uuid, p_campaign_id uuid, p_limit integer DEFAULT 100, p_provider_key text DEFAULT 'internal_stub'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_campaign public.ac360_school_message_campaigns%rowtype;
  v_job public.ac360_school_delivery_jobs%rowtype;
  v_rec record;
  v_attempted integer := 0;
  v_succeeded integer := 0;
  v_failed integer := 0;
  v_channel text;
begin
  select * into v_campaign from public.ac360_school_message_campaigns where id=p_campaign_id and org_id=p_org_id;
  if not found then raise exception 'campaign not found'; end if;
  v_channel := case when v_campaign.channel='omnichannel' then 'internal' else v_campaign.channel end;

  insert into public.ac360_school_delivery_jobs(org_id,campaign_id,job_code,channel,provider_key,status,started_at,run_by,metadata_json)
  values (p_org_id,p_campaign_id,'JOB-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,8),v_channel,coalesce(p_provider_key,'internal_stub'),'running',now(),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning * into v_job;

  for v_rec in
    select * from public.ac360_school_message_recipients
    where org_id=p_org_id and campaign_id=p_campaign_id and status='queued'
    order by created_at asc
    limit greatest(1, least(coalesce(p_limit,100), 1000))
  loop
    v_attempted := v_attempted + 1;
    update public.ac360_school_message_recipients
      set status='dispatched', dispatched_at=now(), updated_at=now()
    where id=v_rec.id;

    insert into public.ac360_school_delivery_events(org_id,campaign_id,recipient_id,delivery_job_id,event_type,provider_key,event_payload_json)
    values (p_org_id,p_campaign_id,v_rec.id,v_job.id,'dispatched',coalesce(p_provider_key,'internal_stub'),jsonb_build_object('stub',true,'phase','phase_2e'));

    if v_rec.guardian_id is not null then
      insert into public.ac360_school_parent_notifications(org_id,campus_id,guardian_id,student_id,campaign_id,recipient_id,notification_code,notification_type,channel,title,body,priority,metadata_json)
      values (p_org_id,v_campaign.campus_id,v_rec.guardian_id,v_rec.student_id,p_campaign_id,v_rec.id,'NOTIF-' || substr(gen_random_uuid()::text,1,12),v_campaign.campaign_type,v_channel,v_campaign.title,v_campaign.body,case when v_campaign.campaign_type='emergency' then 'urgent' else 'normal' end,jsonb_build_object('source','campaign_dispatch','campaign_code',v_campaign.campaign_code));
    end if;
    v_succeeded := v_succeeded + 1;
  end loop;

  update public.ac360_school_delivery_jobs
  set status=case when v_failed > 0 and v_succeeded > 0 then 'partial' when v_failed > 0 then 'failed' else 'completed' end,
      attempted_count=v_attempted, succeeded_count=v_succeeded, failed_count=v_failed, completed_at=now(), updated_at=now()
  where id=v_job.id
  returning * into v_job;

  update public.ac360_school_message_campaigns
  set status=case when (select count(*) from public.ac360_school_message_recipients where campaign_id=p_campaign_id and status='queued') > 0 then 'partially_sent' else 'sent' end,
      dispatched_count=(select count(*) from public.ac360_school_message_recipients where campaign_id=p_campaign_id and status in ('dispatched','delivered','read')),
      queued_count=(select count(*) from public.ac360_school_message_recipients where campaign_id=p_campaign_id and status='queued'),
      sent_at=coalesce(sent_at, now()), updated_at=now()
  where id=p_campaign_id
  returning * into v_campaign;

  update public.ac360_school_messages
    set status='sent', sent_at=coalesce(sent_at, now()), updated_at=now()
  where id=v_campaign.message_id and org_id=p_org_id;

  return jsonb_build_object('ok', true, 'job', to_jsonb(v_job), 'campaign', to_jsonb(v_campaign), 'attemptedCount', v_attempted, 'dispatchedCount', v_succeeded);
end $$;


--
-- Name: ac360_school_documents_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_documents_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_storage_gb numeric := 0;
  v_latest_snapshot jsonb := '{}'::jsonb;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;

  select coalesce(sum(file_size_bytes),0)::numeric / 1073741824.0 into v_storage_gb
  from public.ac360_school_documents d
  where d.org_id = p_org_id
    and (p_campus_id is null or d.campus_id = p_campus_id)
    and d.status in ('active','pending_review','approved');

  select coalesce(to_jsonb(s), '{}'::jsonb) into v_latest_snapshot
  from public.ac360_school_storage_snapshots s
  where s.org_id = p_org_id and (p_campus_id is null or s.campus_id = p_campus_id)
  order by s.created_at desc
  limit 1;

  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2f_documents_reports_storage_exports',
    'uiBuildAllowed', false,
    'asOfDate', coalesce(p_as_of_date,current_date),
    'documents', jsonb_build_object(
      'active', (select count(*) from public.ac360_school_documents where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('active','approved','pending_review')),
      'archived', (select count(*) from public.ac360_school_documents where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='archived'),
      'pendingReview', (select count(*) from public.ac360_school_document_review_requests where org_id=p_org_id and status='pending'),
      'folders', (select count(*) from public.ac360_school_document_folders where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='active')
    ),
    'reports', jsonb_build_object(
      'templates', (select count(*) from public.ac360_school_report_templates where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status <> 'archived'),
      'queued', (select count(*) from public.ac360_school_report_jobs where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('queued','running')),
      'generated', (select count(*) from public.ac360_school_report_jobs where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='generated'),
      'artifacts', (select count(*) from public.ac360_school_report_artifacts where org_id=p_org_id and status='generated')
    ),
    'exports', jsonb_build_object(
      'queued', (select count(*) from public.ac360_school_export_jobs where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('queued','running')),
      'ready', (select count(*) from public.ac360_school_export_jobs where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='ready'),
      'failed', (select count(*) from public.ac360_school_export_jobs where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='failed')
    ),
    'storage', jsonb_build_object(
      'currentGb', round(coalesce(v_storage_gb,0), 4),
      'latestSnapshot', v_latest_snapshot
    ),
    'alerts', jsonb_build_object(
      'open', (select count(*) from public.ac360_school_document_alerts where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('open','in_progress')),
      'critical', (select count(*) from public.ac360_school_document_alerts where org_id=p_org_id and severity='critical' and status in ('open','in_progress'))
    ),
    'checkedAt', now()
  );
end;
$$;


--
-- Name: ac360_school_emit_smart_alert(uuid, uuid, text, text, text, text, text, text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_emit_smart_alert(p_org_id uuid, p_rule_id uuid DEFAULT NULL::uuid, p_alert_key text DEFAULT NULL::text, p_target_module text DEFAULT 'general'::text, p_alert_type text DEFAULT 'operational'::text, p_severity text DEFAULT 'warning'::text, p_title text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid, p_recommendation_json jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_record public.ac360_school_smart_alerts%rowtype;
begin
  insert into public.ac360_school_smart_alerts(org_id,rule_id,alert_key,target_module,alert_type,severity,title,message,target_entity_type,target_entity_id,recommendation_json,metadata_json) values(p_org_id,p_rule_id,coalesce(nullif(p_alert_key,''),'smart-alert-'||substr(gen_random_uuid()::text,1,10)),coalesce(p_target_module,'general'),coalesce(p_alert_type,'operational'),coalesce(p_severity,'warning'),coalesce(nullif(p_title,''),'Smart alert'),p_message,p_target_entity_type,p_target_entity_id,coalesce(p_recommendation_json,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb)) on conflict(org_id,alert_key) do update set severity=excluded.severity,title=excluded.title,message=excluded.message,recommendation_json=excluded.recommendation_json,status='open',metadata_json=public.ac360_school_smart_alerts.metadata_json||excluded.metadata_json,updated_at=now() returning * into v_record;
  return jsonb_build_object('ok',true,'smartAlert',to_jsonb(v_record));
end $$;


--
-- Name: ac360_school_enqueue_campaign_recipients(uuid, uuid, jsonb, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_enqueue_campaign_recipients(p_org_id uuid, p_campaign_id uuid, p_recipients jsonb DEFAULT '[]'::jsonb, p_class_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_campaign public.ac360_school_message_campaigns%rowtype;
  v_count integer := 0;
  v_item jsonb;
  v_channel text;
  v_contact text;
  v_pref text;
begin
  select * into v_campaign from public.ac360_school_message_campaigns where id=p_campaign_id and org_id=p_org_id;
  if not found then raise exception 'campaign not found'; end if;
  v_channel := case when v_campaign.channel='omnichannel' then 'internal' else v_campaign.channel end;

  if jsonb_typeof(coalesce(p_recipients,'[]'::jsonb)) = 'array' and jsonb_array_length(coalesce(p_recipients,'[]'::jsonb)) > 0 then
    for v_item in select * from jsonb_array_elements(p_recipients) loop
      v_contact := coalesce(v_item->>'contactValue', v_item->>'contact_value', v_item->>'email', v_item->>'whatsapp', v_item->>'phone');
      insert into public.ac360_school_message_recipients(org_id,campaign_id,recipient_code,recipient_type,recipient_id,student_id,guardian_id,staff_id,class_id,display_name,channel,contact_value,preference_status,metadata_json)
      values (p_org_id,p_campaign_id,'REC-' || substr(gen_random_uuid()::text,1,12),coalesce(v_item->>'recipientType',v_item->>'recipient_type','custom'),nullif(coalesce(v_item->>'recipientId',v_item->>'recipient_id'),'')::uuid,nullif(coalesce(v_item->>'studentId',v_item->>'student_id'),'')::uuid,nullif(coalesce(v_item->>'guardianId',v_item->>'guardian_id'),'')::uuid,nullif(coalesce(v_item->>'staffId',v_item->>'staff_id'),'')::uuid,p_class_id,coalesce(v_item->>'displayName',v_item->>'display_name'),v_channel,v_contact,'allowed',coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('source','manual_recipients'))
      on conflict (org_id, recipient_code) do nothing;
      v_count := v_count + 1;
    end loop;
  elsif v_campaign.audience_type in ('parents','student','class') then
    for v_item in
      select jsonb_build_object('guardian_id',g.id,'student_id',sg.student_id,'display_name',g.full_name,'contact',case when v_channel='email' then g.email when v_channel='sms' then g.phone when v_channel='whatsapp' then coalesce(g.whatsapp,g.phone) else null end,'pref',coalesce(np.consent_status,'implicit'))
      from public.ac360_school_guardians g
      left join public.ac360_school_student_guardians sg on sg.guardian_id=g.id and sg.status='active'
      left join public.ac360_school_class_enrollments ce on ce.student_id=sg.student_id and ce.status='active'
      left join public.ac360_school_notification_preferences np on np.org_id=p_org_id and np.recipient_type='guardian' and np.recipient_id=g.id and np.channel=v_channel
      where g.org_id=p_org_id and g.status='active'
        and (p_student_id is null or sg.student_id=p_student_id)
        and (p_class_id is null or ce.class_id=p_class_id)
        and coalesce(np.is_enabled,true)=true
        and coalesce(np.consent_status,'implicit') <> 'opted_out'
    loop
      insert into public.ac360_school_message_recipients(org_id,campaign_id,recipient_code,recipient_type,recipient_id,student_id,guardian_id,class_id,display_name,channel,contact_value,preference_status,metadata_json)
      values (p_org_id,p_campaign_id,'REC-' || substr(gen_random_uuid()::text,1,12),'guardian',(v_item->>'guardian_id')::uuid,(v_item->>'student_id')::uuid,(v_item->>'guardian_id')::uuid,p_class_id,v_item->>'display_name',v_channel,v_item->>'contact','allowed',coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('source','auto_parent_audience'));
      v_count := v_count + 1;
    end loop;
  elsif v_campaign.audience_type='staff' then
    for v_item in
      select jsonb_build_object('staff_id',s.id,'display_name',s.full_name,'contact',case when v_channel='email' then s.email when v_channel in ('sms','whatsapp') then s.phone else null end)
      from public.ac360_school_staff_profiles s
      where s.org_id=p_org_id and s.status='active'
    loop
      insert into public.ac360_school_message_recipients(org_id,campaign_id,recipient_code,recipient_type,recipient_id,staff_id,display_name,channel,contact_value,preference_status,metadata_json)
      values (p_org_id,p_campaign_id,'REC-' || substr(gen_random_uuid()::text,1,12),'staff',(v_item->>'staff_id')::uuid,(v_item->>'staff_id')::uuid,v_item->>'display_name',v_channel,v_item->>'contact','allowed',coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('source','auto_staff_audience'));
      v_count := v_count + 1;
    end loop;
  end if;

  update public.ac360_school_message_campaigns
  set recipient_count=(select count(*) from public.ac360_school_message_recipients where campaign_id=p_campaign_id),
      queued_count=(select count(*) from public.ac360_school_message_recipients where campaign_id=p_campaign_id and status='queued'),
      status='queued', queued_at=now(), updated_at=now()
  where id=p_campaign_id and org_id=p_org_id
  returning * into v_campaign;

  update public.ac360_school_messages
  set recipient_count=v_campaign.recipient_count, status='scheduled', updated_at=now()
  where id=v_campaign.message_id and org_id=p_org_id;

  return jsonb_build_object('ok', true, 'campaign', to_jsonb(v_campaign), 'enqueuedCount', v_count);
end $$;


--
-- Name: ac360_school_ensure_admissions_pipeline(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_ensure_admissions_pipeline(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_pipeline_id uuid;
  v_stage_id uuid;
begin
  if p_org_id is null then raise exception 'org_id is required'; end if;

  insert into public.ac360_school_admission_pipelines(org_id,campus_id,pipeline_key,label,pipeline_type,status,created_by,metadata_json)
  values(p_org_id,p_campus_id,'default','Default Admissions Pipeline','standard','active',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,pipeline_key) do update set status='active', updated_at=now()
  returning id into v_pipeline_id;

  if v_pipeline_id is null then
    select id into v_pipeline_id from public.ac360_school_admission_pipelines where org_id=p_org_id and pipeline_key='default' limit 1;
  end if;

  insert into public.ac360_school_admission_stages(org_id,pipeline_id,stage_key,label,stage_type,position,is_conversion_stage,status) values
  (p_org_id,v_pipeline_id,'new','New lead','open',10,false,'active'),
  (p_org_id,v_pipeline_id,'qualified','Qualified','qualified',20,false,'active'),
  (p_org_id,v_pipeline_id,'visit_scheduled','Visit scheduled','visit',30,false,'active'),
  (p_org_id,v_pipeline_id,'offer_sent','Offer sent','offer',40,false,'active'),
  (p_org_id,v_pipeline_id,'application','Application','application',50,false,'active'),
  (p_org_id,v_pipeline_id,'converted','Converted','converted',60,true,'active'),
  (p_org_id,v_pipeline_id,'lost','Lost','lost',90,false,'active')
  on conflict(pipeline_id,stage_key) do update set label=excluded.label, stage_type=excluded.stage_type, position=excluded.position, is_conversion_stage=excluded.is_conversion_stage, status='active', updated_at=now();

  insert into public.ac360_school_admissions_sources(org_id,source_key,label,source_type,status)
  values
  (p_org_id,'manual','Manual entry','manual','active'),
  (p_org_id,'whatsapp','WhatsApp inquiry','whatsapp','active'),
  (p_org_id,'website','Website lead','website','active'),
  (p_org_id,'referral','Parent referral','referral','active')
  on conflict(org_id,source_key) do update set label=excluded.label, source_type=excluded.source_type, status='active', updated_at=now();

  return jsonb_build_object('ok',true,'pipeline_id',v_pipeline_id,'phase','phase_2h_admissions_crm');
end;
$$;


--
-- Name: ac360_school_finance_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_finance_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  with invoice_base as (
    select *
    from public.ac360_school_tuition_invoices i
    where i.org_id = p_org_id
      and (p_campus_id is null or i.campus_id = p_campus_id)
      and i.status not in ('cancelled','archived','draft')
  ), pay_base as (
    select p.*
    from public.ac360_school_fee_payments p
    where p.org_id = p_org_id
      and p.status not in ('cancelled','archived')
  )
  select jsonb_build_object(
    'org_id', p_org_id,
    'campus_id', p_campus_id,
    'as_of_date', coalesce(p_as_of_date, current_date),
    'invoice_count', coalesce((select count(*) from invoice_base), 0),
    'issued_count', coalesce((select count(*) from invoice_base where status in ('issued','sent','partially_paid','overdue')), 0),
    'paid_count', coalesce((select count(*) from invoice_base where status = 'paid'), 0),
    'overdue_count', coalesce((select count(*) from invoice_base where due_date < coalesce(p_as_of_date, current_date) and status in ('issued','sent','partially_paid','overdue')), 0),
    'total_invoiced_mad', coalesce((select sum(total_mad) from invoice_base), 0),
    'total_paid_mad', coalesce((select sum(paid_mad) from invoice_base), 0),
    'total_receivable_mad', coalesce((select sum(balance_mad) from invoice_base), 0),
    'overdue_receivable_mad', coalesce((select sum(balance_mad) from invoice_base where due_date < coalesce(p_as_of_date, current_date) and status in ('issued','sent','partially_paid','overdue')), 0),
    'payments_recorded_mad', coalesce((select sum(amount_mad) from pay_base), 0),
    'open_promises', coalesce((select count(*) from public.ac360_school_payment_promises where org_id = p_org_id and status='open'), 0),
    'open_collection_cases', coalesce((select count(*) from public.ac360_school_collection_cases where org_id = p_org_id and status='open'), 0),
    'open_alerts', coalesce((select count(*) from public.ac360_school_finance_alerts where org_id = p_org_id and status='open'), 0),
    'latest_snapshot', coalesce((select to_jsonb(s) from public.ac360_school_receivable_snapshots s where s.org_id=p_org_id and (p_campus_id is null or s.campus_id=p_campus_id) order by s.snapshot_date desc, s.created_at desc limit 1), '{}'::jsonb),
    'phase', 'phase_2d_finance_receivables_runtime',
    'uiBuildAllowed', false
  ) into v_result;
  return v_result;
end $$;


--
-- Name: ac360_school_find_or_create_daybook(uuid, uuid, uuid, uuid, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_find_or_create_daybook(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_class_id uuid DEFAULT NULL::uuid, p_academic_year_id uuid DEFAULT NULL::uuid, p_operation_date date DEFAULT CURRENT_DATE, p_daybook_key text DEFAULT 'daily'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_daybook_id uuid;
  v_policy_id uuid;
  v_academic_year_id uuid := p_academic_year_id;
begin
  if p_org_id is null then
    raise exception 'AC360 organization id is required for daybook.';
  end if;

  if v_academic_year_id is null then
    select id into v_academic_year_id
    from public.ac360_academic_years
    where org_id = p_org_id and status in ('active','planning')
    order by starts_on desc nulls last, created_at desc
    limit 1;
  end if;

  select id into v_policy_id
  from public.ac360_school_attendance_policy_profiles
  where org_id = p_org_id
    and (campus_id is not distinct from p_campus_id or campus_id is null)
    and status = 'active'
  order by case when campus_id is not null then 0 else 1 end, created_at desc
  limit 1;

  if v_policy_id is null then
    insert into public.ac360_school_attendance_policy_profiles(org_id, campus_id, policy_key, label, metadata_json)
    values (p_org_id, p_campus_id, 'default', 'Default attendance policy', jsonb_build_object('created_by_phase','phase_2c_attendance_presence_daily_ops'))
    on conflict (org_id, campus_id, policy_key) do update set status='active'
    returning id into v_policy_id;
  end if;

  select id into v_daybook_id
  from public.ac360_school_attendance_daybooks
  where org_id = p_org_id
    and campus_id is not distinct from p_campus_id
    and class_id is not distinct from p_class_id
    and operation_date = coalesce(p_operation_date, current_date)
    and daybook_key = coalesce(nullif(p_daybook_key,''), 'daily')
  limit 1;

  if v_daybook_id is null then
    insert into public.ac360_school_attendance_daybooks(
      org_id, campus_id, class_id, academic_year_id, attendance_policy_id, operation_date, daybook_key, opened_by, metadata_json
    ) values (
      p_org_id, p_campus_id, p_class_id, v_academic_year_id, v_policy_id, coalesce(p_operation_date, current_date), coalesce(nullif(p_daybook_key,''), 'daily'), p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb)
    ) returning id into v_daybook_id;
  else
    update public.ac360_school_attendance_daybooks
    set status = case when status in ('draft','archived') then 'open' else status end,
        attendance_policy_id = coalesce(attendance_policy_id, v_policy_id),
        metadata_json = metadata_json || coalesce(p_metadata,'{}'::jsonb)
    where id = v_daybook_id;
  end if;

  return v_daybook_id;
end;
$$;


--
-- Name: ac360_school_fulfill_staffing_request(uuid, uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_fulfill_staffing_request(p_org_id uuid, p_staffing_request_id uuid, p_fulfilled_by_staff_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'fulfilled'::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_row public.ac360_school_staffing_requests%rowtype;
begin
  update public.ac360_school_staffing_requests set fulfilled_by_staff_id=p_fulfilled_by_staff_id, status=coalesce(p_status,'fulfilled'), fulfilled_at=case when coalesce(p_status,'fulfilled')='fulfilled' then now() else fulfilled_at end, notes=coalesce(p_notes,notes), metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now() where id=p_staffing_request_id and org_id=p_org_id returning * into v_row;
  if v_row.id is null then return jsonb_build_object('ok',false,'error','Staffing request not found.'); end if;
  insert into public.ac360_school_hr_events(org_id,campus_id,staff_profile_id,event_key,event_type,related_entity_type,related_entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,v_row.campus_id,p_fulfilled_by_staff_id,'hr.staffing_request.fulfill','staffing','staffing_request',v_row.id,'medium','Staffing request updated to ' || v_row.status || '.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'staffingRequestId',v_row.id,'status',v_row.status);
end $$;


--
-- Name: ac360_school_generate_admission_offer(uuid, uuid, text, numeric, numeric, numeric, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_generate_admission_offer(p_org_id uuid, p_lead_id uuid, p_offer_type text DEFAULT 'standard'::text, p_registration_fee_mad numeric DEFAULT 0, p_tuition_monthly_mad numeric DEFAULT 0, p_discount_mad numeric DEFAULT 0, p_valid_until date DEFAULT NULL::date, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid; v_code text; begin
  if not exists(select 1 from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id) then raise exception 'lead not found'; end if;
  v_code := public.ac360_admissions_default_code('OFFER');
  insert into public.ac360_school_admission_offers(org_id,lead_id,offer_code,offer_type,registration_fee_mad,tuition_monthly_mad,discount_mad,valid_until,status,issued_at,created_by,metadata_json)
  values(p_org_id,p_lead_id,v_code,coalesce(nullif(p_offer_type,''),'standard'),coalesce(p_registration_fee_mad,0),coalesce(p_tuition_monthly_mad,0),coalesce(p_discount_mad,0),p_valid_until,'issued',now(),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  update public.ac360_school_admission_leads set lead_status='offer_sent', updated_at=now() where id=p_lead_id and org_id=p_org_id and lead_status not in ('converted','lost');
  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,to_status,actor_app_user_id,message,metadata_json) values(p_org_id,p_lead_id,'offer.issued','offer','offer_sent',p_actor_app_user_id,'Admission offer issued.',coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'offer_id',v_id,'offer_code',v_code,'status','issued');
end $$;


--
-- Name: ac360_school_generate_invoice_batch(uuid, uuid, uuid, date, text, numeric, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_generate_invoice_batch(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_billing_cycle_id uuid DEFAULT NULL::uuid, p_due_date date DEFAULT NULL::date, p_fee_key text DEFAULT NULL::text, p_default_amount_mad numeric DEFAULT NULL::numeric, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.ac360_school_invoice_batches;
  v_code text := 'BATCH-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text, 1, 6);
  v_student record;
  v_amount numeric := greatest(coalesce(p_default_amount_mad, 0), 0);
  v_invoice_result jsonb;
  v_count integer := 0;
  v_total numeric := 0;
  v_cycle public.ac360_school_billing_cycles;
begin
  if p_billing_cycle_id is not null then
    select * into v_cycle from public.ac360_school_billing_cycles where id=p_billing_cycle_id and org_id=p_org_id;
  end if;

  if v_amount <= 0 and p_fee_key is not null then
    select default_amount_mad into v_amount
    from public.ac360_school_fee_catalog
    where org_id=p_org_id and fee_key=p_fee_key and status='active'
    limit 1;
    v_amount := greatest(coalesce(v_amount,0),0);
  end if;

  insert into public.ac360_school_invoice_batches(org_id, campus_id, billing_cycle_id, batch_code, status, generated_by, generated_at, metadata_json)
  values (p_org_id, p_campus_id, p_billing_cycle_id, v_code, 'generated', p_actor_app_user_id, now(), coalesce(p_metadata,'{}'::jsonb))
  returning * into v_batch;

  for v_student in
    select s.*
    from public.ac360_school_students s
    where s.org_id=p_org_id
      and s.status='active'
      and s.enrollment_status in ('enrolled','active')
      and (p_campus_id is null or s.campus_id=p_campus_id)
  loop
    v_invoice_result := public.ac360_school_issue_invoice(
      p_org_id,
      v_student.id,
      null,
      v_student.campus_id,
      v_student.academic_year_id,
      p_billing_cycle_id,
      v_batch.id,
      null,
      'tuition',
      coalesce(p_due_date, v_cycle.invoice_due_date, current_date + 10),
      jsonb_build_array(jsonb_build_object('line_key', coalesce(p_fee_key,'tuition'), 'label', 'Monthly tuition', 'quantity', 1, 'unit_price_mad', v_amount, 'amount_mad', v_amount)),
      0,
      p_actor_app_user_id,
      jsonb_build_object('source','batch','batch_id',v_batch.id)
    );
    v_count := v_count + 1;
    v_total := v_total + v_amount;
  end loop;

  update public.ac360_school_invoice_batches
  set invoice_count=v_count, total_mad=v_total, updated_at=now()
  where id=v_batch.id
  returning * into v_batch;

  return jsonb_build_object('ok', true, 'batch', to_jsonb(v_batch), 'invoice_count', v_count, 'total_mad', v_total);
end $$;


--
-- Name: ac360_school_generate_recurring_tasks(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_generate_recurring_tasks(p_org_id uuid, p_rule_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_rule record; v_task public.ac360_school_tasks%rowtype; v_count integer := 0; v_code text;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  for v_rule in select * from public.ac360_school_recurring_task_rules where org_id=p_org_id and status='active' and (p_rule_id is null or id=p_rule_id) loop
    v_code := 'TASK-REC-'||to_char(now(),'YYYYMMDDHH24MISS')||'-'||substr(gen_random_uuid()::text,1,6);
    insert into public.ac360_school_tasks(org_id,campus_id,task_code,title,description,department,status,priority,assigned_staff_id,due_at,created_by,source_rule_id,metadata_json)
    values(v_rule.org_id,v_rule.campus_id,v_code,coalesce(v_rule.task_template_json->>'title',v_rule.label),v_rule.task_template_json->>'description',coalesce(v_rule.department,v_rule.task_template_json->>'department'),'planned',coalesce(v_rule.task_template_json->>'priority','medium'),null,(current_date + interval '1 day')::timestamptz,p_actor_app_user_id,v_rule.id,jsonb_build_object('generatedFromRule',v_rule.rule_key,'phase','phase_2g') || coalesce(p_metadata,'{}'::jsonb)) returning * into v_task;
    update public.ac360_school_recurring_task_rules set last_run_on=current_date, next_run_on=case cadence when 'daily' then current_date + 1 when 'weekly' then current_date + 7 when 'monthly' then (current_date + interval '1 month')::date when 'quarterly' then (current_date + interval '3 months')::date when 'annual' then (current_date + interval '1 year')::date else next_run_on end, updated_at=now() where id=v_rule.id;
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('ok',true,'generatedCount',v_count);
end; $$;


--
-- Name: ac360_school_health_safety_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_health_safety_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_students integer:=0; v_profiles integer:=0; v_missing integer:=0; v_med integer:=0; v_pickups integer:=0; v_open integer:=0; v_critical integer:=0; v_checks integer:=0; v_alerts integer:=0;
begin
  select count(*) into v_students from public.ac360_school_students where org_id=p_org_id and enrollment_status in ('enrolled','active') and status='active' and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_profiles from public.ac360_school_health_profiles hp join public.ac360_school_students s on s.id=hp.student_id where hp.org_id=p_org_id and hp.status in ('active','needs_review','restricted') and (p_campus_id is null or s.campus_id=p_campus_id);
  v_missing := greatest(v_students - v_profiles,0);
  select count(*) into v_med from public.ac360_school_medication_plans mp join public.ac360_school_students s on s.id=mp.student_id where mp.org_id=p_org_id and mp.status='active' and (mp.ends_on is null or mp.ends_on>=p_as_of_date) and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_pickups from public.ac360_school_authorized_pickups ap join public.ac360_school_students s on s.id=ap.student_id where ap.org_id=p_org_id and ap.status='active' and ap.authorization_status in ('authorized','temporary') and (ap.valid_until is null or ap.valid_until>=p_as_of_date) and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_open from public.ac360_school_incident_reports where org_id=p_org_id and status in ('open','under_review','parent_notified') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_critical from public.ac360_school_incident_reports where org_id=p_org_id and status in ('open','under_review','parent_notified') and severity in ('high','critical') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_checks from public.ac360_school_safety_checks where org_id=p_org_id and checked_at::date=p_as_of_date and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_alerts from public.ac360_school_health_safety_alerts where org_id=p_org_id and status in ('open','in_review') and (p_campus_id is null or campus_id=p_campus_id);
  return jsonb_build_object('ok',true,'phase','phase_2j_health_safety_incidents_medical_pickup','uiBuildAllowed',false,'asOfDate',p_as_of_date,'students',v_students,'activeHealthProfiles',v_profiles,'missingHealthProfiles',v_missing,'activeMedicationPlans',v_med,'authorizedPickups',v_pickups,'openIncidents',v_open,'criticalIncidents',v_critical,'safetyChecksToday',v_checks,'openAlerts',v_alerts);
end $$;


--
-- Name: ac360_school_hr_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_hr_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_active_staff integer := 0;
  v_scheduled_today integer := 0;
  v_pending_leaves integer := 0;
  v_open_staffing integer := 0;
  v_missing_contracts integer := 0;
  v_open_alerts integer := 0;
begin
  select count(*) into v_active_staff from public.ac360_school_staff_profiles s where s.org_id=p_org_id and s.status='active' and s.employment_status in ('active','probation') and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_scheduled_today from public.ac360_school_staff_shift_assignments a where a.org_id=p_org_id and a.assignment_date=coalesce(p_as_of_date,current_date) and a.status in ('scheduled','confirmed','checked_in') and (p_campus_id is null or a.campus_id=p_campus_id);
  select count(*) into v_pending_leaves from public.ac360_school_leave_requests lr join public.ac360_school_staff_profiles s on s.id=lr.staff_profile_id where lr.org_id=p_org_id and lr.status='pending' and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_open_staffing from public.ac360_school_staffing_requests r where r.org_id=p_org_id and r.status in ('open','assigned') and (p_campus_id is null or r.campus_id=p_campus_id);
  select count(*) into v_missing_contracts from public.ac360_school_staff_profiles s left join public.ac360_school_staff_contracts c on c.staff_profile_id=s.id and c.status='active' where s.org_id=p_org_id and s.status='active' and s.employment_status in ('active','probation') and c.id is null and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_open_alerts from public.ac360_school_hr_alerts a where a.org_id=p_org_id and a.status='open' and (p_campus_id is null or a.campus_id=p_campus_id);

  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2i_hr_staff_scheduling_leave_staffing',
    'uiBuildAllowed', false,
    'asOfDate', coalesce(p_as_of_date,current_date),
    'summary', jsonb_build_object(
      'activeStaff', v_active_staff,
      'scheduledToday', v_scheduled_today,
      'pendingLeaveRequests', v_pending_leaves,
      'openStaffingRequests', v_open_staffing,
      'missingContracts', v_missing_contracts,
      'openAlerts', v_open_alerts
    ),
    'latestAlerts', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id, alert_key, alert_type, severity, title, message, created_at from public.ac360_school_hr_alerts where org_id=p_org_id and status='open' and (p_campus_id is null or campus_id=p_campus_id) order by created_at desc limit 20) x), '[]'::jsonb)
  );
end $$;


--
-- Name: ac360_school_intake_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_intake_dashboard(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_forms int; v_sources int; v_received int; v_unprocessed int; v_converted int; v_requests int; v_critical int; v_alerts int; v_snapshot public.ac360_school_intake_snapshots%rowtype;
begin
  select count(*) into v_forms from public.ac360_school_intake_forms where org_id=p_org_id and status='published';
  select count(*) into v_sources from public.ac360_school_external_intake_sources where org_id=p_org_id and status='active';
  select count(*) into v_received from public.ac360_school_intake_submissions where org_id=p_org_id and created_at::date=coalesce(p_as_of_date,current_date);
  select count(*) into v_unprocessed from public.ac360_school_intake_submissions where org_id=p_org_id and status in ('received','validated','processing');
  select count(*) into v_converted from public.ac360_school_intake_submissions where org_id=p_org_id and status='converted';
  select count(*) into v_requests from public.ac360_school_parent_requests where org_id=p_org_id and status in ('open','in_review','waiting_parent');
  select count(*) into v_critical from public.ac360_school_parent_requests where org_id=p_org_id and status in ('open','in_review','waiting_parent') and priority='critical';
  select count(*) into v_alerts from public.ac360_school_intake_alerts where org_id=p_org_id and status='open';

  insert into public.ac360_school_intake_snapshots(org_id,snapshot_date,published_forms,active_sources,received_submissions,unprocessed_submissions,converted_submissions,open_parent_requests,critical_parent_requests,metadata_json)
  values(p_org_id,coalesce(p_as_of_date,current_date),v_forms,v_sources,v_received,v_unprocessed,v_converted,v_requests,v_critical,jsonb_build_object('open_alerts',v_alerts,'phase','phase_2o'))
  on conflict(org_id,snapshot_date) do update set published_forms=excluded.published_forms,active_sources=excluded.active_sources,received_submissions=excluded.received_submissions,unprocessed_submissions=excluded.unprocessed_submissions,converted_submissions=excluded.converted_submissions,open_parent_requests=excluded.open_parent_requests,critical_parent_requests=excluded.critical_parent_requests,metadata_json=public.ac360_school_intake_snapshots.metadata_json||excluded.metadata_json,created_at=now()
  returning * into v_snapshot;

  return jsonb_build_object('ok',true,'snapshot',to_jsonb(v_snapshot),'open_alerts',v_alerts);
end $$;


--
-- Name: ac360_school_issue_api_key(uuid, text, text[], timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_issue_api_key(p_org_id uuid, p_label text DEFAULT NULL::text, p_scopes text[] DEFAULT '{}'::text[], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_raw text := encode(gen_random_bytes(24),'hex'); v_prefix text := 'ac360_'||substr(encode(gen_random_bytes(6),'hex'),1,12); v_key public.ac360_school_api_keys%rowtype;
begin
  insert into public.ac360_school_api_keys(org_id,api_key_prefix,api_key_hash,label,scopes,expires_at,created_by,metadata_json)
  values(p_org_id,v_prefix,crypt(v_raw,gen_salt('bf')),coalesce(nullif(p_label,''),'API Key'),coalesce(p_scopes,'{}'),p_expires_at,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_key;
  return jsonb_build_object('ok',true,'api_key',to_jsonb(v_key),'one_time_token',v_prefix || '_' || v_raw);
end $$;


--
-- Name: ac360_school_issue_invoice(uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, text, date, jsonb, numeric, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_issue_invoice(p_org_id uuid, p_student_id uuid, p_invoice_account_id uuid DEFAULT NULL::uuid, p_campus_id uuid DEFAULT NULL::uuid, p_academic_year_id uuid DEFAULT NULL::uuid, p_billing_cycle_id uuid DEFAULT NULL::uuid, p_invoice_batch_id uuid DEFAULT NULL::uuid, p_invoice_number text DEFAULT NULL::text, p_invoice_type text DEFAULT 'tuition'::text, p_due_date date DEFAULT NULL::date, p_lines jsonb DEFAULT '[]'::jsonb, p_discount_mad numeric DEFAULT 0, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice public.ac360_school_tuition_invoices;
  v_number text := coalesce(nullif(trim(p_invoice_number), ''), 'AC360-INV-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text, 1, 6));
  v_subtotal numeric := 0;
  v_line jsonb;
  v_line_count integer := 0;
  v_account_id uuid := p_invoice_account_id;
begin
  if p_student_id is null then
    raise exception 'student_id is required';
  end if;

  if v_account_id is null then
    select id into v_account_id
    from public.ac360_school_invoice_accounts
    where org_id = p_org_id and student_id = p_student_id and status = 'active'
    limit 1;
  end if;

  if v_account_id is null then
    insert into public.ac360_school_invoice_accounts(org_id, student_id, account_code, billing_cycle, status, metadata_json)
    values (p_org_id, p_student_id, 'ACC-' || substr(p_student_id::text,1,8), 'monthly', 'active', '{"auto_created_by":"phase_2d_finance"}'::jsonb)
    on conflict (org_id, student_id) do update set updated_at=now()
    returning id into v_account_id;
  end if;

  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'p_lines must be a JSON array';
  end if;

  for v_line in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_subtotal := v_subtotal + greatest(coalesce((v_line->>'amount_mad')::numeric, coalesce((v_line->>'quantity')::numeric,1) * coalesce((v_line->>'unit_price_mad')::numeric,0)), 0);
    v_line_count := v_line_count + 1;
  end loop;

  if v_line_count = 0 then
    v_subtotal := 0;
  end if;

  insert into public.ac360_school_tuition_invoices(org_id, campus_id, academic_year_id, student_id, invoice_account_id, invoice_batch_id, billing_cycle_id, invoice_number, invoice_type, status, due_date, subtotal_mad, discount_mad, total_mad, generated_by, metadata_json)
  values (p_org_id, p_campus_id, p_academic_year_id, p_student_id, v_account_id, p_invoice_batch_id, p_billing_cycle_id, v_number, coalesce(p_invoice_type,'tuition'), 'issued', p_due_date, v_subtotal, greatest(coalesce(p_discount_mad,0),0), greatest(v_subtotal - greatest(coalesce(p_discount_mad,0),0),0), p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb))
  returning * into v_invoice;

  for v_line in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    insert into public.ac360_school_tuition_invoice_lines(org_id, invoice_id, line_key, label, quantity, unit_price_mad, amount_mad, metadata_json)
    values (
      p_org_id,
      v_invoice.id,
      coalesce(nullif(v_line->>'line_key',''), 'line-' || substr(gen_random_uuid()::text,1,8)),
      coalesce(nullif(v_line->>'label',''), 'Fee line'),
      coalesce((v_line->>'quantity')::numeric, 1),
      coalesce((v_line->>'unit_price_mad')::numeric, 0),
      greatest(coalesce((v_line->>'amount_mad')::numeric, coalesce((v_line->>'quantity')::numeric,1) * coalesce((v_line->>'unit_price_mad')::numeric,0)), 0),
      coalesce(v_line->'metadata_json', '{}'::jsonb)
    );
  end loop;

  insert into public.ac360_school_operation_events(org_id, student_id, event_type, event_source, title, description, metadata_json)
  values (p_org_id, p_student_id, 'finance_invoice_issued', 'phase_2d_finance', 'Invoice issued', 'Finance runtime issued invoice ' || v_invoice.invoice_number, jsonb_build_object('invoice_id', v_invoice.id, 'invoice_number', v_invoice.invoice_number, 'total_mad', v_invoice.total_mad));

  return jsonb_build_object('ok', true, 'invoice', to_jsonb(v_invoice), 'line_count', v_line_count);
end $$;


--
-- Name: ac360_school_launch_parenttrust_survey(uuid, uuid, uuid, text, text, text, jsonb, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_launch_parenttrust_survey(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_template_id uuid DEFAULT NULL::uuid, p_survey_key text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_survey_type text DEFAULT 'satisfaction'::text, p_audience_json jsonb DEFAULT '{}'::jsonb, p_closes_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_key text;
begin
  v_key := coalesce(nullif(p_survey_key,''),'pt-survey-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,4));
  insert into public.ac360_school_parenttrust_surveys(org_id,campus_id,template_id,survey_key,title,survey_type,audience_json,launched_at,closes_at,status,created_by,metadata_json)
  values(p_org_id,p_campus_id,p_template_id,v_key,coalesce(nullif(p_title,''),'ParentTrust Survey'),coalesce(p_survey_type,'satisfaction'),coalesce(p_audience_json,'{}'::jsonb),now(),p_closes_at,'launched',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  return jsonb_build_object('ok',true,'surveyId',v_id,'surveyKey',v_key,'status','launched');
end $$;


--
-- Name: ac360_school_lifecycle_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_lifecycle_dashboard(p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_org_id uuid := p_org_id;
  v_counts jsonb := '{}'::jsonb;
  v_latest_integrity jsonb := null;
  v_recent_events jsonb := '[]'::jsonb;
  v_class_capacity jsonb := '[]'::jsonb;
  v_wiring_count integer := 0;
begin
  select count(*) into v_wiring_count from public.ac360_app_action_wiring where wiring_key like 'ac360.school_lifecycle.%' and status='active';

  if v_org_id is not null then
    v_counts := jsonb_build_object(
      'activeStudents', public.ac360_school_current_capacity(v_org_id, 'students'),
      'guardians', (select count(*) from public.ac360_school_guardians where org_id = v_org_id and status = 'active'),
      'guardianLinks', (select count(*) from public.ac360_school_student_guardians where org_id = v_org_id and status = 'active'),
      'activeClasses', public.ac360_school_current_capacity(v_org_id, 'classes'),
      'activeEnrollments', (select count(*) from public.ac360_school_class_enrollments where org_id = v_org_id and status = 'active'),
      'lifecycleEvents', (select count(*) from public.ac360_school_lifecycle_events where org_id = v_org_id),
      'transfers', (select count(*) from public.ac360_school_class_transfer_events where org_id = v_org_id),
      'integrityRuns', (select count(*) from public.ac360_school_integrity_runs where org_id = v_org_id)
    );

    select to_jsonb(r) into v_latest_integrity
    from public.ac360_school_integrity_runs r where r.org_id = v_org_id order by r.created_at desc limit 1;

    select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc), '[]'::jsonb) into v_recent_events
    from (select * from public.ac360_school_lifecycle_events where org_id = v_org_id order by created_at desc limit 25) e;

    select coalesce(jsonb_agg(to_jsonb(x) order by x.name), '[]'::jsonb) into v_class_capacity
    from (
      select c.id, c.class_code, c.name, c.status, c.capacity_students,
        count(e.id)::integer as active_enrollments,
        case when coalesce(c.capacity_students,0) > 0 then round((count(e.id)::numeric / c.capacity_students::numeric), 4) else null end as usage_ratio
      from public.ac360_school_classes c
      left join public.ac360_school_class_enrollments e on e.org_id = c.org_id and e.class_id = c.id and e.status='active'
      where c.org_id = v_org_id and c.status <> 'archived'
      group by c.id, c.class_code, c.name, c.status, c.capacity_students
      limit 100
    ) x;
  end if;

  return jsonb_build_object(
    'ok', v_wiring_count >= 8,
    'phase', 'phase_2b_student_parent_class_lifecycle',
    'uiBuildAllowed', false,
    'message', 'Phase 2B hardens student, parent and class lifecycle runtime only. UI remains locked until explicit user instructions.',
    'activeLifecycleWiringCount', v_wiring_count,
    'counts', v_counts,
    'latestIntegrityRun', v_latest_integrity,
    'recentLifecycleEvents', v_recent_events,
    'classCapacity', v_class_capacity,
    'checkedAt', now()
  );
end;
$$;


--
-- Name: ac360_school_link_admission_guardian(uuid, uuid, uuid, text, text, text, text, boolean, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_link_admission_guardian(p_org_id uuid, p_lead_id uuid, p_guardian_id uuid DEFAULT NULL::uuid, p_guardian_name text DEFAULT NULL::text, p_relationship text DEFAULT 'parent'::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_is_primary boolean DEFAULT false, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid; begin
  if not exists(select 1 from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id) then raise exception 'lead not found'; end if;
  insert into public.ac360_school_admission_lead_guardians(org_id,lead_id,guardian_id,guardian_name,relationship,phone,email,is_primary,consent_status,metadata_json)
  values(p_org_id,p_lead_id,p_guardian_id,coalesce(nullif(p_guardian_name,''),'Guardian'),coalesce(nullif(p_relationship,''),'parent'),p_phone,p_email,coalesce(p_is_primary,false),'pending',coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,actor_app_user_id,message,metadata_json) values(p_org_id,p_lead_id,'lead.guardian.linked','guardian_link',p_actor_app_user_id,'Guardian linked to admission lead.',coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'lead_guardian_id',v_id);
end $$;


--
-- Name: ac360_school_link_guardian(uuid, uuid, uuid, text, boolean, boolean, boolean, boolean, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_link_guardian(p_org_id uuid, p_student_id uuid, p_guardian_id uuid, p_relation_label text DEFAULT 'guardian'::text, p_is_primary boolean DEFAULT false, p_can_pickup boolean DEFAULT true, p_can_receive_billing boolean DEFAULT true, p_can_receive_reports boolean DEFAULT true, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_student public.ac360_school_students%rowtype;
  v_guardian public.ac360_school_guardians%rowtype;
  v_link public.ac360_school_student_guardians%rowtype;
  v_event_id uuid;
begin
  if p_org_id is null or p_student_id is null or p_guardian_id is null then raise exception 'p_org_id, p_student_id and p_guardian_id are required'; end if;
  select * into v_student from public.ac360_school_students where org_id = p_org_id and id = p_student_id;
  if v_student.id is null then raise exception 'Student not found for this organization'; end if;
  select * into v_guardian from public.ac360_school_guardians where org_id = p_org_id and id = p_guardian_id;
  if v_guardian.id is null then raise exception 'Guardian not found for this organization'; end if;

  if p_is_primary then
    update public.ac360_school_student_guardians set is_primary = false, updated_at = now() where org_id = p_org_id and student_id = p_student_id;
  end if;

  insert into public.ac360_school_student_guardians(org_id, student_id, guardian_id, relation_label, is_primary, can_pickup, can_receive_billing, can_receive_reports, status, metadata_json)
  values (p_org_id, p_student_id, p_guardian_id, coalesce(p_relation_label,'guardian'), coalesce(p_is_primary,false), coalesce(p_can_pickup,true), coalesce(p_can_receive_billing,true), coalesce(p_can_receive_reports,true), 'active', coalesce(p_metadata,'{}'::jsonb))
  on conflict (org_id, student_id, guardian_id) do update set
    relation_label = excluded.relation_label,
    is_primary = excluded.is_primary,
    can_pickup = excluded.can_pickup,
    can_receive_billing = excluded.can_receive_billing,
    can_receive_reports = excluded.can_receive_reports,
    status = 'active',
    metadata_json = public.ac360_school_student_guardians.metadata_json || excluded.metadata_json,
    updated_at = now()
  returning * into v_link;

  v_event_id := public.ac360_school_record_lifecycle_event(
    p_org_id, v_student.campus_id, 'family_link', v_link.id, 'school.guardian.link', null, 'active', null, null,
    'Guardian linked to student.', p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('studentId', p_student_id, 'guardianId', p_guardian_id)
  );

  return jsonb_build_object('ok', true, 'linkId', v_link.id, 'studentId', p_student_id, 'guardianId', p_guardian_id, 'eventId', v_event_id, 'isPrimary', v_link.is_primary);
end;
$$;


--
-- Name: ac360_school_mark_export_ready(uuid, uuid, text, bigint, integer, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_mark_export_ready(p_org_id uuid, p_export_job_id uuid, p_output_path text DEFAULT NULL::text, p_file_size_bytes bigint DEFAULT 0, p_row_count integer DEFAULT 0, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_export public.ac360_school_export_jobs%rowtype;
begin
  update public.ac360_school_export_jobs
  set status='ready', output_path=p_output_path, file_size_bytes=greatest(coalesce(p_file_size_bytes,0),0), row_count=greatest(coalesce(p_row_count,0),0), completed_at=now(), metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now()
  where org_id=p_org_id and id=p_export_job_id
  returning * into v_export;
  if v_export.id is null then raise exception 'Export job not found'; end if;
  return jsonb_build_object('ok',true,'exportJob',to_jsonb(v_export));
end;
$$;


--
-- Name: ac360_school_mark_invoice_overdue(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_mark_invoice_overdue(p_org_id uuid, p_invoice_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice public.ac360_school_tuition_invoices;
  v_alert_key text;
begin
  update public.ac360_school_tuition_invoices
  set status='overdue', updated_at=now(), metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb)
  where org_id=p_org_id and id=p_invoice_id and status in ('issued','sent','partially_paid','overdue')
  returning * into v_invoice;

  if not found then
    raise exception 'invoice not found or not overdue eligible';
  end if;

  v_alert_key := 'overdue-' || v_invoice.id::text;
  insert into public.ac360_school_finance_alerts(org_id, campus_id, student_id, invoice_id, alert_key, alert_type, severity, title, description, amount_mad, metadata_json)
  values (p_org_id, v_invoice.campus_id, v_invoice.student_id, v_invoice.id, v_alert_key, 'overdue_invoice', case when v_invoice.balance_mad >= 5000 then 'high' else 'medium' end, 'Overdue invoice', 'Invoice ' || v_invoice.invoice_number || ' is overdue.', v_invoice.balance_mad, jsonb_build_object('source','mark_invoice_overdue'))
  on conflict (org_id, alert_key) do update set amount_mad=excluded.amount_mad, severity=excluded.severity, status='open', updated_at=now();

  return jsonb_build_object('ok', true, 'invoice', to_jsonb(v_invoice));
end $$;


--
-- Name: ac360_school_mark_parent_notification_read(uuid, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_mark_parent_notification_read(p_org_id uuid, p_notification_id uuid, p_acknowledge boolean DEFAULT false, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_notification public.ac360_school_parent_notifications%rowtype;
begin
  update public.ac360_school_parent_notifications
  set status=case when coalesce(p_acknowledge,false) then 'acknowledged' else 'read' end,
      read_at=coalesce(read_at,now()),
      acknowledged_at=case when coalesce(p_acknowledge,false) then now() else acknowledged_at end,
      metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb),
      updated_at=now()
  where id=p_notification_id and org_id=p_org_id
  returning * into v_notification;
  if not found then raise exception 'notification not found'; end if;
  return jsonb_build_object('ok', true, 'notification', to_jsonb(v_notification));
end $$;


--
-- Name: ac360_school_onboarding_success_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_onboarding_success_dashboard(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_snapshot public.ac360_school_onboarding_success_snapshots%rowtype; v_alerts jsonb; v_projects jsonb;
begin
  insert into public.ac360_school_onboarding_success_snapshots(
    org_id,snapshot_date,migration_projects_total,migration_projects_completed,migration_records_total,migration_records_failed,onboarding_projects_active,onboarding_projects_live,setup_items_total,setup_items_completed,open_validation_findings,open_success_alerts,average_health_score,metadata_json
  )
  values(
    p_org_id,p_as_of_date,
    (select count(*) from public.ac360_school_migration_projects where org_id=p_org_id),
    (select count(*) from public.ac360_school_migration_projects where org_id=p_org_id and status='completed'),
    (select count(*) from public.ac360_school_migration_records where org_id=p_org_id),
    (select count(*) from public.ac360_school_migration_records where org_id=p_org_id and status='failed'),
    (select count(*) from public.ac360_school_onboarding_projects where org_id=p_org_id and status in ('planned','active','blocked','ready_for_go_live')),
    (select count(*) from public.ac360_school_onboarding_projects where org_id=p_org_id and status in ('live','completed')),
    (select count(*) from public.ac360_school_setup_items where org_id=p_org_id),
    (select count(*) from public.ac360_school_setup_items where org_id=p_org_id and status='completed'),
    (select count(*) from public.ac360_school_data_validation_findings where org_id=p_org_id and status in ('open','acknowledged')),
    (select count(*) from public.ac360_school_onboarding_success_alerts where org_id=p_org_id and status in ('open','acknowledged')),
    coalesce((select avg(health_score) from public.ac360_school_success_health_scores where org_id=p_org_id and score_date>=p_as_of_date-30),0),
    '{"phase":"phase_2q"}'::jsonb
  )
  on conflict(org_id,snapshot_date) do update set
    migration_projects_total=excluded.migration_projects_total,
    migration_projects_completed=excluded.migration_projects_completed,
    migration_records_total=excluded.migration_records_total,
    migration_records_failed=excluded.migration_records_failed,
    onboarding_projects_active=excluded.onboarding_projects_active,
    onboarding_projects_live=excluded.onboarding_projects_live,
    setup_items_total=excluded.setup_items_total,
    setup_items_completed=excluded.setup_items_completed,
    open_validation_findings=excluded.open_validation_findings,
    open_success_alerts=excluded.open_success_alerts,
    average_health_score=excluded.average_health_score,
    metadata_json=public.ac360_school_onboarding_success_snapshots.metadata_json||excluded.metadata_json,
    created_at=now()
  returning * into v_snapshot;

  select coalesce(jsonb_agg(to_jsonb(a) order by a.emitted_at desc),'[]'::jsonb) into v_alerts
  from (select * from public.ac360_school_onboarding_success_alerts where org_id=p_org_id and status in ('open','acknowledged') order by emitted_at desc limit 20) a;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc),'[]'::jsonb) into v_projects
  from (select id,onboarding_key,label,status,stage,progress_percent,risk_level,target_go_live_date,updated_at from public.ac360_school_onboarding_projects where org_id=p_org_id order by updated_at desc limit 15) p;

  return jsonb_build_object('ok',true,'snapshot',to_jsonb(v_snapshot),'alerts',v_alerts,'projects',v_projects);
end $$;


--
-- Name: ac360_school_open_attendance_session(uuid, uuid, uuid, uuid, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_attendance_session(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_class_id uuid DEFAULT NULL::uuid, p_academic_year_id uuid DEFAULT NULL::uuid, p_session_date date DEFAULT CURRENT_DATE, p_session_key text DEFAULT 'daily'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session_id uuid;
  v_daybook_id uuid;
  v_academic_year_id uuid := p_academic_year_id;
begin
  if p_org_id is null then
    return jsonb_build_object('ok', false, 'error', 'AC360 organization id is required.');
  end if;

  if v_academic_year_id is null then
    select id into v_academic_year_id
    from public.ac360_academic_years
    where org_id = p_org_id and status in ('active','planning')
    order by starts_on desc nulls last, created_at desc
    limit 1;
  end if;

  v_daybook_id := public.ac360_school_find_or_create_daybook(p_org_id, p_campus_id, p_class_id, v_academic_year_id, coalesce(p_session_date,current_date), coalesce(nullif(p_session_key,''),'daily'), p_actor_app_user_id, p_metadata);

  select id into v_session_id
  from public.ac360_school_attendance_sessions
  where org_id = p_org_id
    and campus_id is not distinct from p_campus_id
    and class_id is not distinct from p_class_id
    and session_date = coalesce(p_session_date, current_date)
    and session_key = coalesce(nullif(p_session_key,''),'daily')
  limit 1;

  if v_session_id is null then
    insert into public.ac360_school_attendance_sessions(
      org_id, campus_id, class_id, academic_year_id, session_date, session_key, status, opened_by, metadata_json
    ) values (
      p_org_id, p_campus_id, p_class_id, v_academic_year_id, coalesce(p_session_date, current_date), coalesce(nullif(p_session_key,''),'daily'), 'open', p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb)
    ) returning id into v_session_id;
  else
    update public.ac360_school_attendance_sessions
    set status = case when status in ('closed','locked') then status else 'open' end,
        metadata_json = metadata_json || coalesce(p_metadata,'{}'::jsonb)
    where id = v_session_id;
  end if;

  insert into public.ac360_school_attendance_events(org_id, daybook_id, attendance_session_id, event_type, attendance_type, actor_app_user_id, source, reason, metadata_json)
  values (p_org_id, v_daybook_id, v_session_id, 'session_opened', 'student', p_actor_app_user_id, 'system', 'Attendance session opened or confirmed.', coalesce(p_metadata,'{}'::jsonb));

  perform public.ac360_school_refresh_daybook_counts(v_daybook_id);

  return jsonb_build_object('ok', true, 'sessionId', v_session_id, 'daybookId', v_daybook_id, 'status', 'open');
end;
$$;


--
-- Name: ac360_school_open_billing_cycle(uuid, uuid, uuid, text, text, date, date, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_billing_cycle(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_academic_year_id uuid DEFAULT NULL::uuid, p_cycle_key text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_period_start date DEFAULT CURRENT_DATE, p_period_end date DEFAULT NULL::date, p_invoice_due_date date DEFAULT NULL::date, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text := coalesce(nullif(trim(p_cycle_key), ''), 'cycle-' || to_char(coalesce(p_period_start,current_date), 'YYYY-MM') || '-' || substr(gen_random_uuid()::text, 1, 6));
  v_end date := coalesce(p_period_end, (date_trunc('month', coalesce(p_period_start,current_date)) + interval '1 month - 1 day')::date);
  v_row public.ac360_school_billing_cycles;
begin
  insert into public.ac360_school_billing_cycles(org_id, campus_id, academic_year_id, cycle_key, label, period_start, period_end, invoice_due_date, status, opened_by, metadata_json)
  values (p_org_id, p_campus_id, p_academic_year_id, v_key, coalesce(nullif(trim(p_label), ''), v_key), coalesce(p_period_start,current_date), v_end, p_invoice_due_date, 'open', p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb))
  on conflict (org_id, cycle_key) do update set
    campus_id=excluded.campus_id,
    academic_year_id=excluded.academic_year_id,
    label=excluded.label,
    period_start=excluded.period_start,
    period_end=excluded.period_end,
    invoice_due_date=excluded.invoice_due_date,
    status='open',
    metadata_json=public.ac360_school_billing_cycles.metadata_json || excluded.metadata_json,
    updated_at=now()
  returning * into v_row;
  return jsonb_build_object('ok', true, 'billing_cycle', to_jsonb(v_row));
end $$;


--
-- Name: ac360_school_open_communication_thread(uuid, uuid, text, text, uuid, uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_communication_thread(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_thread_type text DEFAULT 'parent_conversation'::text, p_subject text DEFAULT NULL::text, p_guardian_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_assigned_staff_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'normal'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_thread public.ac360_school_communication_threads%rowtype;
begin
  insert into public.ac360_school_communication_threads(org_id,campus_id,thread_code,thread_type,subject,guardian_id,student_id,assigned_staff_id,priority,opened_by,metadata_json)
  values (p_org_id,p_campus_id,'THR-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,8),coalesce(p_thread_type,'parent_conversation'),coalesce(nullif(trim(p_subject),''),'Conversation parent'),p_guardian_id,p_student_id,p_assigned_staff_id,coalesce(p_priority,'normal'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning * into v_thread;
  return jsonb_build_object('ok', true, 'thread', to_jsonb(v_thread));
end $$;


--
-- Name: ac360_school_open_onboarding_project(uuid, text, text, uuid, date, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_onboarding_project(p_org_id uuid, p_onboarding_key text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_migration_project_id uuid DEFAULT NULL::uuid, p_target_go_live_date date DEFAULT NULL::date, p_owner_name text DEFAULT NULL::text, p_owner_email text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_project public.ac360_school_onboarding_projects%rowtype; v_key text;
begin
  v_key := coalesce(nullif(p_onboarding_key,''),'onboarding-'||to_char(now(),'YYYYMMDDHH24MISS'));
  insert into public.ac360_school_onboarding_projects(org_id,migration_project_id,onboarding_key,label,status,stage,kickoff_date,target_go_live_date,owner_name,owner_email,created_by,metadata_json)
  values(p_org_id,p_migration_project_id,v_key,coalesce(nullif(p_label,''),'School onboarding project'),'active','kickoff',current_date,p_target_go_live_date,p_owner_name,p_owner_email,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)||'{"phase":"phase_2q"}'::jsonb)
  on conflict(org_id,onboarding_key) do update set migration_project_id=excluded.migration_project_id,label=excluded.label,target_go_live_date=excluded.target_go_live_date,owner_name=excluded.owner_name,owner_email=excluded.owner_email,status='active',metadata_json=public.ac360_school_onboarding_projects.metadata_json||excluded.metadata_json,updated_at=now()
  returning * into v_project;

  insert into public.ac360_school_onboarding_steps(org_id,onboarding_project_id,step_key,label,step_group,sort_order,metadata_json) values
  (p_org_id,v_project.id,'kickoff_completed','Kickoff completed','kickoff',10,'{"seed":"default"}'::jsonb),
  (p_org_id,v_project.id,'data_collected','Data collected','data',20,'{"seed":"default"}'::jsonb),
  (p_org_id,v_project.id,'migration_validated','Migration validated','migration',30,'{"seed":"default"}'::jsonb),
  (p_org_id,v_project.id,'configuration_completed','Configuration completed','setup',40,'{"seed":"default"}'::jsonb),
  (p_org_id,v_project.id,'staff_trained','Staff trained','training',50,'{"seed":"default"}'::jsonb),
  (p_org_id,v_project.id,'go_live_confirmed','Go-live confirmed','go_live',60,'{"seed":"default"}'::jsonb)
  on conflict(onboarding_project_id,step_key) do nothing;

  return jsonb_build_object('ok',true,'onboarding_project',to_jsonb(v_project));
end $$;


