CREATE FUNCTION public.ac360_school_open_operation_ticket(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_ticket_code text DEFAULT NULL::text, p_ticket_type text DEFAULT 'operations'::text, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_severity text DEFAULT 'medium'::text, p_related_entity_type text DEFAULT NULL::text, p_related_entity_id uuid DEFAULT NULL::uuid, p_assigned_staff_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_ticket public.ac360_school_operations_tickets%rowtype; v_code text;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  v_code := coalesce(nullif(trim(p_ticket_code),''),'OPS-'||to_char(now(),'YYYYMMDDHH24MISS')||'-'||substr(gen_random_uuid()::text,1,6));
  insert into public.ac360_school_operations_tickets(org_id,campus_id,ticket_code,ticket_type,title,description,severity,related_entity_type,related_entity_id,assigned_staff_id,opened_by,metadata_json)
  values(p_org_id,p_campus_id,v_code,coalesce(p_ticket_type,'operations'),coalesce(nullif(trim(p_title),''),'Operations Ticket'),p_description,coalesce(p_severity,'medium'),p_related_entity_type,p_related_entity_id,p_assigned_staff_id,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_ticket;
  return jsonb_build_object('ok',true,'ticket',to_jsonb(v_ticket));
end; $$;


--
-- Name: ac360_school_open_parenttrust_complaint(uuid, uuid, uuid, uuid, text, text, text, text, text, uuid, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_parenttrust_complaint(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_guardian_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_category text DEFAULT 'general'::text, p_priority text DEFAULT 'medium'::text, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_source_channel text DEFAULT 'manual'::text, p_assigned_staff_id uuid DEFAULT NULL::uuid, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_code text;
begin
  v_code := 'PTC-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || upper(substr(gen_random_uuid()::text,1,4));
  insert into public.ac360_school_parenttrust_complaints(org_id,campus_id,guardian_id,student_id,complaint_code,category,priority,title,description,source_channel,assigned_staff_id,due_at,created_by,metadata_json)
  values(p_org_id,p_campus_id,p_guardian_id,p_student_id,v_code,coalesce(p_category,'general'),coalesce(p_priority,'medium'),coalesce(nullif(p_title,''),'ParentTrust complaint'),p_description,coalesce(p_source_channel,'manual'),p_assigned_staff_id,p_due_at,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  insert into public.ac360_school_parenttrust_complaint_events(org_id,complaint_id,event_type,to_status,note,actor_app_user_id,metadata_json) values(p_org_id,v_id,'opened','open','Complaint opened.',p_actor_app_user_id,'{}'::jsonb);
  if p_priority in ('high','critical') then
    insert into public.ac360_school_parenttrust_alerts(org_id,alert_key,severity,entity_type,entity_id,title,message,metadata_json) values(p_org_id,'parenttrust.high_priority_complaint',p_priority,'complaint',v_id,'High priority parent complaint','A high/critical ParentTrust complaint requires management attention.',jsonb_build_object('complaintCode',v_code));
  end if;
  return jsonb_build_object('ok',true,'complaintId',v_id,'complaintCode',v_code,'status','open');
end $$;


--
-- Name: ac360_school_open_staff_schedule_cycle(uuid, uuid, text, text, text, date, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_staff_schedule_cycle(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_cycle_key text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_cycle_type text DEFAULT 'weekly'::text, p_starts_on date DEFAULT CURRENT_DATE, p_ends_on date DEFAULT CURRENT_DATE, p_status text DEFAULT 'draft'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_key text := coalesce(nullif(trim(p_cycle_key),''),'cycle-' || to_char(coalesce(p_starts_on,current_date),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,6));
begin
  insert into public.ac360_school_staff_schedule_cycles(org_id,campus_id,cycle_key,label,cycle_type,starts_on,ends_on,status,published_at,created_by,metadata_json)
  values(p_org_id,p_campus_id,v_key,coalesce(nullif(trim(p_label),''),v_key),coalesce(p_cycle_type,'weekly'),coalesce(p_starts_on,current_date),coalesce(p_ends_on,coalesce(p_starts_on,current_date)),coalesce(p_status,'draft'),case when p_status='published' then now() else null end,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,cycle_key) do update set campus_id=excluded.campus_id,label=excluded.label,cycle_type=excluded.cycle_type,starts_on=excluded.starts_on,ends_on=excluded.ends_on,status=excluded.status,published_at=coalesce(public.ac360_school_staff_schedule_cycles.published_at, excluded.published_at),metadata_json=public.ac360_school_staff_schedule_cycles.metadata_json || excluded.metadata_json,updated_at=now()
  returning id into v_id;
  return jsonb_build_object('ok',true,'cycleId',v_id);
end $$;


--
-- Name: ac360_school_open_staffing_request(uuid, uuid, text, text, text, date, date, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_staffing_request(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_request_type text DEFAULT 'replacement'::text, p_role_needed text DEFAULT NULL::text, p_department text DEFAULT NULL::text, p_needed_from date DEFAULT NULL::date, p_needed_until date DEFAULT NULL::date, p_priority text DEFAULT 'medium'::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_code text := 'STF-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,6);
begin
  insert into public.ac360_school_staffing_requests(org_id,campus_id,request_code,request_type,role_needed,department,needed_from,needed_until,priority,status,requested_by,notes,metadata_json)
  values(p_org_id,p_campus_id,v_code,coalesce(p_request_type,'replacement'),coalesce(nullif(trim(p_role_needed),''),'Staff support'),p_department,p_needed_from,p_needed_until,coalesce(p_priority,'medium'),'open',p_actor_app_user_id,p_notes,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  insert into public.ac360_school_hr_events(org_id,campus_id,event_key,event_type,related_entity_type,related_entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_campus_id,'hr.staffing_request.open','staffing','staffing_request',v_id,'high','Staffing request opened.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'staffingRequestId',v_id);
end $$;


--
-- Name: ac360_school_open_transport_route_run(uuid, uuid, uuid, uuid, date, text, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_open_transport_route_run(p_org_id uuid, p_route_id uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_driver_id uuid DEFAULT NULL::uuid, p_run_date date DEFAULT CURRENT_DATE, p_run_type text DEFAULT 'pickup'::text, p_planned_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_vehicle uuid; v_driver uuid;
begin
  select default_vehicle_id, default_driver_id into v_vehicle, v_driver from public.ac360_school_transport_routes where id=p_route_id and org_id=p_org_id;
  insert into public.ac360_school_transport_route_runs(org_id,route_id,vehicle_id,driver_id,run_date,run_type,planned_start_at,started_at,status,created_by,metadata_json)
  values(p_org_id,p_route_id,coalesce(p_vehicle_id,v_vehicle),coalesce(p_driver_id,v_driver),coalesce(p_run_date,current_date),coalesce(p_run_type,'pickup'),p_planned_start_at,now(),'started',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning id into v_id;
  return jsonb_build_object('ok',true,'routeRunId',v_id,'status','started');
end $$;


--
-- Name: ac360_school_ops_readiness_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_ops_readiness_dashboard(p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_org_id uuid := p_org_id;
  v_counts jsonb := '{}'::jsonb;
  v_modules jsonb := '[]'::jsonb;
  v_wiring_count integer := 0;
  v_required_tables text[] := array[
    'ac360_school_students','ac360_school_guardians','ac360_school_student_guardians','ac360_school_staff_profiles',
    'ac360_school_classes','ac360_school_class_enrollments','ac360_school_attendance_sessions','ac360_school_attendance_records',
    'ac360_school_invoice_accounts','ac360_school_tuition_invoices','ac360_school_tuition_invoice_lines','ac360_school_fee_payments',
    'ac360_school_documents','ac360_school_report_jobs','ac360_school_messages','ac360_school_tasks','ac360_school_operation_events'
  ];
  v_missing text[] := '{}';
  t text;
begin
  foreach t in array v_required_tables loop
    if to_regclass('public.' || t) is null then
      v_missing := array_append(v_missing, t);
    end if;
  end loop;

  select count(*) into v_wiring_count
  from public.ac360_app_action_wiring
  where wiring_key like 'ac360.school_ops.%'
    and status = 'active';

  select coalesce(jsonb_agg(to_jsonb(m) order by m.module_key), '[]'::jsonb) into v_modules
  from public.ac360_school_ops_modules m;

  if v_org_id is not null then
    v_counts := jsonb_build_object(
      'students', public.ac360_school_current_capacity(v_org_id, 'students'),
      'staffUsers', public.ac360_school_current_capacity(v_org_id, 'staff_users'),
      'classes', public.ac360_school_current_capacity(v_org_id, 'classes'),
      'storageGb', round(public.ac360_school_current_capacity(v_org_id, 'storage_gb'), 4),
      'reportsThisMonth', public.ac360_school_current_capacity(v_org_id, 'reports_monthly'),
      'guardians', (select count(*) from public.ac360_school_guardians where org_id = v_org_id and status = 'active'),
      'attendanceRecords', (select count(*) from public.ac360_school_attendance_records where org_id = v_org_id),
      'schoolInvoices', (select count(*) from public.ac360_school_tuition_invoices where org_id = v_org_id and status <> 'archived'),
      'messages', (select count(*) from public.ac360_school_messages where org_id = v_org_id and status <> 'archived'),
      'tasks', (select count(*) from public.ac360_school_tasks where org_id = v_org_id and status <> 'archived')
    );
  end if;

  return jsonb_build_object(
    'ok', array_length(v_missing,1) is null and v_wiring_count >= 12,
    'phase', 'phase_2a_core_school_ops_skeleton',
    'uiBuildAllowed', false,
    'message', 'Phase 2A backend skeleton is DB-first and guarded. Front-end/UI build remains intentionally locked until user gives instructions.',
    'requiredTableCount', array_length(v_required_tables,1),
    'missingTables', coalesce(to_jsonb(v_missing), '[]'::jsonb),
    'activeSchoolOpsWiringCount', v_wiring_count,
    'modules', v_modules,
    'counts', v_counts,
    'checkedAt', now()
  );
end;
$$;


--
-- Name: ac360_school_parenttrust_dashboard(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_parenttrust_dashboard(p_org_id uuid, p_as_of_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_open_complaints integer := 0;
  v_critical integer := 0;
  v_surveys integer := 0;
  v_responses integer := 0;
  v_avg numeric := 0;
  v_nps numeric := 0;
  v_upcoming integer := 0;
  v_testimonials integer := 0;
  v_alerts integer := 0;
begin
  select count(*) into v_open_complaints from public.ac360_school_parenttrust_complaints where org_id=p_org_id and status in ('open','triaged','in_progress','waiting_parent','waiting_internal');
  select count(*) into v_critical from public.ac360_school_parenttrust_complaints where org_id=p_org_id and priority='critical' and status not in ('resolved','closed','cancelled','archived');
  select count(*) into v_surveys from public.ac360_school_parenttrust_surveys where org_id=p_org_id and status='launched';
  select count(*), coalesce(avg(score),0), coalesce(avg(nps_score),0) into v_responses, v_avg, v_nps from public.ac360_school_parenttrust_survey_responses where org_id=p_org_id and submitted_at::date <= coalesce(p_as_of_date,current_date);
  select count(*) into v_upcoming from public.ac360_school_parenttrust_appointments where org_id=p_org_id and status in ('scheduled','confirmed','rescheduled') and scheduled_at >= now();
  select count(*) into v_testimonials from public.ac360_school_parenttrust_testimonials where org_id=p_org_id and status in ('collected','approved','published');
  select count(*) into v_alerts from public.ac360_school_parenttrust_alerts where org_id=p_org_id and status='open';
  return jsonb_build_object('ok',true,'phase','phase_2l_parenttrust','uiBuildAllowed',false,'counts',jsonb_build_object('openComplaints',v_open_complaints,'criticalComplaints',v_critical,'launchedSurveys',v_surveys,'responses',v_responses,'averageScore',v_avg,'npsAverage',v_nps,'upcomingAppointments',v_upcoming,'testimonialsCollected',v_testimonials,'openAlerts',v_alerts));
end $$;


--
-- Name: ac360_school_post_thread_message(uuid, uuid, text, uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_post_thread_message(p_org_id uuid, p_thread_id uuid, p_sender_type text DEFAULT 'staff'::text, p_sender_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'internal'::text, p_body text DEFAULT NULL::text, p_attachments jsonb DEFAULT '[]'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_message public.ac360_school_thread_messages%rowtype;
  v_thread public.ac360_school_communication_threads%rowtype;
begin
  if nullif(trim(coalesce(p_body,'')),'') is null then raise exception 'thread message body is required'; end if;
  select * into v_thread from public.ac360_school_communication_threads where id=p_thread_id and org_id=p_org_id;
  if not found then raise exception 'thread not found'; end if;
  insert into public.ac360_school_thread_messages(org_id,thread_id,message_code,sender_type,sender_id,channel,body,attachments_json,metadata_json)
  values (p_org_id,p_thread_id,'THMSG-' || substr(gen_random_uuid()::text,1,12),coalesce(p_sender_type,'staff'),p_sender_id,coalesce(p_channel,'internal'),p_body,coalesce(p_attachments,'[]'::jsonb),coalesce(p_metadata,'{}'::jsonb))
  returning * into v_message;
  update public.ac360_school_communication_threads set last_message_at=now(), updated_at=now(), status=case when status='closed' then 'open' else status end where id=p_thread_id returning * into v_thread;
  return jsonb_build_object('ok', true, 'thread', to_jsonb(v_thread), 'message', to_jsonb(v_message));
end $$;


--
-- Name: ac360_school_process_lead_capture(uuid, uuid, uuid, text, text, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_process_lead_capture(p_org_id uuid, p_submission_id uuid, p_mapping_id uuid DEFAULT NULL::uuid, p_action_taken text DEFAULT 'captured'::text, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_result_json jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_event public.ac360_school_lead_capture_events%rowtype; v_key text;
begin
  v_key := 'lead-capture-'||coalesce(p_submission_id::text,substr(gen_random_uuid()::text,1,8))||'-'||substr(gen_random_uuid()::text,1,6);
  insert into public.ac360_school_lead_capture_events(org_id,submission_id,mapping_id,event_key,action_taken,target_entity_type,target_entity_id,result_json,metadata_json)
  values(p_org_id,p_submission_id,p_mapping_id,v_key,coalesce(nullif(p_action_taken,''),'captured'),p_target_entity_type,p_target_entity_id,coalesce(p_result_json,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb)) returning * into v_event;
  update public.ac360_school_intake_submissions set status=case when p_action_taken in ('converted_to_lead','created_request') then 'converted' when p_action_taken='flagged_duplicate' then 'duplicate' when p_action_taken='rejected' then 'rejected' else status end, linked_entity_type=coalesce(p_target_entity_type,linked_entity_type), linked_entity_id=coalesce(p_target_entity_id,linked_entity_id), processed_at=now(), updated_at=now() where id=p_submission_id and org_id=p_org_id;
  return jsonb_build_object('ok',true,'lead_capture_event',to_jsonb(v_event));
end $$;


--
-- Name: ac360_school_process_migration_record(uuid, uuid, integer, text, text, uuid, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_process_migration_record(p_org_id uuid, p_migration_batch_id uuid, p_source_row_number integer DEFAULT NULL::integer, p_source_identifier text DEFAULT NULL::text, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'processed'::text, p_raw_json jsonb DEFAULT '{}'::jsonb, p_mapped_json jsonb DEFAULT '{}'::jsonb, p_error_json jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_record public.ac360_school_migration_records%rowtype;
begin
  insert into public.ac360_school_migration_records(org_id,migration_batch_id,source_row_number,source_identifier,target_entity_type,target_entity_id,status,raw_json,mapped_json,error_json,processed_at,metadata_json)
  values(p_org_id,p_migration_batch_id,p_source_row_number,p_source_identifier,p_target_entity_type,p_target_entity_id,coalesce(nullif(p_status,''),'processed'),coalesce(p_raw_json,'{}'::jsonb),coalesce(p_mapped_json,'{}'::jsonb),coalesce(p_error_json,'{}'::jsonb),now(),coalesce(p_metadata,'{}'::jsonb)||'{"phase":"phase_2q"}'::jsonb)
  returning * into v_record;
  update public.ac360_school_migration_batches set processed_records=processed_records+1,successful_records=successful_records+case when v_record.status='processed' then 1 else 0 end,failed_records=failed_records+case when v_record.status='failed' then 1 else 0 end,duplicate_records=duplicate_records+case when v_record.status='duplicate' then 1 else 0 end,status=case when status='queued' then 'processing' else status end,started_at=coalesce(started_at,now()),updated_at=now() where id=p_migration_batch_id and org_id=p_org_id;
  return jsonb_build_object('ok',true,'migration_record',to_jsonb(v_record));
end $$;


--
-- Name: ac360_school_publish_intake_form(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_publish_intake_form(p_org_id uuid, p_form_id uuid, p_status text DEFAULT 'published'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_form public.ac360_school_intake_forms%rowtype;
begin
  update public.ac360_school_intake_forms set status=coalesce(nullif(p_status,''),'published'), published_at=case when coalesce(nullif(p_status,''),'published')='published' then coalesce(published_at,now()) else published_at end, metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb), updated_at=now() where id=p_form_id and org_id=p_org_id returning * into v_form;
  return jsonb_build_object('ok',v_form.id is not null,'form',to_jsonb(v_form));
end $$;


--
-- Name: ac360_school_queue_ai_job(uuid, uuid, text, text, text, text, uuid, jsonb, text, numeric, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_queue_ai_job(p_org_id uuid, p_prompt_template_id uuid DEFAULT NULL::uuid, p_job_key text DEFAULT NULL::text, p_job_type text DEFAULT 'message'::text, p_target_module text DEFAULT 'general'::text, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid, p_input_json jsonb DEFAULT '{}'::jsonb, p_requested_language text DEFAULT 'fr'::text, p_estimated_credit_cost numeric DEFAULT 10, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_record public.ac360_school_ai_jobs%rowtype;
begin
  insert into public.ac360_school_ai_jobs(org_id,prompt_template_id,job_key,job_type,target_module,target_entity_type,target_entity_id,input_json,requested_language,estimated_credit_cost,status,requested_by,metadata_json)
  values(p_org_id,p_prompt_template_id,coalesce(nullif(p_job_key,''),'AI-'||substr(gen_random_uuid()::text,1,10)),coalesce(p_job_type,'message'),coalesce(p_target_module,'general'),p_target_entity_type,p_target_entity_id,coalesce(p_input_json,'{}'::jsonb),coalesce(p_requested_language,'fr'),coalesce(p_estimated_credit_cost,10),'queued',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  returning * into v_record;
  insert into public.ac360_school_ai_job_events(org_id,ai_job_id,event_type,severity,message,actor_app_user_id,metadata_json) values(p_org_id,v_record.id,'queued','info','AI job queued.',p_actor_app_user_id,'{}'::jsonb);
  return jsonb_build_object('ok',true,'aiJob',to_jsonb(v_record));
