--
-- Name: ac360_school_queue_export_job(uuid, uuid, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_queue_export_job(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_export_code text DEFAULT NULL::text, p_export_type text DEFAULT 'data_export'::text, p_data_scope text DEFAULT 'organization'::text, p_output_format text DEFAULT 'xlsx'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_export public.ac360_school_export_jobs%rowtype; v_code text := coalesce(nullif(p_export_code,''),'EXP-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)));
begin
  insert into public.ac360_school_export_jobs(org_id,campus_id,export_code,export_type,data_scope,output_format,status,requested_by,metadata_json)
  values(p_org_id,p_campus_id,v_code,coalesce(p_export_type,'data_export'),coalesce(p_data_scope,'organization'),coalesce(p_output_format,'xlsx'),'queued',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id, export_code) do update set status='queued', metadata_json=public.ac360_school_export_jobs.metadata_json || excluded.metadata_json, updated_at=now()
  returning * into v_export;
  return jsonb_build_object('ok',true,'exportJob',to_jsonb(v_export));
end;
$$;


--
-- Name: ac360_school_queue_report_job(uuid, uuid, text, text, text, text, date, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_queue_report_job(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_template_key text DEFAULT NULL::text, p_report_code text DEFAULT NULL::text, p_report_type text DEFAULT 'standard'::text, p_title text DEFAULT NULL::text, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_job public.ac360_school_report_jobs%rowtype; v_template uuid; v_code text := coalesce(nullif(p_report_code,''),'RPT-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))); v_type text;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  select id into v_template from public.ac360_school_report_templates where org_id=p_org_id and template_key=p_template_key limit 1;
  v_type := case when coalesce(p_report_type,'standard') in ('standard','attendance','finance','student','classroom','executive','custom') then coalesce(p_report_type,'standard') else 'custom' end;
  insert into public.ac360_school_report_jobs(org_id,campus_id,template_id,report_code,report_type,title,status,requested_by,period_start,period_end,metadata_json)
  values(p_org_id,p_campus_id,v_template,v_code,v_type,coalesce(p_title,'AC360 Report'),'queued',p_actor_app_user_id,p_period_start,p_period_end,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id, report_code) do update set title=excluded.title, status='queued', template_id=excluded.template_id, updated_at=now()
  returning * into v_job;
  return jsonb_build_object('ok',true,'reportJob',to_jsonb(v_job));
end;
$$;


--
-- Name: ac360_school_reconcile_admissions(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_admissions(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_open integer; v_visits integer; v_offers integer; v_apps integer; v_converted integer; v_lost integer; v_overdue integer; v_dupes integer;
begin
  select count(*) into v_open from public.ac360_school_admission_leads where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='active' and lead_status not in ('converted','lost','archived');
  select count(*) into v_visits from public.ac360_school_admission_visits where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('scheduled','confirmed');
  select count(*) into v_offers from public.ac360_school_admission_offers o join public.ac360_school_admission_leads l on l.id=o.lead_id where o.org_id=p_org_id and (p_campus_id is null or l.campus_id=p_campus_id) and o.status='issued';
  select count(*) into v_apps from public.ac360_school_enrollment_applications a left join public.ac360_school_admission_leads l on l.id=a.lead_id where a.org_id=p_org_id and (p_campus_id is null or l.campus_id=p_campus_id) and a.status in ('submitted','in_review','approved');
  select count(*) into v_converted from public.ac360_school_admission_leads where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and converted_at >= date_trunc('month',now());
  select count(*) into v_lost from public.ac360_school_admission_leads where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='lost' and updated_at >= date_trunc('month',now());
  select count(*) into v_overdue from public.ac360_school_admission_followups f join public.ac360_school_admission_leads l on l.id=f.lead_id where f.org_id=p_org_id and (p_campus_id is null or l.campus_id=p_campus_id) and f.status='open' and f.due_at < now();
  select count(*) into v_dupes from public.ac360_school_admission_duplicate_findings where org_id=p_org_id and status='open';

  insert into public.ac360_school_admission_snapshots(org_id,campus_id,snapshot_date,leads_open,visits_scheduled,offers_issued,applications_open,converted_this_month,lost_this_month,overdue_followups,duplicate_findings_open,metadata_json)
  values(p_org_id,p_campus_id,current_date,v_open,v_visits,v_offers,v_apps,v_converted,v_lost,v_overdue,v_dupes,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,campus_id,snapshot_date) do update set leads_open=excluded.leads_open, visits_scheduled=excluded.visits_scheduled, offers_issued=excluded.offers_issued, applications_open=excluded.applications_open, converted_this_month=excluded.converted_this_month, lost_this_month=excluded.lost_this_month, overdue_followups=excluded.overdue_followups, duplicate_findings_open=excluded.duplicate_findings_open, metadata_json=public.ac360_school_admission_snapshots.metadata_json || excluded.metadata_json, created_at=now();

  if v_overdue > 0 then
    insert into public.ac360_school_admission_alerts(org_id,campus_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'admissions.overdue_followups.'||current_date,'followup_overdue',case when v_overdue >= 10 then 'high' else 'medium' end,'Admissions follow-ups overdue',v_overdue || ' admissions follow-ups are overdue.',jsonb_build_object('count',v_overdue))
    on conflict(org_id,alert_key) do update set severity=excluded.severity, message=excluded.message, status='open', updated_at=now();
  end if;
  if v_dupes > 0 then
    insert into public.ac360_school_admission_alerts(org_id,campus_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'admissions.duplicate_findings.'||current_date,'duplicate_lead','medium','Admissions duplicate findings',v_dupes || ' possible duplicate admission leads require review.',jsonb_build_object('count',v_dupes))
    on conflict(org_id,alert_key) do update set message=excluded.message, status='open', updated_at=now();
  end if;

  return jsonb_build_object('ok',true,'leads_open',v_open,'visits_scheduled',v_visits,'offers_issued',v_offers,'applications_open',v_apps,'converted_this_month',v_converted,'lost_this_month',v_lost,'overdue_followups',v_overdue,'duplicate_findings_open',v_dupes);
end $$;


--
-- Name: ac360_school_reconcile_branding_integrations(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_branding_integrations(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dash jsonb; v_pending int; v_errors int; v_failed int;
begin
  v_dash := public.ac360_school_branding_integrations_dashboard(p_org_id,p_as_of_date);
  v_pending := coalesce((v_dash #>> '{snapshot,pending_domains}')::int,0);
  v_errors := coalesce((v_dash #>> '{snapshot,connector_errors}')::int,0);
  v_failed := coalesce((v_dash #>> '{snapshot,failed_deliveries}')::int,0);
  if v_pending > 0 then
    insert into public.ac360_school_integration_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'pending-domain-verification-'||coalesce(p_as_of_date,current_date),'pending_domain_verification','warning','Pending custom domain verification',v_pending::text || ' custom domain(s) need DNS/SSL verification.',jsonb_build_object('count',v_pending))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;
  if v_errors > 0 or v_failed > 0 then
    insert into public.ac360_school_integration_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'integration-health-issues-'||coalesce(p_as_of_date,current_date),'integration_health_issues','critical','Integration health issues detected',(v_errors+v_failed)::text || ' integration issue(s) require review.',jsonb_build_object('connector_errors',v_errors,'failed_deliveries',v_failed))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;
  return jsonb_build_object('ok',true,'dashboard',v_dash,'pending_domains',v_pending,'connector_errors',v_errors,'failed_deliveries',v_failed);
end $$;


--
-- Name: ac360_school_reconcile_class_capacity(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_class_capacity(p_org_id uuid, p_class_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_class public.ac360_school_classes%rowtype;
  v_current numeric := 0;
  v_limit numeric;
  v_ratio numeric;
  v_decision text := 'unknown';
  v_snapshot_id uuid;
begin
  select * into v_class from public.ac360_school_classes where org_id = p_org_id and id = p_class_id for update;
  if v_class.id is null then raise exception 'Class not found for this organization'; end if;

  select count(*)::numeric into v_current
  from public.ac360_school_class_enrollments e
  join public.ac360_school_students s on s.id = e.student_id and s.org_id = e.org_id
  where e.org_id = p_org_id and e.class_id = p_class_id and e.status = 'active' and s.status = 'active' and s.enrollment_status in ('pre_enrolled','enrolled','active');

  v_limit := v_class.capacity_students;
  v_ratio := case when coalesce(v_limit,0) > 0 then v_current / v_limit else null end;
  v_decision := case
    when v_limit is null or v_limit <= 0 then 'unknown'
    when v_current > v_limit then 'over_limit'
    when v_current = v_limit then 'at_limit'
    when v_current >= (v_limit * 0.9) then 'near_limit'
    else 'ok'
  end;

  if v_class.status <> 'archived' then
    update public.ac360_school_classes
    set status = case when v_decision in ('at_limit','over_limit') then 'full' else 'active' end,
        metadata_json = metadata_json || jsonb_build_object('lastCapacityReconcileAt', now(), 'currentStudents', v_current, 'capacityDecision', v_decision),
        updated_at = now()
    where id = p_class_id and org_id = p_org_id;
  end if;

  insert into public.ac360_school_capacity_snapshots(org_id, campus_id, class_id, capacity_key, current_value, limit_value, usage_ratio, decision, source, metadata_json)
  values (p_org_id, v_class.campus_id, p_class_id, 'class_students', v_current, v_limit, v_ratio, v_decision, 'phase_2b_reconcile', coalesce(p_metadata,'{}'::jsonb))
  returning id into v_snapshot_id;

  insert into public.ac360_school_operation_events(org_id, campus_id, event_key, action_key, entity_type, entity_id, severity, message, actor_app_user_id, metadata_json)
  values (p_org_id, v_class.campus_id, 'phase2b.class.capacity_reconciled', 'school.class.capacity.reconcile', 'class', p_class_id, case when v_decision in ('over_limit','at_limit') then 'warning' else 'info' end, 'Class capacity reconciled.', p_actor_app_user_id, jsonb_build_object('snapshotId', v_snapshot_id, 'decision', v_decision, 'current', v_current, 'limit', v_limit));

  return jsonb_build_object('ok', true, 'classId', p_class_id, 'snapshotId', v_snapshot_id, 'currentStudents', v_current, 'capacityStudents', v_limit, 'usageRatio', v_ratio, 'decision', v_decision);
end;
$$;


--
-- Name: ac360_school_reconcile_health_safety(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_health_safety(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_students integer:=0; v_profiles integer:=0; v_missing integer:=0; v_med integer:=0; v_pickups integer:=0; v_open integer:=0; v_critical integer:=0; v_checks integer:=0;
begin
  select count(*) into v_students from public.ac360_school_students where org_id=p_org_id and enrollment_status in ('enrolled','active') and status='active' and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_profiles from public.ac360_school_health_profiles hp join public.ac360_school_students s on s.id=hp.student_id where hp.org_id=p_org_id and hp.status in ('active','needs_review','restricted') and (p_campus_id is null or s.campus_id=p_campus_id);
  v_missing := greatest(v_students - v_profiles,0);
  select count(*) into v_med from public.ac360_school_medication_plans mp join public.ac360_school_students s on s.id=mp.student_id where mp.org_id=p_org_id and mp.status='active' and (mp.ends_on is null or mp.ends_on>=current_date) and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_pickups from public.ac360_school_authorized_pickups ap join public.ac360_school_students s on s.id=ap.student_id where ap.org_id=p_org_id and ap.status='active' and ap.authorization_status in ('authorized','temporary') and (ap.valid_until is null or ap.valid_until>=current_date) and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_open from public.ac360_school_incident_reports where org_id=p_org_id and status in ('open','under_review','parent_notified') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_critical from public.ac360_school_incident_reports where org_id=p_org_id and status in ('open','under_review','parent_notified') and severity in ('high','critical') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_checks from public.ac360_school_safety_checks where org_id=p_org_id and checked_at::date=current_date and (p_campus_id is null or campus_id=p_campus_id);

  insert into public.ac360_school_health_safety_snapshots(org_id,campus_id,snapshot_date,active_health_profiles,active_medication_plans,authorized_pickups,open_incidents,critical_incidents,safety_checks_today,metadata_json)
  values(p_org_id,p_campus_id,current_date,v_profiles,v_med,v_pickups,v_open,v_critical,v_checks,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,campus_id,snapshot_date) do update set active_health_profiles=excluded.active_health_profiles,active_medication_plans=excluded.active_medication_plans,authorized_pickups=excluded.authorized_pickups,open_incidents=excluded.open_incidents,critical_incidents=excluded.critical_incidents,safety_checks_today=excluded.safety_checks_today,metadata_json=public.ac360_school_health_safety_snapshots.metadata_json || excluded.metadata_json;

  if v_missing > 0 then
    insert into public.ac360_school_health_safety_alerts(org_id,campus_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'missing-health-profiles-' || coalesce(p_campus_id::text,'all'),'missing_health_profile','high','Missing health profiles',v_missing || ' active student(s) have no health profile.',jsonb_build_object('missingHealthProfiles',v_missing))
    on conflict(org_id,alert_key) do update set status='open',severity=excluded.severity,title=excluded.title,message=excluded.message,metadata_json=public.ac360_school_health_safety_alerts.metadata_json || excluded.metadata_json,updated_at=now();
  end if;

  if v_critical > 0 then
    insert into public.ac360_school_health_safety_alerts(org_id,campus_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'critical-incidents-' || coalesce(p_campus_id::text,'all'),'critical_incident','critical','Critical incidents open',v_critical || ' high/critical incident(s) require review.',jsonb_build_object('criticalIncidents',v_critical))
    on conflict(org_id,alert_key) do update set status='open',severity=excluded.severity,title=excluded.title,message=excluded.message,metadata_json=public.ac360_school_health_safety_alerts.metadata_json || excluded.metadata_json,updated_at=now();
  end if;

  return jsonb_build_object('ok',true,'activeHealthProfiles',v_profiles,'missingHealthProfiles',v_missing,'activeMedicationPlans',v_med,'authorizedPickups',v_pickups,'openIncidents',v_open,'criticalIncidents',v_critical,'safetyChecksToday',v_checks);
end $$;


--
-- Name: ac360_school_reconcile_hr(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_hr(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_active integer:=0; v_sched integer:=0; v_leave integer:=0; v_staffing integer:=0; v_contracts integer:=0; v_missing integer:=0; v_alert_id uuid;
begin
  select count(*) into v_active from public.ac360_school_staff_profiles where org_id=p_org_id and status='active' and employment_status in ('active','probation') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_sched from public.ac360_school_staff_shift_assignments where org_id=p_org_id and assignment_date=current_date and status in ('scheduled','confirmed','checked_in') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_leave from public.ac360_school_leave_requests lr join public.ac360_school_staff_profiles s on s.id=lr.staff_profile_id where lr.org_id=p_org_id and lr.status='pending' and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_staffing from public.ac360_school_staffing_requests where org_id=p_org_id and status in ('open','assigned') and (p_campus_id is null or campus_id=p_campus_id);
  select count(*) into v_contracts from public.ac360_school_staff_contracts c join public.ac360_school_staff_profiles s on s.id=c.staff_profile_id where c.org_id=p_org_id and c.status='active' and (p_campus_id is null or s.campus_id=p_campus_id);
  select count(*) into v_missing from public.ac360_school_staff_profiles s left join public.ac360_school_staff_contracts c on c.staff_profile_id=s.id and c.status='active' where s.org_id=p_org_id and s.status='active' and s.employment_status in ('active','probation') and c.id is null and (p_campus_id is null or s.campus_id=p_campus_id);

  insert into public.ac360_school_hr_snapshots(org_id,campus_id,snapshot_date,active_staff_count,scheduled_shift_count,pending_leave_count,open_staffing_request_count,active_contract_count,metadata_json)
  values(p_org_id,p_campus_id,current_date,v_active,v_sched,v_leave,v_staffing,v_contracts,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,campus_id,snapshot_date) do update set active_staff_count=excluded.active_staff_count,scheduled_shift_count=excluded.scheduled_shift_count,pending_leave_count=excluded.pending_leave_count,open_staffing_request_count=excluded.open_staffing_request_count,active_contract_count=excluded.active_contract_count,metadata_json=public.ac360_school_hr_snapshots.metadata_json || excluded.metadata_json;

  if v_missing > 0 then
    insert into public.ac360_school_hr_alerts(org_id,campus_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'missing_contracts-' || coalesce(p_campus_id::text,'all'),'missing_contract','high','Staff contracts missing',v_missing || ' active staff profile(s) have no active contract.',jsonb_build_object('missingContracts',v_missing))
    on conflict(org_id,alert_key) do update set status='open',severity=excluded.severity,title=excluded.title,message=excluded.message,metadata_json=public.ac360_school_hr_alerts.metadata_json || excluded.metadata_json,updated_at=now()
    returning id into v_alert_id;
  end if;

  if v_staffing > 0 then
    insert into public.ac360_school_hr_alerts(org_id,campus_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'open_staffing-' || coalesce(p_campus_id::text,'all'),'staffing_gap','medium','Open staffing requests',v_staffing || ' staffing request(s) remain open.',jsonb_build_object('openStaffingRequests',v_staffing))
    on conflict(org_id,alert_key) do update set status='open',severity=excluded.severity,title=excluded.title,message=excluded.message,metadata_json=public.ac360_school_hr_alerts.metadata_json || excluded.metadata_json,updated_at=now();
  end if;

  insert into public.ac360_school_hr_events(org_id,campus_id,event_key,event_type,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_campus_id,'hr.reconcile','compliance','info','HR runtime reconciled.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'activeStaff',v_active,'scheduledToday',v_sched,'pendingLeaves',v_leave,'openStaffingRequests',v_staffing,'missingContracts',v_missing);
end $$;


--
-- Name: ac360_school_reconcile_intake(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_intake(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dash jsonb; v_unprocessed int; v_critical int;
begin
  v_dash := public.ac360_school_intake_dashboard(p_org_id,p_as_of_date);
  v_unprocessed := coalesce((v_dash #>> '{snapshot,unprocessed_submissions}')::int,0);
  v_critical := coalesce((v_dash #>> '{snapshot,critical_parent_requests}')::int,0);
  if v_unprocessed > 10 then
    insert into public.ac360_school_intake_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'unprocessed-intake-'||coalesce(p_as_of_date,current_date),'unprocessed_submissions','warning','Unprocessed intake submissions',v_unprocessed::text || ' intake submission(s) require processing.',jsonb_build_object('count',v_unprocessed))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;
  if v_critical > 0 then
    insert into public.ac360_school_intake_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'critical-parent-requests-'||coalesce(p_as_of_date,current_date),'critical_parent_requests','critical','Critical parent requests open',v_critical::text || ' critical parent request(s) need immediate response.',jsonb_build_object('count',v_critical))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;
  return jsonb_build_object('ok',true,'dashboard',v_dash,'unprocessed_submissions',v_unprocessed,'critical_parent_requests',v_critical);
end $$;


--
-- Name: ac360_school_reconcile_onboarding_success(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_onboarding_success(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dashboard jsonb; v_overdue int; v_failed int;
begin
  select count(*) into v_overdue from public.ac360_school_onboarding_projects where org_id=p_org_id and target_go_live_date is not null and target_go_live_date < coalesce(p_as_of_date,current_date) and status not in ('live','completed','cancelled','archived');
  select count(*) into v_failed from public.ac360_school_migration_records where org_id=p_org_id and status='failed';

  if v_overdue > 0 then
    insert into public.ac360_school_onboarding_success_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'phase2q.onboarding.overdue.'||coalesce(p_as_of_date,current_date)::text,'onboarding','warning','Onboarding go-live overdue',v_overdue||' onboarding project(s) are past target go-live date.',jsonb_build_object('overdue_projects',v_overdue,'phase','phase_2q'))
    on conflict(org_id,alert_key) do update set severity=excluded.severity,title=excluded.title,message=excluded.message,status='open',updated_at=now();
  end if;
  if v_failed > 0 then
    insert into public.ac360_school_onboarding_success_alerts(org_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,'phase2q.migration.failed_records.'||coalesce(p_as_of_date,current_date)::text,'migration','warning','Migration records need review',v_failed||' failed migration record(s) require correction.',jsonb_build_object('failed_records',v_failed,'phase','phase_2q'))
    on conflict(org_id,alert_key) do update set severity=excluded.severity,title=excluded.title,message=excluded.message,status='open',updated_at=now();
  end if;
  v_dashboard := public.ac360_school_onboarding_success_dashboard(p_org_id,coalesce(p_as_of_date,current_date));
  perform public.ac360_school_compute_success_health_score(p_org_id,coalesce(p_as_of_date,current_date),p_actor_app_user_id,p_metadata);
  return jsonb_build_object('ok',true,'dashboard',v_dashboard,'overdue_projects',v_overdue,'failed_records',v_failed);
end $$;


--
-- Name: ac360_school_reconcile_operations(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_operations(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_source_key text DEFAULT 'manual_reconcile'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_snapshot public.ac360_school_operations_snapshots%rowtype; v_overdue integer; v_blocked integer; v_pending integer; v_running integer; v_open_tickets integer; v_critical integer;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  select count(*) into v_overdue from public.ac360_school_tasks where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('planned','in_progress','blocked') and due_at is not null and due_at < now();
  select count(*) into v_blocked from public.ac360_school_tasks where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='blocked';
  select count(*) into v_pending from public.ac360_school_approval_requests where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='pending';
  select count(*) into v_running from public.ac360_school_workflow_instances where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('running','paused','blocked');
  select count(*) into v_open_tickets from public.ac360_school_operations_tickets where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('open','in_progress','blocked');
  select count(*) into v_critical from public.ac360_school_operations_tickets where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('open','in_progress','blocked') and severity='critical';
  insert into public.ac360_school_operations_snapshots(org_id,campus_id,snapshot_date,source_key,open_task_count,overdue_task_count,blocked_task_count,pending_approval_count,running_workflow_count,open_ticket_count,critical_ticket_count,metadata_json)
  values(p_org_id,p_campus_id,current_date,coalesce(p_source_key,'manual_reconcile'),(select count(*) from public.ac360_school_tasks where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('planned','in_progress','blocked')),v_overdue,v_blocked,v_pending,v_running,v_open_tickets,v_critical,coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id,campus_id,snapshot_date,source_key) do update set open_task_count=excluded.open_task_count,overdue_task_count=excluded.overdue_task_count,blocked_task_count=excluded.blocked_task_count,pending_approval_count=excluded.pending_approval_count,running_workflow_count=excluded.running_workflow_count,open_ticket_count=excluded.open_ticket_count,critical_ticket_count=excluded.critical_ticket_count,metadata_json=public.ac360_school_operations_snapshots.metadata_json || excluded.metadata_json,created_at=now()
  returning * into v_snapshot;
  if v_overdue > 0 then
    insert into public.ac360_school_operations_alerts(org_id,campus_id,alert_code,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'OPS-OVERDUE-'||current_date,'task_overdue','high','Overdue school operations tasks',v_overdue::text || ' open tasks are overdue.',jsonb_build_object('count',v_overdue,'phase','phase_2g'))
    on conflict(org_id,alert_code) do update set status='open',message=excluded.message,updated_at=now();
  end if;
  if v_critical > 0 then
    insert into public.ac360_school_operations_alerts(org_id,campus_id,alert_code,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,'OPS-CRITICAL-TICKETS-'||current_date,'ticket_critical','critical','Critical operations tickets open',v_critical::text || ' critical tickets require resolution.',jsonb_build_object('count',v_critical,'phase','phase_2g'))
    on conflict(org_id,alert_code) do update set status='open',message=excluded.message,updated_at=now();
  end if;
  return jsonb_build_object('ok',true,'snapshot',to_jsonb(v_snapshot));
end; $$;


--
-- Name: ac360_school_reconcile_parenttrust_runtime(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_parenttrust_runtime(p_org_id uuid, p_as_of_date date DEFAULT NULL::date, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_surveys integer:=0; v_responses integer:=0; v_avg numeric:=0; v_nps numeric:=0; v_open integer:=0; v_critical integer:=0; v_appts integer:=0; v_testimonials integer:=0; v_snapshot uuid;
begin
  select count(*) into v_surveys from public.ac360_school_parenttrust_surveys where org_id=p_org_id and status='launched';
  select count(*), coalesce(avg(score),0), coalesce(avg(nps_score),0) into v_responses, v_avg, v_nps from public.ac360_school_parenttrust_survey_responses where org_id=p_org_id;
  select count(*) into v_open from public.ac360_school_parenttrust_complaints where org_id=p_org_id and status in ('open','triaged','in_progress','waiting_parent','waiting_internal');
  select count(*) into v_critical from public.ac360_school_parenttrust_complaints where org_id=p_org_id and priority='critical' and status not in ('resolved','closed','cancelled','archived');
  select count(*) into v_appts from public.ac360_school_parenttrust_appointments where org_id=p_org_id and status in ('scheduled','confirmed','rescheduled') and scheduled_at >= now();
  select count(*) into v_testimonials from public.ac360_school_parenttrust_testimonials where org_id=p_org_id and status in ('collected','approved','published');
  insert into public.ac360_school_parenttrust_snapshots(org_id,snapshot_date,surveys_launched,responses_total,average_score,nps_average,complaints_open,complaints_critical,appointments_upcoming,testimonials_collected,metadata_json)
  values(p_org_id,coalesce(p_as_of_date,current_date),v_surveys,v_responses,v_avg,v_nps,v_open,v_critical,v_appts,v_testimonials,coalesce(p_metadata,'{}'::jsonb)) returning id into v_snapshot;
  if v_critical > 0 then
    insert into public.ac360_school_parenttrust_alerts(org_id,alert_key,severity,entity_type,title,message,metadata_json) values(p_org_id,'parenttrust.critical_complaints_open','critical','complaint','Critical ParentTrust complaints open','One or more critical parent complaints require immediate action.',jsonb_build_object('snapshotId',v_snapshot,'criticalComplaints',v_critical));
  end if;
  return jsonb_build_object('ok',true,'snapshotId',v_snapshot,'counts',jsonb_build_object('surveysLaunched',v_surveys,'responsesTotal',v_responses,'averageScore',v_avg,'npsAverage',v_nps,'complaintsOpen',v_open,'complaintsCritical',v_critical,'appointmentsUpcoming',v_appts,'testimonialsCollected',v_testimonials));
end $$;


--
-- Name: ac360_school_reconcile_receivables(uuid, uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_receivables(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_run_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run public.ac360_school_finance_reconcile_runs;
  v_code text := 'FIN-REC-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text, 1, 6);
  v_checked integer := 0;
  v_overdue integer := 0;
  v_total numeric := 0;
  v_paid numeric := 0;
  v_receivable numeric := 0;
  v_overdue_receivable numeric := 0;
  v_alerts integer := 0;
  v_invoice record;
begin
  insert into public.ac360_school_finance_reconcile_runs(org_id, campus_id, run_code, run_date, status, run_by, metadata_json)
  values (p_org_id, p_campus_id, v_code, coalesce(p_run_date,current_date), 'running', p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb))
  returning * into v_run;

  for v_invoice in
    select * from public.ac360_school_tuition_invoices
    where org_id=p_org_id
      and (p_campus_id is null or campus_id=p_campus_id)
      and status in ('issued','sent','partially_paid','overdue')
  loop
    v_checked := v_checked + 1;
    if v_invoice.due_date is not null and v_invoice.due_date < coalesce(p_run_date,current_date) and v_invoice.balance_mad > 0 then
      update public.ac360_school_tuition_invoices set status='overdue', updated_at=now() where id=v_invoice.id;
      v_overdue := v_overdue + 1;
      v_overdue_receivable := v_overdue_receivable + v_invoice.balance_mad;
      insert into public.ac360_school_finance_alerts(org_id, campus_id, student_id, invoice_id, alert_key, alert_type, severity, title, description, amount_mad, metadata_json)
      values (p_org_id, v_invoice.campus_id, v_invoice.student_id, v_invoice.id, 'overdue-' || v_invoice.id::text, 'overdue_invoice', case when v_invoice.balance_mad >= 5000 then 'high' else 'medium' end, 'Overdue invoice', 'Invoice ' || v_invoice.invoice_number || ' is overdue.', v_invoice.balance_mad, jsonb_build_object('source','receivables_reconcile','run_id',v_run.id))
      on conflict (org_id, alert_key) do update set amount_mad=excluded.amount_mad, severity=excluded.severity, status='open', updated_at=now();
      v_alerts := v_alerts + 1;
    end if;
  end loop;

  select coalesce(sum(total_mad),0), coalesce(sum(paid_mad),0), coalesce(sum(balance_mad),0)
  into v_total, v_paid, v_receivable
  from public.ac360_school_tuition_invoices
  where org_id=p_org_id
    and (p_campus_id is null or campus_id=p_campus_id)
    and status not in ('cancelled','archived','draft');

  insert into public.ac360_school_receivable_snapshots(org_id, campus_id, snapshot_date, active_invoice_count, overdue_invoice_count, total_invoiced_mad, total_paid_mad, total_receivable_mad, overdue_receivable_mad, promise_open_count, collection_case_open_count, metadata_json)
  values (
    p_org_id, p_campus_id, coalesce(p_run_date,current_date),
    coalesce((select count(*) from public.ac360_school_tuition_invoices where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status not in ('cancelled','archived','draft')),0),
    coalesce((select count(*) from public.ac360_school_tuition_invoices where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='overdue'),0),
    v_total, v_paid, v_receivable, v_overdue_receivable,
    coalesce((select count(*) from public.ac360_school_payment_promises where org_id=p_org_id and status='open'),0),
    coalesce((select count(*) from public.ac360_school_collection_cases where org_id=p_org_id and status='open'),0),
    jsonb_build_object('run_id', v_run.id)
  )
  on conflict (org_id, campus_id, snapshot_date) do update set
    active_invoice_count=excluded.active_invoice_count,
    overdue_invoice_count=excluded.overdue_invoice_count,
    total_invoiced_mad=excluded.total_invoiced_mad,
    total_paid_mad=excluded.total_paid_mad,
    total_receivable_mad=excluded.total_receivable_mad,
    overdue_receivable_mad=excluded.overdue_receivable_mad,
    promise_open_count=excluded.promise_open_count,
    collection_case_open_count=excluded.collection_case_open_count,
    metadata_json=public.ac360_school_receivable_snapshots.metadata_json || excluded.metadata_json;

  update public.ac360_school_finance_reconcile_runs
  set status='completed', invoices_checked=v_checked, overdue_marked=v_overdue, receivables_mad=v_receivable, payments_mad=v_paid, alerts_created=v_alerts, updated_at=now()
  where id=v_run.id
  returning * into v_run;

  return jsonb_build_object('ok', true, 'run', to_jsonb(v_run));
exception when others then
  update public.ac360_school_finance_reconcile_runs set status='failed', metadata_json=metadata_json || jsonb_build_object('error', sqlerrm), updated_at=now() where id=v_run.id;
  raise;
end $$;


--
-- Name: ac360_school_reconcile_storage(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_storage(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_source_key text DEFAULT 'manual_reconcile'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_active integer := 0; v_archived integer := 0; v_versions integer := 0; v_artifacts integer := 0; v_exports integer := 0; v_bytes bigint := 0; v_snapshot public.ac360_school_storage_snapshots%rowtype;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  select count(*), coalesce(sum(file_size_bytes),0) into v_active, v_bytes from public.ac360_school_documents where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('active','approved','pending_review');
  select count(*) into v_archived from public.ac360_school_documents where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='archived';
  select count(*) into v_versions from public.ac360_school_document_versions where org_id=p_org_id;
  select count(*) into v_artifacts from public.ac360_school_report_artifacts where org_id=p_org_id and status='generated';
  select count(*) into v_exports from public.ac360_school_export_jobs where org_id=p_org_id and status in ('ready','queued','running');

  insert into public.ac360_school_storage_snapshots(org_id,campus_id,snapshot_date,source_key,active_document_count,archived_document_count,version_count,report_artifact_count,export_job_count,total_bytes,total_gb,metadata_json)
  values(p_org_id,p_campus_id,current_date,coalesce(p_source_key,'manual_reconcile'),v_active,v_archived,v_versions,v_artifacts,v_exports,coalesce(v_bytes,0),(coalesce(v_bytes,0)::numeric/1073741824.0),coalesce(p_metadata,'{}'::jsonb))
  on conflict(org_id, campus_id, snapshot_date, source_key) do update set
    active_document_count=excluded.active_document_count,
    archived_document_count=excluded.archived_document_count,
    version_count=excluded.version_count,
    report_artifact_count=excluded.report_artifact_count,
    export_job_count=excluded.export_job_count,
    total_bytes=excluded.total_bytes,
    total_gb=excluded.total_gb,
    metadata_json=public.ac360_school_storage_snapshots.metadata_json || excluded.metadata_json
  returning * into v_snapshot;

  if v_snapshot.total_gb >= 4 then
    insert into public.ac360_school_document_alerts(org_id,campus_id,alert_code,alert_type,severity,status,title,message,metadata_json)
    values(p_org_id,p_campus_id,'STORAGE-' || to_char(current_date,'YYYYMMDD'),'storage_limit_warning','high','open','Storage usage requires review','Storage consumption is high. Review storage add-on or archive policy.',jsonb_build_object('totalGb',v_snapshot.total_gb,'phase','phase_2f'))
    on conflict(org_id, alert_code) do update set status='open', severity='high', message=excluded.message, metadata_json=public.ac360_school_document_alerts.metadata_json || excluded.metadata_json, updated_at=now();
  end if;

  return jsonb_build_object('ok',true,'snapshot',to_jsonb(v_snapshot));
end;
$$;


--
-- Name: ac360_school_reconcile_transport_billing(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_transport_billing(p_org_id uuid, p_billing_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count int;
begin
  insert into public.ac360_school_transport_billing_records(org_id,assignment_id,student_id,billing_month,amount_mad,status,metadata_json)
  select p_org_id, a.id, a.student_id, date_trunc('month',coalesce(p_billing_month,current_date))::date, coalesce(a.monthly_fee_mad,0), 'pending', coalesce(p_metadata,'{}'::jsonb)
  from public.ac360_school_transport_student_assignments a
  where a.org_id=p_org_id and a.status='active' and coalesce(a.monthly_fee_mad,0) > 0
  on conflict(org_id,assignment_id,billing_month) do update set amount_mad=excluded.amount_mad,metadata_json=public.ac360_school_transport_billing_records.metadata_json || excluded.metadata_json,updated_at=now();
  get diagnostics v_count = row_count;
  return jsonb_build_object('ok',true,'billingMonth',date_trunc('month',coalesce(p_billing_month,current_date))::date,'recordsTouched',v_count);
end $$;


--
-- Name: ac360_school_reconcile_transport_runtime(uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_reconcile_transport_runtime(p_org_id uuid, p_as_of_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_vehicles int; v_drivers int; v_routes int; v_assignments int; v_open_runs int; v_failed int; v_snapshot uuid;
begin
  select count(*) into v_vehicles from public.ac360_school_transport_vehicles where org_id=p_org_id and status='active';
  select count(*) into v_drivers from public.ac360_school_transport_drivers where org_id=p_org_id and status='active';
  select count(*) into v_routes from public.ac360_school_transport_routes where org_id=p_org_id and status='active';
  select count(*) into v_assignments from public.ac360_school_transport_student_assignments where org_id=p_org_id and status='active';
  select count(*) into v_open_runs from public.ac360_school_transport_route_runs where org_id=p_org_id and run_date=coalesce(p_as_of_date,current_date) and status in ('planned','started','in_progress','incident');
  select count(*) into v_failed from public.ac360_school_transport_safety_checks where org_id=p_org_id and checked_at::date=coalesce(p_as_of_date,current_date) and result in ('failed','blocked');
  insert into public.ac360_school_transport_snapshots(org_id,snapshot_date,vehicles_active,drivers_active,routes_active,assignments_active,open_runs,failed_safety_checks,metadata_json)
  values(p_org_id,coalesce(p_as_of_date,current_date),v_vehicles,v_drivers,v_routes,v_assignments,v_open_runs,v_failed,coalesce(p_metadata,'{}'::jsonb)) returning id into v_snapshot;
  if v_routes > 0 and v_drivers = 0 then
    insert into public.ac360_school_transport_alerts(org_id,alert_key,severity,entity_type,title,message,metadata_json) values(p_org_id,'transport.no_active_driver','high','driver','No active transport driver','At least one active route exists but no active driver is registered.',jsonb_build_object('snapshotId',v_snapshot));
  end if;
  return jsonb_build_object('ok',true,'snapshotId',v_snapshot,'counts',jsonb_build_object('vehiclesActive',v_vehicles,'driversActive',v_drivers,'routesActive',v_routes,'assignmentsActive',v_assignments,'openRuns',v_open_runs,'failedSafetyChecks',v_failed));
end $$;


--
-- Name: ac360_school_record_ai_job_event(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_record_ai_job_event(p_org_id uuid, p_ai_job_id uuid, p_event_type text, p_severity text DEFAULT 'info'::text, p_message text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_record public.ac360_school_ai_job_events%rowtype;
begin
  insert into public.ac360_school_ai_job_events(org_id,ai_job_id,event_type,severity,message,actor_app_user_id,metadata_json) values(p_org_id,p_ai_job_id,coalesce(p_event_type,'event'),coalesce(p_severity,'info'),p_message,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_record;
  return jsonb_build_object('ok',true,'event',to_jsonb(v_record));
end $$;


--
-- Name: ac360_school_record_attendance_event(uuid, uuid, uuid, uuid, uuid, text, text, text, timestamp with time zone, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_record_attendance_event(p_org_id uuid, p_attendance_session_id uuid DEFAULT NULL::uuid, p_daybook_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_staff_profile_id uuid DEFAULT NULL::uuid, p_attendance_type text DEFAULT NULL::text, p_event_type text DEFAULT 'check_in'::text, p_attendance_status text DEFAULT NULL::text, p_event_at timestamp with time zone DEFAULT now(), p_reason text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session record;
  v_session_id uuid := p_attendance_session_id;
  v_daybook_id uuid := p_daybook_id;
  v_type text := coalesce(nullif(p_attendance_type,''), case when p_staff_profile_id is not null then 'staff' else 'student' end);
  v_status text := p_attendance_status;
  v_record_id uuid;
  v_previous_status text;
begin
  if p_org_id is null then return jsonb_build_object('ok', false, 'error', 'AC360 organization id is required.'); end if;
  if p_student_id is null and p_staff_profile_id is null then return jsonb_build_object('ok', false, 'error', 'studentId or staffProfileId is required.'); end if;

  if v_status is null then
    v_status := case p_event_type
      when 'mark_absent' then 'absent'
      when 'mark_late' then 'late'
      when 'mark_early_out' then 'early_out'
      when 'mark_authorized_absence' then 'authorized_absence'
      when 'staff_check_in' then 'present'
      when 'staff_check_out' then 'present'
      when 'check_in' then 'present'
      when 'check_out' then null
      else 'present'
    end;
  end if;

  if v_session_id is null then
    select * into v_session
    from public.ac360_school_attendance_sessions
    where org_id = p_org_id
      and session_date = (coalesce(p_event_at, now()) at time zone 'Africa/Casablanca')::date
      and status = 'open'
    order by created_at desc
    limit 1;

    if not found then
      select (public.ac360_school_open_attendance_session(p_org_id, null, null, null, (coalesce(p_event_at, now()) at time zone 'Africa/Casablanca')::date, 'daily', p_actor_app_user_id, jsonb_build_object('auto_opened_by','record_attendance_event'))) ->> 'sessionId'
      into v_session_id;
      v_session_id := v_session_id::uuid;
    else
      v_session_id := v_session.id;
    end if;
  end if;

  select * into v_session from public.ac360_school_attendance_sessions where id = v_session_id and org_id = p_org_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'Attendance session not found.'); end if;
  if v_session.status in ('closed','locked','archived') then return jsonb_build_object('ok', false, 'error', 'Attendance session is not open.'); end if;

  if v_daybook_id is null then
    v_daybook_id := public.ac360_school_find_or_create_daybook(p_org_id, v_session.campus_id, v_session.class_id, v_session.academic_year_id, v_session.session_date, v_session.session_key, p_actor_app_user_id, p_metadata);
  end if;

  select id, attendance_status into v_record_id, v_previous_status
  from public.ac360_school_attendance_records
  where org_id = p_org_id
    and attendance_session_id = v_session_id
    and attendance_type = v_type
    and student_id is not distinct from p_student_id
    and staff_profile_id is not distinct from p_staff_profile_id
  order by created_at desc
  limit 1;

  if v_record_id is null then
    insert into public.ac360_school_attendance_records(
      org_id, attendance_session_id, student_id, staff_profile_id, attendance_type, attendance_status, recorded_at, check_in_at, check_out_at, reason, source, created_by, metadata_json
    ) values (
      p_org_id, v_session_id, p_student_id, p_staff_profile_id, v_type, coalesce(v_status,'present'), coalesce(p_event_at, now()),
      case when p_event_type in ('check_in','staff_check_in','mark_present','mark_late') then coalesce(p_event_at, now()) else null end,
      case when p_event_type in ('check_out','staff_check_out','mark_early_out') then coalesce(p_event_at, now()) else null end,
      p_reason, coalesce(nullif(p_source,''),'manual'), p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb)
    ) returning id into v_record_id;
  else
    update public.ac360_school_attendance_records
    set attendance_status = coalesce(v_status, attendance_status),
        recorded_at = coalesce(p_event_at, now()),
        check_in_at = case when p_event_type in ('check_in','staff_check_in','mark_present','mark_late') then coalesce(check_in_at, coalesce(p_event_at, now())) else check_in_at end,
        check_out_at = case when p_event_type in ('check_out','staff_check_out','mark_early_out') then coalesce(p_event_at, now()) else check_out_at end,
        reason = coalesce(p_reason, reason),
        source = coalesce(nullif(p_source,''), source),
        metadata_json = metadata_json || coalesce(p_metadata,'{}'::jsonb)
    where id = v_record_id;
  end if;

  insert into public.ac360_school_attendance_events(
    org_id, daybook_id, attendance_session_id, attendance_record_id, student_id, staff_profile_id, attendance_type, event_type, attendance_status, event_at, source, actor_app_user_id, reason, previous_status, metadata_json
  ) values (
    p_org_id, v_daybook_id, v_session_id, v_record_id, p_student_id, p_staff_profile_id, v_type, p_event_type, coalesce(v_status, v_previous_status), coalesce(p_event_at, now()), coalesce(nullif(p_source,''),'manual'), p_actor_app_user_id, p_reason, v_previous_status, coalesce(p_metadata,'{}'::jsonb)
  );

  perform public.ac360_school_refresh_daybook_counts(v_daybook_id);

  return jsonb_build_object('ok', true, 'sessionId', v_session_id, 'daybookId', v_daybook_id, 'recordId', v_record_id, 'status', coalesce(v_status, v_previous_status), 'eventType', p_event_type);
end;
$$;


