--
-- Name: ac360_school_record_fee_payment(uuid, uuid, uuid, text, text, numeric, timestamp with time zone, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_record_fee_payment(p_org_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_payment_reference text DEFAULT NULL::text, p_payment_method text DEFAULT 'cash'::text, p_amount_mad numeric DEFAULT 0, p_paid_at timestamp with time zone DEFAULT now(), p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payment public.ac360_school_fee_payments;
  v_ref text := coalesce(nullif(trim(p_payment_reference), ''), 'PAY-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text, 1, 6));
  v_invoice public.ac360_school_tuition_invoices;
begin
  if p_invoice_id is not null then
    select * into v_invoice from public.ac360_school_tuition_invoices where id=p_invoice_id and org_id=p_org_id;
    if not found then
      raise exception 'invoice not found';
    end if;
  end if;

  insert into public.ac360_school_fee_payments(org_id, invoice_id, student_id, payment_reference, payment_method, status, amount_mad, paid_at, recorded_by, notes, metadata_json)
  values (p_org_id, p_invoice_id, coalesce(p_student_id, v_invoice.student_id), v_ref, coalesce(p_payment_method,'cash'), 'recorded', greatest(coalesce(p_amount_mad,0),0), coalesce(p_paid_at, now()), p_actor_app_user_id, p_notes, coalesce(p_metadata,'{}'::jsonb))
  returning * into v_payment;

  if p_invoice_id is not null then
    insert into public.ac360_school_payment_allocations(org_id, payment_id, invoice_id, amount_mad, allocated_by, notes, metadata_json)
    values (p_org_id, v_payment.id, p_invoice_id, v_payment.amount_mad, p_actor_app_user_id, 'Auto-allocation from payment record', '{"auto_allocated":true}'::jsonb)
    on conflict (org_id, payment_id, invoice_id) do update set amount_mad=excluded.amount_mad, allocation_status='allocated', updated_at=now();

    update public.ac360_school_tuition_invoices
    set paid_mad = least(total_mad, paid_mad + v_payment.amount_mad),
        status = case
          when least(total_mad, paid_mad + v_payment.amount_mad) >= total_mad then 'paid'
          when least(total_mad, paid_mad + v_payment.amount_mad) > 0 then 'partially_paid'
          else status
        end,
        updated_at=now()
    where id=p_invoice_id and org_id=p_org_id;
  end if;

  insert into public.ac360_school_collection_events(org_id, invoice_id, event_type, event_channel, amount_mad, event_note, actor_app_user_id, metadata_json)
  values (p_org_id, p_invoice_id, 'payment_recorded', 'system', v_payment.amount_mad, 'Payment recorded through Phase 2D finance runtime', p_actor_app_user_id, jsonb_build_object('payment_id', v_payment.id, 'payment_reference', v_payment.payment_reference));

  return jsonb_build_object('ok', true, 'payment', to_jsonb(v_payment));
end $$;


--
-- Name: ac360_school_record_integration_event(uuid, uuid, text, text, text, text, jsonb, jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_record_integration_event(p_org_id uuid, p_connector_id uuid DEFAULT NULL::uuid, p_event_key text DEFAULT NULL::text, p_event_type text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text, p_status text DEFAULT 'recorded'::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_result_json jsonb DEFAULT '{}'::jsonb, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_event public.ac360_school_integration_events%rowtype;
begin
  insert into public.ac360_school_integration_events(org_id,connector_id,event_key,event_type,severity,status,payload_json,result_json,actor_app_user_id)
  values(p_org_id,p_connector_id,coalesce(nullif(p_event_key,''),'integration-event-'||substr(gen_random_uuid()::text,1,8)),coalesce(nullif(p_event_type,''),'generic'),coalesce(nullif(p_severity,''),'info'),coalesce(nullif(p_status,''),'recorded'),coalesce(p_payload_json,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),coalesce(p_result_json,'{}'::jsonb),p_actor_app_user_id)
  on conflict(org_id,event_key) do update set status=excluded.status,severity=excluded.severity,payload_json=public.ac360_school_integration_events.payload_json||excluded.payload_json,result_json=excluded.result_json,actor_app_user_id=excluded.actor_app_user_id returning * into v_event;
  if v_event.severity='critical' or v_event.status='failed' then
    insert into public.ac360_school_integration_alerts(org_id,connector_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_connector_id,'integration-event-critical-'||v_event.id,'integration_event_critical','critical','Critical integration event','An integration event requires immediate review.',jsonb_build_object('event_id',v_event.id))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;
  return jsonb_build_object('ok',true,'event',to_jsonb(v_event));
end $$;


