--
-- Name: ac360_school_register_document(uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, bigint, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_register_document(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_folder_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_guardian_id uuid DEFAULT NULL::uuid, p_staff_profile_id uuid DEFAULT NULL::uuid, p_document_code text DEFAULT NULL::text, p_document_type text DEFAULT 'general'::text, p_title text DEFAULT NULL::text, p_file_name text DEFAULT NULL::text, p_file_path text DEFAULT NULL::text, p_file_size_bytes bigint DEFAULT 0, p_mime_type text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_doc public.ac360_school_documents%rowtype;
  v_code text := coalesce(nullif(p_document_code,''), 'DOC-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)));
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  if coalesce(nullif(p_title,''),'') = '' then raise exception 'p_title is required'; end if;

  insert into public.ac360_school_documents(
    org_id,campus_id,folder_id,student_id,guardian_id,staff_profile_id,document_code,document_type,title,file_name,file_path,file_size_bytes,mime_type,status,uploaded_by,metadata_json
  ) values (
    p_org_id,p_campus_id,p_folder_id,p_student_id,p_guardian_id,p_staff_profile_id,v_code,coalesce(p_document_type,'general'),p_title,p_file_name,p_file_path,greatest(coalesce(p_file_size_bytes,0),0),p_mime_type,'active',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)
  )
  on conflict (org_id, document_code) do update set
    campus_id=coalesce(excluded.campus_id, public.ac360_school_documents.campus_id),
    folder_id=coalesce(excluded.folder_id, public.ac360_school_documents.folder_id),
    title=excluded.title,
    document_type=excluded.document_type,
    file_name=excluded.file_name,
    file_path=excluded.file_path,
    file_size_bytes=excluded.file_size_bytes,
    mime_type=excluded.mime_type,
    status='active',
    metadata_json=public.ac360_school_documents.metadata_json || excluded.metadata_json,
    updated_at=now()
  returning * into v_doc;

  insert into public.ac360_school_operation_events(org_id,campus_id,event_key,action_key,entity_type,entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_campus_id,'document.registered','school.document.register','document',v_doc.id,'info','Document registered in AC360 storage runtime.',p_actor_app_user_id,jsonb_build_object('documentCode',v_doc.document_code,'phase','phase_2f'));

  return jsonb_build_object('ok',true,'document',to_jsonb(v_doc));
end;
$$;


--
-- Name: ac360_school_render_message_template(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_render_message_template(p_org_id uuid, p_template_key text, p_variables jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_template record;
  v_subject text;
  v_body text;
  v_key text;
  v_value text;
begin
  select * into v_template from public.ac360_school_message_templates
  where org_id=p_org_id and template_key=p_template_key and status in ('published','draft')
  order by case when status='published' then 0 else 1 end, updated_at desc
  limit 1;
  if not found then raise exception 'message template not found'; end if;

  v_subject := coalesce(v_template.subject_template,'');
  v_body := coalesce(v_template.body_template,'');
  for v_key, v_value in select key, value from jsonb_each_text(coalesce(p_variables,'{}'::jsonb)) loop
    v_subject := replace(replace(v_subject, '{{' || v_key || '}}', v_value), '[' || v_key || ']', v_value);
    v_body := replace(replace(v_body, '{{' || v_key || '}}', v_value), '[' || v_key || ']', v_value);
  end loop;

  return jsonb_build_object('ok', true, 'templateId', v_template.id, 'subject', nullif(v_subject,''), 'body', v_body, 'channel', v_template.channel, 'audienceType', v_template.audience_type);
end $$;


--
-- Name: ac360_school_report_incident(uuid, uuid, uuid, uuid, text, text, timestamp with time zone, text, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_report_incident(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_student_id uuid DEFAULT NULL::uuid, p_class_id uuid DEFAULT NULL::uuid, p_incident_type text DEFAULT 'safety'::text, p_severity text DEFAULT 'medium'::text, p_occurred_at timestamp with time zone DEFAULT now(), p_location text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_immediate_action text DEFAULT NULL::text, p_reported_by_staff_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_code text := 'INC-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,6);
begin
  if nullif(trim(coalesce(p_description,'')),'') is null then return jsonb_build_object('ok',false,'error','description is required.'); end if;
  insert into public.ac360_school_incident_reports(org_id,campus_id,student_id,class_id,incident_code,incident_type,severity,occurred_at,location,description,immediate_action,reported_by_staff_id,metadata_json)
  values(p_org_id,p_campus_id,p_student_id,p_class_id,v_code,coalesce(p_incident_type,'safety'),coalesce(p_severity,'medium'),coalesce(p_occurred_at,now()),p_location,trim(p_description),p_immediate_action,p_reported_by_staff_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  insert into public.ac360_school_incident_events(org_id,incident_id,event_key,event_type,status_to,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,v_id,'incident.reported','create','open',case when p_severity in ('high','critical') then p_severity else 'medium' end,'Incident reported.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  if coalesce(p_severity,'medium') in ('high','critical') then
    insert into public.ac360_school_health_safety_alerts(org_id,campus_id,student_id,incident_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_campus_id,p_student_id,v_id,'incident-' || v_code,'incident_escalation',coalesce(p_severity,'high'),'High priority incident',trim(p_description),jsonb_build_object('incidentCode',v_code))
    on conflict(org_id,alert_key) do update set status='open',updated_at=now();
  end if;
  return jsonb_build_object('ok',true,'incidentId',v_id,'incidentCode',v_code);
end $$;


--
-- Name: ac360_school_request_approval(uuid, uuid, text, text, text, text, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_request_approval(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_policy_key text DEFAULT NULL::text, p_request_code text DEFAULT NULL::text, p_approval_type text DEFAULT 'generic'::text, p_related_entity_type text DEFAULT NULL::text, p_related_entity_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_request_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_req public.ac360_school_approval_requests%rowtype; v_policy_id uuid; v_code text;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  select id into v_policy_id from public.ac360_school_approval_policies where org_id=p_org_id and policy_key=p_policy_key limit 1;
  v_code := coalesce(nullif(trim(p_request_code),''),'APR-'||to_char(now(),'YYYYMMDDHH24MISS')||'-'||substr(gen_random_uuid()::text,1,6));
  insert into public.ac360_school_approval_requests(org_id,campus_id,policy_id,request_code,approval_type,related_entity_type,related_entity_id,title,request_note,requested_by,metadata_json)
  values(p_org_id,p_campus_id,v_policy_id,v_code,coalesce(p_approval_type,'generic'),p_related_entity_type,p_related_entity_id,coalesce(nullif(trim(p_title),''),'Approval Request'),p_request_note,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_req;
  return jsonb_build_object('ok',true,'approvalRequest',to_jsonb(v_req));
end; $$;


--
-- Name: ac360_school_request_attendance_correction(uuid, uuid, text, timestamp with time zone, timestamp with time zone, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_request_attendance_correction(p_org_id uuid, p_attendance_record_id uuid, p_requested_status text DEFAULT NULL::text, p_requested_check_in_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_requested_check_out_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_request_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_record record;
  v_daybook_id uuid;
  v_correction_id uuid;
begin
  select * into v_record from public.ac360_school_attendance_records where id = p_attendance_record_id and org_id = p_org_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'Attendance record not found.'); end if;

  select public.ac360_school_find_or_create_daybook(s.org_id, s.campus_id, s.class_id, s.academic_year_id, s.session_date, s.session_key, p_actor_app_user_id, p_metadata)
  into v_daybook_id
  from public.ac360_school_attendance_sessions s
  where s.id = v_record.attendance_session_id;

  insert into public.ac360_school_attendance_corrections(
    org_id, daybook_id, attendance_session_id, attendance_record_id, student_id, staff_profile_id, requested_status, requested_check_in_at, requested_check_out_at, request_reason, requested_by, metadata_json
  ) values (
    p_org_id, v_daybook_id, v_record.attendance_session_id, v_record.id, v_record.student_id, v_record.staff_profile_id, p_requested_status, p_requested_check_in_at, p_requested_check_out_at, p_request_reason, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_correction_id;

  update public.ac360_school_attendance_records set correction_status='requested' where id = v_record.id;

  insert into public.ac360_school_attendance_events(org_id, daybook_id, attendance_session_id, attendance_record_id, student_id, staff_profile_id, attendance_type, event_type, attendance_status, actor_app_user_id, reason, correction_id, metadata_json)
  values (p_org_id, v_daybook_id, v_record.attendance_session_id, v_record.id, v_record.student_id, v_record.staff_profile_id, v_record.attendance_type, 'correction_requested', coalesce(p_requested_status, v_record.attendance_status), p_actor_app_user_id, p_request_reason, v_correction_id, coalesce(p_metadata,'{}'::jsonb));

  perform public.ac360_school_refresh_daybook_counts(v_daybook_id);
  return jsonb_build_object('ok', true, 'correctionId', v_correction_id, 'recordId', v_record.id, 'decisionStatus', 'requested');
end;
$$;


--
-- Name: ac360_school_request_custom_domain(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_request_custom_domain(p_org_id uuid, p_brand_profile_id uuid DEFAULT NULL::uuid, p_domain_name text DEFAULT NULL::text, p_domain_type text DEFAULT 'parent_portal'::text, p_dns_target text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_domain public.ac360_school_custom_domains%rowtype;
begin
  insert into public.ac360_school_custom_domains(org_id,brand_profile_id,domain_name,domain_type,status,dns_target,created_by,metadata_json)
  values(p_org_id,p_brand_profile_id,lower(trim(p_domain_name)),coalesce(nullif(p_domain_type,''),'parent_portal'),'pending_dns',p_dns_target,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict(domain_name) do update set brand_profile_id=excluded.brand_profile_id,domain_type=excluded.domain_type,status='pending_dns',dns_target=excluded.dns_target,metadata_json=public.ac360_school_custom_domains.metadata_json||excluded.metadata_json,updated_at=now()
  returning * into v_domain;
  insert into public.ac360_school_domain_verification_events(org_id,domain_id,event_type,next_status,message,actor_app_user_id,payload_json)
  values(p_org_id,v_domain.id,'requested',v_domain.status,'Custom domain verification requested.',p_actor_app_user_id,jsonb_build_object('domain_name',v_domain.domain_name));
  return jsonb_build_object('ok',true,'domain',to_jsonb(v_domain));
end $$;


--
-- Name: ac360_school_request_document_review(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_request_document_review(p_org_id uuid, p_document_id uuid, p_review_type text DEFAULT 'approval'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_review public.ac360_school_document_review_requests%rowtype; v_code text;
begin
  if not exists(select 1 from public.ac360_school_documents where id=p_document_id and org_id=p_org_id) then raise exception 'Document not found'; end if;
  v_code := 'DREV-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
  insert into public.ac360_school_document_review_requests(org_id,document_id,review_code,review_type,status,requested_by,metadata_json)
  values(p_org_id,p_document_id,v_code,coalesce(p_review_type,'approval'),'pending',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_review;
  update public.ac360_school_documents set status='pending_review', review_status='pending', updated_at=now() where id=p_document_id;
  return jsonb_build_object('ok',true,'review',to_jsonb(v_review));
end;
$$;


