--
-- Name: ac360_school_run_daily_ops_reconcile(uuid, uuid, date, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_run_daily_ops_reconcile(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_operation_date date DEFAULT CURRENT_DATE, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_daybook record;
  v_sessions integer := 0;
  v_records integer := 0;
  v_daybooks integer := 0;
  v_alerts integer := 0;
  v_open_issues integer := 0;
  v_run_status text := 'completed';
  v_run_id uuid;
  v_alert_key text;
begin
  for v_daybook in
    select * from public.ac360_school_attendance_daybooks
    where org_id = p_org_id
      and campus_id is not distinct from p_campus_id
      and operation_date = coalesce(p_operation_date, current_date)
      and status in ('open','reconciled','closed')
  loop
    perform public.ac360_school_refresh_daybook_counts(v_daybook.id);
    update public.ac360_school_attendance_daybooks
    set status = case when status='open' then 'reconciled' else status end,
        reconciled_by = p_actor_app_user_id,
        reconciled_at = now()
    where id = v_daybook.id;
    v_daybooks := v_daybooks + 1;
  end loop;

  select count(*)::integer into v_sessions
  from public.ac360_school_attendance_sessions
  where org_id = p_org_id
    and campus_id is not distinct from p_campus_id
    and session_date = coalesce(p_operation_date, current_date);

  select count(*)::integer into v_records
  from public.ac360_school_attendance_records r
  join public.ac360_school_attendance_sessions s on s.id = r.attendance_session_id
  where r.org_id = p_org_id
    and s.campus_id is not distinct from p_campus_id
    and s.session_date = coalesce(p_operation_date, current_date);

  select coalesce(sum(open_issues_count),0)::integer into v_open_issues
  from public.ac360_school_attendance_daybooks
  where org_id = p_org_id
    and campus_id is not distinct from p_campus_id
    and operation_date = coalesce(p_operation_date, current_date);

  if v_open_issues > 0 then
    v_run_status := 'completed_with_issues';
    v_alert_key := 'daily-ops-issues-' || p_org_id::text || '-' || coalesce(p_campus_id::text,'all') || '-' || coalesce(p_operation_date,current_date)::text;
    insert into public.ac360_school_daily_ops_alerts(org_id, campus_id, alert_key, alert_type, severity, subject_type, message, metadata_json)
    values (p_org_id, p_campus_id, v_alert_key, 'daily_ops_open_issues', case when v_open_issues > 10 then 'high' else 'medium' end, 'attendance_day', 'Daily attendance reconciliation detected open issues requiring review.', jsonb_build_object('openIssues',v_open_issues,'operationDate',coalesce(p_operation_date,current_date)))
    on conflict (org_id, alert_key) do update set status='active', severity=excluded.severity, message=excluded.message, metadata_json=public.ac360_school_daily_ops_alerts.metadata_json || excluded.metadata_json;
    v_alerts := v_alerts + 1;
  end if;

  insert into public.ac360_school_daily_ops_reconcile_runs(org_id, campus_id, operation_date, run_status, sessions_checked, records_checked, daybooks_reconciled, alerts_created, open_issues_count, actor_app_user_id, metadata_json)
  values (p_org_id, p_campus_id, coalesce(p_operation_date,current_date), v_run_status, v_sessions, v_records, v_daybooks, v_alerts, v_open_issues, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb))
  returning id into v_run_id;

  return jsonb_build_object('ok', true, 'runId', v_run_id, 'runStatus', v_run_status, 'sessionsChecked', v_sessions, 'recordsChecked', v_records, 'daybooksReconciled', v_daybooks, 'alertsCreated', v_alerts, 'openIssues', v_open_issues);
end;
$$;


--
-- Name: ac360_school_run_lifecycle_integrity_check(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_run_lifecycle_integrity_check(p_org_id uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_run_id uuid;
  v_students_without_guardians integer := 0;
  v_students_without_class integer := 0;
  v_over_capacity_classes integer := 0;
  v_duplicate_primary integer := 0;
  v_critical integer := 0;
  v_warning integer := 0;
  v_score numeric := 100;
  rec record;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;

  select count(*) into v_students_without_guardians
  from public.ac360_school_students s
  where s.org_id = p_org_id and s.status = 'active' and s.enrollment_status in ('pre_enrolled','enrolled','active')
    and not exists (select 1 from public.ac360_school_student_guardians sg where sg.org_id = p_org_id and sg.student_id = s.id and sg.status = 'active');

  select count(*) into v_students_without_class
  from public.ac360_school_students s
  where s.org_id = p_org_id and s.status = 'active' and s.enrollment_status in ('enrolled','active')
    and not exists (select 1 from public.ac360_school_class_enrollments e where e.org_id = p_org_id and e.student_id = s.id and e.status = 'active');

  with class_counts as (
    select c.id, c.capacity_students, count(e.id)::integer as enrolled_count
    from public.ac360_school_classes c
    left join public.ac360_school_class_enrollments e on e.org_id = c.org_id and e.class_id = c.id and e.status = 'active'
    where c.org_id = p_org_id and c.status in ('active','full')
    group by c.id, c.capacity_students
  )
  select count(*) into v_over_capacity_classes
  from class_counts where capacity_students is not null and capacity_students > 0 and enrolled_count > capacity_students;

  select count(*) into v_duplicate_primary
  from (
    select student_id
    from public.ac360_school_student_guardians
    where org_id = p_org_id and status = 'active' and is_primary = true
    group by student_id
    having count(*) > 1
  ) x;

  v_critical := v_over_capacity_classes;
  v_warning := v_students_without_guardians + v_students_without_class + v_duplicate_primary;
  v_score := greatest(0, 100 - (v_critical * 20) - (v_warning * 5));

  insert into public.ac360_school_integrity_runs(org_id, status, score, critical_count, warning_count, result_json, actor_app_user_id, metadata_json)
  values (
    p_org_id,
    case when v_critical > 0 then 'critical' when v_warning > 0 then 'warning' else 'completed' end,
    v_score, v_critical, v_warning,
    jsonb_build_object(
      'studentsWithoutGuardians', v_students_without_guardians,
      'studentsWithoutActiveClass', v_students_without_class,
      'overCapacityClasses', v_over_capacity_classes,
      'duplicatePrimaryGuardians', v_duplicate_primary,
      'uiBuildAllowed', false
    ),
    p_actor_app_user_id,
    coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_run_id;

  if v_students_without_guardians > 0 then
    insert into public.ac360_school_integrity_findings(run_id, org_id, finding_key, severity, message, recommendation, metadata_json)
    values (v_run_id, p_org_id, 'students_without_guardians', 'warning', 'Active/pre-enrolled students exist without active guardian links.', 'Link at least one guardian to every active or pre-enrolled student before UI rollout.', jsonb_build_object('count', v_students_without_guardians));
  end if;
  if v_students_without_class > 0 then
    insert into public.ac360_school_integrity_findings(run_id, org_id, finding_key, severity, message, recommendation, metadata_json)
    values (v_run_id, p_org_id, 'students_without_active_class', 'warning', 'Enrolled students exist without active class enrollment.', 'Assign every enrolled student to an active class before operational launch.', jsonb_build_object('count', v_students_without_class));
  end if;
  if v_over_capacity_classes > 0 then
    insert into public.ac360_school_integrity_findings(run_id, org_id, finding_key, severity, message, recommendation, metadata_json)
    values (v_run_id, p_org_id, 'over_capacity_classes', 'critical', 'One or more classes are over configured capacity.', 'Reduce class enrollment or increase class capacity before production UI use.', jsonb_build_object('count', v_over_capacity_classes));
  end if;
  if v_duplicate_primary > 0 then
    insert into public.ac360_school_integrity_findings(run_id, org_id, finding_key, severity, message, recommendation, metadata_json)
    values (v_run_id, p_org_id, 'duplicate_primary_guardians', 'warning', 'One or more students have multiple primary guardians.', 'Keep only one primary guardian per student.', jsonb_build_object('count', v_duplicate_primary));
  end if;

  insert into public.ac360_school_operation_events(org_id, event_key, action_key, entity_type, entity_id, severity, message, actor_app_user_id, metadata_json)
  values (p_org_id, 'phase2b.lifecycle.integrity_check.completed', 'school.lifecycle.integrity_check', 'integrity_run', v_run_id, case when v_critical > 0 then 'critical' when v_warning > 0 then 'warning' else 'info' end, 'AC360 Phase 2B lifecycle integrity check completed.', p_actor_app_user_id, jsonb_build_object('runId', v_run_id, 'score', v_score, 'critical', v_critical, 'warning', v_warning));

  return jsonb_build_object('ok', true, 'runId', v_run_id, 'score', v_score, 'criticalCount', v_critical, 'warningCount', v_warning, 'uiBuildAllowed', false, 'result', (select result_json from public.ac360_school_integrity_runs where id = v_run_id));
end;
$$;


--
-- Name: ac360_school_run_scheduled_job(uuid, uuid, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_run_scheduled_job(p_org_id uuid, p_scheduled_job_id uuid, p_run_key text DEFAULT NULL::text, p_status text DEFAULT 'completed'::text, p_result_json jsonb DEFAULT '{}'::jsonb, p_failed_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_run public.ac360_school_scheduled_job_runs%rowtype;
begin
  insert into public.ac360_school_scheduled_job_runs(org_id,scheduled_job_id,run_key,status,completed_at,result_json,failed_reason,metadata_json) values(p_org_id,p_scheduled_job_id,coalesce(nullif(p_run_key,''),'SJR-'||substr(gen_random_uuid()::text,1,10)),coalesce(p_status,'completed'),case when coalesce(p_status,'completed') in ('completed','failed','cancelled') then now() else null end,coalesce(p_result_json,'{}'::jsonb),p_failed_reason,coalesce(p_metadata,'{}'::jsonb)) returning * into v_run;
  update public.ac360_school_scheduled_jobs set last_run_at=now(),next_run_at=case run_interval when 'hourly' then now()+interval '1 hour' when 'weekly' then now()+interval '7 days' when 'monthly' then now()+interval '1 month' else now()+interval '1 day' end,updated_at=now() where id=p_scheduled_job_id and org_id=p_org_id;
  return jsonb_build_object('ok',true,'scheduledJobRun',to_jsonb(v_run));
end $$;


--
-- Name: ac360_school_scan_admission_duplicates(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_scan_admission_duplicates(p_org_id uuid, p_lead_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_count integer := 0; begin
  insert into public.ac360_school_admission_duplicate_findings(org_id,lead_id,duplicate_lead_id,match_type,match_score,status,metadata_json)
  select p_org_id,a.id,b.id,
    case when a.parent_phone is not null and a.parent_phone=b.parent_phone then 'phone'
         when a.parent_email is not null and lower(a.parent_email)=lower(b.parent_email) then 'email'
         else 'name_birthdate' end,
    case when a.parent_phone is not null and a.parent_phone=b.parent_phone then 95 else 80 end,
    'open',
    jsonb_build_object('source','phase_2h_duplicate_scan')
  from public.ac360_school_admission_leads a
  join public.ac360_school_admission_leads b on b.org_id=a.org_id and b.id<>a.id
  where a.org_id=p_org_id
    and (p_lead_id is null or a.id=p_lead_id)
    and a.status='active' and b.status='active'
    and (
      (a.parent_phone is not null and a.parent_phone=b.parent_phone)
      or (a.parent_email is not null and b.parent_email is not null and lower(a.parent_email)=lower(b.parent_email))
      or (lower(coalesce(a.child_first_name,''))=lower(coalesce(b.child_first_name,'')) and coalesce(a.date_of_birth,'1900-01-01'::date)=coalesce(b.date_of_birth,'1900-01-01'::date))
    )
  on conflict do nothing;
  get diagnostics v_count = row_count;
  return jsonb_build_object('ok',true,'duplicates_created',v_count);
end $$;


--
-- Name: ac360_school_schedule_admission_visit(uuid, uuid, uuid, timestamp with time zone, text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_schedule_admission_visit(p_org_id uuid, p_lead_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_visit_type text DEFAULT 'school_visit'::text, p_assigned_staff_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_id uuid; v_code text; begin
  if p_scheduled_at is null then raise exception 'scheduled_at is required'; end if;
  if not exists(select 1 from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id) then raise exception 'lead not found'; end if;
  v_code := public.ac360_admissions_default_code('VISIT');
  insert into public.ac360_school_admission_visits(org_id,lead_id,campus_id,visit_code,scheduled_at,visit_type,status,assigned_staff_id,notes,created_by,metadata_json)
  values(p_org_id,p_lead_id,p_campus_id,v_code,p_scheduled_at,coalesce(nullif(p_visit_type,''),'school_visit'),'scheduled',p_assigned_staff_id,p_notes,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
  update public.ac360_school_admission_leads set lead_status='visit_scheduled', next_followup_at=p_scheduled_at + interval '1 day', updated_at=now() where id=p_lead_id and org_id=p_org_id and lead_status not in ('converted','lost');
  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,to_status,actor_app_user_id,message,metadata_json) values(p_org_id,p_lead_id,'visit.scheduled','visit','visit_scheduled',p_actor_app_user_id,'Admission visit scheduled.',coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'visit_id',v_id,'visit_code',v_code);
end $$;


--
-- Name: ac360_school_start_workflow_instance(uuid, uuid, text, text, text, text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_start_workflow_instance(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_template_key text DEFAULT NULL::text, p_instance_code text DEFAULT NULL::text, p_workflow_type text DEFAULT 'operations'::text, p_related_entity_type text DEFAULT NULL::text, p_related_entity_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_tpl public.ac360_school_workflow_templates%rowtype; v_inst public.ac360_school_workflow_instances%rowtype; v_code text; v_steps jsonb; v_step jsonb; v_pos int := 10; v_first text;
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  select * into v_tpl from public.ac360_school_workflow_templates where org_id=p_org_id and template_key=p_template_key limit 1;
  v_steps := coalesce(v_tpl.steps_json, '[]'::jsonb);
  if jsonb_typeof(v_steps) <> 'array' then v_steps := '[]'::jsonb; end if;
  v_code := coalesce(nullif(trim(p_instance_code),''),'WF-'||to_char(now(),'YYYYMMDDHH24MISS')||'-'||substr(gen_random_uuid()::text,1,6));
  insert into public.ac360_school_workflow_instances(org_id,campus_id,template_id,instance_code,workflow_type,related_entity_type,related_entity_id,title,status,started_by,metadata_json)
  values(p_org_id,p_campus_id,v_tpl.id,v_code,coalesce(p_workflow_type,v_tpl.workflow_type,'operations'),p_related_entity_type,p_related_entity_id,coalesce(nullif(trim(p_title),''),coalesce(v_tpl.label,'Workflow Instance')),'running',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) returning * into v_inst;
  for v_step in select * from jsonb_array_elements(v_steps) loop
    if v_first is null then v_first := coalesce(v_step->>'key','step-'||v_pos); end if;
    insert into public.ac360_school_workflow_steps(org_id,workflow_instance_id,step_key,label,status,position,metadata_json) values(p_org_id,v_inst.id,coalesce(v_step->>'key','step-'||v_pos),coalesce(v_step->>'label',v_step->>'key','Step'),'pending',coalesce((v_step->>'position')::int,v_pos),v_step);
    v_pos := v_pos + 10;
  end loop;
  update public.ac360_school_workflow_instances set current_step_key=v_first where id=v_inst.id returning * into v_inst;
  insert into public.ac360_school_workflow_events(org_id,workflow_instance_id,event_key,event_type,actor_app_user_id,message,metadata_json) values(p_org_id,v_inst.id,'workflow.started','status_change',p_actor_app_user_id,'Workflow instance started.',jsonb_build_object('phase','phase_2g'));
  return jsonb_build_object('ok',true,'workflowInstance',to_jsonb(v_inst));
end; $$;


--
-- Name: ac360_school_transfer_student_class(uuid, uuid, uuid, uuid, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_transfer_student_class(p_org_id uuid, p_student_id uuid, p_to_class_id uuid, p_from_class_id uuid DEFAULT NULL::uuid, p_transfer_date date DEFAULT CURRENT_DATE, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_student public.ac360_school_students%rowtype;
  v_to_class public.ac360_school_classes%rowtype;
  v_from_enrollment public.ac360_school_class_enrollments%rowtype;
  v_new_enrollment public.ac360_school_class_enrollments%rowtype;
  v_transfer_id uuid;
  v_to_reconcile jsonb;
  v_from_reconcile jsonb := null;
begin
  select * into v_student from public.ac360_school_students where org_id = p_org_id and id = p_student_id;
  if v_student.id is null then raise exception 'Student not found for this organization'; end if;
  select * into v_to_class from public.ac360_school_classes where org_id = p_org_id and id = p_to_class_id and status in ('active','full','restricted');
  if v_to_class.id is null then raise exception 'Target class not found or unavailable for this organization'; end if;

  if p_from_class_id is not null then
    select * into v_from_enrollment from public.ac360_school_class_enrollments
    where org_id = p_org_id and student_id = p_student_id and class_id = p_from_class_id and status = 'active'
    order by created_at desc limit 1 for update;
  else
    select * into v_from_enrollment from public.ac360_school_class_enrollments
    where org_id = p_org_id and student_id = p_student_id and status = 'active'
    order by created_at desc limit 1 for update;
  end if;

  if v_from_enrollment.id is not null then
    update public.ac360_school_class_enrollments set status = 'completed', ends_on = coalesce(p_transfer_date, current_date), updated_at = now()
    where id = v_from_enrollment.id;
  end if;

  insert into public.ac360_school_class_enrollments(org_id, student_id, class_id, academic_year_id, status, starts_on, metadata_json)
  values (p_org_id, p_student_id, p_to_class_id, coalesce(v_to_class.academic_year_id, v_student.academic_year_id), 'active', coalesce(p_transfer_date,current_date), coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('createdByTransfer', true))
  on conflict (org_id, student_id, class_id, starts_on) do update set status = 'active', ends_on = null, metadata_json = public.ac360_school_class_enrollments.metadata_json || excluded.metadata_json, updated_at = now()
  returning * into v_new_enrollment;

  insert into public.ac360_school_class_transfer_events(org_id, student_id, from_class_id, to_class_id, from_enrollment_id, to_enrollment_id, transfer_date, reason, status, actor_app_user_id, metadata_json)
  values (p_org_id, p_student_id, v_from_enrollment.class_id, p_to_class_id, v_from_enrollment.id, v_new_enrollment.id, coalesce(p_transfer_date,current_date), p_reason, 'applied', p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb))
  returning id into v_transfer_id;

  perform public.ac360_school_record_lifecycle_event(p_org_id, v_to_class.campus_id, 'enrollment', v_new_enrollment.id, 'school.class.transfer_student', v_from_enrollment.status, 'active', null, null, p_reason, p_actor_app_user_id, jsonb_build_object('transferId', v_transfer_id, 'studentId', p_student_id, 'fromClassId', v_from_enrollment.class_id, 'toClassId', p_to_class_id) || coalesce(p_metadata,'{}'::jsonb));

  v_to_reconcile := public.ac360_school_reconcile_class_capacity(p_org_id, p_to_class_id, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('sourceTransferId', v_transfer_id));
  if v_from_enrollment.class_id is not null and v_from_enrollment.class_id <> p_to_class_id then
    v_from_reconcile := public.ac360_school_reconcile_class_capacity(p_org_id, v_from_enrollment.class_id, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('sourceTransferId', v_transfer_id));
  end if;

  return jsonb_build_object('ok', true, 'transferId', v_transfer_id, 'studentId', p_student_id, 'fromClassId', v_from_enrollment.class_id, 'toClassId', p_to_class_id, 'newEnrollmentId', v_new_enrollment.id, 'toClassCapacity', v_to_reconcile, 'fromClassCapacity', v_from_reconcile);
end;
$$;


--
-- Name: ac360_school_transition_student(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_transition_student(p_org_id uuid, p_student_id uuid, p_to_enrollment_status text, p_to_status text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_student public.ac360_school_students%rowtype;
  v_new_status text;
  v_event_id uuid;
  v_guardian_count integer := 0;
  v_enrollment_count integer := 0;
begin
  if p_org_id is null or p_student_id is null then raise exception 'p_org_id and p_student_id are required'; end if;
  select * into v_student from public.ac360_school_students where org_id = p_org_id and id = p_student_id for update;
  if v_student.id is null then raise exception 'Student not found for this organization'; end if;

  select count(*) into v_guardian_count from public.ac360_school_student_guardians where org_id = p_org_id and student_id = p_student_id and status = 'active';
  select count(*) into v_enrollment_count from public.ac360_school_class_enrollments where org_id = p_org_id and student_id = p_student_id and status = 'active';

  if p_to_enrollment_status in ('enrolled','active') and v_guardian_count = 0 then
    insert into public.ac360_school_integrity_findings(run_id, org_id, finding_key, severity, entity_type, entity_id, message, recommendation, metadata_json)
    select r.id, p_org_id, 'student_enrollment_without_guardian', 'high', 'student', p_student_id, 'Student enrollment transition requested without active guardian link.', 'Link at least one guardian before operational enrollment.', coalesce(p_metadata,'{}'::jsonb)
    from public.ac360_school_integrity_runs r where false;
    -- No blocking here: Phase 2B logs and lets guard/policy decide in later UI workflow.
  end if;

  v_new_status := coalesce(p_to_status, case when p_to_enrollment_status in ('withdrawn','graduated','archived') then 'archived' when p_to_enrollment_status = 'paused' then 'inactive' else 'active' end);

  update public.ac360_school_students
  set enrollment_status = p_to_enrollment_status,
      status = v_new_status,
      exited_on = case when p_to_enrollment_status in ('withdrawn','graduated','archived') then coalesce(exited_on, current_date) else exited_on end,
      archived_at = case when v_new_status = 'archived' then coalesce(archived_at, now()) else archived_at end,
      metadata_json = metadata_json || jsonb_build_object('lastLifecycleTransitionAt', now(), 'lastLifecycleReason', p_reason),
      updated_at = now()
  where id = p_student_id and org_id = p_org_id;

  v_event_id := public.ac360_school_record_lifecycle_event(
    p_org_id, v_student.campus_id, 'student', p_student_id, 'school.student.transition',
    v_student.status, v_new_status, v_student.enrollment_status, p_to_enrollment_status,
    p_reason, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('guardianCount', v_guardian_count, 'activeEnrollmentCount', v_enrollment_count)
  );

  perform public.ac360_measure_capacity(p_org_id, 'students', public.ac360_school_current_capacity(p_org_id,'students'), 'ac360_school_students', '{"source":"phase_2b_student_transition"}'::jsonb);

  return jsonb_build_object('ok', true, 'studentId', p_student_id, 'eventId', v_event_id, 'fromStatus', v_student.status, 'toStatus', v_new_status, 'fromEnrollmentStatus', v_student.enrollment_status, 'toEnrollmentStatus', p_to_enrollment_status, 'guardianCount', v_guardian_count, 'activeEnrollmentCount', v_enrollment_count);
end;
$$;


--
-- Name: ac360_school_transport_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_transport_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_vehicles int; v_drivers int; v_routes int; v_assignments int; v_open_runs int; v_alerts int; v_failed_checks int;
begin
  select count(*) into v_vehicles from public.ac360_school_transport_vehicles where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='active';
  select count(*) into v_drivers from public.ac360_school_transport_drivers where org_id=p_org_id and status='active';
  select count(*) into v_routes from public.ac360_school_transport_routes where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='active';
  select count(*) into v_assignments from public.ac360_school_transport_student_assignments where org_id=p_org_id and status='active';
  select count(*) into v_open_runs from public.ac360_school_transport_route_runs where org_id=p_org_id and run_date=coalesce(p_as_of_date,current_date) and status in ('planned','started','in_progress','incident');
  select count(*) into v_failed_checks from public.ac360_school_transport_safety_checks where org_id=p_org_id and checked_at::date=coalesce(p_as_of_date,current_date) and result in ('failed','blocked');
  select count(*) into v_alerts from public.ac360_school_transport_alerts where org_id=p_org_id and status in ('open','acknowledged');
  return jsonb_build_object('ok',true,'phase','phase_2k_transport_routes_vehicles_drivers','uiBuildAllowed',false,'counts',jsonb_build_object('vehiclesActive',v_vehicles,'driversActive',v_drivers,'routesActive',v_routes,'assignmentsActive',v_assignments,'openRuns',v_open_runs,'failedSafetyChecks',v_failed_checks,'openAlerts',v_alerts));
end $$;


--
-- Name: ac360_school_trigger_automation_run(uuid, uuid, text, text, text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_trigger_automation_run(p_org_id uuid, p_rule_id uuid DEFAULT NULL::uuid, p_run_key text DEFAULT NULL::text, p_trigger_event text DEFAULT 'manual'::text, p_target_module text DEFAULT 'general'::text, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid, p_input_json jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_record public.ac360_school_automation_runs%rowtype;
begin
  insert into public.ac360_school_automation_runs(org_id,rule_id,run_key,trigger_event,target_module,target_entity_type,target_entity_id,input_json,status,started_at,metadata_json) values(p_org_id,p_rule_id,coalesce(nullif(p_run_key,''),'RUN-'||substr(gen_random_uuid()::text,1,10)),coalesce(p_trigger_event,'manual'),coalesce(p_target_module,'general'),p_target_entity_type,p_target_entity_id,coalesce(p_input_json,'{}'::jsonb),'running',now(),coalesce(p_metadata,'{}'::jsonb)) returning * into v_record;
  insert into public.ac360_school_automation_run_events(org_id,automation_run_id,event_type,severity,message,payload_json) values(p_org_id,v_record.id,'run_started','info','Automation run started.',coalesce(p_input_json,'{}'::jsonb));
  return jsonb_build_object('ok',true,'automationRun',to_jsonb(v_record));
end $$;


--
-- Name: ac360_school_update_admission_stage(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_admission_stage(p_org_id uuid, p_lead_id uuid, p_stage_key text, p_lead_status text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_lead public.ac360_school_admission_leads%rowtype;
  v_stage_id uuid;
  v_from text;
  v_to text;
begin
  select * into v_lead from public.ac360_school_admission_leads where id=p_lead_id and org_id=p_org_id;
  if v_lead.id is null then raise exception 'lead not found'; end if;
  v_from := v_lead.lead_status;
  select id, stage_type into v_stage_id, v_to from public.ac360_school_admission_stages where pipeline_id=v_lead.pipeline_id and stage_key=p_stage_key limit 1;
  if v_stage_id is null then raise exception 'stage not found'; end if;
  v_to := coalesce(nullif(p_lead_status,''), case when v_to='open' then 'new' else v_to end);

  update public.ac360_school_admission_leads
  set stage_id=v_stage_id, lead_status=v_to, status=case when v_to='converted' then 'converted' when v_to='lost' then 'lost' else status end, lost_reason=case when v_to='lost' then p_reason else lost_reason end, updated_at=now()
  where id=p_lead_id and org_id=p_org_id;

  insert into public.ac360_school_admission_conversion_events(org_id,lead_id,event_key,event_type,from_status,to_status,actor_app_user_id,message,metadata_json)
  values(p_org_id,p_lead_id,'lead.stage.updated','stage_transition',v_from,v_to,p_actor_app_user_id,coalesce(p_reason,'Admission stage updated.'),coalesce(p_metadata,'{}'::jsonb));

  return jsonb_build_object('ok',true,'lead_id',p_lead_id,'from_status',v_from,'to_status',v_to);
end;
$$;


--
-- Name: ac360_school_update_guardian_portal_status(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_guardian_portal_status(p_org_id uuid, p_guardian_id uuid, p_portal_status text, p_status text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_guardian public.ac360_school_guardians%rowtype;
  v_new_status text;
  v_event_id uuid;
begin
  select * into v_guardian from public.ac360_school_guardians where org_id = p_org_id and id = p_guardian_id for update;
  if v_guardian.id is null then raise exception 'Guardian not found for this organization'; end if;
  v_new_status := coalesce(p_status, case when p_portal_status in ('restricted','disabled') then 'inactive' else 'active' end);

  update public.ac360_school_guardians
  set portal_status = p_portal_status,
      status = v_new_status,
      metadata_json = metadata_json || jsonb_build_object('lastPortalStatusChangeAt', now(), 'lastPortalStatusReason', p_reason),
      updated_at = now()
  where org_id = p_org_id and id = p_guardian_id;

  v_event_id := public.ac360_school_record_lifecycle_event(
    p_org_id, v_guardian.campus_id, 'guardian', p_guardian_id, 'school.guardian.portal_status.update',
    v_guardian.status, v_new_status, v_guardian.portal_status, p_portal_status,
    p_reason, p_actor_app_user_id, coalesce(p_metadata,'{}'::jsonb)
  );

  return jsonb_build_object('ok', true, 'guardianId', p_guardian_id, 'eventId', v_event_id, 'fromPortalStatus', v_guardian.portal_status, 'toPortalStatus', p_portal_status, 'status', v_new_status);
end;
$$;


--
-- Name: ac360_school_update_incident_status(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_incident_status(p_org_id uuid, p_incident_id uuid, p_status text, p_parent_notification_status text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old text; v_new text; v_row public.ac360_school_incident_reports%rowtype;
begin
  select status into v_old from public.ac360_school_incident_reports where id=p_incident_id and org_id=p_org_id;
  update public.ac360_school_incident_reports set status=coalesce(p_status,status), parent_notification_status=coalesce(p_parent_notification_status,parent_notification_status), closed_by=case when coalesce(p_status,status) in ('closed','resolved') then p_actor_app_user_id else closed_by end, closed_at=case when coalesce(p_status,status) in ('closed','resolved') then now() else closed_at end, metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb), updated_at=now() where id=p_incident_id and org_id=p_org_id returning * into v_row;
  if v_row.id is null then return jsonb_build_object('ok',false,'error','Incident not found.'); end if;
  v_new := v_row.status;
  insert into public.ac360_school_incident_events(org_id,incident_id,event_key,event_type,status_from,status_to,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,p_incident_id,'incident.status.update','status',v_old,v_new,'info',coalesce(p_note,'Incident status updated.'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'incidentId',p_incident_id,'status',v_new);
end $$;


--
-- Name: ac360_school_update_intake_submission_status(uuid, uuid, text, text, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_intake_submission_status(p_org_id uuid, p_submission_id uuid, p_status text, p_linked_entity_type text DEFAULT NULL::text, p_linked_entity_id uuid DEFAULT NULL::uuid, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_sub public.ac360_school_intake_submissions%rowtype;
begin
  update public.ac360_school_intake_submissions set status=coalesce(nullif(p_status,''),status), linked_entity_type=coalesce(p_linked_entity_type,linked_entity_type), linked_entity_id=coalesce(p_linked_entity_id,linked_entity_id), processed_at=case when coalesce(nullif(p_status,''),status) in ('converted','rejected','duplicate','archived') then now() else processed_at end, metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb), updated_at=now() where id=p_submission_id and org_id=p_org_id returning * into v_sub;
  if v_sub.id is not null then insert into public.ac360_school_intake_events(org_id,submission_id,event_type,severity,message,actor_app_user_id,payload_json) values(p_org_id,v_sub.id,'submission.status.'||v_sub.status,'info',p_note,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)); end if;
  return jsonb_build_object('ok',v_sub.id is not null,'submission',to_jsonb(v_sub));
end $$;


--
-- Name: ac360_school_update_notification_preference(uuid, uuid, text, uuid, text, boolean, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_notification_preference(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_recipient_type text DEFAULT 'guardian'::text, p_recipient_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'whatsapp'::text, p_is_enabled boolean DEFAULT true, p_consent_status text DEFAULT 'explicit'::text, p_language_code text DEFAULT 'fr'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pref public.ac360_school_notification_preferences%rowtype;
begin
  insert into public.ac360_school_notification_preferences(org_id,campus_id,recipient_type,recipient_id,channel,is_enabled,consent_status,language_code,updated_by,metadata_json)
  values (p_org_id,p_campus_id,coalesce(p_recipient_type,'guardian'),p_recipient_id,coalesce(p_channel,'whatsapp'),coalesce(p_is_enabled,true),coalesce(p_consent_status,'explicit'),coalesce(p_language_code,'fr'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
  on conflict (org_id, recipient_type, recipient_id, channel) do update set
    campus_id=excluded.campus_id,
    is_enabled=excluded.is_enabled,
    consent_status=excluded.consent_status,
    language_code=excluded.language_code,
    updated_by=excluded.updated_by,
    metadata_json=public.ac360_school_notification_preferences.metadata_json || excluded.metadata_json,
    updated_at=now()
  returning * into v_pref;
  return jsonb_build_object('ok', true, 'preference', to_jsonb(v_pref));
end $$;


--
-- Name: ac360_school_update_onboarding_step(uuid, uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_onboarding_step(p_org_id uuid, p_step_id uuid, p_status text DEFAULT 'completed'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_blocker_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_step public.ac360_school_onboarding_steps%rowtype; v_project_id uuid; v_progress numeric;
begin
  update public.ac360_school_onboarding_steps set status=coalesce(nullif(p_status,''),status),blocker_reason=p_blocker_reason,completed_at=case when coalesce(nullif(p_status,''),status)='completed' then now() else completed_at end,completed_by=case when coalesce(nullif(p_status,''),status)='completed' then p_actor_app_user_id else completed_by end,metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=p_step_id and org_id=p_org_id returning * into v_step;
  v_project_id := v_step.onboarding_project_id;
  select case when count(*)=0 then 0 else round((count(*) filter(where status='completed'))::numeric*100/count(*),2) end into v_progress from public.ac360_school_onboarding_steps where onboarding_project_id=v_project_id;
  update public.ac360_school_onboarding_projects set progress_percent=coalesce(v_progress,0),status=case when coalesce(v_progress,0)>=100 then 'completed' else status end,stage=case when coalesce(v_progress,0)>=100 then 'completed' else stage end,updated_at=now() where id=v_project_id and org_id=p_org_id;
  return jsonb_build_object('ok',v_step.id is not null,'onboarding_step',to_jsonb(v_step),'progress_percent',v_progress);
end $$;


--
-- Name: ac360_school_update_parent_request_status(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_parent_request_status(p_org_id uuid, p_request_id uuid, p_status text, p_resolution_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old text; v_request public.ac360_school_parent_requests%rowtype;
begin
  select status into v_old from public.ac360_school_parent_requests where id=p_request_id and org_id=p_org_id;
  update public.ac360_school_parent_requests set status=coalesce(nullif(p_status,''),status), resolution_note=coalesce(p_resolution_note,resolution_note), resolved_at=case when coalesce(nullif(p_status,''),status) in ('approved','rejected','resolved','cancelled','archived') then now() else resolved_at end, metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb), updated_at=now() where id=p_request_id and org_id=p_org_id returning * into v_request;
  if v_request.id is not null then insert into public.ac360_school_parent_request_events(org_id,parent_request_id,event_type,previous_status,next_status,note,actor_app_user_id,metadata_json) values(p_org_id,v_request.id,'request.status.update',v_old,v_request.status,p_resolution_note,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)); end if;
  return jsonb_build_object('ok',v_request.id is not null,'parent_request',to_jsonb(v_request));
end $$;


--
-- Name: ac360_school_update_parenttrust_appointment_status(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_parenttrust_appointment_status(p_org_id uuid, p_appointment_id uuid, p_status text, p_outcome_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  update public.ac360_school_parenttrust_appointments set status=p_status,outcome_note=coalesce(p_outcome_note,outcome_note),metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=p_appointment_id and org_id=p_org_id returning id into v_id;
  if v_id is null then return jsonb_build_object('ok',false,'error','ParentTrust appointment not found.'); end if;
  return jsonb_build_object('ok',true,'appointmentId',v_id,'status',p_status);
end $$;


--
-- Name: ac360_school_update_parenttrust_complaint_status(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_parenttrust_complaint_status(p_org_id uuid, p_complaint_id uuid, p_status text, p_note text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old text; v_id uuid;
begin
  select status into v_old from public.ac360_school_parenttrust_complaints where id=p_complaint_id and org_id=p_org_id;
  if v_old is null then return jsonb_build_object('ok',false,'error','ParentTrust complaint not found.'); end if;
  update public.ac360_school_parenttrust_complaints set status=p_status,resolution_summary=case when p_status in ('resolved','closed') then coalesce(p_note,resolution_summary) else resolution_summary end,resolved_at=case when p_status in ('resolved','closed') then now() else resolved_at end,metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=p_complaint_id returning id into v_id;
  insert into public.ac360_school_parenttrust_complaint_events(org_id,complaint_id,event_type,from_status,to_status,note,actor_app_user_id,metadata_json) values(p_org_id,p_complaint_id,'status_changed',v_old,p_status,p_note,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'complaintId',v_id,'fromStatus',v_old,'toStatus',p_status);
end $$;


--
-- Name: ac360_school_update_staff_shift_status(uuid, uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_staff_shift_status(p_org_id uuid, p_assignment_id uuid, p_status text, p_attendance_status text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_row public.ac360_school_staff_shift_assignments%rowtype;
begin
  if p_assignment_id is null then return jsonb_build_object('ok',false,'error','assignmentId is required.'); end if;
  update public.ac360_school_staff_shift_assignments set status=coalesce(p_status,status), attendance_status=coalesce(p_attendance_status,attendance_status), notes=coalesce(p_reason,notes), updated_at=now(), metadata_json=metadata_json || coalesce(p_metadata,'{}'::jsonb) where id=p_assignment_id and org_id=p_org_id returning * into v_row;
  if v_row.id is null then return jsonb_build_object('ok',false,'error','Shift assignment not found.'); end if;
  insert into public.ac360_school_hr_events(org_id,campus_id,staff_profile_id,event_key,event_type,related_entity_type,related_entity_id,severity,message,actor_app_user_id,metadata_json)
  values(p_org_id,v_row.campus_id,v_row.staff_profile_id,'hr.shift.status.update','schedule','staff_shift_assignment',v_row.id,'info','Staff shift status updated to ' || coalesce(p_status,'unchanged') || '.',p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  return jsonb_build_object('ok',true,'assignmentId',v_row.id,'status',v_row.status);
end $$;


--
-- Name: ac360_school_update_task_status(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_update_task_status(p_org_id uuid, p_task_id uuid, p_to_status text, p_reason text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_task public.ac360_school_tasks%rowtype; v_from text;
begin
  if p_org_id is null or p_task_id is null then raise exception 'p_org_id and p_task_id are required'; end if;
  select * into v_task from public.ac360_school_tasks where id=p_task_id and org_id=p_org_id for update;
  if v_task.id is null then raise exception 'Task not found'; end if;
  v_from := v_task.status;
  update public.ac360_school_tasks set status=p_to_status, blocked_reason=case when p_to_status='blocked' then p_reason else blocked_reason end, completed_at=case when p_to_status='done' then now() else completed_at end, updated_at=now() where id=p_task_id returning * into v_task;
  insert into public.ac360_school_task_status_transitions(org_id,task_id,from_status,to_status,reason,changed_by,metadata_json) values(p_org_id,p_task_id,v_from,p_to_status,p_reason,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb));
  insert into public.ac360_school_operation_events(org_id,campus_id,event_key,action_key,entity_type,entity_id,severity,message,actor_app_user_id,metadata_json) values(p_org_id,v_task.campus_id,'school_ops.task.status_changed','school.task.status.update','task',v_task.id,'info','Task status updated from '||coalesce(v_from,'none')||' to '||p_to_status||'.',p_actor_app_user_id,jsonb_build_object('phase','phase_2g'));
  return jsonb_build_object('ok',true,'task',to_jsonb(v_task),'fromStatus',v_from,'toStatus',p_to_status);
end;
$$;


--
-- Name: ac360_school_upsert_ai_prompt_template(uuid, uuid, text, text, text, text, text, text, text, jsonb, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_upsert_ai_prompt_template(p_org_id uuid, p_template_id uuid DEFAULT NULL::uuid, p_prompt_key text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_prompt_type text DEFAULT 'message'::text, p_target_module text DEFAULT 'general'::text, p_language text DEFAULT 'fr'::text, p_system_prompt text DEFAULT NULL::text, p_user_prompt_template text DEFAULT NULL::text, p_variables_json jsonb DEFAULT '[]'::jsonb, p_safety_json jsonb DEFAULT '{}'::jsonb, p_status text DEFAULT 'draft'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_record public.ac360_school_ai_prompt_templates%rowtype;
begin
  if p_template_id is null then
    insert into public.ac360_school_ai_prompt_templates(org_id,prompt_key,label,prompt_type,target_module,language,system_prompt,user_prompt_template,variables_json,safety_json,status,created_by,metadata_json)
    values(p_org_id,coalesce(nullif(p_prompt_key,''),'prompt-'||substr(gen_random_uuid()::text,1,8)),coalesce(nullif(p_label,''),'AI Prompt'),coalesce(p_prompt_type,'message'),coalesce(p_target_module,'general'),coalesce(p_language,'fr'),p_system_prompt,coalesce(p_user_prompt_template,'{{input}}'),coalesce(p_variables_json,'[]'::jsonb),coalesce(p_safety_json,'{}'::jsonb),coalesce(p_status,'draft'),p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb))
    on conflict(org_id,prompt_key) do update set label=excluded.label,prompt_type=excluded.prompt_type,target_module=excluded.target_module,language=excluded.language,system_prompt=excluded.system_prompt,user_prompt_template=excluded.user_prompt_template,variables_json=excluded.variables_json,safety_json=excluded.safety_json,status=excluded.status,metadata_json=public.ac360_school_ai_prompt_templates.metadata_json || excluded.metadata_json,updated_at=now()
    returning id into v_id;
  else
    update public.ac360_school_ai_prompt_templates set label=coalesce(nullif(p_label,''),label),prompt_type=coalesce(p_prompt_type,prompt_type),target_module=coalesce(p_target_module,target_module),language=coalesce(p_language,language),system_prompt=coalesce(p_system_prompt,system_prompt),user_prompt_template=coalesce(p_user_prompt_template,user_prompt_template),variables_json=coalesce(p_variables_json,variables_json),safety_json=coalesce(p_safety_json,safety_json),status=coalesce(p_status,status),metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=p_template_id and org_id=p_org_id returning id into v_id;
  end if;
  select * into v_record from public.ac360_school_ai_prompt_templates where id=v_id;
  return jsonb_build_object('ok',true,'promptTemplate',to_jsonb(v_record));
end $$;


