-- Name: ac360_school_verify_custom_domain(uuid, uuid, boolean, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_verify_custom_domain(p_org_id uuid, p_domain_id uuid, p_verified boolean DEFAULT false, p_ssl_status text DEFAULT 'pending'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_dns_result jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_domain public.ac360_school_custom_domains%rowtype; v_prev text;
begin
  select status into v_prev from public.ac360_school_custom_domains where id=p_domain_id and org_id=p_org_id;
  update public.ac360_school_custom_domains set status=case when p_verified then 'active' else 'failed' end, ssl_status=coalesce(nullif(p_ssl_status,''),ssl_status), verified_at=case when p_verified then now() else verified_at end, activated_at=case when p_verified then now() else activated_at end, last_checked_at=now(), metadata_json=metadata_json||coalesce(p_metadata,'{}'::jsonb), updated_at=now()
  where id=p_domain_id and org_id=p_org_id returning * into v_domain;
  insert into public.ac360_school_domain_verification_events(org_id,domain_id,event_type,previous_status,next_status,dns_result_json,ssl_result_json,message,actor_app_user_id)
  values(p_org_id,p_domain_id,'verification_check',v_prev,v_domain.status,coalesce(p_dns_result,'{}'::jsonb),jsonb_build_object('ssl_status',v_domain.ssl_status),case when p_verified then 'Domain verified and activated.' else 'Domain verification failed.' end,p_actor_app_user_id);
  if not p_verified then
    insert into public.ac360_school_integration_alerts(org_id,domain_id,alert_key,alert_type,severity,title,message,metadata_json)
    values(p_org_id,p_domain_id,'domain-verification-failed-'||p_domain_id,'domain_verification_failed','warning','Custom domain verification failed','DNS or SSL verification failed for custom domain.',jsonb_build_object('domain_id',p_domain_id))
    on conflict(org_id,alert_key) do update set status='open',message=excluded.message,metadata_json=excluded.metadata_json,updated_at=now();
  end if;
  return jsonb_build_object('ok',v_domain.id is not null,'domain',to_jsonb(v_domain));
end $$;


--
-- Name: ac360_school_workflows_dashboard(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_school_workflows_dashboard(p_org_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if p_org_id is null then raise exception 'p_org_id is required'; end if;
  return jsonb_build_object(
    'ok', true,
    'phase', 'phase_2g_tasks_approvals_workflows_operations',
    'uiBuildAllowed', false,
    'counts', jsonb_build_object(
      'boards', (select count(*) from public.ac360_school_task_boards where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='active'),
      'openTasks', (select count(*) from public.ac360_school_tasks where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('planned','in_progress','blocked')),
      'overdueTasks', (select count(*) from public.ac360_school_tasks where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('planned','in_progress','blocked') and due_at is not null and due_at < now()),
      'pendingApprovals', (select count(*) from public.ac360_school_approval_requests where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status='pending'),
      'runningWorkflows', (select count(*) from public.ac360_school_workflow_instances where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('running','paused','blocked')),
      'openTickets', (select count(*) from public.ac360_school_operations_tickets where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('open','in_progress','blocked')),
      'openAlerts', (select count(*) from public.ac360_school_operations_alerts where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) and status in ('open','in_progress'))
    ),
    'latestSnapshot', (select to_jsonb(s) from public.ac360_school_operations_snapshots s where s.org_id=p_org_id and (p_campus_id is null or s.campus_id=p_campus_id) order by s.created_at desc limit 1),
    'recentAlerts', coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from (select * from public.ac360_school_operations_alerts where org_id=p_org_id and (p_campus_id is null or campus_id=p_campus_id) order by created_at desc limit 10) a), '[]'::jsonb)
  );
end;
$$;


--
-- Name: ac360_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac360_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: ac_capital_ai_agent_runs_legacy_sync_05(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ai_agent_runs_legacy_sync_05() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if nullif(new.agent_key, '') is null
     and new.agent_id is not null then
    select a.agent_key
    into new.agent_key
    from public.ac_capital_ai_agents a
    where a.id = new.agent_id;
  end if;

  new.agent_key := coalesce(
    nullif(new.agent_key, ''),
    'legacy-agent-run'
  );

  new.trigger_type := coalesce(
    nullif(new.trigger_type, ''),
    case
      when coalesce(new.input_source, '') ilike '%schedul%'
        then 'scheduled'
      else 'manual'
    end
  );

  new.finished_at := coalesce(
    new.finished_at,
    new.completed_at
  );

  new.completed_at := coalesce(
    new.completed_at,
    new.finished_at
  );

  new.actor_id := coalesce(
    new.actor_id,
    new.created_by
  );

  new.created_by := coalesce(
    new.created_by,
    new.actor_id
  );

  new.updated_at := coalesce(new.updated_at, now());

  return new;
end
$$;


--
-- Name: ac_capital_ai_agents_legacy_sync_05(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ai_agents_legacy_sync_05() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.agent_key := coalesce(
    nullif(new.agent_key, ''),
    'legacy-agent-' || new.id::text
  );

  new.name := coalesce(
    nullif(new.name, ''),
    nullif(new.agent_name, ''),
    new.agent_key
  );

  new.agent_name := new.name;
  new.description := coalesce(new.description, new.purpose);
  new.purpose := coalesce(new.purpose, new.description);

  new.status := case lower(coalesce(new.status, 'paused'))
    when 'active' then 'active'
    when 'disabled' then 'disabled'
    else 'paused'
  end;

  new.updated_at := coalesce(new.updated_at, now());

  return new;
end
$$;


--
-- Name: ac_capital_capture_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_capture_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  payload jsonb := to_jsonb(new);
  id_value uuid;
  version_value bigint;
  changed text[] := '{}';
  key text;
begin
  id_value := (payload ->> 'id')::uuid;
  version_value := coalesce((payload ->> 'record_version')::bigint, 1);
  if tg_op = 'UPDATE' then
    for key in select jsonb_object_keys(payload) loop
      if (to_jsonb(old) -> key) is distinct from (payload -> key) then
        changed := array_append(changed, key);
      end if;
    end loop;
  end if;
  insert into public.ac_capital_record_versions(
    entity_type, entity_id, version_no, change_type, snapshot, changed_fields, source_workspace
  ) values (
    tg_table_name, id_value, version_value, lower(tg_op), payload, changed, tg_table_name
  ) on conflict (entity_type, entity_id, version_no) do nothing;
  return new;
end
$$;


--
-- Name: ac_capital_emit_lifecycle_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_emit_lifecycle_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  payload jsonb := to_jsonb(new);
  id_value uuid := (payload ->> 'id')::uuid;
  version_value text := coalesce(payload ->> 'record_version', payload ->> 'updated_at', payload ->> 'created_at', 'v1');
  event_name text;
  entity_name text := tg_argv[0];
  workspace_name text := tg_argv[1];
  base_event text := tg_argv[2];
  idempotency text;
begin
  -- Agent-authored updates are already represented by the originating event and
  -- agent output. Suppress only the update carrying a fresh automation marker,
  -- preventing self-triggering loops while allowing later human edits to emit.
  if coalesce(payload ->> 'last_automation_at', '') <> ''
     and (
       tg_op = 'INSERT'
       or coalesce(to_jsonb(old) ->> 'last_automation_at', '')
          is distinct from coalesce(payload ->> 'last_automation_at', '')
     ) then
    return new;
  end if;

  event_name := base_event || case when tg_op = 'INSERT' then '.created' else '.updated' end;

  if entity_name = 'source' and coalesce(payload ->> 'verification_status','') in ('validated','verified','official') then
    event_name := 'source.validated';
  elsif entity_name = 'qualification' and coalesce(payload ->> 'decision_label','') ~* 'pursue|approved|qualified' then
    event_name := 'qualification.approved';
  elsif entity_name = 'case' and coalesce(payload ->> 'status','') ~* 'ready|approval' then
    event_name := 'case.ready';
  elsif entity_name = 'approval' and coalesce(payload ->> 'status','') = 'approved' then
    event_name := 'approval.granted';
  elsif entity_name = 'outcome' then
    event_name := 'outcome.recorded';
  end if;

  idempotency := format('db:%s:%s:%s:%s', tg_table_name, id_value, event_name, version_value);

  insert into public.ac_capital_orchestrator_events(
    event_type, entity_type, entity_id, source_workspace, payload,
    idempotency_key, priority, status, available_at, created_by, updated_at
  ) values (
    event_name, entity_name, id_value, workspace_name,
    jsonb_build_object('record', payload, 'table', tg_table_name, 'operation', tg_op),
    idempotency,
    case when event_name in ('case.ready','approval.granted','outcome.recorded') then 'high' else 'normal' end,
    'queued', now(), 'database-event-bridge', now()
  ) on conflict (idempotency_key) do nothing;

  return new;
end
$$;


--
-- Name: ac_capital_ic10_decide_approval(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ic10_decide_approval(p_approval_id uuid, p_decision text, p_note text, p_conditions jsonb, p_decided_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  approval_row public.ac_capital_universal_approvals%rowtype;
  decision_value text := lower(coalesce(p_decision,''));
  status_value text;
  table_name text;
  version_expression text;
  current_version text := '1';
  object_snapshot jsonb := '{}'::jsonb;
  event_row public.ac_capital_orchestrator_events%rowtype;
begin
  if decision_value = 'request-revision' then decision_value := 'revision'; end if;
  if decision_value not in ('approve','reject','revision') then
    raise exception 'AC_CAPITAL_UNSUPPORTED_APPROVAL_DECISION';
  end if;

  select * into approval_row
  from public.ac_capital_universal_approvals
  where id = p_approval_id
  for update;
  if not found then raise exception 'AC_CAPITAL_APPROVAL_NOT_FOUND'; end if;

  table_name := case approval_row.object_type
    when 'case' then 'ac_capital_cases'
    when 'artifact' then 'ac_capital_artifacts'
    when 'qualification' then 'ac_capital_qualification_dossiers'
    when 'pipeline' then 'ac_capital_pipeline_records'
    when 'report' then 'ac_capital_strategy_reports'
    else null
  end;
  version_expression := case approval_row.object_type
    when 'artifact' then 'coalesce(current_version, record_version, 1)::text'
    else 'coalesce(record_version, 1)::text'
  end;

  if table_name is not null and approval_row.object_id is not null then
    execute format('select %s, to_jsonb(t) from public.%I t where id = $1', version_expression, table_name)
      into current_version, object_snapshot
      using approval_row.object_id;
    if object_snapshot is null or object_snapshot = '{}'::jsonb then
      raise exception 'AC_CAPITAL_APPROVAL_OBJECT_NOT_FOUND';
    end if;
  else
    current_version := approval_row.object_version;
    object_snapshot := approval_row.snapshot;
  end if;

  if decision_value = 'approve' and current_version is distinct from approval_row.object_version then
    update public.ac_capital_universal_approvals
    set status = 'superseded',
        superseded_at = now(),
        superseded_by_version = current_version,
        superseded_reason = format('Approval requested for version %s; object is version %s.', approval_row.object_version, current_version),
        decision_note = coalesce(nullif(p_note,''), format('Object advanced to version %s.', current_version)),
        updated_at = now()
    where id = p_approval_id
    returning * into approval_row;

    return jsonb_build_object(
      'conflict', true,
      'requestedVersion', approval_row.object_version,
      'currentVersion', current_version,
      'approval', to_jsonb(approval_row),
      'object', object_snapshot
    );
  end if;

  status_value := case decision_value
    when 'approve' then 'approved'
    when 'reject' then 'rejected'
    else 'revision-requested'
  end;

  update public.ac_capital_universal_approvals
  set status = status_value,
      decided_by = p_decided_by,
      decided_at = now(),
      decision_note = coalesce(nullif(p_note,''), decision_value),
      conditions = coalesce(p_conditions, conditions, '[]'::jsonb),
      snapshot_hash = coalesce(nullif(snapshot_hash,''), encode(digest(snapshot::text,'sha256'),'hex')),
      updated_at = now()
  where id = p_approval_id
  returning * into approval_row;

  if decision_value = 'approve' and approval_row.object_type = 'case' then
    update public.ac_capital_cases
    set founder_approval_status = 'approved', updated_at = now()
    where id = approval_row.object_id;
  elsif decision_value = 'approve' and approval_row.object_type = 'artifact' then
    update public.ac_capital_artifacts
    set approval_status = 'approved',
        approved_version = current_version::integer,
        approved_by = p_decided_by,
        approved_at = now(),
        immutable_snapshot_hash = coalesce(nullif(approval_row.snapshot_hash,''), encode(digest(approval_row.snapshot::text,'sha256'),'hex')),
        updated_at = now()
    where id = approval_row.object_id;
  end if;

  if decision_value = 'approve' then
    insert into public.ac_capital_orchestrator_events(
      event_type, entity_type, entity_id, source_workspace, payload,
      idempotency_key, priority, status, available_at, created_by, updated_at
    ) values (
      'approval.granted','approval',approval_row.id,'approvals',
      jsonb_build_object('approvalId',approval_row.id,'objectType',approval_row.object_type,'objectId',approval_row.object_id,'objectVersion',current_version,'decisionNote',p_note),
      format('approval.granted:%s:%s',approval_row.id,current_version),
      'high','queued',now(),p_decided_by,now()
    ) on conflict (idempotency_key) do nothing
    returning * into event_row;
  end if;

  return jsonb_build_object(
    'conflict', false,
    'governedVersion', current_version,
    'approval', to_jsonb(approval_row),
    'object', object_snapshot,
    'event', case when event_row.id is null then null else to_jsonb(event_row) end
  );
end
$_$;


--
-- Name: ac_capital_ic10_protect_approved_artifact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ic10_protect_approved_artifact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.approval_status = 'approved'
     and new.approval_status = 'approved'
     and (
       new.current_version is distinct from old.current_version
       or new.content_snapshot is distinct from old.content_snapshot
       or new.source_snapshot is distinct from old.source_snapshot
       or new.entity_type is distinct from old.entity_type
       or new.entity_id is distinct from old.entity_id
       or new.immutable_snapshot_hash is distinct from old.immutable_snapshot_hash
     ) then
    raise exception 'AC_CAPITAL_APPROVED_ARTIFACT_IMMUTABLE';
  end if;
  return new;
end
$$;


--
-- Name: ac_capital_ic10_record_submission(uuid, uuid, uuid, text, text, text, text, text[], text, timestamp with time zone, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ic10_record_submission(p_pipeline_record_id uuid, p_case_id uuid, p_approval_id uuid, p_recipient text, p_method text, p_proof_reference text, p_proof_type text, p_documents text[], p_submitted_by text, p_submitted_at timestamp with time zone, p_coordinator_task_id uuid DEFAULT NULL::uuid, p_confirmation_received boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  pipeline_row public.ac_capital_pipeline_records%rowtype;
  case_row public.ac_capital_cases%rowtype;
  approval_row public.ac_capital_universal_approvals%rowtype;
  submission_row public.ac_capital_pipeline_submissions%rowtype;
  proof_row public.ac_capital_submission_proofs%rowtype;
  case_uuid uuid;
  case_version text;
begin
  if nullif(trim(p_proof_reference), '') is null then
    raise exception 'AC_CAPITAL_SUBMISSION_PROOF_REQUIRED';
  end if;
  if nullif(trim(p_recipient), '') is null then
    raise exception 'AC_CAPITAL_SUBMISSION_RECIPIENT_REQUIRED';
  end if;

  select * into pipeline_row
  from public.ac_capital_pipeline_records
  where id = p_pipeline_record_id
  for update;
  if not found then raise exception 'AC_CAPITAL_PIPELINE_NOT_FOUND'; end if;

  case_uuid := coalesce(
    p_case_id,
    case when coalesce(pipeline_row.case_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      then pipeline_row.case_id::uuid else null end
  );
  if case_uuid is null then raise exception 'AC_CAPITAL_SUBMISSION_CASE_REQUIRED'; end if;

  select * into case_row from public.ac_capital_cases where id = case_uuid;
  if not found then raise exception 'AC_CAPITAL_SUBMISSION_CASE_NOT_FOUND'; end if;
  case_version := coalesce(case_row.record_version, 1)::text;

  select * into approval_row
  from public.ac_capital_universal_approvals
  where object_type = 'case'
    and object_id = case_uuid
    and object_version = case_version
    and status = 'approved'
    and (p_approval_id is null or id = p_approval_id)
  order by decided_at desc nulls last, requested_at desc
  limit 1;
  if not found then
    raise exception 'AC_CAPITAL_SUBMISSION_EXACT_VERSION_APPROVAL_REQUIRED:case=%:version=%', case_uuid, case_version;
  end if;

  select * into proof_row
  from public.ac_capital_submission_proofs
  where pipeline_record_id = p_pipeline_record_id
    and proof_reference = p_proof_reference
  order by created_at desc
  limit 1;

  if proof_row.id is not null then
    return jsonb_build_object(
      'idempotent', true,
      'pipeline', to_jsonb(pipeline_row),
      'proof', to_jsonb(proof_row),
      'approval', to_jsonb(approval_row)
    );
  end if;

  insert into public.ac_capital_pipeline_submissions(
    pipeline_record_id, case_id, submitted_by, submitted_at, recipient, method,
    documents_included, version_submitted, proof_of_submission_reference,
    confirmation_received, result_status, updated_at
  ) values (
    p_pipeline_record_id, case_uuid::text, p_submitted_by,
    coalesce(p_submitted_at, now()), p_recipient, coalesce(nullif(p_method,''),'Manual'),
    coalesce(p_documents, '{}'), case_version, p_proof_reference,
    coalesce(p_confirmation_received, false), 'Submitted', now()
  ) returning * into submission_row;

  insert into public.ac_capital_submission_proofs(
    pipeline_record_id, case_id, coordinator_task_id, approval_id,
    submission_channel, recipient, submitted_at, proof_reference, proof_type,
    submitted_by, status, metadata, updated_at
  ) values (
    p_pipeline_record_id, case_uuid, p_coordinator_task_id, approval_row.id,
    coalesce(nullif(p_method,''),'Manual'), p_recipient, coalesce(p_submitted_at, now()),
    p_proof_reference, coalesce(nullif(p_proof_type,''),'manual-evidence'),
    p_submitted_by, 'recorded',
    jsonb_build_object('documentsIncluded',coalesce(to_jsonb(p_documents),'[]'::jsonb),'caseVersion',case_version),
    now()
  ) returning * into proof_row;

  insert into public.ac_capital_pipeline_stage_events(
    pipeline_record_id, previous_stage, new_stage, changed_by, changed_at,
    reason, evidence_reference, comments
  ) values (
    p_pipeline_record_id, pipeline_row.stage, 'Submitted', p_submitted_by, now(),
    'Exact-version approved manual submission proof recorded.', p_proof_reference,
    format('IC10 approval %s · case version %s', approval_row.id, case_version)
  );

  update public.ac_capital_pipeline_records
  set stage = 'Submitted',
      last_activity_at = now(),
      next_action = 'Confirm receipt and schedule follow-up',
      record_version = coalesce(record_version,1) + 1,
      updated_at = now()
  where id = p_pipeline_record_id
  returning * into pipeline_row;

  insert into public.ac_capital_stage_gate_evaluations(
    entity_type, entity_id, workspace_key, requested_stage, passed,
    evaluated_gates, blockers, evaluated_by, evaluated_at
  ) values (
    'pipeline', p_pipeline_record_id, 'pipeline', 'Submitted', true,
    jsonb_build_array(
      jsonb_build_object('gateKey','PIPELINE_APPROVAL_VALID','passed',true,'approvalId',approval_row.id,'objectVersion',case_version),
      jsonb_build_object('gateKey','PIPELINE_SUBMISSION_PROOF','passed',true,'proofId',proof_row.id)
    ),
    '[]'::jsonb, p_submitted_by, now()
  );

  insert into public.ac_capital_orchestrator_events(
    event_type, entity_type, entity_id, source_workspace, payload,
    idempotency_key, priority, status, available_at, created_by, updated_at
  ) values (
    'submission.recorded', 'pipeline', p_pipeline_record_id, 'pipeline',
    jsonb_build_object('submissionId',submission_row.id,'proofId',proof_row.id,'caseId',case_uuid,'approvalId',approval_row.id,'caseVersion',case_version),
    format('submission.recorded:%s:%s',p_pipeline_record_id,encode(digest(p_proof_reference,'sha256'),'hex')),
    'high','queued',now(),p_submitted_by,now()
  ) on conflict (idempotency_key) do nothing;

  return jsonb_build_object(
    'idempotent', false,
    'pipeline', to_jsonb(pipeline_row),
    'submission', to_jsonb(submission_row),
    'proof', to_jsonb(proof_row),
    'approval', to_jsonb(approval_row),
    'caseVersion', case_version
  );
end
$_$;


--
-- Name: ac_capital_ic10_request_case_approval(uuid, text, text, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ic10_request_case_approval(p_case_id uuid, p_approval_item text, p_reason text, p_comments text, p_risk_level text, p_requested_by text, p_approver text, p_due_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  case_row public.ac_capital_cases%rowtype;
  approval_row public.ac_capital_universal_approvals%rowtype;
  legacy_row public.ac_capital_case_founder_approvals%rowtype;
  event_row public.ac_capital_orchestrator_events%rowtype;
  v_object_version text;
  snapshot_hash text;
begin
  if nullif(trim(p_approval_item), '') is null then
    raise exception 'AC_CAPITAL_APPROVAL_ITEM_REQUIRED';
  end if;

  select * into case_row
  from public.ac_capital_cases
  where id = p_case_id
  for update;
  if not found then raise exception 'AC_CAPITAL_CASE_NOT_FOUND'; end if;

  update public.ac_capital_cases
  set founder_approval_status = 'pending',
      updated_at = now()
  where id = p_case_id
  returning * into case_row;

  v_object_version := coalesce(case_row.record_version, 1)::text;
  snapshot_hash := encode(digest(to_jsonb(case_row)::text, 'sha256'), 'hex');

  select * into approval_row
  from public.ac_capital_universal_approvals
  where object_type = 'case'
    and object_id = p_case_id
    and object_version = v_object_version
    and status = 'pending'
  order by requested_at desc
  limit 1;

  if approval_row.id is null then
    insert into public.ac_capital_universal_approvals(
      approval_type, object_type, object_id, object_version,
      snapshot, snapshot_hash, diff_snapshot, evidence_package,
      decision_requested, risk_level, status, approver_role,
      requested_by, requested_at, expires_at, updated_at
    ) values (
      'case-release', 'case', p_case_id, v_object_version,
      to_jsonb(case_row) || jsonb_build_object('_snapshotHash', snapshot_hash),
      snapshot_hash, '{}'::jsonb,
      jsonb_build_object(
        'approvalItem', p_approval_item,
        'reason', p_reason,
        'comments', p_comments
      ),
      p_approval_item, coalesce(nullif(p_risk_level, ''), 'high'),
      'pending', 'founder', p_requested_by, now(),
      case when p_due_date is null then null else p_due_date::timestamptz end,
      now()
    ) returning * into approval_row;
  end if;

  select * into legacy_row
  from public.ac_capital_case_founder_approvals
  where case_id = p_case_id
    and comments like ('Universal approval ' || approval_row.id::text || '%')
  order by created_at desc
  limit 1;

  if legacy_row.id is null then
    insert into public.ac_capital_case_founder_approvals(
      case_id, approval_item, status, reason, approver,
      due_date, comments, updated_at
    ) values (
      p_case_id, p_approval_item, 'required', p_reason,
      coalesce(nullif(p_approver, ''), 'Founder / Managing Director'),
      p_due_date,
      format('Universal approval %s · version %s · hash %s', approval_row.id, v_object_version, snapshot_hash),
      now()
    ) returning * into legacy_row;
  end if;

  insert into public.ac_capital_orchestrator_events(
    event_type, entity_type, entity_id, source_workspace, payload,
    idempotency_key, priority, status, available_at, created_by, updated_at
  ) values (
    'case.approval.requested', 'case', p_case_id, 'cases',
    jsonb_build_object(
      'approvalId', approval_row.id,
      'objectVersion', v_object_version,
      'snapshotHash', snapshot_hash
    ),
    format('case.approval.requested:%s:%s', p_case_id, v_object_version),
    'high', 'queued', now(), p_requested_by, now()
  ) on conflict (idempotency_key) do nothing
  returning * into event_row;

  return jsonb_build_object(
    'case', to_jsonb(case_row),
    'approval', to_jsonb(approval_row),
    'legacyApproval', to_jsonb(legacy_row),
    'event', case when event_row.id is null then null else to_jsonb(event_row) end,
    'objectVersion', v_object_version,
    'snapshotHash', snapshot_hash
  );
end
$$;


--
-- Name: ac_capital_ic10_supersede_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_ic10_supersede_approvals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  object_name text;
  new_version text;
  old_version text;
  material_old jsonb;
  material_new jsonb;
begin
  object_name := case tg_table_name
    when 'ac_capital_cases' then 'case'
    when 'ac_capital_artifacts' then 'artifact'
    when 'ac_capital_qualification_dossiers' then 'qualification'
    when 'ac_capital_pipeline_records' then 'pipeline'
    when 'ac_capital_strategy_reports' then 'report'
    else null
  end;

  if object_name is null then return new; end if;
  new_version := coalesce(to_jsonb(new)->>'record_version', to_jsonb(new)->>'current_version', '1');
  old_version := coalesce(to_jsonb(old)->>'record_version', to_jsonb(old)->>'current_version', '1');

  material_old := to_jsonb(old)
    - 'record_version' - 'updated_at' - 'founder_approval_status'
    - 'approval_status' - 'approved_by' - 'approved_at' - 'approved_version'
    - 'immutable_snapshot_hash' - 'last_integrity_check_at' - 'health_status'
    - 'last_automation_agent' - 'last_automation_at';
  material_new := to_jsonb(new)
    - 'record_version' - 'updated_at' - 'founder_approval_status'
    - 'approval_status' - 'approved_by' - 'approved_at' - 'approved_version'
    - 'immutable_snapshot_hash' - 'last_integrity_check_at' - 'health_status'
    - 'last_automation_agent' - 'last_automation_at';

  if new_version is distinct from old_version
     and material_new is distinct from material_old then
    update public.ac_capital_universal_approvals
       set status = 'superseded',
           superseded_at = now(),
           superseded_by_version = new_version,
           superseded_reason = format('%s advanced from version %s to %s', object_name, old_version, new_version),
           decision_note = coalesce(decision_note || E'\n', '') || format('Superseded automatically by IC10: object advanced to version %s.', new_version),
           updated_at = now()
     where object_type = object_name
       and object_id = new.id
       and object_version = old_version
       and status in ('pending','approved','conditionally-approved');
  end if;
  return new;
end
$$;


--
-- Name: ac_capital_touch_and_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_capital_touch_and_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'UPDATE' then
    new.record_version := coalesce(old.record_version, 1) + 1;
    if to_jsonb(new) ? 'updated_at' then
      new.updated_at := now();
    end if;
  end if;
  return new;
end
$$;


