--
-- Name: ac_whatsapp_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ac_whatsapp_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_message_id text NOT NULL,
    account_id uuid NOT NULL,
    conversation_id uuid,
    contact_id uuid,
    campaign_id uuid,
    campaign_recipient_id uuid,
    message_type text DEFAULT 'text'::text NOT NULL,
    chat_id text NOT NULL,
    body text,
    media_payload jsonb,
    status text DEFAULT 'queued'::text NOT NULL,
    priority integer DEFAULT 50 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    external_message_id text,
    last_error text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ac_whatsapp_outbox_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'queued'::text, 'processing'::text, 'sent'::text, 'failed'::text, 'cancelled'::text, 'expired'::text])))
);


--
-- Name: ac_whatsapp_claim_outbox(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_whatsapp_claim_outbox(p_worker_id text, p_limit integer DEFAULT 25) RETURNS SETOF public.ac_whatsapp_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select id from public.ac_whatsapp_outbox
    where status in ('queued','scheduled')
      and available_at <= now()
      and attempt_count < max_attempts
    order by priority desc, available_at asc
    for update skip locked
    limit greatest(1,least(coalesce(p_limit,25),200))
  )
  update public.ac_whatsapp_outbox o
  set status='processing', locked_at=now(), locked_by=p_worker_id,
      attempt_count=o.attempt_count+1, updated_at=now()
  from candidates c where o.id=c.id
  returning o.*;
end $$;


--
-- Name: ac_whatsapp_merge_contacts(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_whatsapp_merge_contacts(p_source_id uuid, p_target_id uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_correlation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source public.ac_whatsapp_contacts%rowtype;
  v_target public.ac_whatsapp_contacts%rowtype;
  v_conversations integer := 0;
begin
  if p_source_id = p_target_id then raise exception 'CONTACT_MERGE_SAME_RECORD'; end if;
  select * into v_source from public.ac_whatsapp_contacts where id = p_source_id for update;
  if not found then raise exception 'SOURCE_CONTACT_NOT_FOUND'; end if;
  select * into v_target from public.ac_whatsapp_contacts where id = p_target_id for update;
  if not found then raise exception 'TARGET_CONTACT_NOT_FOUND'; end if;

  update public.ac_whatsapp_conversations set contact_id = p_target_id, updated_at = now() where contact_id = p_source_id;
  get diagnostics v_conversations = row_count;
  update public.ac_whatsapp_messages set contact_id = p_target_id, updated_at = now() where contact_id = p_source_id;
  update public.ac_whatsapp_outbox set contact_id = p_target_id, updated_at = now() where contact_id = p_source_id;
  update public.ac_whatsapp_context_links set contact_id = p_target_id where contact_id = p_source_id;
  update public.ac_whatsapp_consent_records set contact_id = p_target_id where contact_id = p_source_id;
  update public.ac_whatsapp_followup_tasks set contact_id = p_target_id, updated_at = now() where contact_id = p_source_id;

  delete from public.ac_whatsapp_campaign_recipients s
   where s.contact_id = p_source_id
     and exists (select 1 from public.ac_whatsapp_campaign_recipients t where t.campaign_id = s.campaign_id and t.contact_id = p_target_id);
  update public.ac_whatsapp_campaign_recipients set contact_id = p_target_id, updated_at = now() where contact_id = p_source_id;

  update public.ac_whatsapp_contacts
     set display_name = coalesce(nullif(v_target.display_name,''), v_source.display_name),
         organization_name = coalesce(nullif(v_target.organization_name,''), v_source.organization_name),
         phone_number_e164 = coalesce(nullif(v_target.phone_number_e164,''), v_source.phone_number_e164),
         city = coalesce(nullif(v_target.city,''), v_source.city),
         tags = array(select distinct x from unnest(coalesce(v_target.tags,'{}') || coalesce(v_source.tags,'{}')) x),
         custom_fields = coalesce(v_source.custom_fields,'{}'::jsonb) || coalesce(v_target.custom_fields,'{}'::jsonb),
         updated_by = p_actor_user_id,
         updated_at = now()
   where id = p_target_id;

  update public.ac_whatsapp_contacts
     set archived_at = now(), archived_by = p_actor_user_id,
         archive_reason = 'Fusionné vers ' || p_target_id::text || coalesce(' · ' || nullif(p_reason,''),''),
         tags = array(select distinct x from unnest(coalesce(tags,'{}') || array['merged-source']) x),
         updated_by = p_actor_user_id, updated_at = now()
   where id = p_source_id;

  insert into public.ac_whatsapp_audit_events(actor_user_id,action,entity_type,entity_id,reason,previous_state,new_state,metadata,correlation_id)
  values(p_actor_user_id,'contact.merge','contact',p_target_id::text,p_reason,to_jsonb(v_target),
    jsonb_build_object('source_id',p_source_id,'target_id',p_target_id),jsonb_build_object('conversations_relinked',v_conversations),p_correlation_id);

  return jsonb_build_object('ok',true,'source_id',p_source_id,'target_id',p_target_id,'conversations_relinked',v_conversations);
end $$;


--
-- Name: ac_whatsapp_mz7_preserve_contact_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_whatsapp_mz7_preserve_contact_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$ declare oldj jsonb:=to_jsonb(old);newj jsonb:=to_jsonb(new);old_name text;new_name text;old_phone text;new_phone text;remote_id text;lid_digits text; begin old_name:=coalesce(oldj->>'display_name',oldj->>'name',oldj->>'contact_name');new_name:=coalesce(newj->>'display_name',newj->>'name',newj->>'contact_name'); if old_name is not null and length(btrim(old_name))>1 and lower(btrim(old_name)) not in('unknown','[unknown]','inconnu','[inconnu]','contact','whatsapp') and(new_name is null or length(btrim(new_name))<2 or lower(btrim(new_name)) in('unknown','[unknown]','inconnu','[inconnu]','contact','whatsapp') or regexp_replace(new_name,'[^0-9+]','','g')~'^\+?[0-9]{7,}$') then if newj?'display_name' then newj:=jsonb_set(newj,'{display_name}',to_jsonb(old_name));end if;if newj?'name' and oldj?'name' then newj:=jsonb_set(newj,'{name}',oldj->'name');end if;if newj?'contact_name' and oldj?'contact_name' then newj:=jsonb_set(newj,'{contact_name}',oldj->'contact_name');end if;end if; old_phone:=coalesce(oldj->>'phone_e164',oldj->>'e164',oldj->>'phone');new_phone:=coalesce(newj->>'phone_e164',newj->>'e164',newj->>'phone');remote_id:=coalesce(newj->>'remote_chat_id',newj->>'whatsapp_id',newj->>'remote_id','');if remote_id~*'@lid$' then lid_digits:=regexp_replace(remote_id,'@lid$','','i');else lid_digits:=null;end if;if old_phone~'^\+[1-9][0-9]{7,14}$' and(new_phone is null or new_phone='' or new_phone!~'^\+[1-9][0-9]{7,14}$' or(lid_digits is not null and regexp_replace(coalesce(new_phone,''),'[^0-9]','','g')=regexp_replace(lid_digits,'[^0-9]','','g'))) then if newj?'phone_e164' then newj:=jsonb_set(newj,'{phone_e164}',to_jsonb(old_phone));end if;if newj?'e164' and oldj?'e164' then newj:=jsonb_set(newj,'{e164}',oldj->'e164');end if;if newj?'phone' and oldj?'phone' then newj:=jsonb_set(newj,'{phone}',oldj->'phone');end if;end if;new:=jsonb_populate_record(new,newj);return new;end;$_$;


--
-- Name: ac_whatsapp_release_stale_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_whatsapp_release_stale_outbox(p_age_minutes integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n integer;
begin
  update public.ac_whatsapp_outbox
  set status='queued', locked_at=null, locked_by=null, available_at=now(), updated_at=now()
  where status='processing' and locked_at < now() - make_interval(mins => greatest(1,p_age_minutes));
  get diagnostics n = row_count; return n;
end $$;


--
-- Name: ac_whatsapp_remove_member(uuid, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_whatsapp_remove_member(p_user_id uuid, p_transfer_target_user_id uuid DEFAULT NULL::uuid, p_transfer_queue_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_correlation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_member public.ac_whatsapp_memberships%rowtype;
  v_conversations integer := 0;
  v_followups integer := 0;
  v_campaigns integer := 0;
begin
  select * into v_member from public.ac_whatsapp_memberships where user_id = p_user_id for update;
  if not found then raise exception 'MEMBERSHIP_NOT_FOUND'; end if;
  if p_transfer_target_user_id = p_user_id then raise exception 'INVALID_TRANSFER_TARGET'; end if;

  update public.ac_whatsapp_conversations
     set assigned_user_id = p_transfer_target_user_id,
         queue_id = coalesce(p_transfer_queue_id, queue_id),
         status = case when p_transfer_target_user_id is null then 'unassigned' else 'assigned' end,
         updated_at = now()
   where assigned_user_id = p_user_id
     and status not in ('resolved','closed','archived');
  get diagnostics v_conversations = row_count;

  update public.ac_whatsapp_followup_tasks
     set assigned_user_id = p_transfer_target_user_id,
         updated_at = now()
   where assigned_user_id = p_user_id and status = 'open';
  get diagnostics v_followups = row_count;

  update public.ac_whatsapp_campaigns
     set owner_user_id = p_transfer_target_user_id,
         updated_by = p_actor_user_id,
         updated_at = now()
   where owner_user_id = p_user_id
     and status not in ('completed','cancelled','failed');
  get diagnostics v_campaigns = row_count;

  delete from public.ac_whatsapp_account_access where user_id = p_user_id;
  delete from public.ac_whatsapp_queue_memberships where user_id = p_user_id;

  update public.ac_whatsapp_memberships
     set status = 'removed',
         removed_at = now(),
         removed_by = p_actor_user_id,
         removal_reason = nullif(btrim(coalesce(p_reason,'')),''),
         transfer_target_user_id = p_transfer_target_user_id,
         lifecycle_metadata = coalesce(lifecycle_metadata,'{}'::jsonb) || jsonb_build_object(
           'conversations_transferred', v_conversations,
           'followups_transferred', v_followups,
           'campaigns_transferred', v_campaigns,
           'transfer_queue_id', p_transfer_queue_id,
           'removed_at', now()
         ),
         updated_by = p_actor_user_id,
         updated_at = now()
   where user_id = p_user_id;

  insert into public.ac_whatsapp_audit_events(actor_user_id,action,entity_type,entity_id,reason,previous_state,new_state,metadata,correlation_id)
  values(p_actor_user_id,'membership.remove','membership',v_member.id::text,p_reason,to_jsonb(v_member),
    jsonb_build_object('status','removed','transfer_target_user_id',p_transfer_target_user_id,'transfer_queue_id',p_transfer_queue_id),
    jsonb_build_object('conversations',v_conversations,'followups',v_followups,'campaigns',v_campaigns),p_correlation_id);

  return jsonb_build_object('ok',true,'membership_id',v_member.id,'conversations',v_conversations,'followups',v_followups,'campaigns',v_campaigns);
end $$;


--
-- Name: ac_whatsapp_rollup_campaign_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_whatsapp_rollup_campaign_metrics() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.ac_whatsapp_campaigns c set
    total_recipients = x.total_recipients,
    queued_count = x.queued_count,
    sent_count = x.sent_count,
    delivered_count = x.delivered_count,
    read_count = x.read_count,
    reply_count = x.reply_count,
    positive_reply_count = x.positive_reply_count,
    conversion_count = x.conversion_count,
    failed_count = x.failed_count,
    completed_at = case when x.total_recipients > 0 and x.terminal_count = x.total_recipients then coalesce(c.completed_at,now()) else c.completed_at end,
    status = case when x.total_recipients > 0 and x.terminal_count = x.total_recipients and c.status not in ('cancelled','paused') then 'completed' else c.status end,
    updated_at = now()
  from (
    select campaign_id,
      count(*)::int total_recipients,
      count(*) filter (where status in ('queued','processing'))::int queued_count,
      count(*) filter (where status in ('sent','delivered','read','replied','converted'))::int sent_count,
      count(*) filter (where status in ('delivered','read','replied','converted'))::int delivered_count,
      count(*) filter (where status in ('read','replied','converted'))::int read_count,
      count(*) filter (where status in ('replied','converted'))::int reply_count,
      count(*) filter (where status in ('replied','converted') and coalesce((variables->>'reply_sentiment'),'positive')='positive')::int positive_reply_count,
      count(*) filter (where status='converted')::int conversion_count,
      count(*) filter (where status='failed')::int failed_count,
      count(*) filter (where status in ('sent','delivered','read','replied','converted','failed','cancelled','excluded'))::int terminal_count
    from public.ac_whatsapp_campaign_recipients where campaign_id=coalesce(new.campaign_id,old.campaign_id)
    group by campaign_id
  ) x where c.id=x.campaign_id;
  if TG_OP = 'DELETE' then
    return old;
  end if;
  return new;
end $$;


