--
-- Name: access_governance_bump_cache_epoch(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_bump_cache_epoch(p_scope text DEFAULT 'global'::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_epoch bigint;
begin
  insert into public.access_authorization_cache_epoch(cache_scope, epoch, updated_at, updated_by)
  values (coalesce(nullif(p_scope, ''), 'global'), 2, now(), p_actor_id)
  on conflict (cache_scope)
  do update set epoch = public.access_authorization_cache_epoch.epoch + 1,
                updated_at = now(),
                updated_by = excluded.updated_by
  returning epoch into v_epoch;
  return v_epoch;
end;
$$;


--
-- Name: access_governance_claim_inventory_items(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_claim_inventory_items(p_job_id uuid, p_worker_token text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, job_id uuid, relative_directory text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_job_id is null or coalesce(p_worker_token, '') = '' then
    raise exception 'Job id and worker token are required';
  end if;

  return query
  with candidates as (
    select work.id
    from public.access_scan_inventory_items work
    join public.access_scanner_jobs job on job.id = work.job_id
    where work.job_id = p_job_id
      and work.status = 'pending'
      and job.status = 'inventorying'
    order by work.relative_directory
    for update of work skip locked
    limit greatest(1, least(coalesce(p_limit, 20), 100))
  ), claimed as (
    update public.access_scan_inventory_items work
    set status = 'claimed',
        worker_token = p_worker_token,
        claimed_at = now(),
        attempt_count = work.attempt_count + 1,
        updated_at = now()
    from candidates
    where work.id = candidates.id
    returning work.*
  )
  select claimed.id, claimed.job_id, claimed.relative_directory
  from claimed
  order by claimed.relative_directory;
end;
$$;


--
-- Name: access_governance_claim_scan_work_items(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_claim_scan_work_items(p_job_id uuid, p_worker_token text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, job_id uuid, relative_path text, absolute_path text, file_kind text, extension text, size_bytes bigint, checksum text, modified_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_job_id is null or coalesce(p_worker_token, '') = '' then
    raise exception 'Job id and worker token are required';
  end if;

  return query
  with candidates as (
    select work.id
    from public.access_scan_work_items work
    join public.access_scanner_jobs job on job.id = work.job_id
    where work.job_id = p_job_id
      and work.status = 'pending'
      and job.status = 'running'
    order by work.sequence_number
    for update of work skip locked
    limit greatest(1, least(coalesce(p_limit, 20), 100))
  ), claimed as (
    update public.access_scan_work_items work
    set status = 'claimed',
        worker_token = p_worker_token,
        claimed_at = now(),
        attempt_count = work.attempt_count + 1,
        updated_at = now()
    from candidates
    where work.id = candidates.id
    returning work.*
  )
  select claimed.id, claimed.job_id, claimed.relative_path, claimed.absolute_path,
         claimed.file_kind, claimed.extension, claimed.size_bytes, claimed.checksum, claimed.modified_at
  from claimed
  order by claimed.sequence_number;
end;
$$;


--
-- Name: access_governance_command_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_command_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with latest_job as (
  select to_jsonb(job.*) as payload
  from public.access_scanner_jobs job
  order by job.created_at desc
  limit 1
), latest_scan as (
  select id from public.access_scanner_jobs where status = 'completed' order by completed_at desc nulls last limit 1
), node_counts as (
  select
    count(*) filter (where node_type = 'application') as applications,
    count(*) filter (where node_type = 'module') as modules,
    count(*) filter (where node_type = 'workspace') as workspaces,
    count(*) filter (where node_type = 'page') as pages,
    count(*) filter (where node_type = 'api_operation') as api_operations,
    count(*) filter (where node_type = 'server_action') as server_actions,
    count(*) filter (where node_type in ('authorization_guard','authentication_guard')) as protected_operations,
    count(*) filter (where node_type = 'permission') as permissions,
    count(*) filter (where node_type in ('membership_authority','database_function','database_table','entitlement')) as native_authorities,
    count(*) filter (where node_type = 'rls_policy') as rls_policies,
    count(*) filter (where node_type = 'unknown_authority' or authority_model = 'UNKNOWN') as unknown_authorities
  from public.access_topology_nodes
  where scan_id = (select id from latest_scan)
), finding_counts as (
  select count(*) as findings,
         count(*) filter (where severity = 'critical' and status = 'open') as critical_findings
  from public.access_reconciliation_findings
  where scan_id = (select id from latest_scan)
), plan_counts as (
  select count(*) filter (where status in ('draft','review_required','approved')) as open_plans
  from public.access_reconciliation_plans
), execution_counts as (
  select count(*) filter (where status in ('preflight','running','verifying','rolling_back')) as running_executions
  from public.access_execution_runs
), drift as (
  select coalesce(jsonb_object_agg(reconciliation_state, quantity), '{}'::jsonb) as payload
  from (select reconciliation_state, count(*) as quantity from public.access_reconciliation_findings where scan_id = (select id from latest_scan) group by reconciliation_state) grouped
), risks as (
  select coalesce(jsonb_object_agg(severity, quantity), '{}'::jsonb) as payload
  from (select severity, count(*) as quantity from public.access_reconciliation_findings where scan_id = (select id from latest_scan) group by severity) grouped
), models as (
  select coalesce(jsonb_object_agg(authority_model, quantity), '{}'::jsonb) as payload
  from (select coalesce(authority_model, 'UNCLASSIFIED') as authority_model, count(*) as quantity from public.access_topology_nodes where scan_id = (select id from latest_scan) group by coalesce(authority_model, 'UNCLASSIFIED')) grouped
), capability_payload as (
  select coalesce(jsonb_agg(jsonb_build_object('key', capability_key, 'label', capability_label, 'status', status, 'detail', detail) order by capability_key), '[]'::jsonb) as payload
  from public.access_scanner_capabilities
)
select jsonb_build_object(
  'generatedAt', now(),
  'scannerVersion', coalesce((select scanner_version from public.access_scanner_jobs order by created_at desc limit 1), '4.0.0'),
  'repositoryCommit', (select repository_commit from public.access_scanner_jobs order by created_at desc limit 1),
  'capabilityStatus', case when exists(select 1 from public.access_scanner_capabilities where status = 'blocked') then 'blocked' when exists(select 1 from public.access_scanner_capabilities where status = 'degraded') then 'degraded' else 'ready' end,
  'latestJob', coalesce((select payload from latest_job), 'null'::jsonb),
  'counts', jsonb_build_object(
    'applications', coalesce((select applications from node_counts),0),
    'modules', coalesce((select modules from node_counts),0),
    'workspaces', coalesce((select workspaces from node_counts),0),
    'pages', coalesce((select pages from node_counts),0),
    'apiOperations', coalesce((select api_operations from node_counts),0),
    'serverActions', coalesce((select server_actions from node_counts),0),
    'protectedOperations', coalesce((select protected_operations from node_counts),0),
    'unprotectedOperations', coalesce((select findings from finding_counts),0),
    'permissionNamespaces', coalesce((select permissions from node_counts),0),
    'nativeAuthorities', coalesce((select native_authorities from node_counts),0),
    'rlsPolicies', coalesce((select rls_policies from node_counts),0),
    'unknownAuthorities', coalesce((select unknown_authorities from node_counts),0),
    'findings', coalesce((select findings from finding_counts),0),
    'criticalFindings', coalesce((select critical_findings from finding_counts),0),
    'openPlans', coalesce((select open_plans from plan_counts),0),
    'runningExecutions', coalesce((select running_executions from execution_counts),0)
  ),
  'health', jsonb_build_object(
    'repositoryDiscovery', case when (select id from latest_scan) is null then 0 else 100 end,
    'authorizationIntelligence', greatest(0, 100 - least(100, coalesce((select unknown_authorities from node_counts),0))),
    'scopeIntegrity', greatest(0, 100 - least(100, coalesce((select count(*) from public.access_reconciliation_findings where scan_id = (select id from latest_scan) and reconciliation_state = 'SCOPE_MISMATCH'),0) * 10)),
    'reconciliationReadiness', greatest(0, 100 - least(100, coalesce((select findings from finding_counts),0))),
    'executionReadiness', case when exists(select 1 from public.access_authority_manifests where scan_id = (select id from latest_scan) and executable = true and validation_status = 'confirmed') then 100 else 25 end
  ),
  'riskDistribution', coalesce((select payload from risks), '{}'::jsonb),
  'driftDistribution', coalesce((select payload from drift), '{}'::jsonb),
  'authorityModels', coalesce((select payload from models), '{}'::jsonb),
  'capabilities', coalesce((select payload from capability_payload), '[]'::jsonb)
);
$$;


--
-- Name: access_governance_execute_plan(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_execute_plan(p_plan_id uuid, p_actor_id uuid, p_actor_email text, p_correlation_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_plan public.access_reconciliation_plans%rowtype;
  v_operation public.access_plan_operations%rowtype;
  v_manifest public.access_authority_manifests%rowtype;
  v_execution_id uuid := gen_random_uuid();
  v_result jsonb;
  v_verification_result jsonb;
  v_cache_epoch bigint;
  v_operation_count integer := 0;
  v_verification_count integer := 0;
  v_rollback_operations jsonb := '[]'::jsonb;
begin
  select * into v_plan from public.access_reconciliation_plans where id = p_plan_id for update;
  if not found then raise exception 'Reconciliation plan was not found'; end if;
  if v_plan.status <> 'approved' then raise exception 'Plan must be approved before execution'; end if;
  if not v_plan.execution_eligible then raise exception 'Plan is not execution eligible: %', array_to_string(v_plan.blocked_reasons, '; '); end if;
  if v_plan.expires_at is not null and v_plan.expires_at <= now() then raise exception 'Plan has expired'; end if;
  if coalesce(p_correlation_id, '') = '' then raise exception 'Correlation id is required'; end if;

  if exists (
    select 1 from public.access_plan_operations
    where plan_id = p_plan_id
      and (not execution_eligible or cardinality(blocked_reasons) > 0)
  ) then
    raise exception 'Plan contains blocked or ineligible operations';
  end if;

  insert into public.access_execution_runs(id, plan_id, status, correlation_id, actor_user_id, actor_email, started_at)
  values (v_execution_id, p_plan_id, 'preflight', p_correlation_id, p_actor_id, p_actor_email, now());
  update public.access_execution_runs set status = 'running', updated_at = now() where id = v_execution_id;
  update public.access_reconciliation_plans set status = 'executing', updated_at = now() where id = p_plan_id;

  begin
  for v_operation in
    select * from public.access_plan_operations where plan_id = p_plan_id order by sequence_number for update
  loop
    update public.access_plan_operations set status = 'running', started_at = now(), updated_at = now() where id = v_operation.id;
    insert into public.access_execution_checkpoints(execution_id, operation_id, checkpoint_key, sequence_number, status, detail, started_at)
    values (v_execution_id, v_operation.id, v_operation.operation_key, v_operation.sequence_number, 'running', v_operation.title, now());

    if v_operation.operation_type = 'WRITE_AUDIT_EVENT' then
      insert into public.access_command_events(event_type, actor_user_id, actor_email, correlation_id, scan_id, plan_id, execution_id, summary, payload)
      values ('authorization_plan_operation', p_actor_id, p_actor_email, p_correlation_id, v_plan.source_scan_id, p_plan_id, v_execution_id, v_operation.title, v_operation.mutation_arguments);
      v_result := jsonb_build_object('ok', true, 'auditEvent', true);

    elsif v_operation.operation_type = 'INVALIDATE_AUTHORIZATION_CACHE' then
      v_cache_epoch := public.access_governance_bump_cache_epoch(coalesce(v_operation.target->>'moduleKey', 'global'), p_actor_id);
      v_result := jsonb_build_object('ok', true, 'cacheEpoch', v_cache_epoch);

    else
      select * into v_manifest
      from public.access_authority_manifests
      where manifest_key = v_operation.authority_manifest_key
        and validation_status = 'confirmed'
        and executable = true
      order by updated_at desc
      limit 1;
      if not found then raise exception 'Confirmed executable authority manifest is missing for operation %', v_operation.operation_key; end if;

      if v_operation.operation_type = 'VERIFY_EFFECTIVE_ACCESS' then
        if coalesce(v_operation.verification_rpc, '') = '' then
          raise exception 'Verification operation % has no verification RPC', v_operation.operation_key;
        end if;
        if v_operation.verification_rpc !~ '^[a-z_][a-z0-9_]{0,62}$' then
          raise exception 'Verification operation % contains an unsafe RPC identifier', v_operation.operation_key;
        end if;
        if v_manifest.mutation_authority->>'verificationRpc' <> v_operation.verification_rpc then
          raise exception 'Verification RPC % is not registered by the confirmed manifest', v_operation.verification_rpc;
        end if;
        execute format('select public.%I($1::jsonb)', v_operation.verification_rpc)
        using v_operation.verification_arguments
        into v_result;
        insert into public.access_verification_results(
          execution_id, operation_id, verification_type, status,
          expected_state, observed_state, evidence, error
        ) values (
          v_execution_id, v_operation.id, 'effective_access',
          case when coalesce((v_result->>'ok')::boolean, false) then 'passed' else 'failed' end,
          v_operation.proposed_state, coalesce(v_result, '{}'::jsonb),
          jsonb_build_object('rpc', v_operation.verification_rpc, 'evidenceKeys', to_jsonb(v_operation.evidence_keys)),
          case when coalesce((v_result->>'ok')::boolean, false) then null else 'Verification RPC returned an unsuccessful result' end
        );
        if coalesce((v_result->>'ok')::boolean, false) is not true then
          raise exception 'Verification RPC % did not return a verified ok result', v_operation.verification_rpc;
        end if;
        v_verification_count := v_verification_count + 1;

      else
        if coalesce(v_operation.mutation_rpc, '') = '' then
          raise exception 'Operation % has no mutation RPC', v_operation.operation_key;
        end if;
        if v_operation.mutation_rpc !~ '^[a-z_][a-z0-9_]{0,62}$' then
          raise exception 'Operation % contains an unsafe RPC identifier', v_operation.operation_key;
        end if;
        if v_manifest.mutation_authority->>'rpc' <> v_operation.mutation_rpc then
          raise exception 'Mutation RPC % is not registered by the confirmed manifest', v_operation.mutation_rpc;
        end if;
        execute format('select public.%I($1::jsonb)', v_operation.mutation_rpc)
        using v_operation.mutation_arguments
        into v_result;
        if coalesce((v_result->>'ok')::boolean, false) is not true then
          raise exception 'Mutation RPC % did not return a verified ok result', v_operation.mutation_rpc;
        end if;

        if coalesce(v_operation.verification_rpc, '') <> '' then
          if v_operation.verification_rpc !~ '^[a-z_][a-z0-9_]{0,62}$' then
            raise exception 'Operation % contains an unsafe verification RPC identifier', v_operation.operation_key;
          end if;
          if v_manifest.mutation_authority->>'verificationRpc' <> v_operation.verification_rpc then
            raise exception 'Verification RPC % is not registered by the confirmed manifest', v_operation.verification_rpc;
          end if;
          update public.access_execution_runs set status = 'verifying', updated_at = now() where id = v_execution_id;
          execute format('select public.%I($1::jsonb)', v_operation.verification_rpc)
          using v_operation.verification_arguments
          into v_verification_result;
          insert into public.access_verification_results(
            execution_id, operation_id, verification_type, status,
            expected_state, observed_state, evidence, error
          ) values (
            v_execution_id, v_operation.id, 'post_mutation',
            case when coalesce((v_verification_result->>'ok')::boolean, false) then 'passed' else 'failed' end,
            v_operation.proposed_state, coalesce(v_verification_result, '{}'::jsonb),
            jsonb_build_object('rpc', v_operation.verification_rpc, 'evidenceKeys', to_jsonb(v_operation.evidence_keys)),
            case when coalesce((v_verification_result->>'ok')::boolean, false) then null else 'Post-mutation verification returned an unsuccessful result' end
          );
          if coalesce((v_verification_result->>'ok')::boolean, false) is not true then
            raise exception 'Post-mutation verification RPC % did not return a verified ok result', v_operation.verification_rpc;
          end if;
          v_verification_count := v_verification_count + 1;
          update public.access_execution_runs set status = 'running', updated_at = now() where id = v_execution_id;
        end if;

        if coalesce(v_operation.rollback_rpc, '') <> '' then
          if v_operation.rollback_rpc !~ '^[a-z_][a-z0-9_]{0,62}$' then
            raise exception 'Operation % contains an unsafe rollback RPC identifier', v_operation.operation_key;
          end if;
          if v_manifest.mutation_authority->>'rollbackRpc' <> v_operation.rollback_rpc then
            raise exception 'Rollback RPC % is not registered by the confirmed manifest', v_operation.rollback_rpc;
          end if;
          v_rollback_operations := jsonb_insert(
            v_rollback_operations,
            '{0}',
            jsonb_build_object(
              'operationId', v_operation.id,
              'operationKey', v_operation.operation_key,
              'sequence', v_operation.sequence_number,
              'manifestKey', v_operation.authority_manifest_key,
              'rpc', v_operation.rollback_rpc,
              'arguments', v_operation.rollback_arguments
            ),
            true
          );
        end if;
      end if;
    end if;

    update public.access_plan_operations set status = 'completed', result = v_result, completed_at = now(), updated_at = now() where id = v_operation.id;
    update public.access_execution_checkpoints set status = 'passed', payload = coalesce(v_result, '{}'::jsonb), completed_at = now() where execution_id = v_execution_id and checkpoint_key = v_operation.operation_key;
    v_operation_count := v_operation_count + 1;
  end loop;

  insert into public.access_rollback_packages(
    execution_id, status, before_topology, after_topology,
    rollback_operations, evidence, expires_at
  ) values (
    v_execution_id,
    case when jsonb_array_length(v_rollback_operations) > 0 then 'available' else 'not_available' end,
    jsonb_build_object('planId', p_plan_id, 'findingKeys', to_jsonb(v_plan.finding_keys)),
    v_plan.simulation,
    v_rollback_operations,
    jsonb_build_object('scanId', v_plan.source_scan_id, 'correlationId', p_correlation_id),
    now() + interval '7 days'
  );

  update public.access_execution_runs set status = 'completed', completed_at = now(), result = jsonb_build_object('operations', v_operation_count, 'verifications', v_verification_count), updated_at = now() where id = v_execution_id;
  update public.access_reconciliation_plans set status = 'completed', updated_at = now() where id = p_plan_id;
  insert into public.access_command_events(event_type, actor_user_id, actor_email, correlation_id, scan_id, plan_id, execution_id, summary, payload)
  values ('authorization_plan_completed', p_actor_id, p_actor_email, p_correlation_id, v_plan.source_scan_id, p_plan_id, v_execution_id, 'Authorization reconciliation plan completed transactionally and passed verification.', jsonb_build_object('operations', v_operation_count, 'verifications', v_verification_count));

  return jsonb_build_object('ok', true, 'executionId', v_execution_id, 'operations', v_operation_count, 'verifications', v_verification_count);
  exception
    when others then
      update public.access_execution_runs
      set status = 'failed', failure_stage = coalesce(v_operation.operation_key, 'transaction'), error = sqlerrm, completed_at = now(), updated_at = now()
      where id = v_execution_id;
      update public.access_reconciliation_plans set status = 'failed', updated_at = now() where id = p_plan_id;
      insert into public.access_command_events(event_type, actor_user_id, actor_email, correlation_id, scan_id, plan_id, execution_id, summary, payload)
      values ('authorization_plan_failed', p_actor_id, p_actor_email, p_correlation_id, v_plan.source_scan_id, p_plan_id, v_execution_id, 'Authorization reconciliation transaction failed and was rolled back.', jsonb_build_object('error', sqlerrm, 'operationKey', v_operation.operation_key));
      return jsonb_build_object('ok', false, 'executionId', v_execution_id, 'error', sqlerrm, 'failureStage', coalesce(v_operation.operation_key, 'transaction'));
  end;
end;
$_$;


--
-- Name: access_governance_execute_rollback(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_execute_rollback(p_package_id uuid, p_actor_id uuid, p_actor_email text, p_correlation_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_package public.access_rollback_packages%rowtype;
  v_execution public.access_execution_runs%rowtype;
  v_item jsonb;
  v_result jsonb;
  v_count integer := 0;
begin
  if coalesce(p_correlation_id, '') = '' then raise exception 'Correlation id is required'; end if;
  select * into v_package from public.access_rollback_packages where id = p_package_id for update;
  if not found then raise exception 'Rollback package was not found'; end if;
  if v_package.status <> 'available' then raise exception 'Rollback package is not available'; end if;
  if v_package.expires_at is not null and v_package.expires_at <= now() then
    update public.access_rollback_packages set status = 'expired', updated_at = now() where id = p_package_id;
    raise exception 'Rollback package has expired';
  end if;
  select * into v_execution from public.access_execution_runs where id = v_package.execution_id for update;
  if not found or v_execution.status <> 'completed' then raise exception 'Only a completed execution can be rolled back'; end if;

  update public.access_rollback_packages set status = 'running', updated_at = now() where id = p_package_id;
  update public.access_execution_runs set status = 'rolling_back', updated_at = now() where id = v_execution.id;

  begin
  for v_item in select value from jsonb_array_elements(v_package.rollback_operations)
  loop
    if coalesce(v_item->>'rpc', '') !~ '^[a-z_][a-z0-9_]{0,62}$' then raise exception 'Rollback package contains an unsafe RPC identifier'; end if;
    if not exists (
      select 1 from public.access_authority_manifests manifest
      where manifest.manifest_key = v_item->>'manifestKey'
        and manifest.validation_status = 'confirmed'
        and manifest.executable = true
        and manifest.mutation_authority->>'rollbackRpc' = v_item->>'rpc'
    ) then raise exception 'Rollback RPC % is not registered by a confirmed manifest', v_item->>'rpc'; end if;
    execute format('select public.%I($1::jsonb)', v_item->>'rpc') using coalesce(v_item->'arguments', '{}'::jsonb) into v_result;
    if coalesce((v_result->>'ok')::boolean, false) is not true then raise exception 'Rollback RPC % did not return a verified ok result', v_item->>'rpc'; end if;
    update public.access_plan_operations set status = 'rolled_back', updated_at = now() where id = nullif(v_item->>'operationId', '')::uuid;
    v_count := v_count + 1;
  end loop;

  update public.access_rollback_packages set status = 'completed', updated_at = now() where id = p_package_id;
  update public.access_execution_runs set status = 'rolled_back', completed_at = now(), updated_at = now() where id = v_execution.id;
  update public.access_reconciliation_plans set status = 'rolled_back', updated_at = now() where id = v_execution.plan_id;
  insert into public.access_command_events(event_type, actor_user_id, actor_email, correlation_id, plan_id, execution_id, summary, payload)
  values ('authorization_rollback_completed', p_actor_id, p_actor_email, p_correlation_id, v_execution.plan_id, v_execution.id, 'Authorization rollback package completed transactionally.', jsonb_build_object('rollbackPackageId', p_package_id, 'operations', v_count));
  return jsonb_build_object('ok', true, 'rollbackPackageId', p_package_id, 'operations', v_count);
  exception
    when others then
      update public.access_rollback_packages set status = 'failed', updated_at = now() where id = p_package_id;
      update public.access_execution_runs set status = 'failed', failure_stage = 'rollback', error = sqlerrm, updated_at = now() where id = v_execution.id;
      insert into public.access_command_events(event_type, actor_user_id, actor_email, correlation_id, plan_id, execution_id, summary, payload)
      values ('authorization_rollback_failed', p_actor_id, p_actor_email, p_correlation_id, v_execution.plan_id, v_execution.id, 'Authorization rollback failed. Transactional rollback operations were reverted.', jsonb_build_object('error', sqlerrm, 'rollbackPackageId', p_package_id));
      return jsonb_build_object('ok', false, 'rollbackPackageId', p_package_id, 'error', sqlerrm);
  end;
end;
$_$;


--
-- Name: access_governance_introspect_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_governance_introspect_authority() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
with public_tables as (
  select n.nspname as schema_name,
         c.relname as table_name,
         c.oid as table_oid,
         c.relrowsecurity as rls_enabled
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relkind in ('r','p')
), table_columns as (
  select t.table_oid,
         jsonb_agg(jsonb_build_object(
           'name', a.attname,
           'dataType', format_type(a.atttypid, a.atttypmod),
           'nullable', not a.attnotnull,
           'defaultValue', pg_get_expr(d.adbin, d.adrelid)
         ) order by a.attnum) as columns
  from public_tables t
  join pg_attribute a on a.attrelid = t.table_oid and a.attnum > 0 and not a.attisdropped
  left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
  group by t.table_oid
), primary_keys as (
  select con.conrelid as table_oid,
         jsonb_agg(att.attname order by key_position.ordinality) as columns
  from pg_constraint con
  cross join lateral unnest(con.conkey) with ordinality as key_position(attnum, ordinality)
  join pg_attribute att on att.attrelid = con.conrelid and att.attnum = key_position.attnum
  where con.contype = 'p'
  group by con.conrelid
), unique_constraints as (
  select grouped.table_oid, jsonb_agg(grouped.columns) as constraints
  from (
    select con.conrelid as table_oid,
           jsonb_agg(att.attname order by key_position.ordinality) as columns
    from pg_constraint con
    cross join lateral unnest(con.conkey) with ordinality as key_position(attnum, ordinality)
    join pg_attribute att on att.attrelid = con.conrelid and att.attnum = key_position.attnum
    where con.contype = 'u'
    group by con.oid, con.conrelid
  ) grouped
  group by grouped.table_oid
), foreign_keys as (
  select con.conrelid as table_oid,
         jsonb_agg(jsonb_build_object(
           'column', local_att.attname,
           'foreignSchema', foreign_ns.nspname,
           'foreignTable', foreign_table.relname,
           'foreignColumn', foreign_att.attname
         )) as foreign_keys
  from pg_constraint con
  join pg_class foreign_table on foreign_table.oid = con.confrelid
  join pg_namespace foreign_ns on foreign_ns.oid = foreign_table.relnamespace
  cross join lateral unnest(con.conkey, con.confkey) as keys(local_attnum, foreign_attnum)
  join pg_attribute local_att on local_att.attrelid = con.conrelid and local_att.attnum = keys.local_attnum
  join pg_attribute foreign_att on foreign_att.attrelid = con.confrelid and foreign_att.attnum = keys.foreign_attnum
  where con.contype = 'f'
  group by con.conrelid
), tables_payload as (
  select jsonb_agg(jsonb_build_object(
    'schema', t.schema_name,
    'name', t.table_name,
    'rlsEnabled', t.rls_enabled,
    'columns', coalesce(tc.columns, '[]'::jsonb),
    'primaryKey', coalesce(pk.columns, '[]'::jsonb),
    'uniqueConstraints', coalesce(uc.constraints, '[]'::jsonb),
    'foreignKeys', coalesce(fk.foreign_keys, '[]'::jsonb)
  ) order by t.table_name) as tables
  from public_tables t
  left join table_columns tc on tc.table_oid = t.table_oid
  left join primary_keys pk on pk.table_oid = t.table_oid
  left join unique_constraints uc on uc.table_oid = t.table_oid
  left join foreign_keys fk on fk.table_oid = t.table_oid
), policies_payload as (
  select jsonb_agg(jsonb_build_object(
    'schema', schemaname,
    'table', tablename,
    'name', policyname,
    'command', cmd,
    'roles', roles,
    'usingExpression', qual,
    'checkExpression', with_check
  ) order by tablename, policyname) as policies
  from pg_policies
  where schemaname = 'public'
), functions_payload as (
  select jsonb_agg(jsonb_build_object(
    'schema', n.nspname,
    'name', p.proname,
    'identityArguments', pg_get_function_identity_arguments(p.oid),
    'securityDefiner', p.prosecdef,
    'volatility', p.provolatile
  ) order by p.proname) as functions
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
)
select jsonb_build_object(
  'generatedAt', now(),
  'tables', coalesce((select tables from tables_payload), '[]'::jsonb),
  'policies', coalesce((select policies from policies_payload), '[]'::jsonb),
  'functions', coalesce((select functions from functions_payload), '[]'::jsonb)
);
$$;


--
-- Name: ai_ops_dependency_snapshot(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_ops_dependency_snapshot(p_entity_type text, p_entity_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_id uuid;
  v_dossier_id uuid;
  v_result jsonb;
begin
  begin v_id := p_entity_id::uuid; exception when others then raise exception 'INVALID_ENTITY_ID'; end;
  if p_entity_type = 'credential' then
    select dossier_id into v_dossier_id from public.ai_provider_credentials where id=v_id;
    if v_dossier_id is null then raise exception 'CREDENTIAL_NOT_FOUND'; end if;
    select jsonb_build_object(
      'entityType','credential',
      'credentialStatus',(select status from public.ai_provider_credentials where id=v_id),
      'dossierId',v_dossier_id,
      'activeCredentialsInDossier',(select count(*) from public.ai_provider_credentials where dossier_id=v_dossier_id and status='active'),
      'enabledAssignments',(select count(*) from public.ai_provider_module_assignments where dossier_id=v_dossier_id and enabled),
      'enabledRoutes',(select count(*) from public.ai_provider_routing_rules r join public.ai_provider_module_assignments a on a.id=r.primary_assignment_id where a.dossier_id=v_dossier_id and r.enabled),
      'usageRows',(select count(*) from public.ai_provider_usage_ledger where credential_id=v_id)
    ) into v_result;
  elsif p_entity_type = 'dossier' then
    if not exists(select 1 from public.ai_provider_dossiers where id=v_id) then raise exception 'DOSSIER_NOT_FOUND'; end if;
    select jsonb_build_object(
      'entityType','dossier',
      'dossierStatus',(select status from public.ai_provider_dossiers where id=v_id),
      'enabled',(select is_enabled from public.ai_provider_dossiers where id=v_id),
      'capacityPools',(select count(*) from public.ai_provider_capacity_pools where dossier_id=v_id),
      'credentials',(select count(*) from public.ai_provider_credentials where dossier_id=v_id),
      'activeCredentials',(select count(*) from public.ai_provider_credentials where dossier_id=v_id and status='active'),
      'models',(select count(*) from public.ai_provider_models where dossier_id=v_id),
      'enabledAssignments',(select count(*) from public.ai_provider_module_assignments where dossier_id=v_id and enabled),
      'enabledRoutes',(select count(*) from public.ai_provider_routing_rules r join public.ai_provider_module_assignments a on a.id=r.primary_assignment_id where a.dossier_id=v_id and r.enabled),
      'usageRows',(select count(*) from public.ai_provider_usage_ledger where dossier_id=v_id)
    ) into v_result;
  else
    raise exception 'UNSUPPORTED_DESTRUCTION_ENTITY';
  end if;
  return coalesce(v_result,'{}'::jsonb);
end;
$$;


--
-- Name: ai_ops_execute_destruction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_ops_execute_destruction(p_request_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_request public.ai_ops_destruction_requests%rowtype;
  v_entity_id uuid;
  v_secret_id uuid;
  v_fingerprint text;
  v_dependency jsonb;
  v_credential_status text;
  v_dossier_status text;
  v_dossier_enabled boolean;
  v_enabled_assignments integer;
  v_active_credentials integer;
begin
  select * into v_request from public.ai_ops_destruction_requests where id=p_request_id for update;
  if v_request.id is null then raise exception 'DESTRUCTION_REQUEST_NOT_FOUND'; end if;
  if v_request.status <> 'approved' then raise exception 'DESTRUCTION_REQUEST_NOT_APPROVED'; end if;
  begin v_entity_id := v_request.entity_id::uuid; exception when others then raise exception 'INVALID_ENTITY_ID'; end;
  v_dependency := public.ai_ops_dependency_snapshot(v_request.entity_type,v_request.entity_id);

  if v_request.entity_type='credential' then
    select status,vault_secret_id,fingerprint into v_credential_status,v_secret_id,v_fingerprint
    from public.ai_provider_credentials where id=v_entity_id for update;
    if v_credential_status is null then raise exception 'CREDENTIAL_NOT_FOUND'; end if;
    if v_credential_status='active' then raise exception 'ACTIVE_CREDENTIAL_CANNOT_BE_DESTROYED'; end if;
    delete from public.ai_provider_credentials where id=v_entity_id;
    delete from vault.secrets where id=v_secret_id;
    insert into public.ai_ops_entity_tombstones(entity_type,entity_code,entity_id,fingerprint,destroyed_by,destruction_reason,dependency_snapshot,destruction_request_id)
    values('credential',v_request.entity_code,v_request.entity_id,v_fingerprint,p_actor_id,v_request.reason,v_dependency,v_request.id);
  elsif v_request.entity_type='dossier' then
    select status,is_enabled into v_dossier_status,v_dossier_enabled from public.ai_provider_dossiers where id=v_entity_id for update;
    if v_dossier_status is null then raise exception 'DOSSIER_NOT_FOUND'; end if;
    select count(*) into v_enabled_assignments from public.ai_provider_module_assignments where dossier_id=v_entity_id and enabled;
    select count(*) into v_active_credentials from public.ai_provider_credentials where dossier_id=v_entity_id and status='active';
    if v_dossier_status<>'archived' or v_dossier_enabled then raise exception 'DOSSIER_MUST_BE_ARCHIVED_AND_DISABLED'; end if;
    if v_enabled_assignments>0 or v_active_credentials>0 then raise exception 'DOSSIER_HAS_ACTIVE_DEPENDENCIES'; end if;
    delete from vault.secrets where id in (select vault_secret_id from public.ai_provider_credentials where dossier_id=v_entity_id);
    insert into public.ai_ops_entity_tombstones(entity_type,entity_code,entity_id,destroyed_by,destruction_reason,dependency_snapshot,destruction_request_id)
    values('dossier',v_request.entity_code,v_request.entity_id,p_actor_id,v_request.reason,v_dependency,v_request.id);
    delete from public.ai_provider_dossiers where id=v_entity_id;
  else
    raise exception 'UNSUPPORTED_DESTRUCTION_ENTITY';
  end if;

  update public.ai_ops_destruction_requests set status='executed',executed_by=p_actor_id,executed_at=now(),execution_result=jsonb_build_object('destroyed',true,'entityType',v_request.entity_type,'entityCode',v_request.entity_code),updated_at=now() where id=p_request_id;
  insert into public.ai_provider_audit(action_key,entity_type,entity_id,actor_id,actor_name,payload)
  values('permanent_destruction_executed',v_request.entity_type,v_request.entity_id,p_actor_id,p_actor_id,jsonb_build_object('requestId',p_request_id,'entityCode',v_request.entity_code,'dependencySnapshot',v_dependency));
  return jsonb_build_object('destroyed',true,'entityType',v_request.entity_type,'entityCode',v_request.entity_code,'requestId',p_request_id);
end;
$$;


--
-- Name: FUNCTION ai_ops_execute_destruction(p_request_id uuid, p_actor_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ai_ops_execute_destruction(p_request_id uuid, p_actor_id text) IS 'Irreversibly deletes approved non-active credentials or fully archived provider dossiers and preserves metadata-only tombstone evidence.';


--
-- Name: ai_provider_acquire_runtime_budget(text, text, text, integer, bigint, bigint, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_acquire_runtime_budget(p_module_key text, p_capability text, p_requested_model text, p_estimated_requests integer DEFAULT 1, p_estimated_input_tokens bigint DEFAULT 0, p_estimated_output_tokens bigint DEFAULT 0, p_grounded boolean DEFAULT false, p_actor_id text DEFAULT NULL::text, p_mission_id text DEFAULT NULL::text, p_command_code text DEFAULT NULL::text) RETURNS TABLE(reservation_id uuid, lease_id uuid, assignment_id uuid, assignment_mode text, dossier_id uuid, provider_type text, capacity_pool_id uuid, credential_id uuid, model_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_route record;
  v_policy record;
  v_reservation uuid;
  v_lease uuid;
  v_global_mode text;
  v_module_mode text;
  v_provider_rpm integer;
  v_provider_tpm bigint;
  v_provider_rpd integer;
  v_provider_grounded_rpd integer;
  v_pool_requests_minute bigint := 0;
  v_pool_requests_day bigint := 0;
  v_pool_input_minute bigint := 0;
  v_pool_grounded_day bigint := 0;
  v_used_minute bigint := 0;
  v_used_hour bigint := 0;
  v_used_day bigint := 0;
  v_used_month bigint := 0;
  v_grounded_day bigint := 0;
  v_input_day bigint := 0;
  v_output_day bigint := 0;
  v_reserved_minute bigint := 0;
  v_reserved_hour bigint := 0;
  v_reserved_day bigint := 0;
  v_reserved_month bigint := 0;
  v_reserved_grounded_day bigint := 0;
  v_reserved_input_day bigint := 0;
  v_reserved_output_day bigint := 0;
  v_active_leases bigint := 0;
  v_day_start timestamptz;
  v_month_start timestamptz;
  v_effective_day_limit bigint;
  v_soft_boundary numeric;
  v_scope_title text;
begin
  p_estimated_requests := greatest(1,coalesce(p_estimated_requests,1));
  p_estimated_input_tokens := greatest(0,coalesce(p_estimated_input_tokens,0));
  p_estimated_output_tokens := greatest(0,coalesce(p_estimated_output_tokens,0));

  select mode into v_global_mode from public.ai_provider_emergency_state where scope_key='*';
  select mode into v_module_mode from public.ai_provider_emergency_state where scope_key=p_module_key;
  if coalesce(v_global_mode,'normal') in ('paused','draining')
     or coalesce(v_module_mode,'normal') in ('paused','draining') then
    raise exception 'AI_PROVIDER_GLOBAL_PAUSED';
  end if;
  if (coalesce(v_global_mode,'normal')='manual_only' or coalesce(v_module_mode,'normal')='manual_only') and p_actor_id is null then
    raise exception 'AI_PROVIDER_MANUAL_ONLY';
  end if;
  if p_grounded and (coalesce(v_global_mode,'normal')='grounding_disabled' or coalesce(v_module_mode,'normal')='grounding_disabled') then
    raise exception 'AI_PROVIDER_GROUNDING_DISABLED';
  end if;

  select * into v_route
  from public.ai_provider_resolve_runtime_provider(p_module_key,p_capability,p_requested_model)
  limit 1;
  if not found then raise exception 'AI_PROVIDER_ROUTE_NOT_FOUND'; end if;
  if (coalesce(v_global_mode,'normal')='reserve_only' or coalesce(v_module_mode,'normal')='reserve_only')
     and v_route.assignment_mode <> 'emergency_reserve' then
    raise exception 'AI_PROVIDER_RESERVE_ONLY';
  end if;
  if not exists(
    select 1 from public.ai_provider_models m
    where m.dossier_id=v_route.dossier_id and m.model_code=v_route.model_code and m.enabled=true
      and (m.capability=p_capability or m.capability='general')
  ) then
    raise exception 'AI_PROVIDER_MODEL_NOT_ALLOWED:%',v_route.model_code;
  end if;
  if p_grounded and not exists(
    select 1 from public.ai_provider_models m
    where m.dossier_id=v_route.dossier_id and m.model_code=v_route.model_code and m.enabled=true
      and m.grounding_allowed=true
      and (m.capability=p_capability or m.capability='general')
  ) then
    raise exception 'AI_PROVIDER_GROUNDING_NOT_ALLOWED:%',v_route.model_code;
  end if;

  -- Lock in a consistent hierarchy so concurrent Vercel instances cannot spend
  -- the same global, module or provider-pool capacity.
  perform pg_advisory_xact_lock(hashtextextended('ai_provider:global',0));
  perform pg_advisory_xact_lock(hashtextextended('ai_provider:module:'||p_module_key,0));
  perform pg_advisory_xact_lock(hashtextextended('ai_provider:pool:'||v_route.capacity_pool_id::text,0));

  update public.ai_provider_budget_reservations set status='expired', updated_at=now()
  where status in ('reserved','running') and expires_at<=now();
  update public.ai_provider_runtime_leases set status='expired', released_at=now()
  where status='active' and expires_at<=now();
  update public.ai_provider_cooldowns set status='expired'
  where status='active' and ends_at<=now();

  select cp.provider_rpm,cp.provider_tpm,cp.provider_rpd,cp.provider_grounded_rpd
    into v_provider_rpm,v_provider_tpm,v_provider_rpd,v_provider_grounded_rpd
  from public.ai_provider_capacity_pools cp
  where cp.id=v_route.capacity_pool_id;

  -- Provider ceilings are informational values entered from the provider portal,
  -- but once configured SANILA never intentionally exceeds them.
  select
    coalesce(sum(u.request_count) filter(where u.occurred_at>=now()-interval '1 minute'),0),
    coalesce(sum(u.request_count) filter(where u.occurred_at>=date_trunc('day',now())),0),
    coalesce(sum(u.input_tokens) filter(where u.occurred_at>=now()-interval '1 minute'),0),
    coalesce(sum(u.grounded_request_count) filter(where u.occurred_at>=date_trunc('day',now())),0)
  into v_pool_requests_minute,v_pool_requests_day,v_pool_input_minute,v_pool_grounded_day
  from public.ai_provider_usage_ledger u
  where u.capacity_pool_id=v_route.capacity_pool_id;

  select
    v_pool_requests_minute + coalesce(sum(r.reserved_requests) filter(where r.created_at>=now()-interval '1 minute'),0),
    v_pool_requests_day + coalesce(sum(r.reserved_requests) filter(where r.created_at>=date_trunc('day',now())),0),
    v_pool_input_minute + coalesce(sum(r.reserved_input_tokens) filter(where r.created_at>=now()-interval '1 minute'),0),
    v_pool_grounded_day + coalesce(sum(case when r.grounded then r.reserved_requests else 0 end) filter(where r.created_at>=date_trunc('day',now())),0)
  into v_pool_requests_minute,v_pool_requests_day,v_pool_input_minute,v_pool_grounded_day
  from public.ai_provider_budget_reservations r
  where r.capacity_pool_id=v_route.capacity_pool_id and r.status in ('reserved','running');

  if v_provider_rpm is not null and v_provider_rpm>0 and v_pool_requests_minute+p_estimated_requests>v_provider_rpm then
    raise exception 'AI_PROVIDER_CEILING_EXHAUSTED:RPM';
  end if;
  if v_provider_tpm is not null and v_provider_tpm>0 and v_pool_input_minute+p_estimated_input_tokens>v_provider_tpm then
    raise exception 'AI_PROVIDER_CEILING_EXHAUSTED:TPM';
  end if;
  if v_provider_rpd is not null and v_provider_rpd>0 and v_pool_requests_day+p_estimated_requests>v_provider_rpd then
    raise exception 'AI_PROVIDER_CEILING_EXHAUSTED:RPD';
  end if;
  if p_grounded and v_provider_grounded_rpd is not null and v_provider_grounded_rpd>0
     and v_pool_grounded_day+p_estimated_requests>v_provider_grounded_rpd then
    raise exception 'AI_PROVIDER_CEILING_EXHAUSTED:GROUNDED_RPD';
  end if;

  for v_policy in
    select q.* from public.ai_provider_quota_policies q
    where q.enabled=true and (
      (q.scope_type='global' and q.scope_key='*')
      or (q.scope_type='module' and q.scope_key=p_module_key)
      or (q.scope_type='dossier' and q.scope_key=v_route.dossier_id::text)
      or (q.scope_type='capacity_pool' and q.scope_key=v_route.capacity_pool_id::text)
      or (q.scope_type='model' and q.scope_key=v_route.model_code)
      or (q.scope_type='command' and p_command_code is not null and q.scope_key=p_command_code)
      or (q.scope_type='user' and p_actor_id is not null and q.scope_key=p_actor_id)
    )
    order by case q.scope_type when 'global' then 1 when 'module' then 2 when 'dossier' then 3 when 'capacity_pool' then 4 when 'model' then 5 when 'command' then 6 else 7 end
  loop
    v_day_start := date_trunc('day',now() at time zone coalesce(nullif(v_policy.reset_timezone,''),'UTC')) at time zone coalesce(nullif(v_policy.reset_timezone,''),'UTC');
    v_month_start := date_trunc('month',now() at time zone coalesce(nullif(v_policy.reset_timezone,''),'UTC')) at time zone coalesce(nullif(v_policy.reset_timezone,''),'UTC');

    select
      coalesce(sum(u.request_count) filter(where u.occurred_at>=now()-interval '1 minute'),0),
      coalesce(sum(u.request_count) filter(where u.occurred_at>=date_trunc('hour',now())),0),
      coalesce(sum(u.request_count) filter(where u.occurred_at>=v_day_start),0),
      coalesce(sum(u.request_count) filter(where u.occurred_at>=v_month_start),0),
      coalesce(sum(u.grounded_request_count) filter(where u.occurred_at>=v_day_start),0),
      coalesce(sum(u.input_tokens) filter(where u.occurred_at>=v_day_start),0),
      coalesce(sum(u.output_tokens) filter(where u.occurred_at>=v_day_start),0)
    into v_used_minute,v_used_hour,v_used_day,v_used_month,v_grounded_day,v_input_day,v_output_day
    from public.ai_provider_usage_ledger u
    where case v_policy.scope_type
      when 'global' then true
      when 'module' then u.module_key=v_policy.scope_key
      when 'dossier' then u.dossier_id::text=v_policy.scope_key
      when 'capacity_pool' then u.capacity_pool_id::text=v_policy.scope_key
      when 'model' then u.model_code=v_policy.scope_key
      when 'command' then u.command_code=v_policy.scope_key
      when 'user' then u.actor_id=v_policy.scope_key
      else false end;

    select
      coalesce(sum(r.reserved_requests) filter(where r.created_at>=now()-interval '1 minute'),0),
      coalesce(sum(r.reserved_requests) filter(where r.created_at>=date_trunc('hour',now())),0),
      coalesce(sum(r.reserved_requests) filter(where r.created_at>=v_day_start),0),
      coalesce(sum(r.reserved_requests) filter(where r.created_at>=v_month_start),0),
      coalesce(sum(case when r.grounded then r.reserved_requests else 0 end) filter(where r.created_at>=v_day_start),0),
      coalesce(sum(r.reserved_input_tokens) filter(where r.created_at>=v_day_start),0),
      coalesce(sum(r.reserved_output_tokens) filter(where r.created_at>=v_day_start),0)
    into v_reserved_minute,v_reserved_hour,v_reserved_day,v_reserved_month,v_reserved_grounded_day,v_reserved_input_day,v_reserved_output_day
    from public.ai_provider_budget_reservations r
    where r.status in ('reserved','running')
      and case v_policy.scope_type
        when 'global' then true
        when 'module' then r.module_key=v_policy.scope_key
        when 'dossier' then r.dossier_id::text=v_policy.scope_key
        when 'capacity_pool' then r.capacity_pool_id::text=v_policy.scope_key
        when 'model' then r.model_code=v_policy.scope_key
        when 'command' then r.command_code=v_policy.scope_key
        when 'user' then r.actor_id=v_policy.scope_key
        else false end;

    v_used_minute := v_used_minute+v_reserved_minute;
    v_used_hour := v_used_hour+v_reserved_hour;
    v_used_day := v_used_day+v_reserved_day;
    v_used_month := v_used_month+v_reserved_month;
    v_grounded_day := v_grounded_day+v_reserved_grounded_day;
    v_input_day := v_input_day+v_reserved_input_day;
    v_output_day := v_output_day+v_reserved_output_day;

    select count(*) into v_active_leases
    from public.ai_provider_runtime_leases l
    join public.ai_provider_budget_reservations r on r.id=l.reservation_id
    where l.status='active' and l.expires_at>now()
      and case v_policy.scope_type
        when 'global' then true
        when 'module' then r.module_key=v_policy.scope_key
        when 'dossier' then r.dossier_id::text=v_policy.scope_key
        when 'capacity_pool' then r.capacity_pool_id::text=v_policy.scope_key
        when 'model' then r.model_code=v_policy.scope_key
        when 'command' then r.command_code=v_policy.scope_key
        when 'user' then r.actor_id=v_policy.scope_key
        else false end;

    v_effective_day_limit := v_policy.max_requests_per_day;
    if v_route.assignment_mode='emergency_reserve' then
      v_effective_day_limit := coalesce(v_effective_day_limit,0)+greatest(0,coalesce(v_policy.emergency_reserve_requests,0));
    end if;
    v_scope_title := upper(v_policy.scope_type)||':'||v_policy.scope_key;

    if v_policy.hard_limit then
      if v_policy.max_requests_per_minute is not null and v_policy.max_requests_per_minute>0 and v_used_minute+p_estimated_requests>v_policy.max_requests_per_minute then raise exception 'AI_PROVIDER_BUDGET_EXHAUSTED:%:MINUTE',v_scope_title; end if;
      if v_policy.max_requests_per_hour is not null and v_policy.max_requests_per_hour>0 and v_used_hour+p_estimated_requests>v_policy.max_requests_per_hour then raise exception 'AI_PROVIDER_BUDGET_EXHAUSTED:%:HOUR',v_scope_title; end if;
      if v_effective_day_limit is not null and v_effective_day_limit>0 and v_used_day+p_estimated_requests>v_effective_day_limit then raise exception 'AI_PROVIDER_BUDGET_EXHAUSTED:%:DAY',v_scope_title; end if;
      if v_policy.max_requests_per_month is not null and v_policy.max_requests_per_month>0 and v_used_month+p_estimated_requests>v_policy.max_requests_per_month then raise exception 'AI_PROVIDER_BUDGET_EXHAUSTED:%:MONTH',v_scope_title; end if;
      if p_grounded and v_policy.max_grounded_requests_per_day is not null and v_policy.max_grounded_requests_per_day>0 and v_grounded_day+p_estimated_requests>v_policy.max_grounded_requests_per_day then raise exception 'AI_PROVIDER_GROUNDING_BUDGET_EXHAUSTED:%',v_scope_title; end if;
      if v_policy.max_concurrent_requests is not null and v_policy.max_concurrent_requests>0 and v_active_leases>=v_policy.max_concurrent_requests then raise exception 'AI_PROVIDER_CONCURRENCY_EXHAUSTED:%',v_scope_title; end if;
      if v_policy.max_input_tokens_per_day is not null and v_policy.max_input_tokens_per_day>0 and v_input_day+p_estimated_input_tokens>v_policy.max_input_tokens_per_day then raise exception 'AI_PROVIDER_INPUT_TOKEN_BUDGET_EXHAUSTED:%',v_scope_title; end if;
      if v_policy.max_output_tokens_per_day is not null and v_policy.max_output_tokens_per_day>0 and v_output_day+p_estimated_output_tokens>v_policy.max_output_tokens_per_day then raise exception 'AI_PROVIDER_OUTPUT_TOKEN_BUDGET_EXHAUSTED:%',v_scope_title; end if;
    end if;

    if v_policy.max_requests_per_day is not null and v_policy.max_requests_per_day>0 then
      v_soft_boundary := v_policy.max_requests_per_day*(v_policy.soft_threshold_percent::numeric/100);
      if v_used_day+p_estimated_requests>=v_soft_boundary then
        insert into public.ai_provider_alerts(alert_type,severity,title,message,scope_type,scope_key,metadata)
        select 'quota_threshold',case when v_used_day+p_estimated_requests>=v_policy.max_requests_per_day then 'critical' else 'warning' end,
          'Seuil de capacité IA atteint',
          format('%s requêtes utilisées ou réservées sur %s autorisées.',v_used_day+p_estimated_requests,v_policy.max_requests_per_day),
          v_policy.scope_type,v_policy.scope_key,
          jsonb_build_object('policyId',v_policy.id,'used',v_used_day,'estimated',p_estimated_requests,'limit',v_policy.max_requests_per_day)
        where not exists(
          select 1 from public.ai_provider_alerts a
          where a.alert_type='quota_threshold' and a.scope_type=v_policy.scope_type and a.scope_key=v_policy.scope_key
            and a.status='open' and a.created_at>=v_day_start
        );
      end if;
    end if;
  end loop;

  insert into public.ai_provider_budget_reservations(
    module_key,capability,dossier_id,capacity_pool_id,credential_id,model_code,
    reserved_requests,reserved_input_tokens,reserved_output_tokens,grounded,status,
    actor_id,mission_id,command_code
  ) values (
    p_module_key,p_capability,v_route.dossier_id,v_route.capacity_pool_id,v_route.credential_id,v_route.model_code,
    p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_grounded,'running',
    p_actor_id,p_mission_id,p_command_code
  ) returning id into v_reservation;

  insert into public.ai_provider_runtime_leases(reservation_id,module_key,capacity_pool_id,credential_id,status)
  values(v_reservation,p_module_key,v_route.capacity_pool_id,v_route.credential_id,'active') returning id into v_lease;

  return query select v_reservation,v_lease,v_route.assignment_id,v_route.assignment_mode,v_route.dossier_id,v_route.provider_type,v_route.capacity_pool_id,v_route.credential_id,v_route.model_code;
end;
$$;


--
-- Name: FUNCTION ai_provider_acquire_runtime_budget(p_module_key text, p_capability text, p_requested_model text, p_estimated_requests integer, p_estimated_input_tokens bigint, p_estimated_output_tokens bigint, p_grounded boolean, p_actor_id text, p_mission_id text, p_command_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ai_provider_acquire_runtime_budget(p_module_key text, p_capability text, p_requested_model text, p_estimated_requests integer, p_estimated_input_tokens bigint, p_estimated_output_tokens bigint, p_grounded boolean, p_actor_id text, p_mission_id text, p_command_code text) IS 'Atomic provider routing, quota reservation and concurrency lease acquisition for all SANILA AI modules.';


--
-- Name: ai_provider_begin_governed_request(text, text, text, text, text, text, text, text, text, text, text, text, text, integer, bigint, bigint, numeric, boolean, boolean, boolean, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_begin_governed_request(p_module_key text, p_workspace_key text, p_capability text, p_command_code text, p_requested_model text, p_request_fingerprint text, p_prompt_version text DEFAULT NULL::text, p_source_revision text DEFAULT NULL::text, p_trigger_type text DEFAULT 'manual'::text, p_schedule_key text DEFAULT NULL::text, p_actor_id text DEFAULT NULL::text, p_mission_id text DEFAULT NULL::text, p_mandate_id text DEFAULT NULL::text, p_estimated_requests integer DEFAULT 1, p_estimated_input_tokens bigint DEFAULT 0, p_estimated_output_tokens bigint DEFAULT 0, p_estimated_cost_usd numeric DEFAULT 0, p_grounded boolean DEFAULT false, p_force_refresh boolean DEFAULT false, p_approval_granted boolean DEFAULT false, p_cache_ttl_seconds integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(decision text, request_id uuid, source_request_id uuid, reservation_id uuid, lease_id uuid, dossier_id uuid, capacity_pool_id uuid, credential_id uuid, provider_type text, model_code text, assignment_mode text, cached_result jsonb, cache_expires_at timestamp with time zone, policy_snapshot jsonb, quota_snapshot jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_policy record;
  v_schedule record;
  v_schedule_id uuid := null;
  v_cache record;
  v_inflight record;
  v_route record;
  v_budget record;
  v_stale record;
  v_request_id uuid := gen_random_uuid();
  v_day_start timestamptz := date_trunc('day',now());
  v_week_start timestamptz := date_trunc('week',now());
  v_month_start timestamptz := date_trunc('month',now());
  v_day_runs bigint := 0;
  v_week_runs bigint := 0;
  v_month_runs bigint := 0;
  v_day_cost numeric := 0;
  v_week_cost numeric := 0;
  v_consecutive_failures integer := 0;
  v_last_completed timestamptz;
  v_last_failed timestamptz;
  v_retry_failures integer := 0;
  v_error text;
  v_block_decision text;
  v_block_status text;
  v_schedule_day_runs bigint := 0;
  v_schedule_week_runs bigint := 0;
  v_q record;
  v_q_day_cost numeric;
  v_q_week_cost numeric;
  v_q_month_cost numeric;
  v_q_week_requests bigint;
  v_q_week_input bigint;
  v_q_week_output bigint;
  v_q_reserved_cost_day numeric;
  v_q_reserved_cost_week numeric;
  v_q_reserved_cost_month numeric;
  v_q_reserved_requests_week bigint;
  v_q_reserved_input_week bigint;
  v_q_reserved_output_week bigint;
  v_policy_json jsonb;
  v_quota_json jsonb := '{}'::jsonb;
  v_ttl integer;
begin
  if coalesce(nullif(p_module_key,''),'')='' or coalesce(nullif(p_capability,''),'')='' or coalesce(nullif(p_request_fingerprint,''),'')='' then
    raise exception 'AI_PROVIDER_GOVERNED_REQUEST_IDENTITY_REQUIRED';
  end if;
  p_workspace_key:=coalesce(nullif(p_workspace_key,''),'*');
  p_command_code:=coalesce(nullif(p_command_code,''),p_capability);
  p_trigger_type:=coalesce(nullif(p_trigger_type,''),'manual');
  p_estimated_requests:=greatest(1,coalesce(p_estimated_requests,1));
  p_estimated_input_tokens:=greatest(0,coalesce(p_estimated_input_tokens,0));
  p_estimated_output_tokens:=greatest(0,coalesce(p_estimated_output_tokens,0));
  p_estimated_cost_usd:=greatest(0,coalesce(p_estimated_cost_usd,0));

  perform pg_advisory_xact_lock(hashtextextended('ai_provider:fingerprint:'||p_request_fingerprint,0));

  for v_stale in
    select * from public.ai_provider_governed_requests
    where request_fingerprint=p_request_fingerprint
      and status in ('queued','running')
      and created_at<now()-interval '20 minutes'
    order by created_at asc
    limit 10
    for update skip locked
  loop
    if v_stale.reservation_id is not null then
      perform public.ai_provider_fail_runtime_budget(
        v_stale.reservation_id,v_stale.lease_id,null,'STALE_RUNTIME_REQUEST',null,
        jsonb_build_object('governedRequestId',v_stale.id,'recoveredBy','AI Provider Control Phase 5')
      );
    end if;
    update public.ai_provider_governed_requests
    set status='expired',completed_at=now(),updated_at=now(),error_code='STALE_RUNTIME_REQUEST',
        error_message='Recovered stale governed request and released its reservation.'
    where id=v_stale.id;
  end loop;

  select * into v_policy
  from public.ai_provider_command_policies p
  where p.enabled=true
    and p.module_key in (p_module_key,'*')
    and p.workspace_key in (p_workspace_key,'*')
    and (p.command_code=p_command_code or (right(p.command_code,1)='*' and p_command_code like left(p.command_code,length(p.command_code)-1)||'%') or p.command_code='*')
  order by (p.module_key=p_module_key) desc,(p.workspace_key=p_workspace_key) desc,(p.command_code=p_command_code) desc,length(p.command_code) desc
  limit 1;
  v_policy_json:=case when v_policy.id is null then null else to_jsonb(v_policy) end;

  if v_policy.id is not null then
    if v_policy.ai_mode='ai_prohibited' then raise exception 'AI_PROVIDER_COMMAND_AI_PROHIBITED:%',p_command_code; end if;
    if p_trigger_type='scheduled' and not v_policy.scheduled_allowed then raise exception 'AI_PROVIDER_SCHEDULED_TRIGGER_NOT_ALLOWED:%',p_command_code; end if;
    if p_trigger_type<>'scheduled' and not v_policy.manual_allowed then raise exception 'AI_PROVIDER_MANUAL_TRIGGER_NOT_ALLOWED:%',p_command_code; end if;
    if cardinality(v_policy.allowed_trigger_types)>0 and not (p_trigger_type=any(v_policy.allowed_trigger_types)) then raise exception 'AI_PROVIDER_TRIGGER_TYPE_NOT_ALLOWED:%',p_trigger_type; end if;
    if p_force_refresh and not v_policy.force_refresh_allowed then raise exception 'AI_PROVIDER_FORCE_REFRESH_NOT_ALLOWED'; end if;
    if coalesce(nullif(v_policy.approval_class,''),'none')<>'none' and not p_approval_granted then raise exception 'AI_PROVIDER_APPROVAL_REQUIRED:%',v_policy.approval_class; end if;
  end if;

  if p_trigger_type='scheduled' then
    select * into v_schedule from public.ai_provider_command_schedules
    where schedule_key=p_schedule_key and module_key=p_module_key and command_code=p_command_code
    limit 1 for update;
    if not found or not v_schedule.enabled or v_schedule.status<>'active' then raise exception 'AI_PROVIDER_SCHEDULE_NOT_ACTIVE:%',coalesce(p_schedule_key,''); end if;
    if v_schedule.next_run_at is not null and v_schedule.next_run_at>now() then raise exception 'AI_PROVIDER_SCHEDULE_NOT_DUE:%',coalesce(p_schedule_key,''); end if;
    v_schedule_id:=v_schedule.id;
  end if;

  if not p_force_refresh and (v_policy.id is null or v_policy.cache_mode<>'no_cache') then
    select * into v_cache
    from public.ai_provider_structured_result_cache
    where request_fingerprint=p_request_fingerprint
      and validation_status='validated' and invalidated_at is null
      and (expires_at is null or expires_at>now())
    limit 1 for update;
    if found then
      insert into public.ai_provider_governed_requests(
        id,request_fingerprint,module_key,workspace_key,capability,command_code,mandate_id,mission_id,actor_id,
        trigger_type,prompt_version,source_revision,requested_model,provider_type,model_code,
        decision,status,source_request_id,estimated_requests,estimated_input_tokens,estimated_output_tokens,
        estimated_cost_usd,result_json,result_hash,cache_expires_at,completed_at,metadata
      ) values (
        v_request_id,p_request_fingerprint,p_module_key,p_workspace_key,p_capability,p_command_code,p_mandate_id,p_mission_id,p_actor_id,
        p_trigger_type,p_prompt_version,p_source_revision,p_requested_model,v_cache.provider_type,v_cache.model_code,
        'REUSE_CACHED','completed',v_cache.source_request_id,p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,
        p_estimated_cost_usd,v_cache.result_json,v_cache.result_hash,v_cache.expires_at,now(),coalesce(p_metadata,'{}'::jsonb)
      );
      update public.ai_provider_structured_result_cache set
        reuse_count=reuse_count+1,
        avoided_input_tokens=avoided_input_tokens+p_estimated_input_tokens,
        avoided_output_tokens=avoided_output_tokens+p_estimated_output_tokens,
        avoided_cost_usd=avoided_cost_usd+p_estimated_cost_usd,
        updated_at=now()
      where id=v_cache.id;
      insert into public.ai_provider_reuse_events(request_id,source_request_id,cache_id,module_key,workspace_key,command_code,event_type,avoided_requests,avoided_input_tokens,avoided_output_tokens,avoided_cost_usd,actor_id,metadata)
      values(v_request_id,v_cache.source_request_id,v_cache.id,p_module_key,p_workspace_key,p_command_code,'cache_reuse',p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_estimated_cost_usd,p_actor_id,coalesce(p_metadata,'{}'::jsonb));
      return query select 'REUSE_CACHED',v_request_id,v_cache.source_request_id,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,v_cache.provider_type,v_cache.model_code,null::text,v_cache.result_json,v_cache.expires_at,v_policy_json,jsonb_build_object('providerCallAvoided',true);
      return;
    end if;
  end if;

  select * into v_inflight
  from public.ai_provider_governed_requests
  where request_fingerprint=p_request_fingerprint and status in ('queued','running')
  order by created_at desc limit 1;
  if found then
    insert into public.ai_provider_governed_requests(
      id,request_fingerprint,module_key,workspace_key,capability,command_code,mandate_id,mission_id,actor_id,
      trigger_type,prompt_version,source_revision,requested_model,decision,status,source_request_id,
      estimated_requests,estimated_input_tokens,estimated_output_tokens,estimated_cost_usd,metadata
    ) values (
      v_request_id,p_request_fingerprint,p_module_key,p_workspace_key,p_capability,p_command_code,p_mandate_id,p_mission_id,p_actor_id,
      p_trigger_type,p_prompt_version,p_source_revision,p_requested_model,'JOIN_IN_FLIGHT','joined',v_inflight.id,
      p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_estimated_cost_usd,coalesce(p_metadata,'{}'::jsonb)
    );
    insert into public.ai_provider_reuse_events(request_id,source_request_id,module_key,workspace_key,command_code,event_type,avoided_requests,avoided_input_tokens,avoided_output_tokens,avoided_cost_usd,actor_id,metadata)
    values(v_request_id,v_inflight.id,p_module_key,p_workspace_key,p_command_code,'joined_in_flight',p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_estimated_cost_usd,p_actor_id,coalesce(p_metadata,'{}'::jsonb));
    return query select 'JOIN_IN_FLIGHT',v_request_id,v_inflight.id,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,v_inflight.provider_type,v_inflight.model_code,null::text,null::jsonb,null::timestamptz,v_policy_json,jsonb_build_object('providerCallAvoided',true);
    return;
  end if;

  if v_policy.id is not null then
    if v_policy.ai_mode='ai_prohibited' then raise exception 'AI_PROVIDER_COMMAND_AI_PROHIBITED:%',p_command_code; end if;
    if p_trigger_type='scheduled' and not v_policy.scheduled_allowed then raise exception 'AI_PROVIDER_SCHEDULED_TRIGGER_NOT_ALLOWED:%',p_command_code; end if;
    if p_trigger_type<>'scheduled' and not v_policy.manual_allowed then raise exception 'AI_PROVIDER_MANUAL_TRIGGER_NOT_ALLOWED:%',p_command_code; end if;
    if cardinality(v_policy.allowed_trigger_types)>0 and not (p_trigger_type=any(v_policy.allowed_trigger_types)) then raise exception 'AI_PROVIDER_TRIGGER_TYPE_NOT_ALLOWED:%',p_trigger_type; end if;
    if p_force_refresh and not v_policy.force_refresh_allowed then raise exception 'AI_PROVIDER_FORCE_REFRESH_NOT_ALLOWED'; end if;
    if coalesce(nullif(v_policy.approval_class,''),'none')<>'none' and not p_approval_granted then
      insert into public.ai_provider_governed_requests(id,request_fingerprint,module_key,workspace_key,capability,command_code,mandate_id,mission_id,actor_id,trigger_type,prompt_version,source_revision,requested_model,decision,status,estimated_requests,estimated_input_tokens,estimated_output_tokens,estimated_cost_usd,metadata)
      values(v_request_id,p_request_fingerprint,p_module_key,p_workspace_key,p_capability,p_command_code,p_mandate_id,p_mission_id,p_actor_id,p_trigger_type,p_prompt_version,p_source_revision,p_requested_model,'REQUIRE_APPROVAL','blocked',p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_estimated_cost_usd,coalesce(p_metadata,'{}'::jsonb));
      return query select 'REQUIRE_APPROVAL',v_request_id,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,null::text,null::text,null::text,null::jsonb,null::timestamptz,v_policy_json,jsonb_build_object('reason','APPROVAL_REQUIRED');
      return;
    end if;
    if v_policy.max_input_tokens_per_run is not null and p_estimated_input_tokens>v_policy.max_input_tokens_per_run then raise exception 'AI_PROVIDER_COMMAND_INPUT_TOKEN_CEILING:%',p_command_code; end if;
    if v_policy.max_output_tokens_per_run is not null and p_estimated_output_tokens>v_policy.max_output_tokens_per_run then raise exception 'AI_PROVIDER_COMMAND_OUTPUT_TOKEN_CEILING:%',p_command_code; end if;
    if v_policy.max_cost_usd_per_run is not null and p_estimated_cost_usd>v_policy.max_cost_usd_per_run then raise exception 'AI_PROVIDER_COMMAND_COST_CEILING:%',p_command_code; end if;

    select max(completed_at) into v_last_completed from public.ai_provider_governed_requests
    where module_key=p_module_key and command_code=p_command_code and decision='EXECUTE_NEW' and status='completed';
    if v_policy.minimum_interval_seconds>0 and v_last_completed is not null and v_last_completed>now()-make_interval(secs=>v_policy.minimum_interval_seconds) then
      raise exception 'AI_PROVIDER_COMMAND_MINIMUM_INTERVAL:%',p_command_code;
    end if;
    select max(completed_at) into v_last_failed from public.ai_provider_governed_requests
    where module_key=p_module_key and command_code=p_command_code and decision='EXECUTE_NEW' and status='failed';
    if v_policy.cooldown_after_failure_seconds>0 and v_last_failed is not null and v_last_failed>now()-make_interval(secs=>v_policy.cooldown_after_failure_seconds) then
      raise exception 'AI_PROVIDER_COMMAND_FAILURE_COOLDOWN:%',p_command_code;
    end if;
    if p_trigger_type='retry' then
      select count(*) into v_retry_failures from public.ai_provider_governed_requests
      where request_fingerprint=p_request_fingerprint and status='failed';
      if v_retry_failures>v_policy.max_retries then raise exception 'AI_PROVIDER_COMMAND_RETRY_LIMIT:%',p_command_code; end if;
    end if;

    select
      count(*) filter(where created_at>=v_day_start),
      count(*) filter(where created_at>=v_week_start),
      count(*) filter(where created_at>=v_month_start),
      coalesce(sum(case when status='running' then estimated_cost_usd else actual_cost_usd end) filter(where created_at>=v_day_start),0),
      coalesce(sum(case when status='running' then estimated_cost_usd else actual_cost_usd end) filter(where created_at>=v_week_start),0)
    into v_day_runs,v_week_runs,v_month_runs,v_day_cost,v_week_cost
    from public.ai_provider_governed_requests
    where module_key=p_module_key and command_code=p_command_code and decision='EXECUTE_NEW' and status in ('running','completed');

    if v_policy.max_runs_per_day is not null and v_day_runs+1>v_policy.max_runs_per_day then raise exception 'AI_PROVIDER_COMMAND_DAILY_RUN_LIMIT:%',p_command_code; end if;
    if v_policy.max_runs_per_week is not null and v_week_runs+1>v_policy.max_runs_per_week then raise exception 'AI_PROVIDER_COMMAND_WEEKLY_RUN_LIMIT:%',p_command_code; end if;
    if v_policy.max_runs_per_month is not null and v_month_runs+1>v_policy.max_runs_per_month then raise exception 'AI_PROVIDER_COMMAND_MONTHLY_RUN_LIMIT:%',p_command_code; end if;
    if v_policy.max_cost_usd_per_day is not null and v_day_cost+p_estimated_cost_usd>v_policy.max_cost_usd_per_day then raise exception 'AI_PROVIDER_COMMAND_DAILY_COST_LIMIT:%',p_command_code; end if;
    if v_policy.max_cost_usd_per_week is not null and v_week_cost+p_estimated_cost_usd>v_policy.max_cost_usd_per_week then raise exception 'AI_PROVIDER_COMMAND_WEEKLY_COST_LIMIT:%',p_command_code; end if;

    select count(*) into v_consecutive_failures from (
      select status from public.ai_provider_governed_requests
      where module_key=p_module_key and command_code=p_command_code and decision='EXECUTE_NEW'
      order by created_at desc limit greatest(1,v_policy.consecutive_failure_suspend_threshold)
    ) recent where status='failed';
    if v_policy.consecutive_failure_suspend_threshold>0 and v_consecutive_failures>=v_policy.consecutive_failure_suspend_threshold then
      raise exception 'AI_PROVIDER_COMMAND_SUSPENDED_AFTER_FAILURES:%',p_command_code;
    end if;
  end if;

  if p_trigger_type='scheduled' then
    select * into v_schedule from public.ai_provider_command_schedules
    where schedule_key=p_schedule_key and module_key=p_module_key and command_code=p_command_code
    limit 1 for update;
    if not found or not v_schedule.enabled or v_schedule.status<>'active'
      or (v_schedule.next_run_at is not null and v_schedule.next_run_at>now())
      or (v_schedule.freshness_seconds>0 and v_schedule.last_completed_at is not null
          and v_schedule.last_completed_at>now()-make_interval(secs=>v_schedule.freshness_seconds)) then
      insert into public.ai_provider_governed_requests(id,request_fingerprint,module_key,workspace_key,capability,command_code,mandate_id,mission_id,actor_id,trigger_type,prompt_version,source_revision,requested_model,decision,status,estimated_requests,estimated_input_tokens,estimated_output_tokens,estimated_cost_usd,metadata)
      values(v_request_id,p_request_fingerprint,p_module_key,p_workspace_key,p_capability,p_command_code,p_mandate_id,p_mission_id,p_actor_id,p_trigger_type,p_prompt_version,p_source_revision,p_requested_model,'DEFER_SCHEDULE','deferred',p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_estimated_cost_usd,coalesce(p_metadata,'{}'::jsonb));
      insert into public.ai_provider_reuse_events(request_id,module_key,workspace_key,command_code,event_type,actor_id,metadata)
      values(v_request_id,p_module_key,p_workspace_key,p_command_code,'schedule_deferred',p_actor_id,
        jsonb_build_object('reason',case
          when v_schedule.id is not null and v_schedule.next_run_at>now() then 'SCHEDULE_NOT_DUE'
          when v_schedule.id is not null and v_schedule.freshness_seconds>0 and v_schedule.last_completed_at is not null
            and v_schedule.last_completed_at>now()-make_interval(secs=>v_schedule.freshness_seconds) then 'SCHEDULE_RESULT_STILL_FRESH'
          else 'SCHEDULE_NOT_ACTIVE' end,'scheduleKey',p_schedule_key));
      return query select 'DEFER_SCHEDULE',v_request_id,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,null::text,null::text,null::text,null::jsonb,null::timestamptz,v_policy_json,
        jsonb_build_object('reason',case
          when v_schedule.id is not null and v_schedule.next_run_at>now() then 'SCHEDULE_NOT_DUE'
          when v_schedule.id is not null and v_schedule.freshness_seconds>0 and v_schedule.last_completed_at is not null
            and v_schedule.last_completed_at>now()-make_interval(secs=>v_schedule.freshness_seconds) then 'SCHEDULE_RESULT_STILL_FRESH'
          else 'SCHEDULE_NOT_ACTIVE' end);
      return;
    end if;
    v_schedule_id:=v_schedule.id;
    select count(*) filter(where created_at>=v_day_start),count(*) filter(where created_at>=v_week_start)
    into v_schedule_day_runs,v_schedule_week_runs
    from public.ai_provider_governed_requests where schedule_id=v_schedule_id and decision='EXECUTE_NEW' and status in ('running','completed');
    if v_schedule.max_runs_per_day is not null and v_schedule_day_runs+1>v_schedule.max_runs_per_day then raise exception 'AI_PROVIDER_SCHEDULE_DAILY_LIMIT:%',p_schedule_key; end if;
    if v_schedule.max_runs_per_week is not null and v_schedule_week_runs+1>v_schedule.max_runs_per_week then raise exception 'AI_PROVIDER_SCHEDULE_WEEKLY_LIMIT:%',p_schedule_key; end if;
  end if;

  select * into v_route from public.ai_provider_resolve_runtime_provider(p_module_key,p_capability,p_requested_model) limit 1;
  if not found then raise exception 'AI_PROVIDER_ROUTE_NOT_FOUND'; end if;
  if v_policy.id is not null then
    if cardinality(v_policy.allowed_provider_types)>0 and not (v_route.provider_type=any(v_policy.allowed_provider_types)) then raise exception 'AI_PROVIDER_PROVIDER_NOT_ALLOWED:%',v_route.provider_type; end if;
    if cardinality(v_policy.allowed_models)>0 and not (v_route.model_code=any(v_policy.allowed_models)) then raise exception 'AI_PROVIDER_MODEL_NOT_ALLOWED_BY_COMMAND:%',v_route.model_code; end if;
  end if;

  for v_q in
    select q.* from public.ai_provider_quota_policies q
    where q.enabled=true and (
      (q.scope_type='global' and q.scope_key='*') or
      (q.scope_type='module' and q.scope_key=p_module_key) or
      (q.scope_type='dossier' and q.scope_key=v_route.dossier_id::text) or
      (q.scope_type='capacity_pool' and q.scope_key=v_route.capacity_pool_id::text) or
      (q.scope_type='model' and q.scope_key=v_route.model_code) or
      (q.scope_type='command' and q.scope_key=p_command_code) or
      (q.scope_type='user' and p_actor_id is not null and q.scope_key=p_actor_id)
    )
  loop
    select
      coalesce(sum(estimated_cost_usd) filter(where occurred_at>=v_day_start),0),
      coalesce(sum(estimated_cost_usd) filter(where occurred_at>=v_week_start),0),
      coalesce(sum(estimated_cost_usd) filter(where occurred_at>=v_month_start),0),
      coalesce(sum(request_count) filter(where occurred_at>=v_week_start),0),
      coalesce(sum(input_tokens) filter(where occurred_at>=v_week_start),0),
      coalesce(sum(output_tokens) filter(where occurred_at>=v_week_start),0)
    into v_q_day_cost,v_q_week_cost,v_q_month_cost,v_q_week_requests,v_q_week_input,v_q_week_output
    from public.ai_provider_usage_ledger u
    where case v_q.scope_type
      when 'global' then true when 'module' then u.module_key=v_q.scope_key
      when 'dossier' then u.dossier_id::text=v_q.scope_key when 'capacity_pool' then u.capacity_pool_id::text=v_q.scope_key
      when 'model' then u.model_code=v_q.scope_key when 'command' then u.command_code=v_q.scope_key
      when 'user' then u.actor_id=v_q.scope_key else false end;

    select
      coalesce(sum(reserved_cost_usd) filter(where created_at>=v_day_start),0),
      coalesce(sum(reserved_cost_usd) filter(where created_at>=v_week_start),0),
      coalesce(sum(reserved_cost_usd) filter(where created_at>=v_month_start),0),
      coalesce(sum(reserved_requests) filter(where created_at>=v_week_start),0),
      coalesce(sum(reserved_input_tokens) filter(where created_at>=v_week_start),0),
      coalesce(sum(reserved_output_tokens) filter(where created_at>=v_week_start),0)
    into v_q_reserved_cost_day,v_q_reserved_cost_week,v_q_reserved_cost_month,v_q_reserved_requests_week,v_q_reserved_input_week,v_q_reserved_output_week
    from public.ai_provider_budget_reservations r
    where r.status in ('reserved','running') and case v_q.scope_type
      when 'global' then true when 'module' then r.module_key=v_q.scope_key
      when 'dossier' then r.dossier_id::text=v_q.scope_key when 'capacity_pool' then r.capacity_pool_id::text=v_q.scope_key
      when 'model' then r.model_code=v_q.scope_key when 'command' then r.command_code=v_q.scope_key
      when 'user' then r.actor_id=v_q.scope_key else false end;

    v_q_day_cost:=v_q_day_cost+v_q_reserved_cost_day;
    v_q_week_cost:=v_q_week_cost+v_q_reserved_cost_week;
    v_q_month_cost:=v_q_month_cost+v_q_reserved_cost_month;
    v_q_week_requests:=v_q_week_requests+v_q_reserved_requests_week;
    v_q_week_input:=v_q_week_input+v_q_reserved_input_week;
    v_q_week_output:=v_q_week_output+v_q_reserved_output_week;

    if v_q.hard_limit then
      if v_q.max_requests_per_week is not null and v_q_week_requests+p_estimated_requests>v_q.max_requests_per_week then raise exception 'AI_PROVIDER_WEEKLY_REQUEST_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
      if v_q.max_input_tokens_per_week is not null and v_q_week_input+p_estimated_input_tokens>v_q.max_input_tokens_per_week then raise exception 'AI_PROVIDER_WEEKLY_INPUT_TOKEN_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
      if v_q.max_output_tokens_per_week is not null and v_q_week_output+p_estimated_output_tokens>v_q.max_output_tokens_per_week then raise exception 'AI_PROVIDER_WEEKLY_OUTPUT_TOKEN_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
      if v_q.max_total_tokens_per_week is not null and v_q_week_input+v_q_week_output+p_estimated_input_tokens+p_estimated_output_tokens>v_q.max_total_tokens_per_week then raise exception 'AI_PROVIDER_WEEKLY_TOTAL_TOKEN_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
      if v_q.max_estimated_cost_usd_per_day is not null and v_q_day_cost+p_estimated_cost_usd>v_q.max_estimated_cost_usd_per_day then raise exception 'AI_PROVIDER_DAILY_COST_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
      if v_q.max_estimated_cost_usd_per_week is not null and v_q_week_cost+p_estimated_cost_usd>v_q.max_estimated_cost_usd_per_week then raise exception 'AI_PROVIDER_WEEKLY_COST_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
      if v_q.max_estimated_cost_usd_per_month is not null and v_q_month_cost+p_estimated_cost_usd>v_q.max_estimated_cost_usd_per_month then raise exception 'AI_PROVIDER_MONTHLY_COST_BUDGET_EXHAUSTED:%:%',v_q.scope_type,v_q.scope_key; end if;
    end if;
    v_quota_json:=v_quota_json||jsonb_build_object(v_q.scope_type||':'||v_q.scope_key,jsonb_build_object('weekRequests',v_q_week_requests,'weekInputTokens',v_q_week_input,'weekOutputTokens',v_q_week_output,'dayCostUsd',v_q_day_cost,'weekCostUsd',v_q_week_cost,'monthCostUsd',v_q_month_cost));
  end loop;

  select * into v_budget
  from public.ai_provider_acquire_runtime_budget(
    p_module_key,p_capability,v_route.model_code,p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,
    p_grounded,p_actor_id,p_mission_id,p_command_code
  ) limit 1;

  update public.ai_provider_budget_reservations set
    reserved_cost_usd=p_estimated_cost_usd,workspace_key=p_workspace_key,trigger_type=p_trigger_type,
    request_fingerprint=p_request_fingerprint,governed_request_id=v_request_id,
    metadata=metadata||jsonb_build_object('promptVersion',p_prompt_version,'sourceRevision',p_source_revision,'mandateId',p_mandate_id)
  where id=v_budget.reservation_id;

  insert into public.ai_provider_governed_requests(
    id,request_fingerprint,module_key,workspace_key,capability,command_code,mandate_id,mission_id,actor_id,trigger_type,schedule_id,
    prompt_version,source_revision,requested_model,provider_type,model_code,decision,status,reservation_id,lease_id,
    estimated_requests,estimated_input_tokens,estimated_output_tokens,estimated_cost_usd,started_at,metadata
  ) values (
    v_request_id,p_request_fingerprint,p_module_key,p_workspace_key,p_capability,p_command_code,p_mandate_id,p_mission_id,p_actor_id,p_trigger_type,v_schedule_id,
    p_prompt_version,p_source_revision,p_requested_model,v_budget.provider_type,v_budget.model_code,'EXECUTE_NEW','running',v_budget.reservation_id,v_budget.lease_id,
    p_estimated_requests,p_estimated_input_tokens,p_estimated_output_tokens,p_estimated_cost_usd,now(),coalesce(p_metadata,'{}'::jsonb)
  );

  if v_schedule_id is not null then
    update public.ai_provider_command_schedules set last_started_at=now(),updated_at=now() where id=v_schedule_id;
  end if;

  v_ttl:=case
    when v_policy.id is not null and v_policy.cache_mode='no_cache' then 0
    when v_policy.id is not null and p_cache_ttl_seconds is not null then least(greatest(0,p_cache_ttl_seconds),greatest(0,v_policy.cache_ttl_seconds))
    when v_policy.id is not null then greatest(0,v_policy.cache_ttl_seconds)
    else greatest(0,coalesce(p_cache_ttl_seconds,0)) end;
  update public.ai_provider_governed_requests
  set cache_expires_at=case when v_ttl>0 then now()+make_interval(secs=>v_ttl) else null end,
      metadata=metadata||jsonb_build_object('effectiveCacheTtlSeconds',v_ttl),updated_at=now()
  where id=v_request_id;
  return query select 'EXECUTE_NEW',v_request_id,null::uuid,v_budget.reservation_id,v_budget.lease_id,v_budget.dossier_id,v_budget.capacity_pool_id,v_budget.credential_id,v_budget.provider_type,v_budget.model_code,v_budget.assignment_mode,null::jsonb,case when v_ttl>0 then now()+make_interval(secs=>v_ttl) else null end,v_policy_json,v_quota_json;
exception when others then
  v_error:=sqlerrm;
  v_block_decision:=case
    when v_error ilike '%APPROVAL%' then 'REQUIRE_APPROVAL'
    when v_error ilike '%SCHEDULE%' then 'DEFER_SCHEDULE'
    when v_error ilike '%BUDGET%' or v_error ilike '%QUOTA%' or v_error ilike '%LIMIT%' or v_error ilike '%CEILING%' or v_error ilike '%CONCURRENCY%' then 'BLOCK_QUOTA'
    else 'BLOCK_POLICY' end;
  v_block_status:=case when v_block_decision='DEFER_SCHEDULE' then 'deferred' else 'blocked' end;
  insert into public.ai_provider_governed_requests(
    id,request_fingerprint,module_key,workspace_key,capability,command_code,mandate_id,mission_id,actor_id,trigger_type,schedule_id,
    prompt_version,source_revision,requested_model,decision,status,estimated_requests,estimated_input_tokens,estimated_output_tokens,
    estimated_cost_usd,error_code,error_message,completed_at,metadata
  ) values (
    v_request_id,p_request_fingerprint,p_module_key,coalesce(nullif(p_workspace_key,''),'*'),p_capability,coalesce(nullif(p_command_code,''),p_capability),
    p_mandate_id,p_mission_id,p_actor_id,coalesce(nullif(p_trigger_type,''),'manual'),v_schedule_id,p_prompt_version,p_source_revision,p_requested_model,
    v_block_decision,v_block_status,greatest(1,coalesce(p_estimated_requests,1)),greatest(0,coalesce(p_estimated_input_tokens,0)),
    greatest(0,coalesce(p_estimated_output_tokens,0)),greatest(0,coalesce(p_estimated_cost_usd,0)),left(v_error,160),left(v_error,2000),now(),
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('blockedBy','AI Provider Control','reason',v_error)
  );
  return query select v_block_decision,v_request_id,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,null::uuid,null::text,null::text,null::text,null::jsonb,null::timestamptz,v_policy_json,jsonb_build_object('reason',v_error);
end;
$$;


--
-- Name: FUNCTION ai_provider_begin_governed_request(p_module_key text, p_workspace_key text, p_capability text, p_command_code text, p_requested_model text, p_request_fingerprint text, p_prompt_version text, p_source_revision text, p_trigger_type text, p_schedule_key text, p_actor_id text, p_mission_id text, p_mandate_id text, p_estimated_requests integer, p_estimated_input_tokens bigint, p_estimated_output_tokens bigint, p_estimated_cost_usd numeric, p_grounded boolean, p_force_refresh boolean, p_approval_granted boolean, p_cache_ttl_seconds integer, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ai_provider_begin_governed_request(p_module_key text, p_workspace_key text, p_capability text, p_command_code text, p_requested_model text, p_request_fingerprint text, p_prompt_version text, p_source_revision text, p_trigger_type text, p_schedule_key text, p_actor_id text, p_mission_id text, p_mandate_id text, p_estimated_requests integer, p_estimated_input_tokens bigint, p_estimated_output_tokens bigint, p_estimated_cost_usd numeric, p_grounded boolean, p_force_refresh boolean, p_approval_granted boolean, p_cache_ttl_seconds integer, p_metadata jsonb) IS 'Sole Phase 5 gateway entry: deduplicate, reuse, enforce frequency/weekly/cost policy, route and reserve.';


--
-- Name: ai_provider_complete_governed_request(uuid, jsonb, text, bigint, bigint, integer, integer, numeric, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_complete_governed_request(p_request_id uuid, p_result_json jsonb, p_result_hash text, p_input_tokens bigint, p_output_tokens bigint, p_latency_ms integer, p_http_status integer, p_estimated_cost_usd numeric, p_cache_ttl_seconds integer DEFAULT 0, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v record;
  v_cache_id uuid;
  v_expires timestamptz;
  v_joined record;
begin
  select * into v from public.ai_provider_governed_requests where id=p_request_id for update;
  if not found then raise exception 'AI_PROVIDER_GOVERNED_REQUEST_NOT_FOUND'; end if;
  if v.status='completed' then return jsonb_build_object('ok',true,'alreadyCompleted',true,'requestId',v.id); end if;
  if v.decision<>'EXECUTE_NEW' then raise exception 'AI_PROVIDER_REQUEST_NOT_EXECUTABLE:%',v.decision; end if;

  perform public.ai_provider_reconcile_runtime_budget(
    v.reservation_id,v.lease_id,
    greatest(1,coalesce(nullif(p_metadata->>'actualRequestCount','')::integer,1)),
    greatest(0,coalesce(nullif(p_metadata->>'actualGroundedRequestCount','')::integer,0)),
    greatest(0,coalesce(p_input_tokens,0)),greatest(0,coalesce(p_output_tokens,0)),p_latency_ms,coalesce(p_http_status,200),
    'completed',null,greatest(0,coalesce(p_estimated_cost_usd,0)),coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('governedRequestId',v.id,'decision',v.decision)
  );

  -- Cache authority is fixed by ai_provider_begin_governed_request after applying
  -- the command policy. The caller cannot extend the governed TTL during completion.
  v_expires:=case when v.cache_expires_at is not null and v.cache_expires_at>now() then v.cache_expires_at else null end;
  update public.ai_provider_governed_requests set
    status='completed',actual_input_tokens=greatest(0,coalesce(p_input_tokens,0)),actual_output_tokens=greatest(0,coalesce(p_output_tokens,0)),
    actual_cost_usd=greatest(0,coalesce(p_estimated_cost_usd,0)),result_json=p_result_json,result_hash=p_result_hash,
    cache_expires_at=v_expires,completed_at=now(),metadata=metadata||coalesce(p_metadata,'{}'::jsonb),updated_at=now()
  where id=v.id;

  if v_expires is not null and p_result_json is not null then
    insert into public.ai_provider_structured_result_cache(
      request_fingerprint,module_key,workspace_key,capability,command_code,prompt_version,source_revision,provider_type,model_code,
      result_json,result_hash,validation_status,source_request_id,original_input_tokens,original_output_tokens,original_cost_usd,expires_at,metadata
    ) values (
      v.request_fingerprint,v.module_key,v.workspace_key,v.capability,v.command_code,v.prompt_version,v.source_revision,v.provider_type,v.model_code,
      p_result_json,p_result_hash,'validated',v.id,greatest(0,coalesce(p_input_tokens,0)),greatest(0,coalesce(p_output_tokens,0)),greatest(0,coalesce(p_estimated_cost_usd,0)),v_expires,coalesce(p_metadata,'{}'::jsonb)
    )
    on conflict (request_fingerprint) do update set
      result_json=excluded.result_json,result_hash=excluded.result_hash,validation_status='validated',source_request_id=excluded.source_request_id,
      original_input_tokens=excluded.original_input_tokens,original_output_tokens=excluded.original_output_tokens,original_cost_usd=excluded.original_cost_usd,
      expires_at=excluded.expires_at,invalidated_at=null,invalidation_reason=null,metadata=excluded.metadata,updated_at=now()
    returning id into v_cache_id;
  end if;

  for v_joined in select * from public.ai_provider_governed_requests where source_request_id=v.id and decision='JOIN_IN_FLIGHT' and status='joined' for update
  loop
    update public.ai_provider_governed_requests set
      status='completed',provider_type=v.provider_type,model_code=v.model_code,result_json=p_result_json,result_hash=p_result_hash,
      cache_expires_at=v_expires,completed_at=now(),updated_at=now()
    where id=v_joined.id;
  end loop;

  if v.schedule_id is not null then
    update public.ai_provider_command_schedules set last_completed_at=now(),failure_count=0,updated_at=now() where id=v.schedule_id;
  end if;

  return jsonb_build_object('ok',true,'requestId',v.id,'cacheId',v_cache_id,'cacheExpiresAt',v_expires);
end;
$$;


--
-- Name: ai_provider_fail_governed_request(uuid, integer, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_fail_governed_request(p_request_id uuid, p_http_status integer, p_error_code text, p_error_message text, p_latency_ms integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v record;
begin
  select * into v from public.ai_provider_governed_requests where id=p_request_id for update;
  if not found then return jsonb_build_object('ok',false,'reason','REQUEST_NOT_FOUND'); end if;
  if v.reservation_id is not null then
    perform public.ai_provider_fail_runtime_budget(v.reservation_id,v.lease_id,p_http_status,p_error_code,p_latency_ms,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('governedRequestId',v.id));
  end if;
  update public.ai_provider_governed_requests set status='failed',error_code=p_error_code,error_message=left(coalesce(p_error_message,''),2000),completed_at=now(),metadata=metadata||coalesce(p_metadata,'{}'::jsonb),updated_at=now() where id=v.id;
  update public.ai_provider_governed_requests set status='failed',error_code='SOURCE_REQUEST_FAILED',error_message=left(coalesce(p_error_message,''),2000),completed_at=now(),updated_at=now() where source_request_id=v.id and status='joined';
  if v.schedule_id is not null then
    update public.ai_provider_command_schedules set
      failure_count=failure_count+1,
      status=case when failure_count+1>=greatest(1,coalesce(nullif(failure_policy->>'suspendAfterFailures','')::integer,3)) then 'suspended' else status end,
      updated_at=now()
    where id=v.schedule_id;
  end if;
  return jsonb_build_object('ok',true,'requestId',v.id);
end;
$$;


--
-- Name: ai_provider_fail_runtime_budget(uuid, uuid, integer, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_fail_runtime_budget(p_reservation_id uuid, p_lease_id uuid, p_http_status integer, p_error_code text, p_latency_ms integer, p_metadata jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v record; v_cooldown_minutes integer:=0;
begin
  select * into v from public.ai_provider_budget_reservations where id=p_reservation_id for update;
  if not found then return; end if;
  insert into public.ai_provider_usage_ledger(
    module_key,capability,dossier_id,capacity_pool_id,credential_id,reservation_id,model_code,
    request_count,grounded_request_count,input_tokens,output_tokens,latency_ms,http_status,
    outcome,error_code,actor_id,mission_id,command_code,metadata
  ) values (
    v.module_key,v.capability,v.dossier_id,v.capacity_pool_id,v.credential_id,v.id,v.model_code,
    1,case when v.grounded then 1 else 0 end,0,0,p_latency_ms,p_http_status,
    'failed',p_error_code,v.actor_id,v.mission_id,v.command_code,coalesce(p_metadata,'{}'::jsonb)
  );
  update public.ai_provider_budget_reservations set status='failed',updated_at=now() where id=v.id;
  update public.ai_provider_runtime_leases set status='failed',released_at=now() where id=p_lease_id;
  update public.ai_provider_credentials set last_failure_at=now(),failure_code=p_error_code,updated_at=now() where id=v.credential_id;
  if p_http_status=429 then v_cooldown_minutes:=30;
  elsif p_http_status in (401,403) then v_cooldown_minutes:=120;
  elsif p_http_status>=500 then v_cooldown_minutes:=5;
  end if;
  if v_cooldown_minutes>0 then
    insert into public.ai_provider_cooldowns(capacity_pool_id,credential_id,reason,error_code,ends_at)
    values(v.capacity_pool_id,v.credential_id,'Automatic provider cooldown',p_error_code,now()+make_interval(mins=>v_cooldown_minutes));
  end if;
end;
$$;


--
-- Name: ai_provider_invalidate_structured_cache(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_invalidate_structured_cache(p_request_fingerprint text, p_reason text, p_actor_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
  update public.ai_provider_structured_result_cache set validation_status='invalidated',invalidated_at=now(),invalidation_reason=left(coalesce(p_reason,'Manual invalidation'),500),updated_at=now()
  where request_fingerprint=p_request_fingerprint and invalidated_at is null;
  get diagnostics v_count=row_count;
  insert into public.ai_provider_audit(action_key,entity_type,entity_id,actor_id,actor_name,payload)
  values('invalidate_cache','structured_result_cache',null,p_actor_id,p_actor_id,jsonb_build_object('fingerprint',p_request_fingerprint,'reason',p_reason,'rows',v_count));
  return v_count;
end;
$$;


--
-- Name: ai_provider_preflight_governed_request(text, text, text, text, text, text, text, text, text, integer, bigint, bigint, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_preflight_governed_request(p_module_key text, p_workspace_key text, p_capability text, p_command_code text, p_requested_model text, p_request_fingerprint text, p_trigger_type text DEFAULT 'manual'::text, p_schedule_key text DEFAULT NULL::text, p_actor_id text DEFAULT NULL::text, p_estimated_requests integer DEFAULT 1, p_estimated_input_tokens bigint DEFAULT 0, p_estimated_output_tokens bigint DEFAULT 0, p_estimated_cost_usd numeric DEFAULT 0, p_force_refresh boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_route record;
  v_policy record;
  v_cache record;
  v_inflight record;
  v_schedule record;
  v_schedule_json jsonb := null;
  v_day_start timestamptz := date_trunc('day', now());
  v_week_start timestamptz := date_trunc('week', now());
  v_day_requests bigint := 0;
  v_week_requests bigint := 0;
  v_day_cost numeric := 0;
  v_week_cost numeric := 0;
  v_day_input bigint := 0;
  v_week_input bigint := 0;
  v_day_output bigint := 0;
  v_week_output bigint := 0;
  v_quota record;
  v_command_day_runs bigint := 0;
  v_command_week_runs bigint := 0;
  v_command_day_cost numeric := 0;
  v_command_week_cost numeric := 0;
  v_last_command_completed timestamptz;
  v_decision text := 'EXECUTE_NEW';
  v_reason text;
begin
  select * into v_route
  from public.ai_provider_resolve_runtime_provider(p_module_key,p_capability,p_requested_model)
  limit 1;
  if not found then
    return jsonb_build_object('eligible',false,'decision','BLOCK_POLICY','reason','AI_PROVIDER_ROUTE_NOT_FOUND');
  end if;

  select * into v_policy
  from public.ai_provider_command_policies p
  where p.enabled=true
    and p.module_key in (p_module_key,'*')
    and p.workspace_key in (coalesce(nullif(p_workspace_key,''),'*'),'*')
    and (p.command_code=p_command_code or (right(p.command_code,1)='*' and p_command_code like left(p.command_code,length(p.command_code)-1)||'%') or p.command_code='*')
  order by (p.module_key=p_module_key) desc,(p.workspace_key=p_workspace_key) desc,(p.command_code=p_command_code) desc,length(p.command_code) desc
  limit 1;

  if found then
    if v_policy.ai_mode='ai_prohibited' or not v_policy.enabled then
      v_decision:='BLOCK_POLICY'; v_reason:='AI_COMMAND_PROHIBITED';
    elsif p_trigger_type='scheduled' and not v_policy.scheduled_allowed then
      v_decision:='BLOCK_POLICY'; v_reason:='SCHEDULED_TRIGGER_NOT_ALLOWED';
    elsif p_trigger_type<>'scheduled' and not v_policy.manual_allowed then
      v_decision:='BLOCK_POLICY'; v_reason:='MANUAL_TRIGGER_NOT_ALLOWED';
    elsif cardinality(v_policy.allowed_trigger_types)>0 and not (p_trigger_type=any(v_policy.allowed_trigger_types)) then
      v_decision:='BLOCK_POLICY'; v_reason:='TRIGGER_TYPE_NOT_ALLOWED';
    elsif p_force_refresh and not v_policy.force_refresh_allowed then
      v_decision:='BLOCK_POLICY'; v_reason:='FORCE_REFRESH_NOT_ALLOWED';
    end if;
  end if;

  if p_trigger_type='scheduled' then
    select * into v_schedule from public.ai_provider_command_schedules
    where schedule_key=p_schedule_key and module_key=p_module_key and command_code=p_command_code
    limit 1;
    if not found or not v_schedule.enabled or v_schedule.status<>'active' then
      v_decision:='DEFER_SCHEDULE'; v_reason:='SCHEDULE_NOT_ACTIVE';
    elsif v_schedule.next_run_at is not null and v_schedule.next_run_at>now() then
      v_decision:='DEFER_SCHEDULE'; v_reason:='SCHEDULE_NOT_DUE';
    elsif v_schedule.freshness_seconds>0 and v_schedule.last_completed_at is not null
      and v_schedule.last_completed_at>now()-make_interval(secs=>v_schedule.freshness_seconds) then
      v_decision:='DEFER_SCHEDULE'; v_reason:='SCHEDULE_RESULT_STILL_FRESH';
    else
      v_schedule_json:=to_jsonb(v_schedule);
    end if;
  end if;

  if not p_force_refresh and (v_policy.id is null or v_policy.cache_mode<>'no_cache') then
    select * into v_cache
    from public.ai_provider_structured_result_cache
    where request_fingerprint=p_request_fingerprint
      and validation_status='validated'
      and invalidated_at is null
      and (expires_at is null or expires_at>now())
    limit 1;
    if found then v_decision:='REUSE_CACHED'; v_reason:='VALID_STRUCTURED_RESULT_AVAILABLE'; end if;
  end if;

  if v_decision='EXECUTE_NEW' then
    select * into v_inflight
    from public.ai_provider_governed_requests
    where request_fingerprint=p_request_fingerprint and status in ('queued','running')
    order by created_at desc limit 1;
    if found then v_decision:='JOIN_IN_FLIGHT'; v_reason:='EQUIVALENT_REQUEST_ALREADY_RUNNING'; end if;
  end if;

  select
    coalesce(sum(request_count) filter(where occurred_at>=v_day_start),0),
    coalesce(sum(request_count) filter(where occurred_at>=v_week_start),0),
    coalesce(sum(estimated_cost_usd) filter(where occurred_at>=v_day_start),0),
    coalesce(sum(estimated_cost_usd) filter(where occurred_at>=v_week_start),0),
    coalesce(sum(input_tokens) filter(where occurred_at>=v_day_start),0),
    coalesce(sum(input_tokens) filter(where occurred_at>=v_week_start),0),
    coalesce(sum(output_tokens) filter(where occurred_at>=v_day_start),0),
    coalesce(sum(output_tokens) filter(where occurred_at>=v_week_start),0)
  into v_day_requests,v_week_requests,v_day_cost,v_week_cost,v_day_input,v_week_input,v_day_output,v_week_output
  from public.ai_provider_usage_ledger
  where module_key=p_module_key;

  select
    v_day_requests+coalesce(sum(reserved_requests) filter(where created_at>=v_day_start),0),
    v_week_requests+coalesce(sum(reserved_requests) filter(where created_at>=v_week_start),0),
    v_day_cost+coalesce(sum(reserved_cost_usd) filter(where created_at>=v_day_start),0),
    v_week_cost+coalesce(sum(reserved_cost_usd) filter(where created_at>=v_week_start),0),
    v_day_input+coalesce(sum(reserved_input_tokens) filter(where created_at>=v_day_start),0),
    v_week_input+coalesce(sum(reserved_input_tokens) filter(where created_at>=v_week_start),0),
    v_day_output+coalesce(sum(reserved_output_tokens) filter(where created_at>=v_day_start),0),
    v_week_output+coalesce(sum(reserved_output_tokens) filter(where created_at>=v_week_start),0)
  into v_day_requests,v_week_requests,v_day_cost,v_week_cost,v_day_input,v_week_input,v_day_output,v_week_output
  from public.ai_provider_budget_reservations
  where module_key=p_module_key and status in ('reserved','running');

  if v_decision='EXECUTE_NEW' then
    select * into v_quota from public.ai_provider_quota_policies
    where enabled=true and scope_type='module' and scope_key=p_module_key limit 1;
    if found and v_quota.hard_limit then
      if v_quota.max_requests_per_day is not null and v_day_requests+greatest(1,p_estimated_requests)>v_quota.max_requests_per_day then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_DAILY_REQUEST_BUDGET'; end if;
      if v_quota.max_requests_per_week is not null and v_week_requests+greatest(1,p_estimated_requests)>v_quota.max_requests_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_WEEKLY_REQUEST_BUDGET'; end if;
      if v_quota.max_input_tokens_per_day is not null and v_day_input+greatest(0,p_estimated_input_tokens)>v_quota.max_input_tokens_per_day then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_DAILY_INPUT_TOKEN_BUDGET'; end if;
      if v_quota.max_input_tokens_per_week is not null and v_week_input+greatest(0,p_estimated_input_tokens)>v_quota.max_input_tokens_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_WEEKLY_INPUT_TOKEN_BUDGET'; end if;
      if v_quota.max_output_tokens_per_day is not null and v_day_output+greatest(0,p_estimated_output_tokens)>v_quota.max_output_tokens_per_day then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_DAILY_OUTPUT_TOKEN_BUDGET'; end if;
      if v_quota.max_output_tokens_per_week is not null and v_week_output+greatest(0,p_estimated_output_tokens)>v_quota.max_output_tokens_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_WEEKLY_OUTPUT_TOKEN_BUDGET'; end if;
      if v_quota.max_total_tokens_per_week is not null and v_week_input+v_week_output+greatest(0,p_estimated_input_tokens)+greatest(0,p_estimated_output_tokens)>v_quota.max_total_tokens_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_WEEKLY_TOTAL_TOKEN_BUDGET'; end if;
      if v_quota.max_estimated_cost_usd_per_day is not null and v_day_cost+greatest(0,p_estimated_cost_usd)>v_quota.max_estimated_cost_usd_per_day then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_DAILY_COST_BUDGET'; end if;
      if v_quota.max_estimated_cost_usd_per_week is not null and v_week_cost+greatest(0,p_estimated_cost_usd)>v_quota.max_estimated_cost_usd_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='MODULE_WEEKLY_COST_BUDGET'; end if;
    end if;
  end if;

  if v_decision='EXECUTE_NEW' and v_policy.id is not null then
    select
      count(*) filter(where created_at>=v_day_start),
      count(*) filter(where created_at>=v_week_start),
      coalesce(sum(case when status='running' then estimated_cost_usd else actual_cost_usd end) filter(where created_at>=v_day_start),0),
      coalesce(sum(case when status='running' then estimated_cost_usd else actual_cost_usd end) filter(where created_at>=v_week_start),0),
      max(completed_at) filter(where status='completed')
    into v_command_day_runs,v_command_week_runs,v_command_day_cost,v_command_week_cost,v_last_command_completed
    from public.ai_provider_governed_requests
    where module_key=p_module_key and command_code=p_command_code and decision='EXECUTE_NEW' and status in ('running','completed');
    if v_policy.max_runs_per_day is not null and v_command_day_runs+1>v_policy.max_runs_per_day then v_decision:='BLOCK_QUOTA'; v_reason:='COMMAND_DAILY_RUN_LIMIT'; end if;
    if v_policy.max_runs_per_week is not null and v_command_week_runs+1>v_policy.max_runs_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='COMMAND_WEEKLY_RUN_LIMIT'; end if;
    if v_policy.max_cost_usd_per_day is not null and v_command_day_cost+greatest(0,p_estimated_cost_usd)>v_policy.max_cost_usd_per_day then v_decision:='BLOCK_QUOTA'; v_reason:='COMMAND_DAILY_COST_LIMIT'; end if;
    if v_policy.max_cost_usd_per_week is not null and v_command_week_cost+greatest(0,p_estimated_cost_usd)>v_policy.max_cost_usd_per_week then v_decision:='BLOCK_QUOTA'; v_reason:='COMMAND_WEEKLY_COST_LIMIT'; end if;
    if v_policy.minimum_interval_seconds>0 and v_last_command_completed is not null and v_last_command_completed>now()-make_interval(secs=>v_policy.minimum_interval_seconds) then v_decision:='BLOCK_DUPLICATE'; v_reason:='COMMAND_MINIMUM_INTERVAL'; end if;
    if v_decision='EXECUTE_NEW' and coalesce(nullif(v_policy.approval_class,''),'none')<>'none' then v_decision:='REQUIRE_APPROVAL'; v_reason:='APPROVAL_REQUIRED'; end if;
  end if;

  return jsonb_build_object(
    'eligible',v_decision in ('EXECUTE_NEW','REUSE_CACHED','JOIN_IN_FLIGHT'),
    'decision',v_decision,'reason',v_reason,
    'moduleKey',p_module_key,'workspaceKey',p_workspace_key,'commandCode',p_command_code,
    'providerType',v_route.provider_type,'model',v_route.model_code,'assignmentMode',v_route.assignment_mode,
    'estimatedRequests',greatest(1,p_estimated_requests),
    'estimatedInputTokens',greatest(0,p_estimated_input_tokens),
    'estimatedOutputTokens',greatest(0,p_estimated_output_tokens),
    'estimatedCostUsd',greatest(0,p_estimated_cost_usd),
    'usage',jsonb_build_object(
      'dayRequests',v_day_requests,'weekRequests',v_week_requests,
      'dayInputTokens',v_day_input,'weekInputTokens',v_week_input,
      'dayOutputTokens',v_day_output,'weekOutputTokens',v_week_output,
      'dayCostUsd',v_day_cost,'weekCostUsd',v_week_cost
    ),
    'quota',case when v_quota.id is null then null else to_jsonb(v_quota) end,
    'policy',case when v_policy.id is null then null else to_jsonb(v_policy) end,
    'schedule',v_schedule_json,
    'cache',case when v_cache.id is null then null else jsonb_build_object('id',v_cache.id,'expiresAt',v_cache.expires_at,'reuseCount',v_cache.reuse_count) end,
    'inFlightRequestId',v_inflight.id
  );
exception when others then
  return jsonb_build_object('eligible',false,'decision','BLOCK_POLICY','reason',sqlerrm);
end;
$$;


--
-- Name: ai_provider_reconcile_runtime_budget(uuid, uuid, integer, integer, bigint, bigint, integer, integer, text, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_reconcile_runtime_budget(p_reservation_id uuid, p_lease_id uuid, p_request_count integer, p_grounded_request_count integer, p_input_tokens bigint, p_output_tokens bigint, p_latency_ms integer, p_http_status integer, p_outcome text, p_error_code text, p_estimated_cost_usd numeric, p_metadata jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v record;
begin
  select * into v from public.ai_provider_budget_reservations where id=p_reservation_id for update;
  if not found then raise exception 'RESERVATION_NOT_FOUND'; end if;
  insert into public.ai_provider_usage_ledger(
    module_key,capability,dossier_id,capacity_pool_id,credential_id,reservation_id,model_code,
    request_count,grounded_request_count,input_tokens,output_tokens,latency_ms,http_status,
    outcome,error_code,estimated_cost_usd,actor_id,mission_id,command_code,metadata
  ) values (
    v.module_key,v.capability,v.dossier_id,v.capacity_pool_id,v.credential_id,v.id,v.model_code,
    greatest(1,coalesce(p_request_count,1)),greatest(0,coalesce(p_grounded_request_count,0)),
    greatest(0,coalesce(p_input_tokens,0)),greatest(0,coalesce(p_output_tokens,0)),p_latency_ms,p_http_status,
    coalesce(nullif(p_outcome,''),'completed'),p_error_code,coalesce(p_estimated_cost_usd,0),
    v.actor_id,v.mission_id,v.command_code,coalesce(p_metadata,'{}'::jsonb)
  );
  update public.ai_provider_budget_reservations set status='consumed',updated_at=now() where id=v.id;
  update public.ai_provider_runtime_leases set status='released',released_at=now() where id=p_lease_id;
  update public.ai_provider_credentials set last_success_at=now(),failure_code=null,updated_at=now() where id=v.credential_id and coalesce(p_http_status,200)<400;
end;
$$;


--
-- Name: ai_provider_resolve_runtime_provider(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_resolve_runtime_provider(p_module_key text, p_capability text, p_requested_model text DEFAULT NULL::text) RETURNS TABLE(assignment_id uuid, assignment_mode text, dossier_id uuid, provider_type text, capacity_pool_id uuid, credential_id uuid, model_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_global_mode text;
  v_module_mode text;
  v_rule_id uuid;
  v_routing_mode text;
  v_primary_assignment_id uuid;
  v_fallback_assignment_ids uuid[] := '{}'::uuid[];
begin
  select mode into v_global_mode from public.ai_provider_emergency_state where scope_key='*';
  select mode into v_module_mode from public.ai_provider_emergency_state where scope_key=p_module_key;
  if coalesce(v_global_mode,'normal') in ('paused','draining')
     or coalesce(v_module_mode,'normal') in ('paused','draining') then
    raise exception 'AI_PROVIDER_GLOBAL_PAUSED';
  end if;

  select r.id, r.routing_mode, r.primary_assignment_id, r.fallback_assignment_ids
    into v_rule_id, v_routing_mode, v_primary_assignment_id, v_fallback_assignment_ids
  from public.ai_provider_routing_rules r
  where r.module_key=p_module_key
    and r.enabled=true
    and r.capability in (p_capability,'*')
  order by (r.capability=p_capability) desc, r.updated_at desc
  limit 1;

  return query
  select
    a.id,
    a.assignment_mode,
    d.id,
    d.provider_type,
    coalesce(a.capacity_pool_id, cp.id),
    c.id,
    coalesce(
      nullif(a.primary_model,''),
      nullif(p_requested_model,''),
      (select m.model_code from public.ai_provider_models m
       where m.dossier_id=d.id and m.enabled=true
         and (m.capability=p_capability or m.capability='general')
       order by (m.capability=p_capability) desc, m.primary_for_capability desc, m.created_at
       limit 1),
      'gemini-2.5-flash'
    )
  from public.ai_provider_module_assignments a
  join public.ai_provider_dossiers d on d.id=a.dossier_id
  join lateral (
    select p.* from public.ai_provider_capacity_pools p
    where p.dossier_id=d.id
      and (a.capacity_pool_id is null or p.id=a.capacity_pool_id)
      and p.status in ('ready','operating','limited','draft')
    order by (p.id=a.capacity_pool_id) desc, p.created_at
    limit 1
  ) cp on true
  join lateral (
    select cred.* from public.ai_provider_credentials cred
    where cred.dossier_id=d.id
      and (cred.capacity_pool_id is null or cp.id is null or cred.capacity_pool_id=cp.id)
      and cred.status='active'
    order by cred.version_number desc
    limit 1
  ) c on true
  where a.module_key=p_module_key
    and a.enabled=true
    and a.assignment_mode <> 'disabled'
    and d.is_enabled=true
    and d.status in ('ready','operating','limited')
    and (cardinality(a.capability_allowlist)=0 or p_capability=any(a.capability_allowlist) or '*'=any(a.capability_allowlist))
    and (
      v_rule_id is null
      or (v_routing_mode='exclusive' and a.id=v_primary_assignment_id)
      or (v_routing_mode='primary_fallback' and (a.id=v_primary_assignment_id or a.id=any(coalesce(v_fallback_assignment_ids,'{}'::uuid[]))))
      or (v_routing_mode='manual' and a.assignment_mode='manual')
      or v_routing_mode in ('capacity_aware','cost_aware','weighted')
    )
    and not exists(
      select 1 from public.ai_provider_cooldowns cd
      where cd.status='active' and cd.ends_at>now()
        and ((cd.capacity_pool_id is not null and cd.capacity_pool_id=cp.id)
          or (cd.credential_id is not null and cd.credential_id=c.id))
    )
  order by
    case
      when v_primary_assignment_id=a.id then 0
      when a.id=any(coalesce(v_fallback_assignment_ids,'{}'::uuid[])) then 1+coalesce(array_position(v_fallback_assignment_ids,a.id),99)
      else 100
    end,
    case a.assignment_mode when 'primary' then 1 when 'secondary' then 2 when 'failover' then 3 when 'emergency_reserve' then 4 when 'manual' then 5 else 9 end,
    a.priority,
    a.created_at
  limit 1;
end;
$$;


--
-- Name: ai_provider_resolve_secret(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_resolve_secret(p_credential_id uuid) RETURNS TABLE(decrypted_secret text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
  select ds.decrypted_secret
  from public.ai_provider_credentials c
  join vault.decrypted_secrets ds on ds.id = c.vault_secret_id
  where c.id = p_credential_id
    and c.status in ('testing','validated','active','standby')
  limit 1;
$$;


--
-- Name: ai_provider_restore_configuration(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_restore_configuration(p_version_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_snapshot jsonb;
  v_item jsonb;
  v_latest integer;
  v_code text;
  v_checksum text;
begin
  perform pg_advisory_xact_lock(hashtextextended('ai_provider:configuration',0));
  select snapshot into v_snapshot
  from public.ai_provider_config_versions
  where id=p_version_id;
  if not found then raise exception 'CONFIG_VERSION_NOT_FOUND'; end if;

  -- Safe deactivation first: objects created after the selected version remain
  -- preserved but cannot route new production requests until explicitly reviewed.
  update public.ai_provider_module_assignments set enabled=false,updated_at=now(),updated_by=p_actor_id;
  update public.ai_provider_routing_rules set enabled=false,updated_at=now(),updated_by=p_actor_id;
  update public.ai_provider_quota_policies set enabled=false,updated_at=now(),updated_by=p_actor_id;
  update public.ai_provider_models set enabled=false,updated_at=now();
  update public.ai_provider_dossiers set is_enabled=false,status=case when status='archived' then status else 'suspended' end,updated_at=now(),updated_by=p_actor_id;
  update public.ai_provider_credentials set status='standby',updated_at=now() where status='active';

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'dossiers','[]'::jsonb)) loop
    update public.ai_provider_dossiers set
      name=coalesce(v_item->>'name',name),
      provider_type=coalesce(v_item->>'provider_type',provider_type),
      status=coalesce(v_item->>'status',status),
      environment=coalesce(v_item->>'environment',environment),
      account_label=v_item->>'account_label',
      external_account_id=v_item->>'external_account_id',
      billing_tier=coalesce(v_item->>'billing_tier',billing_tier),
      reconciliation_state=coalesce(v_item->>'reconciliation_state',reconciliation_state),
      is_enabled=coalesce((v_item->>'is_enabled')::boolean,false),
      metadata=coalesce(v_item->'metadata',metadata),
      updated_by=p_actor_id,updated_at=now()
    where id=(v_item->>'id')::uuid;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'pools','[]'::jsonb)) loop
    update public.ai_provider_capacity_pools set
      project_name=coalesce(v_item->>'project_name',project_name),
      external_project_id=v_item->>'external_project_id',
      quota_scope=coalesce(v_item->>'quota_scope',quota_scope),
      provider_rpm=nullif(v_item->>'provider_rpm','')::integer,
      provider_tpm=nullif(v_item->>'provider_tpm','')::bigint,
      provider_rpd=nullif(v_item->>'provider_rpd','')::integer,
      provider_grounded_rpd=nullif(v_item->>'provider_grounded_rpd','')::integer,
      billing_tier=coalesce(v_item->>'billing_tier',billing_tier),
      status=coalesce(v_item->>'status',status),
      metadata=coalesce(v_item->'metadata',metadata),
      updated_by=p_actor_id,updated_at=now()
    where id=(v_item->>'id')::uuid;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'credentials','[]'::jsonb)) loop
    update public.ai_provider_credentials set
      status=coalesce(v_item->>'status',status),updated_at=now()
    where id=(v_item->>'id')::uuid;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'models','[]'::jsonb)) loop
    insert into public.ai_provider_models(
      dossier_id,model_code,display_name,capability,enabled,primary_for_capability,
      grounding_allowed,max_output_tokens,metadata,updated_at
    ) values (
      (v_item->>'dossier_id')::uuid,v_item->>'model_code',v_item->>'display_name',
      coalesce(v_item->>'capability','general'),coalesce((v_item->>'enabled')::boolean,false),
      coalesce((v_item->>'primary_for_capability')::boolean,false),
      coalesce((v_item->>'grounding_allowed')::boolean,false),
      nullif(v_item->>'max_output_tokens','')::integer,coalesce(v_item->'metadata','{}'::jsonb),now()
    )
    on conflict(dossier_id,model_code,capability) do update set
      display_name=excluded.display_name,enabled=excluded.enabled,
      primary_for_capability=excluded.primary_for_capability,
      grounding_allowed=excluded.grounding_allowed,max_output_tokens=excluded.max_output_tokens,
      metadata=excluded.metadata,updated_at=now();
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'assignments','[]'::jsonb)) loop
    insert into public.ai_provider_module_assignments(
      module_key,dossier_id,capacity_pool_id,assignment_mode,priority,enabled,
      capability_allowlist,primary_model,fallback_model,metadata,updated_by,updated_at
    ) values (
      v_item->>'module_key',(v_item->>'dossier_id')::uuid,nullif(v_item->>'capacity_pool_id','')::uuid,
      v_item->>'assignment_mode',coalesce((v_item->>'priority')::integer,100),
      coalesce((v_item->>'enabled')::boolean,false),
      array(select jsonb_array_elements_text(coalesce(v_item->'capability_allowlist','[]'::jsonb))),
      v_item->>'primary_model',v_item->>'fallback_model',coalesce(v_item->'metadata','{}'::jsonb),p_actor_id,now()
    )
    on conflict(module_key,dossier_id,assignment_mode) do update set
      capacity_pool_id=excluded.capacity_pool_id,priority=excluded.priority,enabled=excluded.enabled,
      capability_allowlist=excluded.capability_allowlist,primary_model=excluded.primary_model,
      fallback_model=excluded.fallback_model,metadata=excluded.metadata,updated_by=p_actor_id,updated_at=now();
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'routingRules','[]'::jsonb)) loop
    insert into public.ai_provider_routing_rules(
      module_key,capability,routing_mode,primary_assignment_id,fallback_assignment_ids,
      sticky_mission,enabled,metadata,updated_by,updated_at
    ) values (
      v_item->>'module_key',coalesce(v_item->>'capability','*'),
      coalesce(v_item->>'routing_mode','primary_fallback'),
      nullif(v_item->>'primary_assignment_id','')::uuid,
      array(select jsonb_array_elements_text(coalesce(v_item->'fallback_assignment_ids','[]'::jsonb)))::uuid[],
      coalesce((v_item->>'sticky_mission')::boolean,true),coalesce((v_item->>'enabled')::boolean,false),
      coalesce(v_item->'metadata','{}'::jsonb),p_actor_id,now()
    )
    on conflict(module_key,capability) do update set
      routing_mode=excluded.routing_mode,primary_assignment_id=excluded.primary_assignment_id,
      fallback_assignment_ids=excluded.fallback_assignment_ids,sticky_mission=excluded.sticky_mission,
      enabled=excluded.enabled,metadata=excluded.metadata,updated_by=p_actor_id,updated_at=now();
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'quotas','[]'::jsonb)) loop
    insert into public.ai_provider_quota_policies(
      scope_type,scope_key,max_requests_per_minute,max_requests_per_hour,max_requests_per_day,
      max_requests_per_month,max_input_tokens_per_day,max_output_tokens_per_day,
      max_grounded_requests_per_day,max_concurrent_requests,emergency_reserve_requests,
      soft_threshold_percent,hard_limit,reset_timezone,enabled,metadata,updated_by,updated_at
    ) values (
      v_item->>'scope_type',v_item->>'scope_key',nullif(v_item->>'max_requests_per_minute','')::integer,
      nullif(v_item->>'max_requests_per_hour','')::integer,nullif(v_item->>'max_requests_per_day','')::integer,
      nullif(v_item->>'max_requests_per_month','')::integer,nullif(v_item->>'max_input_tokens_per_day','')::bigint,
      nullif(v_item->>'max_output_tokens_per_day','')::bigint,nullif(v_item->>'max_grounded_requests_per_day','')::integer,
      nullif(v_item->>'max_concurrent_requests','')::integer,coalesce((v_item->>'emergency_reserve_requests')::integer,0),
      coalesce((v_item->>'soft_threshold_percent')::integer,80),coalesce((v_item->>'hard_limit')::boolean,true),
      coalesce(v_item->>'reset_timezone','Africa/Casablanca'),coalesce((v_item->>'enabled')::boolean,false),
      coalesce(v_item->'metadata','{}'::jsonb),p_actor_id,now()
    )
    on conflict(scope_type,scope_key) do update set
      max_requests_per_minute=excluded.max_requests_per_minute,max_requests_per_hour=excluded.max_requests_per_hour,
      max_requests_per_day=excluded.max_requests_per_day,max_requests_per_month=excluded.max_requests_per_month,
      max_input_tokens_per_day=excluded.max_input_tokens_per_day,max_output_tokens_per_day=excluded.max_output_tokens_per_day,
      max_grounded_requests_per_day=excluded.max_grounded_requests_per_day,max_concurrent_requests=excluded.max_concurrent_requests,
      emergency_reserve_requests=excluded.emergency_reserve_requests,soft_threshold_percent=excluded.soft_threshold_percent,
      hard_limit=excluded.hard_limit,reset_timezone=excluded.reset_timezone,enabled=excluded.enabled,
      metadata=excluded.metadata,updated_by=p_actor_id,updated_at=now();
  end loop;

  if v_snapshot->'emergency' is not null and jsonb_typeof(v_snapshot->'emergency')='object' then
    insert into public.ai_provider_emergency_state(scope_key,mode,reason,updated_by,updated_at)
    values(
      coalesce(v_snapshot#>>'{emergency,scope_key}','*'),
      coalesce(v_snapshot#>>'{emergency,mode}','normal'),
      v_snapshot#>>'{emergency,reason}',p_actor_id,now()
    )
    on conflict(scope_key) do update set mode=excluded.mode,reason=excluded.reason,updated_by=p_actor_id,updated_at=now();
  end if;

  select coalesce(max(version_number),0)+1 into v_latest from public.ai_provider_config_versions;
  v_code := 'AI-PROVIDER-V'||lpad(v_latest::text,4,'0');
  v_checksum := encode(digest(v_snapshot::text,'sha256'),'hex');
  insert into public.ai_provider_config_versions(
    version_number,version_code,status,reason,snapshot,checksum,published_at,created_by
  ) values (
    v_latest,v_code,'rollback','Rollback vers '||(select version_code from public.ai_provider_config_versions where id=p_version_id),
    v_snapshot,v_checksum,now(),p_actor_id
  );
  insert into public.ai_provider_audit(action_key,entity_type,entity_id,actor_id,actor_name,payload)
  values('rollback_configuration','config_version',p_version_id::text,p_actor_id,p_actor_id,
    jsonb_build_object('restoredVersionId',p_version_id,'newVersionCode',v_code));

  return jsonb_build_object('restored',true,'sourceVersionId',p_version_id,'publishedVersionCode',v_code);
end;
$$;


--
-- Name: ai_provider_restore_sovereign_configuration(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_restore_sovereign_configuration(p_version_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_snapshot jsonb;
  v_item jsonb;
  v_base jsonb;
begin
  select snapshot into v_snapshot from public.ai_provider_config_versions where id=p_version_id;
  if not found then raise exception 'CONFIG_VERSION_NOT_FOUND'; end if;

  v_base:=public.ai_provider_restore_configuration(p_version_id,p_actor_id);

  update public.ai_provider_command_policies set enabled=false,updated_by=p_actor_id,updated_at=now();
  update public.ai_provider_command_schedules set enabled=false,status='paused',updated_by=p_actor_id,updated_at=now();

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'quotas','[]'::jsonb)) loop
    update public.ai_provider_quota_policies set
      max_requests_per_week=nullif(v_item->>'max_requests_per_week','')::integer,
      max_input_tokens_per_week=nullif(v_item->>'max_input_tokens_per_week','')::bigint,
      max_output_tokens_per_week=nullif(v_item->>'max_output_tokens_per_week','')::bigint,
      max_total_tokens_per_week=nullif(v_item->>'max_total_tokens_per_week','')::bigint,
      max_estimated_cost_usd_per_day=nullif(v_item->>'max_estimated_cost_usd_per_day','')::numeric,
      max_estimated_cost_usd_per_week=nullif(v_item->>'max_estimated_cost_usd_per_week','')::numeric,
      max_estimated_cost_usd_per_month=nullif(v_item->>'max_estimated_cost_usd_per_month','')::numeric,
      updated_by=p_actor_id,updated_at=now()
    where scope_type=v_item->>'scope_type' and scope_key=v_item->>'scope_key';
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'commandPolicies','[]'::jsonb)) loop
    insert into public.ai_provider_command_policies(
      module_key,workspace_key,command_code,ai_mode,manual_allowed,scheduled_allowed,
      minimum_interval_seconds,max_runs_per_day,max_runs_per_week,max_runs_per_month,
      max_input_tokens_per_run,max_output_tokens_per_run,max_cost_usd_per_run,max_cost_usd_per_day,max_cost_usd_per_week,
      max_retries,cache_mode,cache_ttl_seconds,duplicate_window_seconds,force_refresh_allowed,approval_class,
      allowed_provider_types,allowed_models,allowed_trigger_types,execution_window,cooldown_after_failure_seconds,
      consecutive_failure_suspend_threshold,enabled,metadata,updated_by,updated_at
    ) values (
      v_item->>'module_key',coalesce(v_item->>'workspace_key','*'),v_item->>'command_code',coalesce(v_item->>'ai_mode','ai_required'),
      coalesce((v_item->>'manual_allowed')::boolean,true),coalesce((v_item->>'scheduled_allowed')::boolean,false),
      coalesce((v_item->>'minimum_interval_seconds')::integer,0),nullif(v_item->>'max_runs_per_day','')::integer,
      nullif(v_item->>'max_runs_per_week','')::integer,nullif(v_item->>'max_runs_per_month','')::integer,
      nullif(v_item->>'max_input_tokens_per_run','')::bigint,nullif(v_item->>'max_output_tokens_per_run','')::bigint,
      nullif(v_item->>'max_cost_usd_per_run','')::numeric,nullif(v_item->>'max_cost_usd_per_day','')::numeric,
      nullif(v_item->>'max_cost_usd_per_week','')::numeric,coalesce((v_item->>'max_retries')::integer,0),
      coalesce(v_item->>'cache_mode','until_source_changes'),coalesce((v_item->>'cache_ttl_seconds')::integer,21600),
      coalesce((v_item->>'duplicate_window_seconds')::integer,900),coalesce((v_item->>'force_refresh_allowed')::boolean,false),
      coalesce(v_item->>'approval_class','none'),array(select jsonb_array_elements_text(coalesce(v_item->'allowed_provider_types','[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(v_item->'allowed_models','[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(v_item->'allowed_trigger_types','["manual"]'::jsonb))),
      coalesce(v_item->'execution_window','{}'::jsonb),coalesce((v_item->>'cooldown_after_failure_seconds')::integer,300),
      coalesce((v_item->>'consecutive_failure_suspend_threshold')::integer,3),coalesce((v_item->>'enabled')::boolean,false),
      coalesce(v_item->'metadata','{}'::jsonb),p_actor_id,now()
    )
    on conflict(module_key,workspace_key,command_code) do update set
      ai_mode=excluded.ai_mode,manual_allowed=excluded.manual_allowed,scheduled_allowed=excluded.scheduled_allowed,
      minimum_interval_seconds=excluded.minimum_interval_seconds,max_runs_per_day=excluded.max_runs_per_day,
      max_runs_per_week=excluded.max_runs_per_week,max_runs_per_month=excluded.max_runs_per_month,
      max_input_tokens_per_run=excluded.max_input_tokens_per_run,max_output_tokens_per_run=excluded.max_output_tokens_per_run,
      max_cost_usd_per_run=excluded.max_cost_usd_per_run,max_cost_usd_per_day=excluded.max_cost_usd_per_day,
      max_cost_usd_per_week=excluded.max_cost_usd_per_week,max_retries=excluded.max_retries,cache_mode=excluded.cache_mode,
      cache_ttl_seconds=excluded.cache_ttl_seconds,duplicate_window_seconds=excluded.duplicate_window_seconds,
      force_refresh_allowed=excluded.force_refresh_allowed,approval_class=excluded.approval_class,
      allowed_provider_types=excluded.allowed_provider_types,allowed_models=excluded.allowed_models,
      allowed_trigger_types=excluded.allowed_trigger_types,execution_window=excluded.execution_window,
      cooldown_after_failure_seconds=excluded.cooldown_after_failure_seconds,
      consecutive_failure_suspend_threshold=excluded.consecutive_failure_suspend_threshold,enabled=excluded.enabled,
      metadata=excluded.metadata,updated_by=p_actor_id,updated_at=now();
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'schedules','[]'::jsonb)) loop
    insert into public.ai_provider_command_schedules(
      schedule_key,module_key,workspace_key,command_code,schedule_expression,schedule_format,timezone,enabled,status,priority,
      freshness_seconds,duplicate_window_seconds,max_runs_per_day,max_runs_per_week,estimated_input_tokens,
      estimated_output_tokens,estimated_cost_usd,approval_required,provider_policy,dependency_policy,failure_policy,
      next_run_at,metadata,updated_by,updated_at
    ) values (
      v_item->>'schedule_key',v_item->>'module_key',coalesce(v_item->>'workspace_key','*'),v_item->>'command_code',
      v_item->>'schedule_expression',coalesce(v_item->>'schedule_format','cron'),coalesce(v_item->>'timezone','Africa/Casablanca'),
      coalesce((v_item->>'enabled')::boolean,false),coalesce(v_item->>'status','paused'),coalesce((v_item->>'priority')::integer,100),
      coalesce((v_item->>'freshness_seconds')::integer,21600),coalesce((v_item->>'duplicate_window_seconds')::integer,900),
      nullif(v_item->>'max_runs_per_day','')::integer,nullif(v_item->>'max_runs_per_week','')::integer,
      coalesce((v_item->>'estimated_input_tokens')::bigint,0),coalesce((v_item->>'estimated_output_tokens')::bigint,0),
      coalesce((v_item->>'estimated_cost_usd')::numeric,0),coalesce((v_item->>'approval_required')::boolean,false),
      coalesce(v_item->'provider_policy','{}'::jsonb),coalesce(v_item->'dependency_policy','{}'::jsonb),
      coalesce(v_item->'failure_policy','{}'::jsonb),nullif(v_item->>'next_run_at','')::timestamptz,
      coalesce(v_item->'metadata','{}'::jsonb),p_actor_id,now()
    )
    on conflict(schedule_key) do update set
      module_key=excluded.module_key,workspace_key=excluded.workspace_key,command_code=excluded.command_code,
      schedule_expression=excluded.schedule_expression,schedule_format=excluded.schedule_format,timezone=excluded.timezone,
      enabled=excluded.enabled,status=excluded.status,priority=excluded.priority,freshness_seconds=excluded.freshness_seconds,
      duplicate_window_seconds=excluded.duplicate_window_seconds,max_runs_per_day=excluded.max_runs_per_day,
      max_runs_per_week=excluded.max_runs_per_week,estimated_input_tokens=excluded.estimated_input_tokens,
      estimated_output_tokens=excluded.estimated_output_tokens,estimated_cost_usd=excluded.estimated_cost_usd,
      approval_required=excluded.approval_required,provider_policy=excluded.provider_policy,
      dependency_policy=excluded.dependency_policy,failure_policy=excluded.failure_policy,next_run_at=excluded.next_run_at,
      metadata=excluded.metadata,updated_by=p_actor_id,updated_at=now();
  end loop;

  return coalesce(v_base,'{}'::jsonb)||jsonb_build_object('phase5Restored',true,'sourceVersionId',p_version_id);
end;
$$;


--
-- Name: ai_provider_simulate_runtime_route(text, text, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_simulate_runtime_route(p_module_key text, p_capability text, p_requested_model text, p_estimated_requests integer, p_grounded boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_route record; v_day_used bigint; v_policy record;
begin
  select * into v_route from public.ai_provider_resolve_runtime_provider(p_module_key,p_capability,p_requested_model) limit 1;
  if not found then
    return jsonb_build_object('eligible',false,'reason','AI_PROVIDER_ROUTE_NOT_FOUND');
  end if;
  select coalesce(sum(request_count),0) into v_day_used from public.ai_provider_usage_ledger
  where capacity_pool_id=v_route.capacity_pool_id and occurred_at>=date_trunc('day',now());
  select * into v_policy from public.ai_provider_quota_policies
  where enabled=true and ((scope_type='module' and scope_key=p_module_key) or (scope_type='global' and scope_key='*'))
  order by (scope_type='module') desc limit 1;
  if not found then
    return jsonb_build_object(
      'eligible',true,'moduleKey',p_module_key,'capability',p_capability,
      'dossierId',v_route.dossier_id,'capacityPoolId',v_route.capacity_pool_id,
      'credentialId',v_route.credential_id,'model',v_route.model_code,
      'assignmentMode',v_route.assignment_mode,'estimatedRequests',greatest(1,p_estimated_requests),
      'grounded',p_grounded,'requestsUsedToday',v_day_used,
      'internalDailyLimit',null,'wouldFit',true
    );
  end if;
  return jsonb_build_object(
    'eligible',true,
    'moduleKey',p_module_key,
    'capability',p_capability,
    'dossierId',v_route.dossier_id,
    'capacityPoolId',v_route.capacity_pool_id,
    'credentialId',v_route.credential_id,
    'model',v_route.model_code,
    'assignmentMode',v_route.assignment_mode,
    'estimatedRequests',greatest(1,p_estimated_requests),
    'grounded',p_grounded,
    'requestsUsedToday',v_day_used,
    'internalDailyLimit',v_policy.max_requests_per_day,
    'wouldFit',v_policy.max_requests_per_day is null or v_day_used+greatest(1,p_estimated_requests)<=v_policy.max_requests_per_day
  );
end;
$$;


--
-- Name: ai_provider_store_credential(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_provider_store_credential(p_dossier_id uuid, p_capacity_pool_id uuid, p_secret text, p_key_type text, p_actor_id text) RETURNS TABLE(credential_id uuid, version_number integer, fingerprint text, secret_suffix text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'extensions'
    AS $$
declare
  v_version integer;
  v_vault_id uuid;
  v_credential_id uuid;
  v_fingerprint text;
  v_suffix text;
  v_name text;
begin
  if p_secret is null or length(trim(p_secret)) < 12 then
    raise exception 'INVALID_PROVIDER_SECRET';
  end if;
  if not exists(select 1 from public.ai_provider_dossiers where id = p_dossier_id) then
    raise exception 'DOSSIER_NOT_FOUND';
  end if;
  select coalesce(max(c.version_number),0)+1 into v_version
  from public.ai_provider_credentials c where c.dossier_id = p_dossier_id;
  v_fingerprint := encode(digest(p_secret, 'sha256'), 'hex');
  v_suffix := right(p_secret, 4);
  v_name := 'sanila_ai_provider_' || p_dossier_id::text || '_v' || v_version::text;
  select vault.create_secret(p_secret, v_name, 'SANILA AI Provider credential version') into v_vault_id;
  insert into public.ai_provider_credentials(
    dossier_id, capacity_pool_id, vault_secret_id, fingerprint, secret_suffix,
    version_number, key_type, status, created_by
  ) values (
    p_dossier_id, p_capacity_pool_id, v_vault_id, v_fingerprint, v_suffix,
    v_version, coalesce(nullif(p_key_type,''),'auth_key'), 'testing', p_actor_id
  ) returning id into v_credential_id;
  return query select v_credential_id, v_version, v_fingerprint, v_suffix;
end;
$$;


--
-- Name: angelcare360_action_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_action_label(p_action text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_action
    when 'view' then 'Consulter'
    when 'create' then 'Créer'
    when 'update' then 'Modifier'
    when 'delete' then 'Supprimer'
    when 'approve' then 'Valider'
    when 'export' then 'Exporter'
    when 'assign' then 'Affecter'
    when 'notify' then 'Notifier'
    when 'configure' then 'Configurer'
    when 'audit' then 'Auditer'
    else initcap(p_action)
  end;
$$;


--
-- Name: angelcare360_area8_current_actor_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_area8_current_actor_ids() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  resolved_ids text[] := array[]::text[];
  authenticated_id text := nullif(auth.uid()::text, '');
  authenticated_email text :=
    nullif(coalesce(auth.jwt() ->> 'email', ''), '');

  identity_column text;
  mapped_app_user_id text;
  app_users_has_id boolean := false;
begin
  if authenticated_id is not null then
    resolved_ids := array_append(
      resolved_ids,
      authenticated_id
    );
  end if;

  if to_regclass('public.app_users') is not null then
    select exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'app_users'
        and column_name = 'id'
    )
    into app_users_has_id;

    if app_users_has_id then
      for identity_column in
        select column_name
        from information_schema.columns
        where table_schema = 'public'
          and table_name = 'app_users'
          and column_name in (
            'id',
            'auth_user_id',
            'supabase_user_id'
          )
        order by case column_name
          when 'auth_user_id' then 1
          when 'supabase_user_id' then 2
          when 'id' then 3
          else 10
        end
      loop
        mapped_app_user_id := null;

        execute format(
          'select id::text
             from public.app_users
            where %I::text = $1
            limit 1',
          identity_column
        )
        into mapped_app_user_id
        using authenticated_id;

        if mapped_app_user_id is not null then
          resolved_ids := array_append(
            resolved_ids,
            mapped_app_user_id
          );
        end if;
      end loop;

      if authenticated_email is not null then
        for identity_column in
          select column_name
          from information_schema.columns
          where table_schema = 'public'
            and table_name = 'app_users'
            and column_name in (
              'email',
              'username'
            )
          order by case column_name
            when 'email' then 1
            when 'username' then 2
            else 10
          end
        loop
          mapped_app_user_id := null;

          execute format(
            'select id::text
               from public.app_users
              where lower(%I::text) = lower($1)
              limit 1',
            identity_column
          )
          into mapped_app_user_id
          using authenticated_email;

          if mapped_app_user_id is not null then
            resolved_ids := array_append(
              resolved_ids,
              mapped_app_user_id
            );
          end if;
        end loop;
      end if;
    end if;
  end if;

  return coalesce(
    (
      select array_agg(distinct value)
      from unnest(resolved_ids) as value
      where value is not null
        and value <> ''
    ),
    array[]::text[]
  );
end;
$_$;


--
-- Name: angelcare360_area8_has_school_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_area8_has_school_access(target_school_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  actor_ids text[];
  role_user_column text;
  school_column text;
  status_column text;
  starts_column text;
  ends_column text;
  predicate_sql text;
  access_granted boolean := false;
begin
  if auth.uid() is null
     or target_school_id is null then
    return false;
  end if;

  if to_regclass(
    'public.angelcare360_user_roles'
  ) is null then
    return false;
  end if;

  actor_ids :=
    public.angelcare360_area8_current_actor_ids();

  if coalesce(array_length(actor_ids, 1), 0) = 0 then
    return false;
  end if;

  select column_name
  into role_user_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'angelcare360_user_roles'
    and column_name in (
      'app_user_id',
      'user_id',
      'account_user_id',
      'auth_user_id',
      'supabase_user_id'
    )
  order by case column_name
    when 'app_user_id' then 1
    when 'user_id' then 2
    when 'account_user_id' then 3
    when 'auth_user_id' then 4
    when 'supabase_user_id' then 5
    else 10
  end
  limit 1;

  select column_name
  into school_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'angelcare360_user_roles'
    and column_name = 'school_id'
  limit 1;

  if role_user_column is null
     or school_column is null then
    return false;
  end if;

  select column_name
  into status_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'angelcare360_user_roles'
    and column_name in (
      'status',
      'assignment_state',
      'state'
    )
  order by case column_name
    when 'status' then 1
    when 'assignment_state' then 2
    when 'state' then 3
    else 10
  end
  limit 1;

  select column_name
  into starts_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'angelcare360_user_roles'
    and column_name in (
      'starts_at',
      'effective_from',
      'valid_from'
    )
  order by case column_name
    when 'starts_at' then 1
    when 'effective_from' then 2
    when 'valid_from' then 3
    else 10
  end
  limit 1;

  select column_name
  into ends_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'angelcare360_user_roles'
    and column_name in (
      'ends_at',
      'effective_until',
      'valid_until',
      'expires_at'
    )
  order by case column_name
    when 'ends_at' then 1
    when 'effective_until' then 2
    when 'valid_until' then 3
    when 'expires_at' then 4
    else 10
  end
  limit 1;

  predicate_sql := format(
    '%I::text = any($1)
     and %I::text = $2',
    role_user_column,
    school_column
  );

  if status_column is not null then
    predicate_sql :=
      predicate_sql
      || format(
        ' and (
            %I is null
            or lower(%I::text) not in (
              ''inactive'',
              ''disabled'',
              ''revoked'',
              ''ended'',
              ''expired'',
              ''cancelled'',
              ''archived''
            )
          )',
        status_column,
        status_column
      );
  end if;

  if starts_column is not null then
    predicate_sql :=
      predicate_sql
      || format(
        ' and (
            %I is null
            or %I::timestamptz <= now()
          )',
        starts_column,
        starts_column
      );
  end if;

  if ends_column is not null then
    predicate_sql :=
      predicate_sql
      || format(
        ' and (
            %I is null
            or %I::timestamptz > now()
          )',
        ends_column,
        ends_column
      );
  end if;

  execute format(
    'select exists (
       select 1
       from public.angelcare360_user_roles
       where %s
     )',
    predicate_sql
  )
  into access_granted
  using actor_ids, target_school_id::text;

  return coalesce(access_granted, false);
end;
$_$;


