--
-- Name: angelcare360_inventory_apply_movement_v1(uuid, uuid, text, text, numeric, numeric, date, text, uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_inventory_apply_movement_v1(p_school_id uuid, p_item_id uuid, p_movement_code text, p_movement_type text, p_quantity numeric DEFAULT NULL::numeric, p_observed_stock numeric DEFAULT NULL::numeric, p_movement_date date DEFAULT CURRENT_DATE, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_performed_by uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.angelcare360_inventory_items%ROWTYPE;
  v_existing public.angelcare360_inventory_movements%ROWTYPE;
  v_movement public.angelcare360_inventory_movements%ROWTYPE;
  v_type text;
  v_qty numeric;
  v_before numeric;
  v_after numeric;
  v_delta numeric;
  v_status text;
  v_metadata jsonb := coalesce(p_metadata_json,'{}'::jsonb);
  v_source text;
  v_destination text;
BEGIN
  IF p_school_id IS NULL OR p_item_id IS NULL OR nullif(btrim(p_movement_code),'') IS NULL THEN
    RAISE EXCEPTION 'inventory_required_identity_missing';
  END IF;

  SELECT * INTO v_existing FROM public.angelcare360_inventory_movements
   WHERE school_id=p_school_id AND movement_code=p_movement_code LIMIT 1;
  IF FOUND THEN
    SELECT * INTO v_item FROM public.angelcare360_inventory_items WHERE school_id=p_school_id AND id=v_existing.item_id;
    RETURN jsonb_build_object(
      'ok',true,'idempotent',true,'movement',to_jsonb(v_existing),
      'stockBefore',coalesce((v_existing.metadata_json->>'stock_before')::numeric,v_item.current_stock),
      'stockAfter',coalesce((v_existing.metadata_json->>'stock_after')::numeric,v_item.current_stock),
      'stockDelta',coalesce((v_existing.metadata_json->>'stock_delta')::numeric,0)
    );
  END IF;

  SELECT * INTO v_item FROM public.angelcare360_inventory_items
   WHERE school_id=p_school_id AND id=p_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'inventory_item_not_found'; END IF;
  IF v_item.status IN ('inactive','archived') THEN RAISE EXCEPTION 'inventory_item_lifecycle_locked'; END IF;

  v_type := lower(btrim(coalesce(p_movement_type,'')));
  IF v_type='entry' THEN v_type:='in'; END IF;
  IF v_type='exit' THEN v_type:='out'; END IF;
  IF v_type='adjustment' THEN v_type:='adjust'; END IF;
  IF v_type NOT IN ('in','out','adjust','transfer','loss','damage') THEN RAISE EXCEPTION 'inventory_movement_type_invalid'; END IF;

  v_before := coalesce(v_item.current_stock,0);
  IF v_type='adjust' THEN
    IF p_observed_stock IS NULL OR p_observed_stock < 0 THEN RAISE EXCEPTION 'inventory_observed_stock_invalid'; END IF;
    v_after := p_observed_stock;
    v_delta := v_after-v_before;
    v_qty := abs(v_delta);
    IF nullif(btrim(coalesce(p_notes,'')),'') IS NULL THEN RAISE EXCEPTION 'inventory_adjustment_reason_required'; END IF;
  ELSE
    IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'inventory_quantity_invalid'; END IF;
    v_qty := p_quantity;
    IF v_type='in' THEN v_delta:=v_qty;
    ELSIF v_type IN ('out','loss','damage') THEN v_delta:=-v_qty;
    ELSE v_delta:=0; END IF;
    v_after:=v_before+v_delta;
  END IF;

  IF v_after < 0 THEN RAISE EXCEPTION 'inventory_negative_stock_blocked'; END IF;
  IF v_type IN ('loss','damage') AND nullif(btrim(coalesce(p_notes,'')),'') IS NULL THEN RAISE EXCEPTION 'inventory_exception_reason_required'; END IF;

  IF v_type='transfer' THEN
    v_source := coalesce(nullif(btrim(v_metadata->>'sourceLabel'),''),nullif(btrim(v_metadata->>'source_label'),''));
    v_destination := coalesce(nullif(btrim(v_metadata->>'destinationLabel'),''),nullif(btrim(v_metadata->>'destination_label'),''));
    IF v_source IS NULL OR v_destination IS NULL THEN RAISE EXCEPTION 'inventory_transfer_labels_required'; END IF;
    IF v_source=v_destination THEN RAISE EXCEPTION 'inventory_transfer_source_destination_same'; END IF;
  END IF;

  v_metadata := v_metadata || jsonb_build_object(
    'stock_before',v_before,'stock_after',v_after,'stock_delta',v_delta,
    'authority','angelcare360_inventory_apply_movement_v1',
    'transfer_scope',CASE WHEN v_type='transfer' THEN 'journal_only_no_location_balance' ELSE NULL END
  );

  INSERT INTO public.angelcare360_inventory_movements(
    school_id,item_id,movement_code,movement_type,quantity,movement_date,reference_type,reference_id,
    performed_by,notes,status,created_by,updated_by,metadata_json
  ) VALUES (
    p_school_id,p_item_id,p_movement_code,v_type,v_qty,coalesce(p_movement_date,CURRENT_DATE),
    nullif(btrim(coalesce(p_reference_type,'')),''),p_reference_id,p_performed_by,
    nullif(btrim(coalesce(p_notes,'')),''),'active',p_actor_user_id,p_actor_user_id,v_metadata
  ) RETURNING * INTO v_movement;

  IF v_type='damage' THEN v_status:='damaged';
  ELSIF v_type='loss' THEN v_status:='lost';
  ELSIF v_after<=0 THEN v_status:='out_of_stock';
  ELSIF v_after<=coalesce(v_item.reorder_level,0) THEN v_status:='low_stock';
  ELSE v_status:='active'; END IF;

  -- Transfer is a journal event only because production has no location-balance authority.
  IF v_type='transfer' THEN v_status:=v_item.status; END IF;

  UPDATE public.angelcare360_inventory_items SET
    current_stock=v_after,
    status=v_status,
    updated_by=p_actor_user_id,
    updated_at=now()
  WHERE school_id=p_school_id AND id=p_item_id;

  RETURN jsonb_build_object('ok',true,'idempotent',false,'movement',to_jsonb(v_movement),'stockBefore',v_before,'stockAfter',v_after,'stockDelta',v_delta);
END $$;


--
-- Name: angelcare360_inventory_integrity_status_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_inventory_integrity_status_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'ready',
      to_regprocedure('public.angelcare360_inventory_apply_movement_v1(uuid,uuid,text,text,numeric,numeric,date,text,uuid,uuid,uuid,text,jsonb)') IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.angelcare360_inventory_movements'::regclass AND conname='angelcare360_inventory_movements_movement_type_check'),
    'version','inventory-material-command-v1',
    'reason',CASE WHEN EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.angelcare360_inventory_movements'::regclass AND conname='angelcare360_inventory_movements_movement_type_check') THEN 'legacy_restrictive_movement_constraint_present' ELSE NULL END
  );
$$;


--
-- Name: angelcare360_library_cancel_loan_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_library_cancel_loan_v1(p_school_id uuid, p_loan_id uuid, p_actor_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_loan public.angelcare360_library_loans%ROWTYPE;
  v_copy public.angelcare360_library_copies%ROWTYPE;
  v_before_loan jsonb;
  v_before_copy jsonb;
BEGIN
  IF NULLIF(btrim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Le motif d’annulation est obligatoire.'; END IF;

  SELECT * INTO v_loan FROM public.angelcare360_library_loans
  WHERE school_id = p_school_id AND id = p_loan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prêt introuvable.'; END IF;

  SELECT * INTO v_copy FROM public.angelcare360_library_copies
  WHERE school_id = p_school_id AND id = v_loan.copy_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Exemplaire du prêt introuvable.'; END IF;

  IF v_loan.status = 'cancelled' THEN
    RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copy', to_jsonb(v_copy), 'idempotent', true);
  END IF;
  IF v_loan.returned_at IS NOT NULL OR v_loan.status NOT IN ('open','active','overdue') THEN
    RAISE EXCEPTION 'Ce prêt ne peut pas être annulé depuis son état actuel (%).', v_loan.status;
  END IF;

  v_before_loan := to_jsonb(v_loan); v_before_copy := to_jsonb(v_copy);

  UPDATE public.angelcare360_library_loans
  SET status = 'cancelled', updated_by = p_actor_user_id,
      metadata_json = COALESCE(metadata_json, '{}'::jsonb)
        || jsonb_build_object('cancel_reason', p_reason)
  WHERE id = p_loan_id RETURNING * INTO v_loan;

  UPDATE public.angelcare360_library_copies
  SET status = 'available', updated_by = p_actor_user_id
  WHERE id = v_copy.id RETURNING * INTO v_copy;

  INSERT INTO public.angelcare360_audit_logs (
    school_id, actor_user_id, actor_role, module, action,
    entity_type, entity_id, severity, before_data, after_data, metadata
  ) VALUES (
    p_school_id, p_actor_user_id, 'school_user', 'bibliotheque', 'library_loan.cancelled_atomic',
    'library_loan', v_loan.id, 'notice', v_before_loan, to_jsonb(v_loan),
    jsonb_build_object('reason', p_reason, 'copy_before', v_before_copy, 'copy_after', to_jsonb(v_copy), 'authority', 'angelcare360_library_cancel_loan_v1')
  );

  RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copy', to_jsonb(v_copy));
END;
$$;


--
-- Name: angelcare360_library_create_loan_v1(uuid, uuid, text, uuid, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_library_create_loan_v1(p_school_id uuid, p_copy_id uuid, p_borrower_type text, p_borrower_id uuid, p_due_at timestamp with time zone, p_actor_user_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_copy public.angelcare360_library_copies%ROWTYPE;
  v_loan public.angelcare360_library_loans%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_due_at IS NULL OR p_due_at <= v_now THEN
    RAISE EXCEPTION 'L’échéance du prêt doit être postérieure à maintenant.';
  END IF;
  IF p_borrower_type NOT IN ('student','staff') THEN
    RAISE EXCEPTION 'Type d’emprunteur invalide.';
  END IF;

  SELECT * INTO v_copy
  FROM public.angelcare360_library_copies
  WHERE school_id = p_school_id AND id = p_copy_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Exemplaire introuvable dans cet établissement.'; END IF;
  IF v_copy.status <> 'available' THEN
    RAISE EXCEPTION 'Cet exemplaire n’est pas disponible (état actuel: %).', v_copy.status;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.angelcare360_library_loans
    WHERE school_id = p_school_id
      AND copy_id = p_copy_id
      AND returned_at IS NULL
      AND status IN ('open','active','overdue')
  ) THEN
    RAISE EXCEPTION 'Cet exemplaire possède déjà un prêt actif.';
  END IF;

  IF p_borrower_type = 'student' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.angelcare360_students
      WHERE id = p_borrower_id AND school_id = p_school_id AND status = 'active'
    ) THEN RAISE EXCEPTION 'Élève emprunteur introuvable ou inactif.'; END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.angelcare360_staff
      WHERE id = p_borrower_id AND school_id = p_school_id AND status = 'active'
    ) THEN RAISE EXCEPTION 'Membre du personnel introuvable ou inactif.'; END IF;
  END IF;

  INSERT INTO public.angelcare360_library_loans (
    school_id, copy_id, borrower_type,
    borrower_student_id, borrower_staff_id,
    loaned_at, due_at, returned_at, fine_amount, status,
    created_by, updated_by, metadata_json
  ) VALUES (
    p_school_id, p_copy_id, p_borrower_type,
    CASE WHEN p_borrower_type = 'student' THEN p_borrower_id ELSE NULL END,
    CASE WHEN p_borrower_type = 'staff' THEN p_borrower_id ELSE NULL END,
    v_now, p_due_at, NULL, 0, 'open',
    p_actor_user_id, p_actor_user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'loan_notes', p_notes,
      'circulation_authority', 'angelcare360_library_create_loan_v1'
    ))
  )
  RETURNING * INTO v_loan;

  UPDATE public.angelcare360_library_copies
  SET status = 'loaned', updated_by = p_actor_user_id
  WHERE id = p_copy_id AND school_id = p_school_id;

  INSERT INTO public.angelcare360_audit_logs (
    school_id, actor_user_id, actor_role, module, action,
    entity_type, entity_id, severity, before_data, after_data, metadata
  ) VALUES (
    p_school_id, p_actor_user_id, 'school_user', 'bibliotheque', 'library_loan.created_atomic',
    'library_loan', v_loan.id, 'info', '{}'::jsonb, to_jsonb(v_loan),
    jsonb_build_object('copy_id', p_copy_id, 'borrower_type', p_borrower_type, 'authority', 'angelcare360_library_create_loan_v1')
  );

  RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copyStatus', 'loaned');
END;
$$;


--
-- Name: angelcare360_library_integrity_status_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_library_integrity_status_v1(p_school_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  duplicate_active bigint;
  state_mismatch bigint;
  orphan_loaned bigint;
  invalid_borrowers bigint;
  duplicate_barcodes bigint;
BEGIN
  SELECT count(*) INTO duplicate_active
  FROM (
    SELECT copy_id
    FROM public.angelcare360_library_loans
    WHERE school_id = p_school_id
      AND returned_at IS NULL
      AND status IN ('open','active','overdue')
    GROUP BY copy_id
    HAVING count(*) > 1
  ) x;

  SELECT count(*) INTO state_mismatch
  FROM public.angelcare360_library_loans l
  JOIN public.angelcare360_library_copies c
    ON c.id = l.copy_id AND c.school_id = l.school_id
  WHERE l.school_id = p_school_id
    AND l.returned_at IS NULL
    AND l.status IN ('open','active','overdue')
    AND c.status <> 'loaned';

  SELECT count(*) INTO orphan_loaned
  FROM public.angelcare360_library_copies c
  WHERE c.school_id = p_school_id
    AND c.status = 'loaned'
    AND NOT EXISTS (
      SELECT 1
      FROM public.angelcare360_library_loans l
      WHERE l.school_id = c.school_id
        AND l.copy_id = c.id
        AND l.returned_at IS NULL
        AND l.status IN ('open','active','overdue')
    );

  SELECT count(*) INTO invalid_borrowers
  FROM public.angelcare360_library_loans l
  WHERE l.school_id = p_school_id
    AND l.returned_at IS NULL
    AND l.status IN ('open','active','overdue')
    AND (
      (l.borrower_type = 'student' AND (
        l.borrower_student_id IS NULL OR l.borrower_staff_id IS NOT NULL
        OR NOT EXISTS (
          SELECT 1 FROM public.angelcare360_students s
          WHERE s.id = l.borrower_student_id AND s.school_id = l.school_id
        )
      ))
      OR
      (l.borrower_type = 'staff' AND (
        l.borrower_staff_id IS NULL OR l.borrower_student_id IS NOT NULL
        OR NOT EXISTS (
          SELECT 1 FROM public.angelcare360_staff s
          WHERE s.id = l.borrower_staff_id AND s.school_id = l.school_id
        )
      ))
    );

  SELECT count(*) INTO duplicate_barcodes
  FROM (
    SELECT btrim(barcode)
    FROM public.angelcare360_library_copies
    WHERE school_id = p_school_id
      AND barcode IS NOT NULL
      AND btrim(barcode) <> ''
    GROUP BY btrim(barcode)
    HAVING count(*) > 1
  ) x;

  RETURN jsonb_build_object(
    'installed', true,
    'safeForCirculation', (
      duplicate_active = 0
      AND state_mismatch = 0
      AND orphan_loaned = 0
      AND invalid_borrowers = 0
      AND duplicate_barcodes = 0
    ),
    'duplicateActiveLoans', duplicate_active,
    'activeLoanCopyStateMismatch', state_mismatch,
    'loanedCopiesWithoutActiveLoan', orphan_loaned,
    'invalidBorrowers', invalid_borrowers,
    'barcodeDuplicates', duplicate_barcodes
  );
END;
$$;


--
-- Name: angelcare360_library_mark_lost_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_library_mark_lost_v1(p_school_id uuid, p_loan_id uuid, p_actor_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_loan public.angelcare360_library_loans%ROWTYPE;
  v_copy public.angelcare360_library_copies%ROWTYPE;
  v_before_loan jsonb;
  v_before_copy jsonb;
BEGIN
  IF NULLIF(btrim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Le motif de perte est obligatoire.'; END IF;

  SELECT * INTO v_loan FROM public.angelcare360_library_loans
  WHERE school_id = p_school_id AND id = p_loan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prêt introuvable.'; END IF;

  SELECT * INTO v_copy FROM public.angelcare360_library_copies
  WHERE school_id = p_school_id AND id = v_loan.copy_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Exemplaire du prêt introuvable.'; END IF;

  IF v_loan.status = 'lost' AND v_copy.status = 'lost' THEN
    RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copy', to_jsonb(v_copy), 'idempotent', true);
  END IF;
  IF v_loan.returned_at IS NOT NULL OR v_loan.status NOT IN ('open','active','overdue') THEN
    RAISE EXCEPTION 'Ce prêt ne peut pas être déclaré perdu depuis son état actuel (%).', v_loan.status;
  END IF;

  v_before_loan := to_jsonb(v_loan); v_before_copy := to_jsonb(v_copy);

  UPDATE public.angelcare360_library_loans
  SET status = 'lost', returned_at = now(), updated_by = p_actor_user_id,
      metadata_json = COALESCE(metadata_json, '{}'::jsonb)
        || jsonb_build_object('lost_reason', p_reason)
  WHERE id = p_loan_id RETURNING * INTO v_loan;

  UPDATE public.angelcare360_library_copies
  SET status = 'lost', updated_by = p_actor_user_id
  WHERE id = v_copy.id RETURNING * INTO v_copy;

  INSERT INTO public.angelcare360_audit_logs (
    school_id, actor_user_id, actor_role, module, action,
    entity_type, entity_id, severity, before_data, after_data, metadata
  ) VALUES (
    p_school_id, p_actor_user_id, 'school_user', 'bibliotheque', 'library_loan.marked_lost_atomic',
    'library_loan', v_loan.id, 'warning', v_before_loan, to_jsonb(v_loan),
    jsonb_build_object('reason', p_reason, 'copy_before', v_before_copy, 'copy_after', to_jsonb(v_copy), 'authority', 'angelcare360_library_mark_lost_v1')
  );

  RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copy', to_jsonb(v_copy));
END;
$$;


--
-- Name: angelcare360_library_return_loan_v1(uuid, uuid, timestamp with time zone, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_library_return_loan_v1(p_school_id uuid, p_loan_id uuid, p_returned_at timestamp with time zone, p_copy_outcome text, p_condition text, p_actor_user_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_loan public.angelcare360_library_loans%ROWTYPE;
  v_copy public.angelcare360_library_copies%ROWTYPE;
  v_before_loan jsonb;
  v_before_copy jsonb;
  v_returned timestamptz := COALESCE(p_returned_at, now());
BEGIN
  IF p_copy_outcome NOT IN ('available','damaged') THEN
    RAISE EXCEPTION 'État physique de retour invalide.';
  END IF;

  SELECT * INTO v_loan
  FROM public.angelcare360_library_loans
  WHERE school_id = p_school_id AND id = p_loan_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prêt introuvable.'; END IF;

  SELECT * INTO v_copy
  FROM public.angelcare360_library_copies
  WHERE school_id = p_school_id AND id = v_loan.copy_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Exemplaire du prêt introuvable.'; END IF;

  IF v_loan.status = 'returned' AND v_loan.returned_at IS NOT NULL THEN
    RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copy', to_jsonb(v_copy), 'idempotent', true);
  END IF;
  IF v_loan.returned_at IS NOT NULL OR v_loan.status NOT IN ('open','active','overdue') THEN
    RAISE EXCEPTION 'Ce prêt ne peut pas être retourné depuis son état actuel (%).', v_loan.status;
  END IF;

  v_before_loan := to_jsonb(v_loan);
  v_before_copy := to_jsonb(v_copy);

  UPDATE public.angelcare360_library_loans
  SET status = 'returned',
      returned_at = v_returned,
      updated_by = p_actor_user_id,
      metadata_json = COALESCE(metadata_json, '{}'::jsonb)
        || jsonb_strip_nulls(jsonb_build_object('return_notes', p_notes, 'return_copy_outcome', p_copy_outcome))
  WHERE id = p_loan_id
  RETURNING * INTO v_loan;

  UPDATE public.angelcare360_library_copies
  SET status = p_copy_outcome,
      condition = COALESCE(NULLIF(btrim(p_condition), ''), condition),
      updated_by = p_actor_user_id
  WHERE id = v_copy.id
  RETURNING * INTO v_copy;

  INSERT INTO public.angelcare360_audit_logs (
    school_id, actor_user_id, actor_role, module, action,
    entity_type, entity_id, severity, before_data, after_data, metadata
  ) VALUES (
    p_school_id, p_actor_user_id, 'school_user', 'bibliotheque', 'library_loan.returned_atomic',
    'library_loan', v_loan.id, CASE WHEN p_copy_outcome = 'damaged' THEN 'warning' ELSE 'info' END,
    v_before_loan, to_jsonb(v_loan),
    jsonb_build_object('copy_before', v_before_copy, 'copy_after', to_jsonb(v_copy), 'authority', 'angelcare360_library_return_loan_v1')
  );

  RETURN jsonb_build_object('loan', to_jsonb(v_loan), 'copy', to_jsonb(v_copy));
END;
$$;


--
-- Name: angelcare360_next_finance_number(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_next_finance_number(p_school_id uuid, p_sequence_key text, p_prefix text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_next bigint;
begin
  if p_school_id is null or coalesce(trim(p_sequence_key),'') = '' or coalesce(trim(p_prefix),'') = '' then
    raise exception 'Finance sequence arguments are required.';
  end if;
  insert into public.angelcare360_finance_number_sequences(school_id,sequence_key,prefix,current_value)
  values(p_school_id,p_sequence_key,p_prefix,0)
  on conflict(school_id,sequence_key) do nothing;
  update public.angelcare360_finance_number_sequences
     set current_value=current_value+1,prefix=p_prefix,updated_at=now()
   where school_id=p_school_id and sequence_key=p_sequence_key
   returning current_value into v_next;
  return upper(p_prefix)||'-'||to_char(current_date,'YYYY')||'-'||lpad(v_next::text,6,'0');
end;
$$;


