--
-- Name: angelcare360_transport_assign_student_v1(uuid, uuid, uuid, uuid, text, numeric, date, date, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_transport_assign_student_v1(p_org_id uuid, p_student_id uuid, p_route_id uuid, p_stop_id uuid DEFAULT NULL::uuid, p_service_direction text DEFAULT 'round_trip'::text, p_monthly_fee_mad numeric DEFAULT 0, p_starts_on date DEFAULT CURRENT_DATE, p_ends_on date DEFAULT NULL::date, p_status text DEFAULT 'active'::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_route record; v_stop record; v_student record; v_result jsonb;
BEGIN
  SELECT * INTO v_route FROM public.ac360_school_transport_routes WHERE id=p_route_id AND org_id=p_org_id FOR SHARE;
  IF v_route.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Route not found in organization.'); END IF;
  SELECT * INTO v_student FROM public.ac360_school_students WHERE id=p_student_id AND org_id=p_org_id FOR SHARE;
  IF v_student.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Student not found in organization.'); END IF;
  IF p_stop_id IS NOT NULL THEN
    SELECT * INTO v_stop FROM public.ac360_school_transport_route_stops WHERE id=p_stop_id AND org_id=p_org_id AND route_id=p_route_id FOR SHARE;
    IF v_stop.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Selected stop does not belong to selected route.'); END IF;
  END IF;
  IF p_ends_on IS NOT NULL AND p_ends_on<p_starts_on THEN RETURN jsonb_build_object('ok',false,'error','Assignment end date cannot precede start date.'); END IF;
  SELECT public.ac360_school_assign_transport_student(p_org_id,p_student_id,p_route_id,p_stop_id,p_service_direction,p_monthly_fee_mad,p_starts_on,p_ends_on,p_status,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) INTO v_result;
  RETURN v_result;
END $$;


--
-- Name: angelcare360_transport_close_run_v1(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_transport_close_run_v1(p_org_id uuid, p_route_run_id uuid, p_status text DEFAULT 'completed'::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_run record; v_result jsonb;
BEGIN
  SELECT * INTO v_run FROM public.ac360_school_transport_route_runs WHERE id=p_route_run_id AND org_id=p_org_id FOR UPDATE;
  IF v_run.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Route run not found in organization.'); END IF;
  IF v_run.status IN ('completed','cancelled','archived') THEN RETURN jsonb_build_object('ok',true,'routeRunId',v_run.id,'status',v_run.status,'idempotent',true); END IF;
  IF p_status NOT IN ('completed','cancelled','incident') THEN RETURN jsonb_build_object('ok',false,'error','Unsupported route-run closing state.'); END IF;
  SELECT public.ac360_school_close_transport_route_run(p_org_id,p_route_run_id,p_status,p_notes,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) INTO v_result;
  RETURN v_result;
END $$;


--
-- Name: angelcare360_transport_integrity_status_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_transport_integrity_status_v1(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stop_route integer := 0; v_assignment_org integer := 0; v_route_refs integer := 0;
  v_run_refs integer := 0; v_event_refs integer := 0; v_safety_refs integer := 0; v_over integer := 0;
BEGIN
  SELECT count(*) INTO v_stop_route
  FROM public.ac360_school_transport_student_assignments a
  JOIN public.ac360_school_transport_route_stops s ON s.id=a.stop_id
  WHERE a.org_id=p_org_id AND a.stop_id IS NOT NULL AND (s.org_id<>a.org_id OR s.route_id<>a.route_id);

  SELECT count(*) INTO v_assignment_org
  FROM public.ac360_school_transport_student_assignments a
  JOIN public.ac360_school_students st ON st.id=a.student_id
  JOIN public.ac360_school_transport_routes r ON r.id=a.route_id
  WHERE a.org_id=p_org_id AND (st.org_id<>a.org_id OR r.org_id<>a.org_id);

  SELECT count(*) INTO v_route_refs
  FROM public.ac360_school_transport_routes r
  LEFT JOIN public.ac360_school_transport_vehicles v ON v.id=r.default_vehicle_id
  LEFT JOIN public.ac360_school_transport_drivers d ON d.id=r.default_driver_id
  WHERE r.org_id=p_org_id AND (
    (r.default_vehicle_id IS NOT NULL AND (v.id IS NULL OR v.org_id<>r.org_id)) OR
    (r.default_driver_id IS NOT NULL AND (d.id IS NULL OR d.org_id<>r.org_id))
  );

  SELECT count(*) INTO v_run_refs
  FROM public.ac360_school_transport_route_runs rr
  LEFT JOIN public.ac360_school_transport_routes r ON r.id=rr.route_id
  LEFT JOIN public.ac360_school_transport_vehicles v ON v.id=rr.vehicle_id
  LEFT JOIN public.ac360_school_transport_drivers d ON d.id=rr.driver_id
  WHERE rr.org_id=p_org_id AND (
    r.id IS NULL OR r.org_id<>rr.org_id OR
    (rr.vehicle_id IS NOT NULL AND (v.id IS NULL OR v.org_id<>rr.org_id)) OR
    (rr.driver_id IS NOT NULL AND (d.id IS NULL OR d.org_id<>rr.org_id))
  );

  SELECT count(*) INTO v_event_refs
  FROM public.ac360_school_transport_run_events e
  LEFT JOIN public.ac360_school_transport_route_runs rr ON rr.id=e.route_run_id
  LEFT JOIN public.ac360_school_students st ON st.id=e.student_id
  LEFT JOIN public.ac360_school_transport_route_stops s ON s.id=e.stop_id
  WHERE e.org_id=p_org_id AND (
    rr.id IS NULL OR rr.org_id<>e.org_id OR
    (e.student_id IS NOT NULL AND (st.id IS NULL OR st.org_id<>e.org_id)) OR
    (e.stop_id IS NOT NULL AND (s.id IS NULL OR s.org_id<>e.org_id OR s.route_id<>rr.route_id))
  );

  SELECT count(*) INTO v_safety_refs
  FROM public.ac360_school_transport_safety_checks c
  LEFT JOIN public.ac360_school_transport_vehicles v ON v.id=c.vehicle_id
  LEFT JOIN public.ac360_school_transport_drivers d ON d.id=c.driver_id
  LEFT JOIN public.ac360_school_transport_route_runs rr ON rr.id=c.route_run_id
  WHERE c.org_id=p_org_id AND (
    (c.vehicle_id IS NOT NULL AND (v.id IS NULL OR v.org_id<>c.org_id)) OR
    (c.driver_id IS NOT NULL AND (d.id IS NULL OR d.org_id<>c.org_id)) OR
    (c.route_run_id IS NOT NULL AND (rr.id IS NULL OR rr.org_id<>c.org_id))
  );

  SELECT count(*) INTO v_over FROM (
    SELECT r.id FROM public.ac360_school_transport_routes r
    JOIN public.ac360_school_transport_vehicles v ON v.id=r.default_vehicle_id AND v.org_id=r.org_id
    LEFT JOIN public.ac360_school_transport_student_assignments a ON a.route_id=r.id AND a.org_id=r.org_id AND a.status='active'
    WHERE r.org_id=p_org_id AND r.status='active' AND v.capacity>0
    GROUP BY r.id,v.capacity HAVING count(a.id)>v.capacity
  ) x;

  RETURN jsonb_build_object(
    'installed',true,
    'safeForOperations',(v_stop_route+v_assignment_org+v_route_refs+v_run_refs+v_event_refs+v_safety_refs)=0,
    'assignmentStopRouteMismatch',v_stop_route,
    'assignmentCrossOrg',v_assignment_org,
    'routeReferenceCrossOrg',v_route_refs,
    'runReferenceCrossOrg',v_run_refs,
    'runEventReferenceCrossOrg',v_event_refs,
    'safetyReferenceCrossOrg',v_safety_refs,
    'overCapacityRoutes',v_over,
    'message',case when (v_stop_route+v_assignment_org+v_route_refs+v_run_refs+v_event_refs+v_safety_refs)=0 then 'Transport reference integrity accepted.' else 'Transport reference integrity requires reconciliation.' end
  );
END $$;


--
-- Name: angelcare360_transport_open_run_v1(uuid, uuid, uuid, uuid, date, text, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_transport_open_run_v1(p_org_id uuid, p_route_id uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_driver_id uuid DEFAULT NULL::uuid, p_run_date date DEFAULT CURRENT_DATE, p_run_type text DEFAULT 'pickup'::text, p_planned_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_route record; v_vehicle record; v_driver record; v_vehicle_id uuid; v_driver_id uuid; v_count integer; v_latest text; v_existing uuid; v_result jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org_id::text || ':' || p_route_id::text || ':' || coalesce(p_run_date,current_date)::text || ':' || coalesce(p_run_type,'pickup'),0));
  SELECT * INTO v_route FROM public.ac360_school_transport_routes WHERE id=p_route_id AND org_id=p_org_id FOR SHARE;
  IF v_route.id IS NULL OR v_route.status<>'active' THEN RETURN jsonb_build_object('ok',false,'error','Active route required.'); END IF;
  v_vehicle_id:=coalesce(p_vehicle_id,v_route.default_vehicle_id); v_driver_id:=coalesce(p_driver_id,v_route.default_driver_id);
  IF v_vehicle_id IS NULL OR v_driver_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Vehicle and driver are required before departure.'); END IF;

  SELECT * INTO v_vehicle FROM public.ac360_school_transport_vehicles WHERE id=v_vehicle_id AND org_id=p_org_id FOR SHARE;
  IF v_vehicle.id IS NULL OR v_vehicle.status<>'active' THEN RETURN jsonb_build_object('ok',false,'error','Active vehicle required.'); END IF;
  SELECT * INTO v_driver FROM public.ac360_school_transport_drivers WHERE id=v_driver_id AND org_id=p_org_id FOR SHARE;
  IF v_driver.id IS NULL OR v_driver.status<>'active' THEN RETURN jsonb_build_object('ok',false,'error','Active driver required.'); END IF;

  IF v_vehicle.insurance_expiry IS NOT NULL AND v_vehicle.insurance_expiry<coalesce(p_run_date,current_date) THEN RETURN jsonb_build_object('ok',false,'error','Vehicle insurance is expired for run date.'); END IF;
  IF v_vehicle.inspection_expiry IS NOT NULL AND v_vehicle.inspection_expiry<coalesce(p_run_date,current_date) THEN RETURN jsonb_build_object('ok',false,'error','Vehicle inspection is expired for run date.'); END IF;
  IF v_driver.license_expiry IS NOT NULL AND v_driver.license_expiry<coalesce(p_run_date,current_date) THEN RETURN jsonb_build_object('ok',false,'error','Driver license is expired for run date.'); END IF;

  SELECT count(*) INTO v_count FROM public.ac360_school_transport_student_assignments
  WHERE org_id=p_org_id AND route_id=p_route_id AND status='active'
    AND starts_on<=coalesce(p_run_date,current_date) AND (ends_on IS NULL OR ends_on>=coalesce(p_run_date,current_date))
    AND (service_direction=p_run_type OR service_direction='round_trip' OR p_run_type IN ('event','emergency'));
  IF v_vehicle.capacity>0 AND v_count>v_vehicle.capacity THEN RETURN jsonb_build_object('ok',false,'error','Active student assignments exceed vehicle capacity.','assignedStudents',v_count,'vehicleCapacity',v_vehicle.capacity); END IF;
  IF v_vehicle.seatbelt_count>0 AND v_count>v_vehicle.seatbelt_count THEN RETURN jsonb_build_object('ok',false,'error','Active student assignments exceed recorded seatbelt count.','assignedStudents',v_count,'seatbeltCount',v_vehicle.seatbelt_count); END IF;

  SELECT result INTO v_latest FROM public.ac360_school_transport_safety_checks
  WHERE org_id=p_org_id AND vehicle_id=v_vehicle_id AND driver_id=v_driver_id AND check_type='pre_route'
    AND checked_at::date=coalesce(p_run_date,current_date)
  ORDER BY checked_at DESC LIMIT 1;
  IF v_latest IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Pre-route safety check required before opening a run.'); END IF;
  IF v_latest IN ('failed','blocked') THEN RETURN jsonb_build_object('ok',false,'error','Latest pre-route safety check blocks departure.','safetyResult',v_latest); END IF;

  SELECT id INTO v_existing FROM public.ac360_school_transport_route_runs
  WHERE org_id=p_org_id AND route_id=p_route_id AND run_date=coalesce(p_run_date,current_date) AND run_type=p_run_type
    AND status IN ('planned','started','in_progress','incident')
  ORDER BY created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'routeRunId',v_existing,'status','existing','idempotent',true); END IF;

  SELECT public.ac360_school_open_transport_route_run(p_org_id,p_route_id,v_vehicle_id,v_driver_id,p_run_date,p_run_type,p_planned_start_at,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) INTO v_result;
  RETURN v_result;
END $$;


--
-- Name: angelcare360_transport_record_run_event_v1(uuid, uuid, uuid, uuid, text, timestamp with time zone, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_transport_record_run_event_v1(p_org_id uuid, p_route_run_id uuid, p_student_id uuid DEFAULT NULL::uuid, p_stop_id uuid DEFAULT NULL::uuid, p_event_type text DEFAULT 'run_note'::text, p_occurred_at timestamp with time zone DEFAULT now(), p_status text DEFAULT 'recorded'::text, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_run record; v_assignment record; v_result jsonb;
BEGIN
  SELECT * INTO v_run FROM public.ac360_school_transport_route_runs WHERE id=p_route_run_id AND org_id=p_org_id FOR SHARE;
  IF v_run.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Route run not found in organization.'); END IF;
  IF v_run.status IN ('completed','cancelled','archived') THEN RETURN jsonb_build_object('ok',false,'error','Route run is already closed.'); END IF;

  IF p_stop_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ac360_school_transport_route_stops WHERE id=p_stop_id AND org_id=p_org_id AND route_id=v_run.route_id) THEN
    RETURN jsonb_build_object('ok',false,'error','Stop does not belong to route run.');
  END IF;

  IF p_student_id IS NOT NULL THEN
    SELECT * INTO v_assignment FROM public.ac360_school_transport_student_assignments
    WHERE org_id=p_org_id AND student_id=p_student_id AND route_id=v_run.route_id AND status='active'
      AND starts_on<=v_run.run_date AND (ends_on IS NULL OR ends_on>=v_run.run_date)
      AND (service_direction=v_run.run_type OR service_direction='round_trip' OR v_run.run_type IN ('event','emergency'))
    ORDER BY created_at DESC LIMIT 1;
    IF v_assignment.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Student is not actively assigned to this route/run direction.'); END IF;
    IF p_stop_id IS NOT NULL AND v_assignment.stop_id IS NOT NULL AND p_event_type IN ('student_boarded','student_dropped') AND v_assignment.stop_id<>p_stop_id THEN
      RETURN jsonb_build_object('ok',false,'error','Student event stop differs from active transport assignment.');
    END IF;
  END IF;

  SELECT public.ac360_school_record_transport_run_event(p_org_id,p_route_run_id,p_student_id,p_stop_id,p_event_type,p_occurred_at,p_status,p_notes,p_actor_app_user_id,coalesce(p_metadata,'{}'::jsonb)) INTO v_result;
  RETURN v_result;
END $$;


--
-- Name: angelcare360_transport_record_safety_check_v1(uuid, uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare360_transport_record_safety_check_v1(p_org_id uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_driver_id uuid DEFAULT NULL::uuid, p_route_run_id uuid DEFAULT NULL::uuid, p_check_type text DEFAULT 'pre_route'::text, p_result text DEFAULT 'passed'::text, p_checked_at timestamp with time zone DEFAULT now(), p_checked_by_staff_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_actor_app_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_run record; v_result jsonb;
BEGIN
  IF p_vehicle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ac360_school_transport_vehicles WHERE id=p_vehicle_id AND org_id=p_org_id) THEN RETURN jsonb_build_object('ok',false,'error','Vehicle does not belong to organization.'); END IF;
  IF p_driver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ac360_school_transport_drivers WHERE id=p_driver_id AND org_id=p_org_id) THEN RETURN jsonb_build_object('ok',false,'error','Driver does not belong to organization.'); END IF;
  IF p_route_run_id IS NOT NULL THEN
    SELECT * INTO v_run FROM public.ac360_school_transport_route_runs WHERE id=p_route_run_id AND org_id=p_org_id;
    IF v_run.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Route run does not belong to organization.'); END IF;
    IF p_vehicle_id IS NOT NULL AND v_run.vehicle_id IS NOT NULL AND p_vehicle_id<>v_run.vehicle_id THEN RETURN jsonb_build_object('ok',false,'error','Safety vehicle differs from route-run vehicle.'); END IF;
    IF p_driver_id IS NOT NULL AND v_run.driver_id IS NOT NULL AND p_driver_id<>v_run.driver_id THEN RETURN jsonb_build_object('ok',false,'error','Safety driver differs from route-run driver.'); END IF;
  END IF;
  SELECT public.ac360_school_record_transport_safety_check(p_org_id,p_vehicle_id,p_driver_id,p_route_run_id,p_check_type,p_result,p_checked_at,p_checked_by_staff_id,p_notes,coalesce(p_metadata,'{}'::jsonb) || jsonb_build_object('actorAppUserId',p_actor_app_user_id)) INTO v_result;
  RETURN v_result;
END $$;


--
-- Name: angelcare_marketplace_approve_sensitive_content(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_approve_sensitive_content(p_review_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_sensitive_content_reviews;begin select * into r from public.angelcare_marketplace_sensitive_content_reviews where id=p_review_id for update;if r.id is null then raise exception 'Sensitive review introuvable';end if;if r.source_locale<>'fr' then raise exception 'French canonical source required';end if;if r.translation_status<>'approved' then raise exception 'Approved translations required';end if;if r.evidence_status<>'current' then raise exception 'Approved evidence required';end if;if r.domain_owner_status<>'approved' then raise exception 'Domain owner approval required';end if;if cardinality(r.blocking_reasons)>0 then raise exception 'Blocking reasons remain';end if;update public.angelcare_marketplace_sensitive_content_reviews set compliance_status='approved',publication_status='approved',compliance_reviewer_id=p_actor_id,approved_at=now(),updated_at=now() where id=p_review_id returning * into r;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_auto_grant_admin_permission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_auto_grant_admin_permission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.angelcare_marketplace_role_permissions (
    role_key,
    permission_key
  )
  values (
    'marketplace_admin',
    new.permission_key
  )
  on conflict (role_key, permission_key) do nothing;

  return new;
end;
$$;


--
-- Name: angelcare_marketplace_claim_guest_commerce(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_claim_guest_commerce(p_customer_account_id uuid, p_auth_user_id uuid, p_visitor_reference text, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_hash text;v_conversions int:=0;v_journeys int:=0;v_saved int:=0;v_recent int:=0;v_family uuid;
begin
 v_hash:=encode(digest(p_visitor_reference,'sha256'),'hex');
 select family_account_id into v_family from public.angelcare_marketplace_customer_accounts where id=p_customer_account_id;
 update public.angelcare_marketplace_conversion_sessions set customer_account_id=p_customer_account_id,family_account_id=coalesce(family_account_id,v_family),updated_at=now() where visitor_reference_hash=v_hash and customer_account_id is null;get diagnostics v_conversions=row_count;
 update public.angelcare_marketplace_journeys j set customer_account_id=p_customer_account_id,family_account_id=coalesce(j.family_account_id,v_family),customer_context=j.customer_context||jsonb_build_object('customer_account_id',p_customer_account_id,'email',p_email),updated_at=now()
 where j.customer_account_id is null and (j.conversion_outcome_id in(select outcome_id from public.angelcare_marketplace_conversion_sessions where customer_account_id=p_customer_account_id and outcome_id is not null) or lower(coalesce(j.customer_context->>'email',''))=lower(coalesce(p_email,'')));get diagnostics v_journeys=row_count;
 update public.angelcare_marketplace_homepage_visitor_selections set customer_account_id=p_customer_account_id,updated_at=now() where visitor_reference=p_visitor_reference and customer_account_id is null;get diagnostics v_saved=row_count;
 update public.angelcare_marketplace_recently_viewed set customer_account_id=p_customer_account_id where visitor_reference=p_visitor_reference and customer_account_id is null;get diagnostics v_recent=row_count;
 return jsonb_build_object('conversions',v_conversions,'journeys',v_journeys,'saved_items',v_saved,'recently_viewed',v_recent);
end$$;


--
-- Name: angelcare_marketplace_clone_territory(uuid, text, text, text, text, text, text, text[], uuid, uuid, text[], text[], text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_clone_territory(p_source_territory_id uuid, p_territory_code text, p_name text, p_country_code text, p_timezone text, p_currency_label text, p_default_locale text, p_active_locales text[], p_owner_id uuid, p_executive_sponsor_id uuid, p_inherited_domains text[], p_allowed_override_categories text[], p_idempotency_key text, p_actor_id uuid, p_request_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_existing uuid;
begin
  select target_territory_id into v_existing from public.angelcare_marketplace_territory_clone_operations where idempotency_key=p_idempotency_key and status='completed';
  if v_existing is not null then return v_existing; end if;
  insert into public.angelcare_marketplace_territory_clone_operations(idempotency_key,source_territory_id,inherited_domains,allowed_override_categories,status,created_by)
  values(p_idempotency_key,p_source_territory_id,coalesce(p_inherited_domains,'{}'),coalesce(p_allowed_override_categories,'{}'),'started',p_actor_id)
  on conflict (idempotency_key) do update set status='started' returning target_territory_id into v_existing;
  if v_existing is not null then return v_existing; end if;
  insert into public.angelcare_marketplace_territories
    (territory_code,name,country_code,territory_type,timezone,currency_label,default_locale,active_locales,status,owner_id,executive_sponsor_id,source_territory_id,inheritance_version,created_by,updated_by,metadata)
  select upper(trim(p_territory_code)),trim(p_name),upper(trim(p_country_code)),territory_type,p_timezone,p_currency_label,p_default_locale,p_active_locales,'configuring',p_owner_id,p_executive_sponsor_id,id,inheritance_version+1,p_actor_id,p_actor_id,jsonb_build_object('clone_request_id',p_request_id,'inherited_domains',p_inherited_domains,'allowed_override_categories',p_allowed_override_categories)
  from public.angelcare_marketplace_territories where id=p_source_territory_id returning id into v_id;
  if v_id is null then raise exception 'SOURCE_TERRITORY_NOT_FOUND'; end if;
  insert into public.angelcare_marketplace_territory_settings
    (territory_id,setting_key,category,label,description,source_type,source_id,source_version,inheritance_mode,is_locked,local_override_allowed,effective_value,owner_id,updated_by)
  select v_id,setting_key,category,label,description,'territory',p_source_territory_id,coalesce(source_version,1)+1,
         case when is_locked then 'locked_global' else 'inherited_snapshot' end,is_locked,
         (local_override_allowed and (cardinality(coalesce(p_allowed_override_categories,'{}'))=0 or category=any(p_allowed_override_categories))),effective_value,p_owner_id,p_actor_id
  from public.angelcare_marketplace_territory_settings where territory_id=p_source_territory_id
  on conflict (territory_id,setting_key) do nothing;
  insert into public.angelcare_marketplace_territory_city_zones(territory_id,city_name,zone_name,coverage_status,service_scope,owner_id)
  select v_id,city_name,zone_name,'planned',service_scope,p_owner_id from public.angelcare_marketplace_territory_city_zones where territory_id=p_source_territory_id and ('operations'=any(coalesce(p_inherited_domains,'{}')) or cardinality(coalesce(p_inherited_domains,'{}'))=0) on conflict do nothing;
  insert into public.angelcare_marketplace_territory_support_contacts(territory_id,contact_type,name,email,phone,active)
  select v_id,contact_type,name,email,phone,false from public.angelcare_marketplace_territory_support_contacts where territory_id=p_source_territory_id and ('support'=any(coalesce(p_inherited_domains,'{}')) or cardinality(coalesce(p_inherited_domains,'{}'))=0) on conflict do nothing;
  if p_owner_id is not null then insert into public.angelcare_marketplace_territory_assignments(territory_id,app_user_id,assignment_role,assigned_by) values(v_id,p_owner_id,'territory_owner',p_actor_id) on conflict do nothing; end if;
  perform public.angelcare_marketplace_seed_territory_gates(v_id,p_actor_id);
  update public.angelcare_marketplace_territory_clone_operations set target_territory_id=v_id,status='completed',result=jsonb_build_object('territory_id',v_id,'request_id',p_request_id),completed_at=timezone('utc',now()) where idempotency_key=p_idempotency_key;
  insert into public.angelcare_marketplace_territory_health_events(territory_id,event_key,category,severity,title,description,status,source,owner_id,created_by)
  values(v_id,'territory.cloned','governance','info','Territoire cloné','Standards hérités, overrides locaux et gates générés.','resolved','territory-os',p_owner_id,p_actor_id);
  return v_id;
exception when others then
  update public.angelcare_marketplace_territory_clone_operations set status='failed',result=jsonb_build_object('error',sqlerrm),completed_at=timezone('utc',now()) where idempotency_key=p_idempotency_key;
  raise;
end $$;


--
-- Name: angelcare_marketplace_close_operational_day(date, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_close_operational_day(p_closure_date date, p_territory_id uuid, p_tenant_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare blockers jsonb;mission_count int;status text;r public.angelcare_marketplace_operations_daily_closures;begin select count(*) into mission_count from public.angelcare_marketplace_operations_missions where mission_date=p_closure_date and (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);select jsonb_build_object('unassigned',count(*) filter(where status='staffing_required'),'acceptance_missing',count(*) filter(where status='awaiting_acceptance'),'check_in_missing',count(*) filter(where status='check_in_pending'),'check_out_missing',count(*) filter(where status='check_out_pending'),'reports_pending',count(*) filter(where status in('report_pending','validation_pending','correction_required')),'critical_incidents',(select count(*) from public.angelcare_marketplace_operations_incidents where critical_flag and occurred_at::date=p_closure_date)) into blockers from public.angelcare_marketplace_operations_missions where mission_date=p_closure_date and (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);status:=case when coalesce((blockers->>'unassigned')::int,0)+coalesce((blockers->>'acceptance_missing')::int,0)+coalesce((blockers->>'check_in_missing')::int,0)+coalesce((blockers->>'check_out_missing')::int,0)+coalesce((blockers->>'reports_pending')::int,0)+coalesce((blockers->>'critical_incidents')::int,0)>0 then 'blocked' else 'approved' end;insert into public.angelcare_marketplace_operations_daily_closures(closure_date,territory_id,tenant_id,status,blockers,mission_count,supervisor_id,approved_at) values(p_closure_date,p_territory_id,p_tenant_id,status,blockers,mission_count,p_actor_id,case when status='approved' then now() else null end) on conflict(closure_date,territory_id,tenant_id) do update set status=excluded.status,blockers=excluded.blockers,mission_count=excluded.mission_count,supervisor_id=excluded.supervisor_id,approved_at=excluded.approved_at,updated_at=now() returning * into r;if status='blocked' then raise exception 'Operational closure blocked: %',blockers;end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_convert_b2b_diagnostic(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_convert_b2b_diagnostic(p_diagnostic_id uuid, p_conversion_type text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare d public.angelcare_marketplace_b2b_diagnostics;o public.angelcare_marketplace_b2b_organizations;a public.angelcare_marketplace_crm_accounts;opp public.angelcare_marketplace_crm_opportunities;t public.angelcare_marketplace_partner_tenants;c public.angelcare_marketplace_b2b_conversions;begin select * into d from public.angelcare_marketplace_b2b_diagnostics where id=p_diagnostic_id for update;if d.status<>'qualified' then raise exception 'Diagnostic must be qualified';end if;select * into o from public.angelcare_marketplace_b2b_organizations where id=d.organization_id;insert into public.angelcare_marketplace_b2b_conversions(diagnostic_id,organization_id,conversion_type,status,territory_id,tenant_id,created_by) values(d.id,o.id,p_conversion_type,'processing',o.territory_id,o.tenant_id,p_actor_id) returning * into c;if p_conversion_type in('crm_opportunity','both') then if o.crm_account_id is null then insert into public.angelcare_marketplace_crm_accounts(account_type,legal_name,display_name,territory_id,status,owner_id,metadata,created_by,updated_by) values(o.organization_type,o.legal_name,o.display_name,o.territory_id,'qualified',o.owner_id,jsonb_build_object('b2b_organization_id',o.id),p_actor_id,p_actor_id) returning * into a;update public.angelcare_marketplace_b2b_organizations set crm_account_id=a.id,updated_at=now() where id=o.id;else select * into a from public.angelcare_marketplace_crm_accounts where id=o.crm_account_id;end if;insert into public.angelcare_marketplace_crm_opportunities(account_id,name,stage,estimated_value,currency_label,probability,owner_id,territory_id,next_action,created_by,updated_by) values(a.id,'Programme '||o.display_name,'qualified',(select coalesce(sum(estimated_value),0) from public.angelcare_marketplace_b2b_recommendations where diagnostic_id=d.id),'Dh',35,o.owner_id,o.territory_id,'Préparer la proposition B2B',p_actor_id,p_actor_id) returning * into opp;end if;if p_conversion_type in('partner_tenant','both') then if o.tenant_id is null then insert into public.angelcare_marketplace_partner_tenants(tenant_code,legal_name,display_name,tenant_type,territory_id,status,owner_id,created_by,updated_by) values('TEN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),o.legal_name,o.display_name,o.vertical,o.territory_id,'onboarding',o.owner_id,p_actor_id,p_actor_id) returning * into t;update public.angelcare_marketplace_b2b_organizations set tenant_id=t.id,updated_at=now() where id=o.id;else select * into t from public.angelcare_marketplace_partner_tenants where id=o.tenant_id;end if;end if;update public.angelcare_marketplace_b2b_diagnostics set status='converted',updated_by=p_actor_id,updated_at=now() where id=d.id;update public.angelcare_marketplace_b2b_conversions set status='completed',crm_account_id=a.id,crm_opportunity_id=opp.id,partner_tenant_id=t.id,result=jsonb_build_object('crm_account_id',a.id,'crm_opportunity_id',opp.id,'partner_tenant_id',t.id),completed_at=now() where id=c.id;return jsonb_build_object('conversion_id',c.id,'organization_id',o.id,'crm_account_id',a.id,'crm_opportunity_id',opp.id,'partner_tenant_id',t.id);end$$;


