    CONSTRAINT angelcare_marketplace_b2b_diagnostics_vertical_check CHECK ((vertical = ANY (ARRAY['establishment'::text, 'hospitality'::text, 'health_partner'::text, 'corporate'::text])))
);


--
-- Name: angelcare_marketplace_create_b2b_diagnostic(jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_create_b2b_diagnostic(p_payload jsonb, p_actor_id uuid, p_territory_id uuid, p_tenant_id uuid) RETURNS public.angelcare_marketplace_b2b_diagnostics
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare org public.angelcare_marketplace_b2b_organizations;diag public.angelcare_marketplace_b2b_diagnostics;v text;begin v:=coalesce(nullif(p_payload->>'vertical',''),'establishment');if v not in('establishment','hospitality','health_partner','corporate') then raise exception 'Invalid B2B vertical';end if;if nullif(p_payload->>'organization_id','') is not null then select * into org from public.angelcare_marketplace_b2b_organizations where id=(p_payload->>'organization_id')::uuid;else insert into public.angelcare_marketplace_b2b_organizations(legal_name,display_name,vertical,organization_type,territory_id,tenant_id,owner_id,lifecycle_status,next_action,created_by,updated_by) values(coalesce(nullif(p_payload->>'legal_name',''),p_payload->>'organization_name'),coalesce(nullif(p_payload->>'display_name',''),p_payload->>'organization_name'),v,coalesce(nullif(p_payload->>'organization_type',''),v),p_territory_id,p_tenant_id,p_actor_id,'diagnostic','Compléter le diagnostic',p_actor_id,p_actor_id) returning * into org;end if;if org.id is null then raise exception 'Organization not found';end if;insert into public.angelcare_marketplace_b2b_diagnostics(organization_id,vertical,diagnostic_type,status,territory_id,tenant_id,owner_id,answers,created_by,updated_by) values(org.id,v,coalesce(nullif(p_payload->>'diagnostic_type',''),v||'_diagnostic'),'in_progress',coalesce(p_territory_id,org.territory_id),coalesce(p_tenant_id,org.tenant_id),p_actor_id,coalesce(p_payload->'answers','{}'::jsonb),p_actor_id,p_actor_id) returning * into diag;insert into public.angelcare_marketplace_b2b_diagnostic_sections(diagnostic_id,section_key,title_fr,weight,sort_order) values(diag.id,'identity','Identité & périmètre',1,10),(diag.id,'operations','Opérations & capacité',1.5,20),(diag.id,'quality','Qualité & sécurité',2,30),(diag.id,'digital','Maturité digitale',1,40),(diag.id,'commercial','Budget & décision',1,50);return diag;end$$;


