    CONSTRAINT angelcare_marketplace_family_support_tickets_status_check CHECK ((status = ANY (ARRAY['open'::text, 'triaged'::text, 'in_progress'::text, 'waiting_family'::text, 'resolved'::text, 'closed'::text])))
);


