CREATE FUNCTION public.angelcare_marketplace_create_family_support_ticket(p_family_account_id uuid, p_subject text, p_category text, p_priority text, p_message text, p_actor_id uuid) RETURNS public.angelcare_marketplace_family_support_tickets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_family_support_tickets;begin insert into public.angelcare_marketplace_family_support_tickets(family_account_id,subject,category,priority,status,next_action)values(p_family_account_id,p_subject,p_category,p_priority,'open','Prise en charge par le support ANGELCARE.') returning * into r;insert into public.angelcare_marketplace_family_support_messages(ticket_id,author_type,author_id,body,visible_to_family)values(r.id,'family',p_actor_id,p_message,true);return r;end$$;


