    display_name text NOT NULL,
    tenant_type text NOT NULL,
    territory_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    owner_id uuid,
    default_locale text DEFAULT 'fr'::text NOT NULL,
    currency_label text DEFAULT 'Dh'::text NOT NULL,
    onboarding_score integer DEFAULT 0 NOT NULL,
    health_status text DEFAULT 'unknown'::text NOT NULL,
    created_by uuid,
