    CONSTRAINT angelcare_marketplace_partner_tenants_onboarding_score_check CHECK (((onboarding_score >= 0) AND (onboarding_score <= 100))),
    CONSTRAINT angelcare_marketplace_partner_tenants_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'onboarding'::text, 'trial'::text, 'active'::text, 'suspended'::text, 'cancelled'::text, 'archived'::text])))
);


