-- Name: angelcare_marketplace_create_partner_tenant(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_create_partner_tenant(p_payload jsonb, p_actor_id uuid, p_territory_id uuid) RETURNS public.angelcare_marketplace_partner_tenants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_partner_tenants;begin insert into public.angelcare_marketplace_partner_tenants(tenant_code,legal_name,display_name,tenant_type,territory_id,status,owner_id,default_locale,currency_label,created_by,updated_by) values(coalesce(nullif(p_payload->>'tenant_code',''),'TEN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),p_payload->>'legal_name',coalesce(p_payload->>'display_name',p_payload->>'legal_name'),coalesce(p_payload->>'tenant_type','establishment'),p_territory_id,'onboarding',p_actor_id,coalesce(p_payload->>'default_locale','fr'),coalesce(p_payload->>'currency_label','Dh'),p_actor_id,p_actor_id) returning * into r;insert into public.angelcare_marketplace_partner_onboarding_checks(tenant_id,check_key,title_fr,description_fr,required,sort_order) values(r.id,'identity.verified','Identité légale vérifiée','Confirmer la raison sociale et les documents.',true,10),(r.id,'subscription.active','Plan et abonnement confirmés','Affecter un plan et activer la période.',true,20),(r.id,'modules.configured','Modules configurés','Configurer les modules autorisés.',true,30),(r.id,'members.assigned','Équipe tenant affectée','Inviter et affecter les rôles tenant.',true,40),(r.id,'security.reviewed','Isolation et sécurité revues','Valider le périmètre tenant.',true,50),(r.id,'launch.approved','Activation approuvée','Décision finale de mise en service.',true,60);return r;end$$;


--
-- Name: angelcare_marketplace_create_territory(text, text, text, text, text, text, text, text[], uuid, uuid, uuid, timestamp with time zone, text[], jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_create_territory(p_territory_code text, p_name text, p_country_code text, p_territory_type text, p_timezone text, p_currency_label text, p_default_locale text, p_active_locales text[], p_owner_id uuid, p_executive_sponsor_id uuid, p_source_template_id uuid, p_target_launch_at timestamp with time zone, p_city_names text[], p_support jsonb, p_activation_strategy text, p_actor_id uuid, p_request_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_city text; v_contact text; v_payload jsonb;
begin
  insert into public.angelcare_marketplace_territories
    (territory_code,name,country_code,territory_type,timezone,currency_label,default_locale,active_locales,status,owner_id,executive_sponsor_id,source_template_id,target_launch_at,created_by,updated_by,metadata)
  values (upper(trim(p_territory_code)),trim(p_name),upper(trim(p_country_code)),p_territory_type,p_timezone,p_currency_label,p_default_locale,p_active_locales,'configuring',p_owner_id,p_executive_sponsor_id,p_source_template_id,p_target_launch_at,p_actor_id,p_actor_id,jsonb_build_object('activation_strategy',p_activation_strategy,'request_id',p_request_id))
  returning id into v_id;
  perform public.angelcare_marketplace_seed_territory_settings(v_id,'local',null,p_actor_id,false);
  update public.angelcare_marketplace_territory_settings set effective_value=to_jsonb(upper(trim(p_country_code))) where territory_id=v_id and setting_key='identity.country';
  update public.angelcare_marketplace_territory_settings set effective_value=to_jsonb(p_default_locale) where territory_id=v_id and setting_key='localization.default_locale';
  update public.angelcare_marketplace_territory_settings set effective_value=to_jsonb(p_active_locales) where territory_id=v_id and setting_key='localization.active_locales';
  update public.angelcare_marketplace_territory_settings set effective_value=to_jsonb(p_currency_label) where territory_id=v_id and setting_key='finance.currency_label';
  update public.angelcare_marketplace_territory_settings set effective_value=to_jsonb(p_timezone) where territory_id=v_id and setting_key='operations.timezone';
  foreach v_city in array coalesce(p_city_names,array[]::text[]) loop
    insert into public.angelcare_marketplace_territory_city_zones(territory_id,city_name,coverage_status,owner_id) values(v_id,trim(v_city),'planned',p_owner_id) on conflict do nothing;
  end loop;
  foreach v_contact in array array['public','operations','escalation'] loop
    v_payload:=coalesce(p_support->v_contact,'{}'::jsonb);
    if v_payload <> '{}'::jsonb then
      insert into public.angelcare_marketplace_territory_support_contacts(territory_id,contact_type,name,email,phone)
      values(v_id,v_contact,v_payload->>'name',v_payload->>'email',v_payload->>'phone') on conflict (territory_id,contact_type) do update set name=excluded.name,email=excluded.email,phone=excluded.phone;
    end if;
  end loop;
  if p_owner_id is not null then insert into public.angelcare_marketplace_territory_assignments(territory_id,app_user_id,assignment_role,assigned_by) values(v_id,p_owner_id,'territory_owner',p_actor_id) on conflict do nothing; end if;
  perform public.angelcare_marketplace_seed_territory_gates(v_id,p_actor_id);
  insert into public.angelcare_marketplace_territory_health_events(territory_id,event_key,category,severity,title,description,status,source,owner_id,created_by)
  values(v_id,'territory.created','governance','info','Territoire créé','Configuration et gates générées; aucun lancement n’est simulé.','resolved','territory-os',p_owner_id,p_actor_id);
  return v_id;
end $$;


--
-- Name: angelcare_marketplace_decide_approval(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_decide_approval(p_approval_id uuid, p_decision text, p_reason text, p_actor_id uuid) RETURNS public.angelcare_marketplace_approval_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_approval_requests;begin if p_decision not in('approved','rejected') then raise exception 'Invalid decision';end if;update public.angelcare_marketplace_approval_requests set status=p_decision,decision_reason=p_reason,decided_by=p_actor_id,decided_at=now(),updated_at=now() where id=p_approval_id and status in('submitted','in_review') returning * into r;if r.id is null then raise exception 'Approval is not decidable';end if;insert into public.angelcare_marketplace_approval_decisions(approval_id,decision,reason,actor_id)values(p_approval_id,p_decision,p_reason,p_actor_id);return r;end$$;


--
-- Name: angelcare_marketplace_decide_assignment_proposal(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_decide_assignment_proposal(p_proposal_id uuid, p_decision text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare p public.angelcare_marketplace_operations_assignment_proposals;m public.angelcare_marketplace_operations_missions;e public.angelcare_marketplace_provider_operational_eligibility;a public.angelcare_marketplace_operations_mission_assignments;begin select * into p from public.angelcare_marketplace_operations_assignment_proposals where id=p_proposal_id for update;if p.id is null then raise exception 'Proposal not found';end if;select * into m from public.angelcare_marketplace_operations_missions where id=p.mission_id for update;select * into e from public.angelcare_marketplace_provider_operational_eligibility where provider_id=p.provider_id order by calculated_at desc limit 1;if p_decision='accept' then if e.status not in('eligible','eligible_with_restrictions') or cardinality(p.conflicts)>0 then raise exception 'Provider is not assignable';end if;update public.angelcare_marketplace_operations_assignment_proposals set status='selected',decided_by=p_actor_id,decided_at=now(),decision_reason=p_reason where id=p.id;insert into public.angelcare_marketplace_operations_mission_assignments(mission_id,provider_id,proposal_id,status,assigned_by,territory_id,tenant_id) values(m.id,p.provider_id,p.id,'awaiting_acceptance',p_actor_id,m.territory_id,m.tenant_id) returning * into a;update public.angelcare_marketplace_operations_missions set assigned_provider_id=p.provider_id,status='awaiting_acceptance',updated_by=p_actor_id,updated_at=now() where id=m.id;update public.angelcare_marketplace_operations_assignment_proposals set status='rejected',decided_by=p_actor_id,decided_at=now(),decision_reason='Autre provider sélectionné' where mission_id=m.id and id<>p.id and status='proposed';else update public.angelcare_marketplace_operations_assignment_proposals set status='rejected',decided_by=p_actor_id,decided_at=now(),decision_reason=p_reason where id=p.id;end if;return jsonb_build_object('proposal',to_jsonb(p),'assignment',to_jsonb(a));end$$;


--
-- Name: angelcare_marketplace_decide_margin_exception(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_decide_margin_exception(p_exception_id uuid, p_decision text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_finance_margin_exceptions;begin if p_decision not in('approved','rejected') then raise exception 'Invalid decision';end if;update public.angelcare_marketplace_finance_margin_exceptions set status=p_decision,reviewed_by=p_actor_id,reviewed_at=now(),decision_reason=p_reason where id=p_exception_id and status='pending' returning * into r;if r.id is null then raise exception 'Pending exception introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_decide_payable_eligibility(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_decide_payable_eligibility(p_payable_id uuid, p_action text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_provider_payable_eligibility;target text;begin select * into r from public.angelcare_marketplace_provider_payable_eligibility where id=p_payable_id for update;if r.id is null then raise exception 'Payable eligibility not found';end if;if p_action='approve' then if r.status not in('eligible','pending_validation') or cardinality(r.blockers)>0 then raise exception 'Payable evidence is incomplete';end if;target:='approved';elsif p_action='hold' then target:='held';elsif p_action='dispute' then target:='disputed';elsif p_action='reverse' then target:='reversed';else raise exception 'Unsupported payable action';end if;update public.angelcare_marketplace_provider_payable_eligibility set status=target,reviewed_by=p_actor_id,reviewed_at=now(),review_reason=p_reason,updated_at=now() where id=r.id returning * into r;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_duplicate_footer_profile(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_duplicate_footer_profile(p_profile_id uuid, p_actor_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_source public.angelcare_marketplace_footer_profiles%rowtype;v_new_id uuid;v_key text;v_section record;v_new_section uuid;v_profile jsonb;
begin select * into v_source from public.angelcare_marketplace_footer_profiles where id=p_profile_id;if not found then raise exception 'Footer profile not found';end if;
v_key:=v_source.profile_key||'-copy-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISS');
insert into public.angelcare_marketplace_footer_profiles(profile_key,name,description,theme_id,parent_profile_id,status,is_default,locale_strategy,settings,brand,authority_statement,created_by,updated_by) values(v_key,v_source.name,v_source.description,v_source.theme_id,p_profile_id,'draft',false,v_source.locale_strategy,v_source.settings,v_source.brand,v_source.authority_statement,p_actor_id,p_actor_id) returning id into v_new_id;
for v_section in select * from public.angelcare_marketplace_footer_sections where profile_id=p_profile_id order by sort_order loop insert into public.angelcare_marketplace_footer_sections(profile_id,section_key,kind,title,description,eyebrow,icon_key,settings,targeting,contact_desk_keys,status,sort_order,column_span,mobile_default_open,locked,created_by,updated_by) values(v_new_id,v_section.section_key,v_section.kind,v_section.title,v_section.description,v_section.eyebrow,v_section.icon_key,v_section.settings,v_section.targeting,v_section.contact_desk_keys,v_section.status,v_section.sort_order,v_section.column_span,v_section.mobile_default_open,v_section.locked,p_actor_id,p_actor_id) returning id into v_new_section;insert into public.angelcare_marketplace_footer_links(section_id,link_key,label,href,link_type,open_new_tab,rel,visibility,analytics_key,status,sort_order,created_by,updated_by) select v_new_section,link_key,label,href,link_type,open_new_tab,rel,visibility,analytics_key,status,sort_order,p_actor_id,p_actor_id from public.angelcare_marketplace_footer_links where section_id=v_section.id;end loop;
select to_jsonb(p) into v_profile from public.angelcare_marketplace_footer_profiles p where p.id=v_new_id;return jsonb_build_object('record',v_profile);
end;$$;


--
-- Name: angelcare_marketplace_evaluate_financial_rule(uuid, text, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_evaluate_financial_rule(p_price_rule_id uuid, p_territory_currency text, p_proposed_margin numeric, p_discount_rate numeric, p_exception_approved boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_finance_price_rules;b public.angelcare_marketplace_finance_price_books;blockers text[]:='{}';begin select * into r from public.angelcare_marketplace_finance_price_rules where id=p_price_rule_id;select * into b from public.angelcare_marketplace_finance_price_books where id=r.price_book_id;if r.id is null or b.id is null then raise exception 'Price rule or price book introuvable';end if;if b.currency_label<>p_territory_currency then blockers:=array_append(blockers,'Territory currency mismatch');end if;if b.status<>'active' or r.status<>'active' then blockers:=array_append(blockers,'Price book or rule is not active');end if;if b.valid_from>current_date or (b.valid_until is not null and b.valid_until<current_date) then blockers:=array_append(blockers,'Price book outside validity window');end if;if p_proposed_margin<coalesce(r.floor_margin,0) and not p_exception_approved then blockers:=array_append(blockers,'Margin floor exception required');end if;if p_discount_rate>coalesce(r.maximum_discount,0) and not p_exception_approved then blockers:=array_append(blockers,'Maximum authorized discount exceeded');end if;if cardinality(blockers)>0 then raise exception 'Commercial rule blocked: %',array_to_string(blockers,'; ');end if;return jsonb_build_object('eligible',true,'priceRuleId',r.id,'priceBookId',b.id,'priceBookVersion',b.version,'territoryCurrency',p_territory_currency);end$$;


--
-- Name: angelcare_marketplace_evaluate_invoice_readiness(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_evaluate_invoice_readiness(p_source_type text, p_source_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_finance_revenue_streams;ready public.angelcare_marketplace_finance_invoice_readiness;missing text[]:='{}';blocks text[]:='{}';state text;begin select * into r from public.angelcare_marketplace_finance_revenue_streams where source_object_type=p_source_type and source_object_id=p_source_id;if r.id is null then raise exception 'Revenue stream introuvable';end if;if r.status not in('delivered','validated','invoice_ready') then blocks:=array_append(blocks,'Source delivery not validated');end if;if r.price_book_id is null or r.price_rule_id is null then missing:=array_append(missing,'Price-book lineage');end if;if r.margin_risk then blocks:=array_append(blocks,'Margin exception unresolved');end if;state:=case when cardinality(blocks)>0 then 'blocked' when cardinality(missing)>0 then 'evidence_required' else 'ready' end;insert into public.angelcare_marketplace_finance_invoice_readiness(revenue_stream_id,source_object_type,source_object_id,territory_id,tenant_id,currency_label,amount,status,required_evidence,missing_evidence,blockers,finance_owner_id,ready_at) values(r.id,p_source_type,p_source_id,r.territory_id,r.tenant_id,r.currency_label,r.net_amount,state,array['Price-book lineage','Delivery validation']::text[],missing,blocks,r.finance_owner_id,case when state='ready' then now() else null end) on conflict(source_object_type,source_object_id) do update set status=excluded.status,missing_evidence=excluded.missing_evidence,blockers=excluded.blockers,ready_at=excluded.ready_at,updated_at=now() returning * into ready;return to_jsonb(ready);end$$;


--
-- Name: angelcare_marketplace_footer_audit_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_footer_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_actor text;v_object_id text;
begin
v_actor:=coalesce(case when tg_op='DELETE' then old.updated_by else new.updated_by end,'system');
v_object_id:=coalesce(case when tg_op='DELETE' then old.id::text else new.id::text end,null);
insert into public.angelcare_marketplace_footer_audit_events(actor_id,action,object_type,object_id,before_value,after_value,metadata) values(v_actor,lower(tg_op),tg_table_name,v_object_id,case when tg_op='INSERT' then null else to_jsonb(old) end,case when tg_op='DELETE' then null else to_jsonb(new) end,jsonb_build_object('schema',tg_table_schema));
if tg_op='DELETE' then return old;end if;return new;
end;$$;


--
-- Name: angelcare_marketplace_footer_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_footer_snapshot(p_profile_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
select jsonb_build_object('profile',to_jsonb(p),'theme',to_jsonb(t),'sections',coalesce((select jsonb_agg(to_jsonb(s) || jsonb_build_object('links',coalesce((select jsonb_agg(to_jsonb(l) order by l.sort_order) from public.angelcare_marketplace_footer_links l where l.section_id=s.id),'[]'::jsonb)) order by s.sort_order) from public.angelcare_marketplace_footer_sections s where s.profile_id=p.id),'[]'::jsonb)) from public.angelcare_marketplace_footer_profiles p left join public.angelcare_marketplace_footer_themes t on t.id=p.theme_id where p.id=p_profile_id;
$$;


--
-- Name: angelcare_marketplace_generate_assignment_proposals(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_generate_assignment_proposals(p_mission_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare m public.angelcare_marketplace_operations_missions;inserted int;begin select * into m from public.angelcare_marketplace_operations_missions where id=p_mission_id;if m.id is null then raise exception 'Mission not found';end if;insert into public.angelcare_marketplace_operations_assignment_proposals(mission_id,provider_id,score,eligibility_snapshot,availability_snapshot,travel_snapshot,conflicts,status,proposed_by) select m.id,p.id,greatest(0,e.score-case when m.operational_zone is not null and not(m.operational_zone=any(p.operational_zones)) then 25 else 0 end),to_jsonb(e),jsonb_build_object('rules',coalesce((select count(*) from public.angelcare_marketplace_provider_availability_rules ar where ar.provider_id=p.id and ar.active),0)),jsonb_build_object('zone',m.operational_zone),case when m.operational_zone is not null and not(m.operational_zone=any(p.operational_zones)) then array['zone_mismatch']::text[] else '{}'::text[] end,'proposed',p_actor_id from public.angelcare_marketplace_provider_profiles p join lateral(select * from public.angelcare_marketplace_provider_operational_eligibility e where e.provider_id=p.id order by e.calculated_at desc limit 1)e on true where e.status in('eligible','eligible_with_restrictions') and (m.territory_id is null or p.territory_id=m.territory_id) and (m.tenant_id is null or p.tenant_id=m.tenant_id) and m.service_type=any(p.service_categories) on conflict do nothing;get diagnostics inserted=row_count;update public.angelcare_marketplace_operations_missions set status=case when inserted>0 then 'proposed' else 'staffing_required' end,updated_at=now() where id=m.id;return jsonb_build_object('mission_id',m.id,'proposals_created',inserted);end$$;


--
-- Name: angelcare_marketplace_mark_translations_stale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_mark_translations_stale() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ begin if old.source_hash is distinct from new.source_hash then new.source_version=old.source_version+1; new.last_changed_at=now(); new.freshness_state='changed'; insert into public.angelcare_marketplace_translation_versions(candidate_id,source_version,source_text_fr,source_hash,created_at) values(old.id,old.source_version,old.source_text_fr,old.source_hash,now()) on conflict do nothing; update public.angelcare_marketplace_translations set status='stale',freshness_state='translation_stale',updated_at=now() where candidate_id=old.id and status='published'; end if; return new; end $$;


--
-- Name: angelcare_marketplace_materialize_fulfillment_from_journey(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_materialize_fulfillment_from_journey() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$begin if new.status in('qualified','scheduled','in_preparation','in_progress') then insert into public.angelcare_marketplace_fulfillment_cases(journey_id,canonical_object_type,canonical_object_id,fulfillment_kind,title,status,priority,risk_level,tenant_id,territory_id,customer_id,organization_id,scheduled_start_at,scheduled_end_at,due_at,next_action,commercial_snapshot,customer_visibility) values(new.id,new.canonical_object_type,new.canonical_object_id,case new.journey_type when 'product_order' then 'product_order' when 'kit_order' then 'kit_order' when 'academy_enrollment' then 'academy_delivery' when 'b2b_quotation' then 'b2b_programme' when 'partner_activation' then 'partner_activation' when 'quality_assessment' then 'quality_assessment' when 'recurring_service' then 'recurring_service' else 'family_service' end,new.title,'commercially_confirmed','normal',new.risk_level,new.tenant_id,new.territory_id,new.owner_user_id,new.crm_account_id,new.scheduled_start_at,new.scheduled_end_at,new.next_action_due_at,new.next_action_label,jsonb_build_object('journey_reference',new.public_reference,'financial_status',new.financial_status),jsonb_build_object('journey_status',new.status)) on conflict(journey_id,canonical_object_type,canonical_object_id) do nothing;end if;return new;end$$;


--
-- Name: angelcare_marketplace_materialize_journey_from_conversion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_materialize_journey_from_conversion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
 s public.angelcare_marketplace_conversion_sessions%rowtype;
 item_name text;
 mapped_type text;
 v_journey_id uuid;
 owner_id uuid;
begin
 select * into s from public.angelcare_marketplace_conversion_sessions where id=new.session_id;
 if not found then return new; end if;
 select name_fr into item_name from public.angelcare_marketplace_catalog_items where id=s.catalog_item_id;
 mapped_type := case s.journey
  when 'product_checkout' then case when coalesce(s.metadata->>'item_kind','')='kit' then 'kit_order' else 'product_order' end
  when 'service_booking' then case when coalesce(s.configuration->>'frequency','') in('weekly','monthly','recurring') then 'recurring_service' else 'family_booking' end
  when 'academy_enrollment' then 'academy_enrollment'
  when 'partner_subscription' then 'partner_activation'
  when 'quality_assessment' then 'quality_assessment'
  else case
   when coalesce(s.configuration->>'vertical','')='hospitality' then 'hospitality_programme'
   when coalesce(s.configuration->>'vertical','')='corporate' then 'corporate_benefit'
   else 'b2b_quotation' end
 end;
 begin owner_id := nullif(s.identity_context->>'user_id','')::uuid; exception when others then owner_id := null; end;
 insert into public.angelcare_marketplace_journeys(
  journey_type,status,locale,title,subtitle,owner_user_id,family_account_id,crm_account_id,tenant_id,territory_id,
  conversion_outcome_id,canonical_object_type,canonical_object_id,current_authority,next_action_label,next_action_due_at,
  risk_level,completion_percent,financial_status,fulfillment_status,customer_context,metadata
 ) values(
  mapped_type,'registered',s.locale,coalesce(item_name,'Parcours ANGELCARE'),
  'Parcours post-conversion gouverné et relié à ses autorités canoniques.',owner_id,s.family_account_id,s.crm_account_id,s.tenant_id,s.territory_id,
  new.id,new.canonical_object_type,new.canonical_object_id,new.canonical_object_type,
  case when new.status='handover_pending' then 'Finaliser le handover ANGELCARE' else 'Consulter la confirmation' end,
  now()+interval '48 hours','low',10,
  jsonb_build_object('source','finance_authority','status','linked'),
  jsonb_build_object('source',new.canonical_object_type,'status',new.status),
  coalesce(s.identity_context,'{}'::jsonb),jsonb_build_object('conversion_session_id',s.id,'conversion_reference',s.public_reference)
 ) on conflict(conversion_outcome_id) do update set
  canonical_object_type=excluded.canonical_object_type,canonical_object_id=excluded.canonical_object_id,
  current_authority=excluded.current_authority,fulfillment_status=excluded.fulfillment_status,updated_at=now()
 returning id into v_journey_id;
 if not exists(select 1 from public.angelcare_marketplace_journey_events where journey_id=v_journey_id and event_key='conversion_confirmed') then
  insert into public.angelcare_marketplace_journey_events(journey_id,event_key,title,description,status,authority_type,authority_object_id,evidence,customer_visible)
  values(v_journey_id,'conversion_confirmed','Conversion confirmée','Le parcours a été matérialisé à partir d’une issue canonique de Conversion Universe.','registered','conversion-universe',new.id::text,jsonb_build_object('outcome_type',new.outcome_type,'public_reference',new.public_reference),true);
 end if;
 if not exists(select 1 from public.angelcare_marketplace_journey_actions where journey_id=v_journey_id and action_key='review_confirmation') then
  insert into public.angelcare_marketplace_journey_actions(journey_id,action_key,title,description,status,due_at,consequence,action_url,required_authority)
  values(v_journey_id,'review_confirmation','Vérifier la confirmation','Contrôlez les informations du parcours et signalez immédiatement toute divergence.','open',now()+interval '48 hours','Le parcours reste en attente de votre accusé.','/angelcare-marketplace/fr/account/journeys/'||v_journey_id,'customer');
 end if;
 if not exists(select 1 from public.angelcare_marketplace_journey_notifications where journey_id=v_journey_id and template_key='journey_created') then
  insert into public.angelcare_marketplace_journey_notifications(journey_id,channel,template_key,title,message,locale,status,deep_link)
  values(v_journey_id,'in_app','journey_created','Votre parcours ANGELCARE est ouvert','La conversion a été confirmée. Suivez les prochaines étapes dans Mon ANGELCARE.',s.locale,'queued','/angelcare-marketplace/'||s.locale||'/account/journeys/'||v_journey_id);
 end if;
 return new;
end;$$;


--
-- Name: angelcare_marketplace_operating_approval_decide(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operating_approval_decide(p_approval_id uuid, p_decision text, p_reason text, p_actor_id uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.angelcare_marketplace_operating_approvals;
begin
 if p_decision not in('approved','rejected','returned_for_rework','cancelled') then raise exception 'Unsupported approval decision'; end if;
 update public.angelcare_marketplace_operating_approvals set status=p_decision,decided_by=p_actor_id,decided_at=now(),decision_reason=p_reason,updated_at=now() where id=p_approval_id and status='pending' returning * into r;
 if r.id is null then raise exception 'Pending approval not found'; end if;
 insert into public.angelcare_marketplace_operating_timeline(case_id,event_kind,action,actor_id,reason,request_id,source,metadata) values(r.case_id,'approval','approval.'||p_decision,p_actor_id,p_reason,p_request_id,'operating-kernel',jsonb_build_object('approval_id',r.id,'approval_key',r.approval_key));
 return to_jsonb(r);
end$$;


--
-- Name: angelcare_marketplace_operating_assignment_set(uuid, text, uuid, text, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operating_assignment_set(p_case_id uuid, p_assignee_type text, p_assignee_id uuid, p_role_label text, p_reason text, p_due_at timestamp with time zone, p_actor_id uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.angelcare_marketplace_operating_assignments;
begin
 update public.angelcare_marketplace_operating_assignments set status='released',released_at=now() where case_id=p_case_id and status='active';
 insert into public.angelcare_marketplace_operating_assignments(case_id,assignee_type,assignee_id,role_label,status,assigned_by,due_at,reason) values(p_case_id,p_assignee_type,p_assignee_id,p_role_label,'active',p_actor_id,p_due_at,p_reason) returning * into r;
 update public.angelcare_marketplace_operating_cases set owner_id=case when p_assignee_type='user' then p_assignee_id else owner_id end,due_at=coalesce(p_due_at,due_at),updated_by=p_actor_id,updated_at=now() where id=p_case_id;
 insert into public.angelcare_marketplace_operating_timeline(case_id,event_kind,action,actor_id,reason,request_id,source,metadata) values(p_case_id,'assignment','case.assign',p_actor_id,p_reason,p_request_id,'operating-kernel',jsonb_build_object('assignee_type',p_assignee_type,'assignee_id',p_assignee_id,'role_label',p_role_label));
 return to_jsonb(r);
end$$;


--
-- Name: angelcare_marketplace_operating_case_ensure(text, text, uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operating_case_ensure(p_workspace_key text, p_entity_type text, p_entity_id uuid, p_title text, p_actor_id uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_territory_id uuid DEFAULT NULL::uuid, p_source_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.angelcare_marketplace_operating_cases;
begin
 insert into public.angelcare_marketplace_operating_cases(workspace_key,entity_type,entity_id,title,owner_id,tenant_id,territory_id,source_reference,created_by,updated_by)
 values(p_workspace_key,p_entity_type,p_entity_id,p_title,p_actor_id,p_tenant_id,p_territory_id,p_source_reference,p_actor_id,p_actor_id)
 on conflict(workspace_key,entity_type,entity_id) do update set title=excluded.title,updated_by=p_actor_id,updated_at=now()
 returning * into r;
 insert into public.angelcare_marketplace_operating_timeline(case_id,event_kind,action,actor_id,new_state,source,metadata)
 values(r.id,'case','case.ensure',p_actor_id,r.status,'operating-kernel',jsonb_build_object('workspace_key',p_workspace_key)) on conflict do nothing;
 return to_jsonb(r);
end$$;


--
-- Name: angelcare_marketplace_operating_case_transition(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operating_case_transition(p_case_id uuid, p_next_status text, p_reason text, p_actor_id uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.angelcare_marketplace_operating_cases; old_status text;
begin
 select * into r from public.angelcare_marketplace_operating_cases where id=p_case_id for update;
 if r.id is null then raise exception 'Operating case not found'; end if;
 old_status:=r.status;
 if old_status in('closed','cancelled') then raise exception 'Terminal operating case cannot transition'; end if;
 if p_next_status not in('open','intake','validation','qualified','ready','in_progress','evidence_pending','approval_pending','blocked','recovery','reconciled','closed','cancelled') then raise exception 'Unsupported operating case status'; end if;
 update public.angelcare_marketplace_operating_cases set status=p_next_status,closure_code=case when p_next_status='closed' then coalesce(closure_code,'completed') else closure_code end,closed_at=case when p_next_status='closed' then now() else null end,updated_by=p_actor_id,updated_at=now() where id=p_case_id returning * into r;
 insert into public.angelcare_marketplace_operating_timeline(case_id,event_kind,action,actor_id,previous_state,new_state,reason,request_id,source) values(p_case_id,'state','case.transition',p_actor_id,old_status,p_next_status,p_reason,p_request_id,'operating-kernel');
 return to_jsonb(r);
end$$;


--
-- Name: angelcare_marketplace_operating_exception_transition(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operating_exception_transition(p_exception_id uuid, p_next_status text, p_reason text, p_actor_id uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.angelcare_marketplace_operating_exceptions;
begin
 if p_next_status not in('open','triaged','owned','action_plan','resolved','verified','closed','cancelled') then raise exception 'Unsupported exception status'; end if;
 update public.angelcare_marketplace_operating_exceptions set status=p_next_status,resolution=case when p_next_status in('resolved','verified','closed') then p_reason else resolution end,resolved_by=case when p_next_status in('resolved','verified','closed') then p_actor_id else resolved_by end,resolved_at=case when p_next_status in('resolved','verified','closed') then now() else resolved_at end,updated_at=now() where id=p_exception_id returning * into r;
 if r.id is null then raise exception 'Operating exception not found'; end if;
 insert into public.angelcare_marketplace_operating_timeline(case_id,event_kind,action,actor_id,reason,request_id,source,metadata) values(r.case_id,'exception','exception.'||p_next_status,p_actor_id,p_reason,p_request_id,'operating-kernel',jsonb_build_object('exception_id',r.id,'exception_type',r.exception_type));
 return to_jsonb(r);
end$$;


--
-- Name: angelcare_marketplace_operating_timeline_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operating_timeline_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin raise exception 'Marketplace operating timeline is immutable';end$$;


--
-- Name: angelcare_marketplace_operations_reference(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_operations_reference(prefix text) RETURNS text
    LANGUAGE sql
    AS $$select upper(prefix)||'-'||to_char(now(),'YYMMDD')||'-'||upper(substr(encode(gen_random_bytes(5),'hex'),1,8))$$;


--
-- Name: angelcare_marketplace_prevent_wallet_ledger_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_prevent_wallet_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin raise exception 'AC Wallet ledger is immutable; create a compensating entry';end$$;


--
-- Name: angelcare_marketplace_public_trust_verification(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_public_trust_verification(p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_trust_badge_issuances;d public.angelcare_marketplace_trust_badge_definitions;begin select * into r from public.angelcare_marketplace_trust_badge_issuances where verification_reference=p_reference and status in('active','expiring');if r.id is null then return null;end if;select * into d from public.angelcare_marketplace_trust_badge_definitions where id=r.badge_definition_id;return jsonb_build_object('reference',r.verification_reference,'objectType',r.object_type,'title',d.name_fr,'status',r.status,'issuedAt',r.issued_at,'validUntil',r.valid_until,'issuer','ANGELCARE Trust Authority','publicClaims',to_jsonb(r.public_claims));end$$;


--
-- Name: angelcare_marketplace_publish_footer_profile(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_publish_footer_profile(p_profile_id uuid, p_actor_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_snapshot jsonb;v_version integer;v_version_id uuid;v_profile jsonb;
begin
select coalesce(max(version_number),0)+1 into v_version from public.angelcare_marketplace_footer_profile_versions where profile_id=p_profile_id;
v_snapshot:=public.angelcare_marketplace_footer_snapshot(p_profile_id);
if v_snapshot is null then raise exception 'Footer profile not found';end if;
insert into public.angelcare_marketplace_footer_profile_versions(profile_id,version_number,snapshot,change_summary,created_by) values(p_profile_id,v_version,v_snapshot,'Publication Footer Command Studio',p_actor_id) returning id into v_version_id;
update public.angelcare_marketplace_footer_profiles set status='published',version_number=v_version,published_at=now(),updated_at=now(),updated_by=p_actor_id where id=p_profile_id;
select to_jsonb(p) into v_profile from public.angelcare_marketplace_footer_profiles p where p.id=p_profile_id;
insert into public.angelcare_marketplace_footer_publications(profile_id,version_id,action,affected_routes,actor_id,evidence) values(p_profile_id,v_version_id,'publish',array['/angelcare-marketplace/fr','/angelcare-marketplace/en','/angelcare-marketplace/ar'],p_actor_id,jsonb_build_object('version',v_version));
return jsonb_build_object('record',v_profile,'versionId',v_version_id,'versionNumber',v_version);
end;$$;


--
-- Name: angelcare_marketplace_recalculate_enrollment_completion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_recalculate_enrollment_completion(p_enrollment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare e public.angelcare_marketplace_academy_enrollments;sessions_count int;present_count int;avg_score numeric;begin select * into e from public.angelcare_marketplace_academy_enrollments where id=p_enrollment_id for update;if e.id is null then raise exception 'Enrollment not found';end if;select count(*) into sessions_count from public.angelcare_marketplace_academy_sessions where cohort_id=e.cohort_id and status<>'cancelled';select count(*) into present_count from public.angelcare_marketplace_academy_attendance_records ar join public.angelcare_marketplace_academy_sessions s on s.id=ar.session_id where ar.enrollment_id=e.id and s.cohort_id=e.cohort_id and ar.status in('present','late','left_early');select coalesce(avg(score),0) into avg_score from public.angelcare_marketplace_academy_assessment_results where enrollment_id=e.id and status in('pending_review','approved');update public.angelcare_marketplace_academy_enrollments set attendance_rate=case when sessions_count=0 then 0 else round((present_count::numeric/sessions_count)*100,2) end,completion_score=round(avg_score,2),updated_at=now() where id=e.id returning * into e;return to_jsonb(e);end$$;


--
-- Name: angelcare_marketplace_recalculate_provider_eligibility(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_recalculate_provider_eligibility(p_provider_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare p public.angelcare_marketplace_provider_profiles;valid_docs int;expired_docs int;active_certs int;expired_certs int;critical_incidents int;score int;state text;blockers text[]:='{}';r public.angelcare_marketplace_provider_operational_eligibility;begin select * into p from public.angelcare_marketplace_provider_profiles where id=p_provider_id for update;if p.id is null then raise exception 'Provider not found';end if;select count(*) filter(where status='valid'),count(*) filter(where status in('expired','rejected')) into valid_docs,expired_docs from public.angelcare_marketplace_provider_documents where provider_id=p.id;select count(*) filter(where status in('active','issued','renewed','expiring')),count(*) filter(where status in('expired','suspended','revoked')) into active_certs,expired_certs from (
 select status from public.angelcare_marketplace_provider_certifications where provider_id=p.id
 union all
 select status from public.angelcare_marketplace_academy_certificates where learner_provider_id=p.id
) certification_evidence;begin select count(*) into critical_incidents from public.angelcare_marketplace_operations_incidents where provider_id=p.id and severity in('critical','emergency') and status not in('resolved','closed');exception when undefined_table then critical_incidents:=0;end;if p.operational_status='suspended' then blockers:=array_append(blockers,'provider_suspended');end if;if p.onboarding_status<>'completed' then blockers:=array_append(blockers,'onboarding_incomplete');end if;if expired_docs>0 then blockers:=array_append(blockers,'documents_expired_or_rejected');end if;if expired_certs>0 then blockers:=array_append(blockers,'certification_invalid');end if;if active_certs=0 then blockers:=array_append(blockers,'no_active_certification');end if;if critical_incidents>0 then blockers:=array_append(blockers,'critical_incident_open');end if;score:=greatest(0,100-(cardinality(blockers)*22));if p.operational_status='suspended' then state:='suspended';elsif critical_incidents>0 or expired_docs>0 then state:='temporarily_blocked';elsif cardinality(blockers)=0 then state:='eligible';elsif score>=60 then state:='eligible_with_restrictions';else state:='incomplete';end if;insert into public.angelcare_marketplace_provider_operational_eligibility(provider_id,status,eligible_services,eligible_age_groups,eligible_territories,restrictions,blockers,score,calculated_by,territory_id,tenant_id) values(p.id,state,case when state in('eligible','eligible_with_restrictions') then p.service_categories else '{}' end,case when state in('eligible','eligible_with_restrictions') then p.age_group_competencies else '{}' end,case when p.territory_id is null then '{}' else array[p.territory_id::text] end,jsonb_build_object('operational_zones',p.operational_zones),blockers,score,p_actor_id,p.territory_id,p.tenant_id) returning * into r;update public.angelcare_marketplace_provider_profiles set operational_status=case when state='eligible' then 'active' when state='eligible_with_restrictions' then 'restricted' when state='suspended' then 'suspended' else 'temporarily_blocked' end,updated_at=now(),updated_by=p_actor_id where id=p.id;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_recalculate_quality_assessment(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_recalculate_quality_assessment(p_assessment_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_quality_assessments;available numeric:=0;earned numeric:=0;critical_count int:=0;begin select coalesce(sum(c.weight) filter(where x.outcome not in('not_applicable','not_observed')),0),coalesce(sum(case when x.outcome='compliant' then c.weight when x.outcome='partially_compliant' then c.weight*.5 else 0 end),0),coalesce(count(*) filter(where x.outcome='critical_failure'),0) into available,earned,critical_count from public.angelcare_marketplace_quality_assessment_responses x join public.angelcare_marketplace_quality_assessment_criteria c on c.id=x.criterion_id where x.assessment_id=p_assessment_id;update public.angelcare_marketplace_quality_assessments set score=case when available>0 then round(earned/available*100,2) else 0 end,critical_failures=critical_count,risk_level=case when critical_count>0 then 'critical' when available=0 then 'unknown' when earned/available<.6 then 'high' when earned/available<.8 then 'moderate' else 'controlled' end,updated_at=now() where id=p_assessment_id returning * into r;if r.id is null then raise exception 'Quality Check 360 introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_record_assessment_result(uuid, uuid, numeric, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_record_assessment_result(p_assessment_id uuid, p_enrollment_id uuid, p_score numeric, p_evidence jsonb, p_evaluator_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare a public.angelcare_marketplace_academy_assessments;r public.angelcare_marketplace_academy_assessment_results;begin select * into a from public.angelcare_marketplace_academy_assessments where id=p_assessment_id;if a.id is null then raise exception 'Assessment not found';end if;insert into public.angelcare_marketplace_academy_assessment_results(assessment_id,enrollment_id,evaluator_id,score,passed,evidence,status) values(a.id,p_enrollment_id,p_evaluator_id,p_score,p_score>=a.passing_score,coalesce(p_evidence,'{}'),'pending_review') on conflict(assessment_id,enrollment_id) do update set evaluator_id=excluded.evaluator_id,score=excluded.score,passed=excluded.passed,evidence=excluded.evidence,status='pending_review',assessed_at=now() returning * into r;perform public.angelcare_marketplace_recalculate_enrollment_completion(p_enrollment_id);return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_corporate_quota_allocations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.angelcare_marketplace_corporate_quota_allocations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    program_id uuid NOT NULL,
    beneficiary_reference text NOT NULL,
    period_key text NOT NULL,
    allocated_quantity numeric(12,2) DEFAULT 0 NOT NULL,
    consumed_quantity numeric(12,2) DEFAULT 0 NOT NULL,
    reserved_quantity numeric(12,2) DEFAULT 0 NOT NULL,
    remaining_quantity numeric(12,2) GENERATED ALWAYS AS (GREATEST(((allocated_quantity - consumed_quantity) - reserved_quantity), (0)::numeric)) STORED,
    status text DEFAULT 'active'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT angelcare_marketplace_corporate_quota_allocations_check CHECK (((allocated_quantity >= (0)::numeric) AND (consumed_quantity >= (0)::numeric) AND (reserved_quantity >= (0)::numeric))),
    CONSTRAINT angelcare_marketplace_corporate_quota_allocations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'exhausted'::text, 'exception'::text, 'suspended'::text, 'expired'::text])))
);


--
-- Name: angelcare_marketplace_record_corporate_usage(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_record_corporate_usage(p_quota_id uuid, p_quantity numeric, p_service_reference text, p_actor_id uuid) RETURNS public.angelcare_marketplace_corporate_quota_allocations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare q public.angelcare_marketplace_corporate_quota_allocations;begin if p_quantity<=0 then raise exception 'Quantity must be positive';end if;select * into q from public.angelcare_marketplace_corporate_quota_allocations where id=p_quota_id for update;if q.id is null then raise exception 'Quota not found';end if;if q.status not in('active','exception') then raise exception 'Quota is not active';end if;if q.remaining_quantity<p_quantity then raise exception 'Insufficient quota';end if;insert into public.angelcare_marketplace_corporate_usage_records(organization_id,program_id,quota_id,beneficiary_reference,service_reference,quantity,status,actor_id) values(q.organization_id,q.program_id,q.id,q.beneficiary_reference,p_service_reference,p_quantity,'consumed',p_actor_id);update public.angelcare_marketplace_corporate_quota_allocations set consumed_quantity=consumed_quantity+p_quantity,status=case when remaining_quantity-p_quantity<=0 then 'exhausted' else status end,updated_at=now() where id=q.id returning * into q;return q;end$$;


--
-- Name: angelcare_marketplace_record_isolation_test(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_record_isolation_test(p_test_id uuid, p_observed_result text, p_evidence jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_security_isolation_tests;begin update public.angelcare_marketplace_security_isolation_tests set observed_result=p_observed_result,status=case when expected_result=p_observed_result then 'passed' else 'failed' end,evidence=p_evidence,executed_by=p_actor_id,executed_at=now() where id=p_test_id returning * into r;if r.id is null then raise exception 'Isolation test introuvable';end if;if r.status='failed' then insert into public.angelcare_marketplace_security_events(event_type,severity,status,territory_id,tenant_id,object_type,object_id,description,owner_id) values('isolation_test_failed','critical','open',r.territory_id,r.tenant_id,'security_isolation_test',r.id,'Expected '||r.expected_result||' but observed '||coalesce(r.observed_result,'null'),p_actor_id);end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_record_mission_check_event(uuid, text, uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_record_mission_check_event(p_mission_id uuid, p_event_type text, p_provider_user_id uuid, p_evidence_method text, p_location jsonb, p_device_context jsonb, p_exception_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare m public.angelcare_marketplace_operations_missions;p public.angelcare_marketplace_provider_profiles;e public.angelcare_marketplace_operations_check_events;begin select * into p from public.angelcare_marketplace_provider_profiles where canonical_app_user_id=p_provider_user_id;if p.id is null then raise exception 'Provider identity not resolved';end if;select * into m from public.angelcare_marketplace_operations_missions where id=p_mission_id and assigned_provider_id=p.id for update;if m.id is null then raise exception 'Provider is not assigned to mission';end if;if p_event_type='check_in' and m.status not in('check_in_pending','travel_ready','incident_open') then raise exception 'Mission is not ready for check-in';end if;if p_event_type='check_out' and m.status not in('in_progress','incident_open','check_out_pending') then raise exception 'Mission is not ready for check-out';end if;insert into public.angelcare_marketplace_operations_check_events(mission_id,provider_id,event_type,evidence_method,location,device_context,exception_reason,review_status,territory_id,tenant_id) values(m.id,p.id,p_event_type,p_evidence_method,coalesce(p_location,'{}'),coalesce(p_device_context,'{}'),p_exception_reason,case when p_exception_reason is null then 'accepted' else 'review_required' end,m.territory_id,m.tenant_id) on conflict(mission_id,provider_id,event_type) do update set event_at=now(),evidence_method=excluded.evidence_method,location=excluded.location,device_context=excluded.device_context,exception_reason=excluded.exception_reason,review_status=excluded.review_status returning * into e;update public.angelcare_marketplace_operations_missions set status=case when p_event_type='check_in' then 'in_progress' else 'report_pending' end,updated_at=now() where id=m.id;return to_jsonb(e);end$$;


--
-- Name: angelcare_marketplace_refresh_analytics(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_refresh_analytics(p_territory_id uuid, p_tenant_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare start_at timestamptz:=date_trunc('day',now());finish_at timestamptz:=now();n int:=0;begin insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'commercial.contracted_value',p_territory_id,p_tenant_id,start_at,finish_at,coalesce(sum(net_amount),0),count(*),1 from public.angelcare_marketplace_finance_revenue_streams where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status in('contracted','scheduled');n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'family.active_accounts',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_family_accounts where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'b2b.active_programs',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_b2b_programs where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status='active';n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'academy.completion_rate',p_territory_id,p_tenant_id,start_at,finish_at,case when count(*)=0 then 0 else count(*) filter(where status='completed')::numeric/count(*)*100 end,count(*),1 from public.angelcare_marketplace_academy_enrollments where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'providers.eligible_count',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_provider_operational_eligibility where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status in('eligible','eligible_with_restrictions');n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'operations.validated_missions',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_operations_missions where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status in('validated','payable_handover','closed');n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'trust.health_score',p_territory_id,p_tenant_id,start_at,finish_at,greatest(0,100-count(*) filter(where critical_flag)*15),count(*),1 from public.angelcare_marketplace_quality_findings;n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'finance.invoice_ready_value',p_territory_id,p_tenant_id,start_at,finish_at,coalesce(sum(amount),0),count(*),1 from public.angelcare_marketplace_finance_invoice_readiness where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status='ready';n:=n+1;return jsonb_build_object('snapshotsCreated',n,'calculatedAt',finish_at);end$$;


--
-- Name: angelcare_marketplace_restore_footer_profile(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_restore_footer_profile(p_profile_id uuid, p_version_id uuid, p_actor_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_snapshot jsonb;v_profile jsonb;v_sec jsonb;v_link jsonb;v_section_id uuid;
begin
select snapshot into v_snapshot from public.angelcare_marketplace_footer_profile_versions where id=p_version_id and profile_id=p_profile_id;
if v_snapshot is null then raise exception 'Footer version not found';end if;
update public.angelcare_marketplace_footer_profiles p set name=v_snapshot#>'{profile,name}',description=v_snapshot#>'{profile,description}',theme_id=nullif(v_snapshot#>>'{profile,theme_id}','')::uuid,settings=v_snapshot#>'{profile,settings}',brand=v_snapshot#>'{profile,brand}',authority_statement=v_snapshot#>>'{profile,authority_statement}',status='published',version_number=version_number+1,published_at=now(),updated_at=now(),updated_by=p_actor_id where p.id=p_profile_id;
update public.angelcare_marketplace_footer_sections set status='archived',updated_at=now(),updated_by=p_actor_id where profile_id=p_profile_id and section_key not in (select value->>'section_key' from jsonb_array_elements(coalesce(v_snapshot->'sections','[]'::jsonb)));
for v_sec in select value from jsonb_array_elements(coalesce(v_snapshot->'sections','[]'::jsonb)) loop
  insert into public.angelcare_marketplace_footer_sections(profile_id,section_key,kind,title,description,eyebrow,icon_key,settings,targeting,contact_desk_keys,status,sort_order,column_span,mobile_default_open,locked,updated_by)
  values(p_profile_id,v_sec->>'section_key',coalesce(v_sec->>'kind','directory'),coalesce(v_sec->'title','{}'::jsonb),coalesce(v_sec->'description','{}'::jsonb),coalesce(v_sec->'eyebrow','{}'::jsonb),nullif(v_sec->>'icon_key',''),coalesce(v_sec->'settings','{}'::jsonb),coalesce(v_sec->'targeting','{}'::jsonb),coalesce(array(select jsonb_array_elements_text(coalesce(v_sec->'contact_desk_keys','[]'::jsonb))),'{}'::text[]),coalesce(v_sec->>'status','active'),coalesce((v_sec->>'sort_order')::integer,10),coalesce((v_sec->>'column_span')::integer,1),coalesce((v_sec->>'mobile_default_open')::boolean,false),coalesce((v_sec->>'locked')::boolean,false),p_actor_id)
  on conflict(profile_id,section_key) do update set kind=excluded.kind,title=excluded.title,description=excluded.description,eyebrow=excluded.eyebrow,icon_key=excluded.icon_key,settings=excluded.settings,targeting=excluded.targeting,contact_desk_keys=excluded.contact_desk_keys,status=excluded.status,sort_order=excluded.sort_order,column_span=excluded.column_span,mobile_default_open=excluded.mobile_default_open,locked=excluded.locked,updated_by=p_actor_id,updated_at=now()
  returning id into v_section_id;
  update public.angelcare_marketplace_footer_links set status='archived',updated_at=now(),updated_by=p_actor_id where section_id=v_section_id and link_key not in (select value->>'link_key' from jsonb_array_elements(coalesce(v_sec->'links','[]'::jsonb)));
  for v_link in select value from jsonb_array_elements(coalesce(v_sec->'links','[]'::jsonb)) loop
    insert into public.angelcare_marketplace_footer_links(section_id,link_key,label,href,link_type,open_new_tab,rel,visibility,analytics_key,status,sort_order,updated_by)
    values(v_section_id,v_link->>'link_key',coalesce(v_link->'label','{}'::jsonb),v_link->>'href',coalesce(v_link->>'link_type','internal'),coalesce((v_link->>'open_new_tab')::boolean,false),coalesce(array(select jsonb_array_elements_text(coalesce(v_link->'rel','[]'::jsonb))),'{}'::text[]),coalesce(v_link->'visibility','{}'::jsonb),nullif(v_link->>'analytics_key',''),coalesce(v_link->>'status','active'),coalesce((v_link->>'sort_order')::integer,10),p_actor_id)
    on conflict(section_id,link_key) do update set label=excluded.label,href=excluded.href,link_type=excluded.link_type,open_new_tab=excluded.open_new_tab,rel=excluded.rel,visibility=excluded.visibility,analytics_key=excluded.analytics_key,status=excluded.status,sort_order=excluded.sort_order,updated_by=p_actor_id,updated_at=now();
  end loop;
end loop;
select to_jsonb(p) into v_profile from public.angelcare_marketplace_footer_profiles p where p.id=p_profile_id;
insert into public.angelcare_marketplace_footer_publications(profile_id,version_id,action,affected_routes,actor_id,evidence) values(p_profile_id,p_version_id,'restore',array['/angelcare-marketplace/fr','/angelcare-marketplace/en','/angelcare-marketplace/ar'],p_actor_id,jsonb_build_object('restoredFrom',p_version_id,'dataPreserved',true));
return jsonb_build_object('record',v_profile);
end;$$;


--
-- Name: angelcare_marketplace_cms_pages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.angelcare_marketplace_cms_pages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    public_reference text DEFAULT ('PGE-'::text || upper(substr(replace((gen_random_uuid())::text, '-'::text, ''::text), 1, 10))) NOT NULL,
    route_key text NOT NULL,
    locale text DEFAULT 'fr'::text NOT NULL,
    territory_id uuid,
    title text NOT NULL,
    navigation_label text,
    slug text NOT NULL,
    description text,
    status text DEFAULT 'draft'::text NOT NULL,
    translation_status text DEFAULT 'source'::text NOT NULL,
    sensitive boolean DEFAULT false NOT NULL,
    owner_id uuid,
    reviewer_id uuid,
    current_version integer DEFAULT 1 NOT NULL,
    published_version integer,
    seo_title text,
    seo_description text,
    canonical_url text,
    scheduled_at timestamp with time zone,
    published_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT angelcare_marketplace_cms_pages_locale_check CHECK ((locale = ANY (ARRAY['fr'::text, 'en'::text, 'ar'::text]))),
    CONSTRAINT angelcare_marketplace_cms_pages_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'in_review'::text, 'approved'::text, 'scheduled'::text, 'published'::text, 'retired'::text, 'archived'::text]))),
    CONSTRAINT angelcare_marketplace_cms_pages_translation_status_check CHECK ((translation_status = ANY (ARRAY['source'::text, 'missing'::text, 'draft'::text, 'reviewed'::text, 'approved'::text, 'stale'::text])))
);


--
-- Name: angelcare_marketplace_rollback_cms_page(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_rollback_cms_page(p_page_id uuid, p_version_number integer, p_reason text, p_actor_id uuid) RETURNS public.angelcare_marketplace_cms_pages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare v public.angelcare_marketplace_cms_page_versions; r public.angelcare_marketplace_cms_pages;begin select * into v from public.angelcare_marketplace_cms_page_versions where page_id=p_page_id and version_number=p_version_number;if v.id is null then raise exception 'Version not found';end if;update public.angelcare_marketplace_cms_pages set title=v.title,description=v.description,slug=v.slug,current_version=current_version+1,status='draft',updated_by=p_actor_id,updated_at=now() where id=p_page_id returning * into r;delete from public.angelcare_marketplace_cms_blocks where page_id=p_page_id;insert into public.angelcare_marketplace_cms_blocks(page_id,block_key,block_type,sort_order,status,content,settings,audience,territory_id,locale) select p_page_id,x->>'block_key',x->>'block_type',coalesce((x->>'sort_order')::int,0),coalesce(x->>'status','active'),coalesce(x->'content','{}'),coalesce(x->'settings','{}'),coalesce(array(select jsonb_array_elements_text(coalesce(x->'audience','[]'::jsonb))),'{}'),r.territory_id,r.locale from jsonb_array_elements(coalesce(v.snapshot->'blocks','[]'::jsonb))x;insert into public.angelcare_marketplace_cms_publication_jobs(page_id,action,status,blocker,requested_by,completed_at)values(p_page_id,'rollback','completed',p_reason,p_actor_id,now());return r;end$$;


--
-- Name: angelcare_marketplace_seed_territory_gates(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_seed_territory_gates(p_territory_id uuid, p_actor_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.angelcare_marketplace_territory_launch_checks
    (territory_id,gate_key,gate_group,title,description,requirement_level,status,score_weight,owner_role,evidence_required,next_action,sort_order)
  values
    (p_territory_id,'localization.complete','localization','Localisation complète','FR/EN/AR actifs selon le territoire, textes sensibles sans fallback.','mandatory_blocking','not_started',10,'marketplace_localization_manager',true,'Confirmer les langues et les preuves de traduction.',10),
    (p_territory_id,'legal.pages.approved','legal','Pages légales approuvées','Mentions et pages légales locales approuvées.','mandatory_blocking','not_started',10,'marketplace_quality_reviewer',true,'Joindre la validation juridique.',20),
    (p_territory_id,'trust.center.approved','trust','Trust Center approuvé','Preuves, SOP et frontières de service confirmées.','mandatory_blocking','not_started',10,'marketplace_quality_reviewer',true,'Valider les preuves de confiance.',30),
    (p_territory_id,'catalog.ready','catalog','Catalogue prêt','Disponibilités territoriales et exclusions documentées.','mandatory_blocking','not_started',8,'marketplace_catalog_manager',true,'Publier la matrice catalogue.',40),
    (p_territory_id,'price_book.ready','pricing','Price book prêt','Devise, quote mode et règles financières approuvés.','mandatory_blocking','not_started',10,'marketplace_finance_reviewer',true,'Valider le price book local.',50),
    (p_territory_id,'operations.zones.ready','operations','Zones opérationnelles prêtes','Villes, couverture et capacité initiale confirmées.','mandatory_blocking','not_started',12,'marketplace_operations_lead',true,'Confirmer les zones et la capacité.',60),
    (p_territory_id,'support.route.ready','support','Support prêt','Contacts public, opérations et escalade actifs.','mandatory_blocking','not_started',10,'marketplace_territory_director',true,'Tester les routes de support.',70),
    (p_territory_id,'analytics.active','analytics','Analytics actifs','Événements et santé territoire observables.','mandatory_non_blocking','not_started',6,'marketplace_admin',true,'Confirmer la collecte analytique.',80),
    (p_territory_id,'security.reviewed','security','Sécurité revue','Scopes, accès et tests de non-fuite validés.','mandatory_blocking','not_started',12,'marketplace_security',true,'Joindre la revue de sécurité.',90),
    (p_territory_id,'backup.monitoring.prepared','continuity','Backup & monitoring prêts','Surveillance, support et continuité préparés.','mandatory_blocking','not_started',8,'marketplace_security',true,'Documenter monitoring et reprise.',100),
    (p_territory_id,'executive.approval.recorded','governance','Approbation exécutive','Décision finale enregistrée après les gates.','mandatory_blocking','not_started',4,'marketplace_executive',true,'Enregistrer le sign-off exécutif.',110)
  on conflict (territory_id,gate_key) do nothing;
end $$;


--
-- Name: angelcare_marketplace_seed_territory_settings(uuid, text, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_seed_territory_settings(p_territory_id uuid, p_source_type text, p_source_id uuid, p_actor_id uuid, p_locked boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.angelcare_marketplace_territory_settings
    (territory_id,setting_key,category,label,description,source_type,source_id,source_version,inheritance_mode,is_locked,local_override_allowed,effective_value,owner_id,updated_by)
  select p_territory_id,v.key,v.category,v.label,v.description,p_source_type,p_source_id,1,
         case when p_locked then 'locked_global' else case when p_source_type='local' then 'local_default' else 'inherited_snapshot' end end,
         p_locked,not p_locked,v.value,p_actor_id,p_actor_id
  from (values
    ('identity.country','identity','Pays','Code pays officiel','null'::jsonb),
    ('localization.default_locale','localization','Langue par défaut','Locale principale du territoire','"fr"'::jsonb),
    ('localization.active_locales','localization','Langues actives','Langues autorisées','["fr"]'::jsonb),
    ('finance.currency_label','finance','Libellé devise','Libellé visible dans le territoire','"Dh"'::jsonb),
    ('operations.timezone','operations','Fuseau horaire','Fuseau canonique','"Africa/Casablanca"'::jsonb),
    ('catalog.availability','catalog','Disponibilité catalogue','État contractuel du catalogue','{"status":"not_installed"}'::jsonb),
    ('pricing.price_book','pricing','Price book','État contractuel du price book','{"status":"not_installed"}'::jsonb),
    ('trust.center','trust','Trust Center','État contractuel du Trust Center','{"status":"not_installed"}'::jsonb),
    ('support.routing','support','Support route','Configuration du support','{"status":"configuration_required"}'::jsonb),
    ('security.scope_policy','security','Politique de scope','Protection inter-territoire','{"mode":"deny_by_default"}'::jsonb)
  ) as v(key,category,label,description,value)
  on conflict (territory_id,setting_key) do nothing;
end $$;


--
-- Name: angelcare_marketplace_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$;


--
-- Name: angelcare_marketplace_transition_b2b_diagnostic(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_b2b_diagnostic(p_diagnostic_id uuid, p_target_status text, p_reason text, p_actor_id uuid) RETURNS public.angelcare_marketplace_b2b_diagnostics
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_b2b_diagnostics;begin update public.angelcare_marketplace_b2b_diagnostics set status=p_target_status,reviewed_at=case when p_target_status in('qualified','not_qualified') then now() else reviewed_at end,submitted_at=case when p_target_status='submitted' then now() else submitted_at end,next_action=coalesce(nullif(p_reason,''),next_action),updated_by=p_actor_id,updated_at=now(),version=version+1 where id=p_diagnostic_id returning * into r;if r.id is null then raise exception 'Diagnostic not found';end if;return r;end$$;


--
-- Name: angelcare_marketplace_b2b_programs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.angelcare_marketplace_b2b_programs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    public_reference text DEFAULT ('PROG-'::text || upper(substr(replace((gen_random_uuid())::text, '-'::text, ''::text), 1, 10))) NOT NULL,
    organization_id uuid NOT NULL,
    request_id uuid,
    vertical text NOT NULL,
    program_type text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'configuration'::text NOT NULL,
    territory_id uuid,
    tenant_id uuid,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    capacity integer,
    owner_id uuid,
    readiness_score integer DEFAULT 0 NOT NULL,
    risk_level text DEFAULT 'normal'::text NOT NULL,
    next_action text,
    configuration jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT angelcare_marketplace_b2b_programs_readiness_score_check CHECK (((readiness_score >= 0) AND (readiness_score <= 100))),
    CONSTRAINT angelcare_marketplace_b2b_programs_risk_level_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT angelcare_marketplace_b2b_programs_status_check CHECK ((status = ANY (ARRAY['configuration'::text, 'readiness_review'::text, 'approved'::text, 'scheduled'::text, 'active'::text, 'paused'::text, 'completed'::text, 'suspended'::text, 'archived'::text]))),
    CONSTRAINT angelcare_marketplace_b2b_programs_vertical_check CHECK ((vertical = ANY (ARRAY['establishment'::text, 'hospitality'::text, 'health_partner'::text, 'corporate'::text])))
);


--
-- Name: angelcare_marketplace_transition_b2b_program(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_b2b_program(p_program_id uuid, p_target_status text, p_reason text, p_actor_id uuid) RETURNS public.angelcare_marketplace_b2b_programs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_b2b_programs;begin update public.angelcare_marketplace_b2b_programs set status=p_target_status,next_action=coalesce(nullif(p_reason,''),next_action),updated_by=p_actor_id,updated_at=now() where id=p_program_id returning * into r;if r.id is null then raise exception 'Program not found';end if;return r;end$$;


--
-- Name: angelcare_marketplace_transition_capa(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_capa(p_action_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_quality_corrective_actions;begin if p_next_status='closed' and not exists(select 1 from public.angelcare_marketplace_quality_effectiveness_reviews where action_id=p_action_id and decision='effective') then raise exception 'Effectiveness review required before closure';end if;update public.angelcare_marketplace_quality_corrective_actions set status=p_next_status,closed_by=case when p_next_status='closed' then p_actor_id else closed_by end,closed_at=case when p_next_status='closed' then now() else closed_at end,updated_at=now() where id=p_action_id returning * into r;if r.id is null then raise exception 'CAPA introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_certificate(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_certificate(p_certificate_id uuid, p_action text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.angelcare_marketplace_academy_certificates;e public.angelcare_marketplace_academy_enrollments;course public.angelcare_marketplace_academy_courses;target text;previous_status text;
begin
 select * into c from public.angelcare_marketplace_academy_certificates where id=p_certificate_id for update;
 if c.id is null then raise exception 'Certificate not found';end if;
 previous_status:=c.status;
 select * into e from public.angelcare_marketplace_academy_enrollments where id=c.enrollment_id;
 select * into course from public.angelcare_marketplace_academy_courses where id=c.course_id;
 if p_action='issue' then
  if e.attendance_rate<course.attendance_threshold or e.completion_score<course.passing_score or e.status not in('completed','active') then raise exception 'Certificate eligibility evidence is incomplete';end if;
  target:='active';
  update public.angelcare_marketplace_academy_certificates set status=target,issued_at=coalesce(issued_at,now()),valid_from=coalesce(valid_from,now()),expires_at=case when course.certificate_validity_days is null then expires_at else coalesce(expires_at,now()+make_interval(days=>course.certificate_validity_days)) end,expiry_bucket=case when course.certificate_validity_days is null then 'none' when course.certificate_validity_days<=30 then 'next_30_days' else 'future' end,approved_by=p_actor_id,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 elsif p_action='suspend' then
  target:='suspended';update public.angelcare_marketplace_academy_certificates set status=target,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 elsif p_action='revoke' then
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'revocation_reason is required';end if;
  target:='revoked';update public.angelcare_marketplace_academy_certificates set status=target,revocation_reason=p_reason,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 elsif p_action='renew' then
  if c.status not in('active','expiring','expired') then raise exception 'Certificate is not renewable from current status';end if;
  target:='renewed';update public.angelcare_marketplace_academy_certificates set status=target,valid_from=now(),expires_at=case when course.certificate_validity_days is null then expires_at else now()+make_interval(days=>course.certificate_validity_days) end,expiry_bucket=case when course.certificate_validity_days is null then 'none' when course.certificate_validity_days<=30 then 'next_30_days' else 'future' end,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 else raise exception 'Unsupported certificate action';end if;
 insert into public.angelcare_marketplace_academy_certificate_events(certificate_id,event_type,from_status,to_status,reason,actor_id,evidence) values(c.id,p_action,previous_status,target,p_reason,p_actor_id,jsonb_build_object('enrollment_id',c.enrollment_id,'source_version',c.updated_at));
 if c.learner_provider_id is not null then
  begin perform public.angelcare_marketplace_recalculate_provider_eligibility(c.learner_provider_id,p_actor_id);exception when undefined_function or undefined_table then null;end;
 end if;
 return to_jsonb(c);
end$$;


--
-- Name: angelcare_marketplace_transition_cms_page(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_cms_page(p_page_id uuid, p_target_status text, p_reason text, p_actor_id uuid) RETURNS public.angelcare_marketplace_cms_pages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_cms_pages; current_status text;begin select status into current_status from public.angelcare_marketplace_cms_pages where id=p_page_id for update;if current_status is null then raise exception 'Page not found';end if;if p_target_status='published' and current_status not in('approved','scheduled') then raise exception 'Page is not publishable';end if;if p_target_status='approved' and current_status not in('submitted','in_review') then raise exception 'Page is not approvable';end if;update public.angelcare_marketplace_cms_pages set status=p_target_status,updated_by=p_actor_id,updated_at=now(),published_at=case when p_target_status='published' then now() else published_at end,published_version=case when p_target_status='published' then current_version else published_version end where id=p_page_id returning * into r;insert into public.angelcare_marketplace_cms_page_versions(page_id,version_number,title,description,slug,status,snapshot,change_summary,created_by) select id,current_version,title,description,slug,p_target_status,jsonb_build_object('page',to_jsonb(p.*),'blocks',coalesce((select jsonb_agg(to_jsonb(b) order by b.sort_order) from public.angelcare_marketplace_cms_blocks b where b.page_id=p_page_id),'[]'::jsonb)),p_reason,p_actor_id from public.angelcare_marketplace_cms_pages p where id=p_page_id on conflict(page_id,version_number) do update set snapshot=excluded.snapshot,status=excluded.status,change_summary=excluded.change_summary;insert into public.angelcare_marketplace_cms_publication_jobs(page_id,action,status,scheduled_at,requested_by,approved_by) values(p_page_id,case when p_target_status='published' then 'publish' else 'unpublish' end,case when p_target_status='published' then 'completed' else 'ready' end,case when p_target_status='scheduled' then r.scheduled_at else null end,p_actor_id,case when p_target_status in('approved','published') then p_actor_id else null end);return r;end$$;


--
-- Name: angelcare_marketplace_transition_complaint(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_complaint(p_complaint_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_complaints;begin update public.angelcare_marketplace_complaints set status=p_next_status,next_action=case when p_next_status='triaged' then 'Assigner un investigator et confirmer le SLA.' when p_next_status='resolved' then 'Communiquer la résolution et ouvrir la période d’appel.' when p_next_status='closed' then null else next_action end,updated_at=now() where id=p_complaint_id returning * into r;if r.id is null then raise exception 'Plainte introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_operations_mission(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_operations_mission(p_mission_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare m public.angelcare_marketplace_operations_missions;allowed boolean:=false;begin select * into m from public.angelcare_marketplace_operations_missions where id=p_mission_id for update;if m.id is null then raise exception 'Mission not found';end if;allowed:=case m.status when 'draft' then p_next_status in('awaiting_authorization','cancelled') when 'awaiting_authorization' then p_next_status in('authorized','draft','cancelled') when 'authorized' then p_next_status in('staffing_required','cancelled','suspended') when 'staffing_required' then p_next_status in('proposed','cancelled','suspended') when 'proposed' then p_next_status in('assigned','staffing_required','cancelled') when 'assigned' then p_next_status in('awaiting_acceptance','staffing_required','cancelled') when 'awaiting_acceptance' then p_next_status in('accepted','staffing_required','cancelled') when 'accepted' then p_next_status in('brief_acknowledged','cancelled','suspended') when 'brief_acknowledged' then p_next_status in('travel_ready','suspended') when 'travel_ready' then p_next_status in('check_in_pending','suspended') when 'check_in_pending' then p_next_status in('in_progress','incident_open','suspended') when 'in_progress' then p_next_status in('incident_open','check_out_pending','suspended') when 'incident_open' then p_next_status in('in_progress','check_out_pending','suspended') when 'check_out_pending' then p_next_status in('report_pending','incident_open') when 'report_pending' then p_next_status in('validation_pending','incident_open') when 'validation_pending' then p_next_status in('correction_required','validated','incident_open') when 'correction_required' then p_next_status in('validation_pending','incident_open') when 'validated' then p_next_status in('payable_handover','closed') when 'payable_handover' then p_next_status='closed' when 'suspended' then p_next_status in('staffing_required','accepted','in_progress','cancelled') else false end;if not allowed then raise exception 'Invalid mission transition % -> %',m.status,p_next_status;end if;if p_next_status='accepted' and not exists(select 1 from public.angelcare_marketplace_operations_mission_assignments where mission_id=m.id and status='accepted') then raise exception 'Provider acceptance is missing';end if;if p_next_status='brief_acknowledged' and not exists(select 1 from public.angelcare_marketplace_operations_brief_acknowledgements where mission_id=m.id) then raise exception 'Brief acknowledgement is missing';end if;if p_next_status='in_progress' and not exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_in') then raise exception 'Check-in evidence is missing';end if;if p_next_status='report_pending' and not exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_out') then raise exception 'Check-out evidence is missing';end if;if p_next_status='validated' and not exists(select 1 from public.angelcare_marketplace_operations_mission_reports where mission_id=m.id and status in('validated','published')) then raise exception 'Validated report is missing';end if;update public.angelcare_marketplace_operations_missions set status=p_next_status,next_action=p_reason,authorized_at=case when p_next_status='authorized' then now() else authorized_at end,validated_at=case when p_next_status='validated' then now() else validated_at end,closed_at=case when p_next_status='closed' then now() else closed_at end,updated_by=p_actor_id,updated_at=now() where id=m.id returning * into m;if p_next_status='payable_handover' then insert into public.angelcare_marketplace_provider_payable_eligibility(provider_id,mission_id,status,checklist,blockers,territory_id,tenant_id) select m.assigned_provider_id,m.id,'eligible',jsonb_build_object('authorized',m.authorized_at is not null,'accepted',exists(select 1 from public.angelcare_marketplace_operations_mission_assignments where mission_id=m.id and status='accepted'),'check_in',exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_in'),'check_out',exists(select 1 from public.angelcare_marketplace_operations_check_events where mission_id=m.id and event_type='check_out'),'report_validated',m.validated_at is not null),'{}',m.territory_id,m.tenant_id where m.assigned_provider_id is not null on conflict(provider_id,mission_id) do update set status='eligible',checklist=excluded.checklist,blockers='{}',updated_at=now();end if;return to_jsonb(m);end$$;


--
-- Name: angelcare_marketplace_transition_price_book(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_price_book(p_price_book_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_finance_price_books;begin if p_next_status='active' and exists(select 1 from public.angelcare_marketplace_finance_price_books b join public.angelcare_marketplace_finance_price_books c on c.id=p_price_book_id where b.id<>c.id and b.status='active' and b.territory_id is not distinct from c.territory_id and b.market_segment=c.market_segment and b.customer_type=c.customer_type) then raise exception 'An active price book already covers this scope';end if;update public.angelcare_marketplace_finance_price_books set status=p_next_status,approved_by=case when p_next_status='approved' then p_actor_id else approved_by end,approved_at=case when p_next_status='approved' then now() else approved_at end,updated_by=p_actor_id,updated_at=now() where id=p_price_book_id returning * into r;if r.id is null then raise exception 'Price book introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_qa_defect(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_qa_defect(p_defect_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_qa_defects;begin if p_next_status='closed' and not exists(select 1 from public.angelcare_marketplace_qa_defects where id=p_defect_id and status='verified') then raise exception 'Defect must be verified before closure';end if;update public.angelcare_marketplace_qa_defects set status=p_next_status,reviewer_id=case when p_next_status in('verified','closed') then p_actor_id else reviewer_id end,verified_at=case when p_next_status='verified' then now() else verified_at end,updated_at=now() where id=p_defect_id returning * into r;if r.id is null then raise exception 'Defect introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_quality_assessment(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_quality_assessment(p_assessment_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_quality_assessments;begin update public.angelcare_marketplace_quality_assessments set status=p_next_status,approved_by=case when p_next_status='approved' then p_actor_id else approved_by end,approved_at=case when p_next_status='approved' then now() else approved_at end,updated_at=now() where id=p_assessment_id returning * into r;if r.id is null then raise exception 'Assessment introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_recovery_test(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_recovery_test(p_test_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_recovery_tests;begin if p_next_status='validated' and not exists(select 1 from public.angelcare_marketplace_recovery_tests where id=p_test_id and actual_recovery_point_minutes is not null and actual_recovery_time_minutes is not null and evidence<>'{}'::jsonb) then raise exception 'Recovery metrics and evidence required';end if;update public.angelcare_marketplace_recovery_tests set status=p_next_status,authorized_by=case when p_next_status='authorized' then p_actor_id else authorized_by end,executed_by=case when p_next_status='in_progress' then p_actor_id else executed_by end,validated_by=case when p_next_status in('validated','approved') then p_actor_id else validated_by end,started_at=case when p_next_status='in_progress' then now() else started_at end,completed_at=case when p_next_status in('validated','failed','approved','closed') then now() else completed_at end,next_action=p_reason,updated_at=now() where id=p_test_id returning * into r;if r.id is null then raise exception 'Recovery test introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_release_candidate(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_release_candidate(p_release_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_qa_release_candidates;blocking int;begin if p_next_status='approved_for_controlled_release' then select count(*) into blocking from public.angelcare_marketplace_launch_gates where requirement_level='mandatory_blocking' and status<>'passed';blocking:=blocking+(select count(*) from public.angelcare_marketplace_qa_defects where critical_flag);if blocking>0 then raise exception 'Release blocked by % mandatory gates or critical defects',blocking;end if;if not exists(select 1 from public.angelcare_marketplace_launch_runbooks where release_candidate_id=p_release_id and status='approved') then raise exception 'Approved launch runbook required';end if;end if;update public.angelcare_marketplace_qa_release_candidates set status=p_next_status,approved_at=case when p_next_status='approved_for_controlled_release' then now() else approved_at end,launched_at=case when p_next_status='controlled_release' then now() else launched_at end,paused_at=case when p_next_status='paused' then now() else paused_at end,rolled_back_at=case when p_next_status='rolled_back' then now() else rolled_back_at end,rollback_reason=case when p_next_status='rolled_back' then p_reason else rollback_reason end,updated_at=now() where id=p_release_id returning * into r;if r.id is null then raise exception 'Release candidate introuvable';end if;insert into public.angelcare_marketplace_launch_events(release_candidate_id,event_type,severity,status,description,actor_id) values(p_release_id,'release.'||p_next_status,case when p_next_status in('rolled_back','paused') then 'critical' else 'info' end,'recorded',coalesce(p_reason,p_next_status),p_actor_id);return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_transition_sop(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_transition_sop(p_sop_id uuid, p_next_status text, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_trust_sops;begin update public.angelcare_marketplace_trust_sops set status=p_next_status,next_action=case when p_next_status='effective' then 'Planifier la revue et les acknowledgements.' when p_next_status in('suspended','expired') then 'Retirer des sélections opérationnelles.' else next_action end,effective_at=case when p_next_status='effective' then coalesce(effective_at,now()) else effective_at end,updated_by=p_actor_id,updated_at=now() where id=p_sop_id returning * into r;if r.id is null then raise exception 'SOP introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_update_launch_gate(uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_update_launch_gate(p_gate_id uuid, p_status text, p_evidence jsonb, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$declare r public.angelcare_marketplace_launch_gates;begin if p_status='passed' and exists(select 1 from public.angelcare_marketplace_launch_gates where id=p_gate_id and evidence_required and not exists(select 1 from public.angelcare_marketplace_launch_evidence e where e.gate_id=p_gate_id and e.status='approved')) then raise exception 'Approved evidence required';end if;update public.angelcare_marketplace_launch_gates set status=p_status,score=case when p_status='passed' then 100 when p_status='conditionally_passed' then 80 else score end,blocker_reason=case when p_status in('failed','blocked') then p_reason else null end,evidence_count=(select count(*) from public.angelcare_marketplace_launch_evidence e where e.gate_id=p_gate_id and e.status='approved'),last_validated_at=now(),updated_by=p_actor_id,updated_at=now() where id=p_gate_id returning * into r;if r.id is null then raise exception 'Launch gate introuvable';end if;return to_jsonb(r);end$$;


--
-- Name: angelcare_marketplace_wallet_commit_reservation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_wallet_commit_reservation(p_reservation_id uuid, p_order_reference text, p_payment_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_res record;v_item jsonb;v_total numeric(16,2);
begin
 select * into v_res from public.angelcare_marketplace_wallet_reservations where id=p_reservation_id for update;
 if v_res.id is null or v_res.status='committed' then return;end if;if v_res.status<>'reserved' then raise exception 'reservation not committable';end if;
 for v_item in select * from jsonb_array_elements(v_res.allocation) loop
  update public.angelcare_marketplace_wallet_balance_buckets set reserved_amount=greatest(0,reserved_amount-(v_item->>'amount')::numeric),updated_at=now() where id=(v_item->>'bucket_id')::uuid;
 end loop;
 update public.angelcare_marketplace_wallet_reservations set status='committed',committed_at=now(),updated_at=now() where id=p_reservation_id;
 perform public.angelcare_marketplace_wallet_refresh_totals(v_res.wallet_account_id);select available_balance into v_total from public.angelcare_marketplace_wallet_accounts where id=v_res.wallet_account_id;
 insert into public.angelcare_marketplace_wallet_ledger_entries(wallet_account_id,entry_type,bucket_kind,direction,amount,balance_after,source_type,source_id,order_reference,payment_reference,reason_code,description,idempotency_key,effective_at)
 values(v_res.wallet_account_id,'purchase_commit','reserved','debit',v_res.amount,v_total,v_res.source_type,v_res.source_id,p_order_reference,p_payment_reference,'canonical_purchase','Paiement AC Wallet capturé','commit:'||p_reservation_id::text,now()) on conflict(idempotency_key) do nothing;
 update public.angelcare_marketplace_wallet_accounts set lifetime_spent=lifetime_spent+v_res.amount,updated_at=now() where id=v_res.wallet_account_id;
end$$;


--
-- Name: angelcare_marketplace_wallet_post_entry(uuid, text, text, text, numeric, text, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_wallet_post_entry(p_wallet_account_id uuid, p_entry_type text, p_bucket_kind text, p_direction text, p_amount numeric, p_source_type text, p_source_id uuid, p_reason_code text, p_description text, p_idempotency_key text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_existing uuid;v_bucket uuid;v_available numeric(16,2);v_total numeric(16,2);v_entry uuid;
begin
 if p_amount is null or p_amount<=0 then raise exception 'wallet amount must be positive';end if;
 select id into v_existing from public.angelcare_marketplace_wallet_ledger_entries where idempotency_key=p_idempotency_key;
 if v_existing is not null then return v_existing;end if;
 perform 1 from public.angelcare_marketplace_wallet_accounts where id=p_wallet_account_id and status in('active','restricted') for update;
 if not found then raise exception 'wallet account unavailable';end if;
 select id,available_amount into v_bucket,v_available from public.angelcare_marketplace_wallet_balance_buckets where wallet_account_id=p_wallet_account_id and bucket_kind=p_bucket_kind and expires_at is not distinct from p_expires_at order by created_at limit 1 for update;
 if v_bucket is null then
  insert into public.angelcare_marketplace_wallet_balance_buckets(wallet_account_id,bucket_kind,available_amount,reserved_amount,expires_at) values(p_wallet_account_id,p_bucket_kind,0,0,p_expires_at) returning id,available_amount into v_bucket,v_available;
 end if;
 if p_direction='debit' and v_available<p_amount then raise exception 'insufficient wallet bucket balance';end if;
 update public.angelcare_marketplace_wallet_balance_buckets set available_amount=case when p_direction='credit' then available_amount+p_amount else available_amount-p_amount end,updated_at=now() where id=v_bucket;
 perform public.angelcare_marketplace_wallet_refresh_totals(p_wallet_account_id);
 select available_balance into v_total from public.angelcare_marketplace_wallet_accounts where id=p_wallet_account_id;
 insert into public.angelcare_marketplace_wallet_ledger_entries(wallet_account_id,entry_type,bucket_kind,direction,amount,balance_after,source_type,source_id,reason_code,description,idempotency_key,effective_at,expires_at)
 values(p_wallet_account_id,p_entry_type,p_bucket_kind,p_direction,p_amount,v_total,p_source_type,p_source_id,p_reason_code,p_description,p_idempotency_key,now(),p_expires_at) returning id into v_entry;
 update public.angelcare_marketplace_wallet_accounts set
  lifetime_funded=lifetime_funded+case when p_entry_type='top_up' and p_direction='credit' then p_amount else 0 end,
  lifetime_spent=lifetime_spent+case when p_entry_type='purchase_commit' and p_direction='debit' then p_amount else 0 end,
  updated_at=now() where id=p_wallet_account_id;
 return v_entry;
end$$;


--
-- Name: angelcare_marketplace_wallet_refresh_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_wallet_refresh_totals(p_wallet_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_available numeric(16,2);v_purchased numeric(16,2);v_bonus numeric(16,2);v_reserved numeric(16,2);v_expiring numeric(16,2);
begin
 select coalesce(sum(available_amount),0),coalesce(sum(available_amount) filter(where bucket_kind='purchased'),0),
 coalesce(sum(available_amount) filter(where bucket_kind in('promotional','goodwill','refund','employer','gift')),0),coalesce(sum(reserved_amount),0),
 coalesce(sum(available_amount) filter(where expires_at is not null and expires_at>now()),0)
 into v_available,v_purchased,v_bonus,v_reserved,v_expiring from public.angelcare_marketplace_wallet_balance_buckets where wallet_account_id=p_wallet_account_id;
 update public.angelcare_marketplace_wallet_accounts set available_balance=v_available,purchased_balance=v_purchased,bonus_balance=v_bonus,reserved_balance=v_reserved,expiring_balance=v_expiring,updated_at=now() where id=p_wallet_account_id;
end$$;


--
-- Name: angelcare_marketplace_wallet_release(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_wallet_release(p_reservation_id uuid, p_reason text DEFAULT 'reservation_release'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_res record;v_item jsonb;
begin
 select * into v_res from public.angelcare_marketplace_wallet_reservations where id=p_reservation_id for update;
 if v_res.id is null or v_res.status<>'reserved' then return;end if;
 for v_item in select * from jsonb_array_elements(v_res.allocation) loop
  update public.angelcare_marketplace_wallet_balance_buckets set available_amount=available_amount+(v_item->>'amount')::numeric,reserved_amount=greatest(0,reserved_amount-(v_item->>'amount')::numeric),updated_at=now() where id=(v_item->>'bucket_id')::uuid;
 end loop;
 update public.angelcare_marketplace_wallet_reservations set status='released',released_at=now(),updated_at=now() where id=p_reservation_id;
 perform public.angelcare_marketplace_wallet_refresh_totals(v_res.wallet_account_id);
 insert into public.angelcare_marketplace_wallet_ledger_entries(wallet_account_id,entry_type,bucket_kind,direction,amount,balance_after,source_type,source_id,reason_code,description,idempotency_key,effective_at)
 select v_res.wallet_account_id,'reservation_release','reserved','credit',v_res.amount,w.available_balance,v_res.source_type,v_res.source_id,p_reason,'Réservation AC Wallet libérée','release:'||p_reservation_id::text,now() from public.angelcare_marketplace_wallet_accounts w where w.id=v_res.wallet_account_id on conflict(idempotency_key) do nothing;
end$$;


--
-- Name: angelcare_marketplace_wallet_reserve(uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.angelcare_marketplace_wallet_reserve(p_wallet_account_id uuid, p_amount numeric, p_source_type text, p_source_id uuid, p_idempotency_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_existing uuid;v_remaining numeric(16,2):=p_amount;v_take numeric(16,2);v_reservation uuid;v_alloc jsonb:='[]'::jsonb;v_row record;
begin
 if p_amount is null or p_amount<=0 then raise exception 'reservation amount must be positive';end if;
 select id into v_existing from public.angelcare_marketplace_wallet_reservations where idempotency_key=p_idempotency_key;
 if v_existing is not null then return v_existing;end if;
 perform 1 from public.angelcare_marketplace_wallet_accounts where id=p_wallet_account_id and status='active' for update;
 if not found then raise exception 'wallet not active';end if;
 if (select coalesce(sum(available_amount),0) from public.angelcare_marketplace_wallet_balance_buckets where wallet_account_id=p_wallet_account_id and (expires_at is null or expires_at>now()))<p_amount then raise exception 'insufficient wallet balance';end if;
 insert into public.angelcare_marketplace_wallet_reservations(wallet_account_id,amount,source_type,source_id,idempotency_key) values(p_wallet_account_id,p_amount,p_source_type,p_source_id,p_idempotency_key) returning id into v_reservation;
 for v_row in select id,bucket_kind,available_amount,expires_at from public.angelcare_marketplace_wallet_balance_buckets where wallet_account_id=p_wallet_account_id and available_amount>0 and (expires_at is null or expires_at>now()) order by case when expires_at is null then 1 else 0 end,expires_at,bucket_kind for update loop
  exit when v_remaining<=0;v_take:=least(v_remaining,v_row.available_amount);
  update public.angelcare_marketplace_wallet_balance_buckets set available_amount=available_amount-v_take,reserved_amount=reserved_amount+v_take,updated_at=now() where id=v_row.id;
  v_alloc:=v_alloc||jsonb_build_array(jsonb_build_object('bucket_id',v_row.id,'bucket_kind',v_row.bucket_kind,'amount',v_take,'expires_at',v_row.expires_at));v_remaining:=v_remaining-v_take;
 end loop;
 update public.angelcare_marketplace_wallet_reservations set allocation=v_alloc,updated_at=now() where id=v_reservation;
 perform public.angelcare_marketplace_wallet_refresh_totals(p_wallet_account_id);return v_reservation;
end$$;


--
-- Name: app_password_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_password_hash(input_password text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_schema text;
  v_hash text;
begin
  select n.nspname
  into v_schema
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where p.proname = 'crypt'
    and pg_get_function_identity_arguments(p.oid) = 'text, text'
  limit 1;

  if v_schema is null then
    raise exception 'pgcrypto crypt(text,text) not found';
  end if;

  execute format(
    'select %I.crypt($1, %I.gen_salt(''bf''))',
    v_schema,
    v_schema
  )
  using input_password
  into v_hash;

  return v_hash;
end;
$_$;


--
-- Name: app_password_matches(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_password_matches(input_password text, stored_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_schema text;
  v_ok boolean;
begin
  if stored_hash is null or stored_hash = '' then
    return false;
  end if;

  select n.nspname
  into v_schema
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where p.proname = 'crypt'
    and pg_get_function_identity_arguments(p.oid) = 'text, text'
  limit 1;

  if v_schema is null then
    raise exception 'pgcrypto crypt(text,text) not found';
  end if;

  execute format(
    'select %I.crypt($1, $2) = $2',
    v_schema
  )
  using input_password, stored_hash
  into v_ok;

  return coalesce(v_ok, false);
end;
$_$;


--
-- Name: apply_email_access_rules(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_email_access_rules(p_user_id uuid, p_department text, p_role text, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare applied_count int := 0;
begin
  insert into user_email_permissions(user_id, mailbox_id, access_level, can_read, can_draft, can_send, can_approve, can_assign, can_delete, can_manage_settings, requires_approval, source, granted_by, reason)
  select p_user_id, r.mailbox_id, r.access_level, r.can_read, r.can_draft, r.can_send, r.can_approve, r.can_assign, r.can_delete, r.can_manage_settings, r.requires_approval, 'role_rule', p_actor_user_id, 'Auto-granted from role and department rule'
  from email_access_rules r
  where r.auto_grant = true and lower(r.department) = lower(p_department) and lower(r.role) = lower(p_role)
  on conflict(user_id, mailbox_id) do update set
    access_level=excluded.access_level,
    can_read=excluded.can_read,
    can_draft=excluded.can_draft,
    can_send=excluded.can_send,
    can_approve=excluded.can_approve,
    can_assign=excluded.can_assign,
    can_delete=excluded.can_delete,
    can_manage_settings=excluded.can_manage_settings,
    requires_approval=excluded.requires_approval,
    source='role_rule',
    granted_by=p_actor_user_id,
    is_active=true,
    updated_at=now();
  get diagnostics applied_count = row_count;
  return applied_count;
end;
$$;


