--
-- Name: browser_extension_replace_user_access(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_replace_user_access(p_user_id uuid, p_assigned_by uuid, p_payload jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_previous integer; v_next integer; v_enabled boolean; v_default text;
begin
  select access_version into v_previous from browser_extension_access_profiles where user_id=p_user_id for update;
  v_previous:=coalesce(v_previous,0); v_next:=v_previous+1;
  v_enabled:=coalesce((p_payload->>'enabled')::boolean,false); v_default:=coalesce(p_payload->>'defaultAutonomy','USER_CONFIRMATION');
  insert into browser_extension_access_profiles(user_id,enabled,access_version,default_autonomy,valid_until,notes,assigned_by,updated_at)
  values(p_user_id,v_enabled,v_next,v_default,nullif(p_payload->>'validUntil','')::timestamptz,p_payload->>'notes',p_assigned_by,now())
  on conflict(user_id) do update set enabled=excluded.enabled,access_version=excluded.access_version,default_autonomy=excluded.default_autonomy,valid_until=excluded.valid_until,notes=excluded.notes,assigned_by=excluded.assigned_by,updated_at=now();
  delete from browser_extension_module_grants where user_id=p_user_id; delete from browser_extension_submodule_grants where user_id=p_user_id; delete from browser_extension_capability_grants where user_id=p_user_id; delete from browser_extension_adapter_grants where user_id=p_user_id; delete from browser_extension_data_scopes where user_id=p_user_id; delete from browser_extension_autonomy_rules where user_id=p_user_id; delete from browser_extension_approval_rules where user_id=p_user_id;
  insert into browser_extension_module_grants(user_id,module_key,enabled,access_level,assigned_by) select p_user_id,x->>'key',true,coalesce(x->>'accessLevel','VIEW'),p_assigned_by from jsonb_array_elements(coalesce(p_payload->'modules','[]'::jsonb)) x;
  insert into browser_extension_submodule_grants(user_id,module_key,submodule_key,enabled,access_level,assigned_by) select p_user_id,x->>'moduleKey',x->>'key',true,coalesce(x->>'accessLevel','VIEW'),p_assigned_by from jsonb_array_elements(coalesce(p_payload->'submodules','[]'::jsonb)) x;
  insert into browser_extension_capability_grants(user_id,module_key,capability_key,enabled,access_level,assigned_by) select p_user_id,coalesce(x->>'moduleKey','revenue_b2b'),x->>'key',true,coalesce(x->>'accessLevel','EXECUTE'),p_assigned_by from jsonb_array_elements(coalesce(p_payload->'capabilities','[]'::jsonb)) x;
  insert into browser_extension_adapter_grants(user_id,adapter_key,enabled,permission_mode,assigned_by) select p_user_id,x->>'key',true,coalesce(x->>'permissionMode','ON_DEMAND'),p_assigned_by from jsonb_array_elements(coalesce(p_payload->'adapters','[]'::jsonb)) x;
  insert into browser_extension_data_scopes(user_id,scope_key,scope_value,assigned_by) select p_user_id,key,value,p_assigned_by from jsonb_each(coalesce(p_payload->'scopes','{}'::jsonb));
  insert into browser_extension_autonomy_rules(user_id,action_pattern,mode,priority,enabled,assigned_by) select p_user_id,x->>'actionPattern',x->>'mode',coalesce((x->>'priority')::integer,0),true,p_assigned_by from jsonb_array_elements(coalesce(p_payload->'autonomy','[]'::jsonb)) x;
  insert into browser_extension_approval_rules(user_id,command_pattern,approval_level,approver_role,enabled,assigned_by) select p_user_id,x->>'commandPattern',coalesce(x->>'approvalLevel','manager'),x->>'approverRole',true,p_assigned_by from jsonb_array_elements(coalesce(p_payload->'approvals','[]'::jsonb)) x;
  insert into browser_extension_access_changes(user_id,previous_version,new_version,changed_by,change_summary) values(p_user_id,v_previous,v_next,p_assigned_by,p_payload);
  return v_next;
end $$;


--
-- Name: browser_extension_ultra_bridge_dry_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_bridge_dry_run(p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source_count bigint := 0;
  v_target_count bigint := 0;
  v_active_mappings bigint := 0;
  v_open_conflicts bigint := 0;
begin
  if to_regclass('public.revenue_prospects') is not null then
    execute 'select count(*) from public.revenue_prospects'
      into v_source_count;
  end if;

  if to_regclass('public.b2b_prospects') is not null then
    execute 'select count(*) from public.b2b_prospects where archived_at is null'
      into v_target_count;
  end if;

  select count(*)
  into v_active_mappings
  from public.browser_extension_ultra_commercial_id_map
  where source_system = 'revenue_command_center'
    and source_table = 'revenue_prospects'
    and entity_type = 'prospect'
    and status = 'active';

  select count(*)
  into v_open_conflicts
  from public.browser_extension_ultra_bridge_conflicts
  where status in ('open', 'reviewing');

  return jsonb_build_object(
    'generatedAt', now(),
    'actorId', p_actor_id,
    'bridgeMode', 'revenue_prospects_to_b2b_prospects',
    'sourceCounts', jsonb_build_object(
      'revenue_prospects', v_source_count,
      'b2b_prospects', v_target_count,
      'revenue_accounts', null,
      'revenue_opportunities', null,
      'revenue_partnerships',
        case
          when to_regclass('public.revenue_partnerships') is null then null
          else (select count(*) from public.revenue_partnerships)
        end
    ),
    'activeProspectMappings', v_active_mappings,
    'openConflicts', v_open_conflicts,
    'backfillReady',
      to_regclass('public.revenue_prospects') is not null
      and to_regclass('public.b2b_prospects') is not null,
    'truthBoundary',
      'The deployed schema supports prospect identity mapping. Missing opportunity/account source tables are not fabricated.'
  );
end;
$$;


--
-- Name: browser_extension_ultra_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.browser_extension_ultra_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    schedule_id uuid,
    idempotency_key text NOT NULL,
    job_type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    run_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    completed_at timestamp with time zone,
    last_error text,
    result_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT browser_extension_ultra_jobs_job_type_check CHECK ((job_type = ANY (ARRAY['data_quality_scan'::text, 'report_generate'::text, 'stale_detection'::text, 'renewal_milestone'::text]))),
    CONSTRAINT browser_extension_ultra_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text, 'paused'::text, 'cancelled'::text])))
);


--
-- Name: TABLE browser_extension_ultra_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.browser_extension_ultra_jobs IS 'Low-risk internal scheduler queue. High-risk external/business commitments are forbidden job types.';


--
-- Name: browser_extension_ultra_claim_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_claim_jobs(p_worker_id text, p_limit integer DEFAULT 25) RETURNS SETOF public.browser_extension_ultra_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (select 1 from public.browser_extension_ultra_scheduler_control where singleton=true and (paused=true or kill_switch=true)) then
    return;
  end if;
  return query
  with candidates as (
    select id from public.browser_extension_ultra_jobs
    where status='queued' and run_at <= now()
    order by priority asc, run_at asc
    for update skip locked
    limit greatest(1,least(coalesce(p_limit,25),100))
  ), claimed as (
    update public.browser_extension_ultra_jobs j
    set status='running', locked_at=now(), locked_by=p_worker_id, updated_at=now()
    from candidates c where j.id=c.id
    returning j.*
  ) select * from claimed;
end $$;


--
-- Name: browser_extension_ultra_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_domain(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select nullif(
    lower(
      regexp_replace(
        split_part(
          regexp_replace(trim(coalesce(p_value, '')), '^https?://', '', 'i'),
          '/',
          1
        ),
        '^www\.',
        '',
        'i'
      )
    ),
    ''
  )
$$;


--
-- Name: browser_extension_ultra_enqueue_due_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_enqueue_due_schedules() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare inserted_count integer;
begin
  if exists (select 1 from public.browser_extension_ultra_scheduler_control where singleton=true and (paused=true or kill_switch=true)) then
    return 0;
  end if;
  insert into public.browser_extension_ultra_jobs(schedule_id,idempotency_key,job_type,payload,run_at)
  select s.id, s.schedule_key || ':' || to_char(date_trunc('hour',coalesce(s.next_run_at,now())),'YYYYMMDDHH24MI'), s.job_type, s.payload, coalesce(s.next_run_at,now())
  from public.browser_extension_ultra_schedules s
  where s.enabled=true
    and (s.next_run_at is null or s.next_run_at<=now())
    and (not s.requires_approval or s.approved_at is not null)
    and (
      select count(*) from public.browser_extension_ultra_jobs j
      where j.schedule_id=s.id and j.created_at >= now()-interval '1 hour'
    ) < greatest(1,s.rate_limit_per_hour)
  on conflict (idempotency_key) do nothing;
  get diagnostics inserted_count = row_count;
  update public.browser_extension_ultra_schedules
  set last_run_at=now(), next_run_at=case when interval_seconds is not null then now()+make_interval(secs=>interval_seconds) else now()+interval '1 day' end, updated_at=now()
  where enabled=true and (next_run_at is null or next_run_at<=now()) and (not requires_approval or approved_at is not null);
  return inserted_count;
end $$;


--
-- Name: browser_extension_ultra_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_normalize(value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select trim(regexp_replace(lower(translate(coalesce(value,''),'ÀÁÂÃÄÅàáâãäåÇçÈÉÊËèéêëÌÍÎÏìíîïÑñÒÓÔÕÖòóôõöÙÚÛÜùúûüÝŸýÿ','AAAAAAaaaaaaCcEEEEeeeeIIIIiiiiNnOOOOOoooooUUUUuuuuYYyy')), '[^a-z0-9]+', ' ', 'g'))
$$;


--
-- Name: browser_extension_ultra_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_phone(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select nullif(
    right(regexp_replace(coalesce(p_value, ''), '\D', '', 'g'), 9),
    ''
  )
$$;


--
-- Name: browser_extension_ultra_source_uuid(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.browser_extension_ultra_source_uuid(p_source_table text, p_source_id text) RETURNS uuid
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select (
    substr(h, 1, 8) || '-' ||
    substr(h, 9, 4) || '-' ||
    substr(h, 13, 4) || '-' ||
    substr(h, 17, 4) || '-' ||
    substr(h, 21, 12)
  )::uuid
  from (
    select md5(
      coalesce(p_source_table, '') || ':' || coalesce(p_source_id, '')
    ) as h
  ) digest
$$;


