--
-- Name: connect_can_manage_conversation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_can_manage_conversation(p_conversation_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.connect_conversations c
    where c.id::text = p_conversation_id
      and c.created_by::text = p_user_id
  )
  or exists (
    select 1
    from public.connect_conversation_members m
    where m.conversation_id::text = p_conversation_id
      and m.user_id::text = p_user_id
      and coalesce(m.role, 'member') in ('owner', 'admin')
  );
$$;


--
-- Name: connect_can_read_action(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_can_read_action(p_action_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.connect_actions a
    where a.id::text = p_action_id
      and (
        a.created_by::text = p_user_id
        or a.owner_id::text = p_user_id
        or public.connect_is_action_assignee(a.id::text, p_user_id)
        or (a.conversation_id is not null and public.connect_is_conversation_member(a.conversation_id::text, p_user_id))
      )
  );
$$;


--
-- Name: connect_is_action_assignee(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_is_action_assignee(p_action_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.connect_action_assignees a
    where a.action_id::text = p_action_id
      and a.user_id::text = p_user_id
  );
$$;


--
-- Name: connect_is_conversation_member(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_is_conversation_member(p_conversation_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.connect_conversation_members m
    where m.conversation_id::text = p_conversation_id
      and m.user_id::text = p_user_id
  );
$$;


