--
-- Name: fill_system_module_flags_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_system_module_flags_defaults() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.module_key := coalesce(nullif(new.module_key, ''), 'unknown_module');
  new.module_name := coalesce(nullif(new.module_name, ''), nullif(new.module_label, ''), new.module_key, 'Runtime Module');
  new.module_label := coalesce(nullif(new.module_label, ''), new.module_name, new.module_key, 'Runtime Module');
  new.module_group := coalesce(nullif(new.module_group, ''), 'system');
  new.module_description := coalesce(nullif(new.module_description, ''), 'Runtime controlled module');
  new.status := coalesce(nullif(new.status, ''), case when coalesce(new.enabled, true) then 'active' else 'disabled' end);
  new.control_source := coalesce(nullif(new.control_source, ''), 'ceo_system_control');
  new.environment := coalesce(nullif(new.environment, ''), 'production');
  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  new.updated_at := now();

  if new.last_action_at is null then
    new.last_action_at := now();
  end if;

  return new;
end;
$$;


--
-- Name: flashcards_os_next_revenue_document_number(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flashcards_os_next_revenue_document_number(p_tenant_key text, p_document_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'flashcards_os'
    AS $$
declare y integer:=extract(year from current_date)::integer; current_value bigint; current_prefix text; current_padding integer;
begin
 perform pg_advisory_xact_lock(hashtext(p_tenant_key||':'||p_document_type||':'||y::text));
 insert into flashcards_os.commercial_document_numbers(tenant_key,document_type,year_no,next_value,prefix,padding)
 values(p_tenant_key,p_document_type,y,1,case p_document_type when 'quotation' then 'DEV-FC' when 'sales_order' then 'CMD-FC' when 'delivery_note' then 'BL-FC' when 'invoice' then 'FAC-FC' when 'credit_note' then 'AV-FC' when 'payment' then 'PAY-FC' else upper(left(p_document_type,3))||'-FC' end,4)
 on conflict(tenant_key,document_type,year_no) do nothing;
 select next_value,prefix,padding into current_value,current_prefix,current_padding from flashcards_os.commercial_document_numbers where tenant_key=p_tenant_key and document_type=p_document_type and year_no=y for update;
 update flashcards_os.commercial_document_numbers set next_value=current_value+1,updated_at=now() where tenant_key=p_tenant_key and document_type=p_document_type and year_no=y;
 return current_prefix||'-'||y::text||'-'||lpad(current_value::text,current_padding,'0');
end $$;


--
-- Name: fn_app_attendance_log_attach_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_app_attendance_log_attach_staff() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  resolved_staff uuid;
begin
  if new.staff_id is null and new.user_id is not null then
    select staff_id into resolved_staff
    from public.hr_user_identity_contracts
    where user_id = new.user_id
    limit 1;

    if resolved_staff is not null then
      new.staff_id = resolved_staff;
    end if;
  end if;

  return new;
end;
$$;


