--
-- Name: hr_interview_questionnaires_sync_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_interview_questionnaires_sync_metadata() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
  plain_text text;
  extracted_ref text;
  extracted_role text;
  extracted_dept text;
  extracted_duration text;
  extracted_pass text;
  m text[];
begin
  -- Always clean accidental Markdown fences before saving.
  new.html_code := public.hr_iq_strip_markdown_fences(coalesce(new.html_code, ''));

  plain_text := public.hr_iq_plain_text(new.html_code);

  m := regexp_match(plain_text, '(AC-HR-IQ-[A-Z0-9-]+-20[0-9]{2}-V[0-9]+)');
  if m is not null then
    extracted_ref := trim(m[1]);
  end if;

  extracted_role := public.hr_iq_extract_role(plain_text, extracted_ref);
  extracted_dept := public.hr_iq_extract_department(plain_text, extracted_ref, extracted_role);

  m := regexp_match(plain_text, 'Durée([[:space:]]+indicative)?[[:space:]]*:[[:space:]]*([0-9]{1,3})');
  if m is not null then
    extracted_duration := m[2];
  end if;

  m := regexp_match(plain_text, 'Score[[:space:]]+cible[[:space:]]*:[[:space:]]*([0-9]{1,3})');
  if m is not null then
    extracted_pass := m[1];
  end if;

  if extracted_ref is not null and extracted_ref <> '' then
    new.questionnaire_code := extracted_ref;
  end if;

  if extracted_role is not null and extracted_role <> '' then
    new.title := extracted_role;
    new.role_target := extracted_role;
  end if;

  if extracted_dept is not null and extracted_dept <> '' then
    new.department := extracted_dept;
  end if;

  if extracted_duration ~ '^[0-9]+$' then
    new.duration_minutes := greatest(1, least(300, extracted_duration::int));
  end if;

  if extracted_pass ~ '^[0-9]+$' then
    new.pass_score := greatest(0, least(100, extracted_pass::int));
  end if;

  if coalesce(new.language, '') = '' then
    new.language := case
      when plain_text ~* '(Évaluation|Référence|Département|Durée|Questionnaire)' then 'fr'
      else 'fr'
    end;
  end if;

  new.updated_at := now();

  return new;
end;
$_$;


--
-- Name: hr_iq_extract_department(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_iq_extract_department(_plain text, _ref text, _role text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  m text[];
begin
  if _ref ilike '%B2BEXEC%' or _role ilike '%Business Developer%B2B%' then
    return 'Business Development / B2B Partnerships';
  elsif _ref ilike '%ARCC-B2CB2B%' or _role ilike '%Relations Client%' then
    return 'Customer Relations / Sales / B2C-B2B';
  elsif _ref ilike '%MCDO%' or _role ilike '%Marketing%' then
    return 'Marketing / Communication';
  elsif _ref ilike '%OPS%' or _role ilike '%Dispatch%' or _role ilike '%Operations%' then
    return 'Operations / Dispatch';
  end if;

  m := regexp_match(_plain, '(Département|Departement|Department)[[:space:]]*:[[:space:]]*([^\.]{3,120})');
  if m is not null then
    return trim(m[2]);
  end if;

  return null;
end;
$$;


--
-- Name: hr_iq_extract_role(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_iq_extract_role(_plain text, _ref text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  m text[];
  r text;
begin
  -- Strong known codes used by AngelCare generated templates.
  if _ref ilike '%B2BEXEC%' then
    return 'Business Developer B2B Executive';
  elsif _ref ilike '%ARCC-B2CB2B%' then
    return 'Agent Relations Client et Commerciale B2C / B2B';
  elsif _ref ilike '%MCDO%' then
    return 'Strategic Marketing & Communication Digital Officer Polyvalent et Performant';
  elsif _ref ilike '%OPS%' or _ref ilike '%MDOAM%' then
    return 'Missions Dispatch Operations Assistant Manager';
  end if;

  m := regexp_match(_plain, 'Poste[[:space:]]*:[[:space:]]*([^\.]{6,180})');
  if m is not null then
    r := trim(m[1]);
  end if;

  if r is null or length(r) < 6 then
    m := regexp_match(_plain, '(Évaluation|Evaluation)[[:space:]]*(—|-)?[[:space:]]*([^\.]{8,180})');
    if m is not null then
      r := trim(m[3]);
    end if;
  end if;

  if r is not null then
    r := regexp_replace(r, '[[:space:]]+', ' ', 'g');
    r := regexp_replace(r, 'Questionnaire.*$', '', 'i');
    r := regexp_replace(r, 'Référence document.*$', '', 'i');
    r := trim(r);
  end if;

  if r is null or length(r) < 6 then
    return null;
  end if;

  return r;
end;
$_$;


--
-- Name: hr_iq_plain_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_iq_plain_text(_html text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  t text;
begin
  t := public.hr_iq_strip_markdown_fences(_html);
  t := regexp_replace(t, '<script[^>]*>.*?</script>', ' ', 'gis');
  t := regexp_replace(t, '<style[^>]*>.*?</style>', ' ', 'gis');
  t := regexp_replace(t, '<[^>]+>', ' ', 'g');
  t := replace(t, '&nbsp;', ' ');
  t := replace(t, '&amp;', '&');
  t := replace(t, '&lt;', '<');
  t := replace(t, '&gt;', '>');
  t := replace(t, '&quot;', '"');
  t := replace(t, '&#39;', '''');
  t := regexp_replace(t, '[[:space:]]+', ' ', 'g');
  return trim(t);
end;
$$;


--
-- Name: hr_iq_strip_markdown_fences(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_iq_strip_markdown_fences(_html text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  select trim(
    regexp_replace(
      regexp_replace(coalesce(_html, ''), '(^|\n)[[:space:]]*```[a-zA-Z0-9_-]*[[:space:]]*(\n|$)', E'\n', 'g'),
      '(^|\n)[[:space:]]*```[[:space:]]*(\n|$)', E'\n', 'g'
    )
  );
$_$;


--
-- Name: hr_recalculate_attendance_record(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_recalculate_attendance_record(record_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  r record;
  work_minutes integer := 0;
  pause_minutes integer := 0;
  anomaly text := null;
  miss boolean := false;
begin
  select * into r from public.hr_attendance_records where id = record_id;
  if not found then return; end if;

  if r.check_in is not null and r.check_out is not null then
    work_minutes := greatest(0, floor(extract(epoch from (r.check_out - r.check_in)) / 60)::integer);
  end if;

  if r.lunch_start is not null and r.lunch_end is not null then
    pause_minutes := greatest(0, floor(extract(epoch from (r.lunch_end - r.lunch_start)) / 60)::integer);
  elsif r.lunch_start is not null and r.lunch_end is null and r.check_out is not null then
    pause_minutes := greatest(0, floor(extract(epoch from (r.check_out - r.lunch_start)) / 60)::integer);
  end if;

  if r.check_in is null and (r.check_out is not null or r.lunch_start is not null or r.lunch_end is not null) then
    miss := true;
    anomaly := 'missing_clock_in';
  elsif r.check_in is not null and r.check_out is null then
    miss := false;
    anomaly := null;
  elsif r.check_in is not null and r.check_out is not null and r.check_out < r.check_in then
    miss := true;
    anomaly := 'clock_out_before_clock_in';
  elsif r.lunch_end is not null and r.lunch_start is null then
    miss := true;
    anomaly := 'missing_break_start';
  elsif r.lunch_start is not null and r.lunch_end is not null and r.lunch_end < r.lunch_start then
    miss := true;
    anomaly := 'break_end_before_break_start';
  elsif work_minutes > 14 * 60 then
    anomaly := 'unusually_long_shift';
  end if;

  update public.hr_attendance_records
  set total_minutes = greatest(0, work_minutes - pause_minutes),
      break_minutes = pause_minutes,
      overtime_minutes = greatest(0, greatest(0, work_minutes - pause_minutes) - 8 * 60),
      missing_punch = miss,
      anomaly_reason = anomaly,
      status = case
        when miss then 'needs_review'
        when check_in is not null and check_out is null then 'in_progress'
        when check_in is not null and check_out is not null then 'completed'
        else coalesce(status, 'pending')
      end,
      updated_at = now()
  where id = record_id;
end;
$$;


