--
-- Name: hsd_handoff_request_commit_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hsd_handoff_request_commit_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN IF OLD.status IN('committed','committed_with_projection_failure','reconciled') AND (NEW.sellable_version_id,NEW.technical_plan_version_id,NEW.category_version_id,NEW.customer_ref,NEW.beneficiary_refs,NEW.mission_count,NEW.total_minutes,NEW.snapshot_hash,NEW.idempotency_key) IS DISTINCT FROM (OLD.sellable_version_id,OLD.technical_plan_version_id,OLD.category_version_id,OLD.customer_ref,OLD.beneficiary_refs,OLD.mission_count,OLD.total_minutes,OLD.snapshot_hash,OLD.idempotency_key) THEN RAISE EXCEPTION 'Committed handoff source truth is immutable; use an amendment'; END IF; RETURN NEW; END $$;


