--
-- Name: login_app_user(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.login_app_user(input_username text, input_password text) RETURNS TABLE(id uuid, role text, permissions jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  return query
  select
    u.id,
    u.role,
    coalesce(to_jsonb(u.permissions), '[]'::jsonb) as permissions
  from public.app_users u
  where u.status = 'active'
    and (
      lower(u.username) = lower(trim(input_username))
      or lower(coalesce(u.email, '')) = lower(trim(input_username))
    )
    and public.app_password_matches(input_password, u.password_hash)
  order by u.created_at asc
  limit 1;
end;
$$;


--
-- Name: market_ai_execution_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.market_ai_execution_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    compilation_id uuid,
    compilation_item_id uuid,
    mission_id uuid,
    command_code text,
    job_type text NOT NULL,
    tool_name text,
    status text DEFAULT 'queued'::text NOT NULL,
    priority integer DEFAULT 50 NOT NULL,
    idempotency_key text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    worker_id text,
    scheduled_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    claimed_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    completed_at timestamp with time zone,
    next_retry_at timestamp with time zone,
    input jsonb DEFAULT '{}'::jsonb NOT NULL,
    output jsonb DEFAULT '{}'::jsonb NOT NULL,
    error text,
    created_by text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT market_ai_execution_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 12))),
    CONSTRAINT market_ai_execution_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'claimed'::text, 'running'::text, 'awaiting_approval'::text, 'retry_scheduled'::text, 'completed'::text, 'cancelled'::text, 'dead_letter'::text, 'blocked'::text])))
);


--
-- Name: market_ai_claim_due_jobs(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_ai_claim_due_jobs(p_limit integer, p_worker_id text) RETURNS SETOF public.market_ai_execution_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_job public.market_ai_execution_jobs%rowtype;
begin
  for v_job in
    select * from public.market_ai_execution_jobs
    where status in ('queued','retry_scheduled')
      and scheduled_at <= timezone('utc',now())
      and (next_retry_at is null or next_retry_at <= timezone('utc',now()))
    order by priority desc, scheduled_at asc
    for update skip locked
    limit greatest(1,least(coalesce(p_limit,1),30))
  loop
    update public.market_ai_execution_jobs set status='claimed',worker_id=p_worker_id,claimed_at=timezone('utc',now()),heartbeat_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=v_job.id returning * into v_job;
    return next v_job;
  end loop;
end $$;


