--
-- Name: market_content_begin_source_replacement(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_begin_source_replacement(p_dossier_id uuid, p_content_code text, p_actor_id uuid, p_actor_name text, p_reason text) RETURNS TABLE(replacement_id uuid, previous_bridge_file_id text, previous_storage_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_source public.market_content_source_objects%rowtype; v_replacement uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_dossier_id::text,0));
 select * into v_source from public.market_content_source_objects where dossier_id=p_dossier_id and is_current for update;
 if not found then raise exception 'CURRENT_SOURCE_NOT_FOUND'; end if;
 if exists(select 1 from public.market_content_source_replacements where dossier_id=p_dossier_id and status in('locked','promoted','deletion_pending')) then raise exception 'SOURCE_REPLACEMENT_ALREADY_ACTIVE'; end if;
 insert into public.market_content_source_replacements(dossier_id,content_code,previous_source_id,status,reason,previous_bridge_file_id,previous_storage_key,previous_sha256_hash,previous_filename,previous_size_bytes,requested_by,requested_by_name)
 values(p_dossier_id,p_content_code,v_source.id,'locked',p_reason,v_source.bridge_file_id,v_source.storage_key,v_source.sha256_hash,v_source.original_filename,v_source.size_bytes,p_actor_id,p_actor_name) returning id into v_replacement;
 return query select v_replacement,v_source.bridge_file_id,v_source.storage_key;
end$$;


--
-- Name: market_content_commit_generation_credit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_commit_generation_credit(p_credit_id uuid, p_sample_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$begin update public.market_content_generation_credits set status='consumed',sample_id=p_sample_id,consumed_at=now() where id=p_credit_id and status='reserved';return found;end$$;


--
-- Name: market_content_commit_source_replacement(uuid, text, text, text, text, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_commit_source_replacement(p_replacement_id uuid, p_bridge_file_id text, p_storage_key text, p_original_filename text, p_safe_filename text, p_content_type text, p_size_bytes bigint, p_sha256_hash text, p_actor_id uuid, p_actor_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_rep public.market_content_source_replacements%rowtype;v_version integer;v_new uuid;
begin
 select * into v_rep from public.market_content_source_replacements where id=p_replacement_id for update;
 if not found or v_rep.status<>'locked' then raise exception 'SOURCE_REPLACEMENT_NOT_LOCKED'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_rep.dossier_id::text,0));
 select coalesce(max(source_version),0)+1 into v_version from public.market_content_source_objects where dossier_id=v_rep.dossier_id;
 update public.market_content_source_objects set is_current=false,integrity_state='superseded_pending_delete' where id=v_rep.previous_source_id;
 insert into public.market_content_source_objects(dossier_id,content_code,bridge_file_id,storage_key,original_filename,safe_filename,content_type,size_bytes,sha256_hash,source_version,is_current,integrity_state,created_by,created_by_name)
 values(v_rep.dossier_id,v_rep.content_code,p_bridge_file_id,p_storage_key,p_original_filename,p_safe_filename,p_content_type,p_size_bytes,p_sha256_hash,v_version,true,'verified',p_actor_id,p_actor_name) returning id into v_new;
 update public.market_content_source_replacements set new_source_id=v_new,new_bridge_file_id=p_bridge_file_id,new_storage_key=p_storage_key,status='deletion_pending',committed_at=now(),updated_at=now() where id=p_replacement_id;
 update public.market_content_dossiers set source_state='secured',updated_at=now() where id=v_rep.dossier_id;
 insert into public.market_content_audit(actor_id,actor_name,action,entity_type,entity_id,detail) values(p_actor_id,p_actor_name,'source.replacement_promoted','source_replacement',p_replacement_id,jsonb_build_object('newSourceId',v_new,'version',v_version));
 return v_new;
end$$;


--
-- Name: market_content_confirm_previous_source_deleted(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_confirm_previous_source_deleted(p_replacement_id uuid, p_actor_id uuid, p_actor_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_rep public.market_content_source_replacements%rowtype;
begin
 select * into v_rep from public.market_content_source_replacements where id=p_replacement_id for update;
 if not found or v_rep.status<>'deletion_pending' then raise exception 'SOURCE_REPLACEMENT_NOT_PENDING_DELETE'; end if;
 update public.market_content_source_objects set integrity_state='bytes_deleted',deletion_verified_at=now() where id=v_rep.previous_source_id;
 update public.market_content_source_replacements set status='completed',previous_deleted_at=now(),updated_at=now() where id=p_replacement_id;
 insert into public.market_content_audit(actor_id,actor_name,action,entity_type,entity_id,detail) values(p_actor_id,p_actor_name,'source.previous_bytes_deleted','source_replacement',p_replacement_id,jsonb_build_object('previousSourceId',v_rep.previous_source_id,'previousHash',v_rep.previous_sha256_hash));
 return true;
end$$;


--
-- Name: market_content_execute_owner_cascade(text, uuid, jsonb, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_execute_owner_cascade(p_root_table text, p_root_id uuid, p_items jsonb, p_actor_id uuid, p_actor_name text, p_reason text, p_plan jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_item jsonb;
  v_relation jsonb;
  v_table text;
  v_field text;
  v_match text;
  v_disposition text;
  v_id uuid;
  v_parent_value text;
  v_deleted integer := 0;
  v_detached integer := 0;
  v_rows integer := 0;
  v_allowed_tables constant text[] := array[
    'market_content_signals','market_content_strategies','market_content_action_plans',
    'market_content_missions','market_content_mission_tasks','market_content_dossiers',
    'market_content_checkpoints','market_content_evidence','market_content_ai_reviews',
    'market_content_human_reviews','market_content_source_objects','market_content_source_replacements',
    'market_content_generated_samples','market_content_publication_packages',
    'market_content_performance_events','market_content_learning_records',
    'market_content_assets','market_content_deliverables','market_content_publications',
    'market_content_ai_runs','market_content_approvals','market_content_ai_directors',
    'market_ai_commands','market_ai_skills','market_ai_command_schedules','market_ai_missions',
    'market_ai_compilations','market_ai_compilation_items','market_ai_execution_jobs',
    'market_ai_tool_executions','market_ai_dead_letters','market_ai_decisions',
    'market_ai_doctrine_entries','market_ai_learning_events'
  ];
  v_nullable_fields constant text[] := array[
    'campaign_id','dossier_id','publication_package_id','asset_id','previous_source_id','new_source_id'
  ];
  v_array_fields constant text[] := array['signal_ids'];
begin
  if p_root_table is null or not (p_root_table = any(v_allowed_tables)) then
    raise exception 'CASCADE_ROOT_TABLE_NOT_ALLOWED:%', coalesce(p_root_table, 'NULL');
  end if;
  if p_root_id is null then raise exception 'CASCADE_ROOT_ID_REQUIRED'; end if;
  if coalesce(length(trim(p_reason)),0) < 8 then raise exception 'CASCADE_REASON_REQUIRED'; end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then raise exception 'CASCADE_ITEMS_MUST_BE_ARRAY'; end if;

  insert into public.market_content_audit(actor_id,actor_name,action,entity_type,entity_id,detail)
  values(
    p_actor_id,
    coalesce(nullif(trim(p_actor_name),''),'Authorized operator'),
    'record.owner_cascade_delete.requested',
    p_root_table,
    p_root_id,
    jsonb_build_object('reason',p_reason,'plan',coalesce(p_plan,'{}'::jsonb),'itemCount',jsonb_array_length(coalesce(p_items,'[]'::jsonb)))
  );

  for v_item in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb))
  loop
    v_table := v_item->>'table';
    v_disposition := v_item->>'disposition';
    v_id := nullif(v_item->>'id','')::uuid;
    if v_table is null or not (v_table = any(v_allowed_tables)) then
      raise exception 'CASCADE_ITEM_TABLE_NOT_ALLOWED:%', coalesce(v_table,'NULL');
    end if;
    if v_id is null then raise exception 'CASCADE_ITEM_ID_REQUIRED'; end if;

    if v_disposition = 'delete' then
      execute format('delete from public.%I where id = $1', v_table) using v_id;
      get diagnostics v_rows = row_count;
      v_deleted := v_deleted + v_rows;
    elsif v_disposition = 'detach' then
      if jsonb_typeof(coalesce(v_item->'relations','[]'::jsonb)) <> 'array' then
        raise exception 'CASCADE_RELATIONS_MUST_BE_ARRAY:%', v_id;
      end if;
      for v_relation in select value from jsonb_array_elements(coalesce(v_item->'relations','[]'::jsonb))
      loop
        v_field := v_relation->>'field';
        v_match := v_relation->>'match';
        v_parent_value := v_relation->>'parentValue';
        if v_match = 'contains' then
          if not (v_field = any(v_array_fields)) then raise exception 'CASCADE_ARRAY_FIELD_NOT_ALLOWED:%',coalesce(v_field,'NULL'); end if;
          execute format('update public.%I set %I = array_remove(%I, $1::uuid) where id = $2',v_table,v_field,v_field)
            using nullif(v_parent_value,'')::uuid,v_id;
          v_detached := v_detached + 1;
        elsif v_match = 'nullable_eq' then
          if not (v_field = any(v_nullable_fields)) then raise exception 'CASCADE_NULLABLE_FIELD_NOT_ALLOWED:%',coalesce(v_field,'NULL'); end if;
          execute format('update public.%I set %I = null where id = $1',v_table,v_field) using v_id;
          v_detached := v_detached + 1;
        else
          raise exception 'CASCADE_DETACH_MATCH_NOT_ALLOWED:%',coalesce(v_match,'NULL');
        end if;
      end loop;
    else
      raise exception 'CASCADE_DISPOSITION_NOT_ALLOWED:%',coalesce(v_disposition,'NULL');
    end if;
  end loop;

  execute format('delete from public.%I where id = $1',p_root_table) using p_root_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then raise exception 'CASCADE_ROOT_NOT_DELETED:%',p_root_id; end if;
  v_deleted := v_deleted + v_rows;

  insert into public.market_content_audit(actor_id,actor_name,action,entity_type,entity_id,detail)
  values(
    p_actor_id,
    coalesce(nullif(trim(p_actor_name),''),'Authorized operator'),
    'record.owner_cascade_delete.completed',
    p_root_table,
    p_root_id,
    jsonb_build_object('reason',p_reason,'deleted',v_deleted,'detached',v_detached,'plan',coalesce(p_plan,'{}'::jsonb))
  );

  return jsonb_build_object('deleted',true,'rootId',p_root_id,'deletedCount',v_deleted,'detachedCount',v_detached);
exception
  when others then
    raise;
end;
$_$;


--
-- Name: FUNCTION market_content_execute_owner_cascade(p_root_table text, p_root_id uuid, p_items jsonb, p_actor_id uuid, p_actor_name text, p_reason text, p_plan jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.market_content_execute_owner_cascade(p_root_table text, p_root_id uuid, p_items jsonb, p_actor_id uuid, p_actor_name text, p_reason text, p_plan jsonb) IS 'Executes an authorized Content Command cascade delete or detach scope as one PostgreSQL transaction. Service-role only.';


--
-- Name: market_content_fail_source_replacement(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_fail_source_replacement(p_replacement_id uuid, p_error text, p_actor_id uuid, p_actor_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 update public.market_content_source_replacements set status=case when status='deletion_pending' then 'deletion_failed' else 'failed' end,error=left(p_error,2000),failed_at=now(),updated_at=now() where id=p_replacement_id;
 insert into public.market_content_audit(actor_id,actor_name,action,entity_type,entity_id,detail) values(p_actor_id,p_actor_name,'source.replacement_failed','source_replacement',p_replacement_id,jsonb_build_object('error',left(p_error,2000)));
 return true;
end$$;


--
-- Name: market_content_next_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_next_code(p_prefix text) RETURNS text
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  select 'AC-' || upper(regexp_replace(coalesce(nullif(trim(p_prefix),''),'OBJ'),'[^A-Za-z0-9]+','','g')) || '-' || to_char(timezone('Africa/Casablanca',now()),'YYYY') || '-' || lpad(nextval('public.market_content_general_code_seq')::text,6,'0');
$$;


--
-- Name: market_content_next_content_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_next_content_code(p_family text, p_service text) RETURNS text
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  select 'AC-CONT-' || to_char(timezone('Africa/Casablanca',now()),'YYYY') || '-' ||
    case lower(coalesce(p_family,'')) when 'digital' then 'DIG' when 'print_offline' then 'PRT' when 'corporate_document' then 'DOC' else 'OTH' end || '-' ||
    upper(left(regexp_replace(coalesce(nullif(trim(p_service),''),'GEN'),'[^A-Za-z0-9]+','','g'),8)) || '-' || lpad(nextval('public.market_content_dossier_code_seq')::text,6,'0');
$$;


--
-- Name: market_content_register_initial_source(uuid, text, text, text, text, text, text, bigint, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_register_initial_source(p_dossier_id uuid, p_content_code text, p_bridge_file_id text, p_storage_key text, p_original_filename text, p_safe_filename text, p_content_type text, p_size_bytes bigint, p_sha256_hash text, p_actor_id uuid, p_actor_name text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_dossier_id::text,0));
 if exists(select 1 from public.market_content_source_objects where dossier_id=p_dossier_id and is_current) then raise exception 'CANONICAL_SOURCE_ALREADY_EXISTS'; end if;
 insert into public.market_content_source_objects(dossier_id,content_code,bridge_file_id,storage_key,original_filename,safe_filename,content_type,size_bytes,sha256_hash,source_version,is_current,integrity_state,created_by,created_by_name)
 values(p_dossier_id,p_content_code,p_bridge_file_id,p_storage_key,p_original_filename,p_safe_filename,p_content_type,p_size_bytes,p_sha256_hash,1,true,'verified',p_actor_id,p_actor_name) returning id into v_id;
 update public.market_content_dossiers set source_state='secured',status=case when status in('validated','source_required') then 'source_secured' else status end,updated_at=now() where id=p_dossier_id;
 insert into public.market_content_audit(actor_id,actor_name,action,entity_type,entity_id,detail) values(p_actor_id,p_actor_name,'source.initial_registered','content_source',v_id,jsonb_build_object('contentCode',p_content_code,'reason',p_reason));
 return v_id;
end$$;


--
-- Name: market_content_release_generation_credit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_release_generation_credit(p_credit_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$begin update public.market_content_generation_credits set status='released',reason=left(p_reason,1000),released_at=now() where id=p_credit_id and status='reserved';return found;end$$;


--
-- Name: market_content_reserve_generation_credit(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_content_reserve_generation_credit(p_dossier_id uuid, p_mission_id uuid, p_actor_id uuid, p_actor_name text) RETURNS TABLE(credit_id uuid, credit_number integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_num integer;v_id uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_dossier_id::text,0));
 select n into v_num from generate_series(1,2)n where not exists(select 1 from public.market_content_generation_credits c where c.dossier_id=p_dossier_id and c.credit_number=n and c.status in('reserved','consumed')) order by n limit 1;
 if v_num is null then raise exception 'GENERATION_CREDIT_LIMIT_REACHED'; end if;
 insert into public.market_content_generation_credits(dossier_id,mission_id,credit_number,status,reserved_by,reserved_by_name) values(p_dossier_id,p_mission_id,v_num,'reserved',p_actor_id,p_actor_name)
 on conflict(dossier_id,credit_number) do update set mission_id=excluded.mission_id,status='reserved',reserved_by=excluded.reserved_by,reserved_by_name=excluded.reserved_by_name,reserved_at=now(),released_at=null,reason=null returning id into v_id;
 return query select v_id,v_num;
end$$;


--
-- Name: market_os_ambassador_actor_has_permission(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_actor_has_permission(p_actor_id uuid, p_permission text, p_tenant_id text, p_organization_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.market_os_ambassador_actor_roles ar
    join public.market_os_ambassador_role_permissions rp on rp.role_key = ar.role_key and rp.enabled
    where ar.id = p_actor_id
      and ar.status = 'active'
      and ar.tenant_id = p_tenant_id
      and ar.organization_id = p_organization_id
      and (rp.permission_key = p_permission or rp.permission_key = '*')
  )
$$;


