--
-- Name: market_os_ambassador_bulk_adapter_preview(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_bulk_adapter_preview(p_entity_type text, p_entity_id text, p_tenant_id text, p_organization_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_adapter record;
  v_relation regclass;
  v_count bigint;
  v_nullable boolean;
  v_has_tenant boolean;
  v_has_organization boolean;
  v_scope text;
  v_results jsonb := '[]'::jsonb;
  v_blockers integer := 0;
begin
  for v_adapter in
    select *
    from public.market_os_ambassador_purge_adapters
    where active = true
      and entity_type in (lower(trim(p_entity_type)), '*')
    order by execution_order, adapter_key
  loop
    v_count := 0;
    v_nullable := true;
    v_relation := null;
    v_has_tenant := false;
    v_has_organization := false;
    v_scope := '';

    if v_adapter.table_name is not null then
      v_relation := to_regclass('public.' || v_adapter.table_name);

      if v_relation is not null and v_adapter.foreign_key is not null then
        select exists (
          select 1 from pg_attribute
          where attrelid = v_relation
            and attname = 'tenant_id'
            and attnum > 0
            and not attisdropped
        ) into v_has_tenant;

        select exists (
          select 1 from pg_attribute
          where attrelid = v_relation
            and attname = 'organization_id'
            and attnum > 0
            and not attisdropped
        ) into v_has_organization;

        if v_has_tenant then
          v_scope := v_scope || ' and t.tenant_id::text = $2';
        end if;

        if v_has_organization then
          v_scope := v_scope || ' and t.organization_id::text = $3';
        end if;

        execute format(
          'select count(*) from %s t where t.%I::text = $1%s',
          v_relation,
          v_adapter.foreign_key,
          v_scope
        )
        into v_count
        using p_entity_id, p_tenant_id, p_organization_id;

        select not a.attnotnull
        into v_nullable
        from pg_attribute a
        where a.attrelid = v_relation
          and a.attname = v_adapter.foreign_key
          and a.attnum > 0
          and not a.attisdropped;

        v_nullable := coalesce(v_nullable, false);
      end if;
    end if;

    if v_count > 0 and (
      v_adapter.strategy = 'block'
      or (v_adapter.strategy = 'detach' and not v_nullable)
    ) then
      v_blockers := v_blockers + v_count::integer;
    end if;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'adapterKey', v_adapter.adapter_key,
        'systemKey', v_adapter.system_key,
        'label', v_adapter.display_label,
        'description', v_adapter.description,
        'strategy', v_adapter.strategy,
        'retentionClass', v_adapter.retention_class,
        'table', v_adapter.table_name,
        'foreignKey', v_adapter.foreign_key,
        'available', v_adapter.table_name is null or v_relation is not null,
        'count', v_count,
        'nullable', v_nullable,
        'blocking', v_count > 0 and (
          v_adapter.strategy = 'block'
          or (v_adapter.strategy = 'detach' and not v_nullable)
        )
      )
    );
  end loop;

  return jsonb_build_object(
    'adapters', v_results,
    'blockerCount', v_blockers,
    'canExecute', v_blockers = 0,
    'generatedAt', now()
  );
end;
$_$;


--
-- Name: market_os_ambassador_bulk_cleanup_adapters(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_bulk_cleanup_adapters(p_entity_type text, p_entity_id text, p_tenant_id text, p_organization_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_adapter record;
  v_relation regclass;
  v_has_tenant boolean;
  v_has_organization boolean;
  v_scope text;
  v_affected integer;
  v_results jsonb := '[]'::jsonb;
begin
  for v_adapter in
    select *
    from public.market_os_ambassador_purge_adapters
    where active = true
      and entity_type in (lower(trim(p_entity_type)), '*')
      and strategy in ('delete', 'detach')
      and table_name is not null
      and foreign_key is not null
    order by execution_order, adapter_key
  loop
    v_relation := to_regclass('public.' || v_adapter.table_name);
    v_affected := 0;

    if v_relation is null then
      v_results := v_results || jsonb_build_array(
        jsonb_build_object(
          'adapterKey', v_adapter.adapter_key,
          'strategy', v_adapter.strategy,
          'affected', 0,
          'available', false
        )
      );
      continue;
    end if;

    select exists (
      select 1 from pg_attribute
      where attrelid = v_relation
        and attname = 'tenant_id'
        and attnum > 0
        and not attisdropped
    ) into v_has_tenant;

    select exists (
      select 1 from pg_attribute
      where attrelid = v_relation
        and attname = 'organization_id'
        and attnum > 0
        and not attisdropped
    ) into v_has_organization;

    v_scope := '';
    if v_has_tenant then
      v_scope := v_scope || ' and tenant_id::text = $2';
    end if;
    if v_has_organization then
      v_scope := v_scope || ' and organization_id::text = $3';
    end if;

    if v_adapter.strategy = 'delete' then
      execute format(
        'delete from %s where %I::text = $1%s',
        v_relation,
        v_adapter.foreign_key,
        v_scope
      ) using p_entity_id, p_tenant_id, p_organization_id;
    else
      execute format(
        'update %s set %I = null where %I::text = $1%s',
        v_relation,
        v_adapter.foreign_key,
        v_adapter.foreign_key,
        v_scope
      ) using p_entity_id, p_tenant_id, p_organization_id;
    end if;

    get diagnostics v_affected = row_count;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'adapterKey', v_adapter.adapter_key,
        'strategy', v_adapter.strategy,
        'affected', v_affected,
        'available', true
      )
    );
  end loop;

  return v_results;
end;
$_$;


--
-- Name: market_os_ambassador_bulk_purge_create(text, text, text, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_bulk_purge_create(p_tenant_id text, p_organization_id text, p_title text, p_reason_code text, p_reason_detail text, p_selection jsonb, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.market_os_ambassador_bulk_purge_jobs%rowtype;
  v_item jsonb;
  v_count integer;
begin
  if jsonb_typeof(p_selection) <> 'array' then
    raise exception 'Bulk purge selection must be a JSON array';
  end if;

  v_count := jsonb_array_length(p_selection);
  if v_count < 1 or v_count > 200 then
    raise exception 'Bulk purge selection must contain between 1 and 200 entities';
  end if;

  insert into public.market_os_ambassador_bulk_purge_jobs (
    tenant_id,
    organization_id,
    title,
    reason_code,
    reason_detail,
    total_count,
    confirmation_code,
    requested_by_app_user_id,
    requested_by_display_name
  )
  values (
    p_tenant_id,
    p_organization_id,
    coalesce(nullif(trim(p_title), ''), 'Suppression groupée'),
    coalesce(nullif(trim(p_reason_code), ''), 'administrative_request'),
    p_reason_detail,
    v_count,
    'PENDING',
    p_actor_app_user_id,
    p_actor_display_name
  )
  returning * into v_job;

  update public.market_os_ambassador_bulk_purge_jobs
  set confirmation_code = 'PURGE-BULK-' || upper(right(replace(v_job.id::text, '-', ''), 8))
  where id = v_job.id
  returning * into v_job;

  for v_item in select value from jsonb_array_elements(p_selection)
  loop
    if lower(trim(v_item->>'entityType')) not in ('ambassador', 'candidate', 'lead') then
      raise exception 'Unsupported bulk entity type: %', v_item->>'entityType';
    end if;

    insert into public.market_os_ambassador_bulk_purge_items (
      job_id,
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      display_label
    )
    values (
      v_job.id,
      p_tenant_id,
      p_organization_id,
      lower(trim(v_item->>'entityType')),
      trim(v_item->>'entityId'),
      coalesce(nullif(trim(v_item->>'displayLabel'), ''), 'Dossier ' || right(trim(v_item->>'entityId'), 8))
    )
    on conflict (job_id, entity_type, entity_id) do nothing;
  end loop;

  insert into public.market_os_ambassador_lifecycle_events (
    tenant_id,
    organization_id,
    entity_type,
    entity_id,
    request_id,
    event_type,
    actor_app_user_id,
    actor_display_name,
    details
  )
  values (
    p_tenant_id,
    p_organization_id,
    'bulk_job',
    v_job.id::text,
    null,
    'bulk_purge_created',
    p_actor_app_user_id,
    p_actor_display_name,
    jsonb_build_object('title', v_job.title, 'totalCount', v_count, 'confirmationCode', v_job.confirmation_code)
  );

  return to_jsonb(v_job);
end;
$$;


--
-- Name: market_os_ambassador_bulk_purge_decide(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_bulk_purge_decide(p_job_id text, p_tenant_id text, p_organization_id text, p_decision text, p_note text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.market_os_ambassador_bulk_purge_jobs%rowtype;
  v_may_self_decide boolean := false;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'Unsupported bulk purge decision';
  end if;

  select * into v_job
  from public.market_os_ambassador_bulk_purge_jobs
  where id::text = p_job_id
    and tenant_id = p_tenant_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Bulk purge job was not found';
  end if;

  if v_job.status not in ('ready', 'review_required', 'blocked') then
    raise exception 'Bulk purge job cannot be decided from status %', v_job.status;
  end if;

  select coalesce(bool_or(active and may_self_decide), false)
  into v_may_self_decide
  from public.market_os_ambassador_lifecycle_authorities
  where actor_app_user_id = p_actor_app_user_id;

  if v_job.requested_by_app_user_id = p_actor_app_user_id and not v_may_self_decide then
    raise exception 'Separation of duties: the creator cannot approve their own bulk purge job';
  end if;

  if p_decision = 'approved' then
    if v_job.ready_count < 1 then
      raise exception 'No eligible entity is ready for this bulk purge job';
    end if;

    update public.market_os_ambassador_bulk_purge_jobs
    set
      status = 'approved',
      approved_by_app_user_id = p_actor_app_user_id,
      approved_by_display_name = p_actor_display_name,
      approval_note = p_note,
      approved_at = now(),
      updated_at = now()
    where id = v_job.id
    returning * into v_job;
  else
    update public.market_os_ambassador_bulk_purge_jobs
    set
      status = 'rejected',
      rejected_by_app_user_id = p_actor_app_user_id,
      rejected_by_display_name = p_actor_display_name,
      rejection_note = p_note,
      rejected_at = now(),
      updated_at = now()
    where id = v_job.id
    returning * into v_job;
  end if;

  insert into public.market_os_ambassador_lifecycle_events (
    tenant_id, organization_id, entity_type, entity_id, request_id,
    event_type, actor_app_user_id, actor_display_name, details
  )
  values (
    p_tenant_id, p_organization_id, 'bulk_job', v_job.id::text, null,
    'bulk_purge_' || p_decision, p_actor_app_user_id, p_actor_display_name,
    jsonb_build_object('note', p_note, 'readyCount', v_job.ready_count, 'blockedCount', v_job.blocked_count)
  );

  return to_jsonb(v_job);
end;
$$;


--
-- Name: market_os_ambassador_bulk_purge_execute(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_bulk_purge_execute(p_job_id text, p_tenant_id text, p_organization_id text, p_confirmation text, p_note text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_job public.market_os_ambassador_bulk_purge_jobs%rowtype;
  v_item public.market_os_ambassador_bulk_purge_items%rowtype;
  v_request jsonb;
  v_result jsonb;
  v_cleanup jsonb;
  v_completed integer;
  v_failed integer;
  v_blocked integer;
  v_external_pending integer := 0;
begin
  select * into v_job
  from public.market_os_ambassador_bulk_purge_jobs
  where id::text = p_job_id
    and tenant_id = p_tenant_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Bulk purge job was not found';
  end if;

  if v_job.status not in ('approved', 'partial', 'failed') then
    raise exception 'Bulk purge job must be approved before execution. Current status: %', v_job.status;
  end if;

  if upper(trim(p_confirmation)) <> upper(v_job.confirmation_code) then
    raise exception 'The bulk purge confirmation code is invalid';
  end if;

  update public.market_os_ambassador_bulk_purge_jobs
  set
    status = 'executing',
    executed_by_app_user_id = p_actor_app_user_id,
    executed_by_display_name = p_actor_display_name,
    started_at = coalesce(started_at, now()),
    execution_error = null,
    updated_at = now()
  where id = v_job.id;

  for v_item in
    select * from public.market_os_ambassador_bulk_purge_items
    where job_id = v_job.id
      and status in ('ready', 'failed')
    order by created_at, id
  loop
    begin
      update public.market_os_ambassador_bulk_purge_items
      set status = 'executing', execution_error = null, updated_at = now()
      where id = v_item.id;

      v_cleanup := public.market_os_ambassador_bulk_cleanup_adapters(
        v_item.entity_type,
        v_item.entity_id,
        p_tenant_id,
        p_organization_id
      );

      v_request := public.market_os_ambassador_lifecycle_request_delete(
        v_item.entity_type,
        v_item.entity_id,
        p_tenant_id,
        p_organization_id,
        v_job.reason_code,
        v_job.reason_detail,
        'bulk:' || v_job.id::text || ':' || v_item.id::text,
        v_job.requested_by_app_user_id,
        v_job.requested_by_display_name
      );

      v_request := public.market_os_ambassador_lifecycle_decide_request(
        v_request->>'id',
        p_tenant_id,
        p_organization_id,
        'approved',
        coalesce(v_job.approval_note, 'Approbation groupée'),
        v_job.approved_by_app_user_id,
        v_job.approved_by_display_name
      );

      v_result := public.market_os_ambassador_lifecycle_execute_delete(
        v_request->>'id',
        p_tenant_id,
        p_organization_id,
        'DELETE-' || upper(right(v_item.entity_id, 8)),
        p_actor_app_user_id,
        p_actor_display_name
      );

      update public.market_os_ambassador_bulk_purge_items
      set
        status = 'completed',
        request_id = (v_request->>'id')::uuid,
        ledger_hash = v_result->>'ledgerHash',
        executed_at = now(),
        execution_error = null,
        adapter_snapshot = jsonb_build_object('preflight', adapter_snapshot, 'cleanup', v_cleanup),
        updated_at = now()
      where id = v_item.id;
    exception when others then
      update public.market_os_ambassador_bulk_purge_items
      set status = 'failed', execution_error = sqlerrm, updated_at = now()
      where id = v_item.id;
    end;
  end loop;

  select
    count(*) filter (where status = 'completed'),
    count(*) filter (where status = 'failed'),
    count(*) filter (where status = 'blocked')
  into v_completed, v_failed, v_blocked
  from public.market_os_ambassador_bulk_purge_items
  where job_id = v_job.id;

  select count(*)
  into v_external_pending
  from public.market_os_ambassador_purge_adapters adapter
  where adapter.active = true
    and adapter.strategy = 'verify_only'
    and (
      adapter.entity_type = '*'
      or exists (
        select 1
        from public.market_os_ambassador_bulk_purge_items item
        where item.job_id = v_job.id
          and item.entity_type = adapter.entity_type
      )
    );

  update public.market_os_ambassador_bulk_purge_jobs
  set
    completed_count = v_completed,
    failed_count = v_failed,
    blocked_count = v_blocked,
    status = case
      when v_failed = 0 and v_external_pending = 0 and v_completed = ready_count then 'completed'
      when v_completed > 0 then 'partial'
      else 'failed'
    end,
    completed_at = case when v_failed = 0 and v_external_pending = 0 and v_completed = ready_count then now() else completed_at end,
    execution_error = case
      when v_failed > 0 then v_failed || ' dossier(s) en échec contrôlé'
      when v_external_pending > 0 then v_external_pending || ' vérification(s) externe(s) en attente'
      else null
    end,
    evidence = evidence || jsonb_build_object(
      'executionNote', p_note,
      'executedAt', now(),
      'completedCount', v_completed,
      'failedCount', v_failed,
      'blockedCount', v_blocked,
      'externalVerificationPending', v_external_pending
    ),
    updated_at = now()
  where id = v_job.id
  returning * into v_job;

  insert into public.market_os_ambassador_lifecycle_events (
    tenant_id, organization_id, entity_type, entity_id, request_id,
    event_type, actor_app_user_id, actor_display_name, details
  )
  values (
    p_tenant_id, p_organization_id, 'bulk_job', v_job.id::text, null,
    'bulk_purge_execution_completed', p_actor_app_user_id, p_actor_display_name,
    jsonb_build_object(
      'status', v_job.status,
      'completedCount', v_completed,
      'failedCount', v_failed,
      'blockedCount', v_blocked,
      'externalVerificationPending', v_external_pending,
      'confirmationCode', v_job.confirmation_code
    )
  );

  return to_jsonb(v_job);
end;
$$;


--
-- Name: market_os_ambassador_bulk_purge_preflight(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_bulk_purge_preflight(p_job_id text, p_tenant_id text, p_organization_id text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.market_os_ambassador_bulk_purge_jobs%rowtype;
  v_item public.market_os_ambassador_bulk_purge_items%rowtype;
  v_preview jsonb;
  v_adapter_preview jsonb;
  v_blockers integer;
  v_ready integer;
  v_blocked integer;
begin
  select * into v_job
  from public.market_os_ambassador_bulk_purge_jobs
  where id::text = p_job_id
    and tenant_id = p_tenant_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Bulk purge job was not found';
  end if;

  if v_job.status in ('approved', 'executing', 'completed', 'rejected') then
    raise exception 'Bulk purge job cannot be analysed from status %', v_job.status;
  end if;

  update public.market_os_ambassador_bulk_purge_jobs
  set status = 'analysis', updated_at = now(), execution_error = null
  where id = v_job.id;

  for v_item in
    select * from public.market_os_ambassador_bulk_purge_items
    where job_id = v_job.id
    order by created_at, id
  loop
    begin
      update public.market_os_ambassador_bulk_purge_items
      set status = 'analysing', updated_at = now(), execution_error = null
      where id = v_item.id;

      v_preview := public.market_os_ambassador_lifecycle_preview(
        v_item.entity_type,
        v_item.entity_id,
        p_tenant_id,
        p_organization_id
      );

      v_adapter_preview := public.market_os_ambassador_bulk_adapter_preview(
        v_item.entity_type,
        v_item.entity_id,
        p_tenant_id,
        p_organization_id
      );

      v_blockers := coalesce((v_adapter_preview->>'blockerCount')::integer, 0);

      update public.market_os_ambassador_bulk_purge_items
      set
        status = case when v_blockers = 0 then 'ready' else 'blocked' end,
        blocker_count = v_blockers,
        dependency_snapshot = v_preview,
        adapter_snapshot = coalesce(v_adapter_preview->'adapters', '[]'::jsonb),
        entity_snapshot_hash = v_preview->>'snapshotHash',
        execution_error = case when v_blockers = 0 then null else 'Un ou plusieurs adaptateurs imposent une conservation ou un blocage.' end,
        updated_at = now()
      where id = v_item.id;
    exception when others then
      update public.market_os_ambassador_bulk_purge_items
      set status = 'blocked', execution_error = sqlerrm, updated_at = now()
      where id = v_item.id;
    end;
  end loop;

  select
    count(*) filter (where status = 'ready'),
    count(*) filter (where status = 'blocked')
  into v_ready, v_blocked
  from public.market_os_ambassador_bulk_purge_items
  where job_id = v_job.id;

  update public.market_os_ambassador_bulk_purge_jobs
  set
    status = case when v_ready > 0 and v_blocked = 0 then 'ready' when v_ready > 0 then 'review_required' else 'blocked' end,
    ready_count = v_ready,
    blocked_count = v_blocked,
    updated_at = now(),
    evidence = jsonb_set(evidence, '{lastPreflightAt}', to_jsonb(now()), true)
  where id = v_job.id
  returning * into v_job;

  insert into public.market_os_ambassador_lifecycle_events (
    tenant_id, organization_id, entity_type, entity_id, request_id,
    event_type, actor_app_user_id, actor_display_name, details
  )
  values (
    p_tenant_id, p_organization_id, 'bulk_job', v_job.id::text, null,
    'bulk_purge_preflight_completed', p_actor_app_user_id, p_actor_display_name,
    jsonb_build_object('readyCount', v_ready, 'blockedCount', v_blocked, 'status', v_job.status)
  );

  return to_jsonb(v_job);
end;
$$;


--
-- Name: market_os_ambassador_convert_candidate(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_convert_candidate(p_candidate_id text, p_actor_id uuid, p_tenant_id text, p_organization_id text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  candidate_record public.market_os_ambassador_recruitment%rowtype;
  ambassador_record public.market_os_ambassadors%rowtype;
  existing_result jsonb;
  actor_name text;
begin
  if not public.market_os_ambassador_actor_has_permission(p_actor_id, 'recruitment.convert', p_tenant_id, p_organization_id) then
    raise exception 'Permission denied: recruitment.convert' using errcode = '42501';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null then raise exception 'idempotency key is required'; end if;

  select result into existing_result
  from public.market_os_ambassador_idempotency
  where tenant_id = p_tenant_id and organization_id = p_organization_id
    and operation = 'candidate_conversion' and idempotency_key = p_idempotency_key;
  if existing_result is not null then return existing_result || jsonb_build_object('idempotent', true); end if;

  select * into candidate_record
  from public.market_os_ambassador_recruitment
  where id::text = p_candidate_id and tenant_id::text = p_tenant_id and organization_id::text = p_organization_id
    and archived_at is null
  for update;
  if not found then raise exception 'Candidate not found'; end if;
  if candidate_record.identity_hash is null then raise exception 'Candidate identity is required before conversion'; end if;
  if candidate_record.stage not in ('approved','converted') then raise exception 'Candidate must be approved before conversion'; end if;

  if candidate_record.ambassador_id is not null then
    select * into ambassador_record from public.market_os_ambassadors where id = candidate_record.ambassador_id;
  end if;
  if ambassador_record.id is null then
    select * into ambassador_record
    from public.market_os_ambassadors
    where tenant_id::text = p_tenant_id and organization_id::text = p_organization_id
      and identity_hash = candidate_record.identity_hash and archived_at is null
    order by created_at asc limit 1 for update;
  end if;

  if ambassador_record.id is null then
    insert into public.market_os_ambassadors (
      tenant_id, organization_id, full_name, email, phone, normalized_email, normalized_phone,
      identity_hash, city, region, source, status, lifecycle_stage, created_by_actor_id, updated_by_actor_id
    ) values (
      p_tenant_id, p_organization_id, candidate_record.candidate_name, candidate_record.email, candidate_record.phone,
      candidate_record.normalized_email, candidate_record.normalized_phone, candidate_record.identity_hash,
      candidate_record.city, candidate_record.region, candidate_record.source, 'onboarding', 'onboarding', p_actor_id, p_actor_id
    ) returning * into ambassador_record;
  end if;

  update public.market_os_ambassador_recruitment
  set stage = 'converted', ambassador_id = ambassador_record.id, updated_by_actor_id = p_actor_id, updated_at = now()
  where id = candidate_record.id
  returning * into candidate_record;

  select coalesce(display_name, auth_user_id::text) into actor_name
  from public.market_os_ambassador_actor_roles where id = p_actor_id;

  insert into public.market_os_ambassador_audit_logs (
    tenant_id, organization_id, entity_type, entity_id, action, summary, actor_id, actor_name,
    actor_role, request_id, payload, before_snapshot, after_snapshot, created_at
  ) select p_tenant_id, p_organization_id, 'recruitment', candidate_record.id::text,
    'candidate_converted', 'Converted approved candidate to Ambassador', p_actor_id, actor_name,
    role_key, p_idempotency_key,
    jsonb_build_object('ambassador_id', ambassador_record.id), to_jsonb(candidate_record), to_jsonb(ambassador_record), now()
  from public.market_os_ambassador_actor_roles where id = p_actor_id;

  existing_result := jsonb_build_object('candidate', to_jsonb(candidate_record), 'ambassador', to_jsonb(ambassador_record), 'idempotent', false);
  insert into public.market_os_ambassador_idempotency (tenant_id, organization_id, operation, idempotency_key, actor_id, result)
  values (p_tenant_id, p_organization_id, 'candidate_conversion', p_idempotency_key, p_actor_id, existing_result)
  on conflict (tenant_id, organization_id, operation, idempotency_key) do nothing;
  return existing_result;
end $$;


--
-- Name: market_os_ambassador_decide_incentive(text, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_decide_incentive(p_incentive_id text, p_decision text, p_actor_id uuid, p_tenant_id text, p_organization_id text, p_reason text, p_payment_reference text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  incentive_record public.market_os_ambassador_incentives%rowtype;
  payout_record public.market_os_ambassador_payouts%rowtype;
  existing_result jsonb;
  required_permission text;
  gate_ok boolean;
begin
  if p_decision not in ('approved','rejected','paid') then raise exception 'Unsupported incentive decision'; end if;
  required_permission := case when p_decision = 'paid' then 'payouts.execute' else 'rewards.approve' end;
  if not public.market_os_ambassador_actor_has_permission(p_actor_id, required_permission, p_tenant_id, p_organization_id) then
    raise exception 'Permission denied: %', required_permission using errcode = '42501';
  end if;

  select result into existing_result from public.market_os_ambassador_idempotency
  where tenant_id = p_tenant_id and organization_id = p_organization_id
    and operation = 'incentive_decision' and idempotency_key = p_idempotency_key;
  if existing_result is not null then return existing_result || jsonb_build_object('idempotent', true); end if;

  select * into incentive_record from public.market_os_ambassador_incentives
  where id::text = p_incentive_id and tenant_id::text = p_tenant_id and organization_id::text = p_organization_id
    and archived_at is null
  for update;
  if not found then raise exception 'Incentive not found'; end if;

  if p_decision = 'approved' then
    select (
      (incentive_record.proof_id is not null and exists (
        select 1 from public.market_os_ambassador_proofs p
        where p.id = incentive_record.proof_id and p.status = 'approved'
          and p.tenant_id::text = p_tenant_id and p.organization_id::text = p_organization_id
      )) or
      (incentive_record.conversion_id is not null and exists (
        select 1 from public.market_os_ambassador_conversions c
        where c.id = incentive_record.conversion_id and c.status in ('validated','paid')
          and c.tenant_id::text = p_tenant_id and c.organization_id::text = p_organization_id
      ))
    ) into gate_ok;
    if not coalesce(gate_ok, false) then raise exception 'Reward approval requires an approved proof or validated conversion'; end if;
  end if;

  if p_decision = 'paid' and incentive_record.status <> 'approved' then
    raise exception 'Only an approved reward can be paid';
  end if;
  if p_decision in ('rejected','paid') and nullif(btrim(coalesce(p_reason, '')), '') is null and p_decision = 'rejected' then
    raise exception 'A rejection reason is required';
  end if;
  if p_decision = 'paid' and nullif(btrim(coalesce(p_payment_reference, '')), '') is null then
    raise exception 'A payment reference is required';
  end if;

  update public.market_os_ambassador_incentives
  set status = p_decision,
      approved_by = case when p_decision = 'approved' then coalesce(approved_by, p_actor_id::text) else approved_by end,
      approved_by_actor_id = case when p_decision = 'approved' then p_actor_id else approved_by_actor_id end,
      approved_at = case when p_decision = 'approved' then now() else approved_at end,
      paid_at = case when p_decision = 'paid' then now() else paid_at end,
      updated_by_actor_id = p_actor_id,
      updated_at = now()
  where id = incentive_record.id returning * into incentive_record;

  if p_decision = 'paid' then
    insert into public.market_os_ambassador_payouts (
      tenant_id, organization_id, ambassador_id, incentive_id, amount_mad, currency, status,
      approval_note, approved_by_actor_id, approved_at, executed_by_actor_id, executed_at,
      payment_reference, paid_at, created_by_actor_id, updated_by_actor_id
    ) values (
      p_tenant_id, p_organization_id, incentive_record.ambassador_id, incentive_record.id,
      coalesce(incentive_record.amount_mad, incentive_record.amount, 0), coalesce(incentive_record.currency, 'MAD'), 'paid',
      p_reason, coalesce(incentive_record.approved_by_actor_id, p_actor_id), coalesce(incentive_record.approved_at, now()),
      p_actor_id, now(), p_payment_reference, now(), p_actor_id, p_actor_id
    ) returning * into payout_record;
  end if;

  insert into public.market_os_ambassador_audit_logs (
    tenant_id, organization_id, entity_type, entity_id, action, summary, actor_id, actor_name,
    actor_role, request_id, payload, before_snapshot, after_snapshot, created_at
  ) select p_tenant_id, p_organization_id, 'incentives', incentive_record.id::text,
    'incentive_' || p_decision, 'Incentive decision: ' || p_decision, p_actor_id,
    coalesce(display_name, auth_user_id::text), role_key, p_idempotency_key,
    jsonb_build_object('reason', p_reason, 'payment_reference', p_payment_reference, 'payout_id', payout_record.id),
    null, to_jsonb(incentive_record), now()
  from public.market_os_ambassador_actor_roles where id = p_actor_id;

  existing_result := jsonb_build_object('incentive', to_jsonb(incentive_record), 'payout', case when payout_record.id is null then null else to_jsonb(payout_record) end, 'idempotent', false);
  insert into public.market_os_ambassador_idempotency (tenant_id, organization_id, operation, idempotency_key, actor_id, result)
  values (p_tenant_id, p_organization_id, 'incentive_decision', p_idempotency_key, p_actor_id, existing_result)
  on conflict (tenant_id, organization_id, operation, idempotency_key) do nothing;
  return existing_result;
end $$;


--
-- Name: market_os_ambassador_decide_settings_approval(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_decide_settings_approval(p_version_id uuid, p_actor_id uuid, p_domain text, p_decision text, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  target public.market_os_ambassador_settings_versions%rowtype;
  approval_record public.market_os_ambassador_settings_approvals%rowtype;
  actor_role text;
  actor_name text;
  next_status text;
  remaining integer;
  domain_authorized boolean := false;
  existing_result jsonb;
  v_idempotency_key text;
  audit_tenant public.market_os_ambassador_audit_logs.tenant_id%type;
  audit_organization public.market_os_ambassador_audit_logs.organization_id%type;
begin
  select * into target
  from public.market_os_ambassador_settings_versions
  where id = p_version_id
  for update;

  if target.id is null then
    raise exception 'Settings version not found' using errcode = 'P0002';
  end if;
  if not public.market_os_ambassador_actor_has_permission(
    p_actor_id, 'settings.approve', target.tenant_id, target.organization_id
  ) then
    raise exception 'Actor lacks settings.approve permission' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null then
    raise exception 'Settings approval requires an idempotency request id' using errcode = '23514';
  end if;
  v_idempotency_key := target.id::text || ':' || coalesce(p_domain, '') || ':' || coalesce(p_decision, '') || ':' || p_request_id;
  select result into existing_result
  from public.market_os_ambassador_idempotency
  where tenant_id = target.tenant_id and organization_id = target.organization_id
    and operation = 'settings_approval' and idempotency_key = v_idempotency_key
    and actor_id = p_actor_id;
  if existing_result is not null then
    return existing_result || jsonb_build_object('idempotent', true);
  end if;
  if target.status <> 'pending_approval' then
    raise exception 'This settings version is not awaiting approval' using errcode = '23514';
  end if;
  if p_domain not in ('program','compliance','finance','system') then
    raise exception 'Invalid approval domain' using errcode = '23514';
  end if;
  if p_decision not in ('approved','rejected','revision_requested') then
    raise exception 'Invalid approval decision' using errcode = '23514';
  end if;
  if nullif(btrim(coalesce(p_note, '')), '') is null then
    raise exception 'Approval decision note is required' using errcode = '23514';
  end if;
  select role_key, coalesce(display_name, auth_user_id::text)
    into actor_role, actor_name
  from public.market_os_ambassador_actor_roles
  where id = p_actor_id and status = 'active'
    and tenant_id = target.tenant_id and organization_id = target.organization_id;

  domain_authorized := actor_role = 'ambassador_admin'
    or public.market_os_ambassador_actor_has_permission(
      p_actor_id, '*', target.tenant_id, target.organization_id
    )
    or (actor_role = 'market_manager' and p_domain = 'program')
    or (actor_role = 'compliance' and p_domain = 'compliance')
    or (actor_role = 'finance' and p_domain = 'finance');

  if not coalesce(domain_authorized, false) then
    raise exception 'Actor role cannot decide % settings approval', p_domain using errcode = '42501';
  end if;
  if coalesce((target.configuration #>> '{governance,separationOfDutiesRequired}')::boolean, true)
    and p_domain in ('finance','compliance')
    and p_actor_id in (target.created_by_actor_id, target.submitted_by_actor_id) then
    raise exception '% approval must be decided by an actor other than the draft author or submitter', p_domain
      using errcode = '42501';
  end if;

  select * into approval_record
  from public.market_os_ambassador_settings_approvals
  where tenant_id = target.tenant_id
    and organization_id = target.organization_id
    and version_id = target.id
    and approval_round = target.approval_round
    and approval_domain = p_domain
    and status = 'pending'
  for update;

  if approval_record.id is null then
    raise exception 'No pending % approval exists', p_domain using errcode = 'P0002';
  end if;

  update public.market_os_ambassador_settings_approvals
  set status = p_decision,
      decision_note = btrim(p_note),
      decided_by_actor_id = p_actor_id,
      decided_at = now(),
      updated_at = now()
  where id = approval_record.id
  returning * into approval_record;

  next_status := 'pending_approval';
  if p_decision = 'rejected' then
    next_status := 'rejected';
  elsif p_decision = 'revision_requested' then
    next_status := 'revision_requested';
  else
    select count(*) into remaining
    from public.market_os_ambassador_settings_approvals
    where version_id = target.id
      and approval_round = target.approval_round
      and status = 'pending';
    if remaining = 0 then next_status := 'approved'; end if;
  end if;

  update public.market_os_ambassador_settings_versions
  set status = next_status,
      approved_at = case when next_status = 'approved' then now() else null end,
      rejected_at = case when next_status = 'rejected' then now() else null end,
      updated_by_actor_id = p_actor_id,
      updated_at = now()
  where id = target.id
  returning * into target;

  audit_tenant := target.tenant_id;
  audit_organization := target.organization_id;

  insert into public.market_os_ambassador_settings_runtime_events (
    id, tenant_id, organization_id, version_id, event_type, status,
    summary, details, actor_id, request_id, created_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id, target.id,
    'approval_decision', p_decision,
    p_domain || ' approval ' || replace(p_decision, '_', ' '),
    jsonb_build_object('domain', p_domain, 'decision', p_decision, 'note', btrim(p_note)),
    p_actor_id, p_request_id, now()
  );

  insert into public.market_os_ambassador_audit_logs (
    id, tenant_id, organization_id, entity_type, entity_id, action, summary,
    actor_id, actor_name, actor_role, request_id, payload,
    before_snapshot, after_snapshot, created_at
  ) values (
    gen_random_uuid(), audit_tenant, audit_organization,
    'market_os_ambassador_settings_approvals', approval_record.id,
    'settings_' || p_domain || '_' || p_decision,
    p_domain || ' settings approval ' || replace(p_decision, '_', ' '),
    p_actor_id, actor_name, actor_role, p_request_id,
    jsonb_build_object('versionId', target.id, 'domain', p_domain, 'decision', p_decision, 'note', btrim(p_note)),
    null, to_jsonb(approval_record), now()
  );

  existing_result := to_jsonb(target);
  insert into public.market_os_ambassador_idempotency (
    tenant_id, organization_id, operation, idempotency_key, actor_id, result
  ) values (
    target.tenant_id, target.organization_id, 'settings_approval', v_idempotency_key, p_actor_id, existing_result
  ) on conflict (tenant_id, organization_id, operation, idempotency_key)
    do update set result = excluded.result;

  return existing_result;
end $$;


--
-- Name: market_os_ambassador_effective_settings_configuration(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_effective_settings_configuration(p_tenant_id text, p_organization_id text, p_scope_type text DEFAULT NULL::text, p_scope_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((
    select version.configuration
    from public.market_os_ambassador_settings_active_scopes active
    join public.market_os_ambassador_settings_versions version
      on version.id = active.current_version_id
    where active.tenant_id = p_tenant_id
      and active.organization_id = p_organization_id
      and version.status = 'published'
      and (
        (active.scope_type = p_scope_type and lower(active.scope_key) = lower(coalesce(p_scope_key, '')))
        or (active.scope_type = 'organization' and active.scope_key = 'default')
      )
    order by case
      when active.scope_type = p_scope_type and lower(active.scope_key) = lower(coalesce(p_scope_key, '')) then 0
      else 1
    end
    limit 1
  ), '{}'::jsonb)
$$;


--
-- Name: market_os_ambassador_enforce_mission_assignment_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_enforce_mission_assignment_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  configuration jsonb;
  mission_rules jsonb;
  maximum_concurrent integer;
  active_count integer;
  mission_territory text;
begin
  select mission.territory_id::text into mission_territory
  from public.market_os_ambassador_missions mission
  where mission.id = new.mission_id;

  configuration := public.market_os_ambassador_effective_settings_configuration(
    new.tenant_id, new.organization_id,
    case when mission_territory is null then 'organization' else 'territory' end,
    case when mission_territory is null then 'default' else mission_territory end
  );
  mission_rules := coalesce(configuration -> 'missions', '{}'::jsonb);
  maximum_concurrent := coalesce((mission_rules ->> 'maximumConcurrentMissions')::integer, 4);

  if new.status in ('assigned','accepted') then
    if tg_op = 'UPDATE'
      and old.status in ('assigned','accepted')
      and old.ambassador_id is not distinct from new.ambassador_id then
      return new;
    end if;
    perform pg_advisory_xact_lock(hashtext(new.tenant_id || ':' || new.organization_id || ':ambassador:' || new.ambassador_id::text)::bigint);
    select count(*) into active_count
    from public.market_os_ambassador_mission_assignments assignment
    where assignment.tenant_id = new.tenant_id
      and assignment.organization_id = new.organization_id
      and assignment.ambassador_id = new.ambassador_id
      and assignment.status in ('assigned','accepted')
      and assignment.archived_at is null
      and assignment.id <> new.id;
    if active_count >= maximum_concurrent then
      raise exception 'Ambassador concurrent mission limit is % under the effective policy', maximum_concurrent using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: market_os_ambassador_enforce_territory_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_enforce_territory_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  configuration jsonb;
  territory_rules jsonb;
  maximum_active integer;
  approved_count integer;
  allow_backup boolean;
  allow_temporary boolean;
  maximum_radius numeric;
begin
  configuration := public.market_os_ambassador_effective_settings_configuration(
    new.tenant_id, new.organization_id, 'territory', new.territory_id::text
  );
  territory_rules := coalesce(configuration -> 'territories', '{}'::jsonb);
  maximum_active := coalesce((territory_rules ->> 'maximumAmbassadorsPerTerritory')::integer, 25);
  allow_backup := coalesce((territory_rules ->> 'allowBackupAssignments')::boolean, true);
  allow_temporary := coalesce((territory_rules ->> 'allowTemporaryAssignments')::boolean, true);
  maximum_radius := coalesce((territory_rules ->> 'travelRadiusKm')::numeric, 50);

  if new.assignment_type = 'backup' and not allow_backup then
    raise exception 'Backup territory assignments are disabled by the effective Ambassador policy' using errcode = '23514';
  end if;
  if new.assignment_type = 'temporary' and not allow_temporary then
    raise exception 'Temporary territory assignments are disabled by the effective Ambassador policy' using errcode = '23514';
  end if;
  if new.radius_km is not null and new.radius_km > maximum_radius then
    raise exception 'Territory assignment radius exceeds the effective policy limit of % km', maximum_radius using errcode = '23514';
  end if;

  if new.status = 'approved' then
    if tg_op = 'UPDATE' and old.status = 'approved' then
      return new;
    end if;
    perform pg_advisory_xact_lock(hashtext(new.tenant_id || ':' || new.organization_id || ':territory:' || new.territory_id::text)::bigint);
    select count(*) into approved_count
    from public.market_os_ambassador_territory_assignments assignment
    where assignment.tenant_id = new.tenant_id
      and assignment.organization_id = new.organization_id
      and assignment.territory_id = new.territory_id
      and assignment.status = 'approved'
      and assignment.archived_at is null
      and assignment.id <> new.id;
    if approved_count >= maximum_active then
      raise exception 'Territory capacity is limited to % active Ambassadors by the effective policy', maximum_active using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: market_os_ambassador_guard_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_guard_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  from_value text;
  to_value text;
  allowed text[];
begin
  if tg_table_name = 'market_os_ambassadors' then
    from_value := lower(replace(coalesce(old.lifecycle_stage, old.status, 'candidate'), '-', '_'));
    to_value := lower(replace(coalesce(new.lifecycle_stage, new.status, from_value), '-', '_'));
    new.lifecycle_stage := to_value;
  elsif tg_table_name = 'market_os_ambassador_recruitment' then
    from_value := lower(replace(coalesce(old.stage, 'sourced'), '-', '_'));
    to_value := lower(replace(coalesce(new.stage, from_value), '-', '_'));
    new.stage := to_value;
  else
    from_value := lower(replace(coalesce(old.status, ''), '-', '_'));
    to_value := lower(replace(coalesce(new.status, from_value), '-', '_'));
    new.status := to_value;
  end if;

  if from_value = to_value then return new; end if;

  if tg_table_name = 'market_os_ambassadors' then
    allowed := case from_value
      when 'candidate' then array['onboarding','rejected','archived']
      when 'onboarding' then array['active','suspended','archived']
      when 'active' then array['suspended','inactive','archived']
      when 'suspended' then array['active','inactive','archived']
      when 'inactive' then array['active','archived']
      when 'rejected' then array['archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_recruitment' then
    allowed := case from_value
      when 'sourced' then array['screened','rejected','archived']
      when 'screened' then array['interview','rejected','archived']
      when 'interview' then array['approved','rejected','archived']
      when 'approved' then array['converted','rejected','archived']
      when 'rejected' then array['screened','archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_missions' then
    allowed := case from_value
      when 'draft' then array['assigned','archived']
      when 'assigned' then array['accepted','in_progress','cancelled','archived']
      when 'accepted' then array['in_progress','cancelled','archived']
      when 'in_progress' then array['submitted','blocked','cancelled','archived']
      when 'blocked' then array['in_progress','cancelled','archived']
      when 'submitted' then array['approved','rejected','archived']
      when 'rejected' then array['in_progress','submitted','archived']
      when 'approved' then array['completed','archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_leads' then
    allowed := case from_value
      when 'new' then array['contacted','qualified','lost','archived']
      when 'contacted' then array['follow_up','qualified','lost','archived']
      when 'follow_up' then array['contacted','qualified','lost','archived']
      when 'qualified' then array['converted','lost','archived']
      when 'lost' then array['follow_up','archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_conversions' then
    allowed := case from_value
      when 'pending' then array['under_review','proof_requested','escalated','validated','rejected','archived']
      when 'under_review' then array['proof_requested','escalated','validated','rejected','archived']
      when 'proof_requested' then array['under_review','validated','rejected','archived']
      when 'escalated' then array['under_review','validated','rejected','archived']
      when 'validated' then array['paid','archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_incentives' then
    allowed := case from_value when 'pending' then array['approved','rejected','archived'] when 'approved' then array['paid','rejected','archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_proofs' then
    allowed := case from_value
      when 'submitted' then array['under_review','approved','rejected','revision_requested','archived']
      when 'under_review' then array['approved','rejected','revision_requested','archived']
      when 'revision_requested' then array['submitted','under_review','archived'] else array['archived'] end;
  elsif tg_table_name = 'market_os_ambassador_payouts' then
    allowed := case from_value
      when 'draft' then array['pending_approval','cancelled','archived']
      when 'pending_approval' then array['approved','rejected','cancelled','archived']
      when 'approved' then array['processing','paid','cancelled','archived']
      when 'processing' then array['paid','cancelled','archived'] else array['archived'] end;
  end if;

  if not (to_value = any(coalesce(allowed, array[]::text[]))) then
    raise exception 'Illegal Ambassador lifecycle transition on %: % -> %', tg_table_name, from_value, to_value using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: market_os_ambassador_guard_settings_approval_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_guard_settings_approval_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.status <> 'pending' then
    raise exception 'Decided Ambassador settings approvals are immutable' using errcode = '42501';
  end if;
  if new.status not in ('approved','rejected','revision_requested') then
    raise exception 'Invalid Ambassador settings approval decision' using errcode = '23514';
  end if;
  if new.decided_by_actor_id is null or new.decided_at is null then
    raise exception 'Approval decision requires an actor and timestamp' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: market_os_ambassador_guard_settings_version_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_guard_settings_version_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  allowed text[];
begin
  if old.status = new.status then
    return new;
  end if;

  allowed := case old.status
    when 'draft' then array['pending_approval','cancelled']
    when 'revision_requested' then array['draft','pending_approval','cancelled']
    when 'pending_approval' then array['approved','rejected','revision_requested','cancelled']
    when 'approved' then array['scheduled','published','cancelled']
    when 'scheduled' then array['published','approved','cancelled']
    when 'published' then array['superseded','rolled_back']
    when 'superseded' then array['rolled_back']
    else array[]::text[]
  end;

  if not (new.status = any(allowed)) then
    raise exception 'Invalid Ambassador settings version transition: % -> %', old.status, new.status
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: market_os_ambassador_has_permission(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_has_permission(p_permission text, p_tenant_id text, p_organization_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.market_os_ambassador_actor_roles ar
    join public.market_os_ambassador_role_permissions rp on rp.role_key = ar.role_key and rp.enabled
    where ar.auth_user_id = auth.uid()
      and ar.status = 'active'
      and ar.tenant_id = p_tenant_id
      and ar.organization_id = p_organization_id
      and (rp.permission_key = p_permission or rp.permission_key = '*')
  )
$$;


--
-- Name: market_os_ambassador_identity_hash(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_identity_hash(raw_email text, raw_phone text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when nullif(lower(btrim(coalesce(raw_email, ''))), '') is not null
      then encode(digest('email:' || lower(btrim(raw_email)), 'sha256'), 'hex')
    when public.market_os_ambassador_normalize_phone(raw_phone) is not null
      then encode(digest('phone:' || public.market_os_ambassador_normalize_phone(raw_phone), 'sha256'), 'hex')
    else null
  end
$$;


--
-- Name: market_os_ambassador_lifecycle_decide_request(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_decide_request(p_request_id text, p_tenant_id text, p_organization_id text, p_decision text, p_note text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request
    public.market_os_ambassador_lifecycle_requests%rowtype;

  v_actor_may_self_decide boolean := false;
  v_ceo_override_used boolean := false;
begin
  if p_decision not in (
    'approved',
    'rejected'
  ) then
    raise exception
      'Unsupported deletion decision';
  end if;

  select *
  into v_request
  from
    public.market_os_ambassador_lifecycle_requests
  where
    id::text = p_request_id
    and tenant_id = p_tenant_id
    and organization_id =
      p_organization_id
  for update;

  if not found then
    raise exception
      'Deletion request was not found';
  end if;

  if v_request.status <> 'requested' then
    raise exception
      'Only requested deletions may be decided. Current status: %',
      v_request.status;
  end if;

  select
    coalesce(
      bool_or(
        authority.active
        and authority.authority_code = 'ceo'
        and authority.may_self_decide
      ),
      false
    )
  into
    v_actor_may_self_decide
  from
    public.market_os_ambassador_lifecycle_authorities
      as authority
  where
    authority.actor_app_user_id =
      p_actor_app_user_id;

  v_ceo_override_used :=
    v_request.requested_by_app_user_id =
      p_actor_app_user_id
    and v_actor_may_self_decide;

  if
    v_request.requested_by_app_user_id =
      p_actor_app_user_id
    and not v_actor_may_self_decide
  then
    raise exception
      'Separation of duties: the requester cannot approve or reject their own deletion request';
  end if;

  if p_decision = 'approved' then
    update
      public.market_os_ambassador_lifecycle_requests
    set
      status = 'approved',
      approved_by_app_user_id =
        p_actor_app_user_id,
      approved_by_display_name =
        p_actor_display_name,
      approval_note = p_note,
      approved_at = now(),
      updated_at = now()
    where id = v_request.id
    returning *
    into v_request;
  else
    update
      public.market_os_ambassador_lifecycle_requests
    set
      status = 'rejected',
      rejected_by_app_user_id =
        p_actor_app_user_id,
      rejected_by_display_name =
        p_actor_display_name,
      rejection_note = p_note,
      rejected_at = now(),
      updated_at = now()
    where id = v_request.id
    returning *
    into v_request;
  end if;

  insert into
    public.market_os_ambassador_lifecycle_events (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      request_id,
      event_type,
      actor_app_user_id,
      actor_display_name,
      details
    )
  values (
    v_request.tenant_id,
    v_request.organization_id,
    v_request.entity_type,
    v_request.entity_id,
    v_request.id,
    'deletion_' || p_decision,
    p_actor_app_user_id,
    p_actor_display_name,
    jsonb_build_object(
      'note',
      p_note,
      'authority',
      case
        when v_actor_may_self_decide
          then 'ceo'
        else 'standard'
      end,
      'ceo_self_decision_override',
      v_ceo_override_used
    )
  );

  return to_jsonb(v_request);
end;
$$;


--
-- Name: market_os_ambassador_lifecycle_delete_now(text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_delete_now(p_entity_type text, p_entity_id text, p_tenant_id text, p_organization_id text, p_confirmation text, p_reason text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_entity_type text :=
    lower(trim(p_entity_type));

  v_primary_table regclass;
  v_entity jsonb;
  v_display_label text;

  v_ambassador_ids text[] :=
    array[]::text[];

  v_candidate_ids text[] :=
    array[]::text[];

  v_lead_ids text[] :=
    array[]::text[];

  v_relation record;
  v_column record;

  v_conditions text[];
  v_scope_conditions text[];

  v_sql text;
  v_count integer := 0;
  v_deleted_related integer := 0;
  v_deleted_primary integer := 0;
  v_pass integer;

  v_has_tenant boolean;
  v_has_organization boolean;
begin
  if v_entity_type not in (
    'ambassador',
    'candidate',
    'lead'
  ) then
    raise exception
      'Unsupported lifecycle entity type: %',
      p_entity_type;
  end if;

  v_primary_table :=
    public.market_os_ambassador_lifecycle_entity_table(
      v_entity_type
    );

  if v_primary_table is null then
    raise exception
      'Primary table does not exist for %',
      v_entity_type;
  end if;

  execute format(
    'select to_jsonb(t)
       from %s t
      where t.id::text = $1
        and t.tenant_id::text = $2
        and t.organization_id::text = $3
      limit 1',
    v_primary_table
  )
  into v_entity
  using
    p_entity_id,
    p_tenant_id,
    p_organization_id;

  if v_entity is null then
    raise exception
      'The selected scoped record was not found';
  end if;

  v_display_label :=
    coalesce(
      nullif(v_entity->>'full_name', ''),
      nullif(v_entity->>'display_name', ''),
      nullif(v_entity->>'candidate_name', ''),
      nullif(v_entity->>'lead_name', ''),
      nullif(v_entity->>'contact_name', ''),
      nullif(v_entity->>'name', ''),
      'Record ' || right(p_entity_id, 8)
    );

  if trim(p_confirmation) <>
     trim(v_display_label) then
    raise exception
      'Confirmation refused. Enter the exact record name: %',
      v_display_label;
  end if;

  if length(trim(p_reason)) < 5 then
    raise exception
      'A deletion reason is required';
  end if;

  if v_entity_type = 'ambassador' then
    v_ambassador_ids :=
      array[p_entity_id];

    if exists (
      select 1
      from pg_attribute
      where attrelid =
        'public.market_os_ambassadors'::regclass
        and attname = 'candidate_id'
        and attnum > 0
        and not attisdropped
    ) then
      execute
        'select coalesce(
           array_agg(distinct candidate_id::text)
             filter (where candidate_id is not null),
           array[]::text[]
         )
         from public.market_os_ambassadors
         where id::text = $1
           and tenant_id::text = $2
           and organization_id::text = $3'
      into v_candidate_ids
      using
        p_entity_id,
        p_tenant_id,
        p_organization_id;
    end if;
  end if;

  if v_entity_type = 'candidate' then
    v_candidate_ids :=
      array[p_entity_id];

    if to_regclass(
      'public.market_os_ambassadors'
    ) is not null
    and exists (
      select 1
      from pg_attribute
      where attrelid =
        'public.market_os_ambassadors'::regclass
        and attname = 'candidate_id'
        and attnum > 0
        and not attisdropped
    ) then
      execute
        'select coalesce(
           array_agg(id::text),
           array[]::text[]
         )
         from public.market_os_ambassadors
         where candidate_id::text = $1
           and tenant_id::text = $2
           and organization_id::text = $3'
      into v_ambassador_ids
      using
        p_entity_id,
        p_tenant_id,
        p_organization_id;
    end if;
  end if;

  if v_entity_type = 'lead' then
    v_lead_ids :=
      array[p_entity_id];
  end if;

  if to_regclass(
    'public.market_os_ambassador_leads'
  ) is not null
  and cardinality(v_ambassador_ids) > 0
  and exists (
    select 1
    from pg_attribute
    where attrelid =
      'public.market_os_ambassador_leads'::regclass
      and attname = 'ambassador_id'
      and attnum > 0
      and not attisdropped
  ) then
    execute
      'select coalesce(
         array_agg(id::text),
         array[]::text[]
       )
       from public.market_os_ambassador_leads
       where ambassador_id::text = any($1)
         and tenant_id::text = $2
         and organization_id::text = $3'
    into v_lead_ids
    using
      v_ambassador_ids,
      p_tenant_id,
      p_organization_id;
  end if;

  /*
   * Delete every scoped related row whose column name ends in:
   * ambassador_id, candidate_id or lead_id.
   *
   * Multiple passes allow child records to disappear before
   * parent records when foreign keys are restrictive.
   */
  for v_pass in 1..8 loop
    for v_relation in
      select
        c.oid::regclass as relation_id,
        c.relname
      from pg_class c
      join pg_namespace n
        on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relkind in ('r', 'p')
        and c.relname not in (
          'market_os_ambassadors',
          'market_os_ambassador_recruitment',
          'market_os_ambassador_leads',
          'market_os_ambassador_actor_roles',
          'market_os_ambassador_role_permissions',
          'market_os_ambassador_lifecycle_states',
          'market_os_ambassador_lifecycle_requests',
          'market_os_ambassador_lifecycle_events',
          'market_os_ambassador_purge_ledger'
        )
        and c.relname not like
          'market_os_ambassadors_scope_backup_%'
    loop
      v_conditions :=
        array[]::text[];

      for v_column in
        select attname
        from pg_attribute
        where attrelid =
          v_relation.relation_id
          and attnum > 0
          and not attisdropped
          and (
            attname like '%ambassador_id'
            or attname like '%candidate_id'
            or attname like '%lead_id'
          )
      loop
        if v_column.attname like
           '%ambassador_id'
        and cardinality(
          v_ambassador_ids
        ) > 0 then
          v_conditions :=
            array_append(
              v_conditions,
              format(
                'd.%I::text = any($1)',
                v_column.attname
              )
            );
        end if;

        if v_column.attname like
           '%candidate_id'
        and cardinality(
          v_candidate_ids
        ) > 0 then
          v_conditions :=
            array_append(
              v_conditions,
              format(
                'd.%I::text = any($2)',
                v_column.attname
              )
            );
        end if;

        if v_column.attname like
           '%lead_id'
        and cardinality(
          v_lead_ids
        ) > 0 then
          v_conditions :=
            array_append(
              v_conditions,
              format(
                'd.%I::text = any($3)',
                v_column.attname
              )
            );
        end if;
      end loop;

      if cardinality(v_conditions) = 0 then
        continue;
      end if;

      select exists (
        select 1
        from pg_attribute
        where attrelid =
          v_relation.relation_id
          and attname = 'tenant_id'
          and attnum > 0
          and not attisdropped
      )
      into v_has_tenant;

      select exists (
        select 1
        from pg_attribute
        where attrelid =
          v_relation.relation_id
          and attname = 'organization_id'
          and attnum > 0
          and not attisdropped
      )
      into v_has_organization;

      v_scope_conditions :=
        array[]::text[];

      if v_has_tenant then
        v_scope_conditions :=
          array_append(
            v_scope_conditions,
            'd.tenant_id::text = $4'
          );
      end if;

      if v_has_organization then
        v_scope_conditions :=
          array_append(
            v_scope_conditions,
            'd.organization_id::text = $5'
          );
      end if;

      v_sql :=
        format(
          'delete from %s d
            where (%s)%s',
          v_relation.relation_id,
          array_to_string(
            v_conditions,
            ' or '
          ),
          case
            when cardinality(
              v_scope_conditions
            ) > 0
            then
              ' and ' ||
              array_to_string(
                v_scope_conditions,
                ' and '
              )
            else ''
          end
        );

      begin
        execute v_sql
        using
          v_ambassador_ids,
          v_candidate_ids,
          v_lead_ids,
          p_tenant_id,
          p_organization_id;

        get diagnostics
          v_count = row_count;

        v_deleted_related :=
          v_deleted_related +
          v_count;

      exception
        when foreign_key_violation then
          null;
      end;
    end loop;
  end loop;

  /*
   * Remove every lifecycle trace for the selected person.
   * Immutable triggers are disabled only inside this
   * transaction and restored before completion.
   */
  if exists (
    select 1
    from pg_trigger
    where tgrelid =
      'public.market_os_ambassador_lifecycle_events'::regclass
      and tgname =
        'market_os_ambassador_lifecycle_events_immutable'
      and not tgisinternal
  ) then
    alter table
      public.market_os_ambassador_lifecycle_events
    disable trigger
      market_os_ambassador_lifecycle_events_immutable;
  end if;

  if exists (
    select 1
    from pg_trigger
    where tgrelid =
      'public.market_os_ambassador_purge_ledger'::regclass
      and tgname =
        'market_os_ambassador_purge_ledger_immutable'
      and not tgisinternal
  ) then
    alter table
      public.market_os_ambassador_purge_ledger
    disable trigger
      market_os_ambassador_purge_ledger_immutable;
  end if;

  delete from
    public.market_os_ambassador_purge_ledger
  where request_id in (
    select id
    from
      public.market_os_ambassador_lifecycle_requests
    where tenant_id = p_tenant_id
      and organization_id =
        p_organization_id
      and (
        (
          entity_type = 'ambassador'
          and entity_id =
            any(v_ambassador_ids)
        )
        or (
          entity_type = 'candidate'
          and entity_id =
            any(v_candidate_ids)
        )
        or (
          entity_type = 'lead'
          and entity_id =
            any(v_lead_ids)
        )
      )
  );

  delete from
    public.market_os_ambassador_lifecycle_events
  where tenant_id = p_tenant_id
    and organization_id =
      p_organization_id
    and (
      (
        entity_type = 'ambassador'
        and entity_id =
          any(v_ambassador_ids)
      )
      or (
        entity_type = 'candidate'
        and entity_id =
          any(v_candidate_ids)
      )
      or (
        entity_type = 'lead'
        and entity_id =
          any(v_lead_ids)
      )
    );

  delete from
    public.market_os_ambassador_lifecycle_requests
  where tenant_id = p_tenant_id
    and organization_id =
      p_organization_id
    and (
      (
        entity_type = 'ambassador'
        and entity_id =
          any(v_ambassador_ids)
      )
      or (
        entity_type = 'candidate'
        and entity_id =
          any(v_candidate_ids)
      )
      or (
        entity_type = 'lead'
        and entity_id =
          any(v_lead_ids)
      )
    );

  delete from
    public.market_os_ambassador_lifecycle_states
  where tenant_id = p_tenant_id
    and organization_id =
      p_organization_id
    and (
      (
        entity_type = 'ambassador'
        and entity_id =
          any(v_ambassador_ids)
      )
      or (
        entity_type = 'candidate'
        and entity_id =
          any(v_candidate_ids)
      )
      or (
        entity_type = 'lead'
        and entity_id =
          any(v_lead_ids)
      )
    );

  alter table
    public.market_os_ambassador_lifecycle_events
  enable trigger
    market_os_ambassador_lifecycle_events_immutable;

  alter table
    public.market_os_ambassador_purge_ledger
  enable trigger
    market_os_ambassador_purge_ledger_immutable;

  /*
   * Delete the core records last.
   */
  if cardinality(v_lead_ids) > 0
  and to_regclass(
    'public.market_os_ambassador_leads'
  ) is not null then
    execute
      'delete from public.market_os_ambassador_leads
        where id::text = any($1)
          and tenant_id::text = $2
          and organization_id::text = $3'
    using
      v_lead_ids,
      p_tenant_id,
      p_organization_id;

    get diagnostics v_count = row_count;

    v_deleted_primary :=
      v_deleted_primary + v_count;
  end if;

  if cardinality(v_ambassador_ids) > 0
  and to_regclass(
    'public.market_os_ambassadors'
  ) is not null then
    execute
      'delete from public.market_os_ambassadors
        where id::text = any($1)
          and tenant_id::text = $2
          and organization_id::text = $3'
    using
      v_ambassador_ids,
      p_tenant_id,
      p_organization_id;

    get diagnostics v_count = row_count;

    v_deleted_primary :=
      v_deleted_primary + v_count;
  end if;

  if cardinality(v_candidate_ids) > 0
  and to_regclass(
    'public.market_os_ambassador_recruitment'
  ) is not null then
    execute
      'delete from public.market_os_ambassador_recruitment
        where id::text = any($1)
          and tenant_id::text = $2
          and organization_id::text = $3'
    using
      v_candidate_ids,
      p_tenant_id,
      p_organization_id;

    get diagnostics v_count = row_count;

    v_deleted_primary :=
      v_deleted_primary + v_count;
  end if;

  if v_deleted_primary = 0 then
    raise exception
      'No primary record was deleted';
  end if;

  return jsonb_build_object(
    'status',
      'deleted_permanently',

    'entityType',
      v_entity_type,

    'displayLabel',
      v_display_label,

    'deletedPrimaryRecords',
      v_deleted_primary,

    'deletedRelatedRecords',
      v_deleted_related,

    'deletedAt',
      now()
  );
end;
$_$;


--
-- Name: market_os_ambassador_lifecycle_dependency(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_dependency(p_table_name text, p_foreign_key text, p_dependency_key text, p_dependency_label text, p_entity_id text, p_tenant_id text, p_organization_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_table regclass;
  v_count bigint := 0;

  v_has_foreign_key boolean;
  v_has_tenant boolean;
  v_has_organization boolean;

  v_scope_sql text := '';
begin
  v_table :=
    to_regclass(
      'public.' || p_table_name
    );

  if v_table is null then
    return jsonb_build_object(
      'key', p_dependency_key,
      'label', p_dependency_label,
      'table', p_table_name,
      'available', false,
      'count', 0,
      'blocking', false
    );
  end if;

  select exists (
    select 1
    from pg_attribute
    where attrelid = v_table
      and attname = p_foreign_key
      and attnum > 0
      and not attisdropped
  )
  into v_has_foreign_key;

  if not v_has_foreign_key then
    return jsonb_build_object(
      'key', p_dependency_key,
      'label', p_dependency_label,
      'table', p_table_name,
      'available', false,
      'count', 0,
      'blocking', false
    );
  end if;

  select exists (
    select 1
    from pg_attribute
    where attrelid = v_table
      and attname = 'tenant_id'
      and attnum > 0
      and not attisdropped
  )
  into v_has_tenant;

  select exists (
    select 1
    from pg_attribute
    where attrelid = v_table
      and attname = 'organization_id'
      and attnum > 0
      and not attisdropped
  )
  into v_has_organization;

  if v_has_tenant then
    v_scope_sql :=
      v_scope_sql ||
      ' and d.tenant_id::text = $2';
  end if;

  if v_has_organization then
    v_scope_sql :=
      v_scope_sql ||
      ' and d.organization_id::text = $3';
  end if;

  execute format(
    'select count(*)
       from %s d
      where d.%I::text = $1%s',
    v_table,
    p_foreign_key,
    v_scope_sql
  )
  into v_count
  using
    p_entity_id,
    p_tenant_id,
    p_organization_id;

  return jsonb_build_object(
    'key', p_dependency_key,
    'label', p_dependency_label,
    'table', p_table_name,
    'available', true,
    'count', v_count,
    'blocking', v_count > 0
  );
end;
$_$;


--
-- Name: market_os_ambassador_lifecycle_entity_table(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_entity_table(p_entity_type text) RETURNS regclass
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_relation text;
begin
  v_relation :=
    case lower(trim(p_entity_type))
      when 'ambassador'
        then 'public.market_os_ambassadors'

      when 'candidate'
        then 'public.market_os_ambassador_recruitment'

      when 'lead'
        then 'public.market_os_ambassador_leads'

      else null
    end;

  if v_relation is null then
    raise exception
      'Unsupported lifecycle entity type: %',
      p_entity_type;
  end if;

  return to_regclass(v_relation);
end;
$$;


--
-- Name: market_os_ambassador_lifecycle_execute_delete(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_execute_delete(p_request_id text, p_tenant_id text, p_organization_id text, p_confirmation text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_request
    public.market_os_ambassador_lifecycle_requests%rowtype;

  v_preview jsonb;
  v_table regclass;

  v_deleted integer;
  v_ledger_hash text;

  v_actor_may_self_execute boolean := false;
  v_ceo_override_used boolean := false;
begin
  select *
  into v_request
  from public.market_os_ambassador_lifecycle_requests
  where id::text = p_request_id
    and tenant_id = p_tenant_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception
      'Deletion request was not found';
  end if;

  if v_request.status <> 'approved' then
    raise exception
      'Deletion request must be approved before execution. Current status: %',
      v_request.status;
  end if;

  select
    coalesce(
      bool_or(
        authority.active
        and authority.authority_code = 'ceo'
        and authority.may_self_execute
      ),
      false
    )
  into v_actor_may_self_execute
  from public.market_os_ambassador_lifecycle_authorities
    as authority
  where authority.actor_app_user_id =
    p_actor_app_user_id;

  v_ceo_override_used :=
    v_actor_may_self_execute
    and (
      v_request.requested_by_app_user_id =
        p_actor_app_user_id
      or
      v_request.approved_by_app_user_id =
        p_actor_app_user_id
    );

  if
    v_request.requested_by_app_user_id =
      p_actor_app_user_id
    and not v_actor_may_self_execute
  then
    raise exception
      'Separation of duties: the requester cannot execute the purge';
  end if;

  if
    v_request.approved_by_app_user_id =
      p_actor_app_user_id
    and not v_actor_may_self_execute
  then
    raise exception
      'Separation of duties: the approver cannot execute the purge';
  end if;

  if p_confirmation <>
    (
      'DELETE-' ||
      upper(
        right(
          v_request.entity_id,
          8
        )
      )
    )
  then
    raise exception
      'The permanent deletion confirmation code is invalid';
  end if;

  v_preview :=
    public.market_os_ambassador_lifecycle_preview(
      v_request.entity_type,
      v_request.entity_id,
      v_request.tenant_id,
      v_request.organization_id
    );

  if not coalesce(
    (
      v_preview ->
        'canPermanentDelete'
    )::boolean,
    false
  ) then
    raise exception
      'Dependencies changed after approval. Permanent deletion is blocked.';
  end if;

  if
    v_preview ->> 'snapshotHash' <>
    v_request.entity_snapshot_hash
  then
    raise exception
      'The target record changed after approval. A new deletion request is required.';
  end if;

  v_table :=
    public.market_os_ambassador_lifecycle_entity_table(
      v_request.entity_type
    );

  update
    public.market_os_ambassador_lifecycle_requests
  set
    status = 'executing',
    updated_at = now()
  where id = v_request.id;

  execute format(
    'delete from %s
      where id::text = $1
        and tenant_id::text = $2
        and organization_id::text = $3',
    v_table
  )
  using
    v_request.entity_id,
    v_request.tenant_id,
    v_request.organization_id;

  get diagnostics
    v_deleted = row_count;

  if v_deleted <> 1 then
    raise exception
      'Expected to delete exactly one primary record; deleted %',
      v_deleted;
  end if;

  update
    public.market_os_ambassador_lifecycle_requests
  set
    status = 'completed',
    executed_by_app_user_id =
      p_actor_app_user_id,
    executed_by_display_name =
      p_actor_display_name,
    executed_at = now(),
    execution_error = null,
    updated_at = now()
  where id = v_request.id
  returning *
  into v_request;

  insert into
    public.market_os_ambassador_lifecycle_states (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      lifecycle_state,
      previous_business_status,
      reason,
      changed_by_app_user_id,
      changed_by_display_name,
      deleted_at,
      updated_at
    )
  values (
    v_request.tenant_id,
    v_request.organization_id,
    v_request.entity_type,
    v_request.entity_id,
    'deleted',
    null,
    v_request.reason_detail,
    p_actor_app_user_id,
    p_actor_display_name,
    now(),
    now()
  )
  on conflict (
    tenant_id,
    organization_id,
    entity_type,
    entity_id
  )
  do update set
    lifecycle_state = 'deleted',
    reason = excluded.reason,
    changed_by_app_user_id =
      excluded.changed_by_app_user_id,
    changed_by_display_name =
      excluded.changed_by_display_name,
    deleted_at = now(),
    updated_at = now();

  v_ledger_hash :=
    encode(
      digest(
        concat_ws(
          ':',
          v_request.id::text,
          v_request.entity_hash,
          v_request.requested_by_app_user_id,
          v_request.approved_by_app_user_id,
          p_actor_app_user_id,
          now()::text
        ),
        'sha256'
      ),
      'hex'
    );

  insert into
    public.market_os_ambassador_purge_ledger (
      tenant_id,
      organization_id,
      request_id,
      entity_type,
      entity_hash,
      reason_code,
      dependency_summary,
      requested_by_app_user_id,
      approved_by_app_user_id,
      executed_by_app_user_id,
      executed_at,
      ledger_hash
    )
  values (
    v_request.tenant_id,
    v_request.organization_id,
    v_request.id,
    v_request.entity_type,
    v_request.entity_hash,
    v_request.reason_code,
    v_preview,
    v_request.requested_by_app_user_id,
    v_request.approved_by_app_user_id,
    p_actor_app_user_id,
    v_request.executed_at,
    v_ledger_hash
  );

  insert into
    public.market_os_ambassador_lifecycle_events (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      request_id,
      event_type,
      actor_app_user_id,
      actor_display_name,
      details
    )
  values (
    v_request.tenant_id,
    v_request.organization_id,
    v_request.entity_type,
    v_request.entity_id,
    v_request.id,
    'permanent_deletion_completed',
    p_actor_app_user_id,
    p_actor_display_name,
    jsonb_build_object(
      'ledgerHash',
        v_ledger_hash,
      'reasonCode',
        v_request.reason_code,
      'executorAuthority',
        case
          when v_actor_may_self_execute
            then 'ceo'
          else 'standard'
        end,
      'ceoExecutionOverride',
        v_ceo_override_used
    )
  );

  return jsonb_build_object(
    'requestId',
      v_request.id,
    'entityType',
      v_request.entity_type,
    'entityHash',
      v_request.entity_hash,
    'status',
      'completed',
    'ledgerHash',
      v_ledger_hash,
    'executedAt',
      v_request.executed_at
  );
end;
$_$;


--
-- Name: market_os_ambassador_lifecycle_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

