    LANGUAGE plpgsql
    AS $$
begin
  raise exception
    'Immutable Ambassador lifecycle evidence cannot be modified or deleted';
end;
$$;


--
-- Name: market_os_ambassador_lifecycle_inventory(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_inventory(p_entity_type text, p_tenant_id text, p_organization_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_table regclass;
  v_inventory jsonb;
begin
  v_table :=
    public.market_os_ambassador_lifecycle_entity_table(
      p_entity_type
    );

  if v_table is null then
    return '[]'::jsonb;
  end if;

  execute format(
    $query$
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id',
              t.id::text,

            'label',
              coalesce(
                nullif(
                  to_jsonb(t)->>'full_name',
                  ''
                ),
                nullif(
                  to_jsonb(t)->>'display_name',
                  ''
                ),
                nullif(
                  to_jsonb(t)->>'candidate_name',
                  ''
                ),
                nullif(
                  to_jsonb(t)->>'lead_name',
                  ''
                ),
                nullif(
                  to_jsonb(t)->>'contact_name',
                  ''
                ),
                nullif(
                  to_jsonb(t)->>'name',
                  ''
                ),
                'Record ' ||
                  right(t.id::text, 8)
              ),

            'businessStatus',
              coalesce(
                nullif(
                  to_jsonb(t)->>'status',
                  ''
                ),
                nullif(
                  to_jsonb(t)->>'stage',
                  ''
                ),
                'active'
              ),

            'lifecycleState',
              coalesce(
                s.lifecycle_state,
                'active'
              ),

            'email',
              coalesce(
                to_jsonb(t)->>'email',
                ''
              ),

            'phone',
              coalesce(
                to_jsonb(t)->>'phone',
                to_jsonb(t)->>'whatsapp',
                ''
              ),

            'city',
              coalesce(
                to_jsonb(t)->>'city',
                to_jsonb(t)->>'main_city',
                ''
              ),

            'reference',
              coalesce(
                to_jsonb(t)->>'reference',
                to_jsonb(t)->>'code',
                ''
              ),

            'createdAt',
              coalesce(
                to_jsonb(t)->>'created_at',
                ''
              )
          )
          order by coalesce(
            to_jsonb(t)->>'updated_at',
            to_jsonb(t)->>'created_at',
            ''
          ) desc
        ),
        '[]'::jsonb
      )
      from %s t

      left join
        public.market_os_ambassador_lifecycle_states s
        on s.tenant_id = $1
       and s.organization_id = $2
       and s.entity_type = $3
       and s.entity_id = t.id::text

      where t.tenant_id::text = $1
        and t.organization_id::text = $2
    $query$,
    v_table
  )
  into v_inventory
  using
    p_tenant_id,
    p_organization_id,
    lower(trim(p_entity_type));

  return coalesce(
    v_inventory,
    '[]'::jsonb
  );
end;
$_$;


--
-- Name: market_os_ambassador_lifecycle_preview(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_preview(p_entity_type text, p_entity_id text, p_tenant_id text, p_organization_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_table regclass;
  v_entity jsonb;
  v_dependencies jsonb := '[]'::jsonb;
  v_dependency jsonb;
  v_blocker_count bigint := 0;
  v_state text;
begin
  v_table :=
    public.market_os_ambassador_lifecycle_entity_table(
      p_entity_type
    );

  if v_table is null then
    raise exception
      'The primary table for % does not exist',
      p_entity_type;
  end if;

  execute format(
    'select to_jsonb(t)
       from %s t
      where t.id::text = $1
        and t.tenant_id::text = $2
        and t.organization_id::text = $3
      limit 1',
    v_table
  )
  into v_entity
  using
    p_entity_id,
    p_tenant_id,
    p_organization_id;

  if v_entity is null then
    raise exception
      'Scoped % record % was not found',
      p_entity_type,
      p_entity_id;
  end if;

  select lifecycle_state
  into v_state
  from public.market_os_ambassador_lifecycle_states
  where tenant_id = p_tenant_id
    and organization_id =
      p_organization_id
    and entity_type =
      lower(trim(p_entity_type))
    and entity_id = p_entity_id;

  if lower(trim(p_entity_type)) =
     'ambassador' then

    foreach v_dependency in array array[
      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_mission_assignments',
        'ambassador_id',
        'missions',
        'Mission assignments',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_territory_assignment_history',
        'ambassador_id',
        'territories',
        'Territory history',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_leads',
        'ambassador_id',
        'leads',
        'Attributed leads',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_conversions',
        'ambassador_id',
        'conversions',
        'Validated conversions',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_proofs',
        'ambassador_id',
        'proofs',
        'Operational proofs',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_incentives',
        'ambassador_id',
        'rewards',
        'Rewards and incentives',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_payouts',
        'ambassador_id',
        'payouts',
        'Payout records',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_onboarding',
        'ambassador_id',
        'onboarding',
        'Onboarding records',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      )
    ]
    loop
      v_dependencies :=
        v_dependencies ||
        jsonb_build_array(
          v_dependency
        );

      if coalesce(
        (v_dependency->>'blocking')::boolean,
        false
      ) then
        v_blocker_count :=
          v_blocker_count +
          coalesce(
            (v_dependency->>'count')::bigint,
            0
          );
      end if;
    end loop;
  end if;

  if lower(trim(p_entity_type)) =
     'candidate' then

    foreach v_dependency in array array[
      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassadors',
        'candidate_id',
        'converted_ambassadors',
        'Converted Ambassador profile',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_onboarding',
        'candidate_id',
        'onboarding',
        'Onboarding records',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_training_records',
        'candidate_id',
        'training',
        'Training and certification records',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      )
    ]
    loop
      v_dependencies :=
        v_dependencies ||
        jsonb_build_array(
          v_dependency
        );

      if coalesce(
        (v_dependency->>'blocking')::boolean,
        false
      ) then
        v_blocker_count :=
          v_blocker_count +
          coalesce(
            (v_dependency->>'count')::bigint,
            0
          );
      end if;
    end loop;
  end if;

  if lower(trim(p_entity_type)) =
     'lead' then

    foreach v_dependency in array array[
      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_conversions',
        'lead_id',
        'conversions',
        'Validated conversions',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_proofs',
        'lead_id',
        'proofs',
        'Conversion proofs',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_incentives',
        'lead_id',
        'rewards',
        'Reward records',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      ),

      public.market_os_ambassador_lifecycle_dependency(
        'market_os_ambassador_payouts',
        'lead_id',
        'payouts',
        'Payout records',
        p_entity_id,
        p_tenant_id,
        p_organization_id
      )
    ]
    loop
      v_dependencies :=
        v_dependencies ||
        jsonb_build_array(
          v_dependency
        );

      if coalesce(
        (v_dependency->>'blocking')::boolean,
        false
      ) then
        v_blocker_count :=
          v_blocker_count +
          coalesce(
            (v_dependency->>'count')::bigint,
            0
          );
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'entityType',
      lower(trim(p_entity_type)),

    'entityId',
      p_entity_id,

    'entity',
      v_entity,

    'lifecycleState',
      coalesce(v_state, 'active'),

    'dependencies',
      v_dependencies,

    'blockerCount',
      v_blocker_count,

    'canPermanentDelete',
      v_blocker_count = 0,

    'recommendedAction',
      case
        when v_blocker_count = 0
          then 'permanent_delete'
        else 'anonymize_or_archive'
      end,

    'snapshotHash',
      encode(
        digest(
          v_entity::text,
          'sha256'
        ),
        'hex'
      ),

    'generatedAt',
      now()
  );
end;
$_$;


--
-- Name: market_os_ambassador_lifecycle_request_delete(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_request_delete(p_entity_type text, p_entity_id text, p_tenant_id text, p_organization_id text, p_reason_code text, p_reason_detail text, p_idempotency_key text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_preview jsonb;

  v_request
    public.market_os_ambassador_lifecycle_requests%rowtype;

  v_label text;
begin
  v_preview :=
    public.market_os_ambassador_lifecycle_preview(
      p_entity_type,
      p_entity_id,
      p_tenant_id,
      p_organization_id
    );

  if not coalesce(
    (
      v_preview->
        'canPermanentDelete'
    )::boolean,
    false
  ) then
    raise exception
      'Permanent deletion is blocked by % linked record(s). Archive or anonymize instead.',
      coalesce(
        (
          v_preview->
            'blockerCount'
        )::bigint,
        0
      );
  end if;

  v_label :=
    coalesce(
      nullif(
        v_preview->'entity'->>'full_name',
        ''
      ),
      nullif(
        v_preview->'entity'->>'display_name',
        ''
      ),
      nullif(
        v_preview->'entity'->>'candidate_name',
        ''
      ),
      nullif(
        v_preview->'entity'->>'lead_name',
        ''
      ),
      nullif(
        v_preview->'entity'->>'contact_name',
        ''
      ),
      nullif(
        v_preview->'entity'->>'name',
        ''
      ),
      'Record ' ||
        right(p_entity_id, 8)
    );

  insert into
    public.market_os_ambassador_lifecycle_requests (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      entity_hash,
      display_label,
      reason_code,
      reason_detail,
      dependency_snapshot,
      entity_snapshot_hash,
      idempotency_key,
      requested_by_app_user_id,
      requested_by_display_name
    )
  values (
    p_tenant_id,
    p_organization_id,
    lower(trim(p_entity_type)),
    p_entity_id,

    encode(
      digest(
        concat_ws(
          ':',
          p_tenant_id,
          p_organization_id,
          lower(trim(p_entity_type)),
          p_entity_id
        ),
        'sha256'
      ),
      'hex'
    ),

    v_label,
    p_reason_code,
    p_reason_detail,
    v_preview,
    v_preview->>'snapshotHash',
    p_idempotency_key,
    p_actor_app_user_id,
    p_actor_display_name
  )
  on conflict (
    tenant_id,
    organization_id,
    idempotency_key
  )
  do update set
    updated_at = now()
  returning *
  into v_request;

  insert into
    public.market_os_ambassador_lifecycle_events (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      request_id,
      event_type,
      actor_app_user_id,
      actor_display_name,
      details
    )
  values (
    p_tenant_id,
    p_organization_id,
    lower(trim(p_entity_type)),
    p_entity_id,
    v_request.id,
    'deletion_requested',
    p_actor_app_user_id,
    p_actor_display_name,
    jsonb_build_object(
      'reasonCode',
        p_reason_code,

      'reasonDetail',
        p_reason_detail,

      'snapshotHash',
        v_request.entity_snapshot_hash
    )
  );

  return to_jsonb(v_request);
end;
$$;


--
-- Name: market_os_ambassador_lifecycle_set_state(text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_lifecycle_set_state(p_entity_type text, p_entity_id text, p_tenant_id text, p_organization_id text, p_action text, p_reason text, p_actor_app_user_id text, p_actor_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_table regclass;
  v_preview jsonb;

  v_previous_status text;
  v_target_state text;

  v_assignments text[] :=
    array[]::text[];

  v_column record;

  v_anonymous_reference text;
begin
  if p_action not in (
    'archive',
    'restore',
    'anonymize'
  ) then
    raise exception
      'Unsupported lifecycle state action: %',
      p_action;
  end if;

  v_preview :=
    public.market_os_ambassador_lifecycle_preview(
      p_entity_type,
      p_entity_id,
      p_tenant_id,
      p_organization_id
    );

  v_table :=
    public.market_os_ambassador_lifecycle_entity_table(
      p_entity_type
    );

  v_previous_status :=
    coalesce(
      v_preview->'entity'->>'status',
      v_preview->'entity'->>'stage',
      'active'
    );

  v_target_state :=
    case p_action
      when 'archive'
        then 'archived'

      when 'restore'
        then 'active'

      else 'anonymized'
    end;

  if p_action = 'anonymize' then
    v_anonymous_reference :=
      'ANON-' ||
      upper(
        right(
          encode(
            digest(
              p_entity_id,
              'sha256'
            ),
            'hex'
          ),
          10
        )
      );

    for v_column in
      select
        attname as column_name,
        format_type(
          atttypid,
          atttypmod
        ) as column_type

      from pg_attribute

      where attrelid = v_table
        and attnum > 0
        and not attisdropped

        and attname in (
          'full_name',
          'display_name',
          'candidate_name',
          'lead_name',
          'contact_name',
          'name',
          'email',
          'phone',
          'telephone',
          'mobile',
          'whatsapp',
          'address',
          'approx_address',
          'notes',
          'profile_notes'
        )

        and format_type(
          atttypid,
          atttypmod
        ) in (
          'text',
          'character varying',
          'character'
        )
    loop
      v_assignments :=
        array_append(
          v_assignments,
          format(
            '%I = %L',
            v_column.column_name,
            case
              when v_column.column_name =
                   'email'
                then lower(
                  v_anonymous_reference
                ) ||
                '@invalid.angelcare'

              when v_column.column_name in (
                'phone',
                'telephone',
                'mobile',
                'whatsapp'
              )
                then 'ANONYMIZED'

              when v_column.column_name in (
                'address',
                'approx_address'
              )
                then 'ANONYMIZED'

              when v_column.column_name in (
                'notes',
                'profile_notes'
              )
                then
                  '[ANONYMIZED BY CONTROLLED DATA LIFECYCLE]'

              else v_anonymous_reference
            end
          )
        );
    end loop;

    if exists (
      select 1
      from pg_attribute
      where attrelid = v_table
        and attname = 'updated_at'
        and attnum > 0
        and not attisdropped
    ) then
      v_assignments :=
        array_append(
          v_assignments,
          'updated_at = clock_timestamp()'
        );
    end if;

    if cardinality(v_assignments) > 0 then
      execute format(
        'update %s
            set %s
          where id::text = $1
            and tenant_id::text = $2
            and organization_id::text = $3',
        v_table,
        array_to_string(
          v_assignments,
          ', '
        )
      )
      using
        p_entity_id,
        p_tenant_id,
        p_organization_id;
    end if;
  end if;

  insert into
    public.market_os_ambassador_lifecycle_states (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      lifecycle_state,
      previous_business_status,
      reason,
      changed_by_app_user_id,
      changed_by_display_name,
      archived_at,
      restored_at,
      anonymized_at,
      updated_at
    )
  values (
    p_tenant_id,
    p_organization_id,
    lower(trim(p_entity_type)),
    p_entity_id,
    v_target_state,
    case
      when p_action = 'archive'
        then v_previous_status
      else null
    end,
    p_reason,
    p_actor_app_user_id,
    p_actor_display_name,
    case
      when p_action = 'archive'
        then now()
    end,
    case
      when p_action = 'restore'
        then now()
    end,
    case
      when p_action = 'anonymize'
        then now()
    end,
    now()
  )
  on conflict (
    tenant_id,
    organization_id,
    entity_type,
    entity_id
  )
  do update set
    lifecycle_state =
      excluded.lifecycle_state,

    previous_business_status =
      coalesce(
        excluded.previous_business_status,
        public.market_os_ambassador_lifecycle_states.previous_business_status
      ),

    reason = excluded.reason,

    changed_by_app_user_id =
      excluded.changed_by_app_user_id,

    changed_by_display_name =
      excluded.changed_by_display_name,

    archived_at =
      excluded.archived_at,

    restored_at =
      excluded.restored_at,

    anonymized_at =
      excluded.anonymized_at,

    updated_at = now();

  insert into
    public.market_os_ambassador_lifecycle_events (
      tenant_id,
      organization_id,
      entity_type,
      entity_id,
      event_type,
      actor_app_user_id,
      actor_display_name,
      details
    )
  values (
    p_tenant_id,
    p_organization_id,
    lower(trim(p_entity_type)),
    p_entity_id,
    p_action,
    p_actor_app_user_id,
    p_actor_display_name,
    jsonb_build_object(
      'reason',
        p_reason,

      'previousBusinessStatus',
        v_previous_status,

      'newLifecycleState',
        v_target_state
    )
  );

  return jsonb_build_object(
    'entityType',
      lower(trim(p_entity_type)),

    'entityId',
      p_entity_id,

    'action',
      p_action,

    'lifecycleState',
      v_target_state,

    'completedAt',
      now()
  );
end;
$_$;


--
-- Name: market_os_ambassador_normalize_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_normalize_phone(raw_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare digits text;
begin
  digits := regexp_replace(coalesce(raw_phone, ''), '[^0-9]', '', 'g');
  if digits = '' then return null; end if;
  if digits like '212%' then return '+' || digits; end if;
  if digits like '0%' then return '+212' || substr(digits, 2); end if;
  return '+' || digits;
end $$;


--
-- Name: market_os_ambassador_publish_settings_version(uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_publish_settings_version(p_version_id uuid, p_actor_id uuid, p_request_id text, p_legacy_projection jsonb, p_publication_source text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  target public.market_os_ambassador_settings_versions%rowtype;
  previous public.market_os_ambassador_settings_versions%rowtype;
  actor_role text;
  existing_result jsonb;
  v_idempotency_key text;
  legacy_id uuid;
  legacy_tenant public.market_os_ambassador_settings.tenant_id%type;
  legacy_organization public.market_os_ambassador_settings.organization_id%type;
  audit_tenant public.market_os_ambassador_audit_logs.tenant_id%type;
  audit_organization public.market_os_ambassador_audit_logs.organization_id%type;
begin
  select * into target
  from public.market_os_ambassador_settings_versions
  where id = p_version_id
  for update;

  if target.id is null then
    raise exception 'Settings version not found' using errcode = 'P0002';
  end if;

  if not public.market_os_ambassador_actor_has_permission(
    p_actor_id, 'settings.publish', target.tenant_id, target.organization_id
  ) then
    raise exception 'Actor lacks settings.publish permission' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null then
    raise exception 'Settings publication requires an idempotency request id' using errcode = '23514';
  end if;
  v_idempotency_key := target.id::text || ':' || coalesce(p_publication_source, 'manual') || ':' || p_request_id;
  select result into existing_result
  from public.market_os_ambassador_idempotency
  where tenant_id = target.tenant_id and organization_id = target.organization_id
    and operation = 'settings_publish' and idempotency_key = v_idempotency_key
    and actor_id = p_actor_id;
  if existing_result is not null then
    return existing_result || jsonb_build_object('idempotent', true);
  end if;

  if target.status not in ('approved','scheduled') then
    raise exception 'Only approved or scheduled settings can be published' using errcode = '23514';
  end if;

  if coalesce((target.validation_result ->> 'valid')::boolean, false) is not true then
    raise exception 'Settings validation must pass before publication' using errcode = '23514';
  end if;

  select role_key into actor_role
  from public.market_os_ambassador_actor_roles
  where id = p_actor_id and status = 'active';

  legacy_tenant := target.tenant_id;
  legacy_organization := target.organization_id;
  audit_tenant := target.tenant_id;
  audit_organization := target.organization_id;

  select v.* into previous
  from public.market_os_ambassador_settings_active_scopes active
  join public.market_os_ambassador_settings_versions v on v.id = active.current_version_id
  where active.tenant_id = target.tenant_id
    and active.organization_id = target.organization_id
    and active.scope_type = target.scope_type
    and active.scope_key = target.scope_key
  for update;

  if previous.id is not null and previous.id <> target.id then
    update public.market_os_ambassador_settings_versions
    set status = 'superseded', effective_to = now(), updated_at = now(), updated_by_actor_id = p_actor_id
    where id = previous.id;
  end if;

  update public.market_os_ambassador_settings_versions
  set status = 'published',
      effective_from = now(),
      effective_to = null,
      published_at = now(),
      published_by_actor_id = p_actor_id,
      scheduled_for = null,
      updated_at = now(),
      updated_by_actor_id = p_actor_id
  where id = target.id
  returning * into target;

  insert into public.market_os_ambassador_settings_active_scopes (
    id, tenant_id, organization_id, scope_type, scope_key, current_version_id,
    published_at, published_by_actor_id, created_at, updated_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id, target.scope_type, target.scope_key,
    target.id, now(), p_actor_id, now(), now()
  )
  on conflict (tenant_id, organization_id, scope_type, scope_key)
  do update set current_version_id = excluded.current_version_id,
                published_at = excluded.published_at,
                published_by_actor_id = excluded.published_by_actor_id,
                updated_at = now();

  select id into legacy_id
  from public.market_os_ambassador_settings
  where tenant_id = legacy_tenant and organization_id = legacy_organization
  limit 1;

  insert into public.market_os_ambassador_settings (
    id, tenant_id, organization_id, default_region, approval_rules, incentive_rules,
    onboarding_rules, training_rules, kpi_rules, notification_rules,
    created_by_actor_id, updated_by_actor_id, created_at, updated_at
  ) values (
    coalesce(legacy_id, gen_random_uuid()), legacy_tenant, legacy_organization,
    coalesce(p_legacy_projection ->> 'default_region', ''),
    coalesce(p_legacy_projection -> 'approval_rules', '{}'::jsonb),
    coalesce(p_legacy_projection -> 'incentive_rules', '{}'::jsonb),
    coalesce(p_legacy_projection -> 'onboarding_rules', '{}'::jsonb),
    coalesce(p_legacy_projection -> 'training_rules', '{}'::jsonb),
    coalesce(p_legacy_projection -> 'kpi_rules', '{}'::jsonb),
    coalesce(p_legacy_projection -> 'notification_rules', '{}'::jsonb),
    p_actor_id, p_actor_id, now(), now()
  )
  on conflict (tenant_id, organization_id)
  do update set default_region = excluded.default_region,
                approval_rules = excluded.approval_rules,
                incentive_rules = excluded.incentive_rules,
                onboarding_rules = excluded.onboarding_rules,
                training_rules = excluded.training_rules,
                kpi_rules = excluded.kpi_rules,
                notification_rules = excluded.notification_rules,
                updated_by_actor_id = p_actor_id,
                updated_at = now();

  if p_publication_source = 'scheduled' then
    update public.market_os_ambassador_settings_publications
    set status = 'published', published_at = now(), error_message = null, updated_at = now()
    where tenant_id = target.tenant_id
      and organization_id = target.organization_id
      and version_id = target.id
      and status in ('scheduled','processing');
  end if;

  insert into public.market_os_ambassador_settings_runtime_events (
    id, tenant_id, organization_id, version_id, event_type, status,
    summary, details, actor_id, request_id, created_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id, target.id,
    'publication', 'published',
    'Settings version v' || target.revision::text || ' published',
    jsonb_build_object('source', p_publication_source, 'revision', target.revision),
    p_actor_id, p_request_id, now()
  );

  insert into public.market_os_ambassador_audit_logs (
    id, tenant_id, organization_id, entity_type, entity_id, action, summary,
    actor_id, actor_role, request_id, payload, before_snapshot, after_snapshot, created_at
  ) values (
    gen_random_uuid(), audit_tenant, audit_organization,
    'market_os_ambassador_settings_versions', target.id,
    'settings_published_transactionally',
    'Published Ambassador settings version v' || target.revision::text,
    p_actor_id, actor_role, p_request_id,
    jsonb_build_object('source', p_publication_source, 'revision', target.revision),
    case when previous.id is null then null else to_jsonb(previous) end,
    to_jsonb(target), now()
  );

  existing_result := to_jsonb(target);
  insert into public.market_os_ambassador_idempotency (
    tenant_id, organization_id, operation, idempotency_key, actor_id, result
  ) values (
    target.tenant_id, target.organization_id, 'settings_publish', v_idempotency_key, p_actor_id, existing_result
  ) on conflict (tenant_id, organization_id, operation, idempotency_key)
    do update set result = excluded.result;

  return existing_result;
end $$;


--
-- Name: market_os_ambassador_rollback_settings_version(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_rollback_settings_version(p_target_version_id uuid, p_actor_id uuid, p_request_id text, p_reason text, p_legacy_projection jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  target public.market_os_ambassador_settings_versions%rowtype;
  restored public.market_os_ambassador_settings_versions%rowtype;
  published_json jsonb;
  existing_result jsonb;
  v_idempotency_key text;
  actor_role text;
  audit_tenant public.market_os_ambassador_audit_logs.tenant_id%type;
  audit_organization public.market_os_ambassador_audit_logs.organization_id%type;
begin
  select * into target
  from public.market_os_ambassador_settings_versions
  where id = p_target_version_id
  for update;

  if target.id is null then
    raise exception 'Rollback target not found' using errcode = 'P0002';
  end if;

  if target.status not in ('published','superseded','rolled_back') then
    raise exception 'Rollback target was never published' using errcode = '23514';
  end if;

  if btrim(coalesce(p_reason, '')) = '' then
    raise exception 'Rollback reason is required' using errcode = '23514';
  end if;

  if not public.market_os_ambassador_actor_has_permission(
    p_actor_id, 'settings.rollback', target.tenant_id, target.organization_id
  ) then
    raise exception 'Actor lacks settings.rollback permission' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null then
    raise exception 'Settings rollback requires an idempotency request id' using errcode = '23514';
  end if;
  v_idempotency_key := target.id::text || ':' || p_request_id;
  select result into existing_result
  from public.market_os_ambassador_idempotency
  where tenant_id = target.tenant_id and organization_id = target.organization_id
    and operation = 'settings_rollback' and idempotency_key = v_idempotency_key
    and actor_id = p_actor_id;
  if existing_result is not null then
    return existing_result || jsonb_build_object('idempotent', true);
  end if;

  select role_key into actor_role
  from public.market_os_ambassador_actor_roles
  where id = p_actor_id and status = 'active';

  audit_tenant := target.tenant_id;
  audit_organization := target.organization_id;

  insert into public.market_os_ambassador_settings_versions (
    id, tenant_id, organization_id, title, status, scope_type, scope_key,
    base_version_id, rollback_of_version_id, configuration, change_summary,
    validation_result, impact_snapshot, approval_round, approved_at,
    effective_from, published_at, published_by_actor_id,
    created_by_actor_id, updated_by_actor_id, created_at, updated_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id,
    'Rollback to v' || target.revision::text, 'approved', target.scope_type, target.scope_key,
    target.id, target.id, target.configuration, p_reason,
    target.validation_result, target.impact_snapshot, 0, now(),
    null, null, null,
    p_actor_id, p_actor_id, now(), now()
  ) returning * into restored;

  published_json := public.market_os_ambassador_publish_settings_version(
    restored.id, p_actor_id, p_request_id, p_legacy_projection, 'rollback'
  );
  restored := jsonb_populate_record(null::public.market_os_ambassador_settings_versions, published_json);

  insert into public.market_os_ambassador_audit_logs (
    id, tenant_id, organization_id, entity_type, entity_id, action, summary,
    actor_id, actor_role, request_id, payload, before_snapshot, after_snapshot, created_at
  ) values (
    gen_random_uuid(), audit_tenant, audit_organization,
    'market_os_ambassador_settings_versions', restored.id,
    'settings_rollback_published_transactionally',
    'Published rollback from Ambassador settings version v' || target.revision::text,
    p_actor_id, actor_role, p_request_id,
    jsonb_build_object('target_version_id', target.id, 'reason', p_reason),
    to_jsonb(target), to_jsonb(restored), now()
  );

  existing_result := to_jsonb(restored);
  insert into public.market_os_ambassador_idempotency (
    tenant_id, organization_id, operation, idempotency_key, actor_id, result
  ) values (
    target.tenant_id, target.organization_id, 'settings_rollback', v_idempotency_key, p_actor_id, existing_result
  ) on conflict (tenant_id, organization_id, operation, idempotency_key)
    do update set result = excluded.result;

  return existing_result;
end $$;


--
-- Name: market_os_ambassador_safe_double(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_safe_double(p_value text) RETURNS double precision
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select case
    when nullif(btrim(p_value), '') is null then null
    when btrim(p_value) ~ '^-?[0-9]+([.][0-9]+)?$' then btrim(p_value)::double precision
    else null
  end
$_$;


--
-- Name: market_os_ambassador_schedule_settings_version(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_schedule_settings_version(p_version_id uuid, p_actor_id uuid, p_request_id text, p_scheduled_for timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  target public.market_os_ambassador_settings_versions%rowtype;
  publication public.market_os_ambassador_settings_publications%rowtype;
  actor_role text;
  actor_name text;
  existing_result jsonb;
  v_idempotency_key text;
  audit_tenant public.market_os_ambassador_audit_logs.tenant_id%type;
  audit_organization public.market_os_ambassador_audit_logs.organization_id%type;
begin
  select * into target
  from public.market_os_ambassador_settings_versions
  where id = p_version_id
  for update;

  if target.id is null then
    raise exception 'Settings version not found' using errcode = 'P0002';
  end if;
  if not public.market_os_ambassador_actor_has_permission(
    p_actor_id, 'settings.publish', target.tenant_id, target.organization_id
  ) then
    raise exception 'Actor lacks settings.publish permission' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null then
    raise exception 'Settings publication scheduling requires an idempotency request id' using errcode = '23514';
  end if;
  v_idempotency_key := target.id::text || ':' || p_scheduled_for::text || ':' || p_request_id;
  select result into existing_result
  from public.market_os_ambassador_idempotency
  where tenant_id = target.tenant_id and organization_id = target.organization_id
    and operation = 'settings_schedule' and idempotency_key = v_idempotency_key
    and actor_id = p_actor_id;
  if existing_result is not null then
    return existing_result || jsonb_build_object('idempotent', true);
  end if;
  if target.status <> 'approved' then
    raise exception 'Only approved settings can be scheduled' using errcode = '23514';
  end if;
  if coalesce((target.validation_result ->> 'valid')::boolean, false) is not true then
    raise exception 'Settings validation must pass before scheduling' using errcode = '23514';
  end if;
  if p_scheduled_for <= now() + interval '1 minute' then
    raise exception 'Scheduled publication must be more than one minute in the future' using errcode = '23514';
  end if;

  select role_key, coalesce(display_name, auth_user_id::text)
    into actor_role, actor_name
  from public.market_os_ambassador_actor_roles
  where id = p_actor_id and status = 'active';

  insert into public.market_os_ambassador_settings_publications (
    id, tenant_id, organization_id, version_id, status, scheduled_for,
    requested_by_actor_id, request_id, created_at, updated_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id, target.id,
    'scheduled', p_scheduled_for, p_actor_id, p_request_id, now(), now()
  ) returning * into publication;

  update public.market_os_ambassador_settings_versions
  set status = 'scheduled', scheduled_for = p_scheduled_for,
      updated_by_actor_id = p_actor_id, updated_at = now()
  where id = target.id
  returning * into target;

  audit_tenant := target.tenant_id;
  audit_organization := target.organization_id;

  insert into public.market_os_ambassador_settings_runtime_events (
    id, tenant_id, organization_id, version_id, event_type, status,
    summary, details, actor_id, request_id, created_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id, target.id,
    'publication', 'scheduled',
    'Settings publication scheduled for ' || p_scheduled_for::text,
    jsonb_build_object('publicationId', publication.id, 'scheduledFor', p_scheduled_for),
    p_actor_id, p_request_id, now()
  );

  insert into public.market_os_ambassador_audit_logs (
    id, tenant_id, organization_id, entity_type, entity_id, action, summary,
    actor_id, actor_name, actor_role, request_id, payload,
    before_snapshot, after_snapshot, created_at
  ) values (
    gen_random_uuid(), audit_tenant, audit_organization,
    'market_os_ambassador_settings_versions', target.id,
    'settings_publication_scheduled_transactionally',
    'Scheduled Ambassador settings publication for ' || p_scheduled_for::text,
    p_actor_id, actor_name, actor_role, p_request_id,
    jsonb_build_object('publicationId', publication.id, 'scheduledFor', p_scheduled_for),
    null, to_jsonb(target), now()
  );

  existing_result := jsonb_build_object('version', to_jsonb(target), 'publication', to_jsonb(publication));
  insert into public.market_os_ambassador_idempotency (
    tenant_id, organization_id, operation, idempotency_key, actor_id, result
  ) values (
    target.tenant_id, target.organization_id, 'settings_schedule', v_idempotency_key, p_actor_id, existing_result
  ) on conflict (tenant_id, organization_id, operation, idempotency_key)
    do update set result = excluded.result;

  return existing_result;
end $$;


--
-- Name: market_os_ambassador_set_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_set_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.normalized_email := nullif(lower(btrim(coalesce(new.email, ''))), '');
  new.normalized_phone := public.market_os_ambassador_normalize_phone(new.phone);
  if tg_op = 'INSERT' or new.email is distinct from old.email or new.phone is distinct from old.phone
     or new.identity_hash is null then
    new.identity_hash := public.market_os_ambassador_identity_hash(new.email, new.phone);
  end if;
  return new;
end $$;


--
-- Name: market_os_ambassador_submit_settings_version(uuid, uuid, text, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_submit_settings_version(p_version_id uuid, p_actor_id uuid, p_request_id text, p_validation_result jsonb, p_required_approvals text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  target public.market_os_ambassador_settings_versions%rowtype;
  next_round integer;
  actor_role text;
  actor_name text;
  existing_result jsonb;
  v_idempotency_key text;
  audit_tenant public.market_os_ambassador_audit_logs.tenant_id%type;
  audit_organization public.market_os_ambassador_audit_logs.organization_id%type;
begin
  select * into target
  from public.market_os_ambassador_settings_versions
  where id = p_version_id
  for update;

  if target.id is null then
    raise exception 'Settings version not found' using errcode = 'P0002';
  end if;
  if not public.market_os_ambassador_actor_has_permission(
    p_actor_id, 'settings.submit', target.tenant_id, target.organization_id
  ) then
    raise exception 'Actor lacks settings.submit permission' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null then
    raise exception 'Settings submission requires an idempotency request id' using errcode = '23514';
  end if;
  v_idempotency_key := target.id::text || ':' || p_request_id;
  select result into existing_result
  from public.market_os_ambassador_idempotency
  where tenant_id = target.tenant_id and organization_id = target.organization_id
    and operation = 'settings_submit' and idempotency_key = v_idempotency_key
    and actor_id = p_actor_id;
  if existing_result is not null then
    return existing_result || jsonb_build_object('idempotent', true);
  end if;
  if target.status not in ('draft','revision_requested') then
    raise exception 'Only editable settings drafts can be submitted' using errcode = '23514';
  end if;
  if coalesce((p_validation_result ->> 'valid')::boolean, false) is not true then
    raise exception 'Settings validation must pass before submission' using errcode = '23514';
  end if;
  if coalesce(cardinality(p_required_approvals), 0) = 0 then
    raise exception 'At least one approval domain is required' using errcode = '23514';
  end if;
  if exists (
    select 1 from unnest(p_required_approvals) domain
    where domain not in ('program','compliance','finance','system')
  ) then
    raise exception 'Unsupported settings approval domain' using errcode = '23514';
  end if;

  select role_key, coalesce(display_name, auth_user_id::text)
    into actor_role, actor_name
  from public.market_os_ambassador_actor_roles
  where id = p_actor_id and status = 'active';

  next_round := coalesce(target.approval_round, 0) + 1;
  audit_tenant := target.tenant_id;
  audit_organization := target.organization_id;

  update public.market_os_ambassador_settings_versions
  set status = 'pending_approval',
      approval_round = next_round,
      validation_result = p_validation_result,
      submitted_at = now(),
      submitted_by_actor_id = p_actor_id,
      updated_by_actor_id = p_actor_id,
      updated_at = now()
  where id = target.id
  returning * into target;

  insert into public.market_os_ambassador_settings_approvals (
    id, tenant_id, organization_id, version_id, approval_round,
    approval_domain, status, created_at, updated_at
  )
  select gen_random_uuid(), target.tenant_id, target.organization_id, target.id,
         next_round, domain, 'pending', now(), now()
  from (select distinct unnest(p_required_approvals) as domain) required;

  insert into public.market_os_ambassador_settings_runtime_events (
    id, tenant_id, organization_id, version_id, event_type, status,
    summary, details, actor_id, request_id, created_at
  ) values (
    gen_random_uuid(), target.tenant_id, target.organization_id, target.id,
    'approval_submission', 'pending',
    'Settings version submitted for controlled approval',
    jsonb_build_object('requiredApprovals', p_required_approvals, 'approvalRound', next_round),
    p_actor_id, p_request_id, now()
  );

  insert into public.market_os_ambassador_audit_logs (
    id, tenant_id, organization_id, entity_type, entity_id, action, summary,
    actor_id, actor_name, actor_role, request_id, payload,
    before_snapshot, after_snapshot, created_at
  ) values (
    gen_random_uuid(), audit_tenant, audit_organization,
    'market_os_ambassador_settings_versions', target.id,
    'settings_submitted_for_approval_transactionally',
    'Submitted Ambassador settings version for controlled approval',
    p_actor_id, actor_name, actor_role, p_request_id,
    jsonb_build_object('requiredApprovals', p_required_approvals, 'approvalRound', next_round),
    null, to_jsonb(target), now()
  );

  existing_result := to_jsonb(target);
  insert into public.market_os_ambassador_idempotency (
    tenant_id, organization_id, operation, idempotency_key, actor_id, result
  ) values (
    target.tenant_id, target.organization_id, 'settings_submit', v_idempotency_key, p_actor_id, existing_result
  ) on conflict (tenant_id, organization_id, operation, idempotency_key)
    do update set result = excluded.result;

  return existing_result;
end $$;


--
-- Name: market_os_ambassador_sync_territory_geography(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_os_ambassador_sync_territory_geography() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_prefix constant text := 'AMB_TERRITORY_OS_V2:';
  v_config jsonb := '{}'::jsonb;
  v_lat double precision;
  v_lon double precision;
  v_radius_km double precision;
  v_area double precision;
begin
  if coalesce(new.notes, '') like v_prefix || '%' then
    begin
      v_config := substring(new.notes from length(v_prefix) + 1)::jsonb;
    exception
      when invalid_text_representation then
        v_config := '{}'::jsonb;
    end;
  elsif jsonb_typeof(coalesce(new.metadata, '{}'::jsonb)) = 'object' then
    v_config := coalesce(new.metadata -> 'territoryGeography', '{}'::jsonb);
  end if;

  v_lat := public.market_os_ambassador_safe_double(v_config ->> 'centerLatitude');
  v_lon := public.market_os_ambassador_safe_double(v_config ->> 'centerLongitude');
  v_radius_km := public.market_os_ambassador_safe_double(v_config ->> 'radiusKm');
  v_area := public.market_os_ambassador_safe_double(v_config ->> 'areaSquareKm');

  new.center_latitude := coalesce(new.center_latitude, v_lat);
  new.center_longitude := coalesce(new.center_longitude, v_lon);
  new.radius_meters := coalesce(
    new.radius_meters,
    case when v_radius_km is not null and v_radius_km >= 0 then round(v_radius_km * 1000)::integer end
  );
  new.geometry_type := coalesce(nullif(new.geometry_type, ''), nullif(v_config ->> 'geometryType', ''), 'none');
  new.geometry_geojson := coalesce(new.geometry_geojson, v_config -> 'geometryGeoJson');
  new.area_square_km := coalesce(new.area_square_km, v_area);
  new.osm_object_type := coalesce(nullif(new.osm_object_type, ''), nullif(v_config ->> 'osmObjectType', ''));
  new.osm_object_id := coalesce(nullif(new.osm_object_id, ''), nullif(v_config ->> 'osmObjectId', ''));
  new.osm_display_name := coalesce(nullif(new.osm_display_name, ''), nullif(v_config ->> 'osmDisplayName', ''));

  if new.center_latitude is not null
     or new.center_longitude is not null
     or new.geometry_geojson is not null
     or new.radius_meters is not null then
    new.geography_updated_at := coalesce(new.geography_updated_at, now());
  end if;

  new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
    'territoryGeographyVersion', 1,
    'territoryGeography', jsonb_strip_nulls(jsonb_build_object(
      'centerLatitude', new.center_latitude,
      'centerLongitude', new.center_longitude,
      'radiusMeters', new.radius_meters,
      'geometryType', new.geometry_type,
      'geometryGeoJson', new.geometry_geojson,
      'areaSquareKm', new.area_square_km,
      'osmObjectType', new.osm_object_type,
      'osmObjectId', new.osm_object_id,
      'osmDisplayName', new.osm_display_name,
      'updatedAt', new.geography_updated_at
    ))
  );

  return new;
end;
$$;


