--
-- Name: next_academy_document_sequence(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_academy_document_sequence(input_code text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  next_value integer;
begin
  insert into academy_document_reference_sequences(code, current_value, updated_at)
  values (input_code, 1, now())
  on conflict (code)
  do update set current_value = academy_document_reference_sequences.current_value + 1, updated_at = now()
  returning current_value into next_value;

  return next_value;
end;
$$;


