-- Name: prospect_create_activity(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospect_create_activity(p_prospect_id text, p_action text, p_note text DEFAULT NULL::text, p_actor text DEFAULT 'AngelCare'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare new_id uuid;
begin
  insert into public.prospect_activities(prospect_id, action, note, actor, metadata)
  values (p_prospect_id, p_action, p_note, p_actor, coalesce(p_metadata, '{}'::jsonb))
  returning id into new_id;
  return new_id;
end $$;


--
-- Name: prospect_escalation_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospect_escalation_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare inserted_count integer;
begin
  insert into public.prospect_notifications(prospect_id, title, body, severity)
  select t.prospect_id,
         'Overdue prospect task',
         'Task "' || t.title || '" is overdue and needs action.',
         'warning'
  from public.prospect_tasks t
  where t.status = 'open'
    and t.due_date is not null
    and t.due_date < current_date
    and not exists (
      select 1 from public.prospect_notifications n
      where n.prospect_id = t.prospect_id
        and n.title = 'Overdue prospect task'
        and n.body like '%' || t.title || '%'
        and n.created_at > now() - interval '2 days'
    );
  get diagnostics inserted_count = row_count;
  return inserted_count;
end $$;


--
-- Name: revenue_accept_b2c_match(uuid, uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_accept_b2c_match(p_cycle_id uuid, p_candidate_id uuid, p_actor_id uuid, p_evidence text, p_start_date date DEFAULT NULL::date) RETURNS TABLE(case_id uuid, cycle_id uuid, candidate_id uuid, matching_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cycle public.revenue_b2c_matching_cycles%rowtype;
  candidate public.revenue_b2c_matching_candidates%rowtype;
begin
  select * into cycle from public.revenue_b2c_matching_cycles where id=p_cycle_id for update;
  if not found then raise exception 'Cycle matching introuvable.'; end if;
  select * into candidate from public.revenue_b2c_matching_candidates where id=p_candidate_id and matching_cycle_id=p_cycle_id for update;
  if not found then raise exception 'Candidat matching introuvable.'; end if;
  if candidate.availability_status<>'verified' then raise exception 'Disponibilité non vérifiée.'; end if;
  if coalesce(p_evidence,'')='' then raise exception 'Preuve de décision famille requise.'; end if;
  insert into public.revenue_b2c_matching_decisions(b2c_case_id,matching_cycle_id,candidate_id,decision,decision_reason,evidence_reference,proposed_start_date,decided_by)
  values(cycle.b2c_case_id,cycle.id,candidate.id,'accepted','Décision famille confirmée',p_evidence,p_start_date,p_actor_id);
  update public.revenue_b2c_matching_cycles set status='accepted',selected_candidate_id=candidate.id,closed_at=now(),updated_at=now(),updated_by=p_actor_id where id=cycle.id;
  update public.revenue_b2c_cases set matching_status='accepted',stage='confirmed',last_activity_at=now(),updated_at=now(),updated_by=p_actor_id where id=cycle.b2c_case_id;
  return query select cycle.b2c_case_id,cycle.id,candidate.id,'accepted'::text;
end
$$;


--
-- Name: revenue_accept_partner_referral(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_accept_partner_referral(p_referral_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_convert_to_prospect boolean DEFAULT false, p_owner text DEFAULT NULL::text) RETURNS TABLE(referral_id uuid, prospect_id text, referral_status text, task_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  referral public.revenue_partner_referrals%rowtype;
  generated_prospect_id text;
  generated_task_id uuid;
  open_conflicts integer;
  existing_prospect_id text;
begin
  select * into referral from public.revenue_partner_referrals where id=p_referral_id for update;
  if not found then raise exception 'Referral introuvable.'; end if;
  if referral.consent_status in ('denied','refused') then raise exception 'La contactabilité a été refusée.'; end if;
  if referral.status in ('converted_to_prospect','converted_to_opportunity','attributed') and referral.linked_prospect_id is not null then
    select id into generated_task_id from public.revenue_tasks where metadata->>'partner_referral_id'=referral.id::text order by created_at desc limit 1;
    return query select referral.id,referral.linked_prospect_id,referral.status,generated_task_id;
    return;
  end if;
  select count(*) into open_conflicts from public.revenue_partner_attribution_conflicts where referral_id=referral.id and status='open';
  if referral.status='duplicate_review' and open_conflicts>0 then raise exception 'Le conflit de doublon doit être résolu avant acceptation.'; end if;
  generated_prospect_id:=referral.linked_prospect_id;
  if p_convert_to_prospect and generated_prospect_id is null then
    select pr.id into existing_prospect_id
    from public.revenue_prospects pr
    where (referral.normalized_email is not null and lower(coalesce(pr.email,''))=referral.normalized_email)
       or (referral.normalized_phone is not null and regexp_replace(coalesce(pr.phone,''),'[^0-9+]','','g')=referral.normalized_phone)
    order by pr.created_at asc limit 1;
    if existing_prospect_id is not null then
      update public.revenue_partner_referrals set status='duplicate_review',linked_prospect_id=existing_prospect_id,updated_by=p_actor_id,updated_at=now() where id=referral.id;
      insert into public.revenue_partner_attribution_conflicts(partnership_id,referral_id,conflict_type,description,existing_prospect_id,value_at_risk_mad,status,created_by)
      values(referral.partnership_id,referral.id,'pre_existing_prospect','Le referral correspond à un prospect existant et nécessite une décision d’attribution.',existing_prospect_id,referral.estimated_value_mad,'open',p_actor_id);
      return query select referral.id,existing_prospect_id,'duplicate_review'::text,null::uuid;
      return;
    end if;
    generated_prospect_id:=gen_random_uuid()::text;
    insert into public.revenue_prospects(
      id,name,contact_name,email,phone,company,city,owner,source,segment,stage,status,value_mad,pipeline_value,priority,next_action,notes,metadata,data,created_at,updated_at
    ) values(
      generated_prospect_id,referral.referred_name,referral.referred_name,referral.email,referral.phone,referral.referred_name,
      coalesce(referral.territory,'Unassigned'),coalesce(p_owner,referral.owner,'Revenue Command'),'partner_referral','b2b','new_lead','active',
      referral.estimated_value_mad,referral.estimated_value_mad,'high','Contacter et qualifier le referral',
      'Créé depuis le referral partenaire '||referral.id::text,
      jsonb_build_object('partner_referral_id',referral.id,'partnership_id',referral.partnership_id),
      jsonb_build_object('partner_referral_id',referral.id,'partnership_id',referral.partnership_id),now(),now()
    );
  end if;
  update public.revenue_partner_referrals
  set status=case when p_convert_to_prospect then 'converted_to_prospect' else 'accepted' end,
      linked_prospect_id=generated_prospect_id,owner=coalesce(p_owner,owner),updated_by=p_actor_id,updated_at=now()
  where id=referral.id;
  select id into generated_task_id from public.revenue_tasks where metadata->>'partner_referral_id'=referral.id::text order by created_at desc limit 1;
  if generated_task_id is null then
    insert into public.revenue_tasks(title,description,entity_type,entity_id,entity_name,partnership_id,prospect_id,owner,priority,status,due_date,task_type,workspace_slug,metadata)
    values(
    'Prendre en charge le referral partenaire',
    'Qualifier, contacter et documenter le referral '||referral.referred_name,
    'partnership',referral.partnership_id::text,referral.referred_name,referral.partnership_id::text,generated_prospect_id,
    coalesce(p_owner,referral.owner,'Revenue Command'),'high','planned',(current_date+2),'partner_referral_follow_up','revenue-command-center',
      jsonb_build_object('partner_referral_id',referral.id,'partnership_id',referral.partnership_id)
    ) returning id into generated_task_id;
  end if;
  return query select referral.id,generated_prospect_id,case when p_convert_to_prospect then 'converted_to_prospect' else 'accepted' end,generated_task_id;
end
$$;


--
-- Name: revenue_apply_commercial_outcome(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_apply_commercial_outcome(p_proposal_id uuid, p_input jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  p public.revenue_proposals;
  n public.revenue_negotiations;
  o public.revenue_commercial_outcomes;
  h public.revenue_contract_handoffs;
  task_id uuid;
  outcome_code text;
  final_value numeric;
  final_discount numeric;
  final_margin numeric;
  accepted boolean;
  decision_reason text;
  acceptance_evidence jsonb;
  acceptance_reference text;
begin
  select * into p from public.revenue_proposals where id=p_proposal_id for update;
  if not found then raise exception 'Proposition introuvable'; end if;
  if p.active_version_id is null then raise exception 'Une version immuable active est requise'; end if;

  select * into h from public.revenue_contract_handoffs
  where proposal_id=p.id and proposal_version_id=p.active_version_id
  order by created_at desc limit 1;
  if found then
    select * into o from public.revenue_commercial_outcomes where id=h.commercial_outcome_id;
    return jsonb_build_object('proposal_id',p.id,'proposal_status',p.status,'commercial_outcome_id',o.id,'contract_handoff_id',h.id,'task_id',null,'accepted',true,'final_value',h.final_value,'final_margin_percent',h.final_margin_percent,'idempotent_replay',true);
  end if;

  outcome_code:=coalesce(nullif(p_input->>'outcome',''),'rejected');
  final_value:=greatest(0,coalesce(nullif(p_input->>'finalValue','')::numeric,p.net_value));
  final_discount:=greatest(0,coalesce(nullif(p_input->>'finalDiscountValue','')::numeric,p.discount_value));
  final_margin:=coalesce(nullif(p_input->>'finalMarginPercent','')::numeric,p.margin_percent);
  decision_reason:=coalesce(nullif(trim(p_input->>'decisionReason'),''),nullif(trim(p_input->>'acceptedTerms'),''));
  acceptance_evidence:=coalesce(p_input->'evidence','{}'::jsonb);
  acceptance_reference:=coalesce(nullif(trim(p_input->>'acceptanceEvidence'),''),nullif(trim(acceptance_evidence->>'reference'),''));
  accepted:=outcome_code in ('accepted_as_proposed','accepted_after_negotiation','conditionally_accepted');

  if decision_reason is null then raise exception 'Le motif de décision commerciale est requis'; end if;
  if final_discount>p.gross_value then raise exception 'La remise finale ne peut pas dépasser la valeur brute'; end if;
  if accepted then
    if p.approval_status<>'approved' then raise exception 'La proposition doit être approuvée avant acceptation finale'; end if;
    if final_value<=0 then raise exception 'La valeur finale acceptée doit être strictement positive'; end if;
    if coalesce(nullif(trim(p_input->>'acceptedTerms'),''),'')='' then raise exception 'Les conditions commerciales acceptées sont requises'; end if;
    if acceptance_reference is null then raise exception 'Une preuve ou référence d’acceptation est requise'; end if;
    if exists(select 1 from public.revenue_proposal_approval_requests ar where ar.proposal_id=p.id and ar.status='requested') then
      raise exception 'Une approbation interne reste en attente';
    end if;
    if final_margin<p.minimum_margin_percent and not exists(
      select 1 from public.revenue_margin_exceptions me where me.proposal_id=p.id and me.status='approved'
    ) then raise exception 'La marge finale est sous le seuil sans exception approuvée'; end if;
    if exists(select 1 from public.revenue_concession_requests cr where cr.proposal_id=p.id and cr.status in ('requested','pending')) then
      raise exception 'Une concession reste en attente de décision';
    end if;
  end if;

  select * into n from public.revenue_negotiations where proposal_id=p.id order by created_at desc limit 1;
  insert into public.revenue_commercial_outcomes(
    proposal_id,proposal_version_id,negotiation_id,outcome,final_value,final_discount_value,final_margin_percent,
    accepted_terms,remaining_conditions,decision_reason,evidence,decided_by
  ) values(
    p.id,p.active_version_id,n.id,outcome_code,final_value,final_discount,final_margin,
    p_input->>'acceptedTerms',p_input->>'remainingConditions',decision_reason,acceptance_evidence,p_actor_id
  ) returning * into o;

  if accepted then
    update public.revenue_proposals set
      status='contract_ready',recipient_status='accepted',
      negotiation_status=case when n.id is null then negotiation_status else 'agreement_reached' end,
      net_value=final_value,discount_value=final_discount,gross_margin=final_value-estimated_cost,margin_percent=final_margin,
      accepted_at=now(),last_activity_at=now(),version=version+1,updated_by=p_actor_id
    where id=p.id returning * into p;
    if n.id is not null then
      update public.revenue_negotiations set status='agreement_reached',closed_at=now(),updated_by=p_actor_id,version=version+1 where id=n.id;
    end if;
    insert into public.revenue_contract_handoffs(
      proposal_id,proposal_version_id,commercial_outcome_id,account_id,opportunity_id,prospect_id,
      final_value,currency,final_margin_percent,remaining_conditions,created_by
    ) values(
      p.id,p.active_version_id,o.id,p.account_id,p.opportunity_id,p.prospect_id,
      final_value,p.currency,final_margin,p_input->>'remainingConditions',p_actor_id
    ) returning * into h;
    insert into public.revenue_tasks(entity_type,entity_id,prospect_id,title,description,owner,priority,status,expected_outcome,metadata)
    values('proposal',p.id::text,p.prospect_id,'Préparer le contrat — '||p.title,
      'Transformer la position commerciale acceptée en contrat gouverné.',p.owner,'critical','open',
      'Contrat préparé avec conditions, signature et gates de paiement.',
      jsonb_build_object('proposal_id',p.id,'contract_handoff_id',h.id,'commercial_outcome_id',o.id)
    ) returning id into task_id;
  else
    update public.revenue_proposals set
      status=case when outcome_code='withdrawn' then 'withdrawn' when outcome_code='expired' then 'expired' when outcome_code='superseded' then 'superseded' else 'rejected' end,
      rejected_at=now(),last_activity_at=now(),version=version+1,updated_by=p_actor_id
    where id=p.id returning * into p;
    if n.id is not null then update public.revenue_negotiations set status='rejected',closed_at=now(),updated_by=p_actor_id,version=version+1 where id=n.id; end if;
  end if;
  return jsonb_build_object('proposal_id',p.id,'proposal_status',p.status,'commercial_outcome_id',o.id,'contract_handoff_id',h.id,'task_id',task_id,'accepted',accepted,'final_value',final_value,'final_margin_percent',final_margin,'idempotent_replay',false);
end$$;


--
-- Name: revenue_apply_meeting_outcome(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_apply_meeting_outcome(p_appointment_id uuid, p_payload jsonb, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_appointment public.revenue_appointments%rowtype;
  v_outcome public.revenue_meeting_outcomes%rowtype;
  v_updated public.revenue_appointments%rowtype;
  v_summary text := nullif(trim(coalesce(p_payload->>'summary',p_payload->>'outcome','')),'');
  v_outcome_code text := coalesce(nullif(p_payload->>'outcomeCode',''),'follow_up');
  v_target_status text;
  v_follow_up_required boolean := coalesce((p_payload->>'followUpRequired')::boolean,true);
  v_proposal_required boolean := coalesce((p_payload->>'proposalRequired')::boolean,false);
  v_task_id uuid;
  v_task_ids uuid[] := array[]::uuid[];
  v_follow_up_title text := coalesce(nullif(p_payload->>'followUpTitle',''),'Suivi post-rendez-vous');
  v_follow_up_objective text := coalesce(nullif(p_payload->>'followUpObjective',''),'Exécuter les engagements et faire progresser l’opportunité.');
  v_follow_up_owner text;
  v_follow_up_at timestamptz := nullif(p_payload->>'followUpAt','')::timestamptz;
  v_value numeric;
  v_probability numeric;
begin
  select * into v_appointment from public.revenue_appointments where id=p_appointment_id for update;
  if not found then raise exception 'Rendez-vous introuvable.'; end if;
  if v_summary is null then raise exception 'Le résumé du résultat est requis.'; end if;

  v_value := greatest(0,coalesce(nullif(p_payload->>'commercialValueMad','')::numeric,v_appointment.commercial_value_mad,0));
  v_probability := greatest(0,least(100,coalesce(nullif(p_payload->>'probability','')::numeric,0)));
  v_follow_up_owner := coalesce(nullif(p_payload->>'followUpOwner',''),v_appointment.owner,'BD Officer');
  v_target_status := case
    when v_outcome_code like '%converted%' then 'converted'
    when v_outcome_code like '%lost%' then 'lost'
    when v_follow_up_required then 'follow_up'
    else 'completed'
  end;

  insert into public.revenue_meeting_outcomes(
    appointment_id,outcome_code,summary,interest_level,qualification_change,commercial_value_mad,
    probability,opportunity_stage_recommendation,proposal_required,negotiation_required,
    follow_up_required,escalation_required,loss_reason,next_meeting_required,recorded_by,metadata
  ) values (
    v_appointment.id,v_outcome_code,v_summary,coalesce(nullif(p_payload->>'interestLevel',''),'medium'),
    coalesce(nullif(p_payload->>'qualificationChange',''),'unchanged'),v_value,v_probability,
    nullif(p_payload->>'opportunityStageRecommendation',''),v_proposal_required,
    coalesce((p_payload->>'negotiationRequired')::boolean,false),v_follow_up_required,
    coalesce((p_payload->>'escalationRequired')::boolean,false),nullif(p_payload->>'lossReason',''),
    coalesce((p_payload->>'nextMeetingRequired')::boolean,false),p_actor,coalesce(p_payload->'metadata','{}'::jsonb)
  ) returning * into v_outcome;

  update public.revenue_appointments set
    status=v_target_status,outcome=v_summary,outcome_code=v_outcome_code,commercial_value_mad=v_value,
    completed_at=now(),updated_at=now(),updated_by=p_actor,version=coalesce(version,0)+1
  where id=v_appointment.id returning * into v_updated;

  if v_follow_up_required then
    insert into public.revenue_tasks(
      entity_type,entity_id,prospect_id,title,description,owner,priority,status,due_at,expected_outcome,metadata
    ) values (
      'appointment',v_updated.id::text,v_updated.prospect_id,v_follow_up_title,v_follow_up_objective,
      v_follow_up_owner,coalesce(v_updated.priority,'medium'),'open',v_follow_up_at,v_follow_up_objective,
      jsonb_build_object('appointment_id',v_updated.id,'account_id',v_updated.account_id,'opportunity_id',v_updated.opportunity_id,'outcome_id',v_outcome.id)
    ) returning id into v_task_id;
    v_task_ids:=array_append(v_task_ids,v_task_id);
    insert into public.revenue_meeting_follow_ups(appointment_id,task_id,title,description,channel,owner_name,due_at,status,created_by,updated_by,metadata)
    values(v_updated.id,v_task_id,v_follow_up_title,v_follow_up_objective,coalesce(nullif(p_payload->>'followUpChannel',''),'internal'),v_follow_up_owner,v_follow_up_at,'open',p_actor,p_actor,jsonb_build_object('outcome_id',v_outcome.id));
  end if;

  if v_proposal_required then
    insert into public.revenue_tasks(
      entity_type,entity_id,prospect_id,title,description,owner,priority,status,due_at,expected_outcome,metadata
    ) values (
      'appointment',v_updated.id::text,v_updated.prospect_id,'Préparer la proposition commerciale',
      'Préparer une proposition conforme au résultat de la réunion.',coalesce(nullif(p_payload->>'proposalOwner',''),v_updated.owner,'Revenue Manager'),
      'high','open',nullif(p_payload->>'proposalDueAt','')::timestamptz,'Produire une proposition gouvernée et prête à validation.',
      jsonb_build_object('appointment_id',v_updated.id,'account_id',v_updated.account_id,'opportunity_id',v_updated.opportunity_id,'outcome_id',v_outcome.id,'proposal_required',true)
    ) returning id into v_task_id;
    v_task_ids:=array_append(v_task_ids,v_task_id);
  end if;

  if v_updated.opportunity_id is not null and coalesce((p_payload->>'applyOpportunity')::boolean,false) then
    update public.revenue_opportunities set
      updated_at=now(),last_activity_at=now(),
      value_mad=case when v_value>0 then v_value else value_mad end,
      probability=case when v_probability>0 then v_probability else probability end,
      stage=coalesce(nullif(p_payload->>'opportunityStageRecommendation',''),stage)
    where id=v_updated.opportunity_id;
  end if;

  return jsonb_build_object('outcome',to_jsonb(v_outcome),'appointment',to_jsonb(v_updated),'taskIds',to_jsonb(v_task_ids));
end $$;


--
-- Name: revenue_appointment_quick_action(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_appointment_quick_action(p_appointment_id uuid, p_action text, p_actor text DEFAULT 'AngelCare'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from public.revenue_appointments where id = p_appointment_id) then
    return jsonb_build_object('ok', false, 'error', 'Appointment not found');
  end if;
  if p_action in ('confirm','confirmed') then
    update public.revenue_appointments set status='confirmed', updated_at=now() where id=p_appointment_id;
  elsif p_action in ('complete','completed') then
    update public.revenue_appointments set status='completed', updated_at=now() where id=p_appointment_id;
  elsif p_action in ('cancel','cancelled') then
    update public.revenue_appointments set status='cancelled', updated_at=now() where id=p_appointment_id;
  elsif p_action in ('archive','delete') then
    update public.revenue_appointments set status='archived', archived_at=now(), updated_at=now() where id=p_appointment_id;
  else
    update public.revenue_appointments set updated_at=now() where id=p_appointment_id;
  end if;
  return jsonb_build_object('ok', true, 'appointmentId', p_appointment_id, 'action', p_action);
end $$;


