--
-- Name: revenue_approve_campaign_sequence(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_approve_campaign_sequence(p_sequence_id uuid, p_version_number integer DEFAULT NULL::integer, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s record;v record;step_count integer:=0;next_version integer;
begin
  select * into s from public.revenue_campaign_sequences where id=p_sequence_id for update;
  if not found then raise exception 'Campaign sequence not found.'; end if;
  select count(*) into step_count from public.revenue_campaign_sequence_steps where sequence_id=p_sequence_id and sequence_version_id is null and status='draft';
  if step_count=0 then raise exception 'A sequence without draft steps cannot be approved.'; end if;
  next_version:=coalesce(p_version_number,greatest(1,coalesce(s.current_version,0)+1));
  if exists(select 1 from public.revenue_campaign_sequence_versions where sequence_id=p_sequence_id and version_number=next_version) then
    raise exception 'Sequence version % already exists.',next_version;
  end if;
  insert into public.revenue_campaign_sequence_versions(sequence_id,version_number,snapshot,status,approved_by,approved_at,created_by)
  select s.id,next_version,jsonb_build_object(
    'sequence',to_jsonb(s),
    'steps',coalesce((select jsonb_agg(to_jsonb(x) order by x.step_order) from public.revenue_campaign_sequence_steps x where x.sequence_id=s.id and x.sequence_version_id is null and x.status='draft'),'[]'::jsonb)
  ),'approved',p_actor_id,now(),p_actor_id returning * into v;
  insert into public.revenue_campaign_sequence_steps(sequence_id,sequence_version_id,step_order,step_type,channel,delay_minutes,allowed_window,template_id,template_version_id,sender_identity_id,owner_role,preconditions,skip_conditions,success_conditions,failure_behavior,reply_behavior,retry_policy,status,created_by)
  select d.sequence_id,v.id,d.step_order,d.step_type,d.channel,d.delay_minutes,d.allowed_window,d.template_id,
    coalesce(d.template_version_id,t.active_version_id),d.sender_identity_id,d.owner_role,d.preconditions,d.skip_conditions,d.success_conditions,d.failure_behavior,d.reply_behavior,d.retry_policy,'approved',p_actor_id
  from public.revenue_campaign_sequence_steps d
  left join public.revenue_campaign_templates t on t.id=d.template_id
  where d.sequence_id=s.id and d.sequence_version_id is null and d.status='draft';
  update public.revenue_campaign_sequences set status='approved',active_version_id=v.id,current_version=next_version,updated_by=p_actor_id,updated_at=now() where id=s.id;
  return jsonb_build_object('id',v.id,'sequenceId',s.id,'versionNumber',next_version,'status','approved','approvedSteps',step_count);
end $$;


--
-- Name: revenue_authorize_b2c_activation(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_authorize_b2c_activation(p_case_id uuid, p_actor_id uuid, p_decision text, p_reason text) RETURNS TABLE(case_id uuid, activation_status text, authorized boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  total integer;passed integer;current_status text;approved boolean;
begin
  perform public.revenue_evaluate_b2c_activation(p_case_id,p_actor_id);
  select count(*),count(*) filter(where result='passed') into total,passed from public.revenue_b2c_activation_gates where b2c_case_id=p_case_id and mandatory=true;
  approved:=p_decision='approved';
  if approved and (total=0 or total<>passed) then raise exception 'Les gates obligatoires ne sont pas satisfaits.'; end if;
  current_status:=case when approved then 'approved' else 'rejected' end;
  update public.revenue_b2c_cases set activation_status=current_status,stage=case when approved then 'activation_pending' else stage end,last_activity_at=now(),updated_at=now(),updated_by=p_actor_id where id=p_case_id;
  insert into public.revenue_b2c_status_history(b2c_case_id,event_type,previous_state,new_state,reason,actor_id)
  values(p_case_id,'b2c_activation_decision',null,to_jsonb(current_status),p_reason,p_actor_id);
  return query select p_case_id,current_status,approved;
end
$$;


--
-- Name: revenue_authorize_contract_activation(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_authorize_contract_activation(p_contract_id uuid, p_input jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.revenue_contracts; failed integer; decision text; d public.revenue_activation_decisions; task_id uuid; override_ok boolean;
begin
  select * into c from public.revenue_contracts where id=p_contract_id for update;
  if not found then raise exception 'Contrat introuvable'; end if;
  perform public.revenue_evaluate_activation_gates(c.id,p_input,p_actor_id);
  select count(*) into failed from public.revenue_activation_gates where contract_id=c.id and mandatory and status='failed';
  decision:=coalesce(nullif(p_input->>'decision',''),'authorized');
  override_ok:=exists(select 1 from public.revenue_activation_decisions where contract_id=c.id and decision='override_approved' and evidence_reference is not null order by decided_at desc limit 1);
  if decision='authorized' and failed>0 and not override_ok then raise exception 'Des gates obligatoires restent en échec sans dérogation approuvée'; end if;
  if coalesce(nullif(trim(p_input->>'reason'),''),'')='' then raise exception 'La justification de décision est requise'; end if;
  insert into public.revenue_activation_decisions(contract_id,decision,reason,evidence_reference,override,decided_by)
  values(c.id,decision,p_input->>'reason',p_input->>'evidenceReference',false,p_actor_id) returning * into d;
  update public.revenue_contracts set activation_status=case when decision='authorized' then 'authorized' else 'blocked' end,status=case when decision='authorized' then 'activation_pending' else status end,last_activity_at=now(),updated_by=p_actor_id where id=c.id returning * into c;
  if decision='authorized' then
    insert into public.revenue_tasks(entity_type,entity_id,prospect_id,title,description,owner,priority,status,expected_outcome,metadata)
    values('contract',c.id::text,c.prospect_id,'Créer le handoff opérationnel — '||c.title,'Transmettre portée, contacts, obligations, démarrage et risques au module receveur.',c.owner,'critical','open','Handoff accepté et activation exécutée.',jsonb_build_object('contract_id',c.id,'activation_decision_id',d.id)) returning id into task_id;
  end if;
  return jsonb_build_object('contract_id',c.id,'decision_id',d.id,'decision',decision,'activation_status',c.activation_status,'failed_gates',failed,'override_used',override_ok,'task_id',task_id);
end$$;


