--

CREATE FUNCTION public.revenue_campaign_touch_updated_at_v10() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ begin new.updated_at=now(); return new; end $$;


--
-- Name: revenue_capture_appointment_status_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_capture_appointment_status_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status then
    insert into public.revenue_appointment_status_history(appointment_id,from_status,to_status,reason,changed_by,metadata)
    values(new.id,old.status,new.status,'Transition Revenue Command',new.updated_by,jsonb_build_object('version',new.version));
  end if;
  return new;
end $$;


--
-- Name: revenue_capture_opportunity_stage_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_capture_opportunity_stage_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.stage is distinct from new.stage
     or old.probability is distinct from new.probability
     or old.value_mad is distinct from new.value_mad then
    insert into public.revenue_opportunity_stage_history (
      opportunity_id,
      from_stage,
      to_stage,
      previous_probability,
      new_probability,
      previous_value_mad,
      new_value_mad,
      reason,
      metadata
    ) values (
      new.id,
      old.stage,
      new.stage,
      old.probability,
      new.probability,
      old.value_mad,
      new.value_mad,
      coalesce(new.metadata->>'transition_reason', 'Mise à jour Revenue Command'),
      jsonb_build_object('source', 'database_trigger')
    );
  end if;
  return new;
end;
$$;


--
-- Name: revenue_close_campaign_performance_period(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_close_campaign_performance_period(p_period_id uuid, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p record;enrolled integer;contacted integer;replies integer;positive integer;meetings integer;opportunities integer;contracts integer;realized numeric;confirmed_cost numeric;v_metrics jsonb;v_economics jsonb;v_scorecard jsonb;
begin
  select * into p from public.revenue_campaign_performance_periods where id=p_period_id for update;
  if not found then raise exception 'Performance period not found.'; end if;
  if p.status='closed' then return jsonb_build_object('periodId',p.id,'status','closed','idempotentReplay',true,'metrics',p.metrics,'economics',p.economics); end if;
  select count(*) into enrolled from public.revenue_campaign_recipients where campaign_id=p.campaign_id and created_at>=p.starts_at and (p.ends_at is null or created_at<=p.ends_at);
  select count(*) into contacted from public.revenue_campaign_recipients where campaign_id=p.campaign_id and first_contact_at>=p.starts_at and (p.ends_at is null or first_contact_at<=p.ends_at);
  select count(*),count(*) filter(where classification in ('positive_interest','meeting_request','information_request')) into replies,positive from public.revenue_campaign_replies where campaign_id=p.campaign_id and occurred_at>=p.starts_at and (p.ends_at is null or occurred_at<=p.ends_at);
  select count(*) filter(where event_type='meeting_created'),count(*) filter(where event_type='opportunity_created'),count(*) filter(where event_type='contract_signed') into meetings,opportunities,contracts from public.revenue_campaign_conversion_events where campaign_id=p.campaign_id and occurred_at>=p.starts_at and (p.ends_at is null or occurred_at<=p.ends_at);
  select coalesce(sum(attributed_value),0) into realized from public.revenue_campaign_attributions where campaign_id=p.campaign_id and event_type='revenue_realized' and status in ('active','confirmed','attributed') and created_at>=p.starts_at and (p.ends_at is null or created_at<=p.ends_at);
  select coalesce(sum(amount_mad),0) into confirmed_cost from public.revenue_campaign_costs where campaign_id=p.campaign_id and cost_state='confirmed' and occurred_on>=p.starts_at::date and (p.ends_at is null or occurred_on<=p.ends_at::date);
  v_metrics:=jsonb_build_object('enrolled',enrolled,'contacted',contacted,'replies',replies,'positiveReplies',positive,'meetings',meetings,'opportunities',opportunities,'contracts',contracts,'replyRate',case when contacted>0 then round(replies::numeric/contacted*100,2) else 0 end,'meetingRate',case when replies>0 then round(meetings::numeric/replies*100,2) else 0 end);
  v_economics:=jsonb_build_object('realizedRevenueMad',realized,'confirmedCostMad',confirmed_cost,'returnPercent',case when confirmed_cost>0 then round((realized-confirmed_cost)/confirmed_cost*100,2) else null end);
  v_scorecard:=jsonb_build_object('commercialScore',least(100,coalesce((positive*5+meetings*10+opportunities*15+contracts*25),0)),'deliverabilityRisk',case when exists(select 1 from public.revenue_campaign_dispatch_attempts where campaign_id=p.campaign_id and status in ('hard_bounce','provider_rejected','failed')) then 'review' else 'clear' end,'attributionConflicts',(select count(*) from public.revenue_campaign_attribution_conflicts where campaign_id=p.campaign_id and status='open'));
  update public.revenue_campaign_performance_periods set metrics=v_metrics,economics=v_economics,scorecard=v_scorecard,status='closed',closed_by=p_actor_id,closed_at=now(),updated_at=now() where id=p.id;
  return jsonb_build_object('periodId',p.id,'status','closed','metrics',v_metrics,'economics',v_economics,'scorecard',v_scorecard,'idempotentReplay',false);
end $$;


--
-- Name: revenue_close_partner_performance_period(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_close_partner_performance_period(p_period_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_summary text DEFAULT NULL::text, p_recommendation text DEFAULT NULL::text, p_commitments text DEFAULT NULL::text) RETURNS TABLE(scorecard_id uuid, overall_score numeric, recommendation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  period public.revenue_partner_performance_periods%rowtype;
  referral_count integer:=0;
  qualified_count integer:=0;
  attributed_count integer:=0;
  meeting_count integer:=0;
  contract_count integer:=0;
  realized_value numeric:=0;
  obligation_total integer:=0;
  obligation_completed integer:=0;
  referral_quality numeric:=0;
  conversion_score numeric:=0;
  realized_score numeric:=0;
  obligation_score numeric:=100;
  engagement_score numeric:=0;
  health_score numeric:=0;
  final_score numeric:=0;
  card_id uuid;
  final_recommendation text;
begin
  select * into period from public.revenue_partner_performance_periods where id=p_period_id for update;
  if not found then raise exception 'Période de performance introuvable.'; end if;
  if period.status='closed' then raise exception 'La période est déjà clôturée et immuable.'; end if;
  select count(*),count(*) filter(where status in ('accepted','contact_permission_confirmed','qualification','converted_to_prospect','converted_to_opportunity','meeting','proposal','contract','payment_confirmed','revenue_realized','attributed','closed')),count(*) filter(where status='attributed')
  into referral_count,qualified_count,attributed_count
  from public.revenue_partner_referrals
  where partnership_id=period.partnership_id and received_at::date between period.period_start and period.period_end;
  select count(*) into meeting_count from public.revenue_appointments
  where partnership_id=period.partnership_id::text and coalesce(scheduled_at,appointment_at,created_at)::date between period.period_start and period.period_end and status in ('completed','done');
  select count(*) into contract_count from public.revenue_contracts
  where partnership_id=period.partnership_id::text and created_at::date between period.period_start and period.period_end and status in ('fully_signed','effective','active','completed');
  select coalesce(sum(a.attributed_value),0) into realized_value
  from public.revenue_partner_referral_attributions a
  where a.partnership_id=period.partnership_id and a.event_type='revenue_realized' and a.status in ('confirmed','attributed','active')
    and a.created_at::date between period.period_start and period.period_end;
  select count(*),count(*) filter(where status='completed') into obligation_total,obligation_completed
  from public.revenue_partnership_obligations
  where partnership_id=period.partnership_id and created_at::date<=period.period_end;
  referral_quality:=case when referral_count>0 then least(100,qualified_count::numeric/referral_count*100) else 0 end;
  conversion_score:=case when referral_count>0 then least(100,attributed_count::numeric/referral_count*100) else 0 end;
  realized_score:=case when period.target_realized_mad>0 then least(100,realized_value/period.target_realized_mad*100) else case when realized_value>0 then 100 else 0 end end;
  obligation_score:=case when obligation_total>0 then obligation_completed::numeric/obligation_total*100 else 100 end;
  engagement_score:=case when period.target_meetings>0 then least(100,meeting_count::numeric/period.target_meetings*100) else case when meeting_count>0 then 100 else 0 end end;
  health_score:=greatest(0,least(100,100-(select coalesce(sum(case severity when 'critical' then 25 when 'high' then 15 when 'medium' then 8 else 3 end),0) from public.revenue_partnership_risks where partnership_id=period.partnership_id and status='open')));
  final_score:=round(referral_quality*.20+conversion_score*.20+realized_score*.25+obligation_score*.15+engagement_score*.10+health_score*.10,2);
  final_recommendation:=coalesce(nullif(p_recommendation,''),case when final_score>=82 then 'expand' when final_score>=65 then 'renew' when final_score>=42 then 'recovery' else 'terminate' end);
  insert into public.revenue_partner_scorecards(
    partnership_id,performance_period_id,referral_quality_score,conversion_score,realized_revenue_score,obligation_compliance_score,
    engagement_score,relationship_health_score,overall_score,referral_count,qualified_referral_count,attributed_referral_count,
    meeting_count,contract_count,realized_revenue_mad,performance_status,components,source_evidence,created_by
  ) values(
    period.partnership_id,period.id,referral_quality,conversion_score,realized_score,obligation_score,engagement_score,health_score,final_score,
    referral_count,qualified_count,attributed_count,meeting_count,contract_count,realized_value,
    case when final_score>=82 then 'excellent' when final_score>=65 then 'performing' when final_score>=42 then 'under_review' else 'at_risk' end,
    jsonb_build_object('referral_quality',referral_quality,'conversion',conversion_score,'realized',realized_score,'obligations',obligation_score,'engagement',engagement_score,'health',health_score),
    jsonb_build_object('period_start',period.period_start,'period_end',period.period_end),p_actor_id
  ) returning id into card_id;
  update public.revenue_partner_performance_periods set status='closed',closed_at=now(),updated_by=p_actor_id,updated_at=now() where id=period.id;
  insert into public.revenue_partner_reviews(partnership_id,performance_period_id,summary,recommendation,commitments,status,reviewed_at,created_by)
  values(period.partnership_id,period.id,p_summary,final_recommendation,
    case when nullif(btrim(coalesce(p_commitments,'')),'') is null then '[]'::jsonb else to_jsonb(regexp_split_to_array(btrim(p_commitments),E'\n+')) end,
    'prepared',now(),p_actor_id);
  update public.revenue_partnerships
  set health_score=final_score,health_status=case when final_score>=65 then 'healthy' when final_score>=42 then 'watch' else 'at_risk' end,
      stage=case when final_recommendation='expand' then 'expansion' when final_recommendation='recovery' then 'recovery' when final_recommendation='terminate' then 'at_risk' else 'under_review' end,
      last_activity_at=now(),updated_at=now()
  where id=period.partnership_id;
  return query select card_id,final_score,final_recommendation;
end
$$;


--
-- Name: revenue_command_smoke_test(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_command_smoke_test() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare result jsonb;
begin
  select jsonb_build_object(
    'revenue_prospects_exists', to_regclass('public.revenue_prospects') is not null,
    'revenue_tasks_exists', to_regclass('public.revenue_tasks') is not null,
    'revenue_appointments_exists', to_regclass('public.revenue_appointments') is not null,
    'revenue_events_exists', to_regclass('public.revenue_events') is not null,
    'revenue_notifications_exists', to_regclass('public.revenue_notifications') is not null,
    'analytics_view_exists', to_regclass('public.revenue_command_analytics_view') is not null,
    'checked_at', now()
  ) into result;
  return result;
end $$;


--
-- Name: revenue_confirm_revenue_realization(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_confirm_revenue_realization(p_contract_id uuid, p_input jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.revenue_contracts; e public.revenue_realization_events; existing public.revenue_realization_events; amount numeric; total numeric; finance_ref text; evidence_ref text;
begin
  select * into c from public.revenue_contracts where id=p_contract_id for update;
  if not found then raise exception 'Contrat introuvable'; end if;
  if c.effectiveness_status<>'effective' and c.status not in ('effective','activation_pending','active') then raise exception 'Le contrat doit être effectif'; end if;
  if c.activation_status not in ('authorized','activated') then raise exception 'L’activation doit être autorisée ou exécutée'; end if;
  amount:=greatest(0,coalesce(nullif(p_input->>'amount','')::numeric,0));
  finance_ref:=nullif(trim(p_input->>'financeReference'),'');
  evidence_ref:=nullif(trim(p_input->>'evidenceReference'),'');
  if amount<=0 or finance_ref is null or evidence_ref is null then raise exception 'Montant, référence Finance et preuve autoritative sont requis'; end if;
  select * into existing from public.revenue_realization_events where contract_id=c.id and finance_reference=finance_ref and status in ('realized','partially_realized') order by created_at desc limit 1;
  if found then return jsonb_build_object('contract_id',c.id,'realization_id',existing.id,'amount',existing.amount,'idempotent_replay',true); end if;
  if not exists(select 1 from public.revenue_payment_confirmations where contract_id=c.id and finance_reference=finance_ref and reconciliation_status in ('confirmed','partial')) then raise exception 'La référence Finance ne correspond à aucune confirmation de paiement autoritative'; end if;
  select coalesce(sum(amount),0) into total from public.revenue_realization_events where contract_id=c.id and status in ('realized','partially_realized');
  if total+amount>c.contract_value then raise exception 'La réalisation cumulée dépasserait la valeur contractuelle'; end if;
  insert into public.revenue_realization_events(contract_id,payment_confirmation_id,amount,currency,status,finance_reference,evidence_reference,realization_rule,realized_at,realized_by)
  values(c.id,(select id from public.revenue_payment_confirmations where contract_id=c.id and finance_reference=finance_ref order by created_at desc limit 1),amount,c.currency,case when total+amount>=c.contract_value then 'realized' else 'partially_realized' end,finance_ref,evidence_ref,coalesce(nullif(p_input->>'rule',''),'Paiement confirmé et activation autorisée'),coalesce(nullif(p_input->>'realizedAt','')::timestamptz,now()),p_actor_id) returning * into e;
  update public.revenue_contracts set realized_value=total+amount,realization_status=case when total+amount>=contract_value then 'realized' else 'partially_realized' end,last_activity_at=now(),updated_by=p_actor_id where id=c.id returning * into c;
  return jsonb_build_object('contract_id',c.id,'realization_id',e.id,'amount',e.amount,'cumulative_realized',c.realized_value,'realization_status',c.realization_status,'idempotent_replay',false);
end$$;


--
-- Name: revenue_contact_sync_entity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_contact_sync_entity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.entity_id is null or btrim(new.entity_id) = '' then
    if new.account_id is not null then
      new.entity_type := 'account';
      new.entity_id := new.account_id::text;
    else
      new.entity_type := coalesce(nullif(new.entity_type,''), 'contact');
      new.entity_id := new.id::text;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: revenue_create_campaign_attribution(uuid, uuid, text, text, text, numeric, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_campaign_attribution(p_campaign_id uuid, p_campaign_recipient_id uuid DEFAULT NULL::uuid, p_event_type text DEFAULT NULL::text, p_event_id text DEFAULT NULL::text, p_attribution_model text DEFAULT 'rules_primary_source'::text, p_attribution_share numeric DEFAULT 100, p_attributed_value numeric DEFAULT 0, p_evidence_reference text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  existing_share numeric:=0;partner_share numeric:=0;event_value numeric:=0;event_time timestamptz;
  campaign_start timestamptz;window_days integer;event_opportunity_id uuid;event_contract_id uuid;
  lineage_ok boolean:=false;recipient record;attr record;conflict record;
  attr_sequence_version_id uuid;attr_channel text;attr_sdr_owner text;
begin
  if nullif(p_event_type,'') is null or nullif(p_event_id,'') is null then raise exception 'Attribution event is required.'; end if;
  if nullif(p_evidence_reference,'') is null then raise exception 'Attribution evidence is required.'; end if;
  if p_attribution_share<=0 or p_attribution_share>100 then raise exception 'Attribution share must be between 0 and 100.'; end if;
  select coalesce(launch_at,created_at),attribution_window_days into campaign_start,window_days from public.revenue_campaigns where id=p_campaign_id;
  if not found then raise exception 'Campaign not found.'; end if;
  if p_campaign_recipient_id is not null then
    select * into recipient from public.revenue_campaign_recipients where id=p_campaign_recipient_id and campaign_id=p_campaign_id;
    if not found then raise exception 'Campaign recipient does not belong to the campaign.'; end if;
    attr_sequence_version_id:=recipient.current_sequence_version_id;attr_channel:=recipient.channel;attr_sdr_owner:=recipient.owner;
  end if;
  if p_event_type='reply' then
    select occurred_at into event_time from public.revenue_campaign_replies where id::text=p_event_id and campaign_id=p_campaign_id;
    lineage_ok:=event_time is not null;
  elsif p_event_type='meeting_created' then
    select created_at into event_time from public.revenue_appointments where id::text=p_event_id;
    lineage_ok:=exists(select 1 from public.revenue_campaign_conversion_events where campaign_id=p_campaign_id and event_type='meeting_created' and target_entity_id=p_event_id);
  elsif p_event_type='opportunity_created' then
    select created_at,id into event_time,event_opportunity_id from public.revenue_opportunities where id::text=p_event_id;
    lineage_ok:=exists(select 1 from public.revenue_campaign_conversion_events where campaign_id=p_campaign_id and event_type='opportunity_created' and target_entity_id=p_event_id);
  elsif p_event_type='proposal_created' then
    select created_at,opportunity_id into event_time,event_opportunity_id from public.revenue_proposals where id::text=p_event_id;
    lineage_ok:=exists(select 1 from public.revenue_campaign_conversion_events where campaign_id=p_campaign_id and ((event_type='proposal_created' and target_entity_id=p_event_id) or (event_type='opportunity_created' and target_entity_id=event_opportunity_id::text)));
  elsif p_event_type='contract_signed' then
    select created_at,opportunity_id,id into event_time,event_opportunity_id,event_contract_id from public.revenue_contracts where id::text=p_event_id;
    lineage_ok:=exists(select 1 from public.revenue_campaign_conversion_events where campaign_id=p_campaign_id and ((event_type='contract_signed' and target_entity_id=p_event_id) or (event_type='opportunity_created' and target_entity_id=event_opportunity_id::text)));
  elsif p_event_type='payment_confirmed' then
    select pc.created_at,pc.contract_id,c.opportunity_id into event_time,event_contract_id,event_opportunity_id
    from public.revenue_payment_confirmations pc join public.revenue_contracts c on c.id=pc.contract_id where pc.id::text=p_event_id;
    lineage_ok:=exists(select 1 from public.revenue_campaign_conversion_events where campaign_id=p_campaign_id and ((event_type='payment_confirmed' and target_entity_id=p_event_id) or (event_type='contract_signed' and target_entity_id=event_contract_id::text) or (event_type='opportunity_created' and target_entity_id=event_opportunity_id::text)));
  elsif p_event_type='revenue_realized' then
    select r.amount,r.realized_at,r.contract_id,c.opportunity_id into event_value,event_time,event_contract_id,event_opportunity_id
    from public.revenue_realization_events r join public.revenue_contracts c on c.id=r.contract_id
    where r.id::text=p_event_id and r.status in ('realized','partially_realized');
    lineage_ok:=exists(select 1 from public.revenue_campaign_conversion_events where campaign_id=p_campaign_id and ((event_type='revenue_realized' and target_entity_id=p_event_id) or (event_type='contract_signed' and target_entity_id=event_contract_id::text) or (event_type='opportunity_created' and target_entity_id=event_opportunity_id::text)));
  else raise exception 'Unsupported attribution event type.'; end if;
  if event_time is null then raise exception 'Canonical attribution event not found.'; end if;
  if not lineage_ok and nullif(p_override_reason,'') is null then
    insert into public.revenue_campaign_attribution_conflicts(campaign_id,campaign_recipient_id,conflict_type,description,event_type,event_id,value_at_risk_mad,status,created_by)
    values(p_campaign_id,p_campaign_recipient_id,'lineage_unproven','The canonical event has no verified campaign conversion lineage.',p_event_type,p_event_id,greatest(p_attributed_value,event_value),'open',p_actor_id) returning * into conflict;
    return jsonb_build_object('status','conflict','conflictId',conflict.id,'conflictType',conflict.conflict_type,'attributionCreated',false);
  end if;
  if event_time<campaign_start or event_time>campaign_start+make_interval(days=>greatest(1,window_days)) then
    insert into public.revenue_campaign_attribution_conflicts(campaign_id,campaign_recipient_id,conflict_type,description,event_type,event_id,value_at_risk_mad,status,created_by)
    values(p_campaign_id,p_campaign_recipient_id,'outside_window','The commercial event is outside the campaign attribution window.',p_event_type,p_event_id,greatest(p_attributed_value,event_value),'open',p_actor_id) returning * into conflict;
    return jsonb_build_object('status','conflict','conflictId',conflict.id,'conflictType',conflict.conflict_type,'attributionCreated',false);
  end if;
  select coalesce(sum(attribution_share),0) into existing_share from public.revenue_campaign_attributions where event_type=p_event_type and event_id=p_event_id and status in ('active','confirmed','attributed');
  if to_regclass('public.revenue_partner_referral_attributions') is not null then
    select coalesce(sum(attribution_share),0) into partner_share from public.revenue_partner_referral_attributions where event_type=replace(p_event_type,'meeting_created','meeting_completed') and event_id=p_event_id and status in ('active','confirmed','attributed');
  end if;
  if existing_share+partner_share+p_attribution_share>100 then
    insert into public.revenue_campaign_attribution_conflicts(campaign_id,campaign_recipient_id,conflict_type,description,competing_source_type,event_type,event_id,value_at_risk_mad,status,created_by)
    values(p_campaign_id,p_campaign_recipient_id,'over_allocation','Campaign and partner attribution would exceed 100%.','campaign_or_partner',p_event_type,p_event_id,greatest(p_attributed_value,event_value),'open',p_actor_id) returning * into conflict;
    return jsonb_build_object('status','conflict','conflictId',conflict.id,'conflictType',conflict.conflict_type,'campaignShare',existing_share,'partnerShare',partner_share,'requestedShare',p_attribution_share,'attributionCreated',false);
  end if;
  insert into public.revenue_campaign_attributions(campaign_id,campaign_recipient_id,sequence_version_id,channel,sdr_owner,event_type,event_id,attribution_model,attribution_share,attributed_value,currency,event_timestamp,evidence_reference,status,override_reason,created_by)
  values(p_campaign_id,p_campaign_recipient_id,attr_sequence_version_id,attr_channel,attr_sdr_owner,p_event_type,p_event_id,p_attribution_model,p_attribution_share,case when p_event_type='revenue_realized' and p_attributed_value=0 then event_value*(p_attribution_share/100.0) else greatest(0,p_attributed_value) end,'MAD',event_time,p_evidence_reference,'active',nullif(p_override_reason,''),p_actor_id) returning * into attr;
  return jsonb_build_object('status','attributed','attributionId',attr.id,'eventType',p_event_type,'eventId',p_event_id,'share',attr.attribution_share,'value',attr.attributed_value,'partnerShare',partner_share,'totalShare',existing_share+partner_share+attr.attribution_share,'lineageVerified',lineage_ok,'overrideApplied',nullif(p_override_reason,'') is not null);
end $$;


--
-- Name: revenue_create_contract_from_handoff(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_contract_from_handoff(p_contract_handoff_id uuid, p_input jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare h public.revenue_contract_handoffs; p public.revenue_proposals; existing public.revenue_contracts; c public.revenue_contracts; v public.revenue_contract_versions; task_id uuid;
begin
  select * into h from public.revenue_contract_handoffs where id=p_contract_handoff_id for update;
  if not found then raise exception 'Handoff contractuel introuvable'; end if;
  select * into existing from public.revenue_contracts where contract_handoff_id=h.id;
  if found then return jsonb_build_object('contract_id',existing.id,'contract_reference',existing.reference,'contract_status',existing.status,'idempotent_replay',true); end if;
  select * into p from public.revenue_proposals where id=h.proposal_id for update;
  if not found or p.status<>'contract_ready' then raise exception 'La proposition doit être contract-ready'; end if;
  if p.active_version_id is distinct from h.proposal_version_id then raise exception 'Le handoff ne référence pas la version active acceptée'; end if;
  insert into public.revenue_contracts(
    title,status,contract_type,context_type,prospect_id,account_id,contact_id,opportunity_id,proposal_id,proposal_version_id,
    commercial_outcome_id,contract_handoff_id,partnership_id,owner,currency,contract_value,signed_value,review_status,approval_status,
    signature_status,effectiveness_status,payment_gate_status,activation_status,realization_status,effective_date,expiry_date,next_action,metadata,created_by,updated_by
  ) values(
    coalesce(nullif(trim(p_input->>'title'),''),'Contrat — '||p.title),'draft',coalesce(nullif(p_input->>'contractType',''),case when p.context_type='partnership' then 'partnership_agreement' else 'commercial_contract' end),
    case when p.context_type in ('prospect','partnership') then p.context_type else 'prospect' end,p.prospect_id,p.account_id,p.contact_id,p.opportunity_id,p.id,h.proposal_version_id,h.commercial_outcome_id,h.id,p.partnership_id,
    coalesce(nullif(p_input->>'owner',''),p.owner,'Revenue Manager'),h.currency,h.final_value,h.final_value,'not_requested','not_requested','not_prepared','not_ready',case when h.payment_gate_required then 'requirement_defined' else 'not_required' end,'not_ready','not_eligible',
    nullif(p_input->>'effectiveDate','')::date,nullif(p_input->>'expiryDate','')::date,coalesce(nullif(p_input->>'nextAction',''),'Préparer la version contractuelle 1'),
    jsonb_build_object('source_proposal',p.id,'source_version',h.proposal_version_id,'remaining_conditions',h.remaining_conditions,'final_margin_percent',h.final_margin_percent),p_actor_id,p_actor_id
  ) returning * into c;
  v:=public.revenue_create_contract_version(c.id,'Version initiale depuis proposition acceptée','Transposition du handoff commercial','Version contractuelle initiale',p_actor_id);
  update public.revenue_contract_handoffs set status='consumed' where id=h.id;
  insert into public.revenue_tasks(entity_type,entity_id,prospect_id,title,description,owner,priority,status,expected_outcome,metadata)
  values('contract',c.id::text,c.prospect_id,'Revue contractuelle — '||c.title,'Contrôler clauses, paiement, signatures et conditions d’effectivité.',c.owner,'critical','open','Contrat approuvé et prêt à signer.',jsonb_build_object('contract_id',c.id,'contract_version_id',v.id,'contract_handoff_id',h.id)) returning id into task_id;
  return jsonb_build_object('contract_id',c.id,'contract_reference',c.reference,'contract_version_id',v.id,'task_id',task_id,'contract_status',c.status,'idempotent_replay',false);
end$$;


--
-- Name: revenue_contract_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.revenue_contract_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contract_id uuid NOT NULL,
    version_number integer NOT NULL,
    source_version_id uuid,
    revision_reason text NOT NULL,
    changes text,
    internal_rationale text,
    contract_snapshot jsonb NOT NULL,
    sections_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    obligations_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    milestones_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    payment_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    signatory_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    review_status text DEFAULT 'not_requested'::text NOT NULL,
    approval_status text DEFAULT 'not_requested'::text NOT NULL,
    immutable_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: revenue_create_contract_version(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_contract_version(p_contract_id uuid, p_revision_reason text, p_changes text DEFAULT ''::text, p_internal_rationale text DEFAULT ''::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.revenue_contract_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.revenue_contracts; v public.revenue_contract_versions; next_version integer;
begin
  select * into c from public.revenue_contracts where id=p_contract_id for update;
  if not found then raise exception 'Contrat introuvable'; end if;
  select coalesce(max(version_number),0)+1 into next_version from public.revenue_contract_versions where contract_id=c.id;
  insert into public.revenue_contract_versions(
    contract_id,version_number,source_version_id,revision_reason,changes,internal_rationale,contract_snapshot,
    sections_snapshot,obligations_snapshot,milestones_snapshot,payment_snapshot,signatory_snapshot,review_status,approval_status,created_by
  ) values(
    c.id,next_version,c.active_version_id,coalesce(nullif(trim(p_revision_reason),''),'Version contractuelle'),p_changes,p_internal_rationale,to_jsonb(c),
    coalesce((select jsonb_agg(to_jsonb(s) order by s.sort_order) from public.revenue_contract_sections s where s.contract_id=c.id and s.contract_version_id is null),'[]'::jsonb),
    coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at) from public.revenue_contract_obligations o where o.contract_id=c.id),'[]'::jsonb),
    coalesce((select jsonb_agg(to_jsonb(m) order by m.due_at) from public.revenue_contract_milestones m where m.contract_id=c.id),'[]'::jsonb),
    jsonb_build_object('terms',coalesce((select jsonb_agg(to_jsonb(t)) from public.revenue_payment_terms t where t.contract_id=c.id),'[]'::jsonb),'schedules',coalesce((select jsonb_agg(to_jsonb(s)) from public.revenue_payment_schedules s where s.contract_id=c.id),'[]'::jsonb)),
    coalesce((select jsonb_agg(to_jsonb(s) order by s.signing_order) from public.revenue_contract_signatories s where s.contract_id=c.id),'[]'::jsonb),
    c.review_status,c.approval_status,p_actor_id
  ) returning * into v;
  update public.revenue_contracts set active_version_id=v.id,version=version+1,last_activity_at=now(),updated_by=p_actor_id where id=c.id;
  return v;
end$$;


--
-- Name: revenue_create_enterprise_prospect_dossier(jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_enterprise_prospect_dossier(payload jsonb, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT 'Revenue Command'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_contact_id uuid;
  v_prospect_id text;
  v_opportunity_id uuid;
  v_account_name text;
  v_prospect_name text;
  v_contact_name text;
  v_value numeric;
  v_probability numeric;
begin
  v_account_name := coalesce(nullif(trim(payload->>'accountName'), ''), nullif(trim(payload->>'company'), ''), nullif(trim(payload->>'name'), ''), 'Compte sans nom');
  v_prospect_name := coalesce(nullif(trim(payload->>'name'), ''), v_account_name);
  v_contact_name := nullif(trim(payload->>'contactName'), '');
  v_value := coalesce(nullif(payload->>'valueMad', '')::numeric, 0);
  v_probability := greatest(0, least(100, coalesce(nullif(payload->>'probability', '')::numeric, 0)));
  v_prospect_id := gen_random_uuid()::text;

  insert into public.revenue_accounts (
    account_name, legal_name, account_type, segment, city, lifecycle_stage, priority,
    owner_name, website, domain, phone, email, industry, metadata, created_by, updated_by
  ) values (
    v_account_name,
    nullif(payload->>'legalName', ''),
    coalesce(nullif(payload->>'accountType', ''), 'organization'),
    coalesce(nullif(payload->>'segment', ''), 'b2b'),
    coalesce(nullif(payload->>'city', ''), 'Non attribuée'),
    'prospect',
    coalesce(nullif(payload->>'priority', ''), 'medium'),
    coalesce(nullif(payload->>'owner', ''), 'BD Officer'),
    nullif(payload->>'website', ''),
    nullif(payload->>'domain', ''),
    nullif(payload->>'phone', ''),
    nullif(payload->>'email', ''),
    nullif(payload->>'industry', ''),
    jsonb_build_object('source', 'enterprise_dossier_studio'),
    p_actor_id,
    p_actor_id
  ) returning id into v_account_id;

  insert into public.revenue_prospects (
    id, account_id, contact_id, name, company, city, source, segment, stage, priority,
    score, value_mad, probability, owner_id, owner, contact_name, email, phone,
    next_action_at, status, data, metadata, created_by, updated_by
  ) values (
    v_prospect_id,
    v_account_id,
    null,
    v_prospect_name,
    v_account_name,
    coalesce(nullif(payload->>'city', ''), 'Unassigned'),
    coalesce(nullif(payload->>'source', ''), 'manual'),
    coalesce(nullif(payload->>'segment', ''), 'b2b'),
    'new_lead',
    coalesce(nullif(payload->>'priority', ''), 'medium'),
    0,
    v_value,
    v_probability,
    p_actor_id,
    coalesce(nullif(payload->>'owner', ''), 'BD Officer'),
    coalesce(v_contact_name, ''),
    nullif(payload->>'email', ''),
    nullif(payload->>'phone', ''),
    nullif(payload->>'nextActionAt', '')::timestamptz,
    'active',
    jsonb_build_object(
      'needSummary', coalesce(payload->>'needSummary', ''),
      'nextAction', coalesce(payload->>'nextAction', ''),
      'website', coalesce(payload->>'website', ''),
      'industry', coalesce(payload->>'industry', '')
    ),
    jsonb_build_object('source', 'enterprise_dossier_studio'),
    p_actor_id,
    p_actor_id
  );

  if v_contact_name is not null then
    insert into public.revenue_contacts (
      account_id, entity_type, entity_id, full_name, role_title, email, phone, whatsapp,
      influence_level, decision_role, preferred_channel, consent_status, status, owner_id, metadata
    ) values (
      v_account_id,
      'prospect',
      v_prospect_id,
      v_contact_name,
      nullif(payload->>'roleTitle', ''),
      nullif(payload->>'email', ''),
      nullif(payload->>'phone', ''),
      nullif(payload->>'whatsapp', ''),
      'unknown',
      'contact',
      coalesce(nullif(payload->>'preferredChannel', ''), 'phone'),
      'unknown',
      'active',
      p_actor_id,
      jsonb_build_object('source', 'enterprise_dossier_studio')
    ) returning id into v_contact_id;

    update public.revenue_prospects
    set contact_id = v_contact_id, updated_at = now()
    where id = v_prospect_id;
  end if;

  if coalesce((payload->>'createOpportunity')::boolean, true) then
    insert into public.revenue_opportunities (
      prospect_id, account_id, contact_id, title, stage, value_mad, currency,
      probability, expected_close_date, status, priority, forecast_category,
      owner_id, owner, next_step, source, metadata, created_by, updated_by
    ) values (
      v_prospect_id,
      v_account_id,
      v_contact_id,
      coalesce(nullif(payload->>'opportunityTitle', ''), 'Développement ' || v_account_name),
      'qualification',
      v_value,
      'MAD',
      v_probability,
      nullif(payload->>'expectedCloseDate', '')::date,
      'open',
      coalesce(nullif(payload->>'priority', ''), 'medium'),
      'pipeline',
      p_actor_id,
      coalesce(nullif(payload->>'owner', ''), 'BD Officer'),
      nullif(payload->>'nextAction', ''),
      'enterprise_dossier_studio',
      jsonb_build_object('source', 'enterprise_dossier_studio'),
      p_actor_id,
      p_actor_id
    ) returning id into v_opportunity_id;

    insert into public.revenue_opportunity_stage_history (
      opportunity_id, from_stage, to_stage, new_probability, new_value_mad,
      reason, changed_by, changed_by_name, metadata
    ) values (
      v_opportunity_id, null, 'qualification', v_probability, v_value,
      'Création atomique du dossier commercial', p_actor_id, p_actor_name,
      jsonb_build_object('source', 'enterprise_dossier_studio')
    );
  end if;

  insert into public.revenue_activities (
    entity_type, entity_id, prospect_id, event_type, title, actor_id, actor, severity, metadata
  ) values (
    'prospect', v_prospect_id, v_prospect_id, 'enterprise_dossier_created',
    'Dossier commercial créé : ' || v_prospect_name,
    p_actor_id, p_actor_name, 'info',
    jsonb_build_object('accountId', v_account_id, 'contactId', v_contact_id, 'opportunityId', v_opportunity_id)
  );

  insert into public.revenue_command_action_logs (
    action_type, entity_type, entity_id, actor_id, actor, payload, result
  ) values (
    'create_enterprise_prospect_dossier', 'prospect', v_prospect_id,
    p_actor_id, p_actor_name, payload,
    jsonb_build_object('accountId', v_account_id, 'contactId', v_contact_id, 'prospectId', v_prospect_id, 'opportunityId', v_opportunity_id)
  );

  return jsonb_build_object(
    'accountId', v_account_id,
    'contactId', v_contact_id,
    'prospectId', v_prospect_id,
    'opportunityId', v_opportunity_id
  );
end;
$$;


--
-- Name: revenue_create_notification(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_notification(p_entity_type text, p_entity_id text, p_title text, p_body text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text, p_assigned_to text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare new_id uuid;
begin
  insert into public.revenue_notifications(entity_type, entity_id, title, body, severity, assigned_to)
  values (p_entity_type, p_entity_id, p_title, p_body, coalesce(p_severity,'info'), p_assigned_to)
  returning id into new_id;
  return new_id;
end $$;


--
-- Name: revenue_create_partner_attribution(uuid, text, text, numeric, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_partner_attribution(p_referral_id uuid, p_event_type text, p_event_id text, p_attribution_share numeric, p_value_mad numeric, p_evidence_reference text, p_override_reason text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(attribution_id uuid, attributed_value numeric, total_event_share numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  referral public.revenue_partner_referrals%rowtype;
  existing_share numeric;
  source_value numeric;
  final_value numeric;
  created_id uuid;
  open_conflicts integer;
  event_uuid uuid;
  source_currency text := 'MAD';
  existing_attribution_id uuid;
  existing_attribution_value numeric;
begin
  select * into referral from public.revenue_partner_referrals where id=p_referral_id for update;
  if not found then raise exception 'Referral introuvable.'; end if;
  if referral.status in ('rejected','invalid','duplicate','closed') then raise exception 'Ce referral n’est pas éligible à l’attribution.'; end if;
  if p_event_type not in ('prospect_created','opportunity_created','meeting_completed','proposal_created','contract_signed','payment_confirmed','revenue_realized') then
    raise exception 'Type d’événement d’attribution non autorisé.';
  end if;
  if nullif(btrim(coalesce(p_evidence_reference,'')),'') is null then raise exception 'Une preuve d’attribution est requise.'; end if;
  select id,attributed_value into existing_attribution_id,existing_attribution_value
  from public.revenue_partner_referral_attributions
  where referral_id=referral.id and event_type=p_event_type and event_id=p_event_id
  limit 1;
  if found then
    select coalesce(sum(attribution_share),0) into existing_share from public.revenue_partner_referral_attributions
    where event_type=p_event_type and event_id=p_event_id and status in ('confirmed','attributed','active');
    return query select existing_attribution_id,existing_attribution_value,existing_share;
    return;
  end if;
  select count(*) into open_conflicts from public.revenue_partner_attribution_conflicts where referral_id=referral.id and status='open';
  if open_conflicts>0 and p_override_reason is null then raise exception 'Un conflit d’attribution reste ouvert.'; end if;
  if p_attribution_share<=0 or p_attribution_share>100 then raise exception 'La part d’attribution doit être comprise entre 0 et 100.'; end if;
  select coalesce(sum(attribution_share),0) into existing_share
  from public.revenue_partner_referral_attributions
  where event_type=p_event_type and event_id=p_event_id and status in ('confirmed','attributed','active');
  if existing_share+p_attribution_share>100.0001 then raise exception 'La somme des attributions de cet événement dépasse 100%%.'; end if;
  source_value:=greatest(coalesce(p_value_mad,0),0);
  if p_event_type='prospect_created' then
    perform 1 from public.revenue_prospects pr
    where pr.id=p_event_id and (referral.linked_prospect_id is null or pr.id=referral.linked_prospect_id);
    if not found then raise exception 'Le prospect ne peut pas être relié à ce referral.'; end if;
    source_value:=case when source_value>0 then source_value else referral.estimated_value_mad end;
  elsif p_event_type='opportunity_created' then
    begin event_uuid:=p_event_id::uuid; exception when invalid_text_representation then raise exception 'eventId d’opportunité invalide.'; end;
    select o.value_mad,o.currency into source_value,source_currency
    from public.revenue_opportunities o
    where o.id=event_uuid and o.status not in ('archived','cancelled')
      and (referral.linked_opportunity_id is null or o.id=referral.linked_opportunity_id)
      and (referral.linked_prospect_id is null or o.prospect_id=referral.linked_prospect_id);
    if not found then raise exception 'L’opportunité ne peut pas être reliée à ce referral.'; end if;
  elsif p_event_type='meeting_completed' then
    begin event_uuid:=p_event_id::uuid; exception when invalid_text_representation then raise exception 'eventId de meeting invalide.'; end;
    select greatest(coalesce(a.commercial_value_mad,0),coalesce(p_value_mad,0)),'MAD' into source_value,source_currency
    from public.revenue_appointments a
    where a.id=event_uuid and a.status in ('completed','done')
      and (
        a.partnership_id=referral.partnership_id::text
        or (referral.linked_prospect_id is not null and a.prospect_id::text=referral.linked_prospect_id)
        or (referral.linked_opportunity_id is not null and a.opportunity_id=referral.linked_opportunity_id)
      );
    if not found then raise exception 'Le meeting complété ne peut pas être relié à ce referral.'; end if;
  elsif p_event_type='proposal_created' then
    begin event_uuid:=p_event_id::uuid; exception when invalid_text_representation then raise exception 'eventId de proposition invalide.'; end;
    select greatest(coalesce(p.net_value,0),coalesce(p.gross_value,0)),p.currency into source_value,source_currency
    from public.revenue_proposals p
    where p.id=event_uuid and p.status not in ('withdrawn','archived')
      and (
        p.partnership_id=referral.partnership_id::text
        or (referral.linked_prospect_id is not null and p.prospect_id=referral.linked_prospect_id)
        or (referral.linked_opportunity_id is not null and p.opportunity_id=referral.linked_opportunity_id)
      );
    if not found then raise exception 'La proposition ne peut pas être reliée à ce referral.'; end if;
  elsif p_event_type='contract_signed' then
    begin event_uuid:=p_event_id::uuid; exception when invalid_text_representation then raise exception 'eventId de contrat invalide.'; end;
    select greatest(coalesce(c.signed_value,0),coalesce(c.contract_value,0)),c.currency into source_value,source_currency
    from public.revenue_contracts c
    where c.id=event_uuid and c.status in ('fully_signed','conditions_pending','effective','activation_pending','active','completed')
      and (
        c.partnership_id=referral.partnership_id::text
        or (referral.linked_prospect_id is not null and c.prospect_id=referral.linked_prospect_id)
        or (referral.linked_opportunity_id is not null and c.opportunity_id=referral.linked_opportunity_id)
      );
    if not found then raise exception 'Le contrat signé ne peut pas être relié à ce referral.'; end if;
  elsif p_event_type='payment_confirmed' then
    begin event_uuid:=p_event_id::uuid; exception when invalid_text_representation then raise exception 'eventId de paiement invalide.'; end;
    select pc.confirmed_amount,pc.currency into source_value,source_currency
    from public.revenue_payment_confirmations pc
    join public.revenue_contracts c on c.id=pc.contract_id
    where pc.id=event_uuid and pc.reconciliation_status in ('confirmed','partial')
      and (
        c.partnership_id=referral.partnership_id::text
        or (referral.linked_prospect_id is not null and c.prospect_id=referral.linked_prospect_id)
        or (referral.linked_opportunity_id is not null and c.opportunity_id=referral.linked_opportunity_id)
      );
    if not found then raise exception 'Le paiement confirmé ne peut pas être relié à ce referral.'; end if;
  elsif p_event_type='revenue_realized' then
    begin event_uuid:=p_event_id::uuid; exception when invalid_text_representation then raise exception 'eventId de réalisation invalide.'; end;
    select e.amount,e.currency into source_value,source_currency
    from public.revenue_realization_events e
    join public.revenue_contracts c on c.id=e.contract_id
    where e.id=event_uuid and e.status in ('realized','partially_realized')
      and (
        c.partnership_id=referral.partnership_id::text
        or (referral.linked_prospect_id is not null and c.prospect_id=referral.linked_prospect_id)
        or (referral.linked_opportunity_id is not null and c.opportunity_id=referral.linked_opportunity_id)
      );
    if not found then raise exception 'La réalisation confirmée ne peut pas être reliée à ce referral ou partenariat.'; end if;
    if p_value_mad>0 then source_value:=least(source_value,p_value_mad); end if;
  end if;
  source_value:=greatest(coalesce(source_value,0),0);
  final_value:=round(source_value*(p_attribution_share/100.0),2);
  insert into public.revenue_partner_referral_attributions(
    partnership_id,referral_id,event_type,event_id,attribution_method,attribution_share,attributed_value,currency,evidence_reference,status,override_reason,created_by
  ) values(
    referral.partnership_id,referral.id,p_event_type,p_event_id,
    case when p_override_reason is null then 'rules_based_single_source' else 'executive_override' end,
    p_attribution_share,final_value,source_currency,p_evidence_reference,'confirmed',p_override_reason,p_actor_id
  ) returning id into created_id;
  update public.revenue_partner_referrals
  set status=case when p_event_type='revenue_realized' then 'attributed' else status end,updated_by=p_actor_id,updated_at=now()
  where id=referral.id;
  update public.revenue_partnerships p
  set attributed_realized_mad=coalesce((
      select sum(a.attributed_value) from public.revenue_partner_referral_attributions a
      where a.partnership_id=p.id and a.event_type='revenue_realized' and a.status in ('confirmed','attributed','active')
    ),0),
    last_activity_at=now(),updated_at=now()
  where p.id=referral.partnership_id;
  return query select created_id,final_value,existing_share+p_attribution_share;
end
$$;


--
-- Name: revenue_proposal_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.revenue_proposal_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    proposal_id uuid NOT NULL,
    version_number integer NOT NULL,
    source_version_id uuid,
    revision_reason text NOT NULL,
    customer_changes text,
    internal_rationale text,
    proposal_snapshot jsonb NOT NULL,
    sections_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    line_items_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    pricing_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    terms_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    approval_status text DEFAULT 'not_requested'::text NOT NULL,
    document_status text DEFAULT 'not_generated'::text NOT NULL,
    immutable_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: revenue_create_proposal_version(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_create_proposal_version(p_proposal_id uuid, p_revision_reason text, p_customer_changes text DEFAULT ''::text, p_internal_rationale text DEFAULT ''::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.revenue_proposal_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p public.revenue_proposals; v public.revenue_proposal_versions; next_version integer;
begin
  select * into p from public.revenue_proposals where id=p_proposal_id for update;if not found then raise exception 'Proposition introuvable';end if;
  select coalesce(max(version_number),0)+1 into next_version from public.revenue_proposal_versions where proposal_id=p_proposal_id;
  insert into public.revenue_proposal_versions(proposal_id,version_number,source_version_id,revision_reason,customer_changes,internal_rationale,proposal_snapshot,sections_snapshot,line_items_snapshot,pricing_snapshot,terms_snapshot,approval_status,created_by)
  values(p.id,next_version,p.active_version_id,coalesce(nullif(trim(p_revision_reason),''),'Version commerciale'),p_customer_changes,p_internal_rationale,to_jsonb(p),
    coalesce((select jsonb_agg(to_jsonb(s) order by s.sort_order) from public.revenue_proposal_sections s where s.proposal_id=p.id and s.proposal_version_id is null),'[]'::jsonb),
    coalesce((select jsonb_agg(to_jsonb(l) order by l.sort_order) from public.revenue_proposal_line_items l where l.proposal_id=p.id and l.proposal_version_id is null),'[]'::jsonb),
    jsonb_build_object('gross_value',p.gross_value,'discount_value',p.discount_value,'net_value',p.net_value,'estimated_cost',p.estimated_cost,'gross_margin',p.gross_margin,'margin_percent',p.margin_percent,'minimum_margin_percent',p.minimum_margin_percent,'currency',p.currency),
    jsonb_build_object('validity_until',p.validity_until,'commercial_objective',p.commercial_objective,'client_need',p.client_need),p.approval_status,p_actor_id) returning * into v;
  update public.revenue_proposals set active_version_id=v.id,version=version+1,last_activity_at=now(),updated_by=p_actor_id where id=p.id;
  return v;
end$$;


--
-- Name: revenue_dispatch_campaign_step(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_dispatch_campaign_step(p_execution_id uuid, p_provider text DEFAULT 'manual'::text, p_provider_message_id text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare x record;r record;c record;s record;tv record;existing record;comm record;attempt record;v_thread_id uuid;v_key text;v_status text;v_external boolean;
begin
  select * into x from public.revenue_campaign_step_executions where id=p_execution_id for update;
  if not found then raise exception 'Step execution not found.'; end if;
  select * into r from public.revenue_campaign_recipients where id=x.campaign_recipient_id for update;
  select * into c from public.revenue_campaigns where id=x.campaign_id for share;
  select * into s from public.revenue_campaign_sequence_steps where id=x.sequence_step_id and status='approved';
  if not found then raise exception 'Approved sequence step not found.'; end if;
  if s.template_version_id is not null then select * into tv from public.revenue_campaign_template_versions where id=s.template_version_id and status='approved'; end if;
  if c.status<>'active' or c.emergency_stopped then raise exception 'Campaign is not dispatchable.'; end if;
  if exists(select 1 from public.revenue_campaign_suppressions q where q.status='active' and (q.expires_at is null or q.expires_at>now()) and (q.campaign_id is null or q.campaign_id=c.id) and (q.channel='all' or q.channel=coalesce(x.channel,r.channel)) and (q.prospect_id=r.prospect_id or q.contact_id=r.contact_id or q.contact_value_normalized=r.contact_value_normalized)) then raise exception 'Recipient is suppressed.'; end if;
  v_key:=coalesce(nullif(p_idempotency_key,''),'dispatch:'||p_execution_id::text);
  select * into existing from public.revenue_campaign_dispatch_attempts where idempotency_key=v_key for update;
  v_external:=nullif(p_provider_message_id,'') is not null;
  v_status:=case when v_external then 'provider_accepted' else 'prepared' end;
  if found then
    if existing.status='prepared' and v_external then
      update public.revenue_campaign_dispatch_attempts set provider=coalesce(nullif(p_provider,''),provider),provider_message_id=p_provider_message_id,status='provider_accepted',provider_accepted_at=now(),metadata=metadata||jsonb_build_object('confirmedBy',p_actor_id,'confirmedAt',now()) where id=existing.id returning * into existing;
      update public.revenue_communication_events set provider=coalesce(nullif(p_provider,''),provider),provider_message_id=p_provider_message_id,status='provider_accepted',updated_at=now() where id=existing.communication_event_id;
      update public.revenue_campaign_step_executions set status='provider_accepted',attempt_count=attempt_count+1,started_at=coalesce(started_at,now()),updated_by=p_actor_id,updated_at=now() where id=x.id;
      update public.revenue_campaign_recipients set status='contacted',first_contact_at=coalesce(first_contact_at,now()),last_action_at=now(),updated_by=p_actor_id,updated_at=now() where id=r.id;
      return jsonb_build_object('dispatchAttemptId',existing.id,'communicationEventId',existing.communication_event_id,'status','provider_accepted','externalSendConfirmed',true,'idempotentReplay',false,'preparedUpgraded',true);
    end if;
    return jsonb_build_object('dispatchAttemptId',existing.id,'communicationEventId',existing.communication_event_id,'status',existing.status,'externalSendConfirmed',existing.status in ('provider_accepted','sent','delivered'),'idempotentReplay',true);
  end if;
  v_thread_id:=r.communication_thread_id;
  if v_thread_id is not null and not exists(select 1 from public.revenue_communication_threads where id=v_thread_id) then v_thread_id:=null; end if;
  if v_thread_id is null then
    insert into public.revenue_communication_threads(subject,channel_scope,status,prospect_id,account_id,contact_id,owner_id,owner_name,metadata)
    values('Campagne — '||coalesce(r.display_name,c.name),coalesce(x.channel,r.channel),'open',r.prospect_id,r.account_id,r.contact_id,p_actor_id,coalesce(x.owner,c.owner,'Revenue Command'),jsonb_build_object('campaign_id',c.id,'campaign_recipient_id',r.id)) returning id into v_thread_id;
    update public.revenue_campaign_recipients set communication_thread_id=v_thread_id,updated_by=p_actor_id,updated_at=now() where id=r.id;
  end if;
  insert into public.revenue_communication_events(thread_id,campaign_id,campaign_recipient_id,campaign_sequence_version_id,campaign_step_id,prospect_id,account_id,contact_id,direction,channel,provider,provider_message_id,sender,recipients,subject,body_summary,content,occurred_at,status,owner_id,owner_name,metadata)
  values(v_thread_id,c.id,r.id,r.current_sequence_version_id,s.id,r.prospect_id,r.account_id,r.contact_id,'outbound',coalesce(x.channel,r.channel),coalesce(nullif(p_provider,''),'manual'),coalesce(p_provider_message_id,''),coalesce(x.owner,c.owner,'Revenue Command'),jsonb_build_array(r.contact_value),coalesce(tv.subject,''),coalesce(tv.body,s.step_type),jsonb_build_object('stepType',s.step_type,'stepOrder',s.step_order,'templateVersionId',s.template_version_id),now(),v_status,p_actor_id,coalesce(x.owner,c.owner,'Revenue Command'),jsonb_build_object('campaign_id',c.id,'recipient_id',r.id,'execution_id',x.id)) returning * into comm;
  insert into public.revenue_campaign_dispatch_attempts(campaign_id,campaign_recipient_id,step_execution_id,communication_event_id,provider,provider_message_id,status,idempotency_key,provider_accepted_at,created_by)
  values(c.id,r.id,x.id,comm.id,coalesce(nullif(p_provider,''),'manual'),p_provider_message_id,v_status,v_key,case when v_external then now() else null end,p_actor_id) returning * into attempt;
  update public.revenue_campaign_step_executions set status=v_status,attempt_count=attempt_count+1,started_at=case when v_external then coalesce(started_at,now()) else started_at end,updated_by=p_actor_id,updated_at=now() where id=x.id;
  if v_external then update public.revenue_campaign_recipients set status='contacted',first_contact_at=coalesce(first_contact_at,now()),last_action_at=now(),updated_by=p_actor_id,updated_at=now() where id=r.id; end if;
  return jsonb_build_object('dispatchAttemptId',attempt.id,'communicationEventId',comm.id,'status',v_status,'externalSendConfirmed',v_external,'idempotentReplay',false);
end $$;


--
-- Name: revenue_engagement_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_engagement_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ begin new.updated_at=now(); return new; end $$;


--
-- Name: revenue_enroll_campaign_recipient(uuid, text, uuid, uuid, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_enroll_campaign_recipient(p_campaign_id uuid, p_prospect_id text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_sequence_version_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_contact_value text DEFAULT NULL::text, p_owner text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_eval jsonb;v_decision text;v_existing record;v_version record;v_sequence record;v_step record;v_recipient record;v_enrollment record;v_execution record;v_key text;
  v_display_name text;v_account_id uuid;v_effective_contact_id uuid;
begin
  v_key:=coalesce(nullif(p_idempotency_key,''),p_campaign_id::text||':'||coalesce(p_prospect_id,p_contact_id::text,lower(trim(p_contact_value))));
  select * into v_existing from public.revenue_campaign_recipients where idempotency_key=v_key;
  if found then return jsonb_build_object('recipientId',v_existing.id,'idempotentReplay',true); end if;
  v_eval:=public.revenue_evaluate_campaign_recipient(p_campaign_id,p_prospect_id,p_contact_id,p_channel,p_contact_value,p_actor_id);
  v_decision:=v_eval->>'decision';
  if v_decision<>'eligible' then raise exception 'Recipient not eligible: %',v_decision; end if;
  v_display_name:=nullif(trim(coalesce(p_contact_value,'')),'');
  v_effective_contact_id:=p_contact_id;
  if p_prospect_id is not null then
    select name,account_id,coalesce(p_contact_id,contact_id) into v_display_name,v_account_id,v_effective_contact_id
    from public.revenue_prospects where id=p_prospect_id;
    if not found then raise exception 'Prospect not found.'; end if;
  end if;
  if p_sequence_version_id is null then
    select sv.* into v_version from public.revenue_campaign_sequence_versions sv join public.revenue_campaign_sequences s on s.id=sv.sequence_id
    where s.campaign_id=p_campaign_id and sv.status='approved' order by sv.approved_at desc nulls last,sv.created_at desc limit 1;
  else select * into v_version from public.revenue_campaign_sequence_versions where id=p_sequence_version_id and status='approved'; end if;
  if not found then raise exception 'Approved sequence version required.'; end if;
  select * into v_sequence from public.revenue_campaign_sequences where id=v_version.sequence_id;
  select * into v_step from public.revenue_campaign_sequence_steps where sequence_id=v_sequence.id and sequence_version_id=v_version.id and status='approved' order by step_order limit 1;
  if not found then raise exception 'Sequence has no executable step.'; end if;
  insert into public.revenue_campaign_recipients(campaign_id,audience_snapshot_id,prospect_id,account_id,contact_id,display_name,channel,contact_value,contact_value_normalized,status,owner,current_step_order,current_sequence_version_id,eligibility_id,idempotency_key,created_by,updated_by)
  values(p_campaign_id,(select id from public.revenue_campaign_audience_snapshots where campaign_id=p_campaign_id and status='frozen' order by frozen_at desc limit 1),p_prospect_id,v_account_id,v_effective_contact_id,coalesce(v_display_name,p_contact_value),p_channel,p_contact_value,nullif(lower(trim(coalesce(p_contact_value,''))),''),'enrolled',p_owner,v_step.step_order,v_version.id,(v_eval->>'id')::uuid,v_key,p_actor_id,p_actor_id) returning * into v_recipient;
  insert into public.revenue_campaign_enrollments(campaign_id,campaign_recipient_id,sequence_id,sequence_version_id,status,current_step_order,idempotency_key,created_by,updated_by)
  values(p_campaign_id,v_recipient.id,v_sequence.id,v_version.id,'active',v_step.step_order,'enroll:'||v_key,p_actor_id,p_actor_id) returning * into v_enrollment;
  insert into public.revenue_campaign_step_executions(campaign_id,campaign_recipient_id,enrollment_id,sequence_step_id,step_order,step_type,channel,owner,status,scheduled_at,due_at,idempotency_key,created_by,updated_by)
  values(p_campaign_id,v_recipient.id,v_enrollment.id,v_step.id,v_step.step_order,v_step.step_type,v_step.channel,p_owner,'scheduled',now()+make_interval(mins=>greatest(0,v_step.delay_minutes)),now()+make_interval(mins=>greatest(0,v_step.delay_minutes)),'step:'||v_enrollment.id::text||':'||v_step.id::text,p_actor_id,p_actor_id) returning * into v_execution;
  return jsonb_build_object('recipientId',v_recipient.id,'enrollmentId',v_enrollment.id,'executionId',v_execution.id,'idempotentReplay',false);
end $$;


--
-- Name: revenue_enterprise_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_enterprise_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: revenue_escalation_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_escalation_sweep() RETURNS TABLE(overdue_tasks integer, stale_prospects integer, missed_appointments integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare v_overdue integer := 0;
declare v_stale integer := 0;
declare v_missed integer := 0;
begin
  insert into public.revenue_notifications(entity_type, entity_id, title, body, severity, assigned_to)
  select 'task', t.id::text, 'Overdue task', 'Task "' || t.title || '" is overdue for ' || coalesce(t.owner,'owner') || '.', 'warning', t.owner
  from public.revenue_tasks t
  where t.status = 'open'
    and t.due_date is not null
    and t.due_date < current_date
    and not exists (
      select 1 from public.revenue_notifications n
      where n.entity_type = 'task' and n.entity_id = t.id::text and n.title = 'Overdue task' and n.status = 'unread'
    );
  get diagnostics v_overdue = row_count;

  insert into public.revenue_notifications(entity_type, entity_id, title, body, severity)
  select 'prospect', p.id, 'Stale prospect', 'Prospect "' || p.name || '" has no recent update and needs follow-up.', 'warning'
  from public.revenue_prospects p
  where p.updated_at < now() - interval '7 days'
    and coalesce(p.stage,'') not in ('closed_won','closed_lost')
    and not exists (
      select 1 from public.revenue_notifications n
      where n.entity_type = 'prospect' and n.entity_id = p.id and n.title = 'Stale prospect' and n.created_at > now() - interval '48 hours'
    );
  get diagnostics v_stale = row_count;

  insert into public.revenue_notifications(entity_type, entity_id, title, body, severity, assigned_to)
  select 'appointment', a.id::text, 'Missed appointment', 'Appointment "' || a.title || '" is in the past and still scheduled.', 'critical', a.owner
  from public.revenue_appointments a
  where a.status = 'scheduled'
    and a.appointment_at < now()
    and not exists (
      select 1 from public.revenue_notifications n
      where n.entity_type = 'appointment' and n.entity_id = a.id::text and n.title = 'Missed appointment' and n.status = 'unread'
    );
  get diagnostics v_missed = row_count;

  return query select v_overdue, v_stale, v_missed;
end $$;


--
-- Name: revenue_evaluate_activation_gates(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_evaluate_activation_gates(p_contract_id uuid, p_input jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.revenue_contracts; required_signatures integer; signed_signatures integer; required_conditions integer; verified_conditions integer; blocking_amount numeric; confirmed_amount numeric; finance_ok boolean; critical_risks integer; all_passed boolean; gate jsonb;
begin
  select * into c from public.revenue_contracts where id=p_contract_id for update;
  if not found then raise exception 'Contrat introuvable'; end if;
  select count(*),count(*) filter(where status='signed') into required_signatures,signed_signatures from public.revenue_contract_signatories where contract_id=c.id and required;
  select count(*),count(*) filter(where status in ('verified','waived','not_applicable')) into required_conditions,verified_conditions from public.revenue_contract_conditions where contract_id=c.id and required;
  select coalesce(sum(amount),0) into blocking_amount from public.revenue_payment_requirements where contract_id=c.id and activation_blocking and status not in ('waived','cancelled');
  select coalesce(sum(confirmed_amount),0) into confirmed_amount from public.revenue_payment_confirmations where contract_id=c.id and reconciliation_status in ('confirmed','partial');
  select exists(select 1 from public.revenue_finance_handoffs where contract_id=c.id and status='accepted') into finance_ok;
  if blocking_amount=0 then finance_ok:=true; end if;
  select count(*) into critical_risks from public.revenue_contract_risks where contract_id=c.id and status in ('open','monitoring') and severity='critical';

  gate:=jsonb_build_object(
    'contract_approval',c.approval_status='approved',
    'required_signatures',required_signatures>0 and required_signatures=signed_signatures,
    'contract_effective',c.effectiveness_status='effective' or c.status='effective',
    'payment_gate',confirmed_amount>=blocking_amount,
    'finance_handoff',finance_ok,
    'critical_risk',critical_risks=0
  );

  insert into public.revenue_activation_gates(contract_id,gate_key,title,mandatory,status,reason,evaluated_by,evaluated_at)
  values
    (c.id,'contract_approval','Approbation contractuelle',true,case when (gate->>'contract_approval')::boolean then 'passed' else 'failed' end,'Le contrat doit être approuvé.',p_actor_id,now()),
    (c.id,'required_signatures','Signatures obligatoires',true,case when (gate->>'required_signatures')::boolean then 'passed' else 'failed' end,'Tous les signataires obligatoires doivent être vérifiés.',p_actor_id,now()),
    (c.id,'contract_effective','Effectivité contractuelle',true,case when (gate->>'contract_effective')::boolean then 'passed' else 'failed' end,'Le contrat doit être effectif.',p_actor_id,now()),
    (c.id,'payment_gate','Gate de paiement',true,case when (gate->>'payment_gate')::boolean then 'passed' else 'failed' end,format('Confirmé %s / requis %s',confirmed_amount,blocking_amount),p_actor_id,now()),
    (c.id,'finance_handoff','Handoff Finance',true,case when (gate->>'finance_handoff')::boolean then 'passed' else 'failed' end,'Le handoff Finance doit être accepté lorsqu’un paiement est requis.',p_actor_id,now()),
    (c.id,'critical_risk','Absence de risque critique',true,case when (gate->>'critical_risk')::boolean then 'passed' else 'failed' end,'Aucun risque critique ne doit rester ouvert.',p_actor_id,now())
  on conflict(contract_id,gate_key) do update set status=excluded.status,reason=excluded.reason,evaluated_by=excluded.evaluated_by,evaluated_at=excluded.evaluated_at,updated_at=now();

  all_passed:=(gate->>'contract_approval')::boolean and (gate->>'required_signatures')::boolean and (gate->>'contract_effective')::boolean and (gate->>'payment_gate')::boolean and (gate->>'finance_handoff')::boolean and (gate->>'critical_risk')::boolean;
  update public.revenue_contracts set activation_status=case when all_passed then 'ready' else 'blocked' end,payment_gate_status=case when confirmed_amount>=blocking_amount then 'payment_confirmed' else payment_gate_status end,status=case when status='effective' then 'activation_pending' else status end,last_activity_at=now(),updated_by=p_actor_id where id=c.id returning * into c;
  return jsonb_build_object('contract_id',c.id,'ready',all_passed,'gates',gate,'activation_status',c.activation_status,'blocking_amount',blocking_amount,'confirmed_amount',confirmed_amount,'critical_risks',critical_risks);
end$$;


--
-- Name: revenue_evaluate_b2c_activation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_evaluate_b2c_activation(p_case_id uuid, p_actor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(case_id uuid, mandatory_total integer, mandatory_passed integer, activation_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  item public.revenue_b2c_cases%rowtype;
  contract_pass boolean;
  payment_pass boolean;
  matching_pass boolean;
  onboarding_pass boolean;
  handoff_pass boolean;
  availability_pass boolean;
  instructions_pass boolean;
  emergency_pass boolean;
  total integer;
  passed integer;
  final_status text;
begin
  select * into item from public.revenue_b2c_cases where id=p_case_id for update;
  if not found then raise exception 'Dossier famille introuvable.'; end if;

  select exists(select 1 from public.revenue_contracts c where c.id=item.contract_id and c.status in ('fully_signed','conditions_pending','effective','activation_pending','active','completed')) into contract_pass;
  select exists(select 1 from public.revenue_payment_confirmations p where p.contract_id=item.contract_id and p.reconciliation_status in ('confirmed','partial') and p.confirmed_amount>0) into payment_pass;
  select exists(
    select 1 from public.revenue_b2c_matching_cycles m
    join public.revenue_b2c_matching_candidates mc on mc.id=m.selected_candidate_id
    where m.b2c_case_id=item.id and m.status='accepted' and mc.availability_status='verified'
  ) into matching_pass;
  select not exists(
    select 1 from public.revenue_b2c_onboarding_items oi
    join public.revenue_b2c_onboarding_plans op on op.id=oi.onboarding_plan_id
    where op.b2c_case_id=item.id and oi.status<>'completed'
  ) and exists(select 1 from public.revenue_b2c_onboarding_plans op where op.b2c_case_id=item.id and op.status in ('planned','in_progress','ready')) into onboarding_pass;
  select exists(select 1 from public.revenue_operational_handoffs h where h.id=item.operational_handoff_id and h.status='accepted') into handoff_pass;
  availability_pass:=matching_pass;
  select exists(select 1 from public.revenue_b2c_family_instructions i where i.b2c_case_id=item.id and i.status='active') into instructions_pass;
  select exists(select 1 from public.revenue_b2c_emergency_contacts e where e.b2c_case_id=item.id and e.status='active') into emergency_pass;

  insert into public.revenue_b2c_activation_gates(b2c_case_id,gate_key,mandatory,result,reason,evaluated_at,evaluated_by)
  values
    (item.id,'contract',true,case when contract_pass then 'passed' else 'failed' end,case when contract_pass then 'Contrat valide.' else 'Contrat signé/effectif requis.' end,now(),p_actor_id),
    (item.id,'payment',true,case when payment_pass then 'passed' else 'failed' end,case when payment_pass then 'Paiement confirmé.' else 'Confirmation Finance requise.' end,now(),p_actor_id),
    (item.id,'matching',true,case when matching_pass then 'passed' else 'failed' end,case when matching_pass then 'Matching accepté.' else 'Matching accepté requis.' end,now(),p_actor_id),
    (item.id,'onboarding',true,case when onboarding_pass then 'passed' else 'failed' end,case when onboarding_pass then 'Onboarding complet.' else 'Onboarding incomplet.' end,now(),p_actor_id),
    (item.id,'handoff',true,case when handoff_pass then 'passed' else 'failed' end,case when handoff_pass then 'Handoff accepté.' else 'Handoff opérationnel accepté requis.' end,now(),p_actor_id),
    (item.id,'availability',true,case when availability_pass then 'passed' else 'failed' end,case when availability_pass then 'Disponibilité vérifiée.' else 'Disponibilité caregiver à vérifier.' end,now(),p_actor_id),
    (item.id,'instructions',true,case when instructions_pass then 'passed' else 'failed' end,case when instructions_pass then 'Instructions enregistrées.' else 'Instructions famille requises.' end,now(),p_actor_id),
    (item.id,'emergency_contact',true,case when emergency_pass then 'passed' else 'failed' end,case when emergency_pass then 'Contact urgence disponible.' else 'Contact urgence requis.' end,now(),p_actor_id)
  on conflict(b2c_case_id,gate_key) do update
  set result=excluded.result,reason=excluded.reason,evaluated_at=excluded.evaluated_at,evaluated_by=excluded.evaluated_by,updated_at=now();

  select count(*),count(*) filter(where result='passed') into total,passed
  from public.revenue_b2c_activation_gates where b2c_case_id=item.id and mandatory=true;
  final_status:=case when total>0 and total=passed then 'ready' else 'blocked' end;
  update public.revenue_b2c_cases set activation_status=final_status,stage=case when final_status='ready' then 'activation_pending' else stage end,last_activity_at=now(),updated_at=now(),updated_by=p_actor_id where id=item.id;
  insert into public.revenue_b2c_status_history(b2c_case_id,event_type,previous_state,new_state,reason,actor_id,metadata)
  values(item.id,'b2c_activation_evaluated',to_jsonb(item.activation_status),to_jsonb(final_status),null,p_actor_id,jsonb_build_object('mandatory_total',total,'mandatory_passed',passed));
  return query select item.id,total,passed,final_status;
end
$$;


--
-- Name: revenue_evaluate_campaign_readiness(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_evaluate_campaign_readiness(p_campaign_id uuid, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c record;gates jsonb;ready boolean;critical_risks integer;approved_sequence integer;approved_template integer;provider_ready integer;sender_ready integer;approval_ready integer;snapshot_ready integer;
begin
  select * into c from public.revenue_campaigns where id=p_campaign_id for update;
  if not found then raise exception 'Campaign not found.'; end if;
  select count(*) into snapshot_ready from public.revenue_campaign_audience_snapshots where campaign_id=p_campaign_id and status='frozen' and eligible_count>0;
  select count(*) into approved_sequence from public.revenue_campaign_sequences where campaign_id=p_campaign_id and status='approved' and active_version_id is not null;
  select count(distinct tv.id) into approved_template
  from public.revenue_campaign_sequences q
  join public.revenue_campaign_sequence_steps s on s.sequence_id=q.id and s.sequence_version_id=q.active_version_id and s.status='approved'
  join public.revenue_campaign_template_versions tv on tv.id=s.template_version_id and tv.status='approved'
  where q.campaign_id=p_campaign_id and q.status='approved';
  select count(*) into provider_ready from public.revenue_campaign_provider_readiness where campaign_id=p_campaign_id and status='ready';
  select count(*) into sender_ready from public.revenue_campaign_sender_readiness where campaign_id=p_campaign_id and status='ready';
  select count(*) into approval_ready from public.revenue_campaign_approvals where campaign_id=p_campaign_id and status in ('approved','approved_with_limits');
  select count(*) into critical_risks from public.revenue_campaign_risks where campaign_id=p_campaign_id and severity='critical' and status not in ('resolved','closed','accepted');
  gates:=jsonb_build_object(
    'strategy',jsonb_build_object('status',case when nullif(c.objective,'') is not null and nullif(c.audience,'') is not null then 'passed' else 'failed' end),
    'audience',jsonb_build_object('status',case when snapshot_ready>0 then 'passed' else 'failed' end,'count',snapshot_ready),
    'sequence',jsonb_build_object('status',case when approved_sequence>0 then 'passed' else 'failed' end,'count',approved_sequence),
    'templates',jsonb_build_object('status',case when approved_template>0 then 'passed' else 'failed' end,'count',approved_template),
    'provider',jsonb_build_object('status',case when provider_ready>0 then 'passed' else 'failed' end,'count',provider_ready),
    'sender',jsonb_build_object('status',case when sender_ready>0 then 'passed' else 'failed' end,'count',sender_ready),
    'approval',jsonb_build_object('status',case when approval_ready>0 or c.approval_status in ('approved','approved_with_limits') then 'passed' else 'failed' end,'count',approval_ready),
    'risk',jsonb_build_object('status',case when critical_risks=0 then 'passed' else 'failed' end,'criticalOpen',critical_risks),
    'frequency',jsonb_build_object('status',case when jsonb_typeof(c.frequency_policy)='object' then 'passed' else 'failed' end)
  );
  ready:=not exists(select 1 from jsonb_each(gates) x where x.value->>'status'<>'passed');
  update public.revenue_campaigns set readiness_status=case when ready then 'ready' else 'blocked' end,updated_by=p_actor_id,updated_at=now() where id=p_campaign_id;
  insert into public.revenue_campaign_status_history(campaign_id,event_type,title,to_status,payload,result,actor_id)
  values(p_campaign_id,'campaign_readiness_evaluated','Readiness campagne évaluée',case when ready then 'ready' else 'blocked' end,'{}',jsonb_build_object('ready',ready,'gates',gates),p_actor_id);
  return jsonb_build_object('campaignId',p_campaign_id,'ready',ready,'gates',gates);
end $$;


--
-- Name: revenue_evaluate_campaign_recipient(uuid, text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_evaluate_campaign_recipient(p_campaign_id uuid, p_prospect_id text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_contact_value text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_campaign record;v_normalized text;v_suppressed boolean:=false;v_duplicate boolean:=false;v_daily integer:=0;v_weekly integer:=0;
  v_max_day integer:=2;v_max_week integer:=5;v_min_hours integer:=20;v_last timestamptz;v_next timestamptz;
  v_account_id uuid;v_contact_id uuid;
  v_decision text:='eligible';v_reasons jsonb:='[]'::jsonb;v_checks jsonb;v_row revenue_campaign_recipient_eligibility%rowtype;
begin
  select * into v_campaign from public.revenue_campaigns where id=p_campaign_id for share;
  if not found then raise exception 'Campaign not found.'; end if;
  v_contact_id:=p_contact_id;
  if p_prospect_id is not null then
    select account_id,coalesce(p_contact_id,contact_id) into v_account_id,v_contact_id from public.revenue_prospects where id=p_prospect_id;
  end if;
  v_normalized:=lower(trim(coalesce(p_contact_value,'')));
  if v_normalized='' then v_decision:='missing_channel';v_reasons:=v_reasons||jsonb_build_array('contact_value_missing'); end if;
  select exists(select 1 from public.revenue_campaign_suppressions s where s.status='active'
    and (s.expires_at is null or s.expires_at>now())
    and (s.campaign_id is null or s.campaign_id=p_campaign_id)
    and (s.channel='all' or s.channel=p_channel)
    and ((p_prospect_id is not null and s.prospect_id=p_prospect_id) or (v_contact_id is not null and s.contact_id=v_contact_id) or (v_normalized<>'' and s.contact_value_normalized=v_normalized))) into v_suppressed;
  if v_suppressed then v_decision:='suppressed';v_reasons:=v_reasons||jsonb_build_array('active_suppression'); end if;
  select exists(select 1 from public.revenue_campaign_recipients r where r.campaign_id=p_campaign_id
    and r.status not in ('removed','invalid','completed')
    and ((p_prospect_id is not null and r.prospect_id=p_prospect_id) or (v_contact_id is not null and r.contact_id=v_contact_id) or (v_normalized<>'' and r.contact_value_normalized=v_normalized))) into v_duplicate;
  if v_duplicate and v_decision='eligible' then v_decision:='duplicate';v_reasons:=v_reasons||jsonb_build_array('active_enrollment_exists'); end if;
  begin v_max_day:=greatest(1,coalesce((v_campaign.frequency_policy->>'maxPerDay')::integer,2)); exception when others then v_max_day:=2; end;
  begin v_max_week:=greatest(1,coalesce((v_campaign.frequency_policy->>'maxPerWeek')::integer,5)); exception when others then v_max_week:=5; end;
  begin v_min_hours:=greatest(1,coalesce((v_campaign.frequency_policy->>'minHoursBetween')::integer,20)); exception when others then v_min_hours:=20; end;
  select count(*) filter(where occurred_at>=now()-interval '1 day'),count(*) filter(where occurred_at>=now()-interval '7 days'),max(occurred_at)
  into v_daily,v_weekly,v_last from public.revenue_communication_events e
  where e.direction='outbound' and e.channel=p_channel
    and e.status in ('provider_accepted','sent','delivered','recorded','replied')
    and ((p_prospect_id is not null and e.prospect_id=p_prospect_id) or (v_contact_id is not null and e.contact_id=v_contact_id) or (v_normalized<>'' and exists(select 1 from jsonb_array_elements_text(coalesce(e.recipients,'[]'::jsonb)) as x(value) where lower(x.value)=v_normalized)));
  if v_last is not null then v_next:=v_last+make_interval(hours=>v_min_hours); end if;
  if v_decision='eligible' and (v_daily>=v_max_day or v_weekly>=v_max_week or (v_next is not null and v_next>now())) then
    v_decision:='temporarily_blocked';v_reasons:=v_reasons||jsonb_build_array('frequency_cap');
  end if;
  v_checks:=jsonb_build_object('suppressed',v_suppressed,'duplicate',v_duplicate,'dailyCount',v_daily,'weeklyCount',v_weekly,'maxPerDay',v_max_day,'maxPerWeek',v_max_week,'lastContactAt',v_last,'nextAllowedAt',v_next);
  insert into public.revenue_campaign_recipient_eligibility(campaign_id,prospect_id,account_id,contact_id,channel,contact_value,contact_value_normalized,decision,reasons,checks,evaluated_by)
  values(p_campaign_id,p_prospect_id,v_account_id,v_contact_id,p_channel,p_contact_value,nullif(v_normalized,''),v_decision,v_reasons,v_checks,p_actor_id) returning * into v_row;
  insert into public.revenue_campaign_frequency_decisions(campaign_id,prospect_id,contact_id,channel,decision,reason,daily_count,weekly_count,last_contact_at,next_allowed_at,policy_snapshot)
  values(p_campaign_id,p_prospect_id,v_contact_id,p_channel,case when v_decision='temporarily_blocked' then 'blocked' else 'allowed' end,case when v_decision='temporarily_blocked' then 'frequency_cap' else null end,v_daily,v_weekly,v_last,v_next,v_campaign.frequency_policy);
  return jsonb_build_object('id',v_row.id,'decision',v_decision,'reasons',v_reasons,'checks',v_checks);
end $$;


--
-- Name: revenue_evaluate_contract_effectiveness(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_evaluate_contract_effectiveness(p_contract_id uuid, p_input jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.revenue_contracts; pending_approvals integer; pending_signatures integer; pending_conditions integer; blocking_requirements numeric; confirmed_amount numeric; passed boolean;
begin
  select * into c from public.revenue_contracts where id=p_contract_id for update;
  if not found then raise exception 'Contrat introuvable'; end if;
  select count(*) into pending_approvals from public.revenue_contract_approvals where contract_id=c.id and status='requested';
  select count(*) into pending_signatures from public.revenue_contract_signatories where contract_id=c.id and required and status<>'signed';
  select count(*) into pending_conditions from public.revenue_contract_conditions where contract_id=c.id and required and status not in ('verified','waived','not_applicable');
  select coalesce(sum(amount),0) into blocking_requirements from public.revenue_payment_requirements where contract_id=c.id and activation_blocking and status not in ('waived','cancelled');
  select coalesce(sum(confirmed_amount),0) into confirmed_amount from public.revenue_payment_confirmations where contract_id=c.id and reconciliation_status in ('confirmed','partial');
  passed:=c.approval_status='approved' and pending_approvals=0 and pending_signatures=0 and pending_conditions=0 and confirmed_amount>=blocking_requirements;
  update public.revenue_contracts set effectiveness_status=case when passed then 'effective' else 'conditions_pending' end,status=case when passed then 'effective' else case when status in ('fully_signed','conditions_pending') then 'conditions_pending' else status end end,last_activity_at=now(),updated_by=p_actor_id where id=c.id returning * into c;
  return jsonb_build_object('contract_id',c.id,'effective',passed,'approval_pending',pending_approvals,'signature_pending',pending_signatures,'condition_pending',pending_conditions,'blocking_amount',blocking_requirements,'confirmed_amount',confirmed_amount,'effectiveness_status',c.effectiveness_status);
end$$;


--
-- Name: revenue_evaluate_partner_activation(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_evaluate_partner_activation(p_partnership_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_decision text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS TABLE(partnership_id uuid, mandatory_total integer, mandatory_passed integer, activation_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  partner public.revenue_partnerships%rowtype;
  total integer;
  passed integer;
  contract_ready boolean;
  program_ready boolean;
  final_status text;
begin
  select * into partner from public.revenue_partnerships where id=p_partnership_id for update;
  if not found then raise exception 'Partenaire introuvable.'; end if;
  select count(*),count(*) filter(where status in ('passed','completed','verified','approved'))
  into total,passed from public.revenue_partner_activation_gates where partnership_id=partner.id and mandatory=true;
  select exists(select 1 from public.revenue_contracts where id=partner.contract_id and status in ('fully_signed','conditions_pending','effective','activation_pending','active','completed')) into contract_ready;
  select exists(
    select 1 from public.revenue_partner_programs pg
    where pg.partnership_id=partner.id
      and (
        pg.status in ('ready','active')
        or (pg.status='planning' and exists(select 1 from public.revenue_partner_program_service_lines sl where sl.program_id=pg.id and sl.status='configured'))
      )
  ) into program_ready;
  final_status:=case when contract_ready and program_ready and total>0 and total=passed then 'ready' else 'blocked' end;
  if p_decision='approved' then
    if final_status<>'ready' then raise exception 'Les gates obligatoires ne sont pas satisfaits.'; end if;
    final_status:='active';
    update public.revenue_partner_activation_plans set status='active',actual_launch_at=coalesce(actual_launch_at,now()),updated_by=p_actor_id,updated_at=now() where partnership_id=partner.id;
    update public.revenue_partnerships set stage='active',activation_status='active',last_activity_at=now(),updated_at=now(),updated_by=p_actor_id where id=partner.id;
  else
    update public.revenue_partnerships set activation_status=final_status,last_activity_at=now(),updated_at=now(),updated_by=p_actor_id where id=partner.id;
  end if;
  insert into public.revenue_partnership_status_history(partnership_id,event_type,previous_state,new_state,reason,actor_id,metadata)
  values(partner.id,'partner_activation_evaluated',partner.activation_status,final_status,p_reason,p_actor_id,jsonb_build_object('mandatory_total',total,'mandatory_passed',passed,'contract_ready',contract_ready,'program_ready',program_ready));
  return query select partner.id,total,passed,final_status;
end
$$;


--
-- Name: revenue_executive_close_intervention(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_close_intervention(p_intervention_id uuid, p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_intervention public.revenue_executive_interventions; v_outcome public.revenue_executive_intervention_outcomes;
begin
  select * into v_intervention from public.revenue_executive_interventions where id=p_intervention_id for update;
  if not found then raise exception 'Intervention not found'; end if;
  if nullif(p_input->>'evidenceReference','') is null then raise exception 'Closure evidence is required'; end if;
  insert into public.revenue_executive_intervention_outcomes(
    intervention_id,outcome,protected_value_mad,recovered_value_mad,lost_value_mad,evidence_reference,closed_by
  ) values (
    p_intervention_id,coalesce(nullif(p_input->>'outcome',''),'Intervention closed'),
    greatest(coalesce((p_input->>'protectedValueMad')::numeric,0),0),
    greatest(coalesce((p_input->>'recoveredValueMad')::numeric,0),0),
    greatest(coalesce((p_input->>'lostValueMad')::numeric,0),0),
    p_input->>'evidenceReference',p_actor_id
  ) on conflict(intervention_id) do update set
    outcome=excluded.outcome,protected_value_mad=excluded.protected_value_mad,
    recovered_value_mad=excluded.recovered_value_mad,lost_value_mad=excluded.lost_value_mad,
    evidence_reference=excluded.evidence_reference,closed_by=excluded.closed_by,closed_at=timezone('utc',now())
  returning * into v_outcome;
  update public.revenue_executive_interventions set status='closed',closed_at=timezone('utc',now()),updated_by=p_actor_id where id=p_intervention_id;
  perform public.revenue_executive_write_audit('intervention_closed','intervention',p_intervention_id::text,p_actor_id,v_outcome.outcome,v_outcome.evidence_reference,v_outcome.protected_value_mad+v_outcome.recovered_value_mad,p_input);
  return to_jsonb(v_outcome);
end $$;


--
-- Name: revenue_executive_create_forecast_snapshot(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_create_forecast_snapshot(p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_model_version_id uuid;
  v_snapshot public.revenue_executive_forecast_snapshots;
  v_line jsonb;
  v_source_type text;
  v_source_id text;
begin
  select mv.id into v_model_version_id
  from public.revenue_executive_forecast_model_versions mv
  where mv.status='active'
  order by mv.effective_from desc nulls last, mv.created_at desc
  limit 1;

  insert into public.revenue_executive_forecast_snapshots(
    model_version_id,label,horizon,period_start,period_end,status,
    raw_pipeline_mad,weighted_pipeline_mad,upside_mad,best_case_mad,commit_mad,
    contracted_mad,collectible_mad,payment_confirmed_mad,realized_mad,reversed_mad,at_risk_mad,
    summary,evidence_reference,generated_by
  ) values (
    v_model_version_id,
    coalesce(nullif(p_input->>'label',''),'Prévision exécutive ANGELCARE'),
    coalesce(nullif(p_input->>'horizon',''),'current_month'),
    coalesce((p_input->>'periodStart')::date,current_date),
    nullif(p_input->>'periodEnd','')::date,
    'generated',
    coalesce((p_input->'summary'->>'pipelineMad')::numeric,0),
    coalesce((p_input->'summary'->>'weightedPipelineMad')::numeric,0),
    coalesce((p_input->'summary'->>'upsideMad')::numeric,0),
    coalesce((p_input->'summary'->>'bestCaseMad')::numeric,0),
    coalesce((p_input->'summary'->>'commitMad')::numeric,0),
    coalesce((p_input->'summary'->>'contractedMad')::numeric,0),
    coalesce((p_input->'summary'->>'collectibleMad')::numeric,0),
    coalesce((p_input->'summary'->>'confirmedMad')::numeric,0),
    coalesce((p_input->'summary'->>'realizedMad')::numeric,0),
    coalesce((p_input->'summary'->>'reversedMad')::numeric,0),
    coalesce((p_input->'summary'->>'atRiskMad')::numeric,0),
    coalesce(p_input->'summary','{}'::jsonb),
    nullif(p_input->>'evidenceReference',''),
    p_actor_id
  ) returning * into v_snapshot;

  for v_line in select value from jsonb_array_elements(coalesce(p_input->'lines','[]'::jsonb))
  loop
    v_source_type := coalesce(nullif(v_line->>'sourceType',''),'opportunity');
    v_source_id := coalesce(nullif(v_line->>'sourceId',''),nullif(v_line->>'id',''),gen_random_uuid()::text);
    insert into public.revenue_executive_forecast_lines(
      snapshot_id,source_entity_type,source_entity_id,source_label,source_stage,owner_label,
      system_category,effective_category,system_amount_mad,effective_amount_mad,probability,
      confidence,evidence_score,system_expected_date,effective_expected_date,last_activity_at,
      rationale,blockers,evidence,metadata
    ) values (
      v_snapshot.id,v_source_type,v_source_id,
      coalesce(nullif(v_line->>'title',''),'Ligne de prévision'),
      nullif(v_line->>'stage',''),nullif(v_line->>'owner',''),
      coalesce(nullif(v_line->>'category',''),'pipeline'),
      coalesce(nullif(v_line->>'category',''),'pipeline'),
      coalesce((v_line->>'systemAmountMad')::numeric,0),
      coalesce((v_line->>'systemAmountMad')::numeric,0),
      greatest(0,least(100,coalesce((v_line->>'probability')::numeric,0))),
      greatest(0,least(100,coalesce((v_line->>'confidence')::numeric,0))),
      greatest(0,least(100,coalesce((v_line->>'evidenceScore')::numeric,0))),
      nullif(v_line->>'expectedDate','')::date,
      nullif(v_line->>'expectedDate','')::date,
      nullif(v_line->>'lastActivityAt','')::timestamptz,
      nullif(v_line->>'subtitle',''),
      coalesce(v_line->'blockers','[]'::jsonb),
      coalesce(v_line->'evidence','{}'::jsonb),
      v_line
    ) on conflict(snapshot_id,source_entity_type,source_entity_id) do nothing;
  end loop;

  perform public.revenue_executive_write_audit(
    'forecast_snapshot_created','forecast_snapshot',v_snapshot.id::text,p_actor_id,
    'Snapshot exécutif généré',nullif(p_input->>'evidenceReference',''),
    v_snapshot.weighted_pipeline_mad,p_input
  );
  return to_jsonb(v_snapshot);
end $$;


--
-- Name: revenue_executive_create_intervention(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_create_intervention(p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_intervention public.revenue_executive_interventions;
begin
  insert into public.revenue_executive_interventions(
    source_entity_type,source_entity_id,title,root_cause,affected_value_mad,severity,
    priority_score,owner_label,executive_sponsor_label,due_at,required_outcome,status,evidence_reference,created_by,updated_by
  ) values (
    coalesce(nullif(p_input->>'sourceEntityType',''),'executive_signal'),nullif(p_input->>'sourceEntityId',''),
    coalesce(nullif(p_input->>'title',''),'Intervention exécutive'),coalesce(nullif(p_input->>'rootCause',''),'Analyse requise'),
    greatest(coalesce((p_input->>'affectedValueMad')::numeric,0),0),coalesce(nullif(p_input->>'severity',''),'warning'),
    greatest(coalesce((p_input->>'affectedValueMad')::numeric,0),0),
    coalesce(nullif(p_input->>'owner',''),'Revenue Manager'),nullif(p_input->>'executiveSponsor',''),
    nullif(p_input->>'dueAt','')::timestamptz,nullif(p_input->>'requiredOutcome',''),'detected',
    nullif(p_input->>'evidenceReference',''),p_actor_id,p_actor_id
  ) returning * into v_intervention;
  insert into public.revenue_executive_intervention_assignments(intervention_id,owner_label,executive_sponsor_label,assigned_by)
  values(v_intervention.id,v_intervention.owner_label,v_intervention.executive_sponsor_label,p_actor_id);
  perform public.revenue_executive_write_audit('intervention_created','intervention',v_intervention.id::text,p_actor_id,v_intervention.root_cause,v_intervention.evidence_reference,v_intervention.affected_value_mad,p_input);
  return to_jsonb(v_intervention);
exception when unique_violation then
  select * into v_intervention from public.revenue_executive_interventions
  where source_entity_type=coalesce(nullif(p_input->>'sourceEntityType',''),'executive_signal')
    and source_entity_id=nullif(p_input->>'sourceEntityId','')
    and status not in ('closed','rejected','cancelled')
  order by created_at desc limit 1;
  return to_jsonb(v_intervention);
end $$;


--
-- Name: revenue_executive_decide_intervention(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_decide_intervention(p_target_id uuid, p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_request public.revenue_executive_decision_requests; v_intervention_id uuid; v_decision public.revenue_executive_decisions;
begin
  select * into v_request from public.revenue_executive_decision_requests where id=p_target_id for update;
  if found then v_intervention_id := v_request.intervention_id;
  else
    select id into v_intervention_id from public.revenue_executive_interventions where id=p_target_id for update;
    if not found then raise exception 'Decision target not found'; end if;
  end if;
  insert into public.revenue_executive_decisions(
    decision_request_id,intervention_id,decision,reason,conditions,affected_value_mad,evidence_reference,decided_by,metadata
  ) values (
    case when v_request.id is not null then v_request.id else null end,v_intervention_id,
    coalesce(nullif(p_input->>'decision',''),'approved'),coalesce(nullif(p_input->>'reason',''),'Decision recorded'),
    nullif(p_input->>'conditions',''),coalesce(v_request.affected_value_mad,0),nullif(p_input->>'evidenceReference',''),p_actor_id,p_input
  ) returning * into v_decision;
  if v_request.id is not null then
    update public.revenue_executive_decision_requests set status=case when v_decision.decision='deferred' then 'deferred' else 'decided' end,
      decided_at=timezone('utc',now()) where id=v_request.id;
  end if;
  if v_intervention_id is not null then
    update public.revenue_executive_interventions set
      status=case when v_decision.decision in ('approved','approved_with_conditions') then 'approved_action'
                  when v_decision.decision='deferred' then 'deferred'
                  when v_decision.decision='rejected' then 'rejected' else 'decision_required' end,
      updated_by=p_actor_id
    where id=v_intervention_id;
  end if;
  perform public.revenue_executive_write_audit('executive_decision_recorded','decision',v_decision.id::text,p_actor_id,v_decision.reason,v_decision.evidence_reference,v_decision.affected_value_mad,p_input);
  return to_jsonb(v_decision);
end $$;


--
-- Name: revenue_executive_guard_decision_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_guard_decision_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  raise exception 'Final executive decisions are immutable.';
end $$;


--
-- Name: revenue_executive_guard_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_guard_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Executive governance records are immutable after formalization.';
  end if;
  if coalesce(old.status,'') in ('approved','closed','distributed') then
    raise exception 'Approved or closed executive records are immutable.';
  end if;
  return new;
end;
$$;


--
-- Name: revenue_executive_manage_briefing(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_manage_briefing(p_briefing_id uuid, p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_mode text; v_briefing public.revenue_executive_briefings; v_snapshot_id uuid;
begin
  v_mode := coalesce(nullif(p_input->>'mode',''),'generate');
  if v_mode='generate' then
    select id into v_snapshot_id from public.revenue_executive_forecast_snapshots order by created_at desc limit 1;
    insert into public.revenue_executive_briefings(
      title,briefing_type,horizon,source_snapshot_id,narrative,evidence_reference,generated_by
    ) values (
      coalesce(nullif(p_input->>'title',''),'Briefing exécutif ANGELCARE'),
      coalesce(nullif(p_input->>'briefingType',''),'weekly'),
      coalesce(nullif(p_input->>'horizon',''),'current_month'),v_snapshot_id,
      nullif(p_input->>'narrative',''),nullif(p_input->>'evidenceReference',''),p_actor_id
    ) returning * into v_briefing;
  elsif v_mode='approve' then
    update public.revenue_executive_briefings set status='approved',approved_by=p_actor_id,approved_at=timezone('utc',now())
    where id=p_briefing_id returning * into v_briefing;
    if not found then raise exception 'Briefing not found'; end if;
  else raise exception 'Unsupported briefing mode';
  end if;
  perform public.revenue_executive_write_audit('briefing_'||v_mode,'briefing',v_briefing.id::text,p_actor_id,coalesce(p_input->>'narrative',''),nullif(p_input->>'evidenceReference',''),0,p_input);
  return to_jsonb(v_briefing);
end $$;


--
-- Name: revenue_executive_manage_scenario(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_manage_scenario(p_scenario_id uuid, p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_mode text; v_scenario public.revenue_executive_scenarios; v_version public.revenue_executive_scenario_versions;
begin
  v_mode := coalesce(nullif(p_input->>'mode',''),'create');
  if v_mode='create' then
    insert into public.revenue_executive_scenarios(title,scenario_type,horizon,rationale,evidence_reference,created_by)
    values(coalesce(nullif(p_input->>'title',''),'Scénario exécutif'),coalesce(nullif(p_input->>'scenarioType',''),'expected'),
      coalesce(nullif(p_input->>'horizon',''),'current_month'),nullif(p_input->>'rationale',''),nullif(p_input->>'evidenceReference',''),p_actor_id)
    returning * into v_scenario;
    insert into public.revenue_executive_scenario_versions(scenario_id,version_number,assumptions,status,created_by)
    values(v_scenario.id,1,coalesce(p_input->'assumptions','[]'::jsonb),'draft',p_actor_id) returning * into v_version;
  else
    select * into v_scenario from public.revenue_executive_scenarios where id=p_scenario_id for update;
    if not found then raise exception 'Scenario not found'; end if;
    select * into v_version from public.revenue_executive_scenario_versions where scenario_id=v_scenario.id order by version_number desc limit 1;
    if v_mode='run' then
      insert into public.revenue_executive_scenario_results(scenario_version_id,status,baseline_metrics,simulated_metrics,differences,decision_implications,generated_by)
      values(v_version.id,'simulated','{}'::jsonb,jsonb_build_object('scenarioType',v_scenario.scenario_type,'assumptions',v_version.assumptions),
        '{}'::jsonb,'[]'::jsonb,p_actor_id);
      update public.revenue_executive_scenarios set status='completed' where id=v_scenario.id returning * into v_scenario;
    elsif v_mode='approve' then
      update public.revenue_executive_scenarios set status='approved',approved_by=p_actor_id,approved_at=timezone('utc',now()) where id=v_scenario.id returning * into v_scenario;
    else raise exception 'Unsupported scenario mode';
    end if;
  end if;
  perform public.revenue_executive_write_audit('scenario_'||v_mode,'scenario',v_scenario.id::text,p_actor_id,coalesce(p_input->>'rationale',''),nullif(p_input->>'evidenceReference',''),0,p_input);
  return to_jsonb(v_scenario);
end $$;


--
-- Name: revenue_executive_override_forecast(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_override_forecast(p_forecast_line_id uuid, p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_line public.revenue_executive_forecast_lines; v_override public.revenue_executive_forecast_overrides; v_mode text;
begin
  select * into v_line from public.revenue_executive_forecast_lines where id=p_forecast_line_id for update;
  if not found then raise exception 'Forecast line not found'; end if;
  v_mode := coalesce(nullif(p_input->>'mode',''),'apply');
  if v_mode='expire' then
    update public.revenue_executive_forecast_overrides set status='expired',expired_by=p_actor_id,expired_at=timezone('utc',now())
    where forecast_line_id=p_forecast_line_id and status='active'
    returning * into v_override;
    update public.revenue_executive_forecast_lines set
      executive_amount_mad=null,executive_category=null,executive_expected_date=null,
      effective_amount_mad=coalesce(owner_amount_mad,system_amount_mad),
      effective_category=coalesce(owner_category,system_category),
      effective_expected_date=coalesce(owner_expected_date,system_expected_date)
    where id=p_forecast_line_id;
  else
    update public.revenue_executive_forecast_overrides set status='superseded'
    where forecast_line_id=p_forecast_line_id and status='active';
    insert into public.revenue_executive_forecast_overrides(
      forecast_line_id,override_amount_mad,override_category,override_expected_date,reason,evidence_reference,review_at,created_by
    ) values (
      p_forecast_line_id,greatest(coalesce((p_input->>'amountMad')::numeric,0),0),
      coalesce(nullif(p_input->>'category',''),'commit'),nullif(p_input->>'expectedDate','')::date,
      coalesce(nullif(p_input->>'reason',''),'Executive override'),nullif(p_input->>'evidenceReference',''),
      nullif(p_input->>'reviewAt','')::timestamptz,p_actor_id
    ) returning * into v_override;
    update public.revenue_executive_forecast_lines set
      executive_amount_mad=v_override.override_amount_mad,executive_category=v_override.override_category,
      executive_expected_date=v_override.override_expected_date,effective_amount_mad=v_override.override_amount_mad,
      effective_category=v_override.override_category,effective_expected_date=v_override.override_expected_date
    where id=p_forecast_line_id;
  end if;
  perform public.revenue_executive_write_audit('forecast_override_'||v_mode,'forecast_line',p_forecast_line_id::text,p_actor_id,coalesce(p_input->>'reason',''),nullif(p_input->>'evidenceReference',''),coalesce(v_override.override_amount_mad,0),p_input);
  return coalesce(to_jsonb(v_override),'{}'::jsonb);
end $$;


--
-- Name: revenue_executive_submit_forecast(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_submit_forecast(p_forecast_line_id uuid, p_input jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_line public.revenue_executive_forecast_lines; v_submission public.revenue_executive_forecast_submissions;
begin
  select * into v_line from public.revenue_executive_forecast_lines where id=p_forecast_line_id for update;
  if not found then raise exception 'Forecast line not found'; end if;
  insert into public.revenue_executive_forecast_submissions(
    forecast_line_id,amount_mad,forecast_category,expected_date,probability,rationale,evidence_reference,submitted_by
  ) values (
    p_forecast_line_id,greatest(coalesce((p_input->>'amountMad')::numeric,0),0),
    coalesce(nullif(p_input->>'category',''),'commit'),nullif(p_input->>'expectedDate','')::date,
    greatest(0,least(100,coalesce((p_input->>'probability')::numeric,0))),
    coalesce(nullif(p_input->>'rationale',''),'Forecast owner submission'),
    nullif(p_input->>'evidenceReference',''),p_actor_id
  ) returning * into v_submission;
  update public.revenue_executive_forecast_lines set
    owner_amount_mad=v_submission.amount_mad,
    owner_category=v_submission.forecast_category,
    owner_expected_date=v_submission.expected_date,
    effective_amount_mad=coalesce(executive_amount_mad,v_submission.amount_mad,system_amount_mad),
    effective_category=coalesce(executive_category,v_submission.forecast_category,system_category),
    effective_expected_date=coalesce(executive_expected_date,v_submission.expected_date,system_expected_date),
    rationale=v_submission.rationale
  where id=p_forecast_line_id;
  perform public.revenue_executive_write_audit('forecast_submitted','forecast_line',p_forecast_line_id::text,p_actor_id,v_submission.rationale,v_submission.evidence_reference,v_submission.amount_mad,p_input);
  return to_jsonb(v_submission);
end $$;


