--
-- Name: revenue_executive_write_audit(text, text, text, uuid, text, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_executive_write_audit(p_event_type text, p_entity_type text, p_entity_id text, p_actor_id uuid, p_reason text, p_evidence_reference text, p_affected_value_mad numeric, p_metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  insert into public.revenue_executive_audit_events(
    event_type,entity_type,entity_id,actor_id,reason,evidence_reference,affected_value_mad,metadata
  ) values (
    p_event_type,p_entity_type,p_entity_id,p_actor_id,p_reason,p_evidence_reference,
    greatest(coalesce(p_affected_value_mad,0),0),coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end $$;


--
-- Name: revenue_freeze_campaign_audience(uuid, uuid, uuid, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_freeze_campaign_audience(p_campaign_id uuid, p_segment_id uuid DEFAULT NULL::uuid, p_segment_version_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT 'frozen'::text, p_filter_snapshot jsonb DEFAULT '{}'::jsonb, p_members jsonb DEFAULT '[]'::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_campaign record;v_snapshot record;v_member jsonb;v_eval jsonb;v_decision text;v_prospect_id text;v_contact_id uuid;
  v_account_id uuid;v_display_name text;v_channel text;v_contact_value text;v_candidate integer:=0;v_eligible integer:=0;
  v_excluded integer:=0;v_suppressed integer:=0;v_missing integer:=0;v_frequency integer:=0;v_duplicate integer:=0;
begin
  select * into v_campaign from public.revenue_campaigns where id=p_campaign_id for update;
  if not found then raise exception 'Campaign not found.'; end if;
  if jsonb_typeof(coalesce(p_members,'[]'::jsonb))<>'array' then raise exception 'Audience members must be a JSON array.'; end if;
  insert into public.revenue_campaign_audience_snapshots(campaign_id,segment_id,segment_version_id,mode,filter_snapshot,status,frozen_by,frozen_at)
  values(p_campaign_id,p_segment_id,p_segment_version_id,coalesce(nullif(p_mode,''),'frozen'),coalesce(p_filter_snapshot,'{}'::jsonb),'building',p_actor_id,now())
  returning * into v_snapshot;
  for v_member in select value from jsonb_array_elements(coalesce(p_members,'[]'::jsonb)) loop
    v_candidate:=v_candidate+1;
    v_prospect_id:=nullif(trim(v_member->>'prospectId'),'');
    v_contact_id:=nullif(trim(v_member->>'contactId'),'')::uuid;
    v_account_id:=nullif(trim(v_member->>'accountId'),'')::uuid;
    v_display_name:=coalesce(nullif(trim(v_member->>'displayName'),''),nullif(trim(v_member->>'name'),''),nullif(trim(v_member->>'contactValue'),''),'Destinataire');
    v_channel:=coalesce(nullif(trim(v_member->>'channel'),''),'email');
    v_contact_value:=coalesce(nullif(trim(v_member->>'contactValue'),''),nullif(trim(v_member->>'email'),''),nullif(trim(v_member->>'phone'),''));
    begin
      v_eval:=public.revenue_evaluate_campaign_recipient(p_campaign_id,v_prospect_id,v_contact_id,v_channel,v_contact_value,p_actor_id);
      v_decision:=coalesce(v_eval->>'decision','requires_review');
    exception when others then
      v_decision:='requires_review';
      v_eval:=jsonb_build_object('decision',v_decision,'reasons',jsonb_build_array(sqlerrm));
    end;
    if exists(
      select 1 from public.revenue_campaign_audience_members m
      where m.snapshot_id=v_snapshot.id and coalesce(m.prospect_id,'')=coalesce(v_prospect_id,'')
        and coalesce(m.contact_id::text,'')=coalesce(v_contact_id::text,'')
        and coalesce(m.contact_value_normalized,'')=coalesce(lower(trim(v_contact_value)),'')
    ) then
      v_duplicate:=v_duplicate+1;
      continue;
    end if;
    if v_prospect_id is not null then
      select coalesce(v_account_id,p.account_id),coalesce(v_contact_id,p.contact_id),coalesce(nullif(v_display_name,'Destinataire'),p.name),coalesce(v_contact_value,case when v_channel='email' then p.email else p.phone end)
      into v_account_id,v_contact_id,v_display_name,v_contact_value from public.revenue_prospects p where p.id=v_prospect_id;
    end if;
    insert into public.revenue_campaign_audience_members(snapshot_id,campaign_id,prospect_id,account_id,contact_id,display_name,channel,contact_value,contact_value_normalized,eligibility_status,exclusion_reason,metadata)
    values(v_snapshot.id,p_campaign_id,v_prospect_id,v_account_id,v_contact_id,v_display_name,v_channel,v_contact_value,nullif(lower(trim(coalesce(v_contact_value,''))),''),v_decision,
      case when v_decision='eligible' then null else coalesce((v_eval->'reasons'->>0),v_decision) end,
      coalesce(v_member->'metadata','{}'::jsonb)||jsonb_build_object('eligibility',v_eval));
    if v_decision='eligible' then v_eligible:=v_eligible+1;
    elsif v_decision='suppressed' then v_suppressed:=v_suppressed+1;
    elsif v_decision='missing_channel' then v_missing:=v_missing+1;
    elsif v_decision='temporarily_blocked' then v_frequency:=v_frequency+1;
    else v_excluded:=v_excluded+1; end if;
  end loop;
  update public.revenue_campaign_audience_snapshots set
    candidate_count=v_candidate,eligible_count=v_eligible,excluded_count=v_excluded,suppressed_count=v_suppressed,
    duplicate_count=v_duplicate,missing_channel_count=v_missing,frequency_blocked_count=v_frequency,status='frozen'
  where id=v_snapshot.id returning * into v_snapshot;
  update public.revenue_campaigns set audience_snapshot_id=v_snapshot.id,audience_mode=coalesce(nullif(p_mode,''),'frozen'),status='sequence_preparation',updated_by=p_actor_id,updated_at=now() where id=p_campaign_id;
  insert into public.revenue_campaign_status_history(campaign_id,event_type,title,to_status,payload,result,actor_id)
  values(p_campaign_id,'campaign_audience_frozen','Audience campagne figée','sequence_preparation',jsonb_build_object('segmentId',p_segment_id,'mode',p_mode),
    jsonb_build_object('snapshotId',v_snapshot.id,'candidateCount',v_candidate,'eligibleCount',v_eligible,'excludedCount',v_excluded,'suppressedCount',v_suppressed,'duplicateCount',v_duplicate,'missingChannelCount',v_missing,'frequencyBlockedCount',v_frequency),p_actor_id);
  return jsonb_build_object('id',v_snapshot.id,'candidateCount',v_candidate,'eligibleCount',v_eligible,'excludedCount',v_excluded,'suppressedCount',v_suppressed,'duplicateCount',v_duplicate,'missingChannelCount',v_missing,'frequencyBlockedCount',v_frequency,'status','frozen');
end $$;


--
-- Name: revenue_launch_campaign(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_launch_campaign(p_campaign_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c record;r jsonb;m record;enrollment jsonb;scheduled integer:=0;enrolled integer:=0;skipped integer:=0;errors jsonb:='[]'::jsonb;
begin
  select * into c from public.revenue_campaigns where id=p_campaign_id for update;
  if not found then raise exception 'Campaign not found.'; end if;
  if c.status in ('active','launching') then return jsonb_build_object('campaignId',p_campaign_id,'status',c.status,'idempotentReplay',true); end if;
  r:=public.revenue_evaluate_campaign_readiness(p_campaign_id,p_actor_id);
  if coalesce((r->>'ready')::boolean,false)=false then raise exception 'Campaign readiness is blocked.'; end if;
  if c.approval_status not in ('approved','approved_with_limits') and not exists(select 1 from public.revenue_campaign_approvals where campaign_id=p_campaign_id and status in ('approved','approved_with_limits')) then raise exception 'Approved launch decision required.'; end if;
  for m in
    select * from public.revenue_campaign_audience_members
    where snapshot_id=c.audience_snapshot_id and campaign_id=p_campaign_id and eligibility_status='eligible'
    order by created_at,id
  loop
    begin
      enrollment:=public.revenue_enroll_campaign_recipient(p_campaign_id,m.prospect_id,m.contact_id,null,coalesce(nullif(m.channel,''),'email'),m.contact_value,coalesce(c.sdr_lead,c.owner,'SDR'),p_actor_id,
        coalesce(nullif(p_idempotency_key,''),'launch-'||p_campaign_id::text)||':'||m.id::text);
      if coalesce((enrollment->>'idempotentReplay')::boolean,false) then skipped:=skipped+1; else enrolled:=enrolled+1; end if;
    exception when others then
      skipped:=skipped+1;
      errors:=errors||jsonb_build_array(jsonb_build_object('audienceMemberId',m.id,'error',sqlerrm));
    end;
  end loop;
  if not exists(select 1 from public.revenue_campaign_recipients where campaign_id=p_campaign_id and status not in ('removed','invalid')) then
    raise exception 'Campaign launch produced no eligible enrollment.';
  end if;
  update public.revenue_campaigns set status='active',launch_at=coalesce(launch_at,now()),updated_by=p_actor_id,updated_at=now() where id=p_campaign_id;
  update public.revenue_campaign_step_executions set status='scheduled',updated_by=p_actor_id,updated_at=now() where campaign_id=p_campaign_id and status='prepared';
  get diagnostics scheduled=row_count;
  insert into public.revenue_campaign_status_history(campaign_id,event_type,title,from_status,to_status,payload,result,actor_id)
  values(p_campaign_id,'campaign_launched','Campagne lancée',c.status,'active',jsonb_build_object('idempotencyKey',p_idempotency_key),jsonb_build_object('enrolledRecipients',enrolled,'skippedRecipients',skipped,'scheduledExecutions',scheduled,'errors',errors),p_actor_id);
  return jsonb_build_object('campaignId',p_campaign_id,'status','active','enrolledRecipients',enrolled,'skippedRecipients',skipped,'scheduledExecutions',scheduled,'errors',errors,'idempotentReplay',false);
end $$;


--
-- Name: revenue_launch_partner_renewal_workflow(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_launch_partner_renewal_workflow(p_renewal_id uuid, p_action text, p_actor_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS TABLE(renewal_id uuid, proposal_id uuid, negotiation_id uuid, workflow_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  renewal public.revenue_partner_renewal_readiness%rowtype;
  partner public.revenue_partnerships%rowtype;
  proposal public.revenue_proposals%rowtype;
  created_proposal_id uuid;
  created_negotiation_id uuid;
begin
  select * into renewal from public.revenue_partner_renewal_readiness where id=p_renewal_id for update;
  if not found then raise exception 'Dossier de renouvellement introuvable.'; end if;
  if renewal.status not in ('approved','proposal_launched','negotiation_launched') then
    raise exception 'La recommandation de renouvellement doit être approuvée avant lancement.';
  end if;
  select * into partner from public.revenue_partnerships where id=renewal.partnership_id for update;
  if not found then raise exception 'Partenaire introuvable.'; end if;
  if p_action='launch_proposal' then
    created_proposal_id:=renewal.proposal_id;
    if created_proposal_id is null then
      insert into public.revenue_proposals(
        title,status,proposal_type,context_type,prospect_id,account_id,partnership_id,owner,currency,
        commercial_objective,client_need,next_action,validity_until,metadata,created_by,updated_by
      ) values(
        'Renouvellement — '||coalesce(partner.partner_name,'Partenaire ANGELCARE'),'draft','partnership_renewal','partnership',
        partner.prospect_text_id,partner.account_id,partner.id::text,coalesce(partner.owner,'Partnership Manager'),'MAD',
        coalesce(nullif(p_notes,''),'Préparer le renouvellement sur la base de la performance et des obligations vérifiées.'),
        renewal.evidence_summary,'Finaliser scope, pricing, approvals et conditions de renouvellement.',current_date+30,
        jsonb_build_object('renewal_id',renewal.id,'contract_id',renewal.contract_id,'source','partnership_enterprise'),p_actor_id,p_actor_id
      ) returning id into created_proposal_id;
    end if;
    update public.revenue_partner_renewal_readiness
      set proposal_id=created_proposal_id,proposal_requested_at=coalesce(proposal_requested_at,now()),status='proposal_launched',updated_by=p_actor_id,updated_at=now()
      where id=renewal.id;
    update public.revenue_partnerships set stage='renewal_pending',last_activity_at=now(),updated_at=now(),updated_by=p_actor_id where id=partner.id;
    return query select renewal.id,created_proposal_id,renewal.negotiation_id,'proposal_launched'::text;
    return;
  elsif p_action='launch_negotiation' then
    created_proposal_id:=renewal.proposal_id;
    if created_proposal_id is null then raise exception 'Une proposition de renouvellement doit être créée avant la négociation.'; end if;
    select * into proposal from public.revenue_proposals where id=created_proposal_id for update;
    if not found then raise exception 'Proposition de renouvellement introuvable.'; end if;
    created_negotiation_id:=renewal.negotiation_id;
    if created_negotiation_id is null then
      insert into public.revenue_negotiations(
        proposal_id,proposal_version_id,title,status,current_round,angelcare_position_value,customer_position_value,
        current_margin_percent,opening_position,owner,created_by,updated_by
      ) values(
        proposal.id,proposal.active_version_id,'Négociation renouvellement — '||proposal.title,'open',1,proposal.net_value,0,
        proposal.margin_percent,coalesce(nullif(p_notes,''),'Position ANGELCARE fondée sur performance, obligations et valeur réalisée.'),
        proposal.owner,p_actor_id,p_actor_id
      ) returning id into created_negotiation_id;
      insert into public.revenue_negotiation_rounds(negotiation_id,round_number,status,summary,opened_by)
      values(created_negotiation_id,1,'open',coalesce(nullif(p_notes,''),'Ouverture de la négociation de renouvellement.'),p_actor_id);
    end if;
    update public.revenue_proposals set status='negotiation',negotiation_status='open',updated_by=p_actor_id,updated_at=now() where id=proposal.id;
    update public.revenue_partner_renewal_readiness
      set negotiation_id=created_negotiation_id,negotiation_requested_at=coalesce(negotiation_requested_at,now()),status='negotiation_launched',updated_by=p_actor_id,updated_at=now()
      where id=renewal.id;
    return query select renewal.id,created_proposal_id,created_negotiation_id,'negotiation_launched'::text;
    return;
  end if;
  raise exception 'Action de renouvellement non autorisée.';
end
$$;


--
-- Name: revenue_log_appointment_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_log_appointment_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.revenue_log_event('appointment', new.id::text, 'appointment.scheduled', 'Appointment scheduled', new.title, new.owner, 'info', to_jsonb(new));
  elsif tg_op = 'UPDATE' then
    if old.status is distinct from new.status then
      perform public.revenue_log_event('appointment', new.id::text, 'appointment.status_changed', 'Appointment status changed', old.status || ' → ' || new.status, new.owner, case when new.status='completed' then 'success' else 'info' end, to_jsonb(new));
    else
      perform public.revenue_log_event('appointment', new.id::text, 'appointment.updated', 'Appointment updated', new.title, new.owner, 'info', to_jsonb(new));
    end if;
  elsif tg_op = 'DELETE' then
    perform public.revenue_log_event('appointment', old.id::text, 'appointment.deleted', 'Appointment deleted', old.title, old.owner, 'warning', to_jsonb(old));
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: revenue_log_document_version_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_log_document_version_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.revenue_log_event(new.entity_type, new.entity_id, 'document.version_uploaded', 'Document version uploaded', new.title || ' v' || new.version, new.uploaded_by, 'info', to_jsonb(new));
  elsif tg_op = 'UPDATE' then
    perform public.revenue_log_event(new.entity_type, new.entity_id, 'document.version_updated', 'Document version updated', new.title || ' v' || new.version, new.uploaded_by, 'info', to_jsonb(new));
  elsif tg_op = 'DELETE' then
    perform public.revenue_log_event(old.entity_type, old.entity_id, 'document.version_deleted', 'Document version deleted', old.title || ' v' || old.version, old.uploaded_by, 'warning', to_jsonb(old));
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: revenue_log_event(text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_log_event(p_entity_type text, p_entity_id text, p_event_type text, p_event_title text, p_event_body text DEFAULT NULL::text, p_actor text DEFAULT 'AngelCare'::text, p_severity text DEFAULT 'info'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare new_id uuid;
begin
  insert into public.revenue_events(entity_type, entity_id, event_type, event_title, event_body, actor, severity, metadata)
  values (coalesce(p_entity_type,'system'), coalesce(p_entity_id,'global'), p_event_type, p_event_title, p_event_body, coalesce(p_actor,'AngelCare'), coalesce(p_severity,'info'), coalesce(p_metadata,'{}'::jsonb))
  returning id into new_id;
  return new_id;
end $$;


--
-- Name: revenue_log_prospect_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_log_prospect_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.revenue_log_event('prospect', new.id, 'prospect.created', 'Prospect created', new.name, 'AngelCare', 'info', new.data);
  elsif tg_op = 'UPDATE' then
    if old.stage is distinct from new.stage then
      perform public.revenue_log_event('prospect', new.id, 'prospect.stage_changed', 'Prospect stage changed', coalesce(old.stage,'start') || ' → ' || new.stage, 'AngelCare', 'info', new.data);
    else
      perform public.revenue_log_event('prospect', new.id, 'prospect.updated', 'Prospect updated', new.name, 'AngelCare', 'info', new.data);
    end if;
  elsif tg_op = 'DELETE' then
    perform public.revenue_log_event('prospect', old.id, 'prospect.deleted', 'Prospect deleted', old.name, 'AngelCare', 'warning', old.data);
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: revenue_log_task_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_log_task_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.revenue_log_event('task', new.id::text, 'task.created', 'Task created', new.title, new.owner, 'info', to_jsonb(new));
  elsif tg_op = 'UPDATE' then
    if old.status is distinct from new.status then
      perform public.revenue_log_event('task', new.id::text, 'task.status_changed', 'Task status changed', old.status || ' → ' || new.status, new.owner, case when new.status='done' then 'success' else 'info' end, to_jsonb(new));
    else
      perform public.revenue_log_event('task', new.id::text, 'task.updated', 'Task updated', new.title, new.owner, 'info', to_jsonb(new));
    end if;
  elsif tg_op = 'DELETE' then
    perform public.revenue_log_event('task', old.id::text, 'task.deleted', 'Task deleted', old.title, old.owner, 'warning', to_jsonb(old));
  end if;
  return coalesce(new, old);
end $$;


