CREATE TABLE public.revenue_os_durable_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    queue_name text NOT NULL,
    job_type text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    scheduled_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    fencing_token bigint DEFAULT 0 NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_hash text NOT NULL,
    idempotency_key text NOT NULL,
    trace_id uuid DEFAULT gen_random_uuid() NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: revenue_os_claim_durable_jobs(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_os_claim_durable_jobs(p_tenant_id uuid, p_queue text, p_worker text, p_limit integer, p_lease_seconds integer) RETURNS SETOF public.revenue_os_durable_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 RETURN QUERY
 WITH candidates AS (
  SELECT id FROM public.revenue_os_durable_jobs WHERE tenant_id=p_tenant_id AND queue_name=p_queue AND status IN ('queued','retry_scheduled') AND scheduled_at<=now() AND (lease_expires_at IS NULL OR lease_expires_at<=now()) AND attempts<max_attempts ORDER BY priority ASC,scheduled_at ASC FOR UPDATE SKIP LOCKED LIMIT greatest(1,least(p_limit,100))
 ), updated AS (
  UPDATE public.revenue_os_durable_jobs j SET status='leased',lease_owner=p_worker,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),fencing_token=fencing_token+1,attempts=attempts+1,updated_at=now() FROM candidates c WHERE j.id=c.id RETURNING j.*
 ) SELECT * FROM updated;
END $$;


