--
-- Name: revenue_os_enqueue_execution_action(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_os_enqueue_execution_action(p_action_id uuid, p_tenant_id text, p_idempotency_key text, p_available_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE outbox_id uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.revenue_os_execution_actions WHERE id=p_action_id AND tenant_id=p_tenant_id) THEN RAISE EXCEPTION 'Execution action not found'; END IF;
 INSERT INTO public.revenue_os_execution_idempotency(tenant_id,idempotency_key,scope,action_id,status) VALUES(p_tenant_id,p_idempotency_key,'execution_outbox',p_action_id,'reserved') ON CONFLICT(tenant_id,scope,idempotency_key) DO NOTHING;
 INSERT INTO public.revenue_os_execution_outbox(tenant_id,action_id,idempotency_key,status,available_at) VALUES(p_tenant_id,p_action_id,p_idempotency_key,'pending',p_available_at)
 ON CONFLICT(tenant_id,idempotency_key) DO UPDATE SET available_at=LEAST(public.revenue_os_execution_outbox.available_at,excluded.available_at),updated_at=now() RETURNING id INTO outbox_id;
 UPDATE public.revenue_os_execution_actions SET status='queued',updated_at=now() WHERE id=p_action_id AND tenant_id=p_tenant_id AND status IN ('validated','approved','retry_scheduled','queued');
 RETURN outbox_id;
END $$;


--
-- Name: revenue_os_lease_execution_outbox(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_os_lease_execution_outbox(p_worker_id text, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 90) RETURNS TABLE(id uuid, tenant_id text, action_id uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 RETURN QUERY
 WITH candidates AS (
   SELECT o.id FROM public.revenue_os_execution_outbox o
   WHERE o.status IN ('pending','failed') AND o.available_at<=now() AND (o.lease_expires_at IS NULL OR o.lease_expires_at<now())
   ORDER BY o.available_at,o.created_at FOR UPDATE SKIP LOCKED LIMIT GREATEST(1,LEAST(p_limit,100))
 ), leased AS (
   UPDATE public.revenue_os_execution_outbox o SET status='leased',lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),attempt_count=o.attempt_count+1,updated_at=now()
   FROM candidates c WHERE o.id=c.id RETURNING o.id,o.tenant_id,o.action_id,o.attempt_count
 ) SELECT leased.id,leased.tenant_id,leased.action_id,leased.attempt_count FROM leased;
END $$;


--
-- Name: revenue_os_live_action_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_os_live_action_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE adapter record;
BEGIN
  NEW.execution_mode := 'live';
  NEW.approval_required := false;
  NEW.approval_decision_id := null;

  NEW.external_action :=
    NEW.action_type IN (
      'send_email',
      'email.send',
      'send_whatsapp',
      'whatsapp.send',
      'create_calendar_event',
      'calendar.create',
      'send_proposal',
      'proposal.send',
      'send_payment_followup',
      'payment.followup',
      'campaign.launch',
      'campaign.send',
      'external_webhook'
    )
    OR NEW.external_action = true;

  NEW.payload_hash := encode(digest(NEW.payload::text, 'sha256'), 'hex');

  IF
    NEW.confirmed_payload_hash IS NOT NULL
    AND NEW.confirmed_payload_hash <> NEW.payload_hash
  THEN
    RAISE EXCEPTION 'EXECUTION_PAYLOAD_CHANGED';
  END IF;

  IF
    NEW.external_action
    AND NEW.status IN ('queued', 'leased', 'executing', 'succeeded')
  THEN
    SELECT *
    INTO adapter
    FROM public.revenue_os_adapter_configs
    WHERE tenant_id = NEW.tenant_id
      AND adapter_code = NEW.adapter_code;

    IF adapter IS NOT NULL AND adapter.enabled IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'CHANNEL_OR_ADAPTER_DISABLED:%', NEW.adapter_code;
    END IF;
  END IF;

  RETURN NEW;
END $$;


