--
-- Name: revenue_proposal_reference_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.revenue_proposal_reference_seq
    START WITH 1001
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: revenue_proposals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.revenue_proposals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text DEFAULT ((('AC-PROP-'::text || to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text)) || '-'::text) || lpad((nextval('public.revenue_proposal_reference_seq'::regclass))::text, 6, '0'::text)) NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    proposal_type text DEFAULT 'b2b'::text NOT NULL,
    context_type text DEFAULT 'prospect'::text NOT NULL,
    prospect_id text,
    account_id uuid,
    contact_id uuid,
    opportunity_id uuid,
    meeting_outcome_id uuid,
    partnership_id text,
    b2c_case_id text,
    owner text DEFAULT 'BD Officer'::text NOT NULL,
    currency text DEFAULT 'MAD'::text NOT NULL,
    gross_value numeric(18,2) DEFAULT 0 NOT NULL,
    discount_value numeric(18,2) DEFAULT 0 NOT NULL,
    discount_percent numeric(9,4) DEFAULT 0 NOT NULL,
    net_value numeric(18,2) DEFAULT 0 NOT NULL,
    estimated_cost numeric(18,2) DEFAULT 0 NOT NULL,
    gross_margin numeric(18,2) DEFAULT 0 NOT NULL,
    margin_percent numeric(9,4) DEFAULT 0 NOT NULL,
    minimum_margin_percent numeric(9,4) DEFAULT 25 NOT NULL,
    approval_status text DEFAULT 'not_requested'::text NOT NULL,
    recipient_status text DEFAULT 'not_prepared'::text NOT NULL,
    negotiation_status text DEFAULT 'not_started'::text NOT NULL,
    commercial_objective text,
    client_need text,
    next_action text,
    validity_until date,
    accepted_at timestamp with time zone,
    rejected_at timestamp with time zone,
    active_version_id uuid,
    active_pricing_scenario_id uuid,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT revenue_proposals_check CHECK (((gross_value >= (0)::numeric) AND (discount_value >= (0)::numeric) AND (net_value >= (0)::numeric) AND (estimated_cost >= (0)::numeric))),
    CONSTRAINT revenue_proposals_check1 CHECK ((discount_value <= gross_value)),
    CONSTRAINT revenue_proposals_context_type_check CHECK ((context_type = ANY (ARRAY['prospect'::text, 'partnership'::text, 'b2c'::text]))),
    CONSTRAINT revenue_proposals_margin_percent_check CHECK (((margin_percent >= ('-10000'::integer)::numeric) AND (margin_percent <= (10000)::numeric))),
    CONSTRAINT revenue_proposals_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'internal_preparation'::text, 'pricing_review'::text, 'approval_required'::text, 'approved'::text, 'ready_to_send'::text, 'sent'::text, 'customer_review'::text, 'revision_requested'::text, 'negotiation'::text, 'accepted'::text, 'rejected'::text, 'expired'::text, 'withdrawn'::text, 'superseded'::text, 'contract_ready'::text, 'archived'::text])))
);


--
-- Name: revenue_recalculate_proposal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_recalculate_proposal(p_proposal_id uuid) RETURNS public.revenue_proposals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.revenue_proposals; g numeric:=0; d numeric:=0; n numeric:=0; c numeric:=0; m numeric:=0; mp numeric:=0;
begin
  select coalesce(sum(gross_value),0),coalesce(sum(discount_value),0),coalesce(sum(net_value),0),coalesce(sum(estimated_cost),0) into g,d,n,c from public.revenue_proposal_line_items where proposal_id=p_proposal_id and proposal_version_id is null;
  m:=n-c; mp:=case when n>0 then (m/n)*100 else 0 end;
  update public.revenue_proposals set gross_value=g,discount_value=d,discount_percent=case when g>0 then (d/g)*100 else 0 end,net_value=n,estimated_cost=c,gross_margin=m,margin_percent=mp,last_activity_at=now(),version=version+1 where id=p_proposal_id returning * into v;
  return v;
end$$;


--
-- Name: revenue_record_campaign_provider_event(uuid, text, text, text, timestamp with time zone, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_record_campaign_provider_event(p_communication_event_id uuid, p_event_type text, p_provider text DEFAULT 'manual'::text, p_provider_event_id text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_details jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare comm record;attempt record;delivery record;v_time timestamptz:=coalesce(p_occurred_at,now());v_terminal boolean;v_contacted boolean;
begin
  select * into comm from public.revenue_communication_events where id=p_communication_event_id for update;
  if not found then raise exception 'Communication event not found.'; end if;
  if nullif(p_provider_event_id,'') is not null then
    select d.* into delivery from public.revenue_communication_delivery_events d where d.provider=p_provider and d.provider_event_id=p_provider_event_id limit 1;
    if found then return jsonb_build_object('deliveryEventId',delivery.id,'communicationEventId',comm.id,'status',delivery.event_type,'idempotentReplay',true); end if;
  end if;
  insert into public.revenue_communication_delivery_events(communication_event_id,event_type,provider,provider_event_id,occurred_at,details,metadata)
  values(comm.id,p_event_type,coalesce(nullif(p_provider,''),'manual'),coalesce(p_provider_event_id,''),v_time,coalesce(p_details,'{}'::jsonb),jsonb_build_object('campaign_id',comm.campaign_id,'actor_id',p_actor_id)) returning * into delivery;
  update public.revenue_communication_events set status=p_event_type,provider=coalesce(nullif(p_provider,''),provider),provider_message_id=coalesce(nullif(p_provider_event_id,''),provider_message_id),updated_at=now() where id=comm.id;
  select * into attempt from public.revenue_campaign_dispatch_attempts where communication_event_id=comm.id order by created_at desc limit 1 for update;
  v_contacted:=p_event_type in ('provider_accepted','sent','delivered');
  v_terminal:=p_event_type in ('delivered','hard_bounce','provider_rejected','failed');
  if found then
    update public.revenue_campaign_dispatch_attempts set status=p_event_type,provider_message_id=coalesce(nullif(p_provider_event_id,''),provider_message_id),completed_at=case when v_terminal then v_time else completed_at end,metadata=metadata||jsonb_build_object('lastProviderEvent',p_event_type,'lastProviderEventAt',v_time) where id=attempt.id;
    update public.revenue_campaign_step_executions set status=p_event_type,completed_at=case when v_terminal then v_time else completed_at end,last_error=case when p_event_type in ('hard_bounce','provider_rejected','failed') then coalesce(p_details->>'message',p_event_type) else last_error end,updated_by=p_actor_id,updated_at=now() where id=attempt.step_execution_id;
  end if;
  if v_contacted and comm.campaign_recipient_id is not null then update public.revenue_campaign_recipients set status='contacted',first_contact_at=coalesce(first_contact_at,v_time),last_action_at=v_time,updated_by=p_actor_id,updated_at=now() where id=comm.campaign_recipient_id; end if;
  if p_event_type='hard_bounce' and comm.campaign_recipient_id is not null then
    update public.revenue_campaign_recipients set status='invalid',last_action_at=v_time,updated_by=p_actor_id,updated_at=now() where id=comm.campaign_recipient_id;
    update public.revenue_campaign_enrollments set status='terminated',paused_at=v_time,exit_reason='hard_bounce',updated_by=p_actor_id,updated_at=now() where campaign_recipient_id=comm.campaign_recipient_id and status in ('active','paused');
    update public.revenue_campaign_step_executions set status='cancelled',last_error='hard_bounce',updated_by=p_actor_id,updated_at=now() where campaign_recipient_id=comm.campaign_recipient_id and status in ('scheduled','due','prepared','manual_review');
    insert into public.revenue_campaign_suppressions(campaign_id,prospect_id,contact_id,contact_value_normalized,channel,scope,reason,status,source_event_id,created_by)
    select null,r.prospect_id,r.contact_id,r.contact_value_normalized,coalesce(comm.channel,'email'),'channel','hard_bounce','active',comm.id,p_actor_id
    from public.revenue_campaign_recipients r where r.id=comm.campaign_recipient_id
      and not exists(select 1 from public.revenue_campaign_suppressions q where q.status='active' and q.source_event_id=comm.id);
  end if;
  return jsonb_build_object('deliveryEventId',delivery.id,'communicationEventId',comm.id,'status',p_event_type,'idempotentReplay',false);
end $$;


--
-- Name: revenue_reverse_revenue_realization(uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_reverse_revenue_realization(p_contract_id uuid, p_realization_id uuid, p_input jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c public.revenue_contracts;
  original public.revenue_realization_events;
  reversal public.revenue_realization_events;
  reversal_amount numeric;
  new_total numeric;
  finance_ref text;
  evidence_ref text;
begin
  select * into c from public.revenue_contracts where id=p_contract_id for update;
  if not found then raise exception 'Contrat introuvable'; end if;

  select * into original
  from public.revenue_realization_events
  where id=p_realization_id and contract_id=c.id and status in ('realized','partially_realized')
  for update;
  if not found then raise exception 'Événement de réalisation autoritatif introuvable'; end if;

  select * into reversal
  from public.revenue_realization_events
  where reversal_of_id=original.id
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object(
      'contract_id',c.id,
      'realization_id',reversal.id,
      'reversal_of_id',original.id,
      'amount',reversal.amount,
      'cumulative_realized',c.realized_value,
      'idempotent_replay',true
    );
  end if;

  finance_ref:=nullif(trim(p_input->>'financeReference'),'');
  evidence_ref:=nullif(trim(p_input->>'evidenceReference'),'');
  if finance_ref is null or evidence_ref is null then
    raise exception 'Référence Finance et preuve de contrepassation sont requises';
  end if;

  reversal_amount:=abs(original.amount);
  new_total:=greatest(0,c.realized_value-reversal_amount);

  insert into public.revenue_realization_events(
    contract_id,payment_confirmation_id,reversal_of_id,amount,currency,status,
    finance_reference,evidence_reference,realization_rule,realized_at,realized_by
  ) values(
    c.id,original.payment_confirmation_id,original.id,-reversal_amount,c.currency,'reversed',
    finance_ref,evidence_ref,
    coalesce(nullif(p_input->>'reason',''),'Contrepassation autorisée de réalisation'),
    coalesce(nullif(p_input->>'reversedAt','')::timestamptz,now()),p_actor_id
  ) returning * into reversal;

  update public.revenue_contracts
  set realized_value=new_total,
      realization_status=case when new_total=0 then 'eligible' when new_total>=contract_value then 'realized' else 'partially_realized' end,
      last_activity_at=now(),
      updated_by=p_actor_id
  where id=c.id
  returning * into c;

  return jsonb_build_object(
    'contract_id',c.id,
    'realization_id',reversal.id,
    'reversal_of_id',original.id,
    'amount',reversal.amount,
    'cumulative_realized',c.realized_value,
    'realization_status',c.realization_status,
    'idempotent_replay',false
  );
end$$;


--
-- Name: revenue_task_capture_status_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_task_capture_status_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status then
    insert into public.revenue_task_status_history(task_id,from_status,to_status,reason,changed_by,metadata)
    values(new.id,old.status,new.status,'Captured by database trigger',new.updated_by,jsonb_build_object('source','trigger'));
  end if;
  return new;
end $$;


--
-- Name: revenue_task_completion_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_task_completion_metrics() RETURNS TABLE(total_tasks integer, open_tasks integer, completed_tasks integer, overdue_tasks integer)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  select
    count(*)::integer as total_tasks,
    count(*) filter (where status = 'open')::integer as open_tasks,
    count(*) filter (where status = 'done')::integer as completed_tasks,
    count(*) filter (where status = 'open' and due_date is not null and due_date < current_date)::integer as overdue_tasks
  from public.revenue_tasks;
$$;


