  return new;
end $$;


--
-- Name: revenue_task_quick_action(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_task_quick_action(p_task_id uuid, p_action text, p_actor text DEFAULT 'AngelCare'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
declare v_task public.revenue_tasks%rowtype;
begin
  select * into v_task from public.revenue_tasks where id = p_task_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'Task not found'); end if;
  if p_action in ('complete','done') then
    update public.revenue_tasks set status='done', status_label='Completed', completed_at=now(), updated_at=now() where id=p_task_id;
  elsif p_action in ('reopen','open') then
    update public.revenue_tasks set status='open', status_label='Open', completed_at=null, updated_at=now() where id=p_task_id;
  elsif p_action in ('archive','delete') then
    update public.revenue_tasks set status='archived', archived_at=now(), updated_at=now() where id=p_task_id;
  elsif p_action in ('block','blocked') then
    update public.revenue_tasks set status='blocked', priority='critical', updated_at=now() where id=p_task_id;
  else
    update public.revenue_tasks set updated_at=now() where id=p_task_id;
  end if;
  return jsonb_build_object('ok', true, 'taskId', p_task_id, 'action', p_action);
end $$;


--
-- Name: revenue_touch_parent_prospect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_touch_parent_prospect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.prospect_id is not null then
    update public.revenue_prospects set last_activity_at = now(), updated_at = now() where id::text = new.prospect_id::text;
  elsif new.entity_id is not null then
    update public.revenue_prospects set last_activity_at = now(), updated_at = now() where id::text = new.entity_id::text;
  end if;
  return new;
end $$;


