--
-- Name: revenue_v10_after_deal_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_v10_after_deal_activity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  insert into revenue_v10_activity_timeline(deal_id, activity_type, title, description, old_value, new_value)
  values(new.id, case when tg_op='INSERT' then 'deal_created' else 'deal_update' end, case when tg_op='INSERT' then 'Deal created' else 'Deal updated' end, 'TRUE V10 captured deal lifecycle change', coalesce(old.stage,''), coalesce(new.stage,''));
  return new;
end; $$;


--
-- Name: revenue_v10_before_deal_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_v10_before_deal_score() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare s record;
begin
  select * into s from revenue_v10_compute_scores(new.next_action, new.next_action_due_at, new.last_activity_at, new.value, new.stage, new.status);
  new.risk_score := s.risk_score;
  new.pressure_score := s.pressure_score;
  new.ai_score := s.ai_score;
  new.updated_at := now();
  return new;
end; $$;


--
-- Name: revenue_v10_compute_scores(text, timestamp with time zone, timestamp with time zone, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_v10_compute_scores(p_next_action text, p_next_action_due_at timestamp with time zone, p_last_activity_at timestamp with time zone, p_value numeric, p_stage text, p_status text, OUT risk_score integer, OUT pressure_score integer, OUT ai_score integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
declare risk int := 0; pressure int := 0; ai int := 50;
begin
  if p_next_action is null or length(trim(coalesce(p_next_action,''))) < 3 then risk := risk + 30; end if;
  if p_next_action_due_at is null then risk := risk + 25; end if;
  if p_next_action_due_at is not null and p_next_action_due_at < now() then risk := risk + 30; pressure := pressure + 35; end if;
  if p_last_activity_at is null or p_last_activity_at < now() - interval '48 hours' then risk := risk + 20; pressure := pressure + 20; end if;
  if coalesce(p_value,0) > 20000 then ai := ai + 15; pressure := pressure + 10; end if;
  if p_stage in ('proposal','negotiation','closing') then ai := ai + 15; pressure := pressure + 15; end if;
  if p_status = 'won' then risk := 0; pressure := 0; ai := 100; end if;
  risk_score := least(risk,100);
  pressure_score := least(pressure,100);
  ai_score := least(greatest(ai - risk/2,0),100);
end; $$;


