    AS $$
begin new.updated_at = now(); return new; end; $$;


--
-- Name: saas_factory_audit_events_compat_fill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_factory_audit_events_compat_fill() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.event := coalesce(new.event, new.event_key, new.action, new.message, 'saas_factory.audit.event');
  new.event_key := coalesce(new.event_key, new.event, new.action, 'saas_factory.audit.event');
  new.action := coalesce(new.action, new.event_key, new.event, 'audit_event');
  new.module_key := coalesce(new.module_key, 'saas_factory_command');
  new.severity := coalesce(new.severity, 'info');
  new.status := coalesce(new.status, 'success');
  new.message := coalesce(new.message, new.event_key, new.event, new.action, 'SaaS Factory audit event');
  new.actor := coalesce(new.actor, 'system');
  new.metadata_json := coalesce(new.metadata_json, '{}'::jsonb);
  new.before_json := coalesce(new.before_json, '{}'::jsonb);
  new.after_json := coalesce(new.after_json, '{}'::jsonb);
  new.created_at := coalesce(new.created_at, now());
  return new;
end;
$$;


--
-- Name: saas_factory_introspect_database(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_factory_introspect_database() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'information_schema', 'storage'
    AS $$
declare result jsonb;
begin
  select jsonb_build_object(
    'ok', true,
    'source', 'live_supabase_database',
    'generated_at', now(),
    'tables', coalesce((select jsonb_agg(row_to_json(t)) from (select n.nspname as schema_name,c.relname as table_name,pg_get_userbyid(c.relowner) as owner,c.relrowsecurity as rls_enabled,c.relforcerowsecurity as force_rls,obj_description(c.oid) as description,pg_total_relation_size(c.oid) as total_bytes,pg_relation_size(c.oid) as table_bytes,c.reltuples::bigint as estimated_rows from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p') and n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg_toast%' order by n.nspname,c.relname) t),'[]'::jsonb),
    'columns', coalesce((select jsonb_agg(row_to_json(c)) from (select table_schema as schema_name,table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema not in ('pg_catalog','information_schema') order by table_schema,table_name,ordinal_position) c),'[]'::jsonb),
    'policies', coalesce((select jsonb_agg(row_to_json(p)) from (select schemaname as schema_name,tablename as table_name,policyname as policy_name,permissive,roles,cmd,qual,with_check from pg_policies order by schemaname,tablename,policyname) p),'[]'::jsonb),
    'indexes', coalesce((select jsonb_agg(row_to_json(i)) from (select schemaname as schema_name,tablename as table_name,indexname as index_name,indexdef from pg_indexes where schemaname not in ('pg_catalog','information_schema') order by schemaname,tablename,indexname) i),'[]'::jsonb),
    'functions', coalesce((select jsonb_agg(row_to_json(f)) from (select n.nspname as schema_name,p.proname as function_name,pg_get_userbyid(p.proowner) as owner,l.lanname as language,p.prosecdef as security_definer from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname not in ('pg_catalog','information_schema') order by n.nspname,p.proname) f),'[]'::jsonb),
    'extensions', coalesce((select jsonb_agg(row_to_json(e)) from (select extname as name,extversion as version,n.nspname as schema_name from pg_extension ext left join pg_namespace n on n.oid=ext.extnamespace order by extname) e),'[]'::jsonb),
    'storage_buckets', coalesce((select jsonb_agg(row_to_json(b)) from (select id,name,owner,public,file_size_limit,allowed_mime_types,created_at,updated_at from storage.buckets order by name) b),'[]'::jsonb),
    'publications', coalesce((select jsonb_agg(row_to_json(pub)) from (select p.pubname as publication_name,n.nspname as schema_name,c.relname as table_name from pg_publication p left join pg_publication_rel pr on pr.prpubid=p.oid left join pg_class c on c.oid=pr.prrelid left join pg_namespace n on n.oid=c.relnamespace order by p.pubname,n.nspname,c.relname) pub),'[]'::jsonb)
  ) into result;
  return result;
end;
$$;


