--
-- Name: saas_factory_tenants_compat_fill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_factory_tenants_compat_fill() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.key := coalesce(new.key, new.slug, lower(regexp_replace(coalesce(new.label, new.name, 'tenant'), '[^a-zA-Z0-9]+', '_', 'g')));
  new.label := coalesce(new.label, new.name, new.key, 'Workspace');
  new.name := coalesce(new.name, new.label, new.key, 'Workspace');
  new.slug := coalesce(new.slug, new.key, lower(regexp_replace(coalesce(new.label, new.name, 'tenant'), '[^a-zA-Z0-9]+', '-', 'g')));
  new.status := coalesce(new.status, 'active');
  new.plan := coalesce(new.plan, 'internal_enterprise');
  new.enabled_modules := coalesce(new.enabled_modules, array[]::text[]);
  new.metadata_json := coalesce(new.metadata_json, '{}'::jsonb);
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: sales_terminal_guard_order_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_terminal_guard_order_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.status in ('cancelled', 'archived') and new.status is distinct from old.status then
    raise exception 'Cannot modify terminal order with status %', old.status;
  end if;
  if new.status = 'cancelled' and coalesce(new.cancellation_reason, '') = '' then
    new.cancellation_reason := 'Cancelled from Sales Terminal';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


