--
-- Name: social_command_mz7_compliance_anonymize_contact(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_command_mz7_compliance_anonymize_contact(p_contact_id uuid, p_actor_user_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_identity_ids uuid[]; v_reason text:=coalesce(nullif(trim(p_reason),''),'Compliance erasure/anonymization');
begin
 if p_contact_id is null then raise exception 'CONTACT_ID_REQUIRED'; end if;
 select coalesce(array_agg(id),'{}'::uuid[]) into v_identity_ids from public.social_command_relationship_identities where relationship_contact_id=p_contact_id;
 update public.social_command_relationship_contacts set display_name='Anonymized relationship',relationship_state='anonymized',tags='{}',metadata=jsonb_build_object('compliance_anonymized',true),updated_at=now() where id=p_contact_id;
 update public.social_command_relationship_identities set provider_user_id='anonymized:'||id::text,username=null,display_name='Anonymized identity',profile_picture_url=null,link_state='anonymized',evidence=jsonb_build_object('compliance_anonymized',true),updated_at=now() where relationship_contact_id=p_contact_id;
 update public.social_command_contact_profiles set provider_scoped_user_id='anonymized:'||id::text,username=null,display_name='Anonymized identity',profile_picture_url=null,follower_count=null,is_verified_user=null,is_user_follow_business=null,is_business_follow_user=null,last_error=null,refresh_state='provider_limited',updated_at=now() where relationship_contact_id=p_contact_id;
 update public.social_command_messages m set text='[anonymized by compliance action]',sender_id=null,recipient_id=null,sender_username=null,attachments='[]'::jsonb,provider_payload=jsonb_build_object('compliance_anonymized',true),updated_at=now() where m.conversation_id in(select id from public.social_command_conversations where relationship_contact_id=p_contact_id);
 update public.social_command_comments set commenter_id=null,commenter_username=null,text='[anonymized by compliance action]',metadata=jsonb_build_object('compliance_anonymized',true),updated_at=now() where relationship_contact_id=p_contact_id;
 update public.social_command_mentions set actor_id=null,actor_username=null,text='[anonymized by compliance action]',metadata=jsonb_build_object('compliance_anonymized',true),updated_at=now() where relationship_contact_id=p_contact_id;
 update public.social_command_conversations set participant_id='anonymized:'||id::text,participant_username=null,participant_name='Anonymized contact',participant_profile_picture_url=null,last_message_preview='[anonymized]',metadata=jsonb_build_object('compliance_anonymized',true),updated_at=now() where relationship_contact_id=p_contact_id;
 update public.social_command_journey_events set title=case when event_kind='relationship.compliance_anonymized' then title else coalesce(title,'Historical event') end,summary=null,provider_reference=null,payload=jsonb_build_object('compliance_anonymized',true) where relationship_contact_id=p_contact_id;
 insert into public.social_command_journey_events(id,relationship_contact_id,entity_type,entity_id,event_kind,source_kind,title,summary,actor_user_id,occurred_at,payload,created_at) values(gen_random_uuid(),p_contact_id,'contact',p_contact_id::text,'relationship.compliance_anonymized','operator','Compliance anonymization completed',v_reason,p_actor_user_id,now(),jsonb_build_object('reason',v_reason),now());
 return jsonb_build_object('ok',true,'contactId',p_contact_id,'anonymizedAt',now());
end $$;


--
-- Name: social_command_refresh_media_usage_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_command_refresh_media_usage_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op='INSERT' then
    update public.social_command_media_assets set usage_count=usage_count+1 where id=new.asset_id;
    return new;
  elsif tg_op='DELETE' then
    update public.social_command_media_assets set usage_count=greatest(usage_count-1,0) where id=old.asset_id;
    return old;
  end if;
  return null;
end $$;


--
-- Name: sync_market_os_ambassador_user_access(uuid, uuid, text, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_market_os_ambassador_user_access(p_app_user_id uuid, p_assigned_by uuid, p_access_mode text DEFAULT 'full'::text, p_custom_permissions jsonb DEFAULT '[]'::jsonb, p_tenant_id text DEFAULT NULL::text, p_organization_id text DEFAULT NULL::text, p_global_permissions jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user public.app_users%rowtype;
  v_membership public.market_os_ambassador_module_memberships%rowtype;

  v_tenant text;
  v_organization text;

  v_mode text :=
    coalesce(
      nullif(p_access_mode, ''),
      'full'
    );

  v_custom_permissions jsonb :=
    coalesce(
      p_custom_permissions,
      '[]'::jsonb
    );

  v_global_permissions text[];
  v_next_version bigint;
  v_role_key text;
  v_actor_role_tid tid;
begin
  if v_mode not in (
    'full',
    'view_only',
    'custom',
    'none'
  ) then
    raise exception
      'Invalid Ambassador access mode: %',
      v_mode
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_custom_permissions) <> 'array' then
    raise exception
      'Custom Ambassador permissions must be a JSON array'
      using errcode = '22023';
  end if;

  if p_global_permissions is not null
     and jsonb_typeof(p_global_permissions) <> 'array' then
    raise exception
      'Global company-user permissions must be a JSON array'
      using errcode = '22023';
  end if;

  select *
  into v_user
  from public.app_users
  where id = p_app_user_id
  for update;

  if not found then
    raise exception
      'Company user % was not found',
      p_app_user_id
      using errcode = '23503';
  end if;

  select
    coalesce(
      p_tenant_id,
      v_user.tenant_id
    ),
    coalesce(
      p_organization_id,
      v_user.organization_id
    )
  into
    v_tenant,
    v_organization;

  if v_tenant is null
     or v_organization is null then
    select
      r.tenant_id,
      r.organization_id
    into
      v_tenant,
      v_organization
    from public.market_os_ambassador_actor_roles r
    where r.app_user_id = p_app_user_id
      and r.status = 'active'
    order by r.updated_at desc
    limit 1;
  end if;

  if v_tenant is null
     or v_organization is null then
    select
      a.tenant_id::text,
      coalesce(
        a.organization_id,
        a.school_id
      )::text
    into
      v_tenant,
      v_organization
    from public.angelcare360_operator_tenant_access_accounts a
    where a.app_user_id = p_app_user_id
      and a.status = 'active'
    order by a.updated_at desc
    limit 1;
  end if;

  if v_tenant is null
     or v_organization is null then
    raise exception
      'Ambassador tenant and organization scope are required for user %',
      p_app_user_id
      using errcode = '22023';
  end if;

  -- Serializes updates for the same user and scope.
  perform pg_advisory_xact_lock(
    hashtext(
      p_app_user_id::text
      || '|'
      || v_tenant
      || '|'
      || v_organization
      || '|market_os_ambassadors'
    )
  );

  if p_global_permissions is null then
    v_global_permissions :=
      coalesce(
        v_user.permissions,
        array[]::text[]
      );
  else
    select coalesce(
      array_agg(
        permission_value
        order by permission_order
      ),
      array[]::text[]
    )
    into v_global_permissions
    from jsonb_array_elements_text(
      p_global_permissions
    ) with ordinality as permission_rows(
      permission_value,
      permission_order
    );
  end if;

  select
    coalesce(
      max(grant_version),
      0
    ) + 1
  into v_next_version
  from public.market_os_ambassador_module_memberships
  where app_user_id = p_app_user_id
    and tenant_id = v_tenant
    and organization_id = v_organization
    and module_key = 'market_os_ambassadors';

  update public.app_users
  set
    permissions = v_global_permissions,
    tenant_id = v_tenant,
    organization_id = v_organization,
    updated_at = now()
  where id = p_app_user_id;

  insert into public.market_os_ambassador_module_memberships (
    app_user_id,
    tenant_id,
    organization_id,
    module_key,
    access_mode,
    active,
    grant_permissions,
    grant_version,
    assigned_by,
    assigned_at,
    updated_at
  )
  values (
    p_app_user_id,
    v_tenant,
    v_organization,
    'market_os_ambassadors',
    v_mode,
    v_mode <> 'none',
    case
      when v_mode = 'custom'
        then v_custom_permissions
      else '[]'::jsonb
    end,
    v_next_version,
    p_assigned_by,
    now(),
    now()
  )
  on conflict (
    app_user_id,
    tenant_id,
    organization_id,
    module_key
  )
  do update set
    access_mode = excluded.access_mode,
    active = excluded.active,
    grant_permissions = excluded.grant_permissions,
    grant_version = excluded.grant_version,
    assigned_by = excluded.assigned_by,
    updated_at = now();

  select *
  into v_membership
  from public.market_os_ambassador_module_memberships
  where app_user_id = p_app_user_id
    and tenant_id = v_tenant
    and organization_id = v_organization
    and module_key = 'market_os_ambassadors';

  v_role_key :=
    case v_mode
      when 'full'
        then 'AMBASSADOR_MODULE_ADMINISTRATOR'
      when 'view_only'
        then 'AMBASSADOR_MODULE_VIEWER'
      when 'custom'
        then 'AMBASSADOR_MODULE_CUSTOM'
      else null
    end;

  -- Revoke previous active native roles in this exact scope.
  update public.market_os_ambassador_actor_roles
  set
    status = 'revoked',
    updated_at = now()
  where app_user_id = p_app_user_id
    and tenant_id = v_tenant
    and organization_id = v_organization
    and status = 'active';

  -- No active native role must remain when module access is removed.
  if v_mode <> 'none' then
    v_actor_role_tid := null;

    -- Prefer reusing the same role row. Otherwise reuse the latest
    -- historical row for this user/scope.
    select r.ctid
    into v_actor_role_tid
    from public.market_os_ambassador_actor_roles r
    where r.app_user_id = p_app_user_id
      and r.tenant_id = v_tenant
      and r.organization_id = v_organization
    order by
      case
        when r.role_key = v_role_key
          then 0
        else 1
      end,
      r.updated_at desc
    limit 1
    for update;

    if v_actor_role_tid is not null then
      update public.market_os_ambassador_actor_roles
      set
        role_key = v_role_key,
        display_name = v_user.full_name,
        status = 'active',
        module_membership_id = v_membership.id,
        grant_version = v_next_version,
        updated_at = now()
      where ctid = v_actor_role_tid;
    else
      insert into public.market_os_ambassador_actor_roles (
        auth_user_id,
        app_user_id,
        tenant_id,
        organization_id,
        role_key,
        display_name,
        status,
        module_membership_id,
        grant_version
      )
      values (
        null,
        p_app_user_id,
        v_tenant,
        v_organization,
        v_role_key,
        v_user.full_name,
        'active',
        v_membership.id,
        v_next_version
      );
    end if;
  end if;

  insert into public.market_os_ambassador_audit_logs (
    tenant_id,
    organization_id,
    entity_type,
    entity_id,
    action,
    summary,
    actor_name,
    payload,
    metadata
  )
  values (
    nullif(v_tenant, '')::uuid,
    nullif(v_organization, '')::uuid,
    'module_membership',
    p_app_user_id,
    case
      when v_mode = 'none'
        then 'users_management_ambassadors_revoked'
      else 'users_management_ambassadors_synchronized'
    end,
    'Users Management and native Ambassador authorization synchronized',
    v_user.full_name,
    jsonb_build_object(
      'access_mode',
      v_mode,
      'grant_version',
      v_next_version,
      'module',
      'market_os_ambassadors',
      'assigned_by',
      p_assigned_by
    ),
    jsonb_build_object(
      'source',
      'users_management'
    )
  );

  return jsonb_build_object(
    'ok',
    true,
    'app_user_id',
    p_app_user_id,
    'tenant_id',
    v_tenant,
    'organization_id',
    v_organization,
    'access_mode',
    v_mode,
    'grant_version',
    v_next_version,
    'native_role_key',
    v_role_key
  );
end;
$$;


