    version_no integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    name text NOT NULL,
    promise text DEFAULT ''::text NOT NULL,
    target_segment text DEFAULT ''::text NOT NULL,
    ready_plan_id uuid,
    release_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    price_dh numeric(14,2) DEFAULT 0 NOT NULL,
    gross_margin_percent numeric(8,3) DEFAULT 0 NOT NULL,
    minimum_order integer DEFAULT 1 NOT NULL,
    snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by text,
    approved_by text,
    approved_at timestamp with time zone,
    approval_note text,
    published_at timestamp with time zone,
    suspension_reason text,
    effective_from date,
    effective_until date,
    supersedes_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    journey_scenario_id uuid,
    collection_ids text[] DEFAULT '{}'::text[] NOT NULL,
    collection_version_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    direct_collection_id text,
    direct_collection_version_id uuid,
    CONSTRAINT b2c_sellables_one_composition_source_v2_check CHECK ((((
CASE
    WHEN (scenario_id IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (journey_scenario_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (direct_collection_id IS NOT NULL) THEN 1
    ELSE 0
END) = 1))
);


