    tenant_key text DEFAULT 'angelcare-internal'::text NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    strategic_question text NOT NULL,
    purpose text NOT NULL,
    mode text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    product_domain text,
    collection_ids text[] DEFAULT '{}'::text[] NOT NULL,
    audience_profiles text[] DEFAULT '{}'::text[] NOT NULL,
    geographic_scope text[] DEFAULT '{}'::text[] NOT NULL,
    languages text[] DEFAULT ARRAY['fr'::text] NOT NULL,
    source_categories text[] DEFAULT '{}'::text[] NOT NULL,
    include_domains text[] DEFAULT '{}'::text[] NOT NULL,
    exclude_domains text[] DEFAULT '{}'::text[] NOT NULL,
    planned_queries text[] DEFAULT '{}'::text[] NOT NULL,
    search_depth text DEFAULT 'basic'::text NOT NULL,
    source_limit integer DEFAULT 8 NOT NULL,
    budget_credits integer DEFAULT 12 NOT NULL,
    used_credits numeric(12,3) DEFAULT 0 NOT NULL,
    source_count integer DEFAULT 0 NOT NULL,
    accepted_claim_count integer DEFAULT 0 NOT NULL,
    contradiction_count integer DEFAULT 0 NOT NULL,
    owner_name text DEFAULT 'Direction Produit'::text NOT NULL,
    reviewer_name text,
    deadline timestamp with time zone,
    approved_by text,
    approved_at timestamp with time zone,
    cancelled_by text,
    cancelled_at timestamp with time zone,
    cancellation_note text,
    failure_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT research_missions_accepted_claim_count_check CHECK ((accepted_claim_count >= 0)),
    CONSTRAINT research_missions_budget_credits_check CHECK (((budget_credits >= 1) AND (budget_credits <= 1000))),
    CONSTRAINT research_missions_contradiction_count_check CHECK ((contradiction_count >= 0)),
    CONSTRAINT research_missions_mode_check CHECK ((mode = ANY (ARRAY['rapid_scan'::text, 'deep_evidence'::text, 'known_source'::text, 'domain_investigation'::text]))),
    CONSTRAINT research_missions_purpose_check CHECK ((purpose = ANY (ARRAY['new_collection_opportunity'::text, 'product_concept_validation'::text, 'format_benchmark'::text, 'methodology_review'::text, 'age_suitability'::text, 'institutional_demand'::text, 'competitor_portfolio'::text, 'parent_pain_points'::text, 'specialist_use_case'::text, 'market_positioning'::text, 'cultural_adaptation'::text, 'content_gap'::text]))),
    CONSTRAINT research_missions_search_depth_check CHECK ((search_depth = ANY (ARRAY['basic'::text, 'advanced'::text]))),
    CONSTRAINT research_missions_source_count_check CHECK ((source_count >= 0)),
    CONSTRAINT research_missions_source_limit_check CHECK (((source_limit >= 1) AND (source_limit <= 20))),
    CONSTRAINT research_missions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'queued'::text, 'acquiring'::text, 'evidence_review'::text, 'ready_for_synthesis'::text, 'synthesising'::text, 'human_review'::text, 'completed'::text, 'cancelled'::text, 'failed'::text, 'archived'::text]))),
    CONSTRAINT research_missions_used_credits_check CHECK ((used_credits >= (0)::numeric))
);


