--
-- Name: ac360_policy_safety_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ac360_policy_safety_dashboard AS
 SELECT id AS org_id,
    display_name AS organization_name,
    COALESCE(( SELECT count(*) AS count
           FROM public.ac360_policy_events pe
          WHERE ((pe.org_id = o.id) AND (pe.status = 'open'::text))), (0)::bigint) AS open_policy_events,
    COALESCE(( SELECT count(*) AS count
           FROM public.ac360_policy_override_requests pr
          WHERE ((pr.org_id = o.id) AND (pr.status = 'requested'::text))), (0)::bigint) AS pending_overrides,
    COALESCE(( SELECT count(*) AS count
           FROM public.ac360_guard_decisions gd
          WHERE ((gd.org_id = o.id) AND (gd.allowed = false) AND (gd.created_at >= (now() - '7 days'::interval)))), (0)::bigint) AS blocked_last_7_days,
    COALESCE(( SELECT count(*) AS count
           FROM public.ac360_restrictions r
          WHERE ((r.org_id = o.id) AND (r.status = 'active'::text))), (0)::bigint) AS active_restrictions,
    COALESCE(( SELECT count(*) AS count
           FROM public.ac360_route_coverage_audits rc
          WHERE ((rc.coverage_status = ANY (ARRAY['expected'::text, 'missing'::text])) AND (rc.enforcement_mode = 'strict'::text))), (0)::bigint) AS strict_routes_to_review
   FROM public.ac360_organizations o;


