    CONSTRAINT ac_capital_radar_opportunities_status_check CHECK ((status = ANY (ARRAY['detected'::text, 'watchlist'::text, 'source-review'::text, 'ready-for-qualification'::text, 'duplicate'::text, 'rejected'::text])))
);


--
-- Name: ac_capital_ic10_lifecycle_trace; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ac_capital_ic10_lifecycle_trace AS
 SELECT o.id AS opportunity_id,
    o.title AS opportunity_title,
    o.status AS opportunity_status,
    q.id AS qualification_id,
    q.status AS qualification_status,
    q.decision_label,
    c.id AS case_id,
    c.status AS case_status,
    c.founder_approval_status,
    p.id AS pipeline_id,
    p.stage AS pipeline_stage,
    p.status AS pipeline_status,
    p.owner AS pipeline_owner,
    p.next_action,
    p.deadline,
    GREATEST(COALESCE(o.updated_at, o.created_at), COALESCE(q.updated_at, q.created_at), COALESCE(c.updated_at, c.created_at), COALESCE(p.updated_at, p.created_at)) AS lifecycle_updated_at
   FROM (((public.ac_capital_radar_opportunities o
     LEFT JOIN public.ac_capital_qualification_dossiers q ON (((q.radar_opportunity_id)::text = (o.id)::text)))
     LEFT JOIN public.ac_capital_cases c ON (((c.qualification_dossier_id)::text = (q.id)::text)))
     LEFT JOIN public.ac_capital_pipeline_records p ON ((p.case_id = (c.id)::text)));


