    school_id uuid NOT NULL,
    attendance_session_id uuid NOT NULL,
    student_id uuid NOT NULL,
    attendance_status text NOT NULL,
    check_in_at timestamp with time zone,
    check_out_at timestamp with time zone,
    minutes_late integer,
    marked_by uuid,
    mark_source text DEFAULT 'manual'::text NOT NULL,
    note text,
    justification_required boolean DEFAULT false NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_by uuid,
    updated_by uuid,
    metadata_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ac360_attendance_status_reality_ck CHECK ((attendance_status = ANY (ARRAY['present'::text, 'absent'::text, 'late'::text, 'excused'::text, 'authorized_absence'::text, 'medical_absence'::text, 'remote'::text, 'left_early'::text, 'unmarked'::text]))),
    CONSTRAINT angelcare360_attendance_records_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'archived'::text])))
);


