--
-- Name: angelcare_marketplace_activation_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_activation_readiness_v WITH (security_invoker='true') AS
 WITH item_readiness AS (
         SELECT i.id,
            (EXISTS ( SELECT 1
                   FROM public.angelcare_marketplace_catalog_item_media m
                  WHERE ((m.catalog_item_id = i.id) AND (m.status = 'active'::text)))) AS has_media,
            (EXISTS ( SELECT 1
                   FROM public.angelcare_marketplace_catalog_item_categories c
                  WHERE (c.catalog_item_id = i.id))) AS has_category,
            ((i.price_mode = 'quote_only'::text) OR (i.price_amount IS NOT NULL) OR (EXISTS ( SELECT 1
                   FROM public.angelcare_marketplace_finance_price_rules p
                  WHERE ((p.catalog_item_id = i.id) AND (p.status = 'active'::text))))) AS has_price,
            ((i.availability_status = ANY (ARRAY['available'::text, 'configuration_required'::text])) OR (EXISTS ( SELECT 1
                   FROM public.angelcare_marketplace_catalog_availability a
                  WHERE ((a.catalog_item_id = i.id) AND (a.available = true))))) AS has_availability
           FROM public.angelcare_marketplace_catalog_items i
          WHERE (i.status = 'published'::text)
        )
 SELECT ( SELECT (count(*))::integer AS count
           FROM item_readiness) AS published_items,
    ( SELECT (count(*))::integer AS count
           FROM item_readiness
          WHERE item_readiness.has_media) AS items_with_media,
    ( SELECT (count(*))::integer AS count
           FROM item_readiness
          WHERE item_readiness.has_category) AS items_with_category,
    ( SELECT (count(*))::integer AS count
           FROM item_readiness
          WHERE item_readiness.has_price) AS items_with_price,
    ( SELECT (count(*))::integer AS count
           FROM item_readiness
          WHERE item_readiness.has_availability) AS items_with_availability,
    ( SELECT (count(*))::integer AS count
           FROM public.angelcare_marketplace_homepage_sections
          WHERE ((angelcare_marketplace_homepage_sections.status = ANY (ARRAY['active'::text, 'published'::text, 'scheduled'::text])) AND (angelcare_marketplace_homepage_sections.visible = true))) AS active_homepage_sections,
    ( SELECT (count(*))::integer AS count
           FROM public.angelcare_marketplace_cms_menu_items
          WHERE (angelcare_marketplace_cms_menu_items.status = 'active'::text)) AS active_navigation_items,
    ( SELECT (count(*))::integer AS count
           FROM public.angelcare_marketplace_homepage_placements
          WHERE (angelcare_marketplace_homepage_placements.status = 'active'::text)) AS active_merchandising_placements,
    ( SELECT (count(*))::integer AS count
           FROM public.angelcare_marketplace_media_assets
          WHERE (angelcare_marketplace_media_assets.status = 'active'::text)) AS active_media_assets,
    ( SELECT (count(*))::integer AS count
           FROM public.angelcare_marketplace_catalog_categories
          WHERE ((angelcare_marketplace_catalog_categories.status = 'published'::text) AND (angelcare_marketplace_catalog_categories.visible = true))) AS published_categories,
    ( SELECT (count(*))::integer AS count
           FROM public.angelcare_marketplace_homepage_collections
          WHERE (angelcare_marketplace_homepage_collections.status = ANY (ARRAY['active'::text, 'scheduled'::text]))) AS active_collections,
    ((( SELECT count(*) AS count
           FROM item_readiness) > 0) AND (NOT (EXISTS ( SELECT 1
           FROM item_readiness
          WHERE (NOT (item_readiness.has_media AND item_readiness.has_category AND item_readiness.has_price AND item_readiness.has_availability))))) AND (EXISTS ( SELECT 1
           FROM public.angelcare_marketplace_homepage_sections
          WHERE ((angelcare_marketplace_homepage_sections.status = ANY (ARRAY['active'::text, 'published'::text, 'scheduled'::text])) AND (angelcare_marketplace_homepage_sections.visible = true)))) AND (EXISTS ( SELECT 1
           FROM public.angelcare_marketplace_cms_menu_items
          WHERE (angelcare_marketplace_cms_menu_items.status = 'active'::text))) AND (EXISTS ( SELECT 1
           FROM public.angelcare_marketplace_media_assets
          WHERE (angelcare_marketplace_media_assets.status = 'active'::text)))) AS ready_for_activation;


