--
-- Name: angelcare_marketplace_admin_search_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_admin_search_v AS
 SELECT 'module'::text AS object_type,
    (m.id)::text AS object_id,
    m.module_key AS public_reference,
    m.name AS title,
    COALESCE(m.description, ''::text) AS subtitle,
    m.status,
    m.owner_role AS owner_id,
    NULL::uuid AS territory_id,
    NULL::uuid AS tenant_id,
    m.route_prefix AS route,
    (setweight(to_tsvector('simple'::regconfig, COALESCE(m.name, ''::text)), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, COALESCE(m.description, ''::text)), 'B'::"char")) AS search_document,
    (1)::real AS search_rank,
    m.updated_at
   FROM public.angelcare_marketplace_modules m
UNION ALL
 SELECT 'territory'::text AS object_type,
    (t.id)::text AS object_id,
    t.territory_code AS public_reference,
    t.name AS title,
    t.country_code AS subtitle,
    t.status,
    (t.owner_id)::text AS owner_id,
    t.id AS territory_id,
    NULL::uuid AS tenant_id,
    ('/angelcare-marketplace/admin/territories/'::text || t.territory_code) AS route,
    to_tsvector('simple'::regconfig, ((COALESCE(t.name, ''::text) || ' '::text) || COALESCE(t.territory_code, ''::text))) AS search_document,
    (1)::real AS search_rank,
    t.updated_at
   FROM public.angelcare_marketplace_territories t;


