--
-- Name: angelcare_marketplace_catalog_discovery_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_catalog_discovery_v WITH (security_invoker='true') AS
 SELECT i.id,
    i.public_reference,
    i.item_key,
    i.slug,
    i.kind,
    i.name_fr,
    i.name_en,
    i.name_ar,
    i.short_description_fr,
    i.short_description_en,
    i.short_description_ar,
    i.description_fr,
    NULL::text AS description_en,
    NULL::text AS description_ar,
    i.source_locale,
    i.status,
    i.territory_id,
    i.currency_label,
    i.price_mode,
    i.price_amount,
    i.featured,
    i.availability_status,
    i.owner_id,
    i.created_by,
    i.updated_by,
    i.created_at,
    i.updated_at,
    p.category_key,
    cat.category_title_fr,
    cat.category_title_en,
    cat.category_title_ar,
    media.media_url,
    COALESCE(trust.trust_labels, '{}'::text[]) AS trust_labels,
    territory.territory_code,
    COALESCE(((p.commercial_metadata ->> 'merchandising_priority'::text))::integer, 0) AS merchandising_priority,
    i.updated_at AS published_at,
    ((COALESCE(i.commercial_metadata, '{}'::jsonb) || COALESCE(p.commercial_metadata, '{}'::jsonb)) || jsonb_build_object('experience_schema_key', i.experience_schema_key, 'experience_schema_version', i.experience_schema_version, 'experience_configuration', COALESCE(i.experience_configuration, '{}'::jsonb))) AS commercial_metadata,
    i.experience_schema_key,
    i.experience_schema_version,
    COALESCE(i.experience_configuration, '{}'::jsonb) AS experience_configuration
   FROM (((((public.angelcare_marketplace_catalog_items i
     LEFT JOIN public.angelcare_marketplace_item_commercial_profiles p ON ((p.catalog_item_id = i.id)))
     LEFT JOIN public.angelcare_marketplace_territories territory ON ((territory.id = i.territory_id)))
     LEFT JOIN LATERAL ( SELECT max(c.title) FILTER (WHERE (c.locale = 'fr'::text)) AS category_title_fr,
            max(c.title) FILTER (WHERE (c.locale = 'en'::text)) AS category_title_en,
            max(c.title) FILTER (WHERE (c.locale = 'ar'::text)) AS category_title_ar
           FROM public.angelcare_marketplace_catalog_categories c
          WHERE ((c.category_key = p.category_key) AND (c.status = 'published'::text) AND ((c.territory_id = i.territory_id) OR (c.territory_id IS NULL)))) cat ON (true))
     LEFT JOIN LATERAL ( SELECT m.asset_url AS media_url
           FROM public.angelcare_marketplace_catalog_item_media m
          WHERE ((m.catalog_item_id = i.id) AND (m.status = 'active'::text))
          ORDER BY (m.media_key = 'primary'::text) DESC, m.sort_order, m.created_at
         LIMIT 1) media ON (true))
     LEFT JOIN LATERAL ( SELECT array_agg(DISTINCT COALESCE(d.name_fr, issuance.badge_key)) AS trust_labels
           FROM (public.angelcare_marketplace_trust_badge_issuances issuance
             LEFT JOIN public.angelcare_marketplace_trust_badge_definitions d ON ((d.id = issuance.badge_definition_id)))
          WHERE ((issuance.object_id = i.id) AND (issuance.status = 'active'::text) AND ((issuance.object_type ~~* '%catalog%'::text) OR (issuance.object_type ~~* '%item%'::text)))) trust ON (true));


