    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT angelcare_marketplace_homepage_collection_items_status_check CHECK ((status = ANY (ARRAY['configured'::text, 'eligible'::text, 'scheduled'::text, 'active'::text, 'suppressed'::text, 'expired'::text, 'archived'::text])))
);


--
-- Name: angelcare_marketplace_catalog_collections_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_catalog_collections_v WITH (security_invoker='true') AS
 SELECT id,
    collection_key,
    locale,
    territory_id,
    title,
    subtitle,
    selection_method,
    layout_variant,
    sort_order,
    status,
    COALESCE(( SELECT array_agg(DISTINCT profile.category_key) AS array_agg
           FROM (public.angelcare_marketplace_homepage_collection_items collection_item
             JOIN public.angelcare_marketplace_item_commercial_profiles profile ON ((profile.catalog_item_id = collection_item.catalog_item_id)))
          WHERE ((collection_item.collection_id = collection.id) AND (collection_item.status = ANY (ARRAY['eligible'::text, 'scheduled'::text, 'active'::text])) AND (profile.category_key IS NOT NULL))), '{}'::text[]) AS storefront_keys,
    COALESCE(( SELECT jsonb_agg(to_jsonb(discovery.*) ORDER BY collection_item.sort_order) AS jsonb_agg
           FROM (public.angelcare_marketplace_homepage_collection_items collection_item
             JOIN public.angelcare_marketplace_catalog_discovery_v discovery ON ((discovery.id = collection_item.catalog_item_id)))
          WHERE ((collection_item.collection_id = collection.id) AND (collection_item.status = ANY (ARRAY['eligible'::text, 'scheduled'::text, 'active'::text])) AND (discovery.status = 'published'::text))), '[]'::jsonb) AS items
   FROM public.angelcare_marketplace_homepage_collections collection;


