--
-- Name: angelcare_marketplace_category_discovery_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_category_discovery_v WITH (security_invoker='true') AS
 SELECT c.id,
    c.category_key,
    c.locale,
    c.title,
    c.short_description,
    c.slug,
    c.cover_asset_url,
    c.icon_key,
    c.visual_theme,
    c.allowed_sellable_types,
    c.available_filters,
    c.territory_id,
    c.sort_order,
    c.status,
    c.created_by,
    c.updated_by,
    c.created_at,
    c.updated_at,
    COALESCE(d.storefront_template, 'mixed'::text) AS storefront_template,
    COALESCE(d.hero_configuration, '{}'::jsonb) AS hero_configuration,
    COALESCE((d.filter_configuration -> 'allowed_filters'::text), ( SELECT COALESCE(jsonb_agg(e.key ORDER BY e.key), '[]'::jsonb) AS "coalesce"
           FROM jsonb_each(COALESCE(c.available_filters, '{}'::jsonb)) e(key, value)
          WHERE (e.value = 'true'::jsonb)), '[]'::jsonb) AS allowed_filters,
    ( SELECT count(*) AS count
           FROM (public.angelcare_marketplace_item_commercial_profiles p
             JOIN public.angelcare_marketplace_catalog_items i ON ((i.id = p.catalog_item_id)))
          WHERE ((p.category_key = c.category_key) AND (i.status = 'published'::text))) AS item_count
   FROM (public.angelcare_marketplace_catalog_categories c
     LEFT JOIN public.angelcare_marketplace_category_designs d ON ((d.category_key = c.category_key)))
  WHERE (c.category_key = ANY (ARRAY['families'::text, 'home-services'::text, 'development'::text, 'kits'::text, 'academy'::text, 'establishments'::text, 'hospitality'::text, 'health-partners'::text, 'corporates'::text, 'partner-os'::text, 'quality-check'::text, 'professionals'::text]));


