--
-- Name: angelcare_marketplace_commerce_item_admin_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_commerce_item_admin_v WITH (security_invoker='true') AS
 SELECT id,
    public_reference,
    item_key,
    slug,
    kind,
    name_fr,
    short_description_fr,
    description_fr,
    source_locale,
    status,
    territory_id,
    currency_label,
    price_mode,
    price_amount,
    featured,
    availability_status,
    owner_id,
    created_by,
    updated_by,
    created_at,
    updated_at,
    name_en,
    name_ar,
    short_description_en,
    short_description_ar,
    commercial_metadata,
    sku,
    sellable_type,
    description_en,
    description_ar,
    seo_metadata,
    attributes,
    publish_at,
    unpublish_at,
    deleted_at,
    COALESCE(( SELECT jsonb_agg(to_jsonb(v.*) ORDER BY v.sort_order) AS jsonb_agg
           FROM public.angelcare_marketplace_catalog_variants v
          WHERE (v.catalog_item_id = i.id)), '[]'::jsonb) AS variants,
    COALESCE(( SELECT jsonb_agg(to_jsonb(m.*) ORDER BY m.sort_order) AS jsonb_agg
           FROM public.angelcare_marketplace_catalog_item_media m
          WHERE ((m.catalog_item_id = i.id) AND (m.status <> 'archived'::text))), '[]'::jsonb) AS media,
    COALESCE(( SELECT jsonb_agg(to_jsonb(a.*) ORDER BY a.updated_at DESC) AS jsonb_agg
           FROM public.angelcare_marketplace_catalog_availability a
          WHERE (a.catalog_item_id = i.id)), '[]'::jsonb) AS availability,
    COALESCE(( SELECT jsonb_agg(to_jsonb(c.*) ORDER BY c.sort_order) AS jsonb_agg
           FROM public.angelcare_marketplace_catalog_item_categories c
          WHERE (c.catalog_item_id = i.id)), '[]'::jsonb) AS categories,
    COALESCE(( SELECT jsonb_agg(to_jsonb(p.*) ORDER BY p.updated_at DESC) AS jsonb_agg
           FROM public.angelcare_marketplace_finance_price_rules p
          WHERE (p.catalog_item_id = i.id)), '[]'::jsonb) AS "priceRules",
    (NOT (EXISTS ( SELECT 1
           FROM public.angelcare_marketplace_catalog_item_media m
          WHERE ((m.catalog_item_id = i.id) AND (m.status = 'active'::text))))) AS missing_media,
    ((price_mode <> 'quote_only'::text) AND (price_amount IS NULL) AND (NOT (EXISTS ( SELECT 1
           FROM public.angelcare_marketplace_finance_price_rules p
          WHERE ((p.catalog_item_id = i.id) AND (p.status = 'active'::text)))))) AS missing_price,
    (NOT (EXISTS ( SELECT 1
           FROM public.angelcare_marketplace_catalog_item_categories c
          WHERE (c.catalog_item_id = i.id)))) AS missing_category,
    ((name_en IS NULL) OR (name_ar IS NULL) OR (short_description_en IS NULL) OR (short_description_ar IS NULL)) AS missing_translation
   FROM public.angelcare_marketplace_catalog_items i;


