-- Name: angelcare_marketplace_conversion_funnel_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_conversion_funnel_v WITH (security_invoker='true') AS
 SELECT journey,
    status,
    count(*) AS session_count,
    min(created_at) AS first_created_at,
    max(last_activity_at) AS last_activity_at
   FROM public.angelcare_marketplace_conversion_sessions
  GROUP BY journey, status;


