--

CREATE VIEW public.angelcare_marketplace_conversion_session_v WITH (security_invoker='true') AS
 SELECT s.id,
    s.public_reference,
    s.session_key,
    s.journey,
    s.status,
    s.locale,
    s.territory_id,
    s.tenant_id,
    s.family_account_id,
    s.crm_account_id,
    s.catalog_item_id,
    i.public_reference AS item_reference,
    i.slug AS item_slug,
    i.kind AS item_kind,
    i.name_fr AS item_name_fr,
    s.quote_basket_id,
    s.price_snapshot_id,
    s.failure_code,
    s.failure_message,
    s.expires_at,
    s.last_activity_at,
    s.submitted_at,
    s.confirmed_at,
    s.outcome_type,
    s.outcome_id,
    s.created_at
   FROM (public.angelcare_marketplace_conversion_sessions s
     JOIN public.angelcare_marketplace_catalog_items i ON ((i.id = s.catalog_item_id)));


