--
-- Name: angelcare_marketplace_customer_segment_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_customer_segment_metrics AS
 SELECT c.id AS customer_account_id,
    c.public_reference,
    c.display_name,
    c.email,
    c.phone,
    c.status,
    c.account_kind,
    c.premium_status,
    COALESCE(NULLIF((c.metadata ->> 'city'::text), ''::text), addr.city, ''::text) AS city,
    (COALESCE(ord.order_count, (0)::numeric))::bigint AS order_count,
    (COALESCE(pay.captured_revenue, (0)::numeric))::numeric(18,2) AS captured_revenue,
    (
        CASE
            WHEN (COALESCE(ord.order_count, (0)::numeric) > (0)::numeric) THEN round((COALESCE(pay.captured_revenue, (0)::numeric) / ord.order_count), 2)
            ELSE (0)::numeric
        END)::numeric(18,2) AS average_order_value,
    (COALESCE(w.available_balance, (0)::numeric))::numeric(18,2) AS wallet_balance,
    ord.last_order_at,
    (COALESCE(sub.active_subscriptions, (0)::numeric))::bigint AS active_subscriptions,
    (COALESCE(ord.booking_count, (0)::numeric))::bigint AS booking_count,
    COALESCE(ord.acquisition_sources, '{}'::text[]) AS acquisition_sources,
    COALESCE(ord.booking_statuses, '{}'::text[]) AS booking_statuses,
    COALESCE(sub.subscription_statuses, '{}'::text[]) AS subscription_statuses,
    COALESCE(prod.purchased_product_ids, '{}'::text[]) AS purchased_product_ids,
    c.created_at,
    c.updated_at
   FROM ((((((public.angelcare_marketplace_customer_accounts c
     LEFT JOIN LATERAL ( SELECT a.city
           FROM public.angelcare_marketplace_customer_addresses a
          WHERE ((a.customer_account_id = c.id) AND (a.status = 'active'::text))
          ORDER BY a.is_default DESC, a.updated_at DESC
         LIMIT 1) addr ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::numeric AS order_count,
            max(j.created_at) AS last_order_at,
            (count(*) FILTER (WHERE (j.journey_type ~* 'booking|service'::text)))::numeric AS booking_count,
            array_remove(array_agg(DISTINCT j.creation_source), NULL::text) AS acquisition_sources,
            array_remove(array_agg(DISTINCT j.status) FILTER (WHERE (j.journey_type ~* 'booking|service'::text)), NULL::text) AS booking_statuses
           FROM public.angelcare_marketplace_journeys j
          WHERE (j.customer_account_id = c.id)) ord ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(sum(p.captured_amount), (0)::numeric) AS captured_revenue
           FROM public.angelcare_marketplace_payment_intents p
          WHERE (p.customer_account_id = c.id)) pay ON (true))
     LEFT JOIN public.angelcare_marketplace_wallet_accounts w ON ((w.customer_account_id = c.id)))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (s.status = 'active'::text)))::numeric AS active_subscriptions,
            array_remove(array_agg(DISTINCT s.status), NULL::text) AS subscription_statuses
           FROM public.angelcare_marketplace_customer_subscriptions s
          WHERE (s.customer_account_id = c.id)) sub ON (true))
     LEFT JOIN LATERAL ( SELECT array_remove(array_agg(DISTINCT (ol.catalog_item_id)::text), NULL::text) AS purchased_product_ids
           FROM (public.angelcare_marketplace_journeys j
             JOIN public.angelcare_marketplace_order_lines ol ON (((ol.journey_id = j.id) AND (ol.status <> 'cancelled'::text))))
          WHERE (j.customer_account_id = c.id)) prod ON (true));


