--
-- Name: angelcare_marketplace_experience_schema_registry_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_experience_schema_registry_v WITH (security_invoker='true') AS
 SELECT s.id,
    s.schema_key,
    s.version,
    s.segment_key,
    s.vertical_key,
    s.category_key,
    s.subcategory_key,
    s.archetype_key,
    s.parent_schema_key,
    s.name_fr,
    s.name_en,
    s.name_ar,
    s.description_fr,
    s.description_en,
    s.description_ar,
    s.admin_studio_template,
    s.public_experience_template,
    s.conversion_template,
    s.operations_handover_type,
    s.homepage_card_template,
    s.availability_authority,
    s.pricing_modes,
    s.media_requirements,
    s.search_filters,
    s.comparison_fields,
    s.analytics_dimensions,
    s.configuration,
    s.status,
    s.published_at,
    s.created_by,
    s.updated_by,
    s.created_at,
    s.updated_at,
    COALESCE(f.field_count, (0)::bigint) AS field_count,
    COALESCE(v.variant_group_count, (0)::bigint) AS variant_group_count,
    COALESCE(t.template_count, (0)::bigint) AS csv_template_count
   FROM (((public.angelcare_marketplace_experience_schemas s
     LEFT JOIN ( SELECT angelcare_marketplace_experience_schema_fields.schema_id,
            count(*) AS field_count
           FROM public.angelcare_marketplace_experience_schema_fields
          WHERE (angelcare_marketplace_experience_schema_fields.status = 'active'::text)
          GROUP BY angelcare_marketplace_experience_schema_fields.schema_id) f ON ((f.schema_id = s.id)))
     LEFT JOIN ( SELECT angelcare_marketplace_experience_variant_groups.schema_id,
            count(*) AS variant_group_count
           FROM public.angelcare_marketplace_experience_variant_groups
          WHERE (angelcare_marketplace_experience_variant_groups.status = 'active'::text)
          GROUP BY angelcare_marketplace_experience_variant_groups.schema_id) v ON ((v.schema_id = s.id)))
     LEFT JOIN ( SELECT angelcare_marketplace_schema_csv_templates.schema_id,
            count(*) AS template_count
           FROM public.angelcare_marketplace_schema_csv_templates
          WHERE (angelcare_marketplace_schema_csv_templates.status = 'active'::text)
          GROUP BY angelcare_marketplace_schema_csv_templates.schema_id) t ON ((t.schema_id = s.id)));


