    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    resolution_proposal text,
    opened_by uuid,
    owner_id uuid,
    customer_accepted_at timestamp with time zone,
    sla_due_at timestamp with time zone,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT angelcare_marketplace_journey_recovery_cases_status_check CHECK ((status = ANY (ARRAY['open'::text, 'investigating'::text, 'proposal'::text, 'awaiting_customer'::text, 'resolved'::text, 'closed'::text]))),
    CONSTRAINT angelcare_marketplace_journey_recovery_cases_urgency_check CHECK ((urgency = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))
);


--
-- Name: angelcare_marketplace_journey_command_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_journey_command_v WITH (security_invoker='true') AS
 SELECT id,
    public_reference,
    journey_type,
    status,
    locale,
    title,
    subtitle,
    owner_user_id,
    family_account_id,
    crm_account_id,
    tenant_id,
    territory_id,
    conversion_outcome_id,
    canonical_object_type,
    canonical_object_id,
    current_authority,
    next_action_label,
    next_action_due_at,
    risk_level,
    completion_percent,
    scheduled_start_at,
    scheduled_end_at,
    completed_at,
    financial_status,
    fulfillment_status,
    customer_context,
    metadata,
    created_at,
    updated_at,
    COALESCE(( SELECT count(*) AS count
           FROM public.angelcare_marketplace_journey_actions a
          WHERE ((a.journey_id = j.id) AND (a.status = 'open'::text))), (0)::bigint) AS open_actions,
    COALESCE(( SELECT count(*) AS count
           FROM public.angelcare_marketplace_journey_recovery_cases r
          WHERE ((r.journey_id = j.id) AND (r.status <> ALL (ARRAY['resolved'::text, 'closed'::text])))), (0)::bigint) AS open_recovery_cases,
    COALESCE(( SELECT count(*) AS count
           FROM public.angelcare_marketplace_journey_notifications n
          WHERE ((n.journey_id = j.id) AND (n.status = 'failed'::text))), (0)::bigint) AS failed_notifications
   FROM public.angelcare_marketplace_journeys j;


