--
-- Name: angelcare_marketplace_journey_funnel_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_journey_funnel_v WITH (security_invoker='true') AS
 SELECT journey_type,
    status,
    count(*) AS journey_count,
    (avg(completion_percent))::numeric(8,2) AS average_completion,
    count(*) FILTER (WHERE (risk_level = ANY (ARRAY['high'::text, 'critical'::text]))) AS high_risk_count
   FROM public.angelcare_marketplace_journeys
  GROUP BY journey_type, status;


