    created_by,
    updated_by,
    created_at,
    updated_at,
    closed_at,
    ( SELECT count(*) AS count
           FROM public.angelcare_marketplace_fulfillment_obligations o
          WHERE ((o.fulfillment_case_id = f.id) AND (o.status <> ALL (ARRAY['completed'::text, 'waived'::text])))) AS open_obligations,
    ( SELECT count(*) AS count
           FROM public.angelcare_marketplace_fulfillment_evidence e
          WHERE ((e.fulfillment_case_id = f.id) AND (e.validation_status = 'validated'::text))) AS validated_evidence,
    ((due_at IS NOT NULL) AND (due_at < now()) AND (status <> ALL (ARRAY['closed'::text, 'cancelled'::text]))) AS late_flag
   FROM public.angelcare_marketplace_fulfillment_cases f;


