);


--
-- Name: angelcare_marketplace_operations_financial_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_operations_financial_v WITH (security_invoker='true') AS
 SELECT id,
    public_reference,
    fulfillment_case_id,
    journey_id,
    status,
    contracted_amount,
    adjustment_amount,
    final_reconciled_amount,
    currency,
    finance_handover_status,
    finance_authority_id,
    evidence_complete,
    dispute_open,
    owner_id,
    tenant_id,
    territory_id,
    created_at,
    updated_at,
    closed_at,
    COALESCE(( SELECT sum(
                CASE
                    WHEN (l.direction = 'credit'::text) THEN (- l.amount)
                    ELSE l.amount
                END) AS sum
           FROM public.angelcare_marketplace_reconciliation_lines l
          WHERE (l.reconciliation_case_id = r.id)), (0)::numeric) AS calculated_adjustment
   FROM public.angelcare_marketplace_reconciliation_cases r;


