--
-- Name: angelcare_marketplace_public_navigation_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.angelcare_marketplace_public_navigation_v AS
 SELECT i.id,
    i.menu_id,
        CASE m.locale
            WHEN 'en'::text THEN COALESCE(i.label_en, i.label_fr, i.label)
            WHEN 'ar'::text THEN COALESCE(i.label_ar, i.label_fr, i.label)
            ELSE COALESCE(i.label_fr, i.label)
        END AS label,
    i.href,
    i.page_id,
    i.parent_id,
    i.sort_order,
    i.visibility,
    i.status,
    m.locale,
    COALESCE(i.territory_id, m.territory_id) AS territory_id,
    i.icon_key,
    i.image_asset_id,
    i.desktop_visible,
    i.mobile_visible
   FROM (public.angelcare_marketplace_cms_menu_items i
     JOIN public.angelcare_marketplace_cms_menus m ON ((m.id = i.menu_id)))
  WHERE ((i.status = 'active'::text) AND (m.status = 'published'::text));


