--
-- Name: contract_billing_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contract_billing_summary AS
 SELECT c.id AS contract_id,
    COALESCE(c.contract_value, (0)::numeric) AS contract_value,
    COALESCE(c.monthly_amount, (0)::numeric) AS monthly_amount,
    COALESCE(sum(i.amount), (0)::numeric) AS invoiced_amount,
    COALESCE(sum(i.amount_paid), (0)::numeric) AS collected_amount,
    COALESCE(sum(
        CASE
            WHEN (i.status = 'overdue'::text) THEN (i.amount - i.amount_paid)
            ELSE (0)::numeric
        END), (0)::numeric) AS overdue_amount,
    COALESCE(sum(
        CASE
            WHEN (i.status = 'pending'::text) THEN (i.amount - i.amount_paid)
            ELSE (0)::numeric
        END), (0)::numeric) AS pending_amount,
    count(i.id) AS invoice_count,
    max(i.created_at) AS latest_invoice_at
   FROM (public.contracts c
     LEFT JOIN public.billing_invoices i ON (((i.contract_id = c.id) AND (COALESCE(i.is_archived, false) = false))))
  GROUP BY c.id, c.contract_value, c.monthly_amount;


