--
-- Name: desktop_station_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.desktop_station_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    browser_policy_id uuid,
    name text NOT NULL,
    description text,
    mode text DEFAULT 'standard'::text NOT NULL,
    start_at_login boolean DEFAULT false NOT NULL,
    kiosk_enforcement boolean DEFAULT false NOT NULL,
    always_on_top boolean DEFAULT false NOT NULL,
    confirm_before_quit boolean DEFAULT true NOT NULL,
    restore_after_crash boolean DEFAULT true NOT NULL,
    relock_after_restart boolean DEFAULT true NOT NULL,
    relock_after_inactivity_minutes integer DEFAULT 0 NOT NULL,
    pin_required boolean DEFAULT true NOT NULL,
    exit_reason_required boolean DEFAULT false NOT NULL,
    offline_unlock_permitted boolean DEFAULT true NOT NULL,
    failed_attempt_threshold integer DEFAULT 5 NOT NULL,
    lockout_duration_minutes integer DEFAULT 15 NOT NULL,
    auto_relock_minutes integer DEFAULT 15 NOT NULL,
    restore_tabs boolean DEFAULT true NOT NULL,
    maximum_tabs integer DEFAULT 8 NOT NULL,
    clear_browser_data_on_logout boolean DEFAULT false NOT NULL,
    browser_history_retention_days integer DEFAULT 30 NOT NULL,
    security_flags jsonb DEFAULT '{}'::jsonb NOT NULL,
    policy_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    maximum_ac_plus_tabs integer DEFAULT 6 NOT NULL,
    ac_plus_enabled boolean DEFAULT true NOT NULL,
    ac_plus_allowed_modes text[] DEFAULT ARRAY['standard'::text, 'focus'::text, 'locked'::text] NOT NULL,
    split_enabled boolean DEFAULT true NOT NULL,
    split_allowed_modes text[] DEFAULT ARRAY['standard'::text, 'focus'::text, 'locked'::text] NOT NULL,
    split_modes integer[] DEFAULT ARRAY[2, 3, 4] NOT NULL,
    locked_mode_safety_gate boolean DEFAULT true NOT NULL,
    minimum_locked_desktop_version text DEFAULT '1.7.4'::text NOT NULL,
    emergency_standard_fallback boolean DEFAULT true NOT NULL,
    relock_requires_acknowledgement boolean DEFAULT true NOT NULL,
    CONSTRAINT desktop_station_policies_auto_relock_minutes_check CHECK (((auto_relock_minutes >= 1) AND (auto_relock_minutes <= 1440))),
    CONSTRAINT desktop_station_policies_browser_history_retention_days_check CHECK (((browser_history_retention_days >= 0) AND (browser_history_retention_days <= 365))),
    CONSTRAINT desktop_station_policies_failed_attempt_threshold_check CHECK (((failed_attempt_threshold >= 1) AND (failed_attempt_threshold <= 20))),
    CONSTRAINT desktop_station_policies_lockout_duration_minutes_check CHECK (((lockout_duration_minutes >= 1) AND (lockout_duration_minutes <= 1440))),
    CONSTRAINT desktop_station_policies_maximum_ac_plus_tabs_check CHECK (((maximum_ac_plus_tabs >= 1) AND (maximum_ac_plus_tabs <= 48))),
    CONSTRAINT desktop_station_policies_maximum_tabs_check CHECK (((maximum_tabs >= 2) AND (maximum_tabs <= 50))),
    CONSTRAINT desktop_station_policies_mode_check CHECK ((mode = ANY (ARRAY['standard'::text, 'focus'::text, 'locked'::text]))),
    CONSTRAINT desktop_station_policies_policy_version_check CHECK ((policy_version > 0)),
    CONSTRAINT desktop_station_policies_relock_after_inactivity_minutes_check CHECK (((relock_after_inactivity_minutes >= 0) AND (relock_after_inactivity_minutes <= 1440)))
);


--
-- Name: COLUMN desktop_station_policies.ac_plus_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.desktop_station_policies.ac_plus_enabled IS 'Explicit AC+ capability switch. Applies independently in Standard, Focus and Corporate Locked modes.';


