--
-- Name: COLUMN desktop_station_policies.locked_mode_safety_gate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.desktop_station_policies.locked_mode_safety_gate IS 'Prevents Corporate Locked assignment to clients below minimum_locked_desktop_version unless an explicit elevated override is supplied.';


