--
-- Name: email_effective_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.email_effective_permissions AS
 SELECT p.user_id,
    p.mailbox_id,
    a.label AS mailbox_label,
    COALESCE(a.email_address, a.mailbox_email) AS email_address,
    a.department,
    a.business_context,
    a.risk_level,
    p.access_level,
    p.can_read,
    p.can_draft,
    p.can_send,
    p.can_approve,
    p.can_assign,
    p.can_delete,
    p.can_manage_settings,
    p.requires_approval,
    p.source,
    p.expires_at,
    p.is_active
   FROM (public.user_email_permissions p
     JOIN public.email_accounts_legacy_backup_20260506 a ON ((a.id = p.mailbox_id)))
  WHERE ((p.is_active = true) AND (a.is_active = true) AND ((p.expires_at IS NULL) OR (p.expires_at > now())));


