    error_message text,
    diagnostics jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT hr_employee_email_send_jobs_progress_check CHECK (((progress >= 0) AND (progress <= 100))),
    CONSTRAINT hr_employee_email_send_jobs_stage_check CHECK ((stage = ANY (ARRAY['preparing'::text, 'validating_employee'::text, 'resolving_rh_mailbox'::text, 'recording_outbox'::text, 'sending_to_bridge'::text, 'provider_accepted'::text, 'sent'::text, 'failed'::text]))),
    CONSTRAINT hr_employee_email_send_jobs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'sent'::text, 'failed'::text])))
);


