--
-- Name: hr_live_sync_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hr_live_sync_health AS
 SELECT domain,
    (count(*))::integer AS events_count,
    max(created_at) AS last_event_at,
    (count(*) FILTER (WHERE (severity = ANY (ARRAY['warning'::text, 'critical'::text]))))::integer AS risk_events,
    (count(*) FILTER (WHERE (status ~~ '%gated%'::text)))::integer AS gated_events
   FROM public.hr_live_sync_events
  GROUP BY domain;


