--

CREATE VIEW public.hr_module_health_v AS
 SELECT now() AS checked_at,
    ( SELECT count(*) AS count
           FROM public.hr_activity_log) AS activity_events,
    ( SELECT count(*) AS count
           FROM public.hr_audit_trail) AS audit_events,
    ( SELECT count(*) AS count
           FROM public.hr_observability_events) AS observability_events,
    'ready'::text AS compatibility_status;


