--
-- Name: hsd_executive_intervention_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_executive_intervention_v AS
 SELECT hsd_quality_signals.id,
    hsd_quality_signals.tenant_id,
    'quality_signal'::text AS source_type,
    (hsd_quality_signals.id)::text AS source_id,
    hsd_quality_signals.severity,
    hsd_quality_signals.title,
    (COALESCE(hsd_quality_signals.customer_impact, ''::text) ||
        CASE
            WHEN (hsd_quality_signals.operational_impact <> ''::text) THEN (' · '::text || hsd_quality_signals.operational_impact)
            ELSE ''::text
        END) AS consequence,
    'Décision Quality Board requise'::text AS required_action,
    hsd_quality_signals.owner_id,
    hsd_quality_signals.due_at
   FROM public.hsd_quality_signals
  WHERE ((hsd_quality_signals.status = ANY (ARRAY['open'::text, 'under_review'::text, 'root_cause_required'::text])) AND (hsd_quality_signals.severity = ANY (ARRAY['material'::text, 'blocking'::text, 'critical'::text])))
UNION ALL
 SELECT hsd_system_incidents.id,
    hsd_system_incidents.tenant_id,
    'system_incident'::text AS source_type,
    (hsd_system_incidents.id)::text AS source_id,
    hsd_system_incidents.severity,
    hsd_system_incidents.title,
    COALESCE(hsd_system_incidents.summary, ''::text) AS consequence,
    'Piloter le cycle incident'::text AS required_action,
    hsd_system_incidents.owner_id,
    NULL::timestamp with time zone AS due_at
   FROM public.hsd_system_incidents
  WHERE (hsd_system_incidents.status <> ALL (ARRAY['resolved'::text, 'reviewed'::text, 'closed'::text]))
UNION ALL
 SELECT hsd_enterprise_reconciliation_findings.id,
    hsd_enterprise_reconciliation_findings.tenant_id,
    'reconciliation'::text AS source_type,
    (hsd_enterprise_reconciliation_findings.id)::text AS source_id,
    hsd_enterprise_reconciliation_findings.severity,
    hsd_enterprise_reconciliation_findings.domain AS title,
    COALESCE(hsd_enterprise_reconciliation_findings.detail, ''::text) AS consequence,
    COALESCE(hsd_enterprise_reconciliation_findings.recovery_action, 'Résoudre et réconcilier'::text) AS required_action,
    NULL::text AS owner_id,
    NULL::timestamp with time zone AS due_at
   FROM public.hsd_enterprise_reconciliation_findings
  WHERE ((hsd_enterprise_reconciliation_findings.status = 'open'::text) AND (hsd_enterprise_reconciliation_findings.severity = ANY (ARRAY['blocking'::text, 'critical'::text])));


