    CONSTRAINT hsd_factory_sellables_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'suspended'::text, 'superseded'::text, 'retired'::text, 'archived'::text]))),
    CONSTRAINT hsd_factory_sellables_universe_check CHECK ((universe = ANY (ARRAY['b2c'::text, 'b2b'::text])))
);


--
-- Name: hsd_factory_command_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_factory_command_v AS
 SELECT r.tenant_id,
    r.mode,
    r.universe,
    r.status,
    count(*) AS request_count,
    count(sc.id) AS scenario_count,
    count(fs.id) AS published_sellable_count,
    max(r.created_at) AS latest_request_at
   FROM ((public.hsd_factory_requests r
     LEFT JOIN public.hsd_factory_scenarios sc ON (((sc.request_id = r.id) AND (sc.tenant_id = r.tenant_id))))
     LEFT JOIN public.hsd_factory_sellables fs ON (((fs.factory_scenario_id = sc.id) AND (fs.tenant_id = r.tenant_id))))
  GROUP BY r.tenant_id, r.mode, r.universe, r.status;


