--

CREATE VIEW public.hsd_factory_vitrine_v AS
 SELECT s.id,
    s.tenant_id,
    s.code,
    s.universe,
    s.status,
    s.commercial_name,
    s.technical_name,
    s.promise,
    s.category_id,
    c.code AS category_code,
    c.commercial_name_fr AS category_name,
    s.starting_price_dh,
    s.margin_percent,
    s.readiness,
    s.active_version,
    s.published_at,
    s.snapshot,
    s.checksum
   FROM (public.hsd_factory_sellables s
     JOIN public.hsd_service_categories c ON (((c.id = s.category_id) AND (c.tenant_id = s.tenant_id))));


