--
-- Name: hsd_handoff_registry_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_handoff_registry_v AS
 SELECT id,
    tenant_id,
    code,
    status,
    sellable_id,
    sellable_version_id,
    technical_plan_version_id,
    category_version_id,
    universe,
    customer_ref,
    beneficiary_refs,
    customer_snapshot,
    beneficiary_snapshot,
    operational_contacts,
    access_instructions,
    safety_blockers,
    mission_count,
    total_minutes,
    snapshot_hash,
    idempotency_key,
    blueprint_summary,
    preflight_status,
    last_preflight_run_id,
    reconciliation_status,
    carelink_parent_mission_id,
    last_failure,
    approved_by,
    approved_at,
    created_by,
    created_at,
    updated_at,
    COALESCE(( SELECT jsonb_agg(b.beneficiary_ref) AS jsonb_agg
           FROM public.hsd_handoff_beneficiary_snapshots b
          WHERE (b.handoff_id = h.id)), '[]'::jsonb) AS beneficiary_snapshot_refs,
    ( SELECT count(*) AS count
           FROM public.hsd_handoff_preflight_findings f
          WHERE ((f.handoff_id = h.id) AND (f.status = 'open'::text) AND f.blocking)) AS open_blocker_count,
    ( SELECT count(*) AS count
           FROM public.hsd_handoff_carelink_links l
          WHERE ((l.handoff_id = h.id) AND (l.target_type = 'sub_mission'::text))) AS linked_sub_mission_count
   FROM public.hsd_handoff_requests h;


