--
-- Name: hsd_operational_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_operational_health_v AS
 SELECT d.id,
    d.tenant_id,
    d.code,
    d.label,
    d.domain,
    d.blocking,
    COALESCE(r.state, 'unknown'::text) AS state,
    COALESCE(r.verified, false) AS verified,
    COALESCE(r.detail, 'Aucune preuve récente'::text) AS detail,
    r.checked_at
   FROM (public.hsd_health_check_definitions d
     LEFT JOIN LATERAL ( SELECT x.state,
            x.verified,
            x.detail,
            x.checked_at
           FROM public.hsd_health_check_runs x
          WHERE (x.definition_id = d.id)
          ORDER BY x.checked_at DESC
         LIMIT 1) r ON (true))
  WHERE d.active;


