--
-- Name: hsd_performance_metric_latest_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_performance_metric_latest_v AS
 SELECT DISTINCT ON (d.tenant_id, d.id) d.tenant_id,
    d.code,
    d.label,
    d.unit,
    v.value,
    v.status,
    COALESCE(v.source, d.source_domain) AS source,
    v.measured_at
   FROM (public.hsd_performance_metric_definitions d
     LEFT JOIN public.hsd_performance_metric_values v ON ((v.definition_id = d.id)))
  ORDER BY d.tenant_id, d.id, v.measured_at DESC NULLS LAST;


