--
-- Name: hsd_planning_command_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_planning_command_v AS
 SELECT tenant_id,
    count(*) AS total_requests,
    count(*) FILTER (WHERE (status = 'ready'::text)) AS ready_requests,
    count(*) FILTER (WHERE (status = 'approval_requested'::text)) AS approval_queue,
    count(*) FILTER (WHERE (status = 'approved'::text)) AS approved_plans
   FROM public.hsd_planning_requests r
  GROUP BY tenant_id;


