--
-- Name: hsd_production_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_production_readiness_v AS
 SELECT c.id,
    c.tenant_id,
    c.code,
    c.label,
    c.description,
    c.sort_order,
    c.blocking,
    COALESCE(e.status, c.status) AS status,
    c.owner_id,
    e.verified_at,
    COALESCE(( SELECT count(*) AS count
           FROM public.hsd_production_readiness_evidence z
          WHERE (z.control_id = c.id)), (0)::bigint) AS evidence_count
   FROM (public.hsd_production_readiness_controls c
     LEFT JOIN LATERAL ( SELECT x.status,
            x.verified_at
           FROM public.hsd_production_readiness_evidence x
          WHERE (x.control_id = c.id)
          ORDER BY x.submitted_at DESC
         LIMIT 1) e ON (true));


