--
-- Name: hsd_quality_signal_registry_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_quality_signal_registry_v AS
 SELECT id,
    tenant_id,
    code,
    signal_type,
    severity,
    status,
    title,
    summary,
    customer_impact,
    operational_impact,
    commercial_impact,
    source_count,
    owner_id,
    due_at,
    created_by,
    created_at,
    updated_at,
    ( SELECT count(*) AS count
           FROM public.hsd_quality_signal_sources x
          WHERE (x.signal_id = s.id)) AS source_count_actual,
    ( SELECT count(*) AS count
           FROM public.hsd_improvement_proposals p
          WHERE (p.signal_id = s.id)) AS improvement_count
   FROM public.hsd_quality_signals s;


