);


--
-- Name: hsd_sellable_registry_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_sellable_registry_v WITH (security_invoker='true') AS
 SELECT s.id,
    s.tenant_id,
    s.code,
    s.commercial_name,
    s.technical_name,
    s.universe,
    s.status,
    s.category_id,
    s.active_version,
    s.promise,
    s.readiness,
    s.published_at,
    s.created_at,
    p.starting_price,
    p.margin_percent
   FROM ((public.hsd_sellables s
     LEFT JOIN public.hsd_sellable_versions v ON (((v.sellable_id = s.id) AND (v.version_number = s.active_version))))
     LEFT JOIN public.hsd_sellable_prices p ON ((p.sellable_version_id = v.id)));


