--
-- Name: hsd_v_category_readiness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_v_category_readiness AS
 WITH scores AS (
         SELECT c.id,
            c.tenant_id,
            c.family_id,
            c.code,
            c.commercial_name_fr,
            c.operational_name_fr,
            c.description_fr,
            c.carelink_service_type,
            c.audience,
            c.cities,
            c.languages,
            c.beneficiary_profiles,
            c.mission_formats,
            c.status,
            c.version_number,
            c.created_by,
            c.updated_by,
            c.created_at,
            c.updated_at,
            (LEAST((100)::bigint, ( SELECT (count(*) * 35)
                   FROM public.hsd_doctrine_rules d
                  WHERE ((d.category_id = c.id) AND (d.status = ANY (ARRAY['draft'::text, 'review'::text, 'approved'::text, 'active'::text]))))))::integer AS doctrine_readiness,
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM public.hsd_capacity_rules x
                      WHERE (x.category_id = c.id))) THEN 100
                    ELSE 0
                END AS capacity_readiness,
            (LEAST((100)::bigint, ( SELECT (count(*) * 20)
                   FROM public.hsd_activity_library a
                  WHERE ((a.tenant_id = c.tenant_id) AND ((cardinality(a.category_codes) = 0) OR (c.code = ANY (a.category_codes)))))))::integer AS activity_readiness,
            (LEAST((100)::bigint, ( SELECT (count(*) * 25)
                   FROM public.hsd_service_competency_rules x
                  WHERE (x.category_id = c.id))))::integer AS staffing_readiness,
            (LEAST((100)::bigint, (( SELECT (count(*) * 25)
                   FROM public.hsd_safeguards s
                  WHERE (s.category_id = c.id)) + ( SELECT (count(*) * 4)
                   FROM public.hsd_risk_controls r
                  WHERE (r.tenant_id = c.tenant_id)))))::integer AS safety_readiness,
            LEAST(100, (
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM public.hsd_checklist_templates t
                      WHERE (t.category_id = c.id))) THEN 50
                    ELSE 0
                END +
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM public.hsd_report_templates t
                      WHERE (t.category_id = c.id))) THEN 50
                    ELSE 0
                END)) AS quality_readiness,
            (LEAST((100)::bigint, (
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM public.hsd_price_entries p
                      WHERE (p.category_id = c.id))) THEN 50
                    ELSE 0
                END + LEAST((50)::bigint, ( SELECT (count(*) * 15)
                   FROM public.hsd_service_options o
                  WHERE (o.category_id = c.id))))))::integer AS commercial_readiness
           FROM public.hsd_service_categories c
        ), final AS (
         SELECT s.id,
            s.tenant_id,
            s.family_id,
            s.code,
            s.commercial_name_fr,
            s.operational_name_fr,
            s.description_fr,
            s.carelink_service_type,
            s.audience,
            s.cities,
            s.languages,
            s.beneficiary_profiles,
            s.mission_formats,
            s.status,
            s.version_number,
            s.created_by,
            s.updated_by,
            s.created_at,
            s.updated_at,
            s.doctrine_readiness,
            s.capacity_readiness,
            s.activity_readiness,
            s.staffing_readiness,
            s.safety_readiness,
            s.quality_readiness,
            s.commercial_readiness,
            (round(((((((((s.doctrine_readiness + s.capacity_readiness) + s.activity_readiness) + s.staffing_readiness) + s.safety_readiness) + s.quality_readiness) + s.commercial_readiness))::numeric / 7.0)))::integer AS overall_readiness
           FROM scores s
        )
 SELECT f.id,
    f.tenant_id,
    f.family_id,
    f.code,
    f.commercial_name_fr,
    f.operational_name_fr,
    f.description_fr,
    f.carelink_service_type,
    f.audience,
    f.cities,
    f.languages,
    f.beneficiary_profiles,
    f.mission_formats,
    f.status,
    f.version_number,
    f.created_by,
    f.updated_by,
    f.created_at,
    f.updated_at,
    f.doctrine_readiness,
    f.capacity_readiness,
    f.activity_readiness,
    f.staffing_readiness,
    f.safety_readiness,
    f.quality_readiness,
    f.commercial_readiness,
    f.overall_readiness,
    sf.code AS family_code,
    sf.name_fr AS family_name,
    sf.sort_order AS family_sort_order,
    array_remove(ARRAY[
        CASE
            WHEN (f.doctrine_readiness = 0) THEN 'Doctrine manquante'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (f.capacity_readiness = 0) THEN 'Capacité manquante'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (f.staffing_readiness = 0) THEN 'Compétences non reliées'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (f.quality_readiness = 0) THEN 'Checklist et rapport manquants'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (f.safety_readiness < 60) THEN 'Safeguarding à renforcer'::text
            ELSE NULL::text
        END], NULL::text) AS blockers
   FROM (final f
     JOIN public.hsd_service_families sf ON ((sf.id = f.family_id)));


