--
-- Name: hsd_v_risk_controls; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hsd_v_risk_controls AS
 SELECT id,
    tenant_id,
    code,
    name_fr,
    description_fr,
    severity,
    trigger_conditions,
    preventive_controls,
    required_evidence,
    stop_work,
    escalation_route,
    category_codes,
    status,
    created_by,
    updated_by,
    created_at,
    updated_at,
        CASE severity
            WHEN 'blocking'::text THEN 5
            WHEN 'critical'::text THEN 4
            WHEN 'important'::text THEN 3
            WHEN 'attention'::text THEN 2
            ELSE 1
        END AS severity_rank
   FROM public.hsd_risk_controls r;


