    CONSTRAINT market_os_records_status_check CHECK (((status IS NULL) OR (status = ANY (ARRAY['draft'::text, 'active'::text, 'review'::text, 'approved'::text, 'rejected'::text, 'published'::text, 'paused'::text, 'risk'::text, 'blocked'::text, 'completed'::text, 'cancelled'::text, 'archived'::text, 'converted'::text, 'queued'::text, 'assigned'::text, 'monitoring'::text, 'new'::text]))))
);


