--
-- Name: opsos_modal_telemetry_last_hour; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.opsos_modal_telemetry_last_hour AS
 SELECT COALESCE(modal, 'Unknown Modal'::text) AS modal,
    COALESCE(route, '/unknown'::text) AS route,
    (count(*))::integer AS event_count,
    (count(*) FILTER (WHERE (event_type = 'modal_open'::text)))::integer AS open_count,
    (count(*) FILTER (WHERE (event_type = 'modal_close'::text)))::integer AS close_count,
    max(COALESCE(duration_ms, 0)) AS max_duration_ms,
    max(COALESCE(memory_mb, 0)) AS max_memory_mb,
    max(created_at) AS last_event_at,
        CASE
            WHEN (count(*) FILTER (WHERE (severity = 'critical'::text)) > 0) THEN 'critical'::text
            WHEN (count(*) FILTER (WHERE (severity = 'warning'::text)) > 0) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS status
   FROM public.opsos_performance_events
  WHERE ((created_at >= (now() - '01:00:00'::interval)) AND (modal IS NOT NULL))
  GROUP BY COALESCE(modal, 'Unknown Modal'::text), COALESCE(route, '/unknown'::text)
  ORDER BY (max(COALESCE(duration_ms, 0))) DESC;


