--
-- Name: opsos_route_telemetry_last_hour; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.opsos_route_telemetry_last_hour AS
 SELECT COALESCE(route, '/unknown'::text) AS route,
    (count(*))::integer AS event_count,
    (count(*) FILTER (WHERE (event_type = 'long_task'::text)))::integer AS long_task_count,
    (count(*) FILTER (WHERE (event_type = 'api_call'::text)))::integer AS api_call_count,
    (count(*) FILTER (WHERE (event_type = 'api_error'::text)))::integer AS api_error_count,
    (count(*) FILTER (WHERE (event_type = ANY (ARRAY['client_error'::text, 'unhandled_rejection'::text]))))::integer AS client_error_count,
    max(COALESCE(duration_ms, 0)) AS max_duration_ms,
    (round(avg(COALESCE(duration_ms, 0))))::integer AS avg_duration_ms,
    max(COALESCE(memory_mb, 0)) AS max_memory_mb,
    max(created_at) AS last_event_at,
        CASE
            WHEN (count(*) FILTER (WHERE (severity = 'critical'::text)) > 0) THEN 'critical'::text
            WHEN (count(*) FILTER (WHERE (severity = 'warning'::text)) > 0) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS status
   FROM public.opsos_performance_events
  WHERE (created_at >= (now() - '01:00:00'::interval))
  GROUP BY COALESCE(route, '/unknown'::text)
  ORDER BY
        CASE
            WHEN (count(*) FILTER (WHERE (severity = 'critical'::text)) > 0) THEN 3
            WHEN (count(*) FILTER (WHERE (severity = 'warning'::text)) > 0) THEN 2
            ELSE 1
        END DESC, (max(COALESCE(duration_ms, 0))) DESC;


