    retention_until timestamp with time zone NOT NULL,
    restore_readiness text DEFAULT 'partial'::text NOT NULL,
    restored_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT opsos_storage_quarantine_case_estimated_recoverable_bytes_check CHECK ((estimated_recoverable_bytes >= 0)),
    CONSTRAINT opsos_storage_quarantine_cases_actual_recovered_bytes_check CHECK ((actual_recovered_bytes >= 0)),
    CONSTRAINT opsos_storage_quarantine_cases_approval_count_check CHECK (((approval_count >= 0) AND (approval_count <= 2))),
    CONSTRAINT opsos_storage_quarantine_cases_approvals_required_check CHECK (((approvals_required >= 1) AND (approvals_required <= 2))),
    CONSTRAINT opsos_storage_quarantine_cases_original_size_bytes_check CHECK ((original_size_bytes >= 0)),
    CONSTRAINT opsos_storage_quarantine_cases_quarantine_mode_check CHECK ((quarantine_mode = ANY (ARRAY['logical'::text, 'physical'::text]))),
    CONSTRAINT opsos_storage_quarantine_cases_restore_readiness_check CHECK ((restore_readiness = ANY (ARRAY['complete'::text, 'partial'::text, 'blocked'::text]))),
    CONSTRAINT opsos_storage_quarantine_cases_risk_level_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'controlled'::text, 'high'::text, 'blocked'::text]))),
    CONSTRAINT opsos_storage_quarantine_cases_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'impact_pending'::text, 'awaiting_approval'::text, 'approved'::text, 'executing'::text, 'verifying'::text, 'quarantined'::text, 'restore_requested'::text, 'restoring'::text, 'restored'::text, 'failed'::text, 'cancelled'::text, 'expired'::text, 'eligible_for_future_purge'::text])))
);


