--
-- Name: revenue_contracts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.revenue_contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text DEFAULT ((('AC-CTR-'::text || to_char((CURRENT_DATE)::timestamp with time zone, 'YYYY'::text)) || '-'::text) || lpad((nextval('public.revenue_contract_reference_seq'::regclass))::text, 6, '0'::text)) NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    contract_type text DEFAULT 'commercial_contract'::text NOT NULL,
    context_type text DEFAULT 'partnership'::text NOT NULL,
    prospect_id text,
    account_id uuid,
    contact_id uuid,
    opportunity_id uuid,
    proposal_id uuid,
    proposal_version_id uuid,
    commercial_outcome_id uuid,
    contract_handoff_id uuid,
    partnership_id text,
    owner text DEFAULT 'Revenue Manager'::text NOT NULL,
    currency text DEFAULT 'MAD'::text NOT NULL,
    contract_value numeric(18,2) DEFAULT 0 NOT NULL,
    signed_value numeric(18,2) DEFAULT 0 NOT NULL,
    realized_value numeric(18,2) DEFAULT 0 NOT NULL,
    review_status text DEFAULT 'not_requested'::text NOT NULL,
    approval_status text DEFAULT 'not_requested'::text NOT NULL,
    signature_status text DEFAULT 'not_prepared'::text NOT NULL,
    effectiveness_status text DEFAULT 'not_ready'::text NOT NULL,
    payment_gate_status text DEFAULT 'not_required'::text NOT NULL,
    activation_status text DEFAULT 'not_ready'::text NOT NULL,
    realization_status text DEFAULT 'not_eligible'::text NOT NULL,
    effective_date date,
    expiry_date date,
    renewal_notice_date date,
    next_action text,
    active_version_id uuid,
    activated_at timestamp with time zone,
    archived_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT revenue_contracts_check CHECK ((realized_value <= GREATEST(contract_value, signed_value))),
    CONSTRAINT revenue_contracts_context_type_check CHECK ((context_type = ANY (ARRAY['prospect'::text, 'partnership'::text, 'system'::text]))),
    CONSTRAINT revenue_contracts_contract_value_check CHECK ((contract_value >= (0)::numeric)),
    CONSTRAINT revenue_contracts_realized_value_check CHECK ((realized_value >= (0)::numeric)),
    CONSTRAINT revenue_contracts_signed_value_check CHECK ((signed_value >= (0)::numeric)),
    CONSTRAINT revenue_contracts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'internal_review'::text, 'approval_required'::text, 'approved'::text, 'signature_preparation'::text, 'signature_pending'::text, 'partially_signed'::text, 'fully_signed'::text, 'conditions_pending'::text, 'effective'::text, 'activation_pending'::text, 'active'::text, 'suspended'::text, 'completed'::text, 'expired'::text, 'terminated'::text, 'superseded'::text, 'archived'::text])))
);


