);


--
-- Name: revenue_contract_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_contract_command_view AS
 SELECT c.id,
    c.reference,
    c.title,
    c.status,
    c.contract_type,
    c.context_type,
    c.prospect_id,
    c.account_id,
    c.contact_id,
    c.opportunity_id,
    c.proposal_id,
    c.proposal_version_id,
    c.commercial_outcome_id,
    c.contract_handoff_id,
    c.partnership_id,
    c.owner,
    c.currency,
    c.contract_value,
    c.signed_value,
    c.realized_value,
    c.review_status,
    c.approval_status,
    c.signature_status,
    c.effectiveness_status,
    c.payment_gate_status,
    c.activation_status,
    c.realization_status,
    c.effective_date,
    c.expiry_date,
    c.renewal_notice_date,
    c.next_action,
    c.active_version_id,
    c.activated_at,
    c.archived_at,
    c.metadata,
    c.version,
    c.created_by,
    c.updated_by,
    c.created_at,
    c.updated_at,
    c.last_activity_at,
    COALESCE(a.account_name, NULLIF(c.partnership_id, ''::text), c.title) AS entity_name,
    a.account_name,
    o.title AS opportunity_title,
    pr.reference AS proposal_reference,
    pv.version_number AS proposal_version_number,
    ( SELECT count(*) AS count
           FROM public.revenue_contract_signatories s
          WHERE ((s.contract_id = c.id) AND s.required)) AS required_signatories,
    ( SELECT count(*) AS count
           FROM public.revenue_contract_signatories s
          WHERE ((s.contract_id = c.id) AND s.required AND (s.status = 'signed'::text))) AS signed_signatories,
    ( SELECT COALESCE(sum(pc.confirmed_amount), (0)::numeric) AS "coalesce"
           FROM public.revenue_payment_confirmations pc
          WHERE ((pc.contract_id = c.id) AND (pc.reconciliation_status = ANY (ARRAY['confirmed'::text, 'partial'::text])))) AS payment_confirmed_value,
    ( SELECT count(*) AS count
           FROM public.revenue_contract_obligations ob
          WHERE ((ob.contract_id = c.id) AND (ob.status <> ALL (ARRAY['completed'::text, 'waived'::text, 'cancelled'::text])) AND (ob.due_at < now()))) AS overdue_obligation_count,
    ( SELECT count(*) AS count
           FROM public.revenue_contract_risks r
          WHERE ((r.contract_id = c.id) AND (r.status = ANY (ARRAY['open'::text, 'monitoring'::text])))) AS open_risk_count
   FROM ((((public.revenue_contracts c
     LEFT JOIN public.revenue_accounts a ON ((a.id = c.account_id)))
     LEFT JOIN public.revenue_opportunities o ON ((o.id = c.opportunity_id)))
     LEFT JOIN public.revenue_proposals pr ON ((pr.id = c.proposal_id)))
     LEFT JOIN public.revenue_proposal_versions pv ON ((pv.id = c.proposal_version_id)));


--
-- Name: revenue_activation_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_activation_command_view AS
 SELECT c.id,
    c.reference,
    c.title,
    c.entity_name,
    c.contract_value,
    c.currency,
    c.status,
    c.signature_status,
    c.effectiveness_status,
    c.payment_gate_status,
    c.activation_status,
    c.realization_status,
    count(g.id) AS gate_count,
    count(g.id) FILTER (WHERE (g.status = 'passed'::text)) AS passed_gate_count,
    count(g.id) FILTER (WHERE (g.status = 'failed'::text)) AS failed_gate_count
   FROM (public.revenue_contract_command_view c
     LEFT JOIN public.revenue_activation_gates g ON ((g.contract_id = c.id)))
  GROUP BY c.id, c.reference, c.title, c.entity_name, c.contract_value, c.currency, c.status, c.signature_status, c.effectiveness_status, c.payment_gate_status, c.activation_status, c.realization_status;


