--
-- Name: revenue_appointment_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_appointment_command_view AS
 SELECT a.id,
    a.workspace_slug,
    a.entity_type,
    a.entity_id,
    a.title,
    a.appointment_at,
    a.owner,
    a.status,
    a.location,
    a.notes,
    a.created_at,
    a.updated_at,
    a.end_at,
    a.appointment_type,
    a.priority,
    a.meeting_link,
    a.agenda,
    a.objective,
    a.expected_outcome,
    a.attendees,
    a.reminders,
    a.documents,
    a.tasks,
    a.tenant_id,
    a.user_id,
    a.metadata,
    a.archived_at,
    a.partnership_id,
    a.prospect_id,
    a.scheduled_at,
    a.outcome,
    a.briefing_notes,
    a.live_notes,
    a.follow_up_at,
    a.duration_minutes,
    a.activity_log,
    p.name AS prospect_name,
    p.company AS prospect_company,
    p.city AS prospect_city,
    p.stage AS prospect_stage,
    p.value_mad AS prospect_value_mad,
    ( SELECT (count(*))::integer AS count
           FROM public.revenue_tasks t
          WHERE ((t.entity_id = a.entity_id) OR (t.prospect_id = a.prospect_id))) AS linked_task_count
   FROM (public.revenue_appointments a
     LEFT JOIN public.revenue_prospects p ON (((p.id = a.prospect_id) OR (p.id = a.entity_id))));


--
-- Name: revenue_appointment_metrics_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_appointment_metrics_view AS
 SELECT (count(*) FILTER (WHERE ((appointment_at)::date = CURRENT_DATE)))::integer AS today_count,
    (count(*) FILTER (WHERE ((appointment_at >= date_trunc('week'::text, now())) AND (appointment_at < (date_trunc('week'::text, now()) + '7 days'::interval)))))::integer AS week_count,
    (count(*) FILTER (WHERE ((appointment_at >= date_trunc('month'::text, now())) AND (appointment_at < (date_trunc('month'::text, now()) + '1 mon'::interval)))))::integer AS month_count,
    (COALESCE(round((((count(*) FILTER (WHERE (status = ANY (ARRAY['confirmed'::text, 'completed'::text]))))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric)), (0)::numeric))::integer AS confirmed_rate,
    (COALESCE(round((((count(*) FILTER (WHERE (status = 'completed'::text)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric)), (0)::numeric))::integer AS conversion_rate,
    (COALESCE(round(avg(duration_minutes)), (0)::numeric))::integer AS avg_duration_minutes,
    (count(*))::integer AS total_count
   FROM public.revenue_appointments
  WHERE (COALESCE(status, ''::text) <> 'archived'::text);


