--
-- Name: revenue_appointment_type_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_appointment_type_view AS
 SELECT COALESCE(appointment_type, 'meeting'::text) AS appointment_type,
    (count(*))::integer AS total,
    (COALESCE(round((((count(*))::numeric / (NULLIF(( SELECT count(*) AS count
           FROM public.revenue_appointments revenue_appointments_1), 0))::numeric) * (100)::numeric)), (0)::numeric))::integer AS pct
   FROM public.revenue_appointments
  GROUP BY COALESCE(appointment_type, 'meeting'::text)
  ORDER BY ((count(*))::integer) DESC;


--
-- Name: revenue_appointment_workload_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_appointment_workload_view AS
 SELECT owner,
    count(*) AS total_appointments,
    count(*) FILTER (WHERE (status = ANY (ARRAY['scheduled'::text, 'confirmation_pending'::text, 'confirmed'::text, 'prepared'::text, 'live'::text]))) AS active_appointments,
    count(*) FILTER (WHERE (status = 'no_show'::text)) AS no_shows,
    count(*) FILTER (WHERE (status = 'converted'::text)) AS converted_appointments,
    count(*) FILTER (WHERE (confirmation_status <> 'confirmed'::text)) AS confirmation_pending,
    COALESCE(sum(commercial_value_mad), (0)::numeric) AS commercial_value_mad
   FROM public.revenue_appointments
  GROUP BY owner;


