--
-- Name: revenue_b2c_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_b2c_command_view AS
 SELECT id,
    tenant_id,
    user_id,
    parent_name,
    child_age_range,
    city,
    service_interest,
    stage,
    intake_status,
    consultation_status,
    quote_status,
    matching_status,
    care_start_status,
    status,
    priority,
    urgency,
    owner,
    estimated_value_mad,
    phone,
    email,
    preferred_channel,
    next_action,
    notes,
    metadata,
    created_at,
    updated_at,
    archived_at,
    family_reference,
    family_name,
    prospect_text_id,
    account_id,
    opportunity_id,
    accepted_proposal_id,
    contract_id,
    operational_handoff_id,
    desired_start_date,
    qualification_status,
    recommendation_status,
    onboarding_status,
    activation_status,
    relationship_status,
    retention_status,
    risk_status,
    satisfaction_score,
    next_action_at,
    last_activity_at,
    created_by,
    updated_by,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_guardians g
          WHERE ((g.b2c_case_id = c.id) AND (g.status = 'active'::text))) AS guardian_count,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_beneficiaries b
          WHERE ((b.b2c_case_id = c.id) AND (b.status = 'active'::text))) AS beneficiary_count,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_complaints q
          WHERE ((q.b2c_case_id = c.id) AND (q.status <> 'closed'::text))) AS open_complaint_count,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_retention_risks r
          WHERE ((r.b2c_case_id = c.id) AND (r.status = 'open'::text))) AS open_retention_risk_count,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_activation_gates g
          WHERE ((g.b2c_case_id = c.id) AND g.mandatory AND (g.result <> 'passed'::text))) AS blocking_gate_count,
    ( SELECT max(s.score) AS max
           FROM public.revenue_b2c_satisfaction_checks s
          WHERE (s.b2c_case_id = c.id)) AS latest_satisfaction_score,
    ( SELECT max(h.created_at) AS max
           FROM public.revenue_b2c_status_history h
          WHERE (h.b2c_case_id = c.id)) AS last_history_at
   FROM public.revenue_b2c_cases c
  WHERE (COALESCE(status, 'active'::text) <> 'archived'::text);


