--
-- Name: revenue_b2c_matching_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_b2c_matching_command_view AS
 SELECT cycle.id,
    cycle.b2c_case_id,
    cycle.requirement_id,
    cycle.rematch_of_cycle_id,
    cycle.selected_candidate_id,
    cycle.target_start_date,
    cycle.matching_owner,
    cycle.selection_criteria,
    cycle.status,
    cycle.closed_at,
    cycle.created_by,
    cycle.updated_by,
    cycle.created_at,
    cycle.updated_at,
    c.family_name,
    c.parent_name,
    c.city,
    c.service_interest,
    c.estimated_value_mad,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_matching_candidates mc
          WHERE (mc.matching_cycle_id = cycle.id)) AS candidate_count,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_matching_candidates mc
          WHERE ((mc.matching_cycle_id = cycle.id) AND (mc.availability_status = 'verified'::text))) AS verified_candidate_count,
    ( SELECT max(mc.overall_fit_score) AS max
           FROM public.revenue_b2c_matching_candidates mc
          WHERE (mc.matching_cycle_id = cycle.id)) AS best_fit_score
   FROM (public.revenue_b2c_matching_cycles cycle
     JOIN public.revenue_b2c_cases c ON ((c.id = cycle.b2c_case_id)));


