--
-- Name: revenue_b2c_retention_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_b2c_retention_command_view AS
 SELECT id AS b2c_case_id,
    family_name,
    parent_name,
    owner,
    estimated_value_mad,
    satisfaction_score,
    retention_status,
    risk_status,
    COALESCE(( SELECT sum(r.value_at_risk_mad) AS sum
           FROM public.revenue_b2c_retention_risks r
          WHERE ((r.b2c_case_id = c.id) AND (r.status = 'open'::text))), (0)::numeric) AS value_at_risk_mad,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_complaints q
          WHERE ((q.b2c_case_id = c.id) AND (q.status <> 'closed'::text))) AS open_complaints,
    ( SELECT count(*) AS count
           FROM public.revenue_b2c_retention_plans p
          WHERE ((p.b2c_case_id = c.id) AND (p.status = 'active'::text))) AS active_plans
   FROM public.revenue_b2c_cases c
  WHERE ((stage = ANY (ARRAY['active'::text, 'retention'::text, 'recovery'::text])) OR (retention_status = ANY (ARRAY['at_risk'::text, 'recovery'::text])));


