--
-- Name: revenue_campaign_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_campaign_command_view WITH (security_invoker='true') AS
 SELECT id,
    tenant_id,
    user_id,
    name,
    audience,
    objective,
    channel,
    budget_mad,
    status,
    priority,
    owner,
    launch_at,
    completed_at,
    performance,
    assets,
    metadata,
    created_at,
    updated_at,
    archived_at,
    reference,
    campaign_type,
    channel_mix,
    owner_id,
    sdr_lead,
    end_at,
    approval_status,
    readiness_status,
    audience_mode,
    attribution_model,
    attribution_window_days,
    frequency_policy,
    strategy,
    risk_status,
    pause_reason,
    emergency_stopped,
    emergency_stopped_at,
    audience_snapshot_id,
    created_by,
    updated_by,
    ( SELECT count(*) AS count
           FROM public.revenue_campaign_recipients r
          WHERE ((r.campaign_id = c.id) AND (r.status <> ALL (ARRAY['removed'::text, 'invalid'::text])))) AS recipient_count,
    ( SELECT count(*) AS count
           FROM public.revenue_campaign_replies r
          WHERE (r.campaign_id = c.id)) AS reply_count,
    ( SELECT count(*) AS count
           FROM public.revenue_campaign_replies r
          WHERE ((r.campaign_id = c.id) AND (r.classification = ANY (ARRAY['positive_interest'::text, 'meeting_request'::text, 'information_request'::text])))) AS positive_reply_count,
    ( SELECT count(*) AS count
           FROM public.revenue_campaign_attribution_conflicts x
          WHERE ((x.campaign_id = c.id) AND (x.status = 'open'::text))) AS open_attribution_conflicts,
    ( SELECT COALESCE(sum(a.attributed_value), (0)::numeric) AS "coalesce"
           FROM public.revenue_campaign_attributions a
          WHERE ((a.campaign_id = c.id) AND (a.event_type = 'revenue_realized'::text) AND (a.status = ANY (ARRAY['active'::text, 'confirmed'::text, 'attributed'::text])))) AS realized_revenue_mad,
    ( SELECT COALESCE(sum(k.amount_mad), (0)::numeric) AS "coalesce"
           FROM public.revenue_campaign_costs k
          WHERE ((k.campaign_id = c.id) AND (k.cost_state = 'confirmed'::text))) AS confirmed_cost_mad
   FROM public.revenue_campaigns c;


