--
-- Name: revenue_campaign_recipient_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_campaign_recipient_command_view WITH (security_invoker='true') AS
 SELECT r.id,
    r.campaign_id,
    r.audience_snapshot_id,
    r.prospect_id,
    r.account_id,
    r.contact_id,
    r.display_name,
    r.channel,
    r.contact_value,
    r.contact_value_normalized,
    r.status,
    r.owner,
    r.owner_id,
    r.current_step_order,
    r.current_sequence_version_id,
    r.communication_thread_id,
    r.eligibility_id,
    r.first_contact_at,
    r.last_action_at,
    r.last_reply_at,
    r.completed_at,
    r.idempotency_key,
    r.metadata,
    r.created_by,
    r.updated_by,
    r.created_at,
    r.updated_at,
    c.name AS campaign_name,
    c.status AS campaign_status,
    e.status AS enrollment_status,
    e.current_step_order AS enrollment_step_order,
    ( SELECT max(x.scheduled_at) AS max
           FROM public.revenue_campaign_step_executions x
          WHERE ((x.campaign_recipient_id = r.id) AND (x.status = ANY (ARRAY['scheduled'::text, 'due'::text, 'overdue'::text])))) AS next_step_at,
    ( SELECT count(*) AS count
           FROM public.revenue_campaign_replies q
          WHERE (q.campaign_recipient_id = r.id)) AS reply_count
   FROM ((public.revenue_campaign_recipients r
     JOIN public.revenue_campaigns c ON ((c.id = r.campaign_id)))
     LEFT JOIN LATERAL ( SELECT z.id,
            z.campaign_id,
            z.campaign_recipient_id,
            z.sequence_id,
            z.sequence_version_id,
            z.status,
            z.current_step_order,
            z.entered_at,
            z.paused_at,
            z.completed_at,
            z.exit_reason,
            z.idempotency_key,
            z.created_by,
            z.updated_by,
            z.created_at,
            z.updated_at
           FROM public.revenue_campaign_enrollments z
          WHERE (z.campaign_recipient_id = r.id)
          ORDER BY z.created_at DESC
         LIMIT 1) e ON (true));


