--
-- Name: revenue_communication_thread_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_communication_thread_view AS
 SELECT id,
    subject,
    channel_scope,
    status,
    prospect_id,
    account_id,
    contact_id,
    opportunity_id,
    appointment_id,
    owner_id,
    owner_name,
    waiting_since,
    next_follow_up_at,
    closed_at,
    metadata,
    created_at,
    updated_at,
    ( SELECT count(*) AS count
           FROM public.revenue_communication_events e
          WHERE (e.thread_id = t.id)) AS event_count,
    ( SELECT max(e.occurred_at) AS max
           FROM public.revenue_communication_events e
          WHERE (e.thread_id = t.id)) AS last_event_at,
    ( SELECT e.channel
           FROM public.revenue_communication_events e
          WHERE (e.thread_id = t.id)
          ORDER BY e.occurred_at DESC
         LIMIT 1) AS last_channel,
    ( SELECT e.body_summary
           FROM public.revenue_communication_events e
          WHERE (e.thread_id = t.id)
          ORDER BY e.occurred_at DESC
         LIMIT 1) AS last_summary
   FROM public.revenue_communication_threads t;


