--
-- Name: revenue_daily_task_metrics_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_daily_task_metrics_view AS
 SELECT (count(*))::integer AS total_tasks,
    (count(*) FILTER (WHERE (status = ANY (ARRAY['done'::text, 'completed'::text]))))::integer AS completed_tasks,
    (count(*) FILTER (WHERE (status = ANY (ARRAY['in_progress'::text, 'doing'::text]))))::integer AS in_progress_tasks,
    (count(*) FILTER (WHERE (status = ANY (ARRAY['open'::text, 'pending'::text, 'todo'::text, 'active'::text]))))::integer AS pending_tasks,
    (count(*) FILTER (WHERE ((due_date < now()) AND (status <> ALL (ARRAY['done'::text, 'completed'::text, 'archived'::text])))))::integer AS overdue_tasks,
    (count(*) FILTER (WHERE ((due_date >= now()) AND (due_date < (now() + '7 days'::interval)))))::integer AS next_7_days,
    (COALESCE(round((((count(*) FILTER (WHERE (status = ANY (ARRAY['done'::text, 'completed'::text]))))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric)), (0)::numeric))::integer AS completion_rate
   FROM public.revenue_tasks
  WHERE (COALESCE(status, ''::text) <> 'archived'::text);


