--
-- Name: revenue_engagement_appointment_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_engagement_appointment_view AS
 SELECT a.id,
    a.workspace_slug,
    a.entity_type,
    a.entity_id,
    a.title,
    a.appointment_at,
    a.owner,
    a.status,
    a.location,
    a.notes,
    a.created_at,
    a.updated_at,
    a.end_at,
    a.appointment_type,
    a.priority,
    a.meeting_link,
    a.agenda,
    a.objective,
    a.expected_outcome,
    a.attendees,
    a.reminders,
    a.documents,
    a.tasks,
    a.tenant_id,
    a.user_id,
    a.metadata,
    a.archived_at,
    a.partnership_id,
    a.prospect_id,
    a.scheduled_at,
    a.outcome,
    a.briefing_notes,
    a.live_notes,
    a.follow_up_at,
    a.duration_minutes,
    a.activity_log,
    a.opportunity_id,
    a.account_id,
    a.contact_id,
    a.timezone,
    a.confirmation_status,
    a.preparation_status,
    a.confirmed_at,
    a.completed_at,
    a.cancelled_at,
    a.no_show_risk,
    a.commercial_value_mad,
    a.outcome_code,
    a.version,
    a.created_by,
    a.updated_by,
    COALESCE(ac.account_name, p.name, o.title, 'Dossier commercial'::text) AS entity_name,
    ac.account_name,
    o.title AS opportunity_title,
    c.full_name AS primary_contact_name,
    c.email AS primary_contact_email,
    c.phone AS primary_contact_phone,
    COALESCE(ac.city, p.city) AS entity_city,
    COALESCE(o.stage, p.stage) AS entity_stage,
    COALESCE(o.priority, p.priority, a.priority) AS entity_priority,
    ( SELECT count(*) AS count
           FROM public.revenue_appointment_participants ap
          WHERE (ap.appointment_id = a.id)) AS participant_count,
    ( SELECT count(*) AS count
           FROM public.revenue_appointment_participants ap
          WHERE ((ap.appointment_id = a.id) AND (ap.confirmation_status = 'confirmed'::text))) AS confirmed_participant_count,
    ( SELECT count(*) AS count
           FROM public.revenue_meeting_preparation_items pi
          WHERE ((pi.appointment_id = a.id) AND (pi.status = 'completed'::text))) AS preparation_done_count,
    ( SELECT count(*) AS count
           FROM public.revenue_meeting_preparation_items pi
          WHERE (pi.appointment_id = a.id)) AS preparation_total_count,
    ( SELECT count(*) AS count
           FROM public.revenue_meeting_objections mo
          WHERE (mo.appointment_id = a.id)) AS objection_count,
    ( SELECT count(*) AS count
           FROM public.revenue_meeting_commitments mc
          WHERE (mc.appointment_id = a.id)) AS commitment_count,
    ( SELECT count(*) AS count
           FROM public.revenue_meeting_commitments mc
          WHERE ((mc.appointment_id = a.id) AND (mc.status <> ALL (ARRAY['completed'::text, 'cancelled'::text])))) AS open_commitment_count,
    ( SELECT count(*) AS count
           FROM public.revenue_communication_events ce
          WHERE (ce.appointment_id = a.id)) AS communication_count,
    ( SELECT count(*) AS count
           FROM public.revenue_appointment_recovery_attempts ra
          WHERE (ra.appointment_id = a.id)) AS recovery_attempt_count
   FROM ((((public.revenue_appointments a
     LEFT JOIN public.revenue_prospects p ON ((p.id = COALESCE(a.prospect_id, a.entity_id))))
     LEFT JOIN public.revenue_accounts ac ON ((ac.id = a.account_id)))
     LEFT JOIN public.revenue_opportunities o ON ((o.id = a.opportunity_id)))
     LEFT JOIN public.revenue_contacts c ON ((c.id = a.contact_id)));


--
-- Name: VIEW revenue_engagement_appointment_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.revenue_engagement_appointment_view IS 'Canonical read model for ANGELCARE Revenue Command communications, appointments, meetings and conversion.';


