--
-- Name: revenue_execution_portfolio_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_execution_portfolio_view AS
 SELECT t.id,
    t.workspace_slug,
    t.entity_type,
    t.entity_id,
    t.title,
    t.description,
    t.owner,
    t.priority,
    t.status,
    t.due_date,
    t.completed_at,
    t.created_at,
    t.updated_at,
    t.start_at,
    t.end_at,
    t.task_type,
    t.department,
    t.assigned_role,
    t.location,
    t.outcome_expected,
    t.escalation_rule,
    t.dependencies,
    t.tags,
    t.visibility,
    t.reminder_minutes,
    t.add_to_calendar,
    t.send_notifications,
    t.status_label,
    t.prospect_id,
    t.blocked_reason,
    t.approval_status,
    t.completion_notes,
    t.metadata,
    t.archived_at,
    t.tenant_id,
    t.user_id,
    t.partnership_id,
    t.assigned_owner,
    t.notes,
    t.expected_outcome,
    t.activity_log,
    t.opportunity_id,
    t.due_at,
    t.assigned_user_id,
    t.completion_outcome,
    t.evidence_required,
    t.approval_required,
    t.sla_due_at,
    t.estimated_minutes,
    t.actual_minutes,
    t.created_by,
    t.updated_by,
    t.version,
    COALESCE(p.name, a.account_name, o.title, NULLIF(t.entity_name, ''::text), t.entity_id, 'Aucune entité'::text) AS entity_name,
    o.title AS opportunity_title,
    COALESCE(o.value_mad, p.value_mad, (0)::numeric) AS commercial_value_mad,
    (( SELECT count(*) AS count
           FROM public.revenue_task_checklist_items c
          WHERE (c.task_id = t.id)))::integer AS checklist_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_checklist_items c
          WHERE ((c.task_id = t.id) AND (c.completed_at IS NOT NULL))))::integer AS checklist_done_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_dependencies d
          WHERE (d.task_id = t.id)))::integer AS dependency_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_dependencies d
          WHERE ((d.task_id = t.id) AND (d.satisfied_at IS NULL))))::integer AS unresolved_dependency_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_evidence e
          WHERE (e.task_id = t.id)))::integer AS evidence_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_approval_requests r
          WHERE ((r.task_id = t.id) AND (r.status = ANY (ARRAY['pending'::text, 'requested'::text, 'clarification_required'::text])))))::integer AS pending_approval_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_blockers b
          WHERE ((b.task_id = t.id) AND (b.resolved_at IS NULL))))::integer AS blocker_count,
    (( SELECT count(*) AS count
           FROM public.revenue_task_escalations x
          WHERE ((x.task_id = t.id) AND (x.resolved_at IS NULL))))::integer AS escalation_count
   FROM (((public.revenue_tasks t
     LEFT JOIN public.revenue_prospects p ON ((p.id = COALESCE(t.prospect_id,
        CASE
            WHEN (t.entity_type = 'prospect'::text) THEN t.entity_id
            ELSE NULL::text
        END))))
     LEFT JOIN public.revenue_accounts a ON (((a.id)::text =
        CASE
            WHEN (t.entity_type = 'account'::text) THEN t.entity_id
            ELSE NULL::text
        END)))
     LEFT JOIN public.revenue_opportunities o ON (((o.id)::text =
        CASE
            WHEN (t.entity_type = 'opportunity'::text) THEN t.entity_id
            ELSE NULL::text
        END)));


