 SELECT l.id,
    l.snapshot_id,
    l.source_entity_type,
    l.source_entity_id,
    l.source_label,
    l.source_stage,
    l.owner_label,
    l.system_category,
    l.owner_category,
    l.executive_category,
    l.effective_category,
    l.system_amount_mad,
    l.owner_amount_mad,
    l.executive_amount_mad,
    l.effective_amount_mad,
    l.probability,
    l.confidence,
    l.evidence_score,
    l.system_expected_date,
    l.owner_expected_date,
    l.executive_expected_date,
    l.effective_expected_date,
    l.last_activity_at,
    l.rationale,
    l.blockers,
    l.evidence,
    l.metadata,
    l.created_at,
    l.updated_at,
    s.snapshot_key,
    s.label AS snapshot_label,
    s.horizon,
    s.period_start,
    s.period_end,
    s.status AS snapshot_status
   FROM (public.revenue_executive_forecast_lines l
     JOIN public.revenue_executive_forecast_snapshots s ON ((s.id = l.snapshot_id)));


