    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    closed_at timestamp with time zone,
    CONSTRAINT revenue_executive_interventions_status_check CHECK ((status = ANY (ARRAY['detected'::text, 'triage'::text, 'analysis'::text, 'decision_required'::text, 'approved_action'::text, 'in_execution'::text, 'monitoring'::text, 'escalated'::text, 'resolved'::text, 'closed'::text, 'rejected'::text, 'deferred'::text, 'cancelled'::text])))
);


--
-- Name: revenue_executive_intervention_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_executive_intervention_command_view WITH (security_invoker='true') AS
 SELECT i.id,
    i.intervention_key,
    i.source_entity_type,
    i.source_entity_id,
    i.title,
    i.root_cause,
    i.affected_value_mad,
    i.severity,
    i.priority_score,
    i.owner_label,
    i.executive_sponsor_label,
    i.due_at,
    i.decision_required,
    i.required_outcome,
    i.status,
    i.evidence_reference,
    i.metadata,
    i.created_by,
    i.updated_by,
    i.created_at,
    i.updated_at,
    i.closed_at,
    COALESCE(o.protected_value_mad, (0)::numeric) AS protected_value_mad,
    COALESCE(o.recovered_value_mad, (0)::numeric) AS recovered_value_mad,
    COALESCE(o.lost_value_mad, (0)::numeric) AS lost_value_mad,
    o.outcome,
    o.evidence_reference AS closure_evidence_reference
   FROM (public.revenue_executive_interventions i
     LEFT JOIN public.revenue_executive_intervention_outcomes o ON ((o.intervention_id = i.id)));


