--
-- Name: revenue_proposal_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_proposal_command_view AS
 SELECT p.id,
    p.reference,
    p.title,
    p.status,
    p.proposal_type,
    p.context_type,
    p.prospect_id,
    p.account_id,
    p.contact_id,
    p.opportunity_id,
    p.meeting_outcome_id,
    p.partnership_id,
    p.b2c_case_id,
    p.owner,
    p.currency,
    p.gross_value,
    p.discount_value,
    p.discount_percent,
    p.net_value,
    p.estimated_cost,
    p.gross_margin,
    p.margin_percent,
    p.minimum_margin_percent,
    p.approval_status,
    p.recipient_status,
    p.negotiation_status,
    p.commercial_objective,
    p.client_need,
    p.next_action,
    p.validity_until,
    p.accepted_at,
    p.rejected_at,
    p.active_version_id,
    p.active_pricing_scenario_id,
    p.last_activity_at,
    p.archived_at,
    p.version,
    p.metadata,
    p.created_by,
    p.updated_by,
    p.created_at,
    p.updated_at,
    COALESCE(a.legal_name, a.account_name, pr.company, pr.name, p.partnership_id, p.b2c_case_id, 'Dossier commercial'::text) AS entity_name,
    COALESCE(a.legal_name, a.account_name) AS account_name,
    o.title AS opportunity_title,
    c.full_name AS primary_contact_name,
    c.email AS primary_contact_email,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_proposal_versions v
          WHERE (v.proposal_id = p.id)), (0)::bigint) AS version_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_proposal_line_items l
          WHERE ((l.proposal_id = p.id) AND (l.proposal_version_id IS NULL))), (0)::bigint) AS line_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_proposal_approval_requests ar
          WHERE ((ar.proposal_id = p.id) AND (ar.status = 'requested'::text))), (0)::bigint) AS pending_approval_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_proposal_objections ob
          WHERE ((ob.proposal_id = p.id) AND (ob.resolution_status <> ALL (ARRAY['resolved'::text, 'closed'::text])))), (0)::bigint) AS open_objection_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_concession_requests cr
          WHERE ((cr.proposal_id = p.id) AND (cr.status = ANY (ARRAY['requested'::text, 'pending'::text])))), (0)::bigint) AS pending_concession_count
   FROM ((((public.revenue_proposals p
     LEFT JOIN public.revenue_accounts a ON ((a.id = p.account_id)))
     LEFT JOIN public.revenue_opportunities o ON ((o.id = p.opportunity_id)))
     LEFT JOIN public.revenue_contacts c ON ((c.id = p.contact_id)))
     LEFT JOIN public.revenue_prospects pr ON ((pr.id = p.prospect_id)));


--
-- Name: revenue_negotiation_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_negotiation_command_view AS
 SELECT n.id,
    n.proposal_id,
    n.proposal_version_id,
    n.title,
    n.status,
    n.current_round,
    n.angelcare_position_value,
    n.customer_position_value,
    n.current_margin_percent,
    n.opening_position,
    n.decision_deadline,
    n.owner,
    n.version,
    n.created_by,
    n.updated_by,
    n.created_at,
    n.updated_at,
    n.closed_at,
    p.reference,
    p.title AS proposal_title,
    p.entity_name,
    p.net_value,
    p.margin_percent,
    p.minimum_margin_percent,
    p.validity_until,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_proposal_objections o
          WHERE ((o.negotiation_id = n.id) AND (o.resolution_status <> ALL (ARRAY['resolved'::text, 'closed'::text])))), (0)::bigint) AS open_objection_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.revenue_concession_requests c
          WHERE ((c.negotiation_id = n.id) AND (c.status = ANY (ARRAY['requested'::text, 'pending'::text])))), (0)::bigint) AS pending_concession_count
   FROM (public.revenue_negotiations n
     JOIN public.revenue_proposal_command_view p ON ((p.id = n.proposal_id)));


