--
-- Name: revenue_os_cockpit_execution_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_os_cockpit_execution_summary AS
 SELECT tenant_id,
    count(*) FILTER (WHERE (status = ANY (ARRAY['draft'::text, 'validated'::text]))) AS prepared,
    count(*) FILTER (WHERE (status = 'awaiting_approval'::text)) AS awaiting_approval,
    count(*) FILTER (WHERE (status = ANY (ARRAY['queued'::text, 'leased'::text, 'executing'::text]))) AS in_flight,
    count(*) FILTER (WHERE (status = 'succeeded'::text)) AS succeeded,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed,
    count(*) FILTER (WHERE (status = 'dead_letter'::text)) AS dead_letters,
    count(*) FILTER (WHERE ((status = 'succeeded'::text) AND (external_action = true))) AS external_actions_executed,
    max(updated_at) AS last_updated_at
   FROM public.revenue_os_execution_actions
  GROUP BY tenant_id;


