    organization_id uuid,
    tenant_id uuid,
    command_code text NOT NULL,
    name text NOT NULL,
    family_code text NOT NULL,
    purpose text NOT NULL,
    owner_role text NOT NULL,
    status text NOT NULL,
    active_version text NOT NULL,
    business_units jsonb DEFAULT '[]'::jsonb NOT NULL,
    segments jsonb DEFAULT '[]'::jsonb NOT NULL,
    territories jsonb DEFAULT '[]'::jsonb NOT NULL,
    commercial_stages jsonb DEFAULT '[]'::jsonb NOT NULL,
    trigger_types jsonb DEFAULT '[]'::jsonb NOT NULL,
    eligibility_rules jsonb DEFAULT '[]'::jsonb NOT NULL,
    required_context jsonb DEFAULT '[]'::jsonb NOT NULL,
    optional_context jsonb DEFAULT '[]'::jsonb NOT NULL,
    tool_permissions jsonb DEFAULT '[]'::jsonb NOT NULL,
    input_schema jsonb DEFAULT '[]'::jsonb NOT NULL,
    output_schema jsonb DEFAULT '[]'::jsonb NOT NULL,
    validator_chain jsonb DEFAULT '[]'::jsonb NOT NULL,
    approval_class text NOT NULL,
    downstream_compiler text,
    cooldown_policy jsonb NOT NULL,
    retry_policy jsonb NOT NULL,
    failure_policy jsonb NOT NULL,
    fallback_command_codes jsonb DEFAULT '[]'::jsonb NOT NULL,
    performance_metrics jsonb DEFAULT '[]'::jsonb NOT NULL,
    prohibited_cases jsonb DEFAULT '[]'::jsonb NOT NULL,
    expected_outcomes jsonb DEFAULT '[]'::jsonb NOT NULL,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT revenue_os_command_definitions_approval_class_check CHECK ((approval_class = ANY (ARRAY['none'::text, 'recommendation'::text, 'internal-generation'::text, 'supervisor'::text, 'department'::text, 'director'::text, 'executive'::text, 'prohibited'::text]))),
    CONSTRAINT revenue_os_command_definitions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'proposed'::text, 'under-review'::text, 'needs-evidence'::text, 'needs-approval'::text, 'approved'::text, 'rejected'::text, 'scheduled'::text, 'running'::text, 'paused'::text, 'blocked'::text, 'failed'::text, 'retrying'::text, 'completed'::text, 'superseded'::text, 'retired'::text, 'rolled-back'::text, 'audited'::text])))
);


