--
-- Name: revenue_os_command_library_active; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_os_command_library_active WITH (security_invoker='true') AS
 SELECT id,
    organization_id,
    tenant_id,
    command_code,
    name,
    family_code,
    purpose,
    owner_role,
    status,
    active_version,
    business_units,
    segments,
    territories,
    commercial_stages,
    trigger_types,
    eligibility_rules,
    required_context,
    optional_context,
    tool_permissions,
    input_schema,
    output_schema,
    validator_chain,
    approval_class,
    downstream_compiler,
    cooldown_policy,
    retry_policy,
    failure_policy,
    fallback_command_codes,
    performance_metrics,
    prohibited_cases,
    expected_outcomes,
    tags,
    created_at,
    updated_at,
    created_by,
    updated_by
   FROM public.revenue_os_command_definitions
  WHERE ((status = 'approved'::text) AND ((tags ? 'golden-300'::text) OR (tags ? 'new-700'::text) OR (tags ? 'new-1000'::text) OR (tags ? 'final-1000'::text)));


