    CONSTRAINT revenue_os_signals_opportunity_score_check CHECK (((opportunity_score >= 0) AND (opportunity_score <= 100))),
    CONSTRAINT revenue_os_signals_priority_score_check CHECK (((priority_score >= 0) AND (priority_score <= 100))),
    CONSTRAINT revenue_os_signals_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT revenue_os_signals_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text, 'info'::text]))),
    CONSTRAINT revenue_os_signals_status_check CHECK ((status = ANY (ARRAY['new'::text, 'triaged'::text, 'acknowledged'::text, 'context-ready'::text, 'monitoring'::text, 'resolved'::text, 'dismissed'::text, 'blocked'::text]))),
    CONSTRAINT revenue_os_signals_urgency_score_check CHECK (((urgency_score >= 0) AND (urgency_score <= 100)))
);


