--
-- Name: revenue_partner_performance_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_partner_performance_command_view AS
 SELECT pp.id,
    pp.partnership_id,
    pp.program_id,
    pp.period_start,
    pp.period_end,
    pp.status,
    pp.target_referrals,
    pp.target_qualified_referrals,
    pp.target_meetings,
    pp.target_contracts,
    pp.target_realized_mad,
    pp.closed_at,
    pp.created_by,
    pp.updated_by,
    pp.created_at,
    pp.updated_at,
    p.partner_name,
    sc.overall_score,
    sc.performance_status,
    sc.referral_count,
    sc.qualified_referral_count,
    sc.attributed_referral_count,
    sc.meeting_count,
    sc.contract_count,
    sc.realized_revenue_mad
   FROM ((public.revenue_partner_performance_periods pp
     JOIN public.revenue_partnerships p ON ((p.id = pp.partnership_id)))
     LEFT JOIN public.revenue_partner_scorecards sc ON ((sc.performance_period_id = pp.id)));


