--
-- Name: revenue_partner_referral_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_partner_referral_command_view AS
 SELECT r.id,
    r.partnership_id,
    r.program_id,
    r.source_contact_id,
    r.referred_name,
    r.referred_type,
    r.email,
    r.normalized_email,
    r.phone,
    r.normalized_phone,
    r.service_interest,
    r.consent_status,
    r.owner,
    r.territory,
    r.estimated_value_mad,
    r.status,
    r.received_at,
    r.duplicate_of_referral_id,
    r.linked_prospect_id,
    r.linked_opportunity_id,
    r.source_evidence,
    r.metadata,
    r.created_by,
    r.updated_by,
    r.created_at,
    r.updated_at,
    p.partner_name,
    o.title AS opportunity_title,
    (COALESCE(( SELECT sum(at.attributed_value) AS sum
           FROM public.revenue_partner_referral_attributions at
          WHERE ((at.referral_id = r.id) AND (at.status = ANY (ARRAY['confirmed'::text, 'attributed'::text, 'active'::text])))), (0)::numeric))::numeric(18,2) AS attributed_value_mad,
    (COALESCE(( SELECT count(*) AS count
           FROM public.revenue_partner_attribution_conflicts c
          WHERE ((c.referral_id = r.id) AND (c.status = 'open'::text))), (0)::bigint))::integer AS open_conflict_count
   FROM ((public.revenue_partner_referrals r
     JOIN public.revenue_partnerships p ON ((p.id = r.partnership_id)))
     LEFT JOIN public.revenue_opportunities o ON ((o.id = r.linked_opportunity_id)));


