--
-- Name: revenue_partnership_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_partnership_command_view AS
 SELECT p.id,
    p.name,
    p.organization,
    p.city,
    p.kind,
    p.status,
    p.owner,
    p.contact_name,
    p.phone,
    p.email,
    p.value_mad,
    p.probability,
    p.health_score,
    p.referral_potential,
    p.next_action,
    p.context,
    p.source_prospect_id,
    p.created_by,
    p.updated_by,
    p.created_at,
    p.updated_at,
    p.partner_name,
    p.company,
    p.segment,
    p.partner_type,
    p.tier,
    p.stage,
    p.pipeline_value,
    p.revenue_ytd,
    p.decision_maker,
    p.notes,
    p.owner_id,
    p.prospect_id,
    p.task_id,
    p.appointment_id,
    p.tenant_id,
    p.user_id,
    p.priority,
    p.metadata,
    p.archived_at,
    p.location,
    p.partnership_type,
    p.potential_value_mad,
    p.pipeline_value_mad,
    p.contract_status,
    p.next_action_at,
    p.relationship_notes,
    p.category,
    p.website,
    p.contract_value_mad,
    p.payment_terms,
    p.commission_rate,
    p.programs,
    p.program_details,
    p.offer_parameters,
    p.pricing_parameters,
    p.management_controls,
    p.type_icon,
    p.documents,
    p.tags,
    p.partner_contacts,
    p.linked_programs,
    p.linked_contracts,
    p.linked_offers,
    p.transactions,
    p.invoices,
    p.communications,
    p.team_members,
    p.activity_log,
    p.contract_checklist,
    p.contract_checklist_done,
    p.raw,
    p.source,
    p.source_id,
    p.type,
    p.icon_key,
    p.district,
    p.engagement,
    p.summary,
    p.source_prospect_key,
    p.estimated_value_mad,
    p.partner_category,
    p.partner_icon,
    p.account_id,
    p.prospect_text_id,
    p.sector,
    p.territory,
    p.strategic_tier,
    p.qualification_status,
    p.activation_status,
    p.health_status,
    p.contract_id,
    p.renewal_date,
    p.last_activity_at,
    p.attributed_pipeline_mad,
    p.attributed_realized_mad,
    COALESCE(NULLIF(p.partner_name, ''::text), NULLIF(a.account_name, ''::text), 'Partenaire ANGELCARE'::text) AS entity_name,
    (COALESCE(( SELECT count(*) AS count
           FROM public.revenue_partner_referrals r
          WHERE (r.partnership_id = p.id)), (0)::bigint))::integer AS referral_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.revenue_partner_referral_attributions at
          WHERE ((at.partnership_id = p.id) AND (at.status = ANY (ARRAY['confirmed'::text, 'attributed'::text, 'active'::text])))), (0)::bigint))::integer AS attributed_referral_count,
    (COALESCE(( SELECT sum(at.attributed_value) AS sum
           FROM public.revenue_partner_referral_attributions at
          WHERE ((at.partnership_id = p.id) AND (at.event_type = 'revenue_realized'::text) AND (at.status = ANY (ARRAY['confirmed'::text, 'attributed'::text, 'active'::text])))), (0)::numeric))::numeric(18,2) AS realized_value_mad,
    (COALESCE(( SELECT count(*) AS count
           FROM public.revenue_partnership_risks rk
          WHERE ((rk.partnership_id = p.id) AND (rk.status <> ALL (ARRAY['resolved'::text, 'closed'::text, 'accepted'::text])))), (0)::bigint))::integer AS open_risk_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.revenue_partnership_obligations ob
          WHERE ((ob.partnership_id = p.id) AND (ob.status <> ALL (ARRAY['completed'::text, 'cancelled'::text, 'waived'::text])))), (0)::bigint))::integer AS open_obligation_count,
    GREATEST(COALESCE(p.last_activity_at, p.updated_at, p.created_at), COALESCE(( SELECT max(r.received_at) AS max
           FROM public.revenue_partner_referrals r
          WHERE (r.partnership_id = p.id)), p.created_at)) AS last_activity_effective
   FROM (public.revenue_partnerships p
     LEFT JOIN public.revenue_accounts a ON ((a.id = p.account_id)));


