--
-- Name: revenue_prospect_enterprise_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_prospect_enterprise_overview AS
 SELECT p.id AS prospect_id,
    p.name AS prospect_name,
    p.company,
    p.city,
    p.stage AS prospect_stage,
    p.priority,
    p.score,
    p.value_mad AS prospect_value_mad,
    p.probability AS prospect_probability,
    p.owner,
    p.contact_name,
    p.email,
    p.phone,
    p.next_action_at,
    p.last_activity_at,
    p.status AS prospect_status,
    p.account_id,
    a.account_name,
    a.legal_name,
    a.account_type,
    a.segment AS account_segment,
    a.lifecycle_stage,
    a.industry,
    a.website,
    a.domain,
    a.status AS account_status,
    p.contact_id,
    c.full_name AS primary_contact_name,
    c.role_title AS primary_contact_role,
    c.decision_role AS primary_contact_decision_role,
    c.influence_level AS primary_contact_influence,
    COALESCE(opp_stats.opportunity_count, 0) AS opportunity_count,
    COALESCE(opp_stats.open_opportunity_value_mad, (0)::numeric) AS open_opportunity_value_mad,
    COALESCE(opp_stats.weighted_pipeline_mad, (0)::numeric) AS weighted_pipeline_mad,
    COALESCE(task_stats.open_task_count, 0) AS open_task_count,
    COALESCE(task_stats.overdue_task_count, 0) AS overdue_task_count,
    COALESCE(meeting_stats.upcoming_meeting_count, 0) AS upcoming_meeting_count,
    COALESCE(risk_stats.open_risk_count, 0) AS open_risk_count,
    COALESCE(decision_stats.decision_member_count, 0) AS decision_member_count,
    p.updated_at
   FROM (((((((public.revenue_prospects p
     LEFT JOIN public.revenue_accounts a ON ((a.id = p.account_id)))
     LEFT JOIN public.revenue_contacts c ON ((c.id = p.contact_id)))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS opportunity_count,
            COALESCE(sum(o.value_mad) FILTER (WHERE ((o.status = 'open'::text) AND (o.archived_at IS NULL))), (0)::numeric) AS open_opportunity_value_mad,
            COALESCE(sum(((o.value_mad * o.probability) / 100.0)) FILTER (WHERE ((o.status = 'open'::text) AND (o.archived_at IS NULL))), (0)::numeric) AS weighted_pipeline_mad
           FROM public.revenue_opportunities o
          WHERE (o.prospect_id = p.id)) opp_stats ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (t.status = ANY (ARRAY['open'::text, 'pending'::text, 'todo'::text]))))::integer AS open_task_count,
            (count(*) FILTER (WHERE ((t.status = ANY (ARRAY['open'::text, 'pending'::text, 'todo'::text])) AND (t.due_date < now()))))::integer AS overdue_task_count
           FROM public.revenue_tasks t
          WHERE ((t.prospect_id = p.id) OR ((t.entity_type = 'prospect'::text) AND (t.entity_id = p.id)))) task_stats ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE ((ap.status = 'scheduled'::text) AND (ap.appointment_at >= now()))))::integer AS upcoming_meeting_count
           FROM public.revenue_appointments ap
          WHERE ((ap.prospect_id = p.id) OR ((ap.entity_type = 'prospect'::text) AND (ap.entity_id = p.id)))) meeting_stats ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (r.status = 'open'::text)))::integer AS open_risk_count
           FROM public.revenue_account_risks r
          WHERE ((r.prospect_id = p.id) OR ((p.account_id IS NOT NULL) AND (r.account_id = p.account_id)))) risk_stats ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*) FILTER (WHERE (dm.status = 'active'::text)))::integer AS decision_member_count
           FROM public.revenue_decision_map_members dm
          WHERE ((dm.prospect_id = p.id) OR ((p.account_id IS NOT NULL) AND (dm.account_id = p.account_id)))) decision_stats ON (true))
  WHERE (p.status IS DISTINCT FROM 'archived'::text);


--
-- Name: VIEW revenue_prospect_enterprise_overview; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.revenue_prospect_enterprise_overview IS 'Canonical read model for ANGELCARE Revenue Command prospects, accounts, contacts, opportunities, tasks, meetings, risks and decision maps.';


