    CONSTRAINT revenue_qualification_assessments_evidence_quality_check CHECK (((evidence_quality >= (0)::numeric) AND (evidence_quality <= (100)::numeric))),
    CONSTRAINT revenue_qualification_assessments_fit_score_check CHECK (((fit_score >= (0)::numeric) AND (fit_score <= (100)::numeric))),
    CONSTRAINT revenue_qualification_assessments_need_score_check CHECK (((need_score >= (0)::numeric) AND (need_score <= (100)::numeric))),
