);


--
-- Name: revenue_realization_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_realization_command_view AS
 SELECT c.id,
    c.reference,
    c.title,
    c.entity_name,
    c.contract_value,
    c.realized_value,
    c.currency,
    c.activation_status,
    c.realization_status,
    COALESCE(sum(pc.confirmed_amount), (0)::numeric) AS payment_confirmed_value,
    GREATEST((0)::numeric, (c.contract_value - c.realized_value)) AS remaining_realizable_value
   FROM (public.revenue_contract_command_view c
     LEFT JOIN public.revenue_payment_confirmations pc ON (((pc.contract_id = c.id) AND (pc.reconciliation_status = ANY (ARRAY['confirmed'::text, 'partial'::text])))))
  GROUP BY c.id, c.reference, c.title, c.entity_name, c.contract_value, c.realized_value, c.currency, c.activation_status, c.realization_status;


