    realized_at timestamp with time zone DEFAULT now() NOT NULL,
    realized_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT revenue_realization_events_status_check CHECK ((status = ANY (ARRAY['eligible'::text, 'realized'::text, 'partially_realized'::text, 'reversed'::text, 'rejected'::text])))
);


--
-- Name: revenue_sdr_campaign_queue_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_sdr_campaign_queue_view WITH (security_invoker='true') AS
 SELECT x.id,
    x.campaign_id,
    x.campaign_recipient_id,
    x.enrollment_id,
    x.sequence_step_id,
    x.step_order,
    x.step_type,
    x.channel,
    x.owner,
    x.status,
    x.priority_score,
    x.scheduled_at,
    x.due_at,
    x.attempt_count,
    x.last_error,
    r.display_name,
    r.contact_value,
    r.prospect_id,
    r.contact_id,
    r.status AS recipient_status,
    c.name AS campaign_name,
    c.priority AS campaign_priority
   FROM ((public.revenue_campaign_step_executions x
     JOIN public.revenue_campaign_recipients r ON ((r.id = x.campaign_recipient_id)))
     JOIN public.revenue_campaigns c ON ((c.id = x.campaign_id)))
  WHERE (x.status = ANY (ARRAY['scheduled'::text, 'due'::text, 'overdue'::text, 'manual_review'::text]));


