--
-- Name: revenue_task_category_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_task_category_view AS
 SELECT COALESCE(task_type, 'follow_up'::text) AS task_type,
    (count(*))::integer AS total_tasks,
    (COALESCE(round((((count(*))::numeric / (NULLIF(( SELECT count(*) AS count
           FROM public.revenue_tasks revenue_tasks_1), 0))::numeric) * (100)::numeric)), (0)::numeric))::integer AS pct
   FROM public.revenue_tasks
  GROUP BY COALESCE(task_type, 'follow_up'::text)
  ORDER BY ((count(*))::integer) DESC;


--
-- Name: revenue_task_command_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_task_command_view AS
 SELECT t.id,
    t.workspace_slug,
    t.entity_type,
    t.entity_id,
    t.title,
    t.description,
    t.owner,
    t.priority,
    t.status,
    t.due_date,
    t.completed_at,
    t.created_at,
    t.updated_at,
    t.start_at,
    t.end_at,
    t.task_type,
    t.department,
    t.assigned_role,
    t.location,
    t.outcome_expected,
    t.escalation_rule,
    t.dependencies,
    t.tags,
    t.visibility,
    t.reminder_minutes,
    t.add_to_calendar,
    t.send_notifications,
    t.status_label,
    t.prospect_id,
    t.entity_name,
    t.blocked_reason,
    t.approval_status,
    t.completion_notes,
    t.metadata,
    t.archived_at,
    t.tenant_id,
    t.user_id,
    t.partnership_id,
    t.assigned_owner,
    t.notes,
    t.expected_outcome,
    t.activity_log,
    p.name AS prospect_name,
    p.company AS prospect_company,
    p.city AS prospect_city,
    p.stage AS prospect_stage,
    p.value_mad AS prospect_value_mad,
        CASE
            WHEN ((t.due_date IS NOT NULL) AND (t.due_date < now()) AND (t.status <> ALL (ARRAY['done'::text, 'completed'::text, 'archived'::text]))) THEN true
            ELSE false
        END AS is_overdue
   FROM (public.revenue_tasks t
     LEFT JOIN public.revenue_prospects p ON (((p.id = t.prospect_id) OR (p.id = t.entity_id))));


