CREATE VIEW public.revenue_task_owner_workload_view AS
 SELECT COALESCE(owner, 'Unassigned'::text) AS owner,
    (count(*))::integer AS total_tasks,
    (count(*) FILTER (WHERE (status <> ALL (ARRAY['done'::text, 'completed'::text, 'archived'::text]))))::integer AS open_tasks
   FROM public.revenue_tasks
  GROUP BY COALESCE(owner, 'Unassigned'::text)
  ORDER BY ((count(*) FILTER (WHERE (status <> ALL (ARRAY['done'::text, 'completed'::text, 'archived'::text]))))::integer) DESC, ((count(*))::integer) DESC;


