    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_id uuid NOT NULL,
    user_id uuid,
    user_name text,
    started_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    minutes integer DEFAULT 0 NOT NULL,
    note text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL
);


--
-- Name: revenue_task_workload_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_task_workload_view AS
 SELECT COALESCE(NULLIF(owner, ''::text), 'Non attribué'::text) AS owner,
    (count(*))::integer AS total_tasks,
    (count(*) FILTER (WHERE (status <> ALL (ARRAY['done'::text, 'completed'::text, 'cancelled'::text, 'archived'::text]))))::integer AS open_tasks,
    (count(*) FILTER (WHERE (status = ANY (ARRAY['done'::text, 'completed'::text]))))::integer AS completed_tasks,
    (count(*) FILTER (WHERE (status = 'blocked'::text)))::integer AS blocked_tasks,
    (count(*) FILTER (WHERE ((status <> ALL (ARRAY['done'::text, 'completed'::text, 'cancelled'::text, 'archived'::text])) AND (COALESCE(due_at, (due_date)::timestamp with time zone) < now()))))::integer AS overdue_tasks,
    (sum(COALESCE(estimated_minutes, 0)))::integer AS estimated_minutes,
    (sum(COALESCE(actual_minutes, 0)))::integer AS actual_minutes
   FROM public.revenue_tasks
  GROUP BY COALESCE(NULLIF(owner, ''::text), 'Non attribué'::text);


