--
-- Name: revenue_v10_command_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.revenue_v10_command_dashboard AS
 SELECT count(*) FILTER (WHERE (status = 'active'::text)) AS active_deals,
    count(*) FILTER (WHERE (risk_score >= 70)) AS high_risk_deals,
    count(*) FILTER (WHERE (pressure_score >= 70)) AS high_pressure_deals,
    COALESCE(sum(value) FILTER (WHERE (status = 'active'::text)), (0)::numeric) AS active_pipeline_value,
    (COALESCE(avg(ai_score), (0)::numeric))::integer AS average_ai_score,
    ( SELECT count(*) AS count
           FROM public.revenue_v10_followups
          WHERE ((revenue_v10_followups.status = ANY (ARRAY['scheduled'::text, 'overdue'::text])) AND (revenue_v10_followups.due_at <= now()))) AS due_followups,
    ( SELECT count(*) AS count
           FROM public.revenue_v10_automation_jobs
          WHERE (revenue_v10_automation_jobs.status = 'queued'::text)) AS queued_jobs,
    ( SELECT count(*) AS count
           FROM public.revenue_v10_enforcement_locks
          WHERE (revenue_v10_enforcement_locks.is_active = true)) AS active_locks
   FROM public.revenue_v10_deals;


