--

CREATE VIEW public.saas_factory_command_overview_health AS
 SELECT now() AS generated_at,
    ( SELECT count(*) AS count
           FROM public.saas_factory_audit_events) AS audit_events,
    ( SELECT count(*) AS count
           FROM public.saas_factory_probe_results
          WHERE (saas_factory_probe_results.status = ANY (ARRAY['critical'::text, 'failed'::text, 'unhealthy'::text]))) AS failed_probes,
    ( SELECT count(*) AS count
           FROM public.saas_factory_queue_jobs
          WHERE (saas_factory_queue_jobs.status = ANY (ARRAY['queued'::text, 'retry'::text, 'failed'::text]))) AS queue_backlog;


