--
-- Name: saas_factory_modules_command_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_modules_command_health_v AS
 SELECT key,
    label,
    COALESCE(status, 'operational'::text) AS status,
    COALESCE(visibility, 'visible'::text) AS visibility,
    COALESCE(owner_team, 'SaaS Factory Ops'::text) AS owner_team,
    COALESCE(last_health_status, 'unknown'::text) AS last_health_status,
    last_health_checked_at,
    updated_at,
        CASE
            WHEN (COALESCE(status, 'operational'::text) = ANY (ARRAY['operational'::text, 'healthy'::text, 'active'::text])) THEN 'ready'::text
            WHEN (COALESCE(status, 'operational'::text) = ANY (ARRAY['maintenance'::text, 'warning'::text])) THEN 'review'::text
            WHEN (COALESCE(status, 'operational'::text) = ANY (ARRAY['critical'::text, 'disabled'::text])) THEN 'blocked'::text
            ELSE 'unknown'::text
        END AS command_readiness
   FROM public.saas_factory_modules m
  WHERE (to_regclass('public.saas_factory_modules'::text) IS NOT NULL);


