    source text DEFAULT 'runtime'::text NOT NULL,
    confidence text DEFAULT 'fallback'::text NOT NULL,
    status text DEFAULT 'unknown'::text NOT NULL,
    total_probes integer DEFAULT 0 NOT NULL,
    passing_probes integer DEFAULT 0 NOT NULL,
    warning_probes integer DEFAULT 0 NOT NULL,
    failed_probes integer DEFAULT 0 NOT NULL,
    deployment_readiness_score integer DEFAULT 0 NOT NULL,
    payload_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: saas_factory_observatory_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_observatory_health_v AS
 SELECT COALESCE(( SELECT saas_factory_observatory_snapshots.status
           FROM public.saas_factory_observatory_snapshots
          WHERE (saas_factory_observatory_snapshots.snapshot_key = 'latest'::text)
          ORDER BY saas_factory_observatory_snapshots.updated_at DESC
         LIMIT 1), 'not_captured'::text) AS status,
    COALESCE(( SELECT saas_factory_observatory_snapshots.total_probes
           FROM public.saas_factory_observatory_snapshots
          WHERE (saas_factory_observatory_snapshots.snapshot_key = 'latest'::text)
          ORDER BY saas_factory_observatory_snapshots.updated_at DESC
         LIMIT 1), 0) AS total_probes,
    COALESCE(( SELECT saas_factory_observatory_snapshots.failed_probes
           FROM public.saas_factory_observatory_snapshots
          WHERE (saas_factory_observatory_snapshots.snapshot_key = 'latest'::text)
          ORDER BY saas_factory_observatory_snapshots.updated_at DESC
         LIMIT 1), 0) AS failed_probes,
    COALESCE(( SELECT saas_factory_observatory_snapshots.warning_probes
           FROM public.saas_factory_observatory_snapshots
          WHERE (saas_factory_observatory_snapshots.snapshot_key = 'latest'::text)
          ORDER BY saas_factory_observatory_snapshots.updated_at DESC
         LIMIT 1), 0) AS warning_probes,
    now() AS checked_at;


