--
-- Name: saas_factory_options_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_options_health AS
 SELECT count(*) AS total_options,
    count(*) FILTER (WHERE (status = 'enabled'::text)) AS enabled_options,
    count(*) FILTER (WHERE (status = 'draft'::text)) AS draft_options,
    count(*) FILTER (WHERE (status = 'archived'::text)) AS archived_options,
    count(DISTINCT group_name) AS option_groups,
    max(updated_at) AS last_updated_at
   FROM public.saas_factory_options;


--
-- Name: saas_factory_options_health_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_options_health_v AS
 SELECT now() AS checked_at,
    ( SELECT count(*) AS count
           FROM public.saas_factory_option_groups) AS group_count,
    ( SELECT count(*) AS count
           FROM public.saas_factory_options) AS option_count,
    ( SELECT count(*) AS count
           FROM public.saas_factory_options
          WHERE (saas_factory_options.is_enabled = true)) AS enabled_option_count,
    ( SELECT count(*) AS count
           FROM public.saas_factory_options
          WHERE (saas_factory_options.is_enabled = false)) AS disabled_option_count,
    ( SELECT count(*) AS count
           FROM public.saas_factory_options o
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.saas_factory_option_groups g
                  WHERE (g.key = o.group_key))))) AS options_with_missing_group,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM public.saas_factory_options o
              WHERE (NOT (EXISTS ( SELECT 1
                       FROM public.saas_factory_option_groups g
                      WHERE (g.key = o.group_key))))) > 0) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS health_status;


