    now() AS checked_at;


--
-- Name: saas_factory_phase7_ops_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_phase7_ops_health AS
 SELECT ( SELECT count(*) AS count
           FROM public.saas_factory_probe_results) AS probe_result_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_probe_results
          WHERE (saas_factory_probe_results.status = 'critical'::text)) AS critical_probe_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_queue_jobs
          WHERE (saas_factory_queue_jobs.status = 'queued'::text)) AS queued_jobs,
    ( SELECT count(*) AS count
           FROM public.saas_factory_incidents
          WHERE (saas_factory_incidents.status <> ALL (ARRAY['resolved'::text, 'closed'::text]))) AS open_incidents,
    ( SELECT count(*) AS count
           FROM public.saas_factory_audit_events
          WHERE (saas_factory_audit_events.event_key = 'saas_factory.phase7.ops_migration'::text)) AS migration_audit_rows,
    now() AS checked_at;


--
-- Name: saas_factory_phase8_deep_execution_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_phase8_deep_execution_health AS
 SELECT ( SELECT count(*) AS count
           FROM public.saas_factory_panel_actions) AS panel_action_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_panel_snapshots) AS panel_snapshot_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_audit_events
          WHERE (saas_factory_audit_events.event_key = 'saas_factory.phase8.deep_execution_migration'::text)) AS migration_audit_rows,
    now() AS checked_at;


--
-- Name: saas_factory_phase9_full_option_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_factory_phase9_full_option_health AS
 SELECT ( SELECT count(*) AS count
           FROM public.saas_factory_option_groups) AS option_group_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_options) AS option_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_field_adoption_catalog) AS field_adoption_rows,
    ( SELECT count(*) AS count
           FROM public.saas_factory_audit_events
          WHERE (saas_factory_audit_events.event_key = 'saas_factory.phase9.full_option_registry_migration'::text)) AS migration_audit_rows,
    now() AS checked_at;


