--
-- Name: sales_deal_scores; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_deal_scores (
    id bigint NOT NULL,
    lead_id bigint,
    family_id bigint,
    score integer DEFAULT 0 NOT NULL,
    urgency_score integer DEFAULT 0 NOT NULL,
    budget_score integer DEFAULT 0 NOT NULL,
    authority_score integer DEFAULT 0 NOT NULL,
    service_fit_score integer DEFAULT 0 NOT NULL,
    payment_readiness_score integer DEFAULT 0 NOT NULL,
    closing_probability integer DEFAULT 0 NOT NULL,
    recommended_action text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sales_deal_scores_range CHECK (((score >= 0) AND (score <= 100) AND ((urgency_score >= 0) AND (urgency_score <= 100)) AND ((budget_score >= 0) AND (budget_score <= 100)) AND ((authority_score >= 0) AND (authority_score <= 100)) AND ((service_fit_score >= 0) AND (service_fit_score <= 100)) AND ((payment_readiness_score >= 0) AND (payment_readiness_score <= 100)) AND ((closing_probability >= 0) AND (closing_probability <= 100))))
);


