--
-- Name: v_app_attendance_log_identity_diagnostics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_app_attendance_log_identity_diagnostics AS
 SELECT l.id AS log_id,
    l.staff_id AS log_staff_id,
    l.user_id AS log_user_id,
    l.event_type,
    l.event_at,
    l.source,
    s.id AS resolved_staff_id,
    s.full_name AS resolved_staff_name,
    s.email AS resolved_staff_email,
    s.department AS resolved_department,
    s."position" AS resolved_position,
    s.city AS resolved_city,
        CASE
            WHEN (s.id IS NOT NULL) THEN 'resolved'::text
            WHEN ((l.staff_id IS NULL) AND (l.user_id IS NULL)) THEN 'missing_identity_keys'::text
            WHEN (l.staff_id IS NOT NULL) THEN 'staff_id_not_found'::text
            WHEN (l.user_id IS NOT NULL) THEN 'user_id_not_found'::text
            ELSE 'unmapped'::text
        END AS mapping_status
   FROM (public.app_attendance_logs l
     LEFT JOIN public.hr_staff_profiles s ON (((s.id = l.staff_id) OR (s.user_id = l.user_id))));


--
-- Name: v_hr_attendance_identity_diagnostics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_hr_attendance_identity_diagnostics AS
 SELECT a.id AS attendance_id,
    a.staff_id AS attendance_staff_id,
    a.user_id AS attendance_user_id,
    a.profile_id AS attendance_profile_id,
    a.work_date,
    a.status,
    a.validation_status,
    s.id AS resolved_staff_id,
    s.full_name AS resolved_staff_name,
    s.email AS resolved_staff_email,
    s.department AS resolved_department,
    s."position" AS resolved_position,
    s.city AS resolved_city,
        CASE
            WHEN (s.id IS NOT NULL) THEN 'resolved'::text
            WHEN ((a.staff_id IS NULL) AND (a.user_id IS NULL) AND (a.profile_id IS NULL)) THEN 'missing_all_identity_keys'::text
            WHEN (a.staff_id IS NOT NULL) THEN 'staff_id_not_found'::text
            WHEN (a.user_id IS NOT NULL) THEN 'user_id_not_found'::text
            WHEN (a.profile_id IS NOT NULL) THEN 'profile_id_present_but_staff_profiles_has_no_profile_id_column'::text
            ELSE 'unmapped'::text
        END AS mapping_status
   FROM (public.hr_attendance_records a
     LEFT JOIN public.hr_staff_profiles s ON (((s.id = a.staff_id) OR (s.user_id = a.user_id))));


--
-- Name: v_hr_attendance_resolved_live; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_hr_attendance_resolved_live AS
 SELECT a.id,
    a.staff_profile_id,
    a.staff_name,
    a.attendance_date,
    a.check_in,
    a.check_out,
    a.status,
    a.validation_status,
    a.correction_reason,
    a.approved_by,
    a.notes,
    a.created_at,
    a.updated_at,
    a.staff_id,
    a.user_id,
    a.lunch_start,
    a.lunch_end,
    a.source,
    a.total_minutes,
    a.break_minutes,
    a.overtime_minutes,
    a.late_minutes,
    a.missing_punch,
    a.anomaly_reason,
    a.work_date,
    a.punch_in_at,
    a.punch_out_at,
    a.exceptions,
    a.metadata,
    a.profile_id,
    a.break_start_at,
    a.break_end_at,
    a.attendance_status,
    a.location,
    a.shift_id,
    a.roster_id,
    a.payroll_status,
    COALESCE(s_direct.id, s_linked.id) AS resolved_staff_id,
    COALESCE(s_direct.full_name, s_linked.full_name, il.label, 'Unmapped overhead identity'::text) AS resolved_staff_name,
    COALESCE(s_direct.email, s_linked.email) AS resolved_staff_email,
    COALESCE(s_direct.department, s_linked.department, 'Unmapped department'::text) AS resolved_department,
    COALESCE(s_direct."position", s_linked."position", 'Staff'::text) AS resolved_position,
    COALESCE(s_direct.city, s_linked.city, 'Head Office'::text) AS resolved_city,
        CASE
            WHEN (s_direct.id IS NOT NULL) THEN 'direct_staff_id'::text
            WHEN (s_linked.id IS NOT NULL) THEN 'identity_bridge_auto'::text
            WHEN (il.id IS NOT NULL) THEN 'bridge_unmapped'::text
            ELSE 'unmapped'::text
        END AS identity_resolution_source
   FROM (((public.hr_attendance_records a
     LEFT JOIN public.hr_staff_profiles s_direct ON ((s_direct.id = a.staff_id)))
     LEFT JOIN public.hr_identity_links il ON (((il.source = 'overhead_panel'::text) AND (il.source_user_id = a.user_id))))
     LEFT JOIN public.hr_staff_profiles s_linked ON ((s_linked.id = il.staff_id)));


--
-- Name: v_hr_identity_contract_resolver; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_hr_identity_contract_resolver AS
 SELECT c.staff_id,
    c.user_id,
    c.email,
    c.full_name,
    s.department,
    s."position",
    s.city,
    c.source,
    c.status
   FROM (public.hr_user_identity_contracts c
     LEFT JOIN public.hr_staff_profiles s ON ((s.id = c.staff_id)));


