--
-- Name: angelcare_marketplace_translation_inventory_v _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.angelcare_marketplace_translation_inventory_v AS
 SELECT c.id AS candidate_id,
    c.translation_key,
    c.source_text_fr,
    c.source_hash,
    c.source_version,
    c.source_type,
    c.source_adapter,
    c.source_path,
    c.source_line,
    c.route,
    c.domain,
    c.workflow,
    c.territory_id,
    c.tenant_id,
    c.content_type,
    c.sensitivity,
    c.context_description,
    c.variables,
    c.character_limit,
    c.freshness_state,
    c.last_changed_at,
    max(t.translation_text) FILTER (WHERE (t.target_locale = 'en'::text)) AS en_translation,
    max(t.status) FILTER (WHERE (t.target_locale = 'en'::text)) AS en_status,
    max(t.translation_text) FILTER (WHERE (t.target_locale = 'ar'::text)) AS ar_translation,
    max(t.status) FILTER (WHERE (t.target_locale = 'ar'::text)) AS ar_status,
    COALESCE(max(t.status), 'translation_required'::text) AS translation_status
   FROM (public.angelcare_marketplace_translation_candidates c
     LEFT JOIN public.angelcare_marketplace_translations t ON ((t.candidate_id = c.id)))
  GROUP BY c.id;


--
-- Name: hsd_commercial_price_books_v _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.hsd_commercial_price_books_v WITH (security_invoker='true') AS
 SELECT pb.id,
    pb.tenant_id,
    pb.code,
    pb.name,
    pb.universe,
    pb.status,
    pb.current_version AS version_number,
    v.effective_from,
    v.effective_to,
    (count(e.id))::integer AS entry_count
   FROM ((public.hsd_commercial_price_books pb
     LEFT JOIN public.hsd_commercial_price_book_versions v ON (((v.price_book_id = pb.id) AND (v.version_number = pb.current_version))))
     LEFT JOIN public.hsd_commercial_price_entries e ON ((e.price_book_version_id = v.id)))
  GROUP BY pb.id, v.effective_from, v.effective_to;


--
-- Name: hsd_planning_integrity_v _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.hsd_planning_integrity_v AS
 SELECT r.id AS request_id,
    r.code,
    r.status,
    count(d.id) AS date_count,
    count(b.id) AS beneficiary_count,
    COALESCE(bool_and((d.status <> 'blocked'::text)), false) AS time_ready
   FROM ((public.hsd_planning_requests r
     LEFT JOIN public.hsd_planning_request_dates d ON ((d.request_id = r.id)))
     LEFT JOIN public.hsd_planning_request_beneficiaries b ON ((b.request_id = r.id)))
  GROUP BY r.id;


--
-- Name: hsd_v_competencies _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.hsd_v_competencies AS
 SELECT k.id,
    k.tenant_id,
    k.code,
    k.name_fr,
    k.family,
    k.description_fr,
    k.evidence_type,
    k.renewal_months,
    k.status,
    k.created_by,
    k.updated_by,
    k.created_at,
    k.updated_at,
    (count(r.id))::integer AS category_count,
    COALESCE(array_agg(c.code) FILTER (WHERE (c.code IS NOT NULL)), ARRAY[]::text[]) AS category_codes
   FROM ((public.hsd_competencies k
     LEFT JOIN public.hsd_service_competency_rules r ON ((r.competency_id = k.id)))
     LEFT JOIN public.hsd_service_categories c ON ((c.id = r.category_id)))
  GROUP BY k.id;


--
-- Name: hsd_v_service_families _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.hsd_v_service_families AS
 SELECT sf.id,
    sf.tenant_id,
    sf.code,
    sf.name_fr,
    sf.description_fr,
    sf.icon_key,
    sf.sort_order,
    sf.status,
    sf.created_by,
    sf.updated_by,
    sf.created_at,
    sf.updated_at,
    (count(c.id))::integer AS category_count,
    (COALESCE(round(avg(r.overall_readiness)), (0)::numeric))::integer AS readiness_score
   FROM ((public.hsd_service_families sf
     LEFT JOIN public.hsd_service_categories c ON ((c.family_id = sf.id)))
     LEFT JOIN public.hsd_v_category_readiness r ON ((r.id = c.id)))
  GROUP BY sf.id;


