-- Name: workspace_broadcast_memos admin_insert_workspace_broadcast_memos; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY admin_insert_workspace_broadcast_memos ON public.workspace_broadcast_memos FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM public.app_users u
  WHERE ((u.id = auth.uid()) AND (lower(COALESCE(u.role, ''::text)) = ANY (ARRAY['ceo'::text, 'admin'::text, 'super_admin'::text, 'owner'::text]))))));


--
-- Name: workspace_broadcast_memos admin_update_workspace_broadcast_memos; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY admin_update_workspace_broadcast_memos ON public.workspace_broadcast_memos FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.app_users u
  WHERE ((u.id = auth.uid()) AND (lower(COALESCE(u.role, ''::text)) = ANY (ARRAY['ceo'::text, 'admin'::text, 'super_admin'::text, 'owner'::text])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.app_users u
  WHERE ((u.id = auth.uid()) AND (lower(COALESCE(u.role, ''::text)) = ANY (ARRAY['ceo'::text, 'admin'::text, 'super_admin'::text, 'owner'::text]))))));


