-- Name: app_users app_users_non_recursive_self_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_users_non_recursive_self_insert ON public.app_users FOR INSERT TO authenticated WITH CHECK ((((id)::text = (auth.uid())::text) OR (lower(COALESCE(email, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text))) OR (lower(COALESCE(username, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text)))));


--
-- Name: app_users app_users_non_recursive_self_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_users_non_recursive_self_read ON public.app_users FOR SELECT TO authenticated USING ((((id)::text = (auth.uid())::text) OR (lower(COALESCE(email, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text))) OR (lower(COALESCE(username, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text)))));


--
-- Name: app_users app_users_non_recursive_self_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY app_users_non_recursive_self_update ON public.app_users FOR UPDATE TO authenticated USING ((((id)::text = (auth.uid())::text) OR (lower(COALESCE(email, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text))) OR (lower(COALESCE(username, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text))))) WITH CHECK ((((id)::text = (auth.uid())::text) OR (lower(COALESCE(email, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text))) OR (lower(COALESCE(username, ''::text)) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text)))));


